NO_WINDOW = 0x08000000                                          # subprocess flag: no console window

# FLP event ids
EV_TEMPO = 156
EV_VERSION = 199
EV_CHANNEL = 64
EV_PLUGIN_NAME = 201
EV_PLUGIN_HEADER = 212
EV_DISPLAY_NAME = 203
EV_PLUGIN_STATE = 213
EV_CHANNEL_COLOR = 128                                           # COLORREF 0x00BBGGRR
EV_CHANNEL_ICON = 155
EV_NOTES = 224
EV_PATTERN_CTRL = 223                                           # recorded controller events (12-byte records)
TEMPO_CTRL = (5, 0x40)                                          # record bytes 4 and 7 that mark a tempo event
TEMPO_REC = bytes([5, 0, 0, 0x40])
EV_PLAYLIST = 233
EV_PATTERN_NEW = 65
EV_PATTERN_NAME = 193
# a pattern's name/settings group (PatternNew + these) as FL 2026 writes it: name, color, ..., time signature (33/34),
# length, marker-like events (148/205), ... The group really ends at the next structural boundary (PATTERN_BOUNDARY);
# this set only recognizes a settings group. Use _pattern_groups / _pattern_meta_anchor, never walk this set.
PATTERN_META = {193, 150, 157, 158, 148, 33, 34, 46, 45, 168, 101, 205, 164, 52, 171, 252, 253}
PATTERN_BASE = 0x5000                                           # playlist item index of pattern 0
EV_MIXER_TRACK = 236
EV_MIXER_SLOT = 98
EV_MIXER_PARAMS = 225                                           # 12-byte records: ?, param id, flag, (0x7000 + track<<6 + slot), value
EV_MIXER_ROUTE = 235                                            # bool per destination track
EV_MIXER_COLOR = 149                                            # R G B A
EV_MIXER_HASPROPS = 42
EV_MIXER_NAME = 204
MIX_VOLUME, MIX_PAN = 0xC0, 0xC1
EV_SIZE_EXCEPTIONS = {172: 3}
EV_CHANNEL_END = 51                                             # last event of a channel block
EV_REMOTE_LINK = 227                                            # automation clip -> target parameter
EV_AUTOMATION = 234                                             # automation clip points
EV_SAMPLE_PATH = 196
