# ============================================================================= paths and safety
_TEMP_ROOTS = []                                                # fl-headless's own temp folders (self-test)


def _is_abs_root(r):
    """A full folder path ('D:\\Music', '\\\\server\\share' on Windows; '/home/me/Music' elsewhere). A relative entry
    would be resolved against the MCP client's working folder, which nobody means: such entries are ignored."""
    if os.name == "nt":                                           # the real OS's path rules (not a test's IS_WINDOWS)
        return bool(re.match(r"^[A-Za-z]:[\\/]", r) or re.match(r"^[\\/]{2}[^\\/]+[\\/]+[^\\/]+", r))
    return os.path.isabs(r)


def _root_entries(raw, relative=None):
    """FLH_ROOTS entries: ';'-separated, surrounding spaces and quotes stripped ("D:\\Music; D:\\FL" works). Only
    full paths count; relative ones are left out (and appended to `relative` when a list is given)."""
    out = []
    for r in str(raw or "").split(";"):
        r = r.strip().strip('"').strip("'").strip()
        if not r:
            continue
        if _is_abs_root(r):
            out.append(r)
        elif relative is not None:
            relative.append(r)
    return out


def relative_roots():
    """FLH_ROOTS entries that were ignored because they aren't full paths (flh_setup reports them)."""
    bad = []
    _root_entries(os.environ.get("FLH_ROOTS", ""), bad)
    return bad


def roots():
    """The user's writable folders (FLH_ROOTS entries only): what setup, status and messages show. fl-headless's own
    temp / pending folders are writable too (writable() accepts them) but are never reported as user roots."""
    return [os.path.normcase(os.path.abspath(r)) for r in _root_entries(os.environ.get("FLH_ROOTS", "")) if r.strip()]


def _all_roots():
    return roots() + [os.path.normcase(os.path.abspath(r)) for r in _TEMP_ROOTS if r.strip()]


def _real(path):
    """Absolute, case-folded path with symlinks / junctions resolved (a link inside a root can't lead outside)."""
    try:
        return os.path.normcase(os.path.realpath(os.path.abspath(path)))
    except (OSError, ValueError):
        return os.path.normcase(os.path.abspath(path))


def _under(p, r):
    r = r.rstrip("\\/")
    return p == r or p.startswith(r + os.sep) or (os.altsep is not None and p.startswith(r + os.altsep))


def _fl_templates_dirs():
    """FL's user Templates folder(s): <FL user data>\\Projects\\Templates (FL lists it under File > New from template).
    PC-VERIFY: FL 2026 shows <user data>\\Projects\\Templates\\<name>\\<name>.flp under File > New from template."""
    try:
        u = _fl_userdata()
    except Exception:
        u = ""
    if not u:
        return []
    return [os.path.join(u, "Projects", "Templates"), os.path.join(u, "FL Studio", "Projects", "Templates")]


def writable(path):
    """Raise PermissionError unless `path` is inside FLH_ROOTS (or fl-headless's own temp folders). Links are
    resolved first. One narrow extra: .flp files inside FL's user Templates folder (saved templates)."""
    p = _real(path); ap = os.path.normcase(os.path.abspath(path))
    for r in _all_roots():
        if _under(p, _real(r)) or (p == ap and _under(ap, r)):
            return True
    if p.endswith(".flp"):
        for t in _fl_templates_dirs():
            if _under(p, _real(t)) and p != _real(t):
                return True
    user = roots()
    if not user:
        raise PermissionError(f"{path} can't be written: FLH_ROOTS isn't set, so fl-headless may not write anywhere "
                              "(flh_setup shows how to set it)")
    if p != ap and any(_under(ap, r) or _under(ap, _real(r)) for r in user):     # a link / junction inside a root
        raise PermissionError(f"{path} is a link to {p}, which is outside FLH_ROOTS ({';'.join(user)}): add "
                              f"{os.path.dirname(p)} (or a folder above it) to FLH_ROOTS (run the installer again)")
    raise PermissionError(f"{path} is outside FLH_ROOTS ({';'.join(user)})")


IS_WINDOWS = os.name == "nt"
WINDOWS_ONLY_NOTE = ("this tool drives FL Studio and works on Windows only (FL on macOS isn't supported by "
                     "fl-headless); the flp_*, audio_* and files_* tools work on this system")


def _reg_values(hive, path, wow=0):
    """{value name: value} of one registry key (read only; {} when missing or not on Windows)."""
    if not IS_WINDOWS:
        return {}
    import winreg
    out = {}
    try:
        with winreg.OpenKey(getattr(winreg, hive), path, 0, winreg.KEY_READ | wow) as k:
            i = 0
            while True:
                try:
                    n, v, _t = winreg.EnumValue(k, i)
                except OSError:
                    break
                out[n] = v; i += 1
    except OSError:
        pass
    return out


def _reg_subkeys(hive, path, wow=0):
    if not IS_WINDOWS:
        return []
    import winreg
    out = []
    try:
        with winreg.OpenKey(getattr(winreg, hive), path, 0, winreg.KEY_READ | wow) as k:
            i = 0
            while True:
                try:
                    out.append(winreg.EnumKey(k, i)); i += 1
                except OSError:
                    break
    except OSError:
        pass
    return out


def _fl_version_rank(path):
    """Sort key for an FL install: 'FL Studio 20' < '21' < '2024' < '2025' < '2026' (then newest file)."""
    m = re.search(r"FL Studio\s*(\d+)", path, re.I)
    n = int(m.group(1)) if m else 0
    n = 2000 + n if 0 < n < 100 else n
    try:
        t = os.path.getmtime(path)
    except OSError:
        t = 0
    return (n, t)


_FL_EXE_CACHE = [0.0, None, None]


def fl_installs():
    """Every FL64.exe found: FLH_FL_EXE / FL_EXE, the registry (uninstall entries, Image-Line keys, App Paths) and
    Program Files / Program Files (x86)\\Image-Line\\* (FL 20 installed there by default). [(path, source)]."""
    found = []
    def add(p, src):
        if not p:
            return
        p = os.path.expandvars(str(p).strip().strip('"').split('",')[0].split(",")[0])
        if os.path.isdir(p):
            p = os.path.join(p, "FL64.exe")
        if src not in ("FLH_FL_EXE", "FL_EXE") and p.lower().endswith(".exe") and \
                os.path.basename(p).lower() != "fl64.exe":
            p = os.path.join(os.path.dirname(p), "FL64.exe")       # an uninstaller / icon next to FL64.exe
        if os.path.isfile(p) and os.path.normcase(p) not in {os.path.normcase(f) for f, _ in found}:
            found.append((p, src))
    for env in ("FLH_FL_EXE", "FL_EXE"):
        add(os.environ.get(env), env)
    if IS_WINDOWS:
        import winreg
        for wow in (winreg.KEY_WOW64_64KEY, winreg.KEY_WOW64_32KEY):
            for hive in ("HKEY_LOCAL_MACHINE", "HKEY_CURRENT_USER"):
                un = r"Software\Microsoft\Windows\CurrentVersion\Uninstall"
                for sub in _reg_subkeys(hive, un, wow):
                    v = _reg_values(hive, un + "\\" + sub, wow)
                    if str(v.get("DisplayName", "")).lower().startswith("fl studio") or sub.lower().startswith("fl studio"):
                        for key in ("InstallLocation", "DisplayIcon", "UninstallString"):
                            if v.get(key):
                                p = str(v[key]).strip('"')
                                add(p if key == "InstallLocation" else os.path.dirname(p.split('"')[0]), "registry")
                for sub in _reg_subkeys(hive, r"Software\Image-Line", wow):
                    if sub.lower().startswith("fl studio") or sub.lower() == "shared":
                        for n, v in _reg_values(hive, r"Software\Image-Line" + "\\" + sub, wow).items():
                            if isinstance(v, str) and "path" in n.lower() and ("fl studio" in v.lower() or "fl64" in v.lower()):
                                add(v, "registry")
                add(_reg_values(hive, r"Software\Microsoft\Windows\CurrentVersion\App Paths\FL64.exe", wow).get(""),
                    "registry")
        for base in dict.fromkeys(filter(None, (os.environ.get("ProgramW6432"), os.environ.get("ProgramFiles"),
                                                os.environ.get("ProgramFiles(x86)"), r"C:\Program Files",
                                                r"C:\Program Files (x86)"))):
            for p in glob.glob(os.path.join(base, "Image-Line", "*", "FL64.exe")):
                add(p, "Program Files")
    return found


def fl_exe():
    """FL64.exe to use: FLH_FL_EXE / FL_EXE if set, else the newest FL installed (FL 20, 21, 2024, 2025, 2026...)."""
    key = (os.environ.get("FLH_FL_EXE"), os.environ.get("FL_EXE"))
    if _FL_EXE_CACHE[1] and _FL_EXE_CACHE[2] == key and time.time() - _FL_EXE_CACHE[0] < 60 \
            and os.path.isfile(_FL_EXE_CACHE[1]):
        return _FL_EXE_CACHE[1]
    hits = fl_installs()
    if not hits:
        raise FileNotFoundError("FL64.exe not found (looked in the registry and Program Files\\Image-Line); set "
                                "FLH_FL_EXE to the full path of FL64.exe" if IS_WINDOWS else
                                "FL Studio can only be driven on Windows: " + WINDOWS_ONLY_NOTE)
    env = [p for p, s in hits if s in ("FLH_FL_EXE", "FL_EXE")]
    best = env[0] if env else max((p for p, _ in hits), key=_fl_version_rank)
    _FL_EXE_CACHE[:] = [time.time(), best, key]
    return best


def fl_running():
    if os.name != "nt":
        return False
    return bool(_fl_pids())


# ============================================================================= MIDI reader
def _vlq(d, i):
    v = 0
    while True:
        b = d[i]; i += 1; v = (v << 7) | (b & 0x7F)
        if not b & 0x80:
            return v, i


def midi_read(path, warnings=None):
    """-> (ticks_per_quarter, [(start, end, key, velocity)], [(tick, bpm)]) from all tracks of a MIDI file. Notes pair
    per (track, channel, key); a note-on never released is closed at its track's end (at least 1 tick long) and
    counted in `warnings` (a list, when given). A tempo map that starts after tick 0 gets MIDI's default 120 BPM there."""
    d = open(path, "rb").read()
    if d[:4] != b"MThd" or len(d) < 14:
        raise ValueError(f"{path}: not a MIDI file")
    hl = struct.unpack(">I", d[4:8])[0]
    _, ntr, div = struct.unpack(">HHH", d[8:14])
    if div & 0x8000:
        raise ValueError(f"{path}: SMPTE-timed MIDI files aren't supported")
    i = 8 + hl; events = []; tempos = []; track_end = {}
    for tr in range(ntr):
        if d[i:i + 4] != b"MTrk" or len(d) < i + 8:
            raise ValueError(f"{path}: bad track chunk")
        L = struct.unpack(">I", d[i + 4:i + 8])[0]; t = d[i + 8:i + 8 + L]; i += 8 + L
        j = tick = 0; run = None
        try:
            while j < len(t):
                dt, j = _vlq(t, j); tick += dt; b = t[j]
                if b == 0xFF:
                    typ = t[j + 1]; ln, j = _vlq(t, j + 2)
                    if typ == 0x51 and ln == 3:
                        tempos.append((tick, round(60_000_000 / max(1, int.from_bytes(t[j:j + 3], "big")), 3)))
                    j += ln
                elif b in (0xF0, 0xF7):
                    ln, j = _vlq(t, j + 1); j += ln
                else:
                    if b & 0x80:
                        run = b; j += 1
                    if run is None:
                        raise ValueError(f"{path}: track {tr + 1} has a data byte with no status before it")
                    hi = run & 0xF0
                    if hi in (0x80, 0x90):
                        off = hi == 0x80 or t[j + 1] == 0
                        events.append((tick, 0 if off else 1, tr, run & 0x0F, t[j], t[j + 1]))
                    j += 1 if hi in (0xC0, 0xD0) else 2
        except IndexError:
            raise ValueError(f"{path}: track {tr + 1} is truncated (an event runs past the end of its chunk): the "
                             "file is damaged or cut short") from None
        track_end[tr] = tick
    events.sort(key=lambda e: e[:2])                            # note-offs before note-ons at the same tick
    on, out, lone_off = {}, [], {}
    for tick, kind, tr, chan, key, vel in events:
        nk = (tr, chan, key)                                    # a note pairs with its own track and channel
        if kind:
            if lone_off.get(nk) == tick:                        # on + off at one tick (a zero-length hit): the off
                out.append((tick, tick, key, vel)); del lone_off[nk]    # sorted first and closed nothing - pair them
                continue
            on.setdefault(nk, []).append((tick, vel))
        elif on.get(nk):
            s, v = on[nk].pop(0); out.append((s, tick, key, v))
        else:
            lone_off[nk] = tick
    hung = 0
    for (tr, chan, key), opened in on.items():                  # never released: closed at the track's last tick
        for s, v in opened:
            out.append((s, max(s + 1, track_end.get(tr, s)), key, v)); hung += 1
    if hung and warnings is not None:
        warnings.append(f"{hung} note(s) in {os.path.basename(path)} were never released (no note-off): closed at the "
                        "end of their track")
    out.sort(key=lambda n: (n[0], n[2], n[1]))
    tmap = []
    for tick, bpm in sorted(tempos):
        if tmap and tmap[-1][0] == tick:
            tmap[-1] = (tick, bpm)
        elif not tmap or tmap[-1][1] != bpm:
            tmap.append((tick, bpm))
    if tmap and tmap[0][0] > 0:                                 # MIDI's tempo before its first tempo event
        tmap.insert(0, (0, 120.0))
    return div, out, tmap


def midi_notes(path):
    """-> (ticks_per_quarter, [(start, end, key, velocity)]) from all tracks of a MIDI file."""
    div, notes, _ = midi_read(path)
    return div, notes


def _wvlq(v):
    if v < 0:                                                     # would loop forever (-1 >> 7 == -1)
        raise ValueError(f"MIDI delta time {v} is negative")
    out = [v & 0x7F]; v >>= 7
    while v:
        out.append((v & 0x7F) | 0x80); v >>= 7
    return bytes(reversed(out))


def _midi_order(evs):
    """Events in time order, note-offs before note-ons at one tick (a note ending where the next one of its key
    starts) - except an off that would close nothing but a note starting at that very tick (a zero-length note): it
    goes 1 tick later, after its note-on, so the note isn't left hanging."""
    import heapq
    def is_note(e):
        return len(e) >= 3 and e[0] & 0xF0 in (0x80, 0x90)
    def is_off(e):
        return e[0] & 0xF0 == 0x80 or e[2] == 0
    evs = sorted(evs, key=lambda e: (e[0], e[1][0] & 0xF0 != 0x80))
    if not any(is_note(e) for _, e in evs):
        return evs
    ons_at = {(t, e[0] & 0x0F, e[1]) for t, e in evs if is_note(e) and not is_off(e)}
    heap = [(t, e[0] & 0xF0 != 0x80, i, e, False) for i, (t, e) in enumerate(evs)]; heapq.heapify(heap)
    sounding = {}; out = []; n = len(heap)
    while heap:
        t, rank, i, e, moved = heapq.heappop(heap)
        if is_note(e):
            k = (e[0] & 0x0F, e[1])
            if is_off(e):
                if not moved and not sounding.get(k) and (t,) + k in ons_at:
                    heapq.heappush(heap, (t + 1, rank, n, e, True)); n += 1
                    continue
                sounding[k] = max(0, sounding.get(k, 0) - 1)
            else:
                sounding[k] = sounding.get(k, 0) + 1
        out.append((t, e))
    return out


def midi_write(path, div, tracks):
    """tracks: [(name, [(tick, bytes_event)])] -> type-1 MIDI file."""
    out = struct.pack(">4sIHHH", b"MThd", 6, 1, len(tracks), div)
    for name, evs in tracks:
        body = b"\x00\xff\x03" + _wvlq(len(name.encode())) + name.encode(); last = 0
        for tick, ev_ in _midi_order(evs):
            body += _wvlq(tick - last) + ev_; last = tick
        body += b"\x00\xff\x2f\x00"
        out += b"MTrk" + struct.pack(">I", len(body)) + body
    with open(path, "wb") as f:
        f.write(out)


# ============================================================================= FLP: low level
def _varint(d, i):
    """FL's event length (7 bits per byte, at most 5 bytes); a length that runs off the end is a broken file."""
    n = s = 0
    for _ in range(5):
        if i >= len(d):
            raise ValueError(f"event stream broke at offset {i} (an event length runs past the end of the file): "
                             "the project is truncated or damaged")
        b = d[i]; i += 1; n |= (b & 0x7F) << s; s += 7
        if not b & 0x80:
            return n, i
    raise ValueError(f"event stream broke at offset {i} (an event length over 5 bytes): the project is damaged")


def _wvarint(n):
    out = bytearray()
    while True:
        b = n & 0x7F; n >>= 7; out.append(b | (0x80 if n else 0))
        if not n:
            return bytes(out)


# ---- parse cache: read tools on big projects (thousands of events, tens of thousands of notes) parse once.
# _load is keyed by the file (path, mtime_ns, size, inode) and dropped on our own writes; the parse results are keyed by
# the file's CONTENT (the bytes object itself), so they can never be stale - a changed file is different bytes.
# Results are shared: _events/_structure/_patterns/_song/_clips hand out fresh containers (lists/dicts) over immutable
# items (tuples, bytes), so a caller that edits what it got can't corrupt the cache.
_PARSE_LOCK = threading.Lock()
_LOAD_CACHE = {}                                                  # abspath -> (stat key, bytes)
_PARSE_CACHE = {}                                                 # bytes -> {kind: result}, oldest first
_PARSE_MAX = 6                                                    # distinct project contents kept
_PARSE_MIN = 4096                                                 # tiny buffers (.fst blocks, test bytes) aren't cached
_PARSE_STATS = {"hits": 0, "misses": 0, "load_hits": 0, "seeded": 0}


def _parse_cache_on():
    return os.environ.get("FLH_PARSE_CACHE", "1") != "0"


def _stat_key(path):
    st = os.stat(path)
    return (st.st_mtime_ns, st.st_size, getattr(st, "st_ino", 0), getattr(st, "st_ctime_ns", 0)), st.st_mtime


def _same_edges(path, d, n=4096):
    """The file still starts and ends with the cached bytes (a NAS with a lagging clock can show an old mtime for a
    same-size re-save; a knob change keeps the size): two small reads instead of trusting the timestamp alone."""
    try:
        with open(path, "rb") as f:
            head = f.read(n)
            f.seek(max(0, len(d) - n))
            tail = f.read(n)
        return head == d[:n] and tail == d[-n:]
    except OSError:
        return False


def _load(path):
    key = None
    if _parse_cache_on():
        try:
            ap = os.path.abspath(path); key, mt = _stat_key(ap)
            hit = _LOAD_CACHE.get(ap)
            # a file written within the last 2 s may be rewritten inside one timestamp tick on coarse file systems
            if hit and hit[0] == key and time.time() - mt > 2.0 and _same_edges(ap, hit[1]):
                _PARSE_STATS["load_hits"] += 1
                return hit[1]
        except OSError:
            key = None
    d = _read_flp_bytes(path)
    if key is not None and len(d) >= _PARSE_MIN:
        with _PARSE_LOCK:
            if len(_LOAD_CACHE) > 32:
                _LOAD_CACHE.clear()
            _LOAD_CACHE[os.path.abspath(path)] = (key, d)
    return d


def _read_flp_bytes(path, wait_s=1.5):
    """A project's bytes, complete. A file written in the last few seconds that reads empty or cut short is being
    saved by FL right now: read again for up to wait_s instead of failing the call."""
    t_end = time.time() + wait_s
    while True:
        with open(path, "rb") as f:
            d = f.read()
        try:
            if d[:4] != b"FLhd":
                raise ValueError(f"{path}: not an FL Studio project or preset")
            _check_complete(d, path)
            return d
        except ValueError:
            try:
                fresh = time.time() - os.path.getmtime(path) < 3.0 and fl_running()   # only FL saves behind us
            except Exception:
                fresh = False
            if not fresh or time.time() >= t_end:
                raise
            time.sleep(0.15)


def _forget_file(path):
    """Our own write of `path`: its cached bytes go (the content-keyed parse results stay valid for the old bytes)."""
    try:
        _LOAD_CACHE.pop(os.path.abspath(path), None)
    except Exception:
        pass


def _cached(kind, d, build):
    """build(d) once per (kind, content); results must be treated as read-only (callers copy containers)."""
    if not isinstance(d, bytes) or len(d) < _PARSE_MIN or not _parse_cache_on():
        return build(d)
    with _PARSE_LOCK:
        ent = _PARSE_CACHE.get(d)
        if ent is not None and kind in ent:
            _PARSE_STATS["hits"] += 1
            _PARSE_CACHE[d] = _PARSE_CACHE.pop(d)                  # most recent last
            return ent[kind]
    r = build(d)
    with _PARSE_LOCK:
        _PARSE_STATS["misses"] += 1
        ent = _PARSE_CACHE.pop(d, None) or {}
        ent[kind] = r; _PARSE_CACHE[d] = ent
        while len(_PARSE_CACHE) > _PARSE_MAX:
            _PARSE_CACHE.pop(next(iter(_PARSE_CACHE)))
    return r


def _jcopy(o):
    """A fresh copy of JSON-like data (dicts / lists copied, everything else shared) - faster than deepcopy."""
    t = type(o)
    if t is dict:
        return {k: (v if type(v) not in (dict, list) else _jcopy(v)) for k, v in o.items()}
    if t is list:
        return [v if type(v) not in (dict, list) else _jcopy(v) for v in o]
    return o


def parse_cache_stats():
    return dict(_PARSE_STATS, projects=len(_PARSE_CACHE), files=len(_LOAD_CACHE))


def _ppq(d):
    if len(d) < 14:
        raise ValueError("the file is too short to be an FL Studio project")
    P = struct.unpack("<hHH", d[8:14])[2]
    if P < 24:                                                    # FL's PPQ choices run 24..960
        raise ValueError(f"the project header says PPQ {P}: not a valid FL Studio project (FL uses 24-960)")
    return P


def _header_check(d):
    """FLhd header + FLdt chunk; ValueError when the file can't be an FL project. -> index of the first event."""
    if len(d) < 22 or d[:4] != b"FLhd":
        raise ValueError("the file is too short or isn't an FL Studio project (no FLhd header)")
    hl = struct.unpack("<I", d[4:8])[0]
    if hl < 6 or 16 + hl > len(d) or d[8 + hl:12 + hl] != b"FLdt":
        raise ValueError("the project header is damaged (no FLdt data chunk where the header says): not a valid FL "
                         "Studio project")
    return 16 + hl


def _events(d):
    """Parse the FLdt event stream -> [{off, id, ps (payload start), len, end}] (a fresh list; don't edit the dicts)."""
    return list(_cached("events", d, _events_parse))


def _check_complete(d, path=None):
    """The FLdt chunk must be there and hold as many bytes as its header says. A file cut short (FL still saving,
    a slow network / OneDrive folder) would otherwise parse 'fine' up to the cut and be written back truncated."""
    if len(d) < 8:
        raise ValueError(f"{path or 'project'}: file incomplete ({len(d)} bytes; FL still saving?)")
    hl = struct.unpack("<I", d[4:8])[0]
    if len(d) < 16 + hl or d[8 + hl:12 + hl] != b"FLdt":
        raise ValueError(f"{path or 'project'}: file incomplete or not an FL project (no data chunk; FL still "
                             "saving?)")
    want = struct.unpack("<I", d[12 + hl:16 + hl])[0]
    if len(d) < 16 + hl + want:
        raise ValueError(f"{path or 'project'}: file incomplete ({len(d)} of {16 + hl + want} bytes; FL still "
                             "saving?) - nothing was read or changed; try again in a moment")
    return hl


def _events_parse(d):
    i = _header_check(d); _check_complete(d); out = []
    _events_scan(d, i, len(d), out)
    return out


def _events_scan(d, i, stop, out):
    """Append the events of d[i:stop] to out; ValueError when one runs past stop (the same check _events_parse
    always made, with stop = the end of the file). Hot loop: one-byte lengths (most events) skip _varint."""
    app = out.append; exc = EV_SIZE_EXCEPTIONS
    while i < stop:
        o = i; eid = d[i]; i += 1
        if eid in exc:
            n = exc[eid]; ps = i
        elif eid < 64:
            n = 1; ps = i
        elif eid < 128:
            n = 2; ps = i
        elif eid < 192:
            n = 4; ps = i
        elif i < stop and d[i] < 0x80:
            n = d[i]; ps = i + 1
        else:
            n, ps = _varint(d, i)
        i = ps + n
        if i > stop:
            raise ValueError(f"event stream broke at offset {o} (id {eid}); unsupported FL version?")
        app({"off": o, "id": eid, "ps": ps, "len": n, "end": i})
    return out


def _payload(d, e):
    return d[e["ps"]:e["end"]]


def _raw(d, e):
    return d[e["off"]:e["end"]]


def _data_event(eid, payload):
    return bytes([eid]) + _wvarint(len(payload)) + payload


def _text16(b):
    try:
        return b.decode("utf-16-le").rstrip("\x00")
    except UnicodeDecodeError:
        return ""


def _splice(d, ev, edits):
    """Rebuild a project with event ranges replaced. edits: [(first_event, end_event_exclusive, new_bytes)]."""
    out = bytearray(); pos = 0
    srt = sorted(edits, key=lambda x: (x[0], x[1]))                # an insert (a, a) before a replace (a, a + 1)
    for (a0, b0, _), (a1, _b1, _n) in zip(srt, srt[1:]):
        if a1 < b0:                                               # two edits of one event: both were written (a
            raise ValueError(f"internal: overlapping edits of events {a0}-{b0} and {a1}; nothing was written "
                             "(please report this)")             # duplicated event, a corrupt project)
    for a, b, new in srt:
        off_a = ev[a]["off"] if a < len(ev) else len(d)
        off_b = ev[b]["off"] if b < len(ev) else len(d)
        out += d[pos:off_a] + new; pos = off_b
    out += d[pos:]
    hl = struct.unpack("<I", out[4:8])[0]
    out[12 + hl:16 + hl] = struct.pack("<I", len(out) - (16 + hl))   # FLdt chunk length
    out = bytes(out)
    try:
        _seed_spliced_events(d, ev, srt, out)
    except Exception:                                             # noqa: BLE001 - only a speed-up: parse later
        pass
    return out


def _seed_spliced_events(d, ev, srt, out):
    """Speed: the event list of a spliced project = the old list (shifted past each edit) + the edits' own bytes
    parsed, so the next _events(out) - the writer's next step, _save's check - doesn't re-parse the whole file.
    Only when ev is the cached parse of d (same event dicts) and every edit's bytes parse into whole events that end
    exactly where the edit ends; otherwise nothing is seeded and _events parses out in full as before."""
    if not _parse_cache_on() or not isinstance(d, bytes) or len(out) < _PARSE_MIN or not ev:
        return
    with _PARSE_LOCK:
        ent = _PARSE_CACHE.get(d)
        base = ent.get("events") if ent else None
        if base is None or len(base) != len(ev):
            return
        if (_PARSE_CACHE.get(out) or {}).get("events") is not None:
            return
    n = len(ev); new_ev = []; prev = 0; delta = 0
    if ev[0] is not base[0] or ev[-1] is not base[-1]:
        return
    for a, b, new in srt:
        if a < prev or b < a or b > n:                            # overlapping / odd edits: let _events parse
            return
        for k in (a - 1, a, b - 1, b):
            if 0 <= k < n and ev[k] is not base[k]:
                return
        _shift_events(base, prev, a, delta, new_ev)
        off_a = base[a]["off"] if a < n else len(d)
        off_b = base[b]["off"] if b < n else len(d)
        start = off_a + delta
        if out[start:start + len(new)] != new:
            return
        _events_scan(out, start, start + len(new), new_ev)
        delta += len(new) - (off_b - off_a); prev = b
    _shift_events(base, prev, n, delta, new_ev)
    if not new_ev or new_ev[-1]["end"] != len(out) or new_ev[0]["off"] != _header_check(out):
        return
    _check_complete(out)
    with _PARSE_LOCK:
        ent = _PARSE_CACHE.pop(out, None) or {}
        ent.setdefault("events", new_ev); _PARSE_CACHE[out] = ent
        _PARSE_STATS["seeded"] = _PARSE_STATS.get("seeded", 0) + 1
        while len(_PARSE_CACHE) > _PARSE_MAX:
            _PARSE_CACHE.pop(next(iter(_PARSE_CACHE)))


def _shift_events(base, a, b, delta, out):
    """base[a:b] moved by delta bytes into out (the same read-only dicts when nothing moved)."""
    if not delta:
        out.extend(base[a:b]); return
    app = out.append
    for e in base[a:b]:
        e = e.copy(); e["off"] += delta; e["ps"] += delta; e["end"] += delta; app(e)


_CALL_BACKUPS = set()


EV_PROJECT_FLAGS = 169                                          # u32 bit field FL writes before the first channel
FLAG_CLIP_RECORDS_88 = 0x08                                     # FL 2026.1.7 saves 0x0f; its Empty.flp has 0x07


def _clip_format_flag(data, ev):
    """FL 2026 reads 88-byte playlist clip records only when bit 0x08 of event 169 is set: a project from FL's
    Empty template (0x07) with clips in that layout loads with clips lost and is saved back garbled (PC 2026-10-20,
    bisected: FL's own 3-clip file vs ours; the same records load fine once 169 = 0x0f). When every clip record in
    the file is the 88-byte layout fl-headless writes and the bit is missing, set it as FL itself does on save."""
    k = next((i for i, e in enumerate(ev) if e["id"] in (EV_PROJECT_FLAGS, EV_CHANNEL, EV_PATTERN_NEW)), None)
    if k is None or ev[k]["id"] != EV_PROJECT_FLAGS or ev[k]["len"] != 4:
        return data
    v, = struct.unpack("<I", _payload(data, ev[k]))
    if v & FLAG_CLIP_RECORDS_88:
        return data
    pls = [_payload(data, e) for e in ev if e["id"] == EV_PLAYLIST and e["len"]]
    if not pls or not all(len(p) % 88 == 0 and all(p[i + 4:i + 6] == b"\x00\x50" for i in range(0, len(p), 88))
                          for p in pls):
        return data
    a = ev[k]["end"] - 4
    return data[:a] + struct.pack("<I", v | FLAG_CLIP_RECORDS_88) + data[a + 4:]


def _save(data, output):
    """Atomic write with a read-back parse check. Inside _write_source(input): a project written under another stem
    than its input gets its own Project-info title (_own_title_bytes)."""
    writable(output)
    data = _clip_format_flag(data, _events(data))
    try:                                                          # markers where FL keeps them (older writes left
        data = _marker_layout_fix(data)[0]                        # some where FL's load + save scrambled them)
    except Exception:                                             # noqa: BLE001 - a repair never blocks a save
        pass
    src = _write_src()
    if src and str(output).lower().endswith(".flp"):
        nk = os.path.normcase(os.path.abspath(output))
        if not any(nk.startswith(t) for t in _TEMP_ROOTS) and not _own_folder(output):
            data = _own_title_bytes(data, src, output)
    os.makedirs(os.path.dirname(os.path.abspath(output)), exist_ok=True)
    key = os.path.normcase(os.path.abspath(output))
    if key not in _CALL_BACKUPS:                                 # one backup per tool call, before its first write
        temp = any(key.startswith(t) for t in _TEMP_ROOTS)
        if os.path.isfile(output) and output.lower().endswith(".flp") and not temp:
            _backup(output)
        _CALL_BACKUPS.add(key)
    tmp = f"{output}.{os.getpid()}.{threading.get_ident()}.tmp"  # one per writer: two threads never share it
    try:
        with open(tmp, "wb") as f:
            f.write(data)
        # PC-VERIFY: a song FL / OneDrive / an antivirus scan holds for a moment after a load or save is replaced once
        # it lets go (retried up to OS_RETRY_TOTAL_S), not 'PermissionError [WinError 5]' (checklists/core.md 'locks')
        _retry_os_long(lambda: os.replace(tmp, output), _lock_wait_s(len(data)))
    except BaseException:
        try:
            os.remove(tmp)                                        # a failed write (disk full) leaves nothing behind
        except OSError:
            pass
        raise
    _forget_file(output)
    _note_wrote(output, data)


def _notes_event(d, ev):
    hits = [k for k, e in enumerate(ev) if e["id"] == EV_NOTES and e["len"] % 24 == 0]
    if len(hits) != 1:
        raise ValueError(f"expected exactly one note pattern in the project, found {len(hits)} "
                         "(single-pattern projects only)")
    k = hits[0]; p = _payload(d, ev[k])
    return k, [struct.unpack(NOTE_RECORD, p[i:i + 24]) for i in range(0, len(p), 24)]


def _clip_event(d, ev):
    hits = [k for k, e in enumerate(ev) if e["id"] == EV_PLAYLIST and e["len"] == CLIP_RECORD
            and _payload(d, e)[4:6] == b"\x00\x50"]
    if len(hits) != 1:
        raise ValueError(f"expected exactly one pattern clip in the playlist, found {len(hits)}")
    return hits[0]


def _pattern_ctrl(ev, notes_k):
    """Index of the recorded-controller event (223) of the pattern whose notes are at notes_k, or None."""
    k = notes_k - 1
    while k >= 0 and ev[k]["id"] not in (EV_NOTES, 65):
        if ev[k]["id"] == EV_PATTERN_CTRL:
            return k
        k -= 1
    return None


def _ctrl_records(p):
    return [p[i:i + 12] for i in range(0, len(p) - len(p) % 12, 12)]


def _tempo_map(d, ev, notes_k):
    """[(tick, bpm)] from the project tempo plus tempo events recorded in the pattern."""
    main = next((struct.unpack("<I", _payload(d, e))[0] / 1000 for e in ev if e["id"] == EV_TEMPO), None)
    k = _pattern_ctrl(ev, notes_k) if notes_k is not None else None
    recs = []
    if k is not None:
        for r in _ctrl_records(_payload(d, ev[k])):
            if (r[4], r[7]) == TEMPO_CTRL:
                recs.append((struct.unpack("<I", r[:4])[0], struct.unpack("<I", r[8:])[0] / 1000))
    recs.sort()
    if not recs or recs[0][0] > 0:
        recs.insert(0, (0, main or 120.0))
    return recs


def _tempo_edits(d, ev, notes_k, tmap, P, div):
    """Edits that make the project tempo = tmap[0] and the pattern's tempo events = tmap (ticks in `div`)."""
    edits = []
    first = tmap[0][1]
    for k, e in enumerate(ev):
        if e["id"] == EV_TEMPO:
            edits.append((k, k + 1, bytes([EV_TEMPO]) + struct.pack("<I", int(round(first * 1000)))))
    recs = [struct.pack("<I", int(round(t * P / div))) + TEMPO_REC + struct.pack("<I", int(round(b * 1000)))
            for t, b in tmap]
    k = _pattern_ctrl(ev, notes_k)
    if k is not None:
        keep = [r for r in _ctrl_records(_payload(d, ev[k])) if (r[4], r[7]) != TEMPO_CTRL]
        allr = sorted(keep + recs, key=lambda r: struct.unpack("<I", r[:4])[0])
        edits.append((k, k + 1, _data_event(EV_PATTERN_CTRL, b"".join(allr))))
        return edits, b""
    return edits, _data_event(EV_PATTERN_CTRL, b"".join(recs))      # no controller event yet: goes before the notes


def _structure(d):
    """-> (events, channels {index: {...}}, effects {(track, slot): {...}}).
    A plugin block starting within 4 events of a ChannelNew belongs to that channel; any other is a mixer effect."""
    ev, chans, fx = _cached("structure", d, _structure_parse)
    return list(ev), {k: dict(v) for k, v in chans.items()}, {k: dict(v) for k, v in fx.items()}


def _structure_parse(d):
    ev = _events(d); chans, fx = {}, {}; cur, cur_k, blk = None, -99, None; in_ch = False
    for k, e in enumerate(ev):
        eid = e["id"]
        if eid == EV_CHANNEL:
            cur, cur_k = struct.unpack("<H", _payload(d, e))[0], k; chans[cur] = {"index": cur}; in_ch = True
        elif eid == EV_CHANNEL_END:
            in_ch = False
            if blk is not None and blk.get("channel") == cur and cur in chans:   # a sampler: name, no plugin state
                if blk.get("name") and "name" not in chans[cur]:
                    chans[cur]["name"] = blk["name"]
                if blk.get("plugin") and "plugin" not in chans[cur]:
                    chans[cur]["plugin"] = blk["plugin"]
                blk = None
        elif eid == EV_DISPLAY_NAME and blk is None and in_ch and cur in chans and "name" not in chans[cur]:
            chans[cur]["name"] = _text16(_payload(d, e))          # a sampler / audio channel's own name (no plugin)
        elif eid == EV_PLUGIN_NAME:
            blk = {"plugin": _text16(_payload(d, e)), "channel": cur if k - cur_k <= 4 else None, "first": k}
        elif blk is None:
            continue
        elif eid == EV_PLUGIN_HEADER:
            p = _payload(d, e)
            if len(p) >= 8:
                blk["track"], blk["slot"] = struct.unpack("<ii", p[:8])
        elif eid == EV_DISPLAY_NAME:
            blk["name"] = _text16(_payload(d, e))
        elif eid == EV_PLUGIN_STATE:
            blk["state"] = k
            if blk["channel"] is not None:
                chans[blk["channel"]].update(blk)
            else:                                                 # a block without a (readable) header: its own key
                key = (blk["track"], blk["slot"]) if blk.get("track") is not None else (None, blk["first"])
                fx[key] = blk
            blk = None
    return ev, chans, fx


def _mixer_slots(d, ev):
    """{(track, slot): (first_event_of_plugin_block or None, slot_marker_event)}"""
    tracks = [k for k, e in enumerate(ev) if e["id"] == EV_MIXER_TRACK]
    out = {}
    for t, k0 in enumerate(tracks):
        k1 = tracks[t + 1] if t + 1 < len(tracks) else len(ev)
        blk = None
        for k in range(k0 + 1, k1):
            if ev[k]["id"] == EV_PLUGIN_NAME:
                blk = k
            elif ev[k]["id"] == EV_MIXER_SLOT:
                out[(t, struct.unpack("<H", _payload(d, ev[k]))[0])] = (blk, k); blk = None
    return out


def _channel_block(d, ev, ch):
    """(first, last) event indices of a channel's plugin block."""
    start = None
    for k, e in enumerate(ev):
        if e["id"] == EV_CHANNEL and struct.unpack("<H", _payload(d, e))[0] == ch:
            start = k
        elif start is not None and e["id"] == EV_PLUGIN_NAME and k - start <= 4:
            return k, next(j for j in range(k, len(ev)) if ev[j]["id"] == EV_PLUGIN_STATE)
        elif start is not None and (e["id"] == EV_CHANNEL or k - start > 4):
            break
    raise ValueError(f"channel {ch} has no plugin")


def _fst_text(p):
    p = bytes(p or b"")
    if len(p) >= 2 and len(p) % 2 == 0 and b"\x00" in p[1::2] and not p[1::2].strip(b"\x00"):
        return _text16(p)
    return p.split(b"\x00")[0].decode("latin-1", "replace")


def _fst_default_for(plugin):
    """FL's own 'Default.fst' for a plugin (Plugin presets\\<Generators|Effects>\\<plugin>\\...), or None."""
    want = re.sub(r"[^a-z0-9]", "", str(plugin or "").lower())
    if not want:
        return None
    hits = []
    for root in _preset_roots():
        base = root if os.path.basename(root).lower() == "plugin presets" else os.path.join(root, "Plugin presets")
        for kind in ("Effects", "Generators"):
            kd = os.path.join(base, kind)
            if not os.path.isdir(kd):
                continue
            for plug in os.listdir(kd):
                if re.sub(r"[^a-z0-9]", "", plug.lower()) != want:
                    continue
                for r2, _, files in os.walk(os.path.join(kd, plug)):
                    for f in files:
                        if f.lower().startswith("default") and f.lower().endswith(".fst"):
                            hits.append(os.path.join(r2, f))
    hits.sort(key=lambda h: (os.path.basename(h).lower() != "default.fst", h.count(os.sep), h.lower()))
    return hits[0] if hits else None


def _fst_block(path, _resolve=True):
    """A .fst preset's plugin block -> ([(event id, payload, raw bytes)], plugin name).
    Older factory presets store names as 8-bit text; projects from FL 20+ use UTF-16, so names are converted.
    A Plugin database entry (FL's browser list: only the plugin's name, no settings) is resolved to the plugin's own
    Default.fst under Plugin presets, which FL loads exactly like dragging the plugin in."""
    d = _load(path); ev = _events(d)
    a = next((k for k, e in enumerate(ev) if e["id"] == EV_PLUGIN_NAME), None)
    b = next((k for k in range(a or 0, len(ev)) if ev[k]["id"] == EV_PLUGIN_STATE), None) if a is not None else None
    if a is None or b is None or not any(e["id"] == EV_PLUGIN_HEADER for e in ev[a:b]):
        # PC-VERIFIED 2026-10-20: FL 2026's Plugin database .fst files are ~120-byte name references
        name = _fst_text(_payload(d, ev[a])) if a is not None else os.path.splitext(os.path.basename(path))[0]
        alt = _fst_default_for(name) if _resolve else None
        if alt and os.path.normcase(os.path.abspath(alt)) != os.path.normcase(os.path.abspath(path)):
            return _fst_block(alt, _resolve=False)
        raise ValueError("this .fst has no plugin block (sample-based channel presets and bare Plugin database "
                         "entries aren't supported); pick a plugin preset, e.g. from the Plugin presets folders")
    out = []
    for e in ev[a:b + 1]:
        p = _payload(d, e)
        if e["id"] == EV_PLUGIN_HEADER and len(p) >= 20:
            # a preset saved with its window open opens that window with the song (PC 2026-10-20: every plugin
            # window popped up): clear 'editor visible' (bit 0) and 'detached' (bit 2) as FL writes closed ones
            fl_, = struct.unpack("<I", p[16:20])
            if fl_ & 0x5:
                p = p[:16] + struct.pack("<I", fl_ & ~0x5) + p[20:]
                out.append((e["id"], p, _data_event(e["id"], p)))
                continue
        if e["id"] in (EV_PLUGIN_NAME, EV_DISPLAY_NAME) and p and b"\x00" not in p[:-1]:
            p = p.rstrip(b"\x00").decode("latin-1").encode("utf-16-le") + b"\x00\x00"
            out.append((e["id"], p, _data_event(e["id"], p)))
        else:
            out.append((e["id"], p, _raw(d, e)))
    return out, _text16(out[0][1])


# ----------------------------------------------------------------------------- playlist markers, meter map
EV_MARKER_POS, EV_MARKER_NUM, EV_MARKER_DEN, EV_MARKER_NAME = 148, 33, 34, 205
MARKER_SIGNATURE = 0x08000000                                    # time-signature marker bit in the position


def _markers(d, ev, which=None):
    """Playlist (arrangement) markers of the current arrangement (or arrangement `which`):
    [{"tick", "name", "signature", "num", "den", "action"}]; a time signature marker has bit 0x08000000 set in its
    position."""
    out, cur = [], None
    a = _arrangement(d, ev, which)
    for e in (ev[a["first"] + 1:a["end"]] if a else []):
        i = e["id"]
        if i == EV_MARKER_POS and e["len"] == 4:
            v, = struct.unpack("<I", _payload(d, e))
            cur = {"tick": v & 0x07FFFFFF, "signature": bool(v & MARKER_SIGNATURE), "action": v >> 28, "name": "",
                   "num": None, "den": None}
            out.append(cur)
        elif cur is not None and i == EV_MARKER_NUM:
            cur["num"] = _payload(d, e)[0]
        elif cur is not None and i == EV_MARKER_DEN:
            cur["den"] = _payload(d, e)[0]
        elif cur is not None and i == EV_MARKER_NAME:
            cur["name"] = _text16(_payload(d, e))
            cur = None                                            # the name ends a marker's group: property events
    return out                                                    # after it without a 148 of their own are orphans


def _project_meter(d, ev):
    """(num, den) of the project time signature (events 17/18 before the first channel), default 4/4."""
    num = den = None
    for e in ev:
        if e["id"] == EV_CHANNEL:
            break
        if e["id"] == 17 and num is None and e["len"] == 1:
            num = _payload(d, e)[0]
        elif e["id"] == 18 and den is None and e["len"] == 1:
            den = _payload(d, e)[0]
    return (num or 4, den or 4)


def _meter_map(d, ev):
    """[(tick, num, den)]: the project's time signature, then each time-signature marker of the playlist."""
    meters = [(0,) + _project_meter(d, ev)]
    for mk in _markers(d, ev):
        if mk["signature"] and mk["num"] and mk["den"]:
            meters = [x for x in meters if x[0] != mk["tick"]] + [(mk["tick"], mk["num"], mk["den"])]
    return sorted(meters)


def _tick_to_bar(t, meters, P, nd=3):
    """Song tick -> bar number (1-based, fractional) through the meter map (rounded to nd places; nd=None exact)."""
    bar = 1.0
    for i, (t0, num, den) in enumerate(meters):
        t1 = meters[i + 1][0] if i + 1 < len(meters) else None
        blen = P * num * 4.0 / den
        if t1 is None or t < t1:
            return round(bar + (t - t0) / blen, nd) if nd is not None else bar + (t - t0) / blen
        bar += (t1 - t0) / blen
    return bar


def _markers_view(d, ev, P, limit=64):
    meters = _meter_map(d, ev); out = []
    for mk in _markers(d, ev)[:limit]:
        row = {"bar": _tick_to_bar(mk["tick"], meters, P), "name": mk["name"]}
        if mk["signature"]:
            row["time_signature"] = f"{mk['num']}/{mk['den']}"
        out.append(row)
    return out


# FL 2026 saves each marker as 148 33 34 46 45 168 101 205 (the name 205 ends it) and each playlist track as 238 43
# [239 name] (PC 2026-10-23 sweep: FL's own save). Readers and writers take a whole group, never 'the next event'.
MARKER_GROUP_IDS = {EV_MARKER_NUM, EV_MARKER_DEN, 45, 46, 101, 168, EV_MARKER_NAME}
EV_TRACK_DATA, EV_TRACK_NAME = 238, 239
TRACK_GROUP_IDS = {43, EV_TRACK_NAME}


def _marker_group_end(ev, k, hi=None):
    """Event index just after the marker group that starts at ev[k] (a 148): its 33/34/45/46/101/168 events and the
    name (205) that ends it."""
    hi = len(ev) if hi is None else hi
    j = k + 1
    while j < hi and ev[j]["id"] in MARKER_GROUP_IDS:
        j += 1
        if ev[j - 1]["id"] == EV_MARKER_NAME:
            break
    return j


def _marker_event(tick, name, sig=None):
    """One playlist marker's events: 148 position (+ 33/34 for a time-signature marker) + 205 name."""
    v = int(tick) & 0x07FFFFFF
    out = bytes([EV_MARKER_POS]) + struct.pack("<I", v | (MARKER_SIGNATURE if sig else 0))
    if sig:
        out += bytes([EV_MARKER_NUM, int(sig[0]) & 0xFF, EV_MARKER_DEN, int(sig[1]) & 0xFF])
    return out + _data_event(EV_MARKER_NAME, str(name).encode("utf-16-le") + b"\x00\x00")


def _track_groups(d, ev, which=None):
    """Playlist tracks of the current arrangement (or arrangement `which`): {track number: {"k": index of its 238,
    "end": index after its group (238 43 [239]), "name": text or None, "name_k": index of the 239 or None}}.
    FL 2026 writes 238 43 239; older fl-headless writes put 239 right after 238 - both are read."""
    a = _arrangement(d, ev, which)
    if a is None:
        return {}
    out = {}; k = a["first"] + 1; hi = a["end"]
    while k < hi:
        e = ev[k]
        if e["id"] == EV_TRACK_DATA and e["len"] >= 8:
            j = k + 1; nk = None
            while j < hi and ev[j]["id"] in TRACK_GROUP_IDS:
                if ev[j]["id"] == EV_TRACK_NAME and nk is None:
                    nk = j
                j += 1
            t = struct.unpack("<I", _payload(d, e)[:4])[0]
            out[t] = {"k": k, "end": j, "name_k": nk, "name": _text16(_payload(d, ev[nk])) if nk is not None else None}
            k = j
            continue
        k += 1
    return out


def _marker_slot(d, ev, arr=None, after_markers=True):
    """Event index where playlist markers go: right after the arrangement's playlist event (233), before its track
    groups (238 43 239) - exactly where FL's own save puts them (99 241 36 233 | 148 33 34 46 45 168 101 205 ... |
    238 43 239 ...; PC 2026-10-23 evidence, an FL-saved song). PC 2026-10-23: markers written between the arrangement
    header (99 241 36) and its 233 came back from FL's load+save as markers of the LAST PATTERN (inside its 65 .. 164
    group): the playlist showed none. after_markers: past markers already at that spot (they keep coming first).
    None when the project has no playlist event."""
    # PC-VERIFY: markers written here show on FL's playlist ruler and stay in the arrangement after FL's save
    # (pc_check files.markers_meter, newsong.playlist_names)
    a = arr if arr is not None else _arrangement(d, ev, None)
    kp = a.get("playlist") if a else None
    if kp is None:
        kp = next((k for k, e in enumerate(ev) if e["id"] == EV_PLAYLIST), None)
        if kp is None:
            return None
    hi = a["end"] if a else len(ev)
    slot = kp + 1
    while after_markers and slot < hi and ev[slot]["id"] == EV_MARKER_POS:   # after markers already there
        slot = _marker_group_end(ev, slot, hi)
    return slot


def _marker_layout_fix(d, ev=None):
    """(bytes, fixed): every arrangement's playlist markers laid out the way FL's own save lays them out (right after
    its 233, before its track groups), else `d` unchanged and 0. Repairs what older fl-headless writes left behind
    (PC 2026-10-23: after FL's load + save every marker of a song sat at its last marker's bar with names of an older
    version, and the real markers had become the last pattern's):
    - marker groups (148 .. 205) before the arrangement's 233 (FL takes them as the last pattern's markers) or after
      its track groups move right after the 233;
    - marker property events (33 34 45 46 101 168 205) without a 148 of their own - what a rewrite that took only
      148 33 34 out of FL's 148 33 34 46 45 168 101 205 groups left - are dropped: FL hangs them on the last marker
      read, so each old name became one more marker at that bar.
    Also undoes that damage once FL saved it (_marker_rescue). Runs inside _save, so any write of a damaged file
    repairs it."""
    ev = _events(d) if ev is None else ev
    got = _marker_rescue(d, ev)
    if got:
        return got
    ids = MARKER_GROUP_IDS | {EV_MARKER_POS}
    edits = []; fixed = 0
    for a in _arrangements(d, ev):
        kp = a.get("playlist"); lo, hi = a["first"] + 1, a["end"]
        if kp is None or not (lo <= kp < hi):
            continue

        def scan(k0, k1, keep):
            """Marker groups / orphan events in ev[k0:k1] -> (groups [(k, j)], orphans [k]); keep: stop at the first
            event that isn't a marker's (a contiguous run)."""
            gs, orph, k = [], [], k0
            while k < k1:
                i = ev[k]["id"]
                if i == EV_MARKER_POS and ev[k]["len"] == 4:
                    j = _marker_group_end(ev, k, k1); gs.append((k, j)); k = j
                    continue
                if i in ids:
                    orph.append(k)
                elif keep:
                    break
                k += 1
            return gs, orph, k
        head_g, head_o, _ = scan(lo, kp, False)                   # between 99 241 36 and 233: never FL's place
        body_g, body_o, b_end = scan(kp + 1, hi, True)            # right after 233: FL's place
        groups = _track_groups(d, ev, a["index"])
        tail_g, tail_o = [], []
        t_end = max((g["end"] for g in groups.values()), default=None)
        if t_end is not None and t_end > b_end:                   # after the track groups (an older fl-headless slot)
            tail_g, tail_o, _ = scan(t_end, hi, True)
        if not (head_g or head_o or body_o or tail_g or tail_o):
            continue
        raw = lambda gs: b"".join(d[ev[k]["off"]:(ev[j]["off"] if j < len(ev) else len(d))] for k, j in gs)
        for k, j in head_g + tail_g:
            edits.append((k, j, b""))
        for k in head_o + body_o + tail_o:
            edits.append((k, k + 1, b""))
        if head_g:
            edits.append((kp + 1, kp + 1, raw(head_g)))           # before FL's own groups (older writes made them)
        if tail_g:
            edits.append((b_end, b_end, raw(tail_g)))
        fixed += len(head_g) + len(tail_g) + len(head_o) + len(body_o) + len(tail_o)
    if not edits:
        return d, 0
    return _splice(d, ev, edits), fixed


def _marker_damage(d, ev):
    """FL's load + save of an older fl-headless marker layout, recognized by its exact fingerprint: every playlist
    marker of the current arrangement (2 or more) sits at ONE tick, and that tick is the last of 2+ section markers
    (not time signatures) FL moved into one pattern. -> {"arr", "stacked" [(k, j)], "stray" [(k, j)], "tick",
    "pattern"} or None. (A user's own markers never look like that: FL stacked the old names on the last marker it
    read, which is also the last of the markers it took into the pattern.)"""
    a = _arrangement(d, ev, None)
    if not a or a.get("playlist") is None:
        return None
    lo, hi = a["first"] + 1, a["end"]
    stacked, ticks = [], set()
    k = lo
    while k < hi:
        if ev[k]["id"] == EV_MARKER_POS and ev[k]["len"] == 4:
            j = _marker_group_end(ev, k, hi)
            v, = struct.unpack("<I", _payload(d, ev[k]))
            stacked.append((k, j)); ticks.add(v & 0x07FFFFFF); k = j
            continue
        k += 1
    if len(stacked) < 2 or len(ticks) != 1:
        return None
    spans = [(x["first"], x["end"]) for x in _arrangements(d, ev)]
    by_pat, pat = {}, None
    for k, e in enumerate(ev[:a["first"]]):
        if e["id"] == EV_PATTERN_NEW and e["len"] == 2:
            pat = struct.unpack("<H", _payload(d, e))[0]
        elif e["id"] == EV_MARKER_POS and e["len"] == 4 and not any(s <= k < t for s, t in spans):
            v, = struct.unpack("<I", _payload(d, e)); j = _marker_group_end(ev, k)
            nm = next((_text16(_payload(d, ev[i])) for i in range(k + 1, j) if ev[i]["id"] == EV_MARKER_NAME), "")
            if not v & MARKER_SIGNATURE and not re.fullmatch(r"\s*\d+\s*/\s*\d+\s*", nm):   # FL's own '4/4' marker
                by_pat.setdefault(pat, []).append((k, j, v & 0x07FFFFFF))      # of a pattern stays
    tick = next(iter(ticks))
    for p, grp in by_pat.items():                                 # real section markers: spread over the song
        if len(grp) >= 2 and max(t for _, _, t in grp) == tick and len({t for _, _, t in grp}) >= 2:
            return {"arr": a, "stacked": stacked, "stray": [(k, j) for k, j, _ in grp], "tick": tick, "pattern": p}
    return None


def _marker_rescue(d, ev):
    """Undo _marker_damage: the section markers FL moved into the pattern go back to the playlist (right after the
    233, in their order, positions and names as written), the stacked copies at one bar go. -> (bytes, n) or None."""
    dmg = _marker_damage(d, ev)
    if not dmg:
        return None
    kp = dmg["arr"]["playlist"]
    edits = [(k, j, b"") for k, j in dmg["stacked"] + dmg["stray"]]
    raw = b"".join(d[ev[k]["off"]:(ev[j]["off"] if j < len(ev) else len(d))] for k, j in dmg["stray"])
    edits.append((kp + 1, kp + 1, raw))
    return _splice(d, ev, edits), len(dmg["stray"])


def _stray_markers(d, ev):
    """Markers outside every arrangement - FL keeps those as a pattern's own markers (the piano roll's), not the
    playlist's: [{"tick", "name", "pattern", "signature"}]. FL itself saves a pattern's time signature there (a '4/4'
    marker in FL 2026 files); a section marker FL moved there was written in the wrong place."""
    spans = [(a["first"], a["end"]) for a in _arrangements(d, ev)]
    out, pat = [], None
    for k, e in enumerate(ev):
        if e["id"] == EV_PATTERN_NEW and e["len"] == 2:
            pat = struct.unpack("<H", _payload(d, e))[0]
        elif e["id"] == EV_MARKER_POS and e["len"] == 4 and not any(a <= k < b for a, b in spans):
            j = _marker_group_end(ev, k)
            nm = next((_text16(_payload(d, ev[i])) for i in range(k + 1, j) if ev[i]["id"] == EV_MARKER_NAME), "")
            v, = struct.unpack("<I", _payload(d, e))
            out.append({"tick": v & 0x07FFFFFF, "name": nm, "pattern": pat, "signature": bool(v & MARKER_SIGNATURE)})
    return out


# ----------------------------------------------------------------------------- structural blocks
# FL 2026 order: header | pattern data groups (65 + 223/224) | remote links (226/227) | channel 0 (64 .. its 51) |
# pattern name/settings groups (65 + PATTERN_META) | channels 1.. | arrangements (99 241 36 233 238 43 ..., markers) |
# globals (242 100 29 ...) | mixer (236 ...). Boundaries are structural events, never "the ids we happen to know".
EV_ARRANGEMENT = 99
EV_CURRENT_ARRANGEMENT = 100                                     # globals: the arrangement FL shows (PC-VERIFY)
PATTERN_BOUNDARY = {EV_PATTERN_NEW, EV_CHANNEL, EV_ARRANGEMENT, 226, 227, 236, EV_PLAYLIST, 238, 241, 242}
CHANNEL_BOUNDARY = {EV_CHANNEL, EV_PATTERN_NEW, EV_ARRANGEMENT, 236}


def _blocks(d, ev):
    """[(kind, id, first, end)] structural blocks (end exclusive): "pattern_data" (PatternNew + 223/224),
    "pattern_meta" (PatternNew + name/settings), "pattern" (a bare PatternNew), "channel" (ChannelNew .. its end event
    51), "arrangement" (99 .. the next 99 / mixer; the last one also holds the globals)."""
    if isinstance(d, bytes) and len(ev) == len(_cached("events", d, _events_parse)):
        return list(_cached("blocks", d, lambda d_: _blocks_parse(d_, _events(d_))))
    return _blocks_parse(d, ev)


def _blocks_parse(d, ev):
    out = []; n = len(ev); k = 0
    while k < n:
        eid = ev[k]["id"]
        if eid == EV_PATTERN_NEW and ev[k]["len"] >= 2:
            j = k + 1
            while j < n and ev[j]["id"] not in PATTERN_BOUNDARY:
                j += 1
            ids = {ev[x]["id"] for x in range(k + 1, j)}
            kind = "pattern_data" if ids & {EV_NOTES, EV_PATTERN_CTRL} else "pattern_meta" if ids else "pattern"
            out.append((kind, struct.unpack("<H", _payload(d, ev[k])[:2])[0], k, j)); k = j
        elif eid == EV_CHANNEL and ev[k]["len"] >= 2:
            j = k + 1
            while j < n and ev[j]["id"] != EV_CHANNEL_END and ev[j]["id"] not in CHANNEL_BOUNDARY:
                j += 1
            if j < n and ev[j]["id"] == EV_CHANNEL_END:
                j += 1
            out.append(("channel", struct.unpack("<H", _payload(d, ev[k])[:2])[0], k, j)); k = j
        elif eid == EV_ARRANGEMENT:
            j = k + 1
            while j < n and ev[j]["id"] not in (EV_ARRANGEMENT, EV_MIXER_TRACK):
                j += 1
            aid = struct.unpack("<H", _payload(d, ev[k])[:2])[0] if ev[k]["len"] >= 2 else len(out)
            out.append(("arrangement", aid, k, j)); k = j
        else:
            k += 1
    return out


def _pattern_groups(d, ev):
    return [b for b in _blocks(d, ev) if b[0].startswith("pattern")]


def _channel_span(d, ev, ch):
    """(first, end) event range of channel `ch`'s block (ChannelNew .. its end event 51, end exclusive)."""
    for kind, i, a, b in _blocks(d, ev):
        if kind == "channel" and i == int(ch):
            return a, b
    raise ValueError(f"no channel {ch}")


def _pattern_note_events(d, ev):
    """{pattern id: [event indexes of its notes events (224)]}; FL writes one per pattern, odd files have several."""
    out = {}
    for kind, pid, a, b in _pattern_groups(d, ev):
        out.setdefault(pid, [])
        out[pid] += [k for k in range(a + 1, b) if ev[k]["id"] == EV_NOTES and ev[k]["len"] % 24 == 0]
    return out


def _notes_event_edits(ev, ks, body):
    """Edits that make a pattern's notes = body: the first notes event gets it, any further one goes."""
    return [(ks[0], ks[0] + 1, _data_event(EV_NOTES, body))] + [(k, k + 1, b"") for k in ks[1:]]


def _arrangements(d, ev):
    """[{"index", "name", "first", "end", "playlist" (event index of its clips or None), "current"}]."""
    if isinstance(d, bytes) and len(ev) == len(_cached("events", d, _events_parse)):
        return [dict(a) for a in _cached("arrangements", d, lambda d_: _arrangements_parse(d_, _events(d_)))]
    return _arrangements_parse(d, ev)


def _arrangements_parse(d, ev):
    out = []
    for kind, aid, a, b in _blocks(d, ev):
        if kind != "arrangement":
            continue
        name = next((_text16(_payload(d, ev[k])) for k in range(a + 1, b) if ev[k]["id"] == 241), "")
        pl = next((k for k in range(a + 1, b) if ev[k]["id"] == EV_PLAYLIST), None)
        out.append({"index": aid, "name": name, "first": a, "end": b, "playlist": pl, "current": False})
    if out:
        cur = None
        for e in ev[out[0]["first"]:]:
            if e["id"] == EV_MIXER_TRACK:
                break
            if e["id"] == EV_CURRENT_ARRANGEMENT and e["len"] == 2:
                cur = struct.unpack("<H", _payload(d, e))[0]
        hit = next((a for a in out if a["index"] == cur), out[0])
        hit["current"] = True
    return out


def _arrangement(d, ev, which=None):
    """The current arrangement (FL's selected one), or arrangement index `which`; None in a project without any."""
    arrs = _arrangements(d, ev)
    if which is None:
        return next((a for a in arrs if a["current"]), None)
    hit = next((a for a in arrs if a["index"] == int(which)), None)
    if hit is None:
        raise ValueError(f"no arrangement {which} (this project has {[a['index'] for a in arrs]})")
    return hit


# FL's playlist clip record: 88 bytes since FL 2024; 60 in FL 21 and 32 in FL 20 and older (PyFLP's layouts; the
# first 32 bytes are the same in all three). PC-VERIFY: open FL 20 / FL 21 projects (flp_playlist list = FL's playlist).
CLIP_SIZES = (88, 60, 32)


def _fl_major(d, ev):
    for e in ev:
        if e["id"] == EV_VERSION:
            m_ = re.match(rb"\s*(\d+)", _payload(d, e))
            return int(m_.group(1)) if m_ else None
        if e["id"] in (EV_CHANNEL, EV_PATTERN_NEW):
            break
    return None


def _clip_size(d, ev, p):
    """Record size of the playlist payload p: the FL version's layout when the records check out (0x5000 at +4 in
    every record), else the one layout that does; ValueError when none does."""
    major = _fl_major(d, ev)
    pref = 88 if major is None or major >= 22 else 60 if major == 21 else 32
    if not p:
        return pref
    for size in (pref,) + tuple(x for x in CLIP_SIZES if x != pref):
        if len(p) % size == 0 and all(p[i + 4:i + 6] == b"\x00\x50" for i in range(0, len(p), size)):
            return size
    raise ValueError(f"the playlist format of this project (FL {major or '?'}, {len(p)} bytes of clips) isn't one "
                     "fl-headless knows, so it won't read or edit its playlist")


def _clip_id(r, i):
    """A clip's id: FL 2024+ records carry one at +32; older layouts get their 1-based place in the list."""
    return struct.unpack("<I", r[32:36])[0] if len(r) >= 88 else i + 1


def _playlist_at(d, ev, which=None):
    """(event index of the arrangement's clip event or None, record size, [bytearray records]) for the current
    arrangement (or arrangement `which`)."""
    a = _arrangement(d, ev, which)
    if a is None or a["playlist"] is None:
        return None, _clip_size(d, ev, b""), []
    k = a["playlist"]; p = _payload(d, ev[k]); size = _clip_size(d, ev, p)
    return k, size, [bytearray(p[i:i + size]) for i in range(0, len(p), size)]


def _next_clip_id(ids):
    """A fresh clip id: one above the highest, or the lowest unused one when that would overflow 32 bits."""
    top = max(ids, default=0) + 1
    if top <= 0xFFFFFFFF:
        return top
    used = set(ids)
    return next(i for i in range(1, len(used) + 2) if i not in used)


MAX_PLAYLIST_TRACK = 500


def _check_track(track):
    t = int(track)
    if not 1 <= t <= MAX_PLAYLIST_TRACK:
        raise ValueError(f"playlist track {t} doesn't exist (FL's playlist has tracks 1-{MAX_PLAYLIST_TRACK})")
    return t


def _new_pattern_id(pats):
    """Next pattern id: one above the highest, or the lowest free one in 1..999 (FL's limit) past that."""
    top = max(pats, default=0) + 1
    if top <= 999:
        return top
    nxt = next((i for i in range(1, 1000) if i not in pats), None)
    if nxt is None:
        raise ValueError("this project already has 999 patterns (FL's limit)")
    return nxt


def _bar_to_tick(bar, meters, P):
    """Song bar (1-based, fractional) -> tick through the meter map (the inverse of _tick_to_bar)."""
    bar = float(bar); t_at = 0; b_at = 1.0
    for i, (t0, num, den) in enumerate(meters):
        blen = P * num * 4.0 / den
        t1 = meters[i + 1][0] if i + 1 < len(meters) else None
        if t1 is not None:
            b1 = b_at + (t1 - t0) / blen
            if bar >= b1:
                b_at = b1; continue
        return int(round(t0 + (bar - b_at) * blen))
    return int(round((bar - 1) * 4 * P))


def _song_bar_ticks(d, ev, P):
    """Ticks per bar of the project's own time signature (pattern-relative bars use it)."""
    num, den = _project_meter(d, ev)
    return max(1, int(round(P * num * 4.0 / den)))


SANE_SONG_BARS = 20000                                           # past this a note/clip position is a corrupt value


def _sane_span(end_tick, P, what="the song"):
    if end_tick > SANE_SONG_BARS * 4 * P:
        raise ValueError(f"{what} reaches bar {int(end_tick // (4 * P)) + 1:,}, which looks like a corrupt position "
                         f"(over {SANE_SONG_BARS:,} bars); check the project in FL (flp_playlist / fl_doctor)")


def _sane_bpm(b):
    """A tempo value FL can play (10-999 BPM), else None (0 or garbage in a file is ignored, not divided by)."""
    try:
        b = float(b)
    except (TypeError, ValueError):
        return None
    return b if 10.0 <= b <= 999.0 else None


# ============================================================================= FLP: tools
def flp_info(path, fields=None):
    """Quick facts of a .flp. fields: only these keys (a list or 'a,b'; e.g. ['tempo_bpm', 'time_signature']) -
    an unknown one is named with the keys there are."""
    d = _load(path)
    info = _cached("info", d, _flp_info_parse)                   # by content: a re-read of the same bytes is free
    if fields in (None, "", []):
        return {"path": path, **_jcopy(info)}                     # (a fresh copy: callers may edit theirs)
    want = [f.strip() for f in (fields.split(",") if isinstance(fields, str) else fields) if str(f).strip()]
    out = {"path": path}
    for f in want:
        if f in info:
            out[f] = _jcopy(info[f]) if isinstance(info[f], (dict, list)) else info[f]
    miss = [f for f in want if f not in info and f != "path"]
    if miss:
        out["unknown_fields"] = miss
        out["fields_here"] = sorted(info)
    return out


def _flp_info_parse(d):
    ev = _events(d); P = _ppq(d)
    info = {"ppq": P}
    for e in ev:
        if e["id"] == EV_VERSION and "fl_version" not in info:
            info["fl_version"] = _payload(d, e).rstrip(b"\x00").decode("ascii", "replace")
        elif e["id"] == EV_TEMPO and "tempo_bpm" not in info:
            info["tempo_bpm"] = struct.unpack("<I", _payload(d, e))[0] / 1000
    notes, tempos = _song(d, ev)
    per = {}
    for n in notes:
        per[n[2]] = per.get(n[2], 0) + 1
    info["notes_per_channel"] = per
    meters = _meter_map(d, ev)
    to_bars = lambda t: round(_tick_to_bar(t, meters, P) - 1, 2) if t else 0
    info["last_note_end_bars"] = to_bars(max(n[0] + n[1] for n in notes)) if notes else 0
    clips = _clips(d, ev)
    info["patterns"] = len(_patterns(d, ev)); info["clips"] = len(clips)
    info["song_length_bars"] = to_bars(max((struct.unpack("<I", r[0:4])[0] + struct.unpack("<I", r[8:12])[0]
                                            for _, _, r in clips), default=0))
    arrs = _arrangements(d, ev)
    if len(arrs) > 1:                                             # readers report the arrangement FL plays
        info["arrangements"] = [{"index": a["index"], "name": a["name"], "current": a["current"],
                                 "clips": len(_playlist_at(d, ev, a["index"])[2])} for a in arrs]
    if len(tempos) > 1:
        info["tempo_events"] = len(tempos)
    num, den = _project_meter(d, ev)
    info["time_signature"] = f"{num}/{den}"
    if len(meters) > 1:
        info["time_signature_changes"] = [{"bar": _tick_to_bar(t, meters, P), "time_signature": f"{n}/{dd}"}
                                          for t, n, dd in meters[1:]]
    mk = _markers_view(d, ev, P)
    try:
        lay = _marker_layout_fix(d, ev)[1]
    except Exception:                                             # noqa: BLE001 - a note only
        lay = 0
    if lay:
        info["markers_note"] = (f"{lay} marker group(s)/event(s) sit where FL's load + save scrambles them (an older "
                                "fl-headless write - or FL already did: every marker at one bar, the real ones on a "
                                "pattern). The next fl-headless edit of this file puts them back where FL keeps them")
    if mk:
        info["markers"] = mk
    elif not lay:
        try:
            stray = [s for s in _stray_markers(d, ev) if not s["signature"]]   # FL gives patterns a 4/4 marker
        except Exception:                                         # noqa: BLE001 - a note only
            stray = []
        if stray:                                                 # e.g. a song from fl-headless before 2026-10-23
            pats = sorted({s["pattern"] for s in stray if s["pattern"] is not None})
            info["markers_note"] = (f"no playlist markers, but {len(stray)} marker(s) sit on pattern(s) {pats[:4]} "
                                    f"({', '.join(repr(s['name']) for s in stray[:4])}): FL keeps those as the "
                                    "pattern's own markers")
    return info


def flp_list(path):
    d = _load(path); ev, chans, fx = _structure(d)
    ins = _channel_inserts(d, ev)
    return {"events": len(ev),
            "channels": [{"index": c["index"], "name": c.get("name"), "plugin": c.get("plugin"),
                          "state_bytes": ev[c["state"]]["len"] if "state" in c else 0,
                          **({"insert": ins[c["index"]]} if c["index"] in ins else {})} for c in chans.values()],
            "effects": [{"track": f.get("track"), "slot": f.get("slot"), "plugin": f.get("plugin"), "name": f.get("name"),
                         "state_bytes": ev[f["state"]]["len"]}
                        for (t, s), f in sorted(fx.items(), key=lambda kv: (kv[0][0] if kv[0][0] is not None else -1,
                                                                            kv[0][1] if kv[0][1] is not None else -1))]}


def flp_set_song_length(path, bars):
    d = _load(path); ev = _events(d)
    try:
        k = _clip_event(d, ev)
    except ValueError:                                            # several clips (a tempo lane, audio, layers...):
        lst = flp_playlist(path, "list")                          # stretch the one pattern clip at bar 1, if any
        pc = [c for c in lst.get("clips", []) if c.get("kind") == "pattern"]
        one = [c for c in pc if abs(float(c["bar"]) - 1) < 1e-6]
        if not pc:
            raise ValueError("the playlist has no pattern clip to set the song length with (place a pattern first)")
        if len(pc) == 1 or len(one) == 1:
            c = pc[0] if len(pc) == 1 else one[0]
            flp_playlist(path, "resize", output=path, clips=[c["id"]], length_bars=float(bars))
            return {"path": path, "song_length_bars": float(bars)}
        return {"path": path, "song_length_bars": None,
                "note": "several pattern clips: the song is as long as its clips (nothing stretched)"}
    rec = bytearray(_payload(d, ev[k]))
    ticks = _bar_to_tick(1 + float(bars), _meter_map(d, ev), _ppq(d))     # bars of the song's time signature
    s0, = struct.unpack("<I", rec[24:28])                         # a clip that starts later into its pattern
    rec[8:12] = struct.pack("<I", ticks); rec[28:32] = struct.pack("<I", ticks + (s0 if s0 <= 1 << 28 else 0))
    _save(_splice(d, ev, [(k, k + 1, _data_event(EV_PLAYLIST, bytes(rec)))]), path)
    return {"path": path, "song_length_bars": float(bars)}


def flp_set_tempo(path, bpm):
    """Set the project tempo. Tempo events recorded in the pattern (e.g. from a MIDI import) override
    the project tempo when FL plays or renders, so they are moved too (the first one becomes `bpm`,
    later ones keep their ratio to it)."""
    d = _load(path); ev = _events(d)
    hits = [k for k, e in enumerate(ev) if e["id"] == EV_TEMPO]
    if not hits:
        raise ValueError("no tempo event found")
    target = int(round(float(bpm) * 1000))
    edits = [(k, k + 1, bytes([EV_TEMPO]) + struct.pack("<I", target)) for k in hits]
    if not 10 <= float(bpm) <= 522:
        raise ValueError(f"tempo {bpm} BPM is outside FL's range (10-522)")
    scaled = 0; base = None
    for k, e in enumerate(ev):
        if e["id"] != EV_PATTERN_CTRL or e["len"] % 12:
            continue
        p = bytearray(_payload(d, e))
        for i in range(0, len(p), 12):
            if (p[i + 4], p[i + 7]) == TEMPO_CTRL:
                v = struct.unpack_from("<I", p, i + 8)[0]
                if not _sane_bpm(v / 1000):                           # 0 / garbage: not a reference, left alone
                    continue
                base = base or v                                       # first recorded tempo = reference
                struct.pack_into("<I", p, i + 8, min(0xFFFFFFFF, int(round(v * target / base))))
                scaled += 1
        edits.append((k, k + 1, _data_event(EV_PATTERN_CTRL, bytes(p))))
    _save(_splice(d, ev, edits), path)
    return {"path": path, "tempo_bpm": float(bpm), "pattern_tempo_events_scaled": scaled}


def flp_write_notes(template, output, parts, song_length="auto", tail_bars=2, tempo="auto", meter="auto",
                    clear_song=False):
    """Replace all notes of the template's pattern with notes from MIDI files (one per channel).
    tempo: "auto" = take the tempo map of the first MIDI file that has one (FL plays it as recorded tempo
    events, so notes can stay on the grid while the tempo moves; a project with several patterns gets it as a Tempo
    lane), "keep" = leave the template's, or a number. meter: "auto" = the first MIDI file's time signature (FF 58)
    becomes the project's, later changes become time-signature markers; "keep"; or "3/4". A template that is an
    arranged song (several patterns with notes) is refused unless clear_song=True: then its patterns, clips, markers
    and tempo lane are left out of the output (channels, plugins, mixer kept - as flp_new_from) and the parts are
    written as a new song."""
    writable(output)
    d = _load(template); ev = _events(d); P = _ppq(d)
    held = [f"{v['name'] or pid} ({len(v['notes'])} notes)" for pid, v in sorted(_patterns(d, ev).items()) if v["notes"]]
    if len(held) > 1 or (held and sum(1 for e in ev if e["id"] == EV_NOTES and e["len"] % 24 == 0) != 1):
        if not clear_song:
            raise ValueError(f"the template is an arranged song ({len(held)} patterns hold notes: {', '.join(held[:6])}). "
                             "To write a new song with its sounds: clear_song=true (its patterns, clips and markers "
                             "are left out of the output; channels and mixer kept) or flp_new_from first; to change "
                             "one part of this song: flp_replace_part")
    pre = []                                                      # what's done to the copy before the notes go in
    if clear_song and (held or _clips(d, ev)):
        d, info = _new_song_bytes(d, None, None)
        pre.append(f"the template's song was left out ({info['patterns']} patterns, {info['clips']} clips, "
                   f"{info['markers']} markers); its channels and mixer kept")
    mt = None
    if meter not in (None, "keep"):
        if meter == "auto":
            mt = next((m_ for m_ in (_midi_meters(p_["midi"], P) for p_ in parts if p_.get("midi")) if m_), None)
        else:
            mt = [(0,) + _parse_meter(meter)]
        if mt:
            if mt[0][0] > 0:                                      # MIDI's 4/4 before its first time signature
                mt.insert(0, (0, 4, 4))
            d, said = _meter_map_write(d, mt)
            if said:
                pre.append(said)
    if pre:
        _save(d, output); template = output; ev = _events(d)
    if sum(1 for e in ev if e["id"] == EV_PATTERN_NEW) > 2:
        npat, empty = _all_patterns_empty(d, ev)
        if empty:                                                  # flh_new_song's empty section blocks: one 'Song'
            r = _write_into_fresh_song(template, output, parts, [{"name": "Song", "bar": 1}], tempo,
                                       tail_bars if song_length == "auto" else 0)
            if pre:
                r["before"] = pre
            return r
    k, old = _notes_event(d, ev)
    midi_ch = {}
    for r in old:
        midi_ch.setdefault(r[2], r[9])
    recs = []; tmap = None; tdiv = None; warns = []
    for part in parts:
        ch = int(part["channel"])
        if part.get("notes") is not None:                         # inline [bar, length_bars, pitch, vel(, slide)]
            div, notes = _inline_notes_x(template, part["notes"], P); tm = None
        else:
            div, notes, tm = midi_read(part["midi"], warns)
        if tm and tmap is None:
            tmap, tdiv = tm, div
        for n in notes:
            s, e, key, v = n[:4]; sl = len(n) > 4 and n[4]
            ps = s * P // div; pl = max(1, e * P // div - ps)              # floor both ends, like FL's import
            recs.append((ps, NOTE_FLAGS_DEFAULT | (NOTE_SLIDE if sl else 0), ch, pl, key, 0, 120, 0, 0,
                         midi_ch.get(ch, 0), 64, v, 128, 128))
    if not recs:
        raise ValueError("no notes found in the MIDI files")
    recs.sort(key=lambda r: (r[0], r[2], r[4]))
    body = b"".join(struct.pack(NOTE_RECORD, *r) for r in recs)
    edits = []; prefix = b""
    res = {"output": output, "notes_written": len(recs)}
    if tempo != "keep":
        if tempo != "auto":
            tmap, tdiv = [(0, float(tempo))], P
        if tmap:
            edits, prefix = _tempo_edits(d, ev, k, tmap, P, tdiv)
            res["tempo_events"] = len(tmap); res["tempo_start_bpm"] = tmap[0][1]
    edits.append((k, k + 1, prefix + _data_event(EV_NOTES, body)))
    _save(_splice(d, ev, edits), output)
    if song_length == "auto":
        end = max(r[0] + r[3] for r in recs); dd = _load(output)    # whole bars of the song's time signature
        if not _clips(dd, _events(dd)):                           # a pattern the playlist doesn't play (FL's
            pid = next(iter(sorted(_patterns(dd, _events(dd)))), None)   # empty template + a new pattern): placed
            if pid is not None:                                   # at bar 1, else nothing would sound
                flp_playlist(output, "place", output=output, pattern=pid, bar=1, track=1)
                res["placed"] = f"pattern {pid} put on the playlist at bar 1 (it wasn't placed)"
                dd = _load(output)
        res.update(flp_set_song_length(output, int(_tick_to_bar(end, _meter_map(dd, _events(dd)), P) - 1)
                                       + int(tail_bars)))
    elif song_length is not None:
        res.update(flp_set_song_length(output, float(song_length)))
    if warns:
        res["warnings"] = warns
    if pre:
        res["before"] = pre
    return _overlap_report(res, [(r[2], r[0], r[3], r[4]) for r in recs])


def flp_export_midi(path, output, channels=None):
    """Write the project's notes (and its tempo map) to a type-1 MIDI file, one track per channel."""
    if not output.lower().endswith((".mid", ".midi")):
        raise ValueError("output must be a .mid file")
    writable(output)
    d = _load(path); ev, chans, _ = _structure(d); P = _ppq(d)
    notes, tempos = _song(d, ev)
    want = None if channels is None else {int(c) for c in channels}
    meters = _meter_map(d, ev)
    tsig = []; warnings = []
    for t, num, den in meters:                                    # FF 58: nn, dd = log2(den), clocks/click, 32nds/qn
        if not den or den & (den - 1) or not 1 <= num <= 255 or den > 2 ** 15:
            warnings.append(f"time signature {num}/{den} can't be written to MIDI (the denominator must be a power of "
                            "2); left out")
            continue
        tsig.append((int(t), b"\xff\x58\x04" + bytes([int(num), int(den).bit_length() - 1, 24, 8])))
    tempo_evs = []
    for t, b in tempos:
        if not b or b <= 0:
            continue
        us = max(1, min(0xFFFFFF, int(round(60_000_000 / b))))   # MIDI's 3-byte tempo: 3.58 .. 60M BPM
        tempo_evs.append((int(t), b"\xff\x51\x03" + us.to_bytes(3, "big")))
    tracks = [("tempo", tempo_evs + tsig)]
    per = {}
    for n in notes:
        if want is None or n[2] in want:
            per.setdefault(n[2], []).append(n)
    moved = 0
    for i, (ch, rs) in enumerate(sorted(per.items())):
        mc = [c for c in range(16) if c != 9][i % 15]           # never GM's drum channel 10 (the 25th part landed there)
        evs = []
        for r in rs:
            pos, length, key, vel = r[0], r[1], r[3], max(1, min(127, r[4]))
            if key > 127:                                         # FL's roll reaches 131 (B10); MIDI stops at 127
                key -= 12 * -(-(key - 127) // 12); moved += 1
            evs.append((pos, bytes([0x90 | mc, key, vel]))); evs.append((pos + length, bytes([0x80 | mc, key, 0])))
        c = chans.get(ch, {})
        tracks.append((c.get("name") or c.get("plugin") or f"channel {ch}", evs))
    if len(tracks) == 1:
        raise ValueError("no notes on the requested channels")
    if moved:
        warnings.append(f"{moved} note(s) above MIDI's top key (127, G9) moved down to the highest octave that fits")
    midi_write(output, P, tracks)
    r = {"output": output, "channels": sorted(per), "notes": sum(len(v) for v in per.values()),
         "tempo_events": len(tempo_evs), "time_signatures": [f"{n}/{dd}" for _, n, dd in meters], "ppq": P}
    if warnings:
        r["warnings"] = warnings
    return r


def flp_tempo_map(path, limit=40):
    """The tempo FL will actually play: project tempo plus tempo events recorded in patterns (as placed)."""
    d = _load(path); ev = _events(d); P = _ppq(d)
    _, tm = _song(d, ev)
    step = max(1, len(tm) // int(limit))
    meters = _meter_map(d, ev)
    r = {"path": path, "ppq": P, "events": len(tm), "min_bpm": min(b for _, b in tm), "max_bpm": max(b for _, b in tm),
         "map": [{"bar": _tick_to_bar(t, meters, P), "bpm": b} for t, b in tm[::step]], "sampled_every": step}
    try:
        auto = _tempo_automation(d, ev, P)
    except Exception:
        auto = []
    if auto:
        r["tempo_automation_clips"] = len(auto)
        r["automation_note"] = "tempo automation read as 10-522 BPM over the clip's 0..1 range (not yet verified in FL)"
    return r


# ----------------------------------------------------------------------------- multi-pattern arrangements
def _clips(d, ev):
    """[(event index, record offset, record bytes)] of every clip in the current arrangement's playlist (what FL plays;
    other arrangements are read with _playlist_at(which=...))."""
    if isinstance(d, bytes) and len(ev) == len(_cached("events", d, _events_parse)):
        return list(_cached("clips", d, lambda d_: _clips_parse(d_, _events(d_))))
    return _clips_parse(d, ev)


def _clips_parse(d, ev, which=None):
    k, size, recs = _playlist_at(d, ev, which)
    return [(k, i * size, bytes(r)) for i, r in enumerate(recs) if struct.unpack("<H", r[4:6])[0] == PATTERN_BASE]


def _patterns(d, ev):
    """{pattern id: {"notes": [records], "ctrl": bytes, "name": str}} from the data groups (PatternNew + 223/224)."""
    if isinstance(d, bytes) and len(ev) == len(_cached("events", d, _events_parse)):
        pats = _cached("patterns", d, lambda d_: _patterns_parse(d_, _events(d_)))
        return {k: {"notes": list(v["notes"]), "ctrl": v["ctrl"], "name": v["name"]} for k, v in pats.items()}
    return _patterns_parse(d, ev)


def _patterns_parse(d, ev):
    pats = {}
    for kind, cur, a, b in _pattern_groups(d, ev):
        pats.setdefault(cur, {"notes": [], "ctrl": b"", "name": ""})
        for e in ev[a + 1:b]:
            if e["id"] == EV_NOTES and e["len"] % 24 == 0:
                p = _payload(d, e)
                pats[cur]["notes"] += [struct.unpack(NOTE_RECORD, p[i:i + 24]) for i in range(0, len(p), 24)]
            elif e["id"] == EV_PATTERN_CTRL:
                pats[cur]["ctrl"] += _payload(d, e)
            elif e["id"] == EV_PATTERN_NAME:
                pats[cur]["name"] = _text16(_payload(d, e))
    return pats


def _song(d, ev):
    """Every note and tempo event as the playlist plays them: (notes [(pos, len, channel, key, vel)], tempo map).
    _song_x has the same notes with their slide flag, pattern and FL record."""
    if isinstance(d, bytes) and len(ev) == len(_cached("events", d, _events_parse)):
        notes, tempos = _cached("song", d, lambda d_: _song_plain(_song_x(d_, _events(d_))))
        return list(notes), list(tempos)
    return _song_plain(_song_parse(d, ev))


def _song_plain(sx):
    notes, tempos = sx
    return [n[:5] for n in notes], tempos


def _song_x(d, ev):
    """(notes [(pos, len, channel, key, vel, slide, pattern id, FL note record)], tempo map) as the playlist plays them
    (sorted like _song's notes)."""
    if isinstance(d, bytes) and len(ev) == len(_cached("events", d, _events_parse)):
        notes, tempos = _cached("song_x", d, lambda d_: _song_parse(d_, _events(d_)))
        return list(notes), list(tempos)
    return _song_parse(d, ev)


def _song_x_all(d, ev):
    """_song_x with the notes of muted clips too (callers that edit what the patterns hold, heard or not)."""
    return _song_parse(d, ev, include_muted=True)


def _song_parse(d, ev, include_muted=False):
    """Notes and tempo as the playlist plays them: muted clips play nothing (include_muted=True keeps them)."""
    P = _ppq(d); pats = _patterns(d, ev); clips = _clips(d, ev)
    main = _sane_bpm(next((struct.unpack("<I", _payload(d, e))[0] / 1000 for e in ev if e["id"] == EV_TEMPO), None))
    main = main or 120.0
    notes, tempos = [], []
    for _, _, r in clips:
        pid = struct.unpack("<H", r[6:8])[0] - PATTERN_BASE
        pos, length = struct.unpack("<I", r[0:4])[0], struct.unpack("<I", r[8:12])[0]
        pat = pats.get(pid)
        if not pat or (not include_muted and struct.unpack("<H", r[18:20])[0] & CLIP_MUTE):
            continue
        start = _clip_offsets(r)[0]
        for n in pat["notes"]:
            if start <= n[0] < start + length:
                notes.append((pos + n[0] - start, min(n[3], start + length - n[0]), n[2], n[4], n[11],
                              bool(n[1] & NOTE_SLIDE), pid, n))
        for c in _ctrl_records(pat["ctrl"]):
            t = struct.unpack("<I", c[:4])[0]
            if (c[4], c[7]) == TEMPO_CTRL and start <= t < start + length:
                b = _sane_bpm(struct.unpack("<I", c[8:])[0] / 1000)
                if b:
                    tempos.append((pos + t - start, b))
    tempos.sort()
    if not tempos or tempos[0][0] > 0:
        tempos.insert(0, (0, main))
    try:
        auto = _tempo_automation(d, ev, P)
    except Exception:                                             # never let an odd clip break every reader
        auto = []
    if auto:
        spans = [(a, b) for a, b, _ in auto]
        inside = lambda t: any(a <= t < b for a, b in spans)
        tempos = sorted([x for x in tempos if not inside(x[0])] + [pt for _, _, pts in auto for pt in pts])
    notes.sort(key=lambda n: n[:6])
    return notes, tempos


TEMPO_LINK = (0x4000, 5)                                          # REC_Global_First item, REC_Tempo (FL API ids)
TEMPO_RANGE = (10.0, 522.0)                                       # FL's tempo knob: automation 0..1 -> 10..522 BPM


def _tempo_automation(d, ev, P):
    """Tempo automation clips as played: [(start tick, end tick, [(tick, bpm), ...])]. An automation clip whose remote
    link (event 227) targets FL's global tempo; values map linearly onto 10-522 BPM; sampled every 1/4 beat where
    it moves. PC-VERIFY: the link ids (dest 0x4000, param 5) and the 10-522 BPM mapping on a song that automates
    tempo (flp_tempo_map vs FL's tempo display)."""
    chans = set()
    for e in ev:
        if e["id"] == EV_REMOTE_LINK and e["len"] >= 12:
            p = _payload(d, e)
            ch, = struct.unpack("<H", p[2:4]); prm, dest = struct.unpack("<HH", p[8:12])
            if (dest, prm) == TEMPO_LINK:
                chans.add(ch)
    if not chans:
        return []
    pts_of = {}
    for ch, k in _automation_events(d, ev).items():
        if ch in chans:
            pts_of[ch] = _auto_points(_payload(d, ev[k]))[0]
    import bisect
    lo, hi = TEMPO_RANGE; out = []
    for _, _, r in _clips(d, ev):
        item, = struct.unpack("<H", r[6:8])
        if item >= PATTERN_BASE or item not in pts_of or struct.unpack("<H", r[18:20])[0] & CLIP_MUTE:
            continue
        pos, = struct.unpack("<I", r[0:4]); ln, = struct.unpack("<I", r[8:12])
        off, = struct.unpack("<f", r[24:28]); off = off * P if 0 < off < 1e9 else 0.0     # PC-VERIFY: offset in beats
        pts = [(b * P, lo + (hi - lo) * max(0.0, min(1.0, v))) for b, v, _t, _f in pts_of[item]
               if math.isfinite(b) and math.isfinite(v)]
        if not pts:
            continue

        def bpm_at(x):
            if x <= pts[0][0]:
                return round(pts[0][1], 3)
            if x >= pts[-1][0]:
                return round(pts[-1][1], 3)
            j = bisect.bisect_left([q[0] for q in pts], x)
            (x0, y0), (x1, y1) = pts[j - 1], pts[j]
            return round(y0 + (y1 - y0) * ((x - x0) / (x1 - x0) if x1 > x0 else 1.0), 3)
        # the tempo only moves between the first and the last point: sample that stretch (work bounded by the points,
        # not by the clip length - a clip millions of bars long must not hang the readers)
        step = max(1, P // 4)
        a = max(0, int((pts[0][0] - off) // step) * step); b = min(ln, int(pts[-1][0] - off) + step)
        if (b - a) // step > 200000:
            step = max(step, (b - a) // 200000)
        seg = [(pos, bpm_at(off))]
        t = a
        while t <= b:
            bpm = bpm_at(t + off)
            if abs(seg[-1][1] - bpm) >= 0.01:
                seg.append((pos + t, bpm))
            t += step
        out.append((pos, pos + ln, seg))
    return sorted(out)


def flp_tempo_write(project, output, midi=None, points=None, pattern="Tempo"):
    """Replace the song's tempo map in place: the tempo events in the pattern named `pattern` (the playlist's Tempo
    lane, made by flp_write_arrangement) come from a MIDI file's tempo track, or points [[bar, bpm], ...]. The
    project tempo becomes the first value. Notes, sounds and clips stay as they are. A song without that pattern
    gets one (with recorded tempo events) and a clip of it across the whole song on a free playlist track."""
    writable(output)
    d = _load(project); ev = _events(d); P = _ppq(d)
    try:
        bpb = _qbar(flp_project_info(project))
    except Exception:
        bpb = 4
    meters = _meter_map(d, ev)                                    # bars follow the time signature (and its markers)
    if midi:
        div, _, tm = midi_read(midi)
        if not tm:
            raise ValueError("that MIDI file has no tempo events")
        tmap = [(int(round(t * P / div)), float(b)) for t, b in tm]
    elif points:
        tmap = [(_bar_to_tick(float(b), meters, P), float(v)) for b, v in points]
    else:
        raise ValueError("give midi or points")
    tmap.sort()
    bad = [b for _, b in tmap if not 10 <= b <= 522]
    if bad or any(t < 0 for t, _ in tmap):                        # FL's tempo range; bar 1 is the song's start
        raise ValueError(f"tempo points must be 10-522 BPM at bar 1 or later (got {bad[:4] or 'a point before bar 1'})")
    created = None
    names = {pid_: v["name"] for pid_, v in _patterns(d, ev).items()}
    want = [i for i, n_ in names.items() if n_.strip().lower() == str(pattern).lower()]
    if not want:                                                  # no tempo lane yet: make the pattern + its clip
        d, pid = _add_pattern(d, pattern); ev = _events(d); created = {"pattern": pid}
    else:
        pid = want[0]
    def data_group():
        g = next((g for g in _pattern_groups(d, ev) if g[0] == "pattern_data" and g[1] == pid), None)
        return (g[2], next((k for k in range(g[2] + 1, g[3]) if ev[k]["id"] == EV_PATTERN_CTRL), None)) if g else (None, None)
    k_data, k_ctrl = data_group()
    if k_data is None:                                            # a name group only: give it a data group first
        d = _write_pattern_notes(d, ev, pid, []); ev = _events(d)
        k_data, k_ctrl = data_group()
    recs = [struct.pack("<I", t) + TEMPO_REC + struct.pack("<I", int(round(b * 1000))) for t, b in tmap]
    if k_ctrl is not None:
        keep = [r for r in _ctrl_records(_payload(d, ev[k_ctrl])) if (r[4], r[7]) != TEMPO_CTRL]
        allr = sorted(keep + recs, key=lambda r: struct.unpack("<I", r[:4])[0])
        edits = [(k_ctrl, k_ctrl + 1, _data_event(EV_PATTERN_CTRL, b"".join(allr)))]
    else:                                                         # recorded-controller event right after PatternNew
        edits = [(k_data + 1, k_data + 1, _data_event(EV_PATTERN_CTRL, b"".join(recs)))]
    stripped = 0
    for k, e in enumerate(ev):
        if e["id"] == EV_TEMPO:
            edits.append((k, k + 1, bytes([EV_TEMPO]) + struct.pack("<I", int(round(tmap[0][1] * 1000)))))
        elif created and e["id"] == EV_PATTERN_CTRL and k != k_ctrl and e["len"] % 12 == 0:
            # a new lane is the whole tempo map: tempo events recorded in other patterns (a MIDI import) would fight it
            rs = _ctrl_records(_payload(d, e)); keep = [r for r in rs if (r[4], r[7]) != TEMPO_CTRL]
            if len(keep) != len(rs):
                stripped += len(rs) - len(keep)
                edits.append((k, k + 1, _data_event(EV_PATTERN_CTRL, b"".join(keep))))
    d = _splice(d, ev, sorted(edits))
    if stripped:
        created["moved_tempo_events"] = stripped
    placed = any(struct.unpack("<H", r[6:8])[0] == PATTERN_BASE + pid for _, _, r in _clips(d, _events(d)))
    if not placed:                                                # the lane must be in the playlist to play
        ev = _events(d)
        notes_end = max((n[0] + n[1] for n in _song(d, ev)[0]), default=0)
        clips_end = max((struct.unpack("<I", r[0:4])[0] + struct.unpack("<I", r[8:12])[0] for _, _, r in _clips(d, ev)),
                        default=0)
        bar = int(round(bpb * P))
        end = max(notes_end, clips_end, tmap[-1][0] + P)
        _sane_span(end, P, "the song (its last clip or note)")
        track = _free_track(d)
        d = _place_pattern(d, pid, 0, -(-end // bar) * bar, track)
        created = dict(created or {}, clip_track=track, clip_bars=round(-(-end // bar), 2))
    _save(d, output)
    r = {"output": output, "pattern": pattern, "tempo_points": len(tmap),
         "bpm_range": [min(b for _, b in tmap), max(b for _, b in tmap)]}
    if created:
        r["created"] = created
    try:                                                          # a tempo AUTOMATION clip plays over the lane where
        ev = _events(d); auto = _tempo_automation(d, ev, P)       # it lies: FL keeps that older tempo there
        over = [(a, b) for a, b, _ in auto if a < tmap[-1][0] + P and b > tmap[0][0]]
        if over:
            bt = max(1, int(round(bpb * P)))
            r["WARNING"] = ("tempo automation clip(s) play over the written lane at bars "
                            + ", ".join(f"{a // bt + 1}-{-(-b // bt)}" for a, b in over[:4])
                            + ": FL plays the automation there, not these points. Remove or mute that clip "
                              "(flp_playlist) for the new tempo map to play")
    except Exception:                                             # noqa: BLE001 - a check only
        pass
    return r


def _all_patterns_empty(d, ev):
    """(pattern count, True if no pattern holds a note) - a project fresh from flh_new_song or FL's templates."""
    pats = _patterns(d, ev)
    return len(pats), all(not v["notes"] for v in pats.values())


def _set_markers(d, marks, P, bpb=None):
    """Replace the current arrangement's playlist markers (time-signature markers are kept) with marks [(bar, name)]
    (song bars, through the project's meter map - time-signature markers included; `bpb` is not used any more).
    Every marker of the arrangement is (re)written at _marker_slot (FL's place), time-signature ones first in their
    tick order - so markers an older version put before the playlist event move to where FL reads them."""
    ev = _events(d); meters = _meter_map(d, ev)
    a = _arrangement(d, ev, None)
    lo, hi = (a["first"] + 1, a["end"]) if a else (0, len(ev))
    slot = _marker_slot(d, ev, a, after_markers=False)
    if slot is None:
        return d, 0
    edits, keep, k = [], [], lo
    while k < hi:
        e = ev[k]
        if e["id"] == EV_MARKER_POS and e["len"] == 4:
            v, = struct.unpack("<I", _payload(d, e))
            j = _marker_group_end(ev, k, hi)
            if v & MARKER_SIGNATURE:
                keep.append((v & 0x07FFFFFF, b"".join(_raw(d, ev[i]) for i in range(k, j))))
            edits.append((k, j, b""))
            k = j
            continue
        k += 1
    new = b"".join(raw for _, raw in sorted(keep, key=lambda t: t[0]))
    for bar, name in marks:
        new += _marker_event(_bar_to_tick(float(bar), meters, P), name)
    edits.append((slot, slot, new))
    return _splice(d, ev, edits), len(marks)


def _writer_meter(d, ev, beats_per_bar):
    """(beats per bar, beats per bar to set as the time signature or None). Not given: the project's own meter
    (quarter beats per bar: 3/4 -> 3, 6/8 -> 3), nothing to set. Given: it, set when the project's bar differs."""
    num, den = _project_meter(d, ev); q = num * 4.0 / den
    if beats_per_bar in (None, "", 0):
        return (int(q) if q == int(q) else q), None
    bpb = int(beats_per_bar)
    return bpb, (None if abs(q - bpb) < 1e-9 else bpb)


def _overlaps(rows):
    """rows [(channel, start, length, key)] -> {channel: same-key notes that start before an earlier one ends}."""
    by, per = {}, {}
    for ch, st, ln, key in rows:
        by.setdefault((ch, key), []).append((st, st + ln))
    for (ch, _k), xs in by.items():
        end = None
        for a, b in sorted(xs):
            if end is not None and a < end:
                per[ch] = per.get(ch, 0) + 1
            end = b if end is None else max(end, b)
    return per


def _overlap_report(res, rows):
    per = _overlaps(rows)
    if per:
        res["same_key_overlaps"] = {str(c): n for c, n in sorted(per.items())}
        res["overlap_note"] = ("; ".join(f"{n} overlapping same-key note(s) on channel {c}" for c, n in sorted(per.items()))
                               + ": written as given, but one channel plays a key once at a time, so FL can cut or merge "
                               "them - listen, or remove the doubles (flp_edit_notes dedupe)")
    return res


def _write_into_fresh_song(template, output, parts, sections, tempo="auto", tail_bars=2, beats_per_bar=None):
    """flp_write_arrangement / flp_write_notes on a project whose patterns are all empty (flh_new_song's section
    blocks, FL templates): its pattern clips go, one named pattern per section is placed (all on playlist track 1:
    alternating tracks looked like empty sections once FL's playlist scrolled; a clip stretched over notes that ring
    past its section overlaps the next one on that track and both play), the notes go in with flp_replace_part
    (verified read-back), markers are rewritten from the sections, empty leftovers are removed. A MIDI tempo map with
    changes becomes a Tempo lane (flp_tempo_write) - the whole map, not just its first tempo."""
    global _EDIT_DEPTH
    import shutil
    writable(output)
    if os.path.normcase(os.path.abspath(template)) != os.path.normcase(os.path.abspath(output)):
        _save(_load(template), output)                            # through _save: an existing output is backed up first
    d = _load(output); P = _ppq(d)
    bpb, set_bpb = _writer_meter(d, _events(d), beats_per_bar)    # bars of the project's own meter unless asked
    if set_bpb:                                                   # before anything is laid out in bars
        flp_project_info(output, output, time_sig_num=set_bpb, time_sig_beat=4); d = _load(output)
    bar = int(round(bpb * P))
    tmap = None; notes_by = []; song_end = 0; warns = []
    for part in parts:
        ch = int(part["channel"])
        if part.get("notes") is not None:
            div, ns = _inline_notes_x(output, part["notes"], P)[:2]; tm = None
            ns = [n[:4] for n in ns]
        else:
            div, ns, tm = midi_read(part["midi"], warns)
        if tm and tmap is None:
            tmap = (tm, div)
        ticks = [(s0 * P // div, max(1, e0 * P // div - s0 * P // div), k, v) for s0, e0, k, v in ns]
        if ticks:
            song_end = max(song_end, max(t + l for t, l, _, _ in ticks))
        notes_by.append((ch, part, ticks))
    if not song_end:
        raise ValueError("no notes found in the parts")
    secs = sorted(sections, key=lambda x: float(x["bar"]))
    if not secs or float(secs[0]["bar"]) > 1:
        secs.insert(0, {"name": "Start", "bar": 1})
    starts = [int(round((float(x["bar"]) - 1) * bar)) for x in secs]
    ends = starts[1:] + [max(song_end, starts[-1] + bar)]
    _edit_enter()
    try:
        lst = flp_playlist(output, "list")
        ids = [c["id"] for c in lst.get("clips", []) if c.get("kind") == "pattern"]
        if ids:
            flp_playlist(output, "remove", output=output, clips=ids)
        layout = []
        for i, (sec, st, en) in enumerate(zip(secs, starts, ends)):
            has = any(st <= t < en for _, _, ts in notes_by for t, _, _, _ in ts)
            if not has:
                continue
            nm = str(sec.get("name") or f"Part {i + 1}")
            # PC-VERIFY: section clips on ONE playlist track, a ringing one overlapping the next: FL plays both (the
            # ringing tail is heard) and the playlist shows every section on track 1
            r = flp_new_pattern(output, nm, output=output, place_at_bar=1 + st / bar, length_bars=(en - st) / bar,
                                playlist_track=1)
            ring = max([t + l for _, _, ts in notes_by for t, l, _, _ in ts if st <= t < en] + [en])
            layout.append({"pattern": r["pattern"], "name": nm, "bar": round(1 + st / bar, 3),
                           "length_bars": round((-(-(ring - st) // P) * P) / bar, 2), "track": 1,
                           "_ring": ring > en})
        written = 0
        for ch, part, ts in notes_by:
            if not ts:
                continue
            arg = {"midi": part["midi"]} if part.get("notes") is None else {"notes": part["notes"]}
            r = flp_replace_part(output, output, ch, **arg)
            written += int(r.get("added", 0))
        lst = flp_playlist(output, "list")
        for L in layout:
            if L.pop("_ring"):
                ids = [c["id"] for c in lst.get("clips", []) if c.get("pattern") == L["pattern"]]
                if ids:
                    flp_playlist(output, "resize", output=output, clips=ids, length_bars=L["length_bars"])
        try:
            flp_pattern_tools(output, "remove_empty", output=output)
        except Exception:
            pass
    finally:
        _edit_exit()
    d = _load(output)
    d, nmark = _set_markers(d, [(L["bar"], L["name"]) for L in layout], _ppq(d), bpb)
    tempo_note = None; lane = None
    if tempo not in ("keep", None):
        if tempo != "auto":
            bpm = float(tempo)
        elif tmap and len(tmap[0]) == 1:
            bpm = float(tmap[0][0][1])
        else:
            bpm = None
            if tmap:                                              # the whole map: a Tempo lane, after the save
                lane = tmap; bpm = float(tmap[0][0][1])
        if bpm:
            ev = _events(d)
            ed = [(k, k + 1, bytes([EV_TEMPO]) + struct.pack("<I", int(round(bpm * 1000)))) for k, e in enumerate(ev)
                  if e["id"] == EV_TEMPO]
            if ed:
                d = _splice(d, ev, ed)
    _save(d, output)
    if lane:
        tm, tdiv = lane; dd = _load(output); ms = _meter_map(dd, _events(dd)); PP = _ppq(dd)
        pts = [[_tick_to_bar(t * PP / tdiv, ms, PP, None), b] for t, b in tm]
        try:
            tw = flp_tempo_write(output, output, points=pts)
            tempo_note = (f"the MIDI's tempo map ({len(tm)} points) is the song's Tempo lane (track "
                          f"{(tw.get('created') or {}).get('clip_track', '?')})")
        except ValueError as e:                                   # e.g. a tempo outside FL's 10-522 BPM
            tempo_note = f"only the MIDI's first tempo was set: its tempo map couldn't be a Tempo lane ({e})"
    total = max(int(round((L["bar"] - 1 + L["length_bars"]) * bar)) for L in layout)   # FL plays to the last clip
    try:
        import flh_store
        flh_store.journal_update(output, set={"sections": [{"name": L["name"], "bar": L["bar"],
                                                             "end_bar": round(L["bar"] + L["length_bars"], 3),
                                                             "pattern": L["pattern"]} for L in layout]})
    except Exception:
        pass
    res = {"output": output, "notes_written": written, "patterns": layout, "markers": nmark,
           "song_length_bars": round(total / bar, 2), "beats_per_bar": bpb,
           "note": "the project's empty section patterns were replaced by the written ones"}
    if tempo_note:
        res["tempo_note"] = tempo_note
    if warns:
        res["warnings"] = warns
    return _overlap_report(res, [(ch, t, l, k) for ch, _, ts in notes_by for t, l, k, _ in ts])


def flp_write_arrangement(template, output, parts, sections, tempo="auto", tail_bars=2, beats_per_bar=None):
    """Like flp_write_notes, but the song is split into one named pattern per section and laid out in the
    playlist (sections: [{"name": "Intro", "bar": 1}, ...]). Every section clip goes on playlist track 1 (a clip that
    rings past its section's end overlaps the next one; both play). A tempo map goes into its own "Tempo" pattern on
    track 3.
    Bars are bars of the template's time signature unless beats_per_bar is given (then the song gets that meter)."""
    writable(output)
    d = _load(template); ev = _events(d); P = _ppq(d)
    bpb, set_bpb = _writer_meter(d, ev, beats_per_bar); bar = int(round(bpb * P)); warns = []
    data_ks = [k for k, e in enumerate(ev) if e["id"] == EV_PATTERN_NEW]
    if len(data_ks) == 2:
        k_notes, old = _notes_event(d, ev)
    if len(data_ks) != 2:
        npat, empty = _all_patterns_empty(d, ev)
        if empty:                                                  # flh_new_song's empty section blocks
            return _write_into_fresh_song(template, output, parts, sections, tempo, tail_bars, beats_per_bar)
        held = [f"{v['name'] or pid} ({len(v['notes'])} notes)" for pid, v in _patterns(d, ev).items() if v["notes"]]
        raise ValueError(f"the template must have one pattern (or only empty ones): these hold notes: "
                         f"{', '.join(held[:8])}. To change one part of an arranged song use flp_replace_part")
    meta_k = data_ks[1]
    meta_end = next(g[3] for g in _pattern_groups(d, ev) if g[2] == meta_k)   # the group's real end (all settings)
    clip_k = _clip_event(d, ev); base_clip = bytearray(_payload(d, ev[clip_k]))
    midi_ch = {}
    for r in old:
        midi_ch.setdefault(r[2], r[9])
    recs = []; tmap = None; tdiv = None
    for part in parts:
        ch = int(part["channel"]); div, notes, tm = midi_read(part["midi"], warns)
        if tm and tmap is None:
            tmap, tdiv = tm, div
        for s0, e0, key, v in notes:
            ps = s0 * P // div; pl = max(1, e0 * P // div - ps)
            recs.append((ps, 16384, ch, pl, key, 0, 120, 0, 0, midi_ch.get(ch, 0), 64, v, 128, 128))
    if not recs:
        raise ValueError("no notes found in the MIDI files")
    secs = sorted(sections or [], key=lambda x: float(x["bar"]))
    secs = [x for i, x in enumerate(secs)                         # two sections at one bar: the later one names it
            if i + 1 == len(secs) or int(round((float(secs[i + 1]["bar"]) - 1) * bar)) != int(round((float(x["bar"]) - 1) * bar))]
    starts = [int(round((float(x["bar"]) - 1) * bar)) for x in secs]
    if not starts or starts[0] != 0:
        secs.insert(0, {"name": "Start", "bar": 1}); starts.insert(0, 0)
    song_end = max(r[0] + r[3] for r in recs)
    data, meta, clips = b"", b"", []
    color = next((_payload(d, e) for e in ev[meta_k:meta_end] if e["id"] == 150), None)
    def clip(pos, pid, length, track):
        r = bytearray(base_clip)
        r[0:4] = struct.pack("<I", pos); r[6:8] = struct.pack("<H", PATTERN_BASE + pid)
        r[8:12] = struct.pack("<I", length); r[24:28] = struct.pack("<I", 0); r[28:32] = struct.pack("<I", length)
        r[12:16] = struct.pack("<I", 500 - track)                # FL: playlist track n is 500 - n (n from 1)
        return bytes(r)
    layout = []
    for i, (sec, st) in enumerate(zip(secs, starts)):
        en = starts[i + 1] if i + 1 < len(starts) else max(song_end, st + bar)   # a last section after the notes
        mine = sorted([r for r in recs if st <= r[0] < en], key=lambda r: (r[0], r[2], r[4]))
        pid = i + 1
        rel = [(r[0] - st,) + r[1:] for r in mine]
        length = max([en - st] + [r[0] + r[3] for r in rel])
        length = -(-length // P) * P                              # whole beats
        data += struct.pack("<BH", EV_PATTERN_NEW, pid) + _data_event(EV_NOTES, b"".join(struct.pack(NOTE_RECORD, *r) for r in rel))
        meta += struct.pack("<BH", EV_PATTERN_NEW, pid) + _data_event(EV_PATTERN_NAME, (str(sec.get("name") or f"Part {pid}")).encode("utf-16-le") + b"\x00\x00")
        if color:
            meta += bytes([150]) + color
        clips.append(clip(st, pid, length, 1)); layout.append({"pattern": pid, "name": sec.get("name"), "bar": round(1 + st / bar, 3),
                                                              "length_bars": round(length / bar, 2), "notes": len(rel), "track": 1})
    if tempo != "keep":
        if tempo != "auto":
            tmap, tdiv = [(0, float(tempo))], P
    else:
        tmap = None
    edits = []
    if tmap:
        pid = len(secs) + 1
        ctrl = b"".join(struct.pack("<I", int(round(t * P / tdiv))) + TEMPO_REC + struct.pack("<I", int(round(b * 1000)))
                        for t, b in tmap)
        data += struct.pack("<BH", EV_PATTERN_NEW, pid) + _data_event(EV_PATTERN_CTRL, ctrl)
        meta += struct.pack("<BH", EV_PATTERN_NEW, pid) + _data_event(EV_PATTERN_NAME, "Tempo".encode("utf-16-le") + b"\x00\x00")
        end = max(song_end, int(round(tmap[-1][0] * P / tdiv)) + P)
        clips.append(clip(0, pid, -(-end // bar) * bar, 3))
        for k, e in enumerate(ev):
            if e["id"] == EV_TEMPO:
                edits.append((k, k + 1, bytes([EV_TEMPO]) + struct.pack("<I", int(round(tmap[0][1] * 1000)))))
    first = data_ks[0]; last = k_notes
    edits.append((first, last + 1, data))                          # old pattern 1 data group -> all patterns
    edits.append((meta_k, meta_end, meta))
    clips.sort(key=lambda r: struct.unpack("<I", r[:4])[0])
    edits.append((clip_k, clip_k + 1, _data_event(EV_PLAYLIST, b"".join(clips))))
    _save(_splice(d, ev, edits), output)
    if set_bpb:                                                    # FL's bar grid follows the project time signature
        flp_project_info(output, output, time_sig_num=set_bpb, time_sig_beat=4)
    total = max(struct.unpack("<I", c[0:4])[0] + struct.unpack("<I", c[8:12])[0] for c in clips)
    res = {"output": output, "notes_written": len(recs), "patterns": layout, "tempo_events": len(tmap) if tmap else 0,
           "song_length_bars": round(total / bar, 2), "beats_per_bar": bpb}
    if warns:
        res["warnings"] = warns
    return _overlap_report(res, [(r[2], r[0], r[3], r[4]) for r in recs])


def _pitch(x):
    """60, "C4" (= middle C, MIDI 60), "F#3", "Eb5" -> MIDI note number."""
    if isinstance(x, (int, float)):
        return int(x)
    m_ = re.fullmatch(r"\s*([A-Ga-g])([#b]?)(-?\d+)\s*", str(x))
    if not m_:
        raise ValueError(f"note '{x}': use a number or a name like C4 (middle C), F#3, Eb5")
    return 12 * (int(m_.group(3)) + 1) + {"C": 0, "D": 2, "E": 4, "F": 5, "G": 7, "A": 9, "B": 11}[m_.group(1).upper()] \
        + {"#": 1, "b": -1, "": 0}[m_.group(2)]


def _inline_notes(project, notes, P):
    """notes as [bar, length_bars, pitch, velocity] or {bar, len|length_bars, key|pitch|note, vel} in song bars (the
    project's time signature, bar 1 = start) -> (div, [(start, end, key, vel)])."""
    div, out = _inline_notes_x(project, notes, P)
    return div, [n[:4] for n in out]


def _inline_notes_x(project, notes, P):
    """_inline_notes with the slide mark kept: (div, [(start, end, key, vel, slide, fl)]). A 5th list item
    ({'slide': true}, true or 'slide') or a dict's slide: true makes it an FL slide note. A dict 5th item (or a note
    dict) may also carry "fl": FL's other note fields [flags, group, fine pitch, x7, release, midi channel, pan, mod X,
    mod Y] (what flp_perform passes so a rewritten part keeps them), and a note dict may give exact song ticks
    ("tick", "ticks") instead of bars."""
    try:                                                          # song bars follow the time signature (markers too)
        d_ = _load(project); meters = _meter_map(d_, _events(d_))
        if _ppq(d_) != P:
            meters = [(int(round(t * P / _ppq(d_))), nu, de) for t, nu, de in meters]
    except Exception:
        meters = [(0, 4, 4)]
    tick = lambda b_: _bar_to_tick(float(b_), meters, P)
    out = []
    for n in notes:
        fl = None
        if isinstance(n, dict):
            key, vel = n.get("key", n.get("pitch", n.get("note"))), n.get("vel", n.get("velocity", 90))
            sl = bool(n.get("slide")); fl = n.get("fl")
            if n.get("tick") is not None:
                s0 = int(n["tick"]); e0 = s0 + int(n.get("ticks") or 1)
            else:
                bar, ln = n["bar"], n.get("len", n.get("length_bars"))
                s0 = tick(bar); e0 = tick(float(bar) + float(ln))
        else:
            bar, ln, key, vel, extra = (list(n) + [90, None])[:5] if len(n) < 5 else list(n)[:5]
            sl = _is_slide(extra); fl = extra.get("fl") if isinstance(extra, dict) else None
            s0 = tick(bar); e0 = tick(float(bar) + float(ln))
        if fl is not None:
            fl = tuple(int(x) for x in fl)
            if len(fl) != 9:
                raise ValueError("a note's fl fields are [flags, group, fine, x7, release, midi_ch, pan, mod_x, mod_y]")
        out.append((max(0, s0), max(max(0, s0) + 1, e0), _pitch(key), max(1, min(128, int(vel))), sl, fl))
    return P, sorted(out, key=lambda x: x[:5])


def _note_record(pos, length, ch, key, vel, slide, fl, midi_ch):
    """A new FL note record: FL's defaults, or the fields `fl` carries over from the note it replaces."""
    if fl:
        flags, group, fine, x7, rel, mch, pan, mx, my = fl
        flags = (flags & ~NOTE_SLIDE) | (NOTE_SLIDE if slide else 0)
        return (pos, flags, ch, length, key, group, fine, x7, rel, mch, pan, vel, mx, my)
    return (pos, NOTE_FLAGS_DEFAULT | (NOTE_SLIDE if slide else 0), ch, length, key, 0, 120, 0, 0, midi_ch, 64, vel,
            128, 128)


def _fl_fields(r):
    """The fields of an FL note record that _note_record's `fl` carries: [flags, group, fine, x7, release, midi_ch,
    pan, mod_x, mod_y]."""
    return [r[1], r[5], r[6], r[7], r[8], r[9], r[10], r[12], r[13]]


REPLACE_INTO = ("auto", "covering_clip")
REPLACE_HIDDEN = ("remove", "keep")


def _tempo_lane_pids(pats):
    """Patterns that are a tempo lane (recorded tempo events, no notes): never a home for a part's notes."""
    return {pid for pid, v in pats.items() if not v["notes"] and v.get("ctrl")
            and any((c[4], c[7]) == TEMPO_CTRL for c in _ctrl_records(v["ctrl"]))}


def flp_replace_part(project, output, channel, midi=None, notes=None, pattern=None, into="auto", hidden="remove"):
    """Swap one channel's notes in an arranged song (several patterns laid out in the playlist). Each new note (a MIDI
    file in song time, or `notes` inline as [bar, length_bars, pitch, vel(, {"slide": true})]) goes into the clip that
    covers it whose pattern already holds this channel's notes there (or the clip of `pattern`, the section the
    caller targets); never just "some clip at that bar". A section clip whose pattern doesn't hold the channel yet
    takes the notes when it's the only clip there (a tempo lane never counts); into="covering_clip" also settles
    stacked clips that don't hold the channel: the latest-starting playing clip there gets them (no placeholder notes
    needed). The channel's old notes go from the patterns the playlist plays; hidden="remove" (default) also drops the
    channel's notes no clip plays any more (past a shortened clip's end), "keep" leaves them. Notes a hair (up to a
    32nd) before the clip that holds the part start with it, silently; only grace notes that end before it are
    reported. A pattern placed several times (a repeated chorus) holds one copy: notes that differ between its
    repeats can't all be kept, and the result says where. The written song is read back and compared before saving."""
    writable(output)
    if (midi is None) == (notes is None):
        raise ValueError("give either midi (a .mid file) or notes ([bar, length_bars, pitch, vel], ...)")
    into = str(into or "auto").strip().lower().replace("-", "_")
    if into not in REPLACE_INTO:
        raise ValueError(f"into: {' | '.join(REPLACE_INTO)}")
    hidden = str(hidden or "remove").strip().lower()
    if hidden not in REPLACE_HIDDEN:
        raise ValueError(f"hidden: {' | '.join(REPLACE_HIDDEN)}")
    d = _load(project); ev = _events(d); P = _ppq(d); ch = int(channel)
    pats = _patterns(d, ev); note_ks = _pattern_note_events(d, ev)
    lanes = _tempo_lane_pids(pats)
    spans = []                                                    # (pos, end, pattern, window start, muted)
    for _, _, r in _clips(d, ev):
        item, = struct.unpack("<H", r[6:8])
        if item < PATTERN_BASE or item - PATTERN_BASE not in pats or item - PATTERN_BASE in lanes:
            continue
        pos, = struct.unpack("<I", r[0:4]); ln, = struct.unpack("<I", r[8:12]); s0, _ = _clip_offsets(r)
        spans.append((pos, pos + ln, item - PATTERN_BASE, s0, bool(struct.unpack("<H", r[18:20])[0] & CLIP_MUTE)))
    spans.sort()
    if not spans:
        raise ValueError("no pattern clips found in the playlist")
    import bisect
    want_pid = _pattern_id(d, ev, pattern) if pattern is not None else None
    mine = {pid: sorted(r[0] for r in v["notes"] if r[2] == ch) for pid, v in pats.items()}
    chs_of = {pid: {r[2] for r in v["notes"]} - {ch} for pid, v in pats.items()}
    partners = set().union(*[chs_of[pid] for pid, xs in mine.items() if xs]) if any(mine.values()) else set()
    midi_ch = next((r[9] for v in pats.values() for r in v["notes"] if r[2] == ch), 0)
    windows, by_pid = {}, {}
    for sp in spans:
        windows.setdefault(sp[2], []).append((sp[3], sp[3] + sp[1] - sp[0])); by_pid.setdefault(sp[2], []).append(sp)
    inside_of = {}
    LONG = 64 * 4 * P                                             # clips longer than this are checked for every note
    EARLY = max(1, P // 8)                                        # "a hair early": up to a 32nd note
    longs = [sp for sp in spans if sp[1] - sp[0] > LONG]
    shorts = [sp for sp in spans if sp[1] - sp[0] <= LONG]; starts = [sp[0] for sp in shorts]

    def holds(sp, off):
        """How well clip sp's pattern holds this channel near pattern offset off (lower = better)."""
        xs = mine.get(sp[2]) or []
        if sp not in inside_of:
            lo, hi = bisect.bisect_left(xs, sp[3]), bisect.bisect_left(xs, sp[3] + sp[1] - sp[0])
            inside_of[sp] = xs[lo:hi]
        inside = inside_of[sp]
        if inside:
            j = bisect.bisect_left(inside, off)
            near = min(abs(inside[i] - off) for i in (j - 1, j) if 0 <= i < len(inside))
            return (0, near)
        return (1, 0) if xs else None

    from collections import Counter as _Counter
    mine_k = {pid: _Counter((r[0], r[4]) for r in v["notes"] if r[2] == ch) for pid, v in pats.items()}
    mine_v = {pid: {(r[0], r[4], r[11]) for r in v["notes"] if r[2] == ch} for pid, v in pats.items()}
    taken = _Counter()                                            # (pid, clip start, offset, key) already matched

    def is_repeat(sp, po):
        return any(x[0] < sp[0] and x[3] <= po < x[3] + x[1] - x[0] for x in by_pid[sp[2]])

    def pick(ps, key=None, vel=None, ln=None):
        lo = bisect.bisect_left(starts, ps - LONG); hi = bisect.bisect_right(starts, ps)
        cover = [sp for sp in shorts[lo:hi] + longs if sp[0] <= ps < sp[1]]
        if key is not None and want_pid is None and len(cover) > 1:
            # a clip whose pattern holds this very note (offset, key) of this channel first: layered patterns of one
            # channel (a section 808 and a fill at the same bars) keep their own notes; a pattern's first play
            # before its repeats; each held note matched once
            ex = [sp for sp in cover if mine_k.get(sp[2], {}).get((ps - sp[0] + sp[3], key))]
            if ex:
                def rank(sp):
                    po = ps - sp[0] + sp[3]
                    return (taken[(sp[2], sp[0], po, key)] >= mine_k[sp[2]][(po, key)],
                            (po, key, vel) not in mine_v[sp[2]], is_repeat(sp, po), sp[4], -sp[0], sp[2])
                best = min(ex, key=rank)
                taken[(best[2], best[0], ps - best[0] + best[3], key)] += 1
                return best, None
        if not cover:
            soon = [sp for sp in shorts[hi:bisect.bisect_right(starts, ps + EARLY)] if ps < sp[0] <= ps + EARLY
                    and holds(sp, sp[3]) is not None and holds(sp, sp[3])[0] == 0]
            if soon:
                return min(soon, key=lambda sp: (sp[4], sp[0], sp[2])), "early"
            return None, "outside"
        if want_pid is not None:
            hit = [sp for sp in cover if sp[2] == want_pid]
            if hit:
                return max(hit, key=lambda sp: sp[0]), None
        scored = [(holds(sp, ps - sp[0] + sp[3]), sp) for sp in cover]
        owned = [(h, sp) for h, sp in scored if h is not None and h[0] == 0]
        # a note nudged a hair before the next clip that holds its part (humanized timing at a section start) belongs
        # to that clip's first tick when the part's notes there are closer in time than in the clip it falls in
        soon = []
        for sp in shorts[hi:bisect.bisect_right(starts, ps + EARLY)] + longs:
            h = holds(sp, sp[3]) if ps < sp[0] <= ps + EARLY else None
            if h is not None and h[0] == 0:
                soon.append(((0, h[1] + sp[0] - ps), sp))
        best = min(owned, key=lambda x: (x[0], x[1][4], -x[1][0], x[1][2])) if owned else None
        if soon:
            nxt = min(soon, key=lambda x: (x[0], x[1][4], x[1][0], x[1][2]))
            grace = ln is not None and ps + ln <= nxt[1][0]       # over before the next clip starts: a grace
            if best is None or (nxt[0] < best[0] and not grace):  # note the clip it falls in plays as written
                return nxt[1], "early"
        if best is not None:                                      # the pattern(s) that already hold this part there
            return best[1], None
        owned = [(h, sp) for h, sp in scored if h is not None]
        if owned:
            return min(owned, key=lambda x: (x[0], x[1][4], -x[1][0], x[1][2]))[1], None
        if len(cover) == 1:
            return cover[0], None
        free = [sp for sp in cover if not pats[sp[2]]["notes"]]   # an empty pattern laid out for this part
        if len(free) == 1:
            return free[0], None
        # the layer this part belongs to: the covering pattern that shares the most channels with the patterns that
        # hold this part elsewhere (a hi-hat goes with the kick and snare, as in its other sections)
        score = sorted(((len(chs_of[sp[2]] & partners), sp) for sp in cover), key=lambda x: (-x[0], -x[1][0]))
        if score and score[0][0] and (len(score) == 1 or score[1][0] < score[0][0]):
            return score[0][1], None
        if into == "covering_clip":                               # the caller's rule: the clip that covers it
            return min(cover, key=lambda sp: (sp[4], -sp[0], sp[2])), None    # playing first, then the latest
        return None, "ambiguous"

    div, new_notes = _inline_notes_x(project, notes, P) if notes is not None else midi_read(midi)[:2]
    per = {}; unplaced = 0; ambiguous = []; slides = 0; repeats = {}; differs = []; meters = _meter_map(d, ev); nudged = 0
    graces = []; asked = []                                       # asked: where each note was meant to sound
    written = {}                                                  # pattern -> {(offset, key)} written so far
    resolved = []
    for nn in new_notes:
        s0, e0, key, v = nn[:4]; sl = len(nn) > 4 and nn[4]; fl = nn[5] if len(nn) > 5 else None
        ps = s0 * P // div; pl_ = max(1, e0 * P // div - ps)
        sp, why = pick(ps, key, v, pl_)
        if sp is None:
            if why == "outside":
                unplaced += 1; asked.append((ps, key))
            else:
                ambiguous.append(round(_tick_to_bar(ps, meters, P), 2))
            continue
        resolved.append((why == "early", ps, pl_, key, v, sl, fl, sp))
    resolved.sort(key=lambda x: (x[0], x[1]))                     # notes moved to a clip start go last: never doubled
    for early, ps, pl_, key, v, sl, fl, sp in resolved:
        st, en, p_, off, _m = sp
        if early:                                                 # starts with its clip (moved by under a 32nd:
            if ps + pl_ <= st:                                    # humanized timing, said nowhere); a grace note
                graces.append(round(_tick_to_bar(ps, meters, P), 2))   # that ends before the clip is said
            pl_ = max(1, pl_ - (st - ps)); ps = st
            if (off, key) in written.get(p_, set()):
                continue                                          # the clip already starts with this note
            nudged += 1
        asked.append((ps, key))
        po = ps - st + off
        earlier = [x for x in by_pid[p_] if x[0] < st and x[3] <= po < x[3] + x[1] - x[0]]
        if earlier:                                               # a repeat of a stretch an earlier clip already plays
            repeats.setdefault(p_, set()).add(st)
            if (po, key) not in written.get(p_, set()):
                differs.append(round(_tick_to_bar(ps, meters, P), 2))
            continue
        slides += bool(sl)
        written.setdefault(p_, set()).add((po, key))
        per.setdefault(p_, []).append(_note_record(po, pl_, ch, key, v, sl, fl, midi_ch))
    if ambiguous:
        raise ValueError(f"channel {ch} has no notes in the clips at bar(s) {ambiguous[:6]} and several patterns start "
                         "there; say which pattern the new notes go to (pattern=...), or into='covering_clip' (the "
                         "latest-starting clip there takes them)")
    played = {}                                                   # windows other arrangements play (kept)
    for a_ in _arrangements(d, ev):
        if a_["current"]:
            continue
        for r in _playlist_at(d, ev, a_["index"])[2]:
            item, = struct.unpack("<H", bytes(r[6:8]))
            if item >= PATTERN_BASE:
                s0_, _ = _clip_offsets(r)
                played.setdefault(item - PATTERN_BASE, []).append((s0_, s0_ + struct.unpack("<I", bytes(r[8:12]))[0]))
    for p_ in per:                                                # a target pattern without a notes event gets one
        if not note_ks.get(p_):
            d = _write_pattern_notes(d, ev, p_, []); ev = _events(d); note_ks = _pattern_note_events(d, ev)
    edits, removed, added, stale = [], 0, 0, 0
    for p_ in sorted({sp[2] for sp in spans} | set(per)):
        old = pats.get(p_, {"notes": []})["notes"]
        keep = [r for r in old if not (r[2] == ch and any(a <= r[0] < b for a, b in windows.get(p_, [])))]
        if hidden == "remove" and p_ in windows:                  # what no clip plays any more (a clip shortened
            kept_ = [r for r in keep if r[2] != ch                # after its notes): junk that would come back
                     or any(a <= r[0] < b for a, b in played.get(p_, []))]    # when the clip is lengthened
            stale += len(keep) - len(kept_); keep = kept_
        gone = len(old) - len(keep)                               # the old part (+ its hidden rest)
        if not gone and not per.get(p_):
            continue
        removed += gone; added += len(per.get(p_, []))
        recs = sorted(keep + per.get(p_, []), key=lambda r: (r[0], r[2], r[4]))
        edits += _notes_event_edits(ev, note_ks[p_], b"".join(struct.pack(NOTE_RECORD, *r) for r in recs))
    new_d = _splice(d, ev, edits)
    # read back: the other channels play exactly as before; this channel plays what was asked (where it can)
    before, _ = _song(d, ev); after, _ = _song(new_d, _events(new_d))
    if sorted(n for n in before if n[2] != ch) != sorted(n for n in after if n[2] != ch):
        raise RuntimeError("flp_replace_part would have changed other channels' notes, so nothing was written "
                           "(please report this project)")
    got = sorted((n[0], n[3]) for n in after if n[2] == ch)
    final = _patterns(new_d, _events(new_d))                      # what each clip must now play of this channel
    expect = sorted((sp[0] + r[0] - sp[3], r[4]) for sp in spans for r in final.get(sp[2], {"notes": []})["notes"]
                    if r[2] == ch and not sp[4] and sp[3] <= r[0] < sp[3] + sp[1] - sp[0])   # muted clips play nothing
    if got != expect:
        raise RuntimeError("flp_replace_part's read-back didn't match what it wrote, so nothing was saved "
                           f"({len(_multiset_minus(expect, got))} notes missing); please report this project")
    want = sorted(asked)                                          # (a note a hair early: where its clip starts)
    missing = len(_multiset_minus(want, got)); extra = len(_multiset_minus(got, want))
    _save(new_d, output)
    res = {"output": output, "channel": ch, "removed": removed, "added": added, "outside_clips": unplaced,
           "patterns": len(per), "verified": {"read_back": True, "other_channels_unchanged": True,
                                              "notes_heard": len(got), "asked_not_heard": missing,
                                              "heard_not_asked": extra}}
    if slides:
        res["slides"] = slides
    if stale:
        res["hidden_removed"] = stale                             # old notes of this channel no clip played
    if graces:                                                    # jitter is clamped silently; a grace note that
        res["grace_notes_moved"] = len(graces)                    # ends before its clip changes the music: said
        res["grace_note_bars"] = sorted(set(graces))[:12]
        res["grace_note"] = ("short note(s) just before a section clip (grace notes) were moved onto the clip's first "
                             "tick (1 tick long): lengthen the previous clip to keep them before the downbeat")
    if repeats:
        res["repeated_patterns"] = {pats[p_]["name"] or f"pattern {p_}": len(v) + 1 for p_, v in repeats.items()}
        res["note"] = ("the part spans repeated clips of the same pattern: each pattern holds one copy, so its repeats "
                       "play what its first clip plays")
    if differs:
        res["in_repeated_patterns_skipped"] = len(differs)
        res["differs_in_repeats_at_bars"] = sorted(set(differs))[:12]
        res["note"] = ("the new part differs between repeats of the same pattern; those notes were left out (make "
                       "the pattern unique with flp_pattern_tools clone, then place the copy, to keep them)")
    return res


def _multiset_minus(a, b):
    from collections import Counter
    c = Counter(a); c.subtract(Counter(b))
    return [k for k, v in c.items() for _ in range(max(0, v))]


def flp_style_channels(project, output, channels):
    """Set channel colors, icons and names in a project file (works with FL closed).
    channels: [{"channel": 0, "color": "#4A80D8", "icon": 12, "name": "Melody"}]"""
    writable(output)
    d = _load(project); ev = _events(d)
    spans = {i: (a, b) for kind, i, a, b in _blocks(d, ev) if kind == "channel"}
    edits, done = [], []
    merged = {}                                                   # one channel listed twice (name, then color):
    for spec in channels:                                         # one spec, the later value wins - two edits of
        merged.setdefault(int(spec["channel"]), {}).update(       # one event wrote it twice
            {k: v for k, v in spec.items() if v is not None})
    for spec in merged.values():
        ch = int(spec["channel"])
        if ch not in spans:
            raise ValueError(f"no channel {ch}")
        k0, k1 = spans[ch]                                        # the channel's own block: ChannelNew .. its event 51
        found = {}
        for k in range(k0, k1):
            eid = ev[k]["id"]
            if eid in (EV_CHANNEL_COLOR, EV_CHANNEL_ICON, EV_DISPLAY_NAME) and eid not in found:
                found[eid] = k
        # FL leaves out events that hold defaults (an unnamed channel has no 203): a missing one goes into the block
        # where FL writes it - after the plugin header (212) / plugin name (201) / type (21). PC-VERIFY in FL.
        after = next((k for k in range(k0, k1) if ev[k]["id"] == EV_PLUGIN_HEADER), None)
        if after is None:
            after = next((k for k in range(k0, k1) if ev[k]["id"] == EV_PLUGIN_NAME), None)
        if after is None:
            after = next((k for k in range(k0, k1) if ev[k]["id"] == 21), k0)
        ins = []
        if spec.get("name") is not None:
            new = _data_event(EV_DISPLAY_NAME, str(spec["name"]).encode("utf-16-le") + b"\x00\x00")
            if EV_DISPLAY_NAME in found:
                k = found[EV_DISPLAY_NAME]; edits.append((k, k + 1, new))
            else:
                ins.append(new)
        if spec.get("icon") is not None:
            new = bytes([EV_CHANNEL_ICON]) + struct.pack("<I", int(spec["icon"]))
            if EV_CHANNEL_ICON in found:
                k = found[EV_CHANNEL_ICON]; edits.append((k, k + 1, new))
            else:
                ins.append(new)
        if spec.get("color") is not None:
            c = _hexcolor(spec["color"]); r, g, b = int(c[1:3], 16), int(c[3:5], 16), int(c[5:7], 16)
            new = bytes([EV_CHANNEL_COLOR]) + struct.pack("<I", r | g << 8 | b << 16)
            if EV_CHANNEL_COLOR in found:
                k = found[EV_CHANNEL_COLOR]; edits.append((k, k + 1, new))
            else:
                ins.append(new)
        if ins:
            edits.append((after + 1, after + 1, b"".join(ins)))
        done.append(ch)
    _save(_splice(d, ev, edits), output)
    return {"output": output, "styled_channels": done}


# fader position (FL's 0..1, stored x16000) <-> dB. FL's curve: amplitude = (20^v - 1) / (20^0.8 - 1) (0.8 = 0 dB,
# 1.0 = +5.59 dB, 0 = -inf). FADER_DB holds the points FL's own read-back gave (older FL); the formula meets every one
# within 0.01 dB (tests/test_fader_fl26.py). The bridge script (v7) uses the same curve.
FADER_DB = [(0.0, -150.0), (0.003375, -60.0), (0.0318, -40.0), (0.0916, -30.0), (0.16325, -24.0), (0.271875, -18.0),
            (0.340875, -15.0), (0.419125, -12.0), (0.5053, -9.0), (0.6472, -4.5), (0.697, -3.0), (0.731, -2.0),
            (0.7653, -1.0), (0.8, 0.0), (0.8351, 1.0), (0.9063, 3.0), (0.9786, 5.0), (1.0, 5.6)]
_FADER_B = 20.0
_FADER_UNITY = _FADER_B ** 0.8 - 1.0
FADER_FLOOR_DB = -150.0           # what a fader at 0 reads as (dB math needs a number; FL shows -inf)
FADER_TOP_EXACT_DB = 20 * math.log10((_FADER_B - 1.0) / _FADER_UNITY)   # +5.5876


def _fader(db):
    """dB -> FL mixer fader position 0..1 (exact curve; above the top -> 1.0, -150 dB or less -> 0)."""
    db = float(db)
    if db <= FADER_FLOOR_DB:
        return 0.0
    v = math.log(1.0 + _FADER_UNITY * 10 ** (min(db, FADER_TOP_EXACT_DB) / 20.0)) / math.log(_FADER_B)
    return max(0.0, min(1.0, v))


def _fader_db(v):
    """FL mixer fader position 0..1 -> dB (exact curve; 0 -> FADER_FLOOR_DB)."""
    v = float(v)
    if v <= 0:
        return FADER_FLOOR_DB
    return max(FADER_FLOOR_DB, 20 * math.log10((_FADER_B ** min(1.0, v) - 1.0) / _FADER_UNITY))


# channel volume knob 0..1 <-> dB on FL's channel scale (FL's utils.VolTodB: amplitude = (11^v - 1) / 10): 1.0 = 0 dB,
# FL's default 0.78125 (78 %) = -5.18 dB. PC 2026-10-23: volume_db=-6 landed on 0.748 = exactly -6.00 on this scale.
CHAN_DEFAULT = 0.78125


def _chan_vol(db):
    db = float(db)
    if db <= FADER_FLOOR_DB:
        return 0.0
    return max(0.0, min(1.0, math.log(1.0 + 10.0 * 10 ** (min(db, 0.0) / 20.0)) / math.log(11.0)))


def _chan_db(v):
    v = float(v)
    if v <= 0:
        return FADER_FLOOR_DB
    return max(FADER_FLOOR_DB, 20 * math.log10((11.0 ** min(1.0, v) - 1.0) / 10.0))


def flp_mixer(project, output, tracks):
    """Mixer settings in the project file (FL closed, or for a project that isn't open):
    tracks: [{track, name, color, volume_db, pan (-1..1), route_to: [tracks], unroute: [tracks]}]"""
    writable(output)
    d = _load(project)
    for spec in tracks:
        ev = _events(d); t = int(spec["track"])
        tr = [k for k, e in enumerate(ev) if e["id"] == EV_MIXER_TRACK]
        if not 0 <= t < len(tr):
            raise ValueError(f"no mixer track {t}")
        edits = []
        k236 = tr[t]; end = tr[t + 1] if t + 1 < len(tr) else len(ev)
        if spec.get("name") is not None or spec.get("color") is not None:
            a = k236
            while a > 0 and ev[a - 1]["id"] in (EV_MIXER_COLOR, EV_MIXER_HASPROPS, EV_MIXER_NAME):
                a -= 1
            old = {ev[k]["id"]: _payload(d, ev[k]) for k in range(a, k236)}
            color = old.get(EV_MIXER_COLOR); name = old.get(EV_MIXER_NAME)
            if spec.get("color") is not None:
                c = _hexcolor(spec["color"]); color = bytes([int(c[1:3], 16), int(c[3:5], 16), int(c[5:7], 16), 255])
            if spec.get("name") is not None:
                name = str(spec["name"]).encode("utf-16-le") + b"\x00\x00"
            new = b""
            if color:
                new += bytes([EV_MIXER_COLOR]) + color
            new += bytes([EV_MIXER_HASPROPS, 1])
            if name:
                new += _data_event(EV_MIXER_NAME, name)
            edits.append((a, k236, new))
        if spec.get("route_to") or spec.get("unroute"):
            kr = next((k for k in range(k236, end) if ev[k]["id"] == EV_MIXER_ROUTE), None)
            if kr is None:
                raise ValueError(f"track {t} has no routing event")
            r = bytearray(_payload(d, ev[kr]))
            for dst in spec.get("route_to") or []:
                dst = int(dst)
                if dst == t:
                    raise ValueError("a track can't route to itself")
                if len(r) <= dst:
                    r += bytes(dst + 1 - len(r))
                r[dst] = 1
            for dst in spec.get("unroute") or []:
                if int(dst) < len(r):
                    r[int(dst)] = 0
            edits.append((kr, kr + 1, _data_event(EV_MIXER_ROUTE, bytes(r))))
        if spec.get("volume_db") is not None or spec.get("pan") is not None:
            kp = next(k for k, e in enumerate(ev) if e["id"] == EV_MIXER_PARAMS)
            p = bytearray(_payload(d, ev[kp])); code = 0x7000 + (t << 6); hit = set()
            for i in range(0, len(p) - 11, 12):
                if struct.unpack("<H", p[i + 6:i + 8])[0] != code:
                    continue
                if p[i + 4] == MIX_VOLUME and spec.get("volume_db") is not None:
                    struct.pack_into("<i", p, i + 8, int(round(_fader(spec["volume_db"]) * 16000))); hit.add("v")
                if p[i + 4] == MIX_PAN and spec.get("pan") is not None:
                    struct.pack_into("<i", p, i + 8, int(round(max(-1.0, min(1.0, float(spec["pan"]))) * PAN_SCALE))); hit.add("p")
            miss = [w for w, k_ in (("volume", "volume_db"), ("pan", "pan")) if spec.get(k_) is not None
                    and w[0] not in hit]
            if miss:                                              # never report a setting that wasn't written
                raise ValueError(f"mixer track {t} has no {' / '.join(miss)} value in this project's file to change")
            edits.append((kp, kp + 1, _data_event(EV_MIXER_PARAMS, bytes(p))))
        d = _splice(d, ev, sorted(edits, key=lambda x: x[0]))
    _save(d, output)
    return {"output": output, "tracks": [int(x["track"]) for x in tracks]}


PAN_SCALE = 6400


# ----------------------------------------------------------------------------- automation and audio clips
def _raw_events(buf):
    """Parse a bare event stream (no header) -> [(id, payload, raw bytes)]."""
    i, out = 0, []
    while i < len(buf):
        o = i; eid = buf[i]; i += 1
        if eid in EV_SIZE_EXCEPTIONS:
            n, ps = EV_SIZE_EXCEPTIONS[eid], i
        elif eid < 64:
            n, ps = 1, i
        elif eid < 128:
            n, ps = 2, i
        elif eid < 192:
            n, ps = 4, i
        else:
            n, ps = _varint(buf, i)
        i = ps + n
        out.append((eid, buf[ps:i], buf[o:i]))
    return out


def _new_channel(d, block, name, replace=None):
    """Append a channel (block = its events after ChannelNew) after the last channel. -> (data, new index)."""
    ev = _events(d)
    starts = [k for k, e in enumerate(ev) if e["id"] == EV_CHANNEL]
    if not starts:
        raise ValueError("project has no channels")
    new_index = max(struct.unpack("<H", _payload(d, ev[k]))[0] for k in starts) + 1
    spans = [(a, b) for kind, i, a, b in _blocks(d, ev) if kind == "channel"]
    if not spans:
        raise ValueError("couldn't find the end of the last channel")
    j = max(b for _, b in spans) - 1                              # its 51, or its last event (FL's empty template)
    out = b""
    for eid, p, raw in _raw_events(block):
        if eid == EV_DISPLAY_NAME:
            out += _data_event(eid, str(name).encode("utf-16-le") + b"\x00\x00")
        elif replace and eid in replace:
            out += replace[eid]
        else:
            out += raw
    new = bytearray(_splice(d, ev, [(j + 1, j + 1, bytes([EV_CHANNEL]) + struct.pack("<H", new_index) + out)]))
    fmt, nch, ppq = struct.unpack("<hHH", new[8:14]); new[8:14] = struct.pack("<hHH", fmt, nch + 1, ppq)
    return bytes(new), new_index


def _clip_range(pos, length):
    pos, length = int(pos), int(length)
    if not 0 <= pos <= 0xFFFFFFFF or not 0 <= length <= 0xFFFFFFFF or pos + length > 0xFFFFFFFF:
        raise ValueError(f"a clip at tick {pos} of {length} ticks doesn't fit FL's playlist (positions are 32-bit)")
    return pos, length


def _clip_template(template, size):
    """FL's own 88-byte clip record (fl_blocks) as this project's record size; older layouts only when the project
    has no record of its own to copy (their first 32 bytes are the same; PC-VERIFY on FL 20/21)."""
    return bytes(template[:size]) if size <= len(template) else bytes(template) + bytes(size - len(template))


def _put_clips(d, ev, recs, k=None, have=True):
    """Write the current arrangement's clip records (sorted by position) back; k/have from _playlist_anchor."""
    if k is None:
        k, have = _playlist_anchor(d, ev)
    recs = sorted((bytes(r) for r in recs), key=lambda x: struct.unpack("<I", x[:4])[0])
    return _splice(d, ev, [(k, k + 1 if have else k, _data_event(EV_PLAYLIST, b"".join(recs)))])


def _add_clip(d, template, item, pos, length, track):
    ev = _events(d)
    k, have = _playlist_anchor(d, ev)
    _, size, recs = _playlist_at(d, ev)
    r = bytearray(_clip_template(template, size)); pos, length = _clip_range(pos, length)
    r[0:4] = struct.pack("<I", int(pos)); r[6:8] = struct.pack("<H", item); r[8:12] = struct.pack("<I", int(length))
    r[12:14] = struct.pack("<H", 499 - (_check_track(track) - 1)); r[14:16] = b"\x00\x00"
    r[16:24] = bytes.fromhex("7800400040648080"); r[24:32] = struct.pack("<ff", -1.0, -1.0)
    if size >= 88:
        r[32:36] = struct.pack("<I", _next_clip_id([_clip_id(x, i) for i, x in enumerate(recs)]))
    return _put_clips(d, ev, recs + [r], k, have)


def _free_track(d):
    """The lowest playlist track (1-500) with no clip in the current arrangement."""
    ev = _events(d); used = {499 - struct.unpack("<H", r[12:14])[0] + 1 for _, _, r in _clips(d, ev)}
    hit = next((t for t in range(max(used, default=0) + 1, MAX_PLAYLIST_TRACK + 1) if t not in used), None)
    if hit is None:
        hit = next((t for t in range(1, MAX_PLAYLIST_TRACK + 1) if t not in used), None)
    if hit is None:
        raise ValueError("every playlist track (1-500) already holds clips: give playlist_track")
    return hit


CHAN_LINK = {"volume": 0, "pan": 1}                             # REC_Chan_Vol / REC_Chan_Pan (FL API ids)


def _automation_target(d, track=0, param="volume", slot=None, plugin_param=None, channel=None):
    """(link parameter id, link destination, label text) of an automation target: a mixer track's volume / pan, a
    plugin parameter in a mixer slot, or (channel=) a channel's own volume / pan or its generator plugin's parameter.
    Channel targets: destination = the channel index, parameter = 0x8000 | plugin parameter (as mixer slots) or the
    FL API's REC_Chan_Vol (0) / REC_Chan_Pan (1). A VST's MIDI CC n is its plugin parameter 4096 + n (FL's wrapper
    lists 4096 parameter slots, then 128 MIDI CC sends).
    PC-VERIFY: an automation clip made with channel=<a VST channel>, plugin_param=4097 moves that plugin's CC1
    (mod wheel / dynamics) when the song plays; channel=<ch>, param=volume moves the channel's volume knob."""
    if channel is not None:
        ch = int(channel)
        ev = _events(d)
        if not any(e["id"] == EV_CHANNEL and struct.unpack("<H", _payload(d, e)[:2])[0] == ch for e in ev):
            raise ValueError(f"channel {ch} isn't in the project")
        if ch >= 0x0FFF:
            raise ValueError(f"channel {ch} can't be an automation target (index too large)")
        if plugin_param is not None:
            pp = int(plugin_param)
            if not 0 <= pp < 0x8000:
                raise ValueError("plugin_param must be 0..32767")
            return 0x8000 | pp, ch, f"param {pp}"
        if param not in CHAN_LINK:
            raise ValueError("with channel: param must be volume or pan (or give plugin_param)")
        return CHAN_LINK[param], ch, param.capitalize()
    t = int(track)
    if plugin_param is not None:
        if slot is None:
            raise ValueError("plugin_param needs the mixer slot of the plugin (or channel= for a channel's plugin)")
        return 0x8000 | int(plugin_param), 0x7000 + (t << 6) + int(slot), f"slot {slot} param {plugin_param}"
    if param not in MIX_LINK:
        raise ValueError("param must be volume or pan (or give slot + plugin_param)")
    return MIX_LINK[param], 0x7000 + (t << 6), param.capitalize()


def _automation_body(pts):
    """FL's automation points event (234) for [(beat, value 0..1)] sorted by beat (linear segments)."""
    import fl_blocks
    start = pts[0][0]; body = b""; prev = start
    for i, (beat, v) in enumerate(pts):
        body += struct.pack("<ddf", beat - prev, v, 0.0) + (b"\x00" * 4 if i == 0 else b"\x00\x00\x00\x02"); prev = beat
    tmpl = dict((eid, p) for eid, p, _ in _raw_events(fl_blocks.AUTOMATION_BLOCK))[EV_AUTOMATION]
    cnt = struct.unpack("<I", tmpl[17:21])[0]
    return tmpl[:17] + struct.pack("<I", len(pts)) + body + tmpl[21 + 24 * cnt:]


def _automation_write(d, pid, dest, label, pts, playlist_track=None, replace_channel=None):
    """In memory: an automation clip channel named `label` linked to (pid, dest) with points [(beat, value)], placed
    from its first to its last point. replace_channel: that existing automation channel gets the new points, target
    and clip instead (no extra channel). -> (data, {"channel", "playlist_track", "start_tick", "length_ticks"})."""
    import fl_blocks
    P = _ppq(d)
    pts = sorted((float(b), max(0.0, min(1.0, float(v)))) for b, v in pts)
    if len(pts) < 2:
        raise ValueError("give at least two points")
    auto = _automation_body(pts); start = pts[0][0]
    length = int(round((pts[-1][0] - start) * P))
    if replace_channel is not None:
        ch = int(replace_channel); ev = _events(d)
        k0, k1 = _channel_span(d, ev, ch)
        ka = next((k for k in range(k0, k1) if ev[k]["id"] == EV_AUTOMATION), None)
        if ka is None:
            raise ValueError(f"channel {ch} ('{label}') has no automation points to replace")
        edits = [(ka, ka + 1, _data_event(EV_AUTOMATION, auto))]
        kn = next((k for k in range(k0, k1) if ev[k]["id"] == EV_DISPLAY_NAME), None)
        if kn is not None and _text16(_payload(d, ev[kn])) != label:
            edits.append((kn, kn + 1, _data_event(EV_DISPLAY_NAME, str(label).encode("utf-16-le") + b"\x00\x00")))
        d = _splice(d, ev, sorted(edits))
        ev = _events(d)
        for k, e in enumerate(ev):                                # point it at the (possibly new) target
            if e["id"] == EV_REMOTE_LINK:
                lk = bytearray(_payload(d, e))
                if struct.unpack("<H", lk[2:4])[0] == ch:
                    lk[8:10] = struct.pack("<H", pid); lk[10:12] = struct.pack("<H", dest)
                    d = _splice(d, ev, [(k, k + 1, _data_event(EV_REMOTE_LINK, bytes(lk)))]); break
        ev = _events(d)
        try:
            k, recs = _playlist_event(d, ev)
        except ValueError:
            k, recs = None, []
        mine = [r for r in recs if struct.unpack("<H", r[6:8])[0] == ch]
        if mine:
            r = mine[0]; r[0:4] = struct.pack("<I", int(round(start * P))); r[8:12] = struct.pack("<I", length)
            if playlist_track:
                r[12:14] = struct.pack("<H", 499 - (_check_track(playlist_track) - 1))
            recs.sort(key=lambda x: struct.unpack("<I", x[:4])[0])
            d = _splice(d, ev, [(k, k + 1, _data_event(EV_PLAYLIST, b"".join(bytes(x) for x in recs)))])
            ptrack = 499 - struct.unpack("<H", r[12:14])[0] + 1
        else:
            ptrack = int(playlist_track) if playlist_track else _free_track(d)
            d = _add_clip(d, fl_blocks.AUTOMATION_CLIP, ch, int(round(start * P)), length, ptrack)
        return d, {"channel": ch, "playlist_track": ptrack, "start_tick": int(round(start * P)),
                   "length_ticks": length, "replaced": True}
    d, ch = _new_channel(d, fl_blocks.AUTOMATION_BLOCK, label, {EV_AUTOMATION: _data_event(EV_AUTOMATION, auto)})
    link = bytearray(fl_blocks.LINK)
    link[2:4] = struct.pack("<H", ch); link[8:10] = struct.pack("<H", pid); link[10:12] = struct.pack("<H", dest)
    ev = _events(d)
    first = next(k for k, e in enumerate(ev) if e["id"] == EV_CHANNEL)
    d = _splice(d, ev, [(first, first, _data_event(EV_REMOTE_LINK, bytes(link)))])
    ptrack = int(playlist_track) if playlist_track else _free_track(d)
    d = _add_clip(d, fl_blocks.AUTOMATION_CLIP, ch, int(round(start * P)), length, ptrack)
    return d, {"channel": ch, "playlist_track": ptrack, "start_tick": int(round(start * P)), "length_ticks": length}


def flp_add_automation(project, output, points, track=0, param="volume", slot=None, plugin_param=None, name=None,
                       playlist_track=None, replace=False, channel=None):
    """Add an automation clip to a project file and place it in the playlist.
    Target: mixer `track` volume or pan (param), or a plugin parameter on that track (slot + plugin_param); or with
    `channel`: that channel's volume / pan (param) or its instrument plugin's parameter (plugin_param; a VST's MIDI
    CC n = 4096 + n).
    points: [{bar, value}] in song bars (fractional ok). Volume points may use db instead of value (0 dB = 0.8),
    pan points may use pan (-1..1). Values are 0..1. The clip spans from the first to the last point."""
    writable(output)
    d = _load(project); P = _ppq(d)
    try:
        bpb = _qbar(flp_project_info(project))                          # bars follow the project's time signature
    except Exception:
        bpb = 4
    pid, dest, what = _automation_target(d, track, param, slot, plugin_param, channel)
    pts = []; meters = _meter_map(d, _events(d))
    for pt in sorted(points, key=lambda x: float(x["bar"])):
        if "db" in pt:
            v = _fader(pt["db"])
        elif "pan" in pt:
            v = (max(-1.0, min(1.0, float(pt["pan"]))) + 1) / 2
        else:
            v = float(pt["value"])
        pts.append((_bar_to_tick(pt["bar"], meters, P) / P, max(0.0, min(1.0, v))))   # through the meter map
    if len(pts) < 2:
        raise ValueError("give at least two points")
    if channel is not None:
        cname = next((nm for c_, nm in _channel_display_names(d).items() if c_ == int(channel)), None)
        label = name or f"{cname or f'Channel {int(channel)}'} - {what}"
    else:
        t = int(track)
        label = name or f"{'Master' if t == 0 else f'Insert {t}'} - {what}"
    old_ch = None
    if replace:
        old_ch = next((c for c, (kind, nm) in sorted(_clip_names(d, _events(d)).items(), reverse=True)
                       if kind == "automation" and nm == label), None)
    d, info = _automation_write(d, pid, dest, label, pts, playlist_track, old_ch)
    _save(d, output)
    return {"output": output, "channel": info["channel"], "name": label, "points": len(pts),
            **({"replaced": True} if old_ch is not None else {}),
            "start_bar": _tick_to_bar(info["start_tick"], meters, P),
            "length_bars": round(_tick_to_bar(info["start_tick"] + info["length_ticks"], meters, P)
                                 - _tick_to_bar(info["start_tick"], meters, P), 3),
            "playlist_track": info["playlist_track"]}


def _channel_display_names(d):
    """{channel index: display name or None}."""
    out, cur = {}, None
    for e in _events(d):
        if e["id"] == EV_CHANNEL:
            cur = struct.unpack("<H", _payload(d, e)[:2])[0]; out[cur] = None
        elif e["id"] == EV_CHANNEL_END:
            cur = None
        elif cur is not None and e["id"] == EV_DISPLAY_NAME and out.get(cur) is None:
            out[cur] = _text16(_payload(d, e))
    return out


def _audio_seconds(path):
    with open(path, "rb") as f:
        head = f.read(1 << 16)
    if head[:4] == b"RIFF" and head[8:12] == b"WAVE":
        i, rate, block = 12, None, None
        while i + 8 <= len(head):
            cid, n = head[i:i + 4], struct.unpack("<I", head[i + 4:i + 8])[0]
            if cid == b"fmt ":
                _, ch, rate, _, block, _ = struct.unpack("<HHIIHH", head[i + 8:i + 24])
            elif cid == b"data":
                return n / block / rate
            i += 8 + n + (n & 1)
    if head[:4] == b"fLaC":
        si = head[8:42]
        v = int.from_bytes(si[10:18], "big")
        rate, total = v >> 44, v & ((1 << 36) - 1)
        return total / rate
    raise ValueError("audio length is only read from WAV or FLAC; pass length_bars for other formats")


def _ticks_for_seconds(tempos, start, seconds, P):
    """How many ticks `seconds` of audio covers from tick `start`, following the tempo map."""
    t, left, i = start, float(seconds), 0
    tm = sorted((tk, b) for tk, b in tempos if _sane_bpm(b)) or [(0, 120.0)]
    if tm[0][0] > 0:
        tm.insert(0, (0, tm[0][1]))
    while True:
        bpm = [b for tk, b in tm if tk <= t][-1]
        nxt = next((tk for tk, _ in tm if tk > t), None)
        per_tick = 60.0 / bpm / P
        if nxt is None or (nxt - t) * per_tick >= left:
            return int(round(t + left / per_tick - start))
        left -= (nxt - t) * per_tick; t = nxt


def flp_add_audio_clip(project, output, audio, bar=1, playlist_track=None, name=None, length_bars=None):
    """Add an audio file (WAV/FLAC; others with length_bars) as an audio clip at `bar` in the playlist."""
    import fl_blocks
    writable(output)
    if not os.path.isfile(audio):
        raise FileNotFoundError(audio)
    d = _load(project); P = _ppq(d); ev = _events(d)
    meters = _meter_map(d, ev)                                    # bars follow the time signature (and its markers)
    pos = _bar_to_tick(bar, meters, P)
    if length_bars:
        length = _bar_to_tick(float(bar) + float(length_bars), meters, P) - pos
    else:
        _, tempos = _song(d, ev)
        length = _ticks_for_seconds(tempos, pos, _audio_seconds(audio), P)
    label = name or os.path.splitext(os.path.basename(audio))[0]
    path = _data_event(EV_SAMPLE_PATH, os.path.abspath(audio).encode("utf-16-le") + b"\x00\x00")
    d, ch = _new_channel(d, fl_blocks.AUDIO_BLOCK, label, {EV_SAMPLE_PATH: path})
    ptrack = int(playlist_track) if playlist_track else _free_track(d)
    d = _add_clip(d, fl_blocks.AUDIO_CLIP, ch, pos, length, ptrack)
    _save(d, output)
    return {"output": output, "channel": ch, "name": label, "bar": float(bar),
            "length_bars": round(_tick_to_bar(pos + length, meters, P) - _tick_to_bar(pos, meters, P), 3),
            "playlist_track": ptrack}


# ----------------------------------------------------------------------------- patterns and note editing
def _pattern_events(d, ev):
    """{pattern id: event index of its first notes event (224) or None}; patterns from data and name groups."""
    return {pid: (ks[0] if ks else None) for pid, ks in _pattern_note_events(d, ev).items()}


def _rec_to_note(r):
    """An FL note record as a note dict. "vel" is FL's raw velocity (0-128; 128 = FL's 100 %), never clamped here."""
    return {"pos": r[0], "len": r[3], "key": r[4], "vel": r[11], "ch": r[2], "_r": r}


def _note_to_rec(n):
    """A note dict -> FL's 24-byte record. A note nobody changed is written back byte for byte (velocity 128 and every
    other field kept); changed values are kept in range (velocity 0-128, key 0-131, positions 32-bit)."""
    old = n.get("_r")
    r = list(old or (0, NOTE_FLAGS_DEFAULT, 0, 0, 0, 0, 120, 0, 0, 0, 64, 100, 128, 128))
    pos, ln, key, vel, ch = int(n["pos"]), int(n["len"]), int(n["key"]), int(n["vel"]), int(n["ch"])
    if old is None or vel != old[11]:
        vel = max(0, min(128, vel))
    if old is None or key != old[4]:
        key = max(0, min(131, key))
    r[0], r[3], r[4], r[11], r[2] = max(0, min(0xFFFFFFFF, pos)), max(1, min(0xFFFFFFFF, ln)), key, vel, ch
    if "slide" in n:                                              # a note dict may switch FL's slide flag on or off
        r[1] = ((int(r[1]) & ~NOTE_SLIDE) | (NOTE_SLIDE if n["slide"] else 0)) or NOTE_FLAGS_DEFAULT
    return struct.pack(NOTE_RECORD, *r)


def _is_slide(x):
    """A slide mark on an inline note: True, 'slide', {'slide': true}."""
    if isinstance(x, dict):
        return bool(x.get("slide"))
    if isinstance(x, str):
        return x.strip().lower() in ("slide", "s", "true")
    return x is True


def _pattern_id(d, ev, pattern):
    pats = _patterns(d, ev)
    if pattern is None:
        with_notes = [p for p, v in pats.items() if v["notes"]]
        if not with_notes and len(pats) == 1:                     # one (still empty) pattern: that's the one
            return next(iter(pats))
        if not with_notes:
            raise ValueError("no pattern holds notes yet" + (f"; say which pattern ({sorted(pats)[:20]}); see "
                             "flp_patterns" if pats else " (this project has no patterns: flp_new_pattern makes one)"))
        if len(with_notes) != 1:
            raise ValueError(f"say which pattern (patterns with notes: {with_notes}); see flp_patterns")
        return with_notes[0]
    if isinstance(pattern, str) and not pattern.isdigit():
        hits = [p for p, v in pats.items() if v["name"].lower() == pattern.lower()] or \
               [p for p, v in pats.items() if pattern.lower() in v["name"].lower()]
        if not hits:
            raise ValueError(f"no pattern named '{pattern}'")
        return hits[0]
    if int(pattern) not in pats:
        raise ValueError(f"no pattern {pattern}")
    return int(pattern)


def flp_patterns(path):
    """Patterns of a project: id, name, notes per channel, length, and where they're placed in the playlist."""
    d = _load(path); ev = _events(d); P = _ppq(d); pats = _patterns(d, ev); places = {}
    meters = _meter_map(d, ev); bar_t = _song_bar_ticks(d, ev, P)
    for _, _, r in _clips(d, ev):
        item = struct.unpack("<H", r[6:8])[0]
        if item >= PATTERN_BASE:
            places.setdefault(item - PATTERN_BASE, []).append(round(_tick_to_bar(struct.unpack("<I", r[0:4])[0], meters, P), 2))
    out = []
    for pid, v in sorted(pats.items()):
        per = {}
        for r in v["notes"]:
            per[r[2]] = per.get(r[2], 0) + 1
        end = max((r[0] + r[3] for r in v["notes"]), default=0)
        out.append({"pattern": pid, "name": v["name"], "notes": len(v["notes"]), "notes_per_channel": per,
                    "length_bars": round(end / bar_t, 2), "placed_at_bars": places.get(pid, [])})
    return out


def _select(notes, channel, start_bar, end_bar, low, high, P, bar_t=None):
    """Note filter; bars are pattern bars of bar_t ticks (the project's time signature; 4/4 when not given)."""
    bar_t = bar_t or 4 * P
    a = (float(start_bar) - 1) * bar_t if start_bar else None
    b = (float(end_bar) - 1) * bar_t if end_bar else None
    lo = parse_note(low) if low is not None else None
    hi = parse_note(high) if high is not None else None
    def sel(n):
        return ((channel is None or n["ch"] == int(channel)) and (a is None or n["pos"] >= a) and
                (b is None or n["pos"] < b) and (lo is None or n["key"] >= lo) and (hi is None or n["key"] <= hi))
    return sel


def flp_notes(path, pattern=None, channel=None, start_bar=None, end_bar=None, limit=400):
    """The notes of a pattern, readable: bar.beat position, note name, length in beats, velocity, channel."""
    d = _load(path); ev = _events(d); P = _ppq(d); pid = _pattern_id(d, ev, pattern); bt = _song_bar_ticks(d, ev, P)
    sel = _select([], channel, start_bar, end_bar, None, None, P, bt)
    notes = [n for n in map(_rec_to_note, _patterns(d, ev)[pid]["notes"]) if sel(n)]
    notes.sort(key=lambda n: (n["pos"], n["key"]))
    rows = [{"at": f"{n['pos'] // bt + 1}.{n['pos'] % bt // P + 1}" + (f"+{n['pos'] % P}" if n["pos"] % P else ""),
             "note": note_name(n["key"]), "beats": round(n["len"] / P, 3), "vel": n["vel"], "ch": n["ch"],
             **({"slide": True} if n["_r"][1] & NOTE_SLIDE else {})}
            for n in notes[:int(limit)]]
    return {"pattern": pid, "count": len(notes), "shown": len(rows), "ppq": P, "notes": rows,
            "naming": "C4 = middle C (MIDI 60); FL's piano roll calls that note C5"}


def _pattern_data_anchor(d, ev):
    """Where a new pattern data group (65 + 224) goes when the project has none yet: FL writes the groups right
    before the remote-controller events (226/227) that precede the first channel. PC-VERIFY: a project saved by FL
    with no notes at all gets notes this way and FL shows them."""
    first = next((k for k, e in enumerate(ev) if e["id"] == EV_CHANNEL), None)
    if first is None:
        raise ValueError("couldn't find where pattern data lives in this project (no channels)")
    j = first
    while j > 0 and ev[j - 1]["id"] in (226, EV_REMOTE_LINK):
        j -= 1
    return j


def _write_pattern_notes(d, ev, pid, notes):
    """Set pattern `pid`'s notes. The first notes event of the pattern gets them all and any further notes event of it
    goes (FL writes one per pattern; two would play twice). A pattern without one gets a data group after the last
    data group (structural block end, not the last notes event)."""
    body = b"".join(_note_to_rec(n) for n in sorted(notes, key=lambda n: (n["pos"], n["ch"], n["key"])))
    ks = _pattern_note_events(d, ev).get(pid)
    if ks:
        return _splice(d, ev, _notes_event_edits(ev, ks, body))
    data = [g for g in _pattern_groups(d, ev) if g[0] == "pattern_data"]
    if data:
        g = next((g for g in data if g[1] == pid), data[-1])         # a controller-only group of this pattern: into it
        at = g[3]
    else:
        at = _pattern_data_anchor(d, ev)
    lead = b"" if data and g[1] == pid else struct.pack("<BH", EV_PATTERN_NEW, pid)
    return _splice(d, ev, [(at, at, lead + _data_event(EV_NOTES, body))])


def _pattern_meta_anchor(d, ev):
    """Index where a new pattern's name group (65 + 193) goes: right after the last existing name/settings group
    (its real end: the next structural event, so its time signature, length, ... stay with it); in a project with no
    named pattern yet, after the first channel's block (where FL 2026 keeps them). PC-VERIFY."""
    metas = [g for g in _pattern_groups(d, ev) if g[0] == "pattern_meta"]
    if metas:
        return metas[-1][3]
    ch = next((b for b in _blocks(d, ev) if b[0] == "channel"), None)
    if ch is not None:
        return ch[3]
    arr = next((k for k, e in enumerate(ev) if e["id"] == EV_ARRANGEMENT), None)
    if arr is None:
        raise ValueError("couldn't find where pattern names live in this project")
    return arr


def _new_pattern_group(pid, name, color=None):
    """Bytes of a pattern name group: PatternNew + name (+ color as FL's 150 event: R, G, B, 0)."""
    out = struct.pack("<BH", EV_PATTERN_NEW, pid) + _data_event(EV_PATTERN_NAME, str(name).encode("utf-16-le") + b"\x00\x00")
    if color is not None:
        c = _hexcolor(color)
        out += bytes([150, int(c[1:3], 16), int(c[3:5], 16), int(c[5:7], 16), 0])
    return out


def _add_pattern(d, name, color=None):
    """A new empty pattern named `name` -> (new bytes, pattern id). Works on projects without any named pattern.
    The one place that makes a pattern: extensions should call this (ns["_add_pattern"]) rather than copy it."""
    ev = _events(d)
    pid = _new_pattern_id(_patterns(d, ev))
    j = _pattern_meta_anchor(d, ev)
    d = _splice(d, ev, [(j, j, _new_pattern_group(pid, name, color))])
    return _write_pattern_notes(d, _events(d), pid, []), pid


# ---- per-PC speed factor ('tin can' PCs) ------------------------------------------------------------------------
# One number for how much slower FL is on this PC than on a fast one (1.0 = fast; clamp 1..6). Every wait that
# depends on FL's speed (bridge replies, saves landing, project loads, open/export dialogs, renders, FL lock waits)
# is its fast-PC value times this factor, so a weak PC isn't failed for being slow. Tiny UI polls are not scaled.
# Evidence (the slowest source wins; each source is smoothed): render seconds per song second (flh_finalize's
# learned ratio, over SPEED_BASE['render_ratio']), the median recent project load cost (over 'load_s'), the median
# bridge ping round trip (over 'ping_ms'), and replies FL gave after a fast PC's limit (late = answered_s / limit,
# smoothed). Default 1.0 until something was measured.
SPEED_FACTOR_MAX = 6.0
SPEED_BASE = {"render_ratio": 0.5, "load_s": 10.0, "ping_ms": 250.0}   # PC-VERIFY: a fast PC stays at 1.0 with these
SPEED_MIN_SCALED_S = 2.5                                          # waits shorter than this are UI polls: not scaled
SPEED_TTL_S = 20.0                                                # the factor is recomputed at most this often
SPEED_SOURCE_CAP = {"load": 3.0, "render": 4.0}                   # project size weighs in these: they alone never
                                                                  # make a PC count as slower than this
SAVE_FOREGROUND_CAP_S = 20.0                                      # a tool call's save wait on a slow PC
BRIDGE_FOREGROUND_CAP_S = 50.0                                    # a tool call's bridge wait (MCP clients: ~60 s)
_SPEED = {"f": None, "t": 0.0, "why": None, "sig": None, "pings": [], "late": None, "note": None}
_SPEED_LOCK = threading.RLock()
_SPEED_TL = threading.local()                                     # .notes: 'FL is still working' notes of this call


def _median(xs):
    xs = sorted(xs)
    if not xs:
        return None
    n = len(xs)
    return xs[n // 2] if n % 2 else (xs[n // 2 - 1] + xs[n // 2]) / 2.0


def speed_factor_from(render_ratio=None, load_s=(), ping_ms=(), late=()):
    """Pure: the speed factor from measurements -> (factor, {source: factor}). render_ratio = learned render seconds
    per song second; load_s = recent project load costs (s); ping_ms = bridge round trips; late = observed
    answered_s / fast-PC limit ratios, oldest first (exponentially smoothed, the newest weighs most)."""
    ev = {}
    try:
        if render_ratio and float(render_ratio) > 0:
            ev["render"] = float(render_ratio) / SPEED_BASE["render_ratio"]
    except (TypeError, ValueError):
        pass
    ls = [float(x) for x in (load_s or ()) if isinstance(x, (int, float)) and x > 0]
    if ls:
        ev["load"] = _median(ls) / SPEED_BASE["load_s"]
    ps = [float(x) for x in (ping_ms or ()) if isinstance(x, (int, float)) and x >= 0]
    if len(ps) >= 3:                                              # one cold ping proves nothing
        ev["bridge"] = _median(ps) / SPEED_BASE["ping_ms"]
    lt = [float(x) for x in (late or ()) if isinstance(x, (int, float)) and x > 0]
    if lt:
        e = lt[0]
        for x in lt[1:]:
            e += 0.5 * (x - e)
        ev["late"] = e
    ev = {k: round(min(SPEED_SOURCE_CAP.get(k, SPEED_FACTOR_MAX), SPEED_FACTOR_MAX, max(1.0, v)), 2)
          for k, v in ev.items()}
    return (max(ev.values()) if ev else 1.0), ev


def _speed_path():
    return os.path.join(os.path.dirname(STATE), "pc_speed.json")


def _speed_file():
    if _SPEED["late"] is None:
        d = _json_read(_speed_path(), {}) if os.path.exists(_speed_path()) else {}
        cut = time.time() - 14 * 86400                           # a slow week (an update running) is forgotten
        _SPEED["late"] = [x for x in (d.get("late") or []) if isinstance(x, list) and len(x) == 2 and x[0] > cut][-8:]
        _SPEED["pings"] = [float(x) for x in (d.get("pings") or []) if isinstance(x, (int, float))][-10:]
        if isinstance(d.get("f"), (int, float)):
            _SPEED["f_saved"] = float(d["f"])
    return _SPEED


def _speed_save():
    try:
        if _mkdirs(os.path.dirname(_speed_path())):
            _json_write(_speed_path(), {"f": _SPEED.get("f"), "why": _SPEED.get("why"), "late": _SPEED["late"],
                                        "pings": _SPEED["pings"][-10:], "t": int(time.time())})
    except Exception:
        pass


def _speed_evidence():
    """The measurements speed_factor_from takes, gathered from what the server already learned on this PC."""
    S = _speed_file(); rr = None; loads = []
    try:
        rs = _live().get("render_speed")
        d = rs() if rs else {}
        if int(d.get("renders") or 0) > 0:
            rr = float(d.get("ratio") or 0) or None
    except Exception:
        pass
    try:
        lc = globals().get("LOAD_COSTS")
        if lc and os.path.exists(lc):
            cut = time.time() - 30 * 86400
            es = sorted((e for e in _json_read(lc, {}).values() if isinstance(e, dict) and e.get("t", 0) > cut),
                        key=lambda e: -e.get("t", 0))[:8]
            loads = [e.get("avg_s") for e in es if isinstance(e.get("avg_s"), (int, float))]
    except Exception:
        pass
    return {"render_ratio": rr, "load_s": loads, "ping_ms": list(S["pings"]), "late": [x[1] for x in S["late"]]}


def _speed_factor(refresh=False):
    """This PC's speed factor (cached; 1.0 = a fast PC, until measured). Rises at once with slower evidence, falls
    halfway per change of evidence (one fast reply after a slow week doesn't make the PC 'fast')."""
    with _SPEED_LOCK:
        if not refresh and _SPEED["f"] is not None and time.time() - _SPEED["t"] < SPEED_TTL_S:
            return _SPEED["f"]
        try:
            ev = _speed_evidence()
            raw, why = speed_factor_from(**ev)
        except Exception:
            raw, why = 1.0, {}
        sig = json.dumps(why, sort_keys=True)
        prev = _SPEED["f"] if _SPEED["f"] is not None else _SPEED.get("f_saved")
        if prev is None or raw >= prev:
            f = raw
        elif sig != _SPEED["sig"]:
            f = prev + 0.5 * (raw - prev)
        else:
            f = prev
        f = round(min(SPEED_FACTOR_MAX, max(1.0, f)), 2)
        changed = f != _SPEED["f"]
        _SPEED.update(f=f, t=time.time(), why=why, sig=sig)
        if changed:
            _speed_save()
        return f


def _scaled(seconds, min_s=None):
    """A fast-PC wait in seconds -> this PC's (times the speed factor). Waits under min_s (UI polls) unchanged;
    factor 1.0 gives back exactly the same number."""
    s = float(seconds)
    if s < (SPEED_MIN_SCALED_S if min_s is None else min_s):
        return s
    f = _speed_factor()
    return s if f <= 1.0 else round(s * f, 2)


def _speed_extra(base, scaled):
    """How much longer a wait may run, once, when it timed out while FL is visibly still working: up to the
    scaled wait again, never past SPEED_FACTOR_MAX x the fast-PC wait."""
    base = float(base)
    if base < SPEED_MIN_SCALED_S:
        return 0.0
    return round(max(0.0, min(float(scaled), base * SPEED_FACTOR_MAX - float(scaled))), 2)


def _speed_observe_ping(ms):
    if not 0 <= ms < 2000:                                        # FL busy loading: not this PC's bridge speed
        return
    with _SPEED_LOCK:
        S = _speed_file(); S["pings"] = (S["pings"] + [round(ms, 1)])[-10:]
        if len(S["pings"]) in (3, 10) or len(S["pings"]) % 5 == 0:
            _speed_save()


def _speed_observe_late(what, base, took, extended=False):
    """FL answered `what` after `took` s where a fast PC gets `base` s: evidence this PC is slow (and a note)."""
    if base < SPEED_MIN_SCALED_S or took <= base:
        return
    with _SPEED_LOCK:
        S = _speed_file()
        S["late"] = (S["late"] + [[int(time.time()), round(min(SPEED_FACTOR_MAX, took / base * 1.2), 2)]])[-8:]
        _SPEED["t"] = 0.0                                         # recompute on the next ask
        _speed_save()
    if extended:
        _slow_note(f"FL is still working (slow PC): {what} took {took:.0f} s (a fast PC: {base:g} s); waited longer "
                   "instead of failing")


def _slow_note(text):
    _SPEED["note"] = {"note": text, "at": time.strftime("%H:%M:%S")}
    notes = getattr(_SPEED_TL, "notes", None)
    if notes is None:
        notes = _SPEED_TL.notes = []
    if text not in notes:
        notes.append(text)


def _pop_slow_notes():
    notes = getattr(_SPEED_TL, "notes", None) or []
    _SPEED_TL.notes = []
    return notes


def _slow_why(base, waited, extended=False):
    """The end of a 'gave up waiting' error: what was waited and this PC's measured factor."""
    f = _speed_factor()
    return (f" (waited {waited:.0f} s: a fast PC's {base:g} s x this PC's speed factor {f:g}"
            + ("; FL looked busy, so the wait was extended once" if extended else "") + ")")


def _fl_cpu_busy(sample_s=0.3, busy=0.15):
    """True when an FL process used more than `busy` of a CPU core over `sample_s` (Windows; None elsewhere or when
    unreadable). PC-VERIFY: FL loading a big project reads True; idle FL with a song stopped reads False."""
    if os.name != "nt":
        return None
    try:
        import ctypes
        from ctypes import wintypes
        k32 = ctypes.windll.kernel32
        k32.OpenProcess.restype = wintypes.HANDLE
        def cpu(pid):
            h = k32.OpenProcess(0x1000, False, int(pid))          # PROCESS_QUERY_LIMITED_INFORMATION
            if not h:
                return None
            try:
                a, b, c_, d = (wintypes.FILETIME() for _ in range(4))
                if not k32.GetProcessTimes(h, ctypes.byref(a), ctypes.byref(b), ctypes.byref(c_), ctypes.byref(d)):
                    return None
                return ((c_.dwHighDateTime << 32 | c_.dwLowDateTime) + (d.dwHighDateTime << 32 | d.dwLowDateTime)) / 1e7
            finally:
                k32.CloseHandle(h)
        pids = _fl_pids()
        before = {p: cpu(p) for p in pids}
        time.sleep(sample_s)
        for p in pids:
            a, b = before.get(p), cpu(p)
            if a is not None and b is not None and (b - a) / sample_s > busy:
                return True
        return False
    except Exception:
        return None


def _fl_still_working():
    """FL runs and is visibly busy: the bridge script's heartbeat stopped (FL's UI thread is loading, saving or
    exporting) or the FL process is using CPU. A dead or closed FL is never 'still working'.
    PC-VERIFY: True while FL loads a big project; False after FL was closed; a plugin's modal popup reads ?"""
    try:
        if not fl_running():
            return False
        hb = os.path.join(_mailbox_dir(), "alive.json")
        if os.path.exists(hb) and not _mailbox_alive(max_age=3.0):
            return True
        return bool(_fl_cpu_busy())
    except Exception:
        return False


def fl_speed_view():
    """Compact view for fl_status / fl_timings."""
    f = _speed_factor()
    r = {"factor": f, "from": dict(_SPEED.get("why") or {}) or "not measured yet (1.0 = a fast PC)"}
    if _SPEED.get("note"):
        r["last_slow"] = _SPEED["note"]
    return r


FL_LOCK_WAIT_S = 30.0                                             # a foreground FL tool waits this long for FL


def _wait_saved(project, before, wait_s, stop=None):
    """True once FL's save of `project` has fully landed: its (mtime, size) moved away from `before`, then stayed the
    same for ~0.3 s, and a project file holds all the bytes its header announces. A big project on a slow, network
    or OneDrive folder is written over seconds; reading it half-written would edit a truncated copy."""
    return _wait_saved_any({project: before}, wait_s, stop) == project


SAVE_WAIT_CAP_S = 60.0                                            # a save still writing bytes is waited for this long
SAVE_GROW_GRACE_S = 4.0                                           # ... in steps of this after each change seen


def _wait_saved_any(befores, wait_s, stop=None, cap_s=None):
    """_wait_saved over several candidate files ({path: (mtime, size) before}; the first key is the project the
    caller means): the one FL's save landed in, or None.
    A save through the bridge writes only the file FL has open, so this is how the open file is identified when
    several projects share the name FL's title shows. The deadline moves on while a file keeps changing (a big
    project on a slow, network or OneDrive folder takes a while), up to cap_s (SAVE_WAIT_CAP_S) in all.
    Proof needs one file: the first key when it changed; a twin only when it is the only candidate that changed
    (two files changing at once - a sync client, an autosave copy - prove nothing: None)."""
    keys = list(befores)
    first = keys[0] if keys else None
    t0 = time.time(); last = {}; since = {}; changed = set(); done_ = []
    base = float(wait_s); wait_s = _scaled(base); f = wait_s / base if base > 0 else 1.0   # slow PC: longer
    fg = not getattr(_JOB_LOCAL, "job", None)
    if fg:                                                        # a tool call: the slow-PC stretch stays under
        wait_s = min(wait_s, max(base, SAVE_FOREGROUND_CAP_S))    # the job threshold (a save that never comes
    deadline = t0 + wait_s; cap = t0 + max(wait_s, (SAVE_WAIT_CAP_S if cap_s is None else cap_s) * f)
    extra = _speed_extra(base, wait_s)
    if fg:                                                        # must still be said within one call)
        cap = min(cap, t0 + max(base, SAVE_FOREGROUND_CAP_S) * 1.5)
        extra = min(extra, max(0.0, max(base, SAVE_FOREGROUND_CAP_S) - wait_s))
    while True:
        if time.time() >= deadline:                               # nothing landed yet, but FL is visibly still
            if extra > 0 and not changed and _fl_still_working():  # saving (slow PC): once more, not a failure
                deadline += extra; cap = max(cap, deadline); extra = 0.0
                _slow_note("FL is still working (slow PC): its save took longer than a fast PC's "
                           f"{base:g} s; waited longer instead of failing")
            else:
                break
        time.sleep(0.08)
        if stop is not None and stop():
            return None
        for project, before in befores.items():
            if project in done_:
                continue
            try:
                sig = _file_sig(project)
            except OSError:
                continue
            if before is not None and list(sig) == list(before):
                continue
            changed.add(project)
            if sig != last.get(project):
                last[project], since[project] = sig, time.time()
                deadline = min(cap, max(deadline, time.time() + SAVE_GROW_GRACE_S))   # still writing: wait on
                continue
            if time.time() - since[project] < 0.3:
                continue
            try:
                with open(project, "rb") as f:
                    d = f.read()
                if d[:4] == b"FLhd":
                    _check_complete(d)
            except (OSError, ValueError):
                since[project] = time.time()                       # still being written: keep waiting
                deadline = min(cap, max(deadline, time.time() + SAVE_GROW_GRACE_S))
                continue
            done_.append(project)
        if first in done_:
            return first
        if len(changed) == 1 and done_:
            return done_[0]
    return None


def _sigs(paths):
    out = {}
    for p in paths:
        try:
            out[p] = _file_sig(p)
        except OSError:
            out[p] = None
    return out


def _warm_scan():
    try:
        _scan_flps()
    except Exception:
        pass


def _same_name_files(project):
    """`project` plus every other project file FL's current title could mean (same name or title)."""
    out = [os.path.abspath(project)]
    try:
        stem = _title_stem(_main_title())
        if stem and stem.lower() in _project_names(project):
            out += [c for c in _name_candidates(stem) if _ud_key(c) != _ud_key(project) and not _is_backup_copy(c)]
    except Exception:
        pass
    return out


def _new_save_as_dialogs(before):
    """Close a Save As box that a save through the bridge opened (FL's project was never saved): Esc, nothing
    saved. True when there was one. PC-VERIFY: FPT_Save on a never-saved 'Project 3' opens Save As."""
    found = False
    try:
        for d in fl_dialogs():
            if d["hwnd"] not in before and d.get("kind") == "save_as":
                found = True
                try:
                    _press_vk(d["hwnd"], 0x1B)
                except Exception:
                    pass
    except Exception:
        pass
    return found


TRIAL_SAVE_MSG = ("FL's save brought up its demo/trial warning ('{title}'): a plugin in this project runs as a demo, "
                  "and FL won't save it without 'Save anyway', which fl-headless never answers. It pressed Cancel and "
                  "changed nothing - remove or replace the demo plugin (or save it yourself in FL), then try again")


def _cancel_trial_warning(before):
    """After a save through the bridge: FL's demo/trial 'Save anyway' warning, if one came up, gets Esc (Cancel,
    nothing saved) -> the message to raise, else None. FL is blocked while it shows, so nothing may drive FL on.
    PC-VERIFY: a bridge save (FPT_Save) of a project with a demo plugin shows the same warning as Ctrl+S, and Esc
    cancels it without saving."""
    try:
        for d in fl_dialogs():
            if d["hwnd"] not in before and _is_save_anyway(d):
                try:
                    _press_vk(d["hwnd"], 0x1B)
                except Exception:
                    pass
                return TRIAL_SAVE_MSG.format(title=d.get("title") or "Save anyway")
    except Exception:
        pass
    return None


def _trial_stop(before, every_s=0.5):
    """A stop() for _wait_saved_any: True once FL's trial 'Save anyway' warning is up (FL won't save; no need to wait
    out the deadline). Looks at FL's popups at most every every_s."""
    last = [0.0]

    def stop():
        if time.time() - last[0] < every_s:
            return False
        last[0] = time.time()
        try:
            return any(d["hwnd"] not in before and _is_save_anyway(d) for d in fl_dialogs())
        except Exception:
            return False
    return stop


def _dialog_ids():
    try:
        return {d["hwnd"] for d in fl_dialogs()}
    except Exception:
        return set()


_NOT_THIS = "not-this-file"                                       # _hot_reload: FL's save landed in another file


def _prove_open(project, wait_s=6.0):
    """Ask FL to save through the bridge and see which file changes: the open project's identity, proven.
    -> the path FL wrote (`project` or a same-name twin), 'never_saved' (FL opened Save As: a new unsaved project),
    or None (no save landed: no bridge, FL busy, or a file outside FLH_ROOTS). Takes the FL lock (2 s 'busy' when a
    job holds it)."""
    blocked = _stale_block(project)
    if blocked:                                                   # FL holds an older copy: no save over the file
        raise RuntimeError(blocked)
    if _preview_mutes_on():                                       # never save FL with a preview's live mutes in it
        raise RuntimeError(_preview_mutes_on())
    _warm_scan()                                                  # the roots scan runs before FL is locked
    if not _fl_acquire():
        raise RuntimeError(f"FL is busy ({_fl_busy_with()}), so nothing was changed; try again when it's done")
    try:
        cands = _same_name_files(project); before = _sigs(cands); dlg = _dialog_ids()
        for c in cands:                                           # a file newer than FL's copy is never saved over
            older = _fl_copy_older(c)                             # (the save lands in whichever FL holds)
            if older:
                raise RuntimeError(older)
        for c in cands:                                           # no record of what FL holds (FL opened it by
            if not _fl_held(c):                                   # hand): the file as it is now stays restorable,
                _backup_once(c)                                   # whatever FL's save writes into it
        try:
            BRIDGE.call("transport", action="save")
        except Exception:
            return None
        got = _wait_saved_any(before, wait_s, stop=_trial_stop(dlg))
        if got:
            _note_open_proof(got)
            return got
        trial = _cancel_trial_warning(dlg)
        if trial:
            raise RuntimeError(trial)
        return "never_saved" if _new_save_as_dialogs(dlg) else None
    finally:
        _FL_LOCK.release()


_BACKED_UP = {}                                                   # ud key -> (mtime_ns, size) backed up already


def _backup_once(path):
    """_backup, once per version of the file (a wait that proves identity every few seconds makes one backup)."""
    try:
        st = os.stat(path); sig = (st.st_mtime_ns, st.st_size)
        if _BACKED_UP.get(_ud_key(path)) == sig:
            return None
        b = _backup(path); _BACKED_UP[_ud_key(path)] = sig
        return b
    except Exception:                                             # noqa: BLE001
        return None


def _bridge_state_light(timeout=15.0):
    """Transport-only state (playing, position, tempo, title, channel/mixer counts): a reply of a few bytes, so it
    works on any project size. Older bridge scripts don't know light=1: then the full state."""
    try:
        return BRIDGE.call("state", timeout=timeout, light=True)
    except RuntimeError as e:
        if "light" not in str(e):
            raise
    return BRIDGE.call("state", timeout=timeout)


def _hot_reload(project, fn):
    """Edit the project that's open in FL without closing FL: save through the bridge, wait for the file to land,
    edit it, then load it again in the same window. None if the bridge can't do it (caller falls back).
    Holds the FL lock (no other FL tool, job or check drives FL meanwhile) and the verify lock; a check of the
    previous edit still running steps aside first. Never proceeds without both locks."""
    if getattr(_HOT_TL, "active", False):                         # a writer inside this thread's own hot reload
        # PC-VERIFY: flp_extend_ending on the open song: one save, one reload, edit step ~1 s
        return _as_edit(fn)                                       # (PC 2026-10-22: flp_extend_ending -> flp_playlist
                                                                  # waited 30 s on its own verify lock, then saved FL
                                                                  # over its own edit): the file only, no 2nd save
    T0 = time.time()
    _warm_scan()                                                  # the roots scan runs before FL is locked
    _PENDING_VERIFY["__gen"] = _PENDING_VERIFY.get("__gen", 0) + 1   # a check of the last edit still running stops:
    if not _fl_acquire():                                         # this edit's own save checks that edit instead
        raise RuntimeError(f"FL is busy ({_fl_busy_with()}), so nothing was changed; try again when it's done")
    try:
        _VERIFY_STOP.set()                                        # a check still holding the verify lock steps aside
        lk = _VERIFY_LOCK
        try:
            got = lk.acquire(timeout=FL_LOCK_WAIT_S * _speed_factor())   # (never two threads saving at once)
        finally:
            _VERIFY_STOP.clear()                                  # set only while waiting: never left behind
        if not got and not _verify_running():                     # held, yet no check runs: a leaked lock (a
            _verify_lock_reset()                                  # thread that died holding it) - heal, go on
            lk = _VERIFY_LOCK
            got = lk.acquire(timeout=2.0)
        if not got:
            raise RuntimeError("the check of the previous edit is still driving FL, so nothing was changed; try again "
                               "in a few seconds")
        _HOT_TL.active = True
        try:
            return _hot_reload_locked(project, fn, T0)
        finally:
            _HOT_TL.active = False
            lk.release()
    finally:
        _FL_LOCK.release()


_HOT_TL = threading.local()                                       # .active: this thread is inside _hot_reload


def _as_edit(fn):
    """Run a project writer as part of the edit already under way on this thread: writers it calls inside (flp_playlist,
    flp_tempo_write...) write the file only - no save, reload or verify-lock wait of their own."""
    _edit_enter()
    try:
        return fn()
    finally:
        _edit_exit()


# ---- what FL holds vs what fl-headless wrote (content checksums, this session) ----------------------------------
# FL's export renders what FL has LOADED, not the file. When fl-headless wrote other content into a file after FL
# last loaded (or saved) it and FL wasn't reloaded, FL holds an OLDER copy: its export would render the old song and
# its save would undo the write. Tracked by content (crc32 + size), so a write that puts the same bytes back (an
# all-or-nothing restore) never counts as newer; only files FL was SEEN holding are judged (no record: no claim).
_FL_HOLDS = {}                                                    # ud key -> (crc, size) of the file as FL holds it
_FH_WROTE = {}                                                    # ud key -> ((mtime_ns, size), (crc, size)): our last write


def _crc(data):
    import zlib
    return (zlib.crc32(data) & 0xFFFFFFFF, len(data))


def _note_wrote(path, data):
    """fl-headless just wrote `data` into the project `path` (temp / own-folder copies aren't tracked)."""
    try:
        if not str(path).lower().endswith(".flp"):
            return
        ap = os.path.abspath(path); nk = os.path.normcase(ap)
        if any(nk.startswith(t) for t in _TEMP_ROOTS) or _own_folder(ap):
            return
        _FH_WROTE[_ud_key(ap)] = (tuple(_file_sig(ap)), _crc(data))
    except Exception:
        pass


def _note_fl_holds(path, data=None):
    """FL holds `path` exactly as it is on disk now (it just loaded it, or its save just wrote it)."""
    try:
        if data is None:
            with open(path, "rb") as f:
                data = f.read()
        _FL_HOLDS[_ud_key(path)] = _crc(data)
        _note_fl_synced()                                         # FL's live changes are in the file now
        _holds_persist()
    except Exception:
        pass


# ---- live changes FL holds that its file doesn't (yet) ---------------------------------------------------------
# Live tools (fl_plugin_set, fl_channel_set, fl_mixer_set ...) change FL, not the file. A save through FL puts them
# into the file; a reload WITHOUT that save throws them away. Normally every edit of the open project saves FL first,
# but some paths skip FL's save (FL is known to hold an older copy than the file: a reload that couldn't be proven,
# or the file changed behind FL) - and FL's own 'changed' flag doesn't see changes made through its scripting API.
# So fl-headless keeps its own log; those paths check it (_live_save_probe) instead of dropping the changes (PC
# 2026-10-27, twice: a master Convolver's wet level, an INSTRUMENT choir's dynamics knobs, set live and gone after the
# next queued edit's sync).
LIVE_CHANGE_TOOLS = {"fl_channel_set", "fl_mixer_set", "fl_playlist_track_set", "fl_pattern_set", "fl_pattern_new",
                     "fl_steps", "fl_batch", "fl_organize", "fl_plugin_set", "fl_plugin_set_value", "fl_plugin_preset",
                     "fl_plugin_set_named", "fl_load_preset", "fl_set_tempo", "fl_mix_apply"}
_LIVE_LOG = []                     # [(time, tool, parts)] live changes made through the bridge (bounded)
_FL_SYNC_T = {"t": 0.0}            # when FL last saved or loaded its project (its file then held what FL holds)


def _note_fl_synced():
    _FL_SYNC_T["t"] = time.time()


def _live_parts(name, kw):
    """The parts of the project (render-cache fingerprint parts: ('m', mixer track), ('lv', track levels), ('c',
    channel), 'G' global) a live call changes; {'*'} when it can't say (then nothing can be proven about it)."""
    def num(*keys):
        for k in keys:
            try:
                if kw.get(k) is not None:
                    return int(kw[k])
            except (TypeError, ValueError):
                return None
        return None
    if name in ("fl_plugin_set", "fl_plugin_set_value", "fl_plugin_preset", "fl_plugin_set_named"):
        i = num("index", "track"); s = num("slot")
        if name == "fl_plugin_set_named" and s is None:
            s = 0
        if i is None:
            return {"*"}
        return {("m", i)} if s is not None and s >= 0 else {("c", i)}
    if name == "fl_mixer_set":
        t = num("track", "index")
        return {("m", t), ("lv", t)} if t is not None else {"*"}
    if name == "fl_channel_set":
        c = num("index", "channel")
        return {("c", c)} if c is not None else {"*"}
    if name == "fl_steps":
        c = num("channel")
        return {("c", c), "G"} if c is not None else {"*"}
    if name == "fl_load_preset":
        c, t = num("channel"), num("track")
        return {("c", c)} if c is not None else {("m", t)} if t is not None else {"*"}
    if name in ("fl_playlist_track_set", "fl_pattern_set", "fl_pattern_new", "fl_set_tempo"):
        return {"G"}
    if name == "fl_batch":
        out = set()
        for o in kw.get("ops") or []:
            got = _live_parts({"mixer": "fl_mixer_set", "channel": "fl_channel_set", "plugin": "fl_plugin_set"}
                              .get(str((o or {}).get("op")), "?"), o or {}) if isinstance(o, dict) else {"*"}
            out |= got
        return out or {"*"}
    return {"*"}


def _note_live_change(name, kw=None):
    """A live change went into FL (not into its file)."""
    try:
        parts = _live_parts(name, kw or {})
    except Exception:                                             # noqa: BLE001
        parts = {"*"}
    _LIVE_LOG.append((time.time(), str(name), frozenset(parts)))
    del _LIVE_LOG[:-60]


def _live_since(t):
    """Names of the live changes made after time t (oldest first, each once)."""
    return list(dict.fromkeys(n for tt, n, _p in list(_LIVE_LOG) if tt > float(t or 0)))


def _live_unsaved():
    """Live changes FL holds that aren't in its file: made after FL last saved or loaded. [(tool, parts)]"""
    t0 = _FL_SYNC_T["t"]
    return [(n, p) for tt, n, p in list(_LIVE_LOG) if tt > t0]


def _live_noting(name, fn):
    """A live tool that records its change in _LIVE_LOG when it worked (dry runs / reads aren't changes)."""
    def run(*a, **kw):
        r = fn(*a, **kw)
        if not kw.get("dry_run") and not (isinstance(r, dict) and r.get("error")):
            _note_live_change(name, kw)
        return r
    run.__wrapped__ = getattr(fn, "__wrapped__", fn)
    for attr in ("__lazy__",):
        if hasattr(fn, attr):
            setattr(run, attr, getattr(fn, attr))
    return run


def _fl_forget(path=None):
    """FL no longer holds `path` (it switched files) - or anything (path None: FL closed)."""
    if path is None:
        _FL_HOLDS.clear(); _LAST_PROVEN.clear()
        _note_fl_synced()                                         # FL closed: no live changes left to keep
    elif path:
        _FL_HOLDS.pop(_ud_key(path), None)
        if _LAST_PROVEN.get("path") and _ud_key(_LAST_PROVEN["path"]) == _ud_key(path):
            _LAST_PROVEN.clear()
    _holds_persist()


# The file fl-headless last PROVED FL has open (a save through the bridge landed in it, the reload marker was read
# back, a reload's tag went, FL's title switched to it after fl_open) with FL's title then and FL's process: when two
# files share the name / title FL's window shows ('Song.flp' and 'Song (v2).flp' both titled 'Song'), it is the one
# _open_project_identify() proves first (by a save) - a hint, never an identity by itself: a twin switched by hand in
# FL shows the very same title. Valid while FL's title and process are unchanged since; kept with the hold record.
_LAST_PROVEN = {}


def _note_proven_open(path, how, persist=True):
    try:
        _LAST_PROVEN.clear()
        _LAST_PROVEN.update(path=os.path.abspath(path), title=_title_stem(_main_title()) or "", fl=_fl_proc_sig(),
                            how=str(how), t=time.time())
        if persist:
            _holds_persist()
    except Exception:                                             # noqa: BLE001
        pass


def _proven_pick(cands, stem):
    """The candidate _LAST_PROVEN names, while FL's title (`stem`) and FL's process are what they were then; else
    None. PC-VERIFY: two files titled alike - after fl_open of one, fl_status / fl_save / edits name that one
    (checklists/core.md 'Release bug hunt: live layer' 7)."""
    _holds_restore()
    p = _LAST_PROVEN.get("path")
    if not p or not stem or str(_LAST_PROVEN.get("title") or "").lower() != str(stem).lower():
        return None
    sig = _fl_proc_sig()
    if _LAST_PROVEN.get("fl") and sig and list(_LAST_PROVEN["fl"]) != list(sig):
        return None                                               # another FL since: it proves nothing now
    return next((c for c in cands if _ud_key(c) == _ud_key(p) and os.path.isfile(c)), None)


# What FL holds survives a restart of this server (Claude Desktop restarts it; FL stays open): kept next to state.json
# with the FL process it belongs to, and read back only while that same FL runs. Without it, a server started after
# FL loaded a song had no record, so it couldn't see a file put over the song on disk (PC 2026-10-23).
_HOLDS_DISK = {"loaded": False}


def _holds_file():
    return os.path.join(os.path.dirname(STATE), "fl_holds.json")


def _fl_proc_sig():
    try:
        return sorted(int(p) for p in _fl_pids())
    except Exception:                                             # noqa: BLE001
        return []


def _holds_persist():
    try:
        sig = _fl_proc_sig()
        if not sig:
            return
        _json_write(_holds_file(), {"fl": sig, "holds": {k: list(v) for k, v in _FL_HOLDS.items()},
                                    "proven": dict(_LAST_PROVEN) or None})
    except Exception:                                             # noqa: BLE001
        pass


def _holds_restore():
    """Once per process: what FL holds, as an earlier run of this server recorded it - if the same FL still runs."""
    if _HOLDS_DISK["loaded"]:
        return
    _HOLDS_DISK["loaded"] = True
    try:
        d = _json_read(_holds_file(), {}) or {}
        sig = _fl_proc_sig()
        if not sig or d.get("fl") != sig:
            return
        for k, v in (d.get("holds") or {}).items():
            if k not in _FL_HOLDS and isinstance(v, list) and len(v) == 2:
                _FL_HOLDS[k] = (int(v[0]), int(v[1]))
        pv = d.get("proven")
        if not _LAST_PROVEN and isinstance(pv, dict) and pv.get("path"):
            _LAST_PROVEN.update(pv)
    except Exception:                                             # noqa: BLE001
        pass


def _fl_held(project):
    """(crc, size) of `project` as FL last loaded / saved it, or None (no record)."""
    k = _ud_key(project)
    if k not in _FL_HOLDS:
        _holds_restore()
    return _FL_HOLDS.get(k)


def _fl_behind_file(project):
    """True when FL is known to hold an OLDER copy of `project` than the file: FL was seen holding it (loaded /
    saved, checksum noted) and since then fl-headless wrote other content into the file without FL loading it."""
    if not project:
        return False
    k = _ud_key(project); w = _FH_WROTE.get(k); held = _fl_held(project) if w else None
    if not held or not w:
        return False
    try:
        sig = tuple(_file_sig(project))
    except OSError:
        return False
    return sig == w[0] and w[1] != held                          # the file is still our write, and FL has other bytes


def _fl_copy_older(project):
    """A message when `project` on disk is no longer what FL last loaded or saved - a copy put over it (a restore),
    another program, fl-headless's own write FL didn't reload, or a save by hand in FL - so a save through FL could
    overwrite something newer than FL's copy. None when FL was never seen holding it (no record: no claim) or the file
    is still exactly what FL holds. PC 2026-10-23: fl_open's identity save wrote FL's (older) copy over a file the
    user had just restored on disk - twice."""
    if not project:
        return None
    held = _fl_held(project)
    if not held:
        return None
    try:
        with open(project, "rb") as f:
            now = _crc(f.read())
    except OSError:
        return None
    if now == held:
        return None
    return (f"{os.path.basename(project)} on disk isn't what FL last loaded or saved (it changed since: a copy put "
            "over it, another program, or a save by hand in FL), so a save through FL could overwrite newer work in "
            "the file - FL wasn't asked to save it")


# ---- FL holds an older copy than the file (a reload failed): nothing may save FL over the file ------------------
_STALE_FL = {}                                                    # ud key -> {project, t, why, backup}


def _stale_mark(project, why, data=None):
    """The file has edits FL didn't load (its reload failed / timed out): until FL loads the file, no save through FL
    may land in it (fl_save, the background check, merged-edit flushes, fl_open's save, the next edit's save)."""
    bk = None
    try:
        bk = _backup(project, data=data) if data is not None else None   # restorable whatever happens in FL
    except Exception:
        pass
    _STALE_FL[_ud_key(project)] = {"project": os.path.abspath(project), "t": time.time(), "why": str(why)[:400],
                                   "backup": bk}


def _stale_clear(project):
    _STALE_FL.pop(_ud_key(project), None)


def _stale_get(project):
    """The stale entry of `project` while FL still shows it (FL closed or switched to another project: it no longer
    holds the old copy, the entry goes), else None."""
    e = _STALE_FL.get(_ud_key(project)) if project else None
    if not e:
        if not project or not _fl_behind_file(project):
            return None
        try:                                                      # fl-headless wrote the file behind FL's back
            where = _open_state(project)
        except Exception:
            where = "unknown"
        if where == "not_open":                                   # FL left it meanwhile: it loads the file fresh
            _fl_forget(project)
            return None
        try:
            with open(project, "rb") as f:
                data = f.read()
        except OSError:
            data = None
        _stale_mark(project, "fl-headless wrote the file after FL last loaded it, and FL wasn't reloaded since", data)
        return _STALE_FL.get(_ud_key(project))
    try:
        where = _open_state(project)
    except Exception:
        where = "unknown"
    if where == "not_open":
        _STALE_FL.pop(_ud_key(project), None)
        return None
    return e


def _stale_block(project=None):
    """The message why FL must not save now (FL holds an older copy of a file with newer edits on disk), or None.
    project=None: any stale project FL still shows (for saves whose target isn't known: the bridge itself)."""
    keys = [project] if project else [v["project"] for v in list(_STALE_FL.values())]
    for k in keys:
        e = _stale_get(k)
        if e:
            name = os.path.basename(e["project"])
            return (f"not saved: FL holds an older copy of {name} than the file on disk (the last reload into FL "
                    f"failed: {e['why']}), so saving in FL would overwrite the newer edits. fl_open('{e['project']}') "
                    "loads the file into FL (answering No to 'save changes?'); the next edit of it reloads FL too"
                    + (f". The edited file is also backed up (flp_versions)" if e.get("backup") else ""))
    return None


def _check_previous_edit(project):
    """Right after FL saved for a new edit: does FL still hold the previous edit? (instead of a slow background check)"""
    key = os.path.normcase(os.path.abspath(project))
    pend = _PENDING_VERIFY.pop(key, None)
    if not pend or time.time() - pend.get("t", 0) > 180:          # older: hand edits in FL are likely, don't judge
        return None
    try:
        got = _fingerprint(project)
    except Exception:
        return None
    bad = [k for k in pend["want"] if _fp_differs(pend["want"], got, k)]   # tempo lane: with a tolerance
    if bad:
        _state({"verify_alert": f"{os.path.basename(project)}: at the next edit FL's copy had an older "
                                f"{', '.join(bad)} than the previous edit wrote (FL kept an old copy, or it was "
                                "changed by hand in FL)"})
        return False
    return True


def _hot_reload_locked(project, fn, T0):
    """The save is also the identity proof: every file FL's title could mean is watched, and only when the save lands
    in `project` is it edited and reloaded (answering 'No' to 'save changes?' is then safe: FL's work is on disk).
    Lands in a same-name twin -> _NOT_THIS (FL has the other file; this one may be written directly).
    FL known to hold an older copy (stale / file changed behind it) is edited WITHOUT its save - unless live changes
    are in FL that its file lacks (_live_unsaved): then FL saves anyway and _live_save_probe keeps that save as the
    base only when FL proves to hold the file's edits too, else puts the file back and refuses (nothing lost)."""
    steps = {"wait_prev_check": round(time.time() - T0, 1)}; T0 = time.time()
    live = _live_unsaved()                                       # live changes FL holds that its file doesn't
    probe = None
    if _stale_get(project):                                       # FL holds an OLDER copy (its last reload failed):
        if not live:                                              # its save would undo the edits on disk
            return _hot_reload_stale(project, fn, steps, T0)
        probe = "stale"                                           # ... but a reload alone would drop the live changes
    else:
        older = _fl_copy_older(project)
        if older:                                                 # the file changed behind FL (a restore copied over
            if _fl_changed_flag() == 0 and not live:              # it...): FL's save would overwrite it. Nothing of
                return _hot_reload_stale(project, fn, steps, T0)  # FL's unsaved: edit the file, FL loads it
            if not live:
                raise RuntimeError(older + ", and FL has unsaved changes (or can't say), so nothing was changed. "
                                   "fl_open(project, save_current=false) loads the file into FL (FL's changes are "
                                   "dropped); then edit again. If the change on disk was your own save in FL, fl_save() "
                                   "once, then edit again")
            probe = older
    if _preview_mutes_on():
        raise RuntimeError(_preview_mutes_on())
    cands = _same_name_files(project); dlg = _dialog_ids()
    file_before = None
    if probe:                                                     # FL's save is a probe: the file comes back unless
        try:                                                      # FL is proven to hold it plus the live changes
            with open(project, "rb") as f:
                file_before = f.read()
        except OSError as e:
            raise RuntimeError(f"{os.path.basename(project)} couldn't be read ({e}), so nothing was changed")
    try:
        was_playing = bool(_bridge_state_light().get("playing"))
        before = _sigs(cands)
        BRIDGE.call("transport", action="save")
    except Exception:
        return None
    landed = None
    for attempt in (1, 2):                                        # a busy FL (still loading) may miss the first save
        landed = _wait_saved_any(before, 8.0, stop=_trial_stop(dlg))
        if landed:
            break
        trial = _cancel_trial_warning(dlg)
        if trial:                                                 # FL won't save it: nothing edited, said why
            raise RuntimeError(trial)
        if _new_save_as_dialogs(dlg):                             # Save As (closed again): FL's project has no file
            _HOT_MISS["never_saved"] = True
            return None
        try:
            BRIDGE.call("transport", action="save")
        except Exception:
            pass
    if landed is None:
        if probe and file_before is not None:                     # a save that landed only now: the newer file back
            try:
                if open(project, "rb").read() != file_before:
                    _backup(project); _write_bytes(project, file_before)
            except Exception:                                     # noqa: BLE001
                pass
        return None
    if probe and _ud_key(landed) == _ud_key(project):
        steps["live_probe"] = _live_save_probe(project, file_before, live, probe)   # raises: file put back
    _note_open_proof(landed)
    if _ud_key(landed) != _ud_key(project):
        _HOT_MISS["other"] = landed
        return _NOT_THIS
    steps["save"] = round(time.time() - T0, 1); T0 = time.time()
    prev_ok = _check_previous_edit(project)
    try:
        orig = open(project, "rb").read()
        pre = _fingerprint(project)                               # what FL held before this edit
    except Exception:
        orig, pre = None, None
    res = _as_edit(fn)                                            # writers inside it: the file only (one reload)
    steps["edit"] = round(time.time() - T0, 1)
    if steps.get("live_probe") and isinstance(res, dict):
        res["live_kept"] = steps.pop("live_probe")                # said in the result, not only in the timings
    return _reload_edited(project, res, steps, orig, pre, was_playing, prev_ok)


def _rc_parts(fp):
    """A render-cache fingerprint as {part: hash}: 'G' (song-wide), ('c', channel), ('m', mixer track), ('lv', track
    levels)."""
    out = {"G": fp.get("G")}
    out.update({("c", int(c)): h for c, h in (fp.get("chan") or {}).items()})
    out.update({("m", int(t)): h for t, h in (fp.get("mix") or {}).items()})
    out.update({("lv", int(t)): tuple(v or ()) for t, v in (fp.get("levels") or {}).items()})
    return out


def _part_words(x):
    if x == "G":
        return "the song itself (patterns, playlist, tempo)"
    k, i = x
    return {"c": f"channel {i}", "m": f"mixer track {i}", "lv": f"mixer track {i}'s level"}.get(k, str(x))


def _master_tempo_like(data, ref):
    """`data` with its master tempo set to `ref`'s when ref's tempo lane plays from bar 1 (FL saves the master tempo
    as the lane's value at the playhead: that difference means nothing)."""
    try:
        dr, er = ref, _events(ref)
        if not _tempo_lane_fp(dr, er)[0]:
            return data
        rv = next((_payload(dr, e) for e in er if e["id"] == EV_TEMPO and e["len"] == 4), None)
        ev = _events(data)
        k = next((k for k, e in enumerate(ev) if e["id"] == EV_TEMPO and e["len"] == 4), None)
        if rv is None or k is None:
            return data
        return _splice(data, ev, [(k, k + 1, bytes([EV_TEMPO]) + bytes(rv))])
    except Exception:                                             # noqa: BLE001
        return data


def _live_save_probe(project, file_before, live, why):
    """FL had to save although it holds an OLDER copy than the file (`why`: a reload that wasn't proven, or the file
    changed behind FL), because live changes (`live`: [(tool, parts)]) would otherwise be lost: its save just landed
    in `project`. Keep it only when FL is proven to hold the file's edits too - part by part (render-cache
    fingerprint: song, channels, mixer tracks, levels; FL's playhead tempo on a song with a tempo lane ignored):
      - with the version from before the file's last edit (kept with the stale mark): every part that edit changed
        is in FL's save -> FL holds the edit (other differences are FL's: live / by hand, kept);
      - else: FL's save differs from the file only in parts the live changes touched.
    Then the edit goes on top of FL's save (the live changes kept) -> a note. Otherwise the file is put back as it
    was, FL's save kept as a backup (flp_versions), and RuntimeError says what to do - nothing was changed, so a
    queued edit stays queued. PC-VERIFY: after a reload that wasn't proven (content_check 'can't tell'), fl_plugin_set
    on a mixer effect, then flp_edit (queued) + flh_sync: the knob keeps its live value and the edit is in FL."""
    tools = list(dict.fromkeys(n for n, _p in live))
    parts = set()
    for _n, p in live:
        parts |= set(p)
    try:
        with open(project, "rb") as f:
            saved = f.read()
    except OSError:
        saved = None
    ent = _STALE_FL.get(_ud_key(project)) or {}
    prev = ent.get("prev")
    ok, detail = False, "FL's save couldn't be read"
    if saved is not None:
        try:
            RC = _rc()
            pF = _rc_parts(RC.fingerprint(file_before))
            pS = _rc_parts(RC.fingerprint(_master_tempo_like(saved, file_before)))
            if RC.fingerprint(file_before).get("raw") or RC.fingerprint(saved).get("raw"):
                raise ValueError("a project layout the check can't split into parts")
            if prev is not None:
                pP = _rc_parts(RC.fingerprint(_master_tempo_like(prev, file_before)))
                edited = [x for x in set(pF) | set(pP) if pF.get(x) != pP.get(x)]
                lacks = [x for x in edited if pS.get(x) != pF.get(x)]
                ok = not lacks
                detail = ("FL's save holds every part the file's last edit changed" if ok else
                          "FL's save lacks the file's last edit in " + ", ".join(_part_words(x) for x in sorted(
                              lacks, key=str)[:4]))
            else:
                diff = [x for x in set(pF) | set(pS) if pF.get(x) != pS.get(x)]
                other = [x for x in diff if "*" in parts or x not in parts]
                ok = not other
                detail = ("FL's save differs from the file only where the live changes went" if ok else
                          "FL's save differs from the file in " + ", ".join(_part_words(x) for x in sorted(
                              other, key=str)[:4]) + " too, not only where the live changes went")
        except Exception as e:                                    # noqa: BLE001
            ok, detail = False, f"FL's save and the file couldn't be compared ({type(e).__name__}: {str(e)[:80]})"
    if ok:
        _stale_clear(project)                                     # FL holds the file's edits (+ its live changes)
        was = ("FL was marked as holding an older copy (its last reload wasn't proven)" if why == "stale" else
               "the file had changed behind FL")
        return f"{was}, so FL's save was checked first: {detail}, so its live changes ({', '.join(tools)}) are kept"
    bk = None
    try:
        bk = _backup(project, data=saved) if saved else None      # FL's state with the live changes: restorable
    except Exception:                                             # noqa: BLE001
        pass
    _write_bytes(project, file_before)                            # the file exactly as it was
    if ent:
        _STALE_FL[_ud_key(project)] = ent                         # (still stale: FL holds the older copy)
    name = os.path.basename(project)
    reason = ent.get("why") if ent else str(why)
    raise RuntimeError(
        f"nothing was changed: FL holds live changes made since it last loaded or saved {name} ({', '.join(tools)}), "
        f"but FL's copy is older than the file ({str(reason)[:200]}): {detail}. Reloading FL would throw the live "
        "changes away and saving FL would throw the file's newer edits away, so neither was done - the file is as it "
        "was and queued edits stay queued" + ("; FL's current state (with the live changes) is backed up "
                                              "(flp_versions)" if bk else "")
        + f". To keep the file: fl_open('{project}', save_current=false), redo the live changes, then flh_sync(). To "
          "keep FL's state instead: save in FL (Ctrl+S), then flh_sync() (the file's newer edits are then only in "
          "flp_versions)")


def _hot_reload_stale(project, fn, steps, T0):
    """The edit of a project FL holds an OLDER copy of (its last reload failed): FL isn't asked to save first (that
    would write the old copy over the newer file), the edit goes onto the file and FL loads it (answering No to 'save
    changes?' - what FL holds is older than the file). # PC-VERIFY: after a reload that timed out, the next edit of
    that project reloads FL without saving first and FL then shows both edits."""
    try:
        was_playing = bool(_bridge_state_light(timeout=3.0).get("playing"))
    except Exception:
        was_playing = False
    try:
        orig = open(project, "rb").read(); pre = _fingerprint(project)
    except Exception:
        orig, pre = None, None
    steps["save"] = 0.0; T0 = time.time()
    res = _as_edit(fn)
    steps["edit"] = round(time.time() - T0, 1)
    if not isinstance(res, dict):
        res = {"result": res}
    res["fl_held_older_copy"] = ("FL wasn't saved first: it still held the copy from before the last edit (whose "
                                 "reload failed), and its save would have undone that edit; the file was edited and "
                                 "loaded into FL")
    if orig is not None:
        try:
            if open(project, "rb").read() == orig:                # nothing changed: FL still needs the earlier edit
                orig = None
        except Exception:
            pass
    return _reload_edited(project, res, steps, orig, pre, was_playing, None)


def _reload_edited(project, res, steps, orig, pre, was_playing, prev_ok):
    """After the edit of the open project: reload FL (unless nothing changed), then prove it in the background."""
    try:
        written = open(project, "rb").read(); want = _fingerprint(project)
    except Exception:
        written, want = None, None
    if orig is not None and written == orig:                      # the writer changed nothing: no reload, no check
        if not isinstance(res, dict):
            res = {"result": res}
        res.update(reloaded_in_fl=False, steps_s=steps)
        res.setdefault("note", "nothing changed in the file, so FL wasn't reloaded")
        if prev_ok is not None:
            res["previous_edit_held"] = prev_ok
        return res
    cost0 = _load_cost_ref(project)                               # before this reload: is its time plausible?
    # FL held an OLDER copy (its last reload failed, or the file changed behind it): a direct reopen FL may serve from
    # its own copy, so the proven route (empty template first, a marker only the file has) - like fl_open does
    older = isinstance(res, dict) and bool(res.get("fl_held_older_copy"))
    try:
        if older:
            with _reload_verified():
                steps.update(_reload_in_fl(project) or {})
        else:
            steps.update(_reload_in_fl(project) or {})            # same window
        _note_fl_synced()                                         # FL loaded (proven or not): earlier live changes
                                                                  # were saved first or are gone with that load
        if steps.get("unproven"):                                 # FL's load of the edit couldn't be proven: no claim
            raise RuntimeError(steps.pop("unproven"))             # that FL holds it (FL is marked stale already)
        if steps.get("proof") != "marker":                        # (the marker route recorded what FL holds itself)
            _note_fl_holds(project, written)
    except Exception as e:                                        # the FILE holds the edit; FL still the old copy
        if not isinstance(res, dict):
            res = {"result": res}
        _stale_mark(project, f"{type(e).__name__}: {e}", written)  # no save may land over the edit until FL has it
        if orig is not None and not (isinstance(res, dict) and res.get("fl_held_older_copy")):
            _STALE_FL[_ud_key(project)]["prev"] = orig            # FL's own save before the edit: lets a later save
                                                                  # prove whether FL holds the edit (_live_save_probe)
        if want is not None:                                      # what FL must hold once it loaded the file
            _PENDING_VERIFY[os.path.normcase(os.path.abspath(project))] = {"want": want, "t": time.time(), "job": None}
        res.update(reloaded_in_fl=False, fl_shows_old_version=True, steps_s=steps,
                   WARNING=(f"the file was edited, but FL couldn't be made to reload it ({type(e).__name__}: {e}). FL "
                            "still shows the OLD version: fl-headless won't save FL over the file meanwhile (fl_save, "
                            "checks, merged edits refuse); fl_open(project) loads it into FL - or File > Open it in "
                            "FL and answer No to 'save changes?'. Don't press Ctrl+S in FL before that: FL's save "
                            "would undo this edit"))
        return res
    t0 = time.time(); loaded = False; wait_load = _scaled(30.0)     # a slow PC loads slower
    while time.time() - t0 < wait_load:
        try:
            BRIDGE.call("ping", timeout=2.0); loaded = True; break
        except Exception:
            time.sleep(0.2)
    if loaded and not was_playing:
        try:
            BRIDGE.call("transport", action="stop")              # FL starts playback after a load
        except Exception:
            pass
    sus = _reload_suspect(cost0, steps)
    fl_orig = not (isinstance(res, dict) and res.get("fl_held_older_copy"))   # orig = FL's own save before the edit
    if sus and written is not None and orig is not None and fl_orig:
        T = time.time()
        chk = _reload_check_now(project, written, orig, cost0)
        steps["reload_check"] = round(time.time() - T, 1)
        if not isinstance(res, dict):
            res = {"result": res}
        res["reload_check"] = dict(chk, reload_s=sus[0], load_cost_s=sus[1])
        if chk.get("verified") is True and chk.get("attempts") == 1:   # the fast reload was real: averaged in
            try:
                _note_load_cost(project, _reload_took(steps), "reload")
            except Exception:                                     # noqa: BLE001
                pass
        if chk.get("verified") is False:
            res.update(reloaded_in_fl=False, fl_shows_old_version=True, steps_s=steps,
                       WARNING=(f"FL didn't load this edit: its 'reload' took {sus[0]:g} s for a project that loads in "
                                f"~{sus[1]:g} s, and FL's save afterwards was still the version from before the edit. "
                                f"{chk.get('note')}. fl-headless won't save FL over the file meanwhile; fl_open(project, "
                                "save_current=false) loads it into FL"))
            if prev_ok is not None:
                res["previous_edit_held"] = prev_ok
            return res
    res["reloaded_in_fl"] = True; res["steps_s"] = steps
    if prev_ok is not None:
        res["previous_edit_held"] = prev_ok
    if loaded and written is not None and (res.get("reload_check") or {}).get("verified") is not True:
        res["verify_job"] = _verify_in_background(project, written, want, was_playing, pre)   # (in the background)
    return res


def _reload_check_now(project, written, orig, cost=None):
    """Right after an implausibly fast reload (_reload_suspect): did FL really load the edit? FL saves, and its save is
    compared with `orig` - FL's own save right before the edit - by the render cache's sound fingerprint (notes,
    sounds, effects, mixer, levels; FL's save-time stamps left out). The same sound while the edit changed it: FL never
    loaded the edit (its save just wrote the old version over it). Then the edit is put back into the file (FL's save
    kept as a backup) and FL loads it through an empty project, checked once more; still old -> the file keeps the
    edit and is marked so nothing saves FL over it. -> {"verified": True | False | None, "note"}.
    PC-VERIFY: a merged edit on a big project whose reload FL ignored is caught here and loaded the second time."""
    RC = _rc()

    def snd(b):
        fp = RC.fingerprint(b)
        return fp["sound"], RC.levels_key(fp)
    try:
        s_old, s_new = snd(orig), snd(written)
    except Exception as e:                                        # noqa: BLE001
        return {"verified": None, "note": f"couldn't fingerprint the project ({type(e).__name__})"}
    if s_old == s_new:
        return {"verified": None, "note": "the edit changed nothing FL's save would show, so it can't be checked"}
    for attempt in (1, 2):
        _wait_for(lambda: _ping_ok(), _scaled(max(30.0, 2.0 * float(cost or 0))), 0.5)   # FL answers once loaded
        saved = False
        for _ in range(3):                                        # right after a load FL may ignore a save
            if _save_in_fl_and_wait(project, wait_s=8.0):
                saved = True; break
            time.sleep(1.0)
        if not saved:
            return {"verified": None, "note": "FL didn't save, so the reload couldn't be checked"}
        try:
            with open(project, "rb") as f:
                got = f.read()
        except OSError as e:
            return {"verified": None, "note": f"the project couldn't be read back ({e})"}
        try:
            same_old = snd(got) == s_old
        except Exception:                                         # noqa: BLE001
            return {"verified": None, "note": "FL's save couldn't be fingerprinted"}
        if not same_old:
            return {"verified": True, "attempts": attempt,
                    "note": "FL's save after the reload differs from the version before the edit"
                    + ("" if attempt == 1 else " (FL needed a second load, through an empty project)")}
        try:
            _backup(project)                                      # FL's save (the old version), restorable
        except Exception:                                         # noqa: BLE001
            pass
        _write_bytes(project, written)                            # the edit back into the file
        if attempt == 2:
            break
        try:
            _reload_in_fl(project, force_blank=True)
        except Exception as e:                                    # noqa: BLE001
            _stale_mark(project, f"FL ignored the reload and the second load failed ({e})", written)
            return {"verified": False, "note": f"the edit is back in the file; FL couldn't be made to load it ({e})"}
    _stale_mark(project, "FL kept the version from before the edit after two loads", written)
    return {"verified": False, "note": "FL kept the version from before the edit after two loads; the edit is back in "
                                      "the file"}


_HOT_MISS = {}                                                    # why the last hot reload didn't happen (messages)
_VERIFY_LOCK = threading.Lock()
_VERIFY_LEAKS = []                                                # healed leaked verify locks (for flh_bug_report)


def _verify_running():
    return any(str(j).startswith("verify-") and v.get("status") == "running" for j, v in list(JOBS.items()))


def _verify_lock_reset():
    """Replace a verify lock nobody can be holding on purpose (no check runs). PC 2026-10-21: every edit was refused
    'the check of the previous edit is still driving FL' with no check running."""
    global _VERIFY_LOCK
    _VERIFY_LEAKS.append({"t": time.strftime("%H:%M:%S"), "holder": _FL_HOLDER.get("what"),
                          "threads": sorted(t.name for t in threading.enumerate())[:40]})
    _VERIFY_LOCK = threading.Lock()
_VERIFY_STOP = threading.Event()                                  # set: a newer edit wants FL; checks step aside
_PENDING_VERIFY = {}                                              # project -> what FL should hold (until checked)


def _pop_verify_alert():
    a = _live().get("_state_get", _state_get)("verify_alert")
    if a:
        _state({"verify_alert": None})
        return f"an earlier edit didn't stick in FL - {a}"
    return None


_TIMINGS = {}


def _steps_of(res):
    """steps_s of a tool result (also inside a job result or an flp_edit's ops)."""
    if not isinstance(res, dict):
        return None
    if isinstance(res.get("steps_s"), dict):
        return res["steps_s"]
    if isinstance(res.get("result"), dict) and isinstance(res["result"].get("steps_s"), dict):
        return res["result"]["steps_s"]
    return None


def _timing_note(name, took, res=None):
    t = _TIMINGS.setdefault(name, {"calls": 0, "total_s": 0.0, "max_s": 0.0})
    t["calls"] += 1; t["total_s"] = round(t["total_s"] + took, 2)
    steps = _steps_of(res)
    if steps:
        t["last_steps"] = steps
    if took >= t["max_s"]:
        t["max_s"] = took
        if steps:
            t["slowest_steps"] = steps


def fl_timings():
    """Where the time goes this session: per tool calls, total and slowest seconds (slowest first), with the step
    breakdown of the slowest and the last call where the tool reports one."""
    rows = sorted(({"tool": k, **v, "avg_s": round(v["total_s"] / v["calls"], 2)} for k, v in _TIMINGS.items()),
                  key=lambda r: -r["total_s"])
    jobs = [{"job": j, "seconds": v.get("seconds"), "steps_s": _steps_of(v.get("result"))}
            for j, v in JOBS.items() if not j.startswith("verify-") and v.get("status") != "running"]
    try:
        speed = fl_speed_view()
    except Exception:
        speed = None
    return {"tools": rows[:25], "jobs": [j for j in jobs if j["steps_s"]][-8:], "renders": _render_stats_view(),
            "pc_speed": speed}


_FL_HOLDER = {"what": None}                                       # who holds the FL lock (for 'busy' messages)


def _fl_busy_with():
    w = _FL_HOLDER.get("what")
    if w:
        return w
    run = [j for j, v in JOBS.items() if v.get("status") == "running"]
    return f"job {run[-1]} (fl_job)" if run else "another FL step"


def _verify_in_background(project, written, want, was_playing, pre=None):
    done = [j for j, v in list(JOBS.items()) if j.startswith("verify-") and v.get("status") != "running"]
    for j in done[:-20]:                                          # finished checks don't pile up
        JOBS.pop(j, None); _JOB_EVENTS.pop(j, None)
    jid = _job_id("verify", {"status": "running", "started": time.strftime("%H:%M:%S")})
    ev = _JOB_EVENTS[jid] = threading.Event()
    key = os.path.normcase(os.path.abspath(project))
    gen = _PENDING_VERIFY.get("__gen", 0); since = time.time()   # live changes after this are FL's, kept
    _PENDING_VERIFY[key] = {"want": want, "t": since, "job": jid}
    aside = {"verified": None, "verify_note": "a newer edit checks it"}
    newer = lambda: _PENDING_VERIFY.get("__gen", 0) != gen

    def run():
        try:
            t0 = time.time()                                      # FL lock first, then the verify lock (same order
            while not _FL_LOCK.acquire(timeout=0.5):              # as every edit: no deadlock)
                if newer() or time.time() - t0 > _scaled(300):
                    JOBS[jid].update(status="done", result=aside if newer() else
                                     {"verified": None, "verify_note": "FL stayed busy; the next edit checks it"})
                    return
            try:
                lk = _VERIFY_LOCK
                while not lk.acquire(timeout=0.5):
                    if newer():
                        JOBS[jid].update(status="done", result=aside)
                        return
                    lk = _VERIFY_LOCK
                try:
                    _FL_HOLDER["what"] = "checking that FL holds the last edit"
                    if newer() or _VERIFY_STOP.is_set():
                        r = aside
                    else:
                        r = _verify_loaded(project, written, want, was_playing, pre, gen, since)
                    JOBS[jid].update(status="done", result=r)
                    if r.get("verified") is not None and _PENDING_VERIFY.get(key, {}).get("job") == jid:
                        _PENDING_VERIFY.pop(key, None)            # settled: the next edit needn't check it
                    if r.get("verified") is False:
                        _state({"verify_alert": f"{os.path.basename(project)}: {r.get('verify_note')}"})
                finally:
                    _FL_HOLDER["what"] = None
                    lk.release()
            finally:
                _FL_LOCK.release()
        except Exception as e:
            JOBS[jid].update(status="failed", error=f"{type(e).__name__}: {e}")
        finally:
            ev.set()
    threading.Thread(target=run, daemon=True).start()
    return jid


def _fingerprint(path):
    """What FL has to keep when it loads and re-saves a project: every pattern's notes, the playlist clips (without
    the ids FL renumbers on save) and the channel count. {part: hash}."""
    import hashlib
    d = _load(path); ev = _events(d)
    notes = sorted((pid, r[0], r[2], r[3], r[4], min(127, r[11])) for pid, pt in _patterns(d, ev).items()
                   for r in pt["notes"])
    try:
        clips = sorted((bytes(r[0:4]), bytes(r[6:12]), bytes(r[12:14]), bytes(r[24:28]),
                        struct.unpack("<H", r[18:20])[0] & CLIP_MUTE) for r in _playlist_event(d, ev)[1])
    except ValueError:
        clips = []
    h = lambda x: hashlib.sha256(repr(x).encode()).hexdigest()[:16]
    tempo = next((struct.unpack("<I", _payload(d, e))[0] for e in ev if e["id"] == EV_TEMPO and e["len"] == 4), None)
    lane = _tempo_lane_fp(d, ev)[1]
    # FL saves the master tempo as the tempo lane's value at the playhead (PC 2026-10-27: 71.8 / 70.9 / 69.2 / 81.2
    # on one song, depending where playback stopped): FL's saved master tempo is then compared loosely (any value the
    # lane plays counts as the same) and the lane itself with a tolerance (_fp_differs)
    # PC-VERIFY: a song with a tempo lane, playhead stopped mid-song, two syncs: no 'didn't stick' alert (core.md 3b)
    return {"notes": h(notes), "clips": h(clips), "channels": sum(1 for e in ev if e["id"] == EV_CHANNEL),
            "tempo": tempo, "tempo_lane": lane}


FINGERPRINT_PARTS = "notes, playlist clips, channel count and tempo (the tempo lane when the song has one)"
NOT_FINGERPRINTED = "mixer, plugin, automation-shape, color and project-info changes"
TEMPO_LANE_TOL_BPM = 0.5           # FL re-saves tempo-lane points with its own rounding: closer than this = the same


def _tempo_lane_fp(d, ev):
    """(covers_bar_1, lane) of a project's tempo lane as the playlist plays it - tempo events recorded in placed
    patterns (flp_tempo_write / flp_write_arrangement's 'Tempo' lane) and tempo automation clips, NOT the master tempo.
    lane = (ppq, ((tick, bpm), ...)) or None (no lane). covers_bar_1: the lane sets the tempo from the song's start."""
    try:
        P = _ppq(d); pats = _patterns(d, ev); pts = []
        for _, _, r in _clips(d, ev):
            if struct.unpack("<H", r[18:20])[0] & CLIP_MUTE:
                continue
            pat = pats.get(struct.unpack("<H", r[6:8])[0] - PATTERN_BASE)
            if not pat or not pat.get("ctrl"):
                continue
            pos, length = struct.unpack("<I", r[0:4])[0], struct.unpack("<I", r[8:12])[0]
            start = _clip_offsets(r)[0]
            for c in _ctrl_records(pat["ctrl"]):
                t = struct.unpack("<I", c[:4])[0]
                if (c[4], c[7]) == TEMPO_CTRL and start <= t < start + length:
                    b = _sane_bpm(struct.unpack("<I", c[8:])[0] / 1000)
                    if b:
                        pts.append((pos + t - start, round(b, 3)))
        auto = _tempo_automation(d, ev, P)
    except Exception:                                             # noqa: BLE001 - an odd file: no lane claim
        return False, None
    if auto:
        spans = [(a, b) for a, b, _ in auto]
        pts = [x for x in pts if not any(a <= x[0] < b for a, b in spans)] + [pt for _, _, ps in auto for pt in ps]
    if not pts:
        return False, None
    pts = tuple(sorted(set(pts)))
    covers = pts[0][0] <= max(1, P // 16) or any(a <= 0 < b for a, b, _ in auto)
    return covers, (P, pts)


def _lanes_close(a, b, tol=None):
    """Two tempo lanes ((ppq, ((tick, bpm), ...)) or None) play the same tempo within `tol` BPM everywhere, allowing
    each point to sit up to 1/8 beat off (FL re-rounds lane points when it saves)."""
    if a == b:
        return True
    if not a or not b:
        return False
    import bisect
    tol = TEMPO_LANE_TOL_BPM if tol is None else float(tol)
    (pa_, pa), (pb_, pb) = a, b
    if pb_ != pa_ and pb_:                                        # another resolution: ticks onto a's
        pb = tuple((int(round(t * pa_ / pb_)), v) for t, v in pb)
    P = max(1, int(pa_ or 96)); J = max(1, P // 8)

    def f(pts):
        ticks = [t for t, _ in pts]
        return lambda x: pts[max(0, bisect.bisect_right(ticks, x) - 1)][1]
    fa, fb = f(pa), f(pb)
    end = max(pa[-1][0], pb[-1][0]) + P
    step = max(1, P // 4, end // 20000 + 1)
    xs = set(range(0, end, step)) | {t for t, _ in pa} | {t for t, _ in pb}
    for x in xs:
        if min(abs(fa(x) - fb(y)) for y in (x - J, x, x + J)) > tol or \
                min(abs(fb(x) - fa(y)) for y in (x - J, x, x + J)) > tol:
            return False
    return True


def _fp_differs(a, b, k):
    """Does _fingerprint() b (FL's save, when one side is) differ from a in part k? The tempo lane with a tolerance
    (_lanes_close). The master tempo: when both have the same tempo lane, b's counts as the same when it is a value
    that lane plays - FL saves the master tempo as the lane's value at the playhead, so on a song with a lane it
    follows where playback stopped (a real stale copy has its OLD lane: then the master tempo is compared exactly)."""
    x, y = (a or {}).get(k), (b or {}).get(k)
    if x == y:
        return False
    if k == "tempo_lane":
        return not _lanes_close(x, y)
    if k == "tempo" and x is not None and y is not None:
        la, lb = (a or {}).get("tempo_lane"), (b or {}).get("tempo_lane")
        if la and lb and _lanes_close(la, lb) and \
                any(abs(y / 1000.0 - bpm) <= TEMPO_LANE_TOL_BPM for _t, bpm in lb[1]):
            return False
    return True


def _fp_diff(a, b):
    """The parts in which two _fingerprint()s differ (see _fp_differs), [] when they hold the same."""
    return [k for k in dict.fromkeys(list(a or {}) + list(b or {})) if _fp_differs(a, b, k)]


_SAVE_TL = threading.local()       # .why: why this thread's last _save_in_fl_and_wait was refused (None: it wasn't)


def _save_guard_why(project, explicit=False):
    """Why a save through FL meant for `project` must not happen now, or None. FL's save writes whatever FL holds into
    FL's own file - so the guards are checked for that file, whichever it is:
    - FL shows ANOTHER project (FL's title names another file, not this one's name / title): the save would land
      there, not in `project` (PC: a render of B saved FL's older copy of A over A's newer file);
    - FL holds an older copy than the file of `project` or of any project FL still shows (a reload failed);
    - a preview's / in-FL stems' live mutes are in FL (any project);
    - unless the user asked for this save (explicit: fl_save): the file - or a same-name/title twin FL's title could
      mean - changed on disk after FL last loaded or saved it."""
    try:
        if fl_running() and not _proven_open(project):
            cur = _open_project_guess()[0]                        # (a title naming this project too - a same-
            if cur and _ud_key(cur) != _ud_key(project) and not _title_is_one_of([project]):   # title twin - is
                # left to the twin guards below: FL's save lands in whichever of them it holds)
                return (f"not saved: FL shows {os.path.basename(cur)}, not {os.path.basename(project)}, so its save "
                        f"would write {os.path.basename(cur)} - fl_open('{project}') first")
    except Exception:                                             # noqa: BLE001 - the guards below still apply
        pass
    why = _stale_block(project) or _stale_block() or _preview_mutes_on(project) or _preview_mutes_on()
    if why:
        return why
    try:
        twins = _same_name_files(project)[1:]
    except Exception:                                             # noqa: BLE001
        twins = []
    for c in twins:                                               # FL's title could mean a twin: its guards too
        e = _stale_get(c)
        if e:
            return _stale_block(c)
    if not explicit:
        for c in [project] + twins:
            older = _fl_copy_older(c)
            if older:
                return older
    return None


RESAVE_AFTER_S = 3.0              # a save through FL that hasn't touched the file after this is sent once more


def _save_refused_why():
    """Why this thread's last _save_in_fl_and_wait was refused without asking FL (None: it wasn't refused)."""
    return getattr(_SAVE_TL, "why", None)


def _save_in_fl_and_wait(project, wait_s=8.0, stop=None, explicit=False):
    """Save the open project through FL and wait for the file to land: True / False. Refused (False without asking
    FL; _save_refused_why() says why) by _save_guard_why: FL shows another project, FL holds an older copy than the
    file (a reload failed), a preview's live mutes are in FL, or - unless the user asked for this save (explicit:
    fl_save) - the file changed on disk after FL last loaded or saved it (_fl_copy_older)."""
    _SAVE_TL.why = None
    why = _save_guard_why(project, explicit)
    if why:
        _SAVE_TL.why = why
        return False
    sv = getattr(_FRESH_TL, "saved", None) if getattr(_FRESH_TL, "on", False) else None
    if sv and sv[0] == _ud_key(project) and not explicit:         # this call's fresh-read save just wrote it, the
        try:                                                      # file is unchanged since and FL has nothing new:
            if tuple(_file_sig(project)) == sv[1] and _fl_changed_flag() == 0:   # no second save (heavy songs save
                return True                                       # slowly)
        except OSError:
            pass
    stop = stop or _VERIFY_STOP.is_set
    before = _file_sig(project)
    BRIDGE.call("transport", action="save")
    first = min(float(wait_s), RESAVE_AFTER_S)
    ok = _wait_saved(project, before, first, stop=stop)
    if not ok and float(wait_s) > first and not stop():
        try:
            unchanged = list(_file_sig(project)) == list(before)
        except OSError:
            unchanged = False
        if unchanged:                             # nothing landed: FL dropped it (just after a load FL ignores saves
            BRIDGE.call("transport", action="save")   # for a moment - PC 2026-10-24: fl_finalize's 'save FL first'
        ok = _wait_saved(project, before, float(wait_s) - first, stop=stop)   # waited 17 s for nothing): once more
    if ok:
        _note_open_proof(project)                                 # FL's save landed here: it's the open file
    return ok


def _verify_loaded(project, written, want, was_playing, pre=None, gen=None, since=None):
    """Prove FL holds the edit: let FL save what it has loaded and compare it with what was written (`want`) and
    with what FL held before the edit (`pre`).
    - FL's save == the edit (in every part the edit touched): verified; other differences are hand edits, kept.
    - FL's save == the version before the edit, exactly: FL ignored the reload. The edit is put back (FL's save is
      backed up first) and FL reloads once more.
    - anything else: FL's copy differs from both, i.e. it was changed by hand in FL right after the reload. Nothing
      is restored (that would throw the hand edits away); the edit is kept as a backup and reported.
    Every write and reload first checks that no newer edit wants FL (then it steps aside). Live changes made in FL
    since the reload (`since`: fl_plugin_set, fl_channel_set ...) are never thrown away by putting the edit back: the
    check then reports instead (PC 2026-10-27: a plugin gain set right after a sync was gone).
    The tempo lane is compared with a tolerance and the master tempo of a song with a lane isn't (_fp_differs)."""
    stepped_aside = {"verified": None, "verify_note": "a newer edit checks it"}
    stop = lambda: _VERIFY_STOP.is_set() or (gen is not None and _PENDING_VERIFY.get("__gen", 0) != gen)
    touched = [k for k in want if pre is None or _fp_differs(pre, want, k)]
    if not touched:                                              # nothing the check can see changed
        return {"verified": None, "checked": [],
                "verify_note": (f"FL reloaded the file, but this edit changed nothing the reload check compares "
                                f"({FINGERPRINT_PARTS}); {NOT_FINGERPRINTED} can't be checked this way - look or "
                                "listen in FL to confirm")}
    seen = {"checked": touched, "not_checked": NOT_FINGERPRINTED}
    bad = []
    for attempt in (1, 2):
        saved = False
        for _ in range(6):                                     # right after a load FL ignores saves for a few s
            if stop():
                return stepped_aside
            blocked = _stale_block(project)
            if blocked:                                           # FL holds an older copy: its save would undo edits
                return {"verified": None, "verify_note": blocked.replace("not saved:", "not checked:", 1)}
            _VERIFY_STOP.wait(1.0)                                # (a newer edit wanting FL ends the wait at once)
            if stop():
                return stepped_aside
            if _save_in_fl_and_wait(project, wait_s=3.0, stop=stop):
                saved = True; break
        if not saved:
            if stop():
                return stepped_aside
            return {"verified": None, "verify_note": "FL didn't save, so the reload couldn't be checked"}
        got = _fingerprint(project)
        bad = [k for k in want if _fp_differs(want, got, k)]
        if not bad:
            return dict(seen, verified=True) if attempt == 1 else dict(seen, verified=True, verify_note=(
                "FL had kept an old copy; reloaded it a second time"))
        if all(not _fp_differs(want, got, k) for k in touched):    # the edit is there; the rest was done by hand
            return {"verified": True, "hand_edits": bad, **seen,
                    "verify_note": f"FL holds the edit; its {', '.join(bad)} also changed by hand in FL (kept)"}
        reverted = pre is not None and all(not _fp_differs(pre, got, k) for k in want)
        live = _live_since(since) if since is not None else []
        if reverted and live:                                     # FL looks like it ignored the reload, but live
            kept = None                                           # changes went in since: putting the edit back
            try:                                                  # would throw them away - report, keep FL's state
                kept = _backup(project, data=written)
            except Exception:                                     # noqa: BLE001
                pass
            return {"verified": False, "live_kept": live, **seen,
                    "verify_note": (f"FL's save looks like the version from before the edit ({', '.join(bad)}), but "
                                    f"live changes were made in FL since the reload ({', '.join(live)}), so the edit "
                                    "wasn't put back over them: FL's state (with those changes) is in the file now"
                                    + ("; the edit is saved as a backup (flp_versions)" if kept else "")
                                    + ". Run the edit again - it goes on top of FL's state")}
        if not reverted:
            kept = None
            try:
                kept = _backup(project, data=written)               # the edit stays restorable
            except Exception:
                pass
            return {"verified": False, "hand_edits": True,
                    "verify_note": (f"FL's copy differs from both the edit and the version before it ({', '.join(bad)}): "
                                    "it was most likely changed by hand in FL right after the reload. Nothing was "
                                    "restored, so the hand edits are kept; the edit is saved as a backup"
                                    + (" (flp_versions / flp_restore)" if kept else "") + ". Check the project in FL")}
        if attempt == 2 or stop():
            break
        _backup(project)                                          # FL's save (== the version before the edit)
        _write_bytes(project, written)                          # FL's save just reverted the edit: restore it
        if stop():
            return stepped_aside
        try:
            _reload_in_fl(project)
        except Exception as e:
            _stale_mark(project, f"{type(e).__name__}: {e}", written)
            return {"verified": False, "verify_note": f"FL kept an old copy and couldn't be made to reload ({e}); the "
                                                      "edit is in the file and nothing saves FL over it - "
                                                      "fl_open(project) loads it (or File > Open it in FL, No to "
                                                      "'save changes?')"}
        time.sleep(1.5)
        t0 = time.time(); wait_load = _scaled(30.0)              # a slow PC loads slower
        while time.time() - t0 < wait_load and not stop():
            try:
                BRIDGE.call("ping"); break
            except Exception:
                time.sleep(0.5)
        if not was_playing and not stop():
            time.sleep(1.0)
            try:
                BRIDGE.call("transport", action="stop")
            except Exception:
                pass
    if stop():
        return stepped_aside
    live = _live_since(since) if since is not None else []
    if live:                                                      # (as above: FL's live changes are kept)
        return {"verified": False, "live_kept": live,
                "verify_note": (f"FL still showed an older {', '.join(bad)} after a second reload, and live changes "
                                f"were made in FL since ({', '.join(live)}), so nothing was put back over them; "
                                "run the edit again - it goes on top of FL's state")}
    _backup(project)
    _write_bytes(project, written)
    _stale_mark(project, f"FL kept an older {', '.join(bad)} after two reloads", written)   # FL still holds the old
    return {"verified": False, "verify_note": f"FL still shows an older {', '.join(bad)} after two reloads; the edit "   # copy: no save over the file
                                               "is back in the file - reopen the project in FL (File > Open)"}


def _write_bytes(path, data):
    writable(path)
    tmp = path + ".flh-tmp"
    try:
        with open(tmp, "wb") as f:
            f.write(data)
        # PC-VERIFY: the reload marker's write right after FL loaded / saved the song waits for FL to let go of the file
        # (WinError 5 seen on the PC) instead of failing at once (checklists/core.md 'locks')
        _retry_os_long(lambda: os.replace(tmp, path), _lock_wait_s(len(data)))
    except BaseException:
        try:
            os.remove(tmp)                                        # nothing left behind when the file stays locked
        except OSError:
            pass
        raise
    _forget_file(path)
    _note_wrote(path, data)



def _png_encode(w, h, rgb):
    """Minimal PNG (8-bit RGB) from raw rows - no imaging library needed."""
    import zlib
    raw = b"".join(b"\x00" + rgb[y * w * 3:(y + 1) * w * 3] for y in range(h))
    chunk = lambda t, b: struct.pack(">I", len(b)) + t + b + struct.pack(">I", zlib.crc32(t + b) & 0xFFFFFFFF)
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0))
            + chunk(b"IDAT", zlib.compress(raw, 6)) + chunk(b"IEND", b""))


def _bgra_crop_scale(buf, w, h, box, step):
    """Top-down BGRA pixels -> RGB bytes of the box (x0, y0, x1, y1 in pixels), keeping every `step`-th pixel."""
    x0, y0, x1, y1 = box; out_rows = []
    for y in range(y0, y1, step):
        row = buf[(y * w + x0) * 4:(y * w + x1) * 4]
        n = len(row[0::4 * step]); px = bytearray(n * 3)
        px[0::3] = row[2::4 * step]; px[1::3] = row[1::4 * step]; px[2::3] = row[0::4 * step]
        out_rows.append(bytes(px))
    return (len(out_rows[0]) // 3 if out_rows else 0), len(out_rows), b"".join(out_rows)


_SNAP_AREAS = {"window": (0, 0, 1, 1), "top": (0, 0, 1, 0.5), "bottom": (0, 0.5, 1, 1), "left": (0, 0, 0.5, 1),
               "right": (0.5, 0, 1, 1)}


def _snapshot_alt(title, size, focused=None, caption=None, popups=None, area="window"):
    """Alt text for a picture of FL: which window, what has focus, which popups are open."""
    bits = [f"Picture of FL Studio ({area}): window '{title}'" + (f", {size[0]}x{size[1]} pixels" if size else "")]
    if focused or caption:
        bits.append("focused: " + " - ".join(str(x) for x in (focused, caption) if x))
    pops = [p for p in (popups or []) if isinstance(p, dict)]
    if pops:
        bits.append("open popups: " + "; ".join(
            f"'{p.get('title')}'" + (f" saying '{' '.join(map(str, (p.get('text') or [])[:2]))[:120]}'" if p.get("text")
                                     else "") + (f" with buttons {', '.join(map(str, p.get('buttons') or []))}"
                                                 if p.get("buttons") else "") for p in pops[:4]))
    else:
        bits.append("no popups open")
    return ". ".join(bits) + "."


SNAP_BLANK_RETRY_S = (0.3, 0.6, 1.2)   # a blank capture (FL repainting right after a reload) is taken again after these


def _snap_has_pixels(data):
    """Any non-black pixel in a capture (BGRA bytes; alpha not looked at), ~120k pixels sampled over the window."""
    n = len(data or b"") // 4 * 4
    if not n:
        return False
    step = max(1, n // 4 // 120000) * 4
    for o in (0, step // 2 // 4 * 4):                             # two interleaved passes: thin lines are found too
        if any(data[p] or data[p + 1] or data[p + 2] for p in range(o, n - 3, step)):
            return True
    return False


def fl_snapshot(area="window", region=None, max_width=1400, save=False, hwnd=None):
    """A picture of FL's main window only (nothing else on the screen), so the playlist, mixer or a popup can be
    checked by eye without screen control. area: window|top|bottom|left|right, or region [x0, y0, x1, y1] as
    0..1 fractions of the window. Works while FL is behind other windows.
    The whole window is captured and the area / region cut from it; 'blank' is judged on the whole window (a dark
    corner of FL is no blank capture), and a blank one is taken again a few times (SNAP_BLANK_RETRY_S) - right after a
    reload FL repaints for a moment (PC 2026-10-27: region=... said 'blank' where a full snapshot a moment later
    worked). PC-VERIFY: fl_snapshot(region=[0, 0, 0.5, 0.3]) right after flh_sync's reload returns the picture."""
    import base64
    grab = _snap_grab
    if os.name != "nt" and getattr(grab, "__win__", False):
        raise RuntimeError("fl_snapshot needs Windows")
    if hwnd:                                                      # one of FL's popups (fl_dialog list gives hwnd)
        mine = {d["hwnd"]: d["title"] for d in fl_dialogs()}
        mine.update({w: t for w, t in _fl_windows()})
        if int(hwnd) not in mine:
            raise ValueError("that window isn't FL's (use an hwnd from fl_dialog list)")
        hw = (int(hwnd), mine[int(hwnd)])
    else:
        hw = _fl_main_window()
    if not hw:
        raise RuntimeError("FL isn't running")
    f = region or _SNAP_AREAS.get(area)
    if not f or len(f) != 4:
        raise ValueError(f"area is one of {sorted(_SNAP_AREAS)}, or give region [x0, y0, x1, y1] (0..1)")
    try:
        f = [float(x) for x in f]
    except (TypeError, ValueError):
        raise ValueError("region is [x0, y0, x1, y1] as numbers 0..1")
    if not (f[2] > f[0] and f[3] > f[1]):
        raise ValueError("region [x0, y0, x1, y1] needs x1 > x0 and y1 > y0 (0..1 fractions of FL's window)")
    w = h = 0; data = b""; tries = 0
    for wait in (0.0,) + tuple(SNAP_BLANK_RETRY_S):
        if wait:
            time.sleep(wait)
        tries += 1
        w, h, data = grab(hw[0])
        if w > 0 and h > 0 and _snap_has_pixels(data):
            break
    else:
        raise RuntimeError(f"FL's window came back blank {tries} times (it may be on a sleeping display or "
                           "minimized to a blank state); wake the display or bring FL up, then try again")
    box = (int(w * max(0.0, f[0])), int(h * max(0.0, f[1])), int(w * min(1.0, f[2])), int(h * min(1.0, f[3])))
    if box[2] <= box[0] or box[3] <= box[1]:
        raise ValueError("that region is empty at FL's window size")
    step = max(1, -(-(box[2] - box[0]) // int(max_width)))
    ow, oh, rgb = _bgra_crop_scale(data, w, h, box, step)
    png = _png_encode(ow, oh, rgb); out = {"window": hw[1], "size": [ow, oh], "_image_png": base64.b64encode(png).decode()}
    if tries > 1:
        out["note"] = f"FL's window came back blank at first (repainting); taken again ({tries} tries)"
    try:                                                          # words for screen-reader users (and the model)
        ctx = {}
        try:
            ctx = BRIDGE.call("context", timeout=2.0) or {}
        except Exception:
            pass
        out["alt"] = _snapshot_alt(hw[1], [ow, oh], ctx.get("focused"), ctx.get("focused_caption"),
                                   [d for d in fl_dialogs()], area if not region else "region")
    except Exception:
        pass
    if save:
        path = os.path.join(_mailbox_dir() or tempfile.gettempdir(), "..", "fl-snapshot.png")
        path = os.path.abspath(path)
        with open(path, "wb") as fh:
            fh.write(png)
        out["saved"] = path
    return out


def _snap_grab(hwnd):
    """FL's window `hwnd` as (width, height, top-down BGRA bytes), through PrintWindow (works while FL is behind other
    windows). Windows only."""
    import ctypes
    from ctypes import wintypes
    user32 = ctypes.windll.user32; gdi = ctypes.windll.gdi32
    if user32.IsIconic(hwnd):
        raise RuntimeError("FL is minimized; restore its window first")
    r = wintypes.RECT(); user32.GetWindowRect(hwnd, ctypes.byref(r)); w, h = r.right - r.left, r.bottom - r.top
    if w <= 0 or h <= 0:
        return 0, 0, b""
    wdc = user32.GetWindowDC(hwnd); mdc = gdi.CreateCompatibleDC(wdc); bmp = gdi.CreateCompatibleBitmap(wdc, w, h)
    old = gdi.SelectObject(mdc, bmp)
    try:
        if not user32.PrintWindow(hwnd, mdc, 2):                  # PW_RENDERFULLCONTENT
            user32.PrintWindow(hwnd, mdc, 0)
        class BIH(ctypes.Structure):
            _fields_ = [("biSize", wintypes.DWORD), ("biWidth", wintypes.LONG), ("biHeight", wintypes.LONG),
                        ("biPlanes", wintypes.WORD), ("biBitCount", wintypes.WORD), ("biCompression", wintypes.DWORD),
                        ("biSizeImage", wintypes.DWORD), ("biXPelsPerMeter", wintypes.LONG),
                        ("biYPelsPerMeter", wintypes.LONG), ("biClrUsed", wintypes.DWORD),
                        ("biClrImportant", wintypes.DWORD)]
        bih = BIH(ctypes.sizeof(BIH), w, -h, 1, 32, 0, 0, 0, 0, 0, 0)
        buf = ctypes.create_string_buffer(w * h * 4)
        gdi.GetDIBits(mdc, bmp, 0, h, buf, ctypes.byref(bih), 0)
        data = buf.raw
    finally:
        gdi.SelectObject(mdc, old); gdi.DeleteObject(bmp); gdi.DeleteDC(mdc); user32.ReleaseDC(hwnd, wdc)
    return w, h, data


_snap_grab.__win__ = True


_EDIT_DEPTH = 0                                                   # >0 inside flp_edit: one reload at the end
_EDIT_TL = threading.local()                                      # the same, per thread: a background flush of
                                                                  # queued edits must never see a foreground edit's depth


def _edit_enter():
    global _EDIT_DEPTH
    _EDIT_DEPTH += 1
    _EDIT_TL.v = getattr(_EDIT_TL, "v", 0) + 1


def _edit_exit():
    global _EDIT_DEPTH
    _EDIT_DEPTH = max(0, _EDIT_DEPTH - 1)
    _EDIT_TL.v = max(0, getattr(_EDIT_TL, "v", 0) - 1)


def _editing_here():
    """Inside an flp_edit / planned batch on THIS thread (its writes skip their own save+reload)."""
    return getattr(_EDIT_TL, "v", 0) > 0


def _with_open_project(project, output, fn, _pending_ok=True):
    """Run fn() (which writes `output`); if that's the project open in FL, reload it in place (save, edit, load in the
    same window). Only if the bridge isn't there: save + close FL and reopen it. Edits queued for `output` (lazy
    mode) are applied first, in the same save/reload, so their order is kept."""
    if _editing_here():
        return fn()
    if _pending_ok and output and _pending_get(output):
        return _with_queue_first(project, output, fn)
    same = bool(output) and os.path.normcase(os.path.abspath(output)) == os.path.normcase(os.path.abspath(project))
    running = same and fl_running()
    if same and not running:
        _fl_forget()                                              # FL isn't running: it holds no project
    if running:
        where = _open_state(project); why = _open_why(project) if where == "unknown" else None
        if where == "unknown" and not _title_stem(_main_title()):
            raise RuntimeError(f"can't tell whether FL has {os.path.basename(project)} open: {why}. Nothing was "
                               "changed (writing the file behind FL's back would be undone by FL's next save); retry "
                               "once FL shows the project's name")
        if where in ("open", "unknown"):                          # unknown: FL's title names it; a save proves which
            _HOT_MISS.clear()
            hot = _hot_reload(project, fn)
            if hot is _NOT_THIS or (hot is None and where == "unknown" and _HOT_MISS.get("never_saved")):
                _fl_forget(project)                               # FL's save showed it holds another file
                res = _as_edit(fn)                                # FL has another file / an unsaved new project open
                if isinstance(res, dict):
                    res["fl_has_open"] = (f"another file with this name ({_rel(_HOT_MISS['other'])})"
                                          if _HOT_MISS.get("other") else "a new, never-saved project with this name")
                    res.setdefault("note", "FL has a different project open, so the file was written directly "
                                           "(FL's save showed which file it holds)")
                return res
            if hot is not None:
                if isinstance(hot, dict) and hot.get("reloaded_in_fl") is True:
                    _note_fl_holds(project)                       # FL reloaded the file: it holds what's on disk
                return hot
            # never close FL to get at its project (house rule): stop and say so; nothing was changed
            if where == "unknown":
                raise RuntimeError(f"can't tell for sure whether FL has {os.path.basename(project)} open: {why}. FL "
                                   "was asked to save to find out, but the save didn't land in any of those files "
                                   "(FL busy, its bridge not answering, or the open project is a file outside "
                                   "FLH_ROOTS), so nothing was changed. Save in FL (Ctrl+S) and retry, or switch FL "
                                   "to the project first (fl_open)")
            raise RuntimeError(f"FL didn't save the open project in time, so nothing was changed: FL may be busy "
                               f"(loading, a popup: fl_dialog), or the project FL shows is another file named "
                               f"{os.path.basename(project)} outside FLH_ROOTS. Retry in a few seconds")
        _fl_forget(project)                                       # not_open: FL doesn't hold it (a later load is fresh)
    return _as_edit(fn)


def _with_queue_first(project, output, fn):
    """_with_open_project for a writer that runs while edits are queued for `output`: the queue goes first, in the
    same save/reload (order kept). Like _sync_pending: the FL lock, then one flush at a time; only the ops applied
    leave the queue (edits queued meanwhile stay)."""
    hold = False
    try:
        hold = fl_running()
    except Exception:
        pass
    if hold and not _fl_acquire():
        raise RuntimeError(f"FL is busy ({_fl_busy_with()}), so nothing was changed; try again when it's done")
    try:
        with _SYNC_RUN_LOCK:
            queued = _pending_take(output)
            if not queued:                                        # a flush just put them in
                return _with_open_project(project, output, fn, _pending_ok=False)
            ok = False
            try:
                plan, inner = _plan_ops(output, queued), fn

                def run():
                    orig = open(output, "rb").read()
                    try:
                        pre = _run_plan(output, plan)
                        r = inner()
                    except Exception:
                        _write_bytes(output, orig)
                        raise
                    if isinstance(r, dict):
                        r["queued_ops_applied_first"] = len(pre)
                    return r
                res = _with_open_project(project, output, run, _pending_ok=False)
                ok = True
                return res
            finally:
                _pending_done(output, queued, ok)
    finally:
        if hold:
            _FL_LOCK.release()


def flp_edit_notes(path, ops, output=None, pattern=None, channel=None, start_bar=None, end_bar=None, low=None,
                   high=None):
    """Edit the notes of one pattern with piano-roll style operations, applied in order to the selected notes
    (channel / bar range / pitch range). If the project is open in FL it is saved, edited and reopened.
    ops: [{"op": "quantize", "grid": "1/16", "strength": 0.6}, {"op": "fix_scale", "key": "G minor"}, ...]
    quantize(grid, strength, ends) tighten(strength 0.8, grid or "none" for rubato baked into notes, window|window_ms: chords land together, runs untouched) humanize(timing_ms, velocity, seed) transpose(semitones, octaves)
    fix_scale(key) velocity(set | scale | add | ramp:[from,to]) legato(gap_ticks) staccato(length)
    strum(ms, direction) arpeggiate(rate, mode up|down|updown|random, gate) swing(grid, amount 0.5-0.75)
    chop(grid) octave(octaves, double) harmonize(key, steps 2=third 5=sixth, above) invert(times) dedupe delete
    slide(on: true|false - FL slide notes, e.g. 808 glides)"""
    output = output or path
    def run():
        writable(output)
        d = _load(path); ev = _events(d); P = _ppq(d); pid = _pattern_id(d, ev, pattern)
        tempo = next((struct.unpack("<I", _payload(d, e))[0] / 1000 for e in ev if e["id"] == EV_TEMPO), 120.0)
        allnotes = list(map(_rec_to_note, _patterns(d, ev)[pid]["notes"]))
        sel = _select(allnotes, channel, start_bar, end_bar, low, high, P, _song_bar_ticks(d, ev, P))
        chosen = [n for n in allnotes if sel(n)]; rest = [n for n in allnotes if not sel(n)]
        before = len(chosen)
        meters = [(0,) + tuple(_project_meter(d, ev))]          # pattern time: the project's meter (swing pairs per beat)
        for op in ops:
            if str(op.get("op", "")).lower() == "slide":         # FL slide flag on/off for the selected notes
                on = bool(op.get("on", op.get("value", True)))
                chosen = [dict(n, slide=on) for n in chosen]
                continue
            chosen = fl_music.apply(chosen, op, P, tempo, meters=meters)
        _save(_write_pattern_notes(d, ev, pid, rest + chosen), output)
        return {"output": output, "pattern": pid, "selected": before, "after": len(chosen),
                "ops": [o.get("op") for o in ops]}
    return _with_open_project(path, output, run)


def flp_add_notes(path, notes, pattern=None, channel=0, output=None, replace=False):
    """Add notes to a pattern: [{note: "G4" | 67, bar: 1, beat: 0 (0-based, may be fractional), beats: 1,
    velocity: 100, slide: false}]; bar/beat are relative to the pattern start. slide=true writes an FL slide note.
    replace=true clears that channel first."""
    output = output or path
    def run():
        writable(output)
        d = _load(path); ev = _events(d); P = _ppq(d)
        pats = _patterns(d, ev)
        pid = _pattern_id(d, ev, pattern) if pattern is not None else (min(pats) if pats else 1)
        cur = list(map(_rec_to_note, pats.get(pid, {"notes": []})["notes"]))
        ch = int(channel)
        if replace:
            cur = [n for n in cur if n["ch"] != ch]
        tmpl = next((n["_r"] for n in cur if n["ch"] == ch), None) or next((n["_r"] for n in cur), None)
        bar_t = _song_bar_ticks(d, ev, P)                             # pattern bars follow the time signature
        new = []
        for x in notes:
            pos = int(round((float(x.get("bar", 1)) - 1) * bar_t + float(x.get("beat", 0)) * P))
            nd = {"pos": pos, "len": int(round(float(x.get("beats", 1)) * P)), "key": parse_note(x["note"]),
                  "vel": int(x.get("velocity", 100)), "ch": ch, "_r": tmpl}
            if "slide" in x or (tmpl and tmpl[1] & NOTE_SLIDE):           # never inherit a template's slide flag
                nd["slide"] = bool(x.get("slide"))
            new.append(nd)
        _save(_write_pattern_notes(d, ev, pid, cur + new), output)
        return {"output": output, "pattern": pid, "added": len(new), "channel": ch}
    return _with_open_project(path, output, run)


def _chords_by_segment(notes, seg):
    """fl_music.chords_by_segment with notes bucketed by segment: same result, O(notes) instead of
    O(segments x notes) (a 3-minute song with 30k notes took ~20 s)."""
    if not notes:
        return []
    end = max(n["pos"] + n["len"] for n in notes)
    nseg = len(range(0, end, seg))
    if nseg > 200000:                                             # a corrupt far note / endless note: only the bars
        return _chords_sparse(notes, seg)                         # where notes start are analyzed (bounded work)
    w = [[0.0] * 12 for _ in range(nseg)]; low = [None] * nseg
    for n in notes:
        a0, b0 = n["pos"], n["pos"] + n["len"]
        if b0 <= a0:
            continue
        for i in range(max(0, a0 // seg), min(nseg, -(-b0 // seg))):
            s = i * seg
            a, b = max(a0, s), min(b0, s + seg)
            if b > a:
                w[i][n["key"] % 12] += b - a
                if low[i] is None or n["key"] < low[i]:
                    low[i] = n["key"]
    return [(i * seg, fl_music.name_chord(w[i], low[i] % 12 if low[i] is not None else None)) for i in range(nseg)]


def _chords_sparse(notes, seg):
    """_chords_by_segment over the segments where notes start (plus one empty row after each gap)."""
    import bisect
    act = sorted({n["pos"] // seg for n in notes})
    w = {i: [0.0] * 12 for i in act}; low = {}
    for n in notes:
        a0, b0 = n["pos"], n["pos"] + n["len"]
        if b0 <= a0:
            continue
        for i in act[bisect.bisect_left(act, a0 // seg):bisect.bisect_left(act, -(-b0 // seg))]:
            a, b = max(a0, i * seg), min(b0, i * seg + seg)
            if b > a:
                w[i][n["key"] % 12] += b - a
                low[i] = min(low.get(i, n["key"]), n["key"])
    out, prev = [], None
    for i in act:
        if prev is not None and i > prev + 1:
            out.append(((prev + 1) * seg, fl_music.name_chord([0.0] * 12, None)))
        out.append((i * seg, fl_music.name_chord(w[i], low[i] % 12 if i in low else None))); prev = i
    return out


def _midi_meter_drums(path):
    """A MIDI file's time signatures [(tick, num, den)] (FF 58) and its GM drum notes (channel 10) as a Counter of
    (start tick, key) - for flp_analyze_music, which keeps drums out of the key and the chords."""
    from collections import Counter
    d = open(path, "rb").read()
    hl = struct.unpack(">I", d[4:8])[0]; ntr = struct.unpack(">H", d[10:12])[0]
    i = 8 + hl; meters = []; drums = Counter()
    for _ in range(ntr):
        if d[i:i + 4] != b"MTrk":
            break
        L = struct.unpack(">I", d[i + 4:i + 8])[0]; t = d[i + 8:i + 8 + L]; i += 8 + L
        j = tick = 0; run = None
        try:
            while j < len(t):
                dt, j = _vlq(t, j); tick += dt; b = t[j]
                if b == 0xFF:
                    typ = t[j + 1]; ln, j = _vlq(t, j + 2)
                    if typ == 0x58 and ln >= 2 and t[j] > 0:
                        meters.append((tick, int(t[j]), 1 << min(6, int(t[j + 1]))))
                    j += ln
                elif b in (0xF0, 0xF7):
                    ln, j = _vlq(t, j + 1); j += ln
                else:
                    if b & 0x80:
                        run = b; j += 1
                    if run is None:
                        break
                    if run & 0xF0 == 0x90 and run & 0x0F == 9 and t[j + 1] > 0:
                        drums[(tick, t[j])] += 1
                    j += 1 if run & 0xF0 in (0xC0, 0xD0) else 2
        except IndexError:                                      # a cut-off track: what was read counts
            pass
    out = []
    for tk, a, b in sorted(meters):
        if out and out[-1][0] == tk:
            out[-1] = (tk, a, b)
        elif not out or out[-1][1:] != (a, b):
            out.append((tk, a, b))
    return out, drums


def flp_analyze_music(path, pattern=None, channel=None, segment="bar"):
    """Music analysis of a project (whole song, or one pattern) or a MIDI file: key (top 3), chords per bar or
    half bar, note range and density per channel. A MIDI file's own time signature sets its bars; its GM drums
    (channel 10) are left out of the key and the chords."""
    midi_meters, harm = None, None
    if path.lower().endswith((".mid", ".midi")):
        div, raw, _ = midi_read(path); P = div
        notes = [{"pos": s, "len": e - s, "key": k, "vel": v, "ch": 0} for s, e, k, v in raw]
        midi_meters, drums = _midi_meter_drums(path)
        if drums:                                               # channel-10 hits: not pitches of the harmony
            left = dict(drums); harm = []
            for n in notes:
                k_ = (n["pos"], n["key"])
                if left.get(k_):
                    left[k_] -= 1
                else:
                    harm.append(n)
    else:
        d = _load(path); ev = _events(d); P = _ppq(d)
        if pattern is not None:
            notes = list(map(_rec_to_note, _patterns(d, ev)[_pattern_id(d, ev, pattern)]["notes"]))
        else:
            notes = [{"pos": p, "len": L, "key": k, "vel": v, "ch": c} for p, L, c, k, v in _song(d, ev)[0]]
    if channel is not None:
        notes = [n for n in notes if n["ch"] == int(channel)]
        harm = None if harm is None else [n for n in harm if n["ch"] == int(channel)]
    if not notes:
        raise ValueError("no notes to analyze")
    hn = harm if harm else notes                                # drums only: read what there is
    if path.lower().endswith((".mid", ".midi")):                # the file's own meter (FF 58), else 4/4
        num, den = midi_meters[0][1:] if midi_meters else (4, 4)
        bt = max(1, int(round(num * 4 * P / den)))
    else:
        bt = _song_bar_ticks(d, ev, P)                          # the project's bars
    seg = bt if segment == "bar" else max(1, bt // 2)
    chords = _chords_by_segment(hn, seg)
    prog = []
    for s, c in chords:
        label = f"{s // bt + 1}" + (f".{s % bt / P + 1:g}" if s % bt else "")
        if prog and prog[-1][1] == c:
            continue
        prog.append((label, c))
    per = {}
    for n in notes:
        e = per.setdefault(n["ch"], {"notes": 0, "low": 127, "high": 0})
        e["notes"] += 1; e["low"] = min(e["low"], n["key"]); e["high"] = max(e["high"], n["key"])
    bars = max(n["pos"] + n["len"] for n in notes) / bt
    sections = None
    if not path.lower().endswith((".mid", ".midi")) and pattern is None:
        pats = _patterns(d, ev)
        if sum(1 for v in pats.values() if v["notes"]) > 1:              # key per section (songs change key)
            sections = {}
            for pid, v in sorted(pats.items()):
                pn = [n for n in map(_rec_to_note, v["notes"]) if channel is None or n["ch"] == int(channel)]
                if pn:
                    sections[v["name"] or f"pattern {pid}"] = fl_music.detect_key(pn, 1)[0][0]
    res = {"key": fl_music.detect_key(hn), "key_by_section": sections, "chords": [f"{b}: {c or '-'}" for b, c in prog][:200],
           "channels": {ch: {"notes": v["notes"], "range": f"{note_name(v['low'])}-{note_name(v['high'])}",
                             "notes_per_bar": round(v["notes"] / max(bars, 1), 1)} for ch, v in per.items()},
           "bars": round(bars, 2)}
    if midi_meters is not None:
        res["meter"] = "%d/%d" % (midi_meters[0][1:] if midi_meters else (4, 4))
        if len(midi_meters) > 1:
            res["meter_note"] = ("the meter changes (" + ", ".join(f"{a}/{b} at tick {t}" for t, a, b in midi_meters[:6])
                                 + f"): bars are counted in {res['meter']} throughout")
        if harm is not None and len(harm) < len(notes):
            res["drums_skipped"] = len(notes) - len(harm)
    return res


def _playlist_anchor(d, ev):
    """(index, replace?) of the current arrangement's playlist clip event (233); an arrangement with no clips gets one
    after its header (99, its name 241, 36). PC-VERIFY: FL loads a playlist made this way."""
    a = _arrangement(d, ev)
    if a is None:
        raise ValueError("this project has no arrangement (playlist) yet: place any pattern in FL's playlist once")
    if a["playlist"] is not None:
        _clip_size(d, ev, _payload(d, ev[a["playlist"]]))           # refuse a playlist layout we can't read
        return a["playlist"], True
    j = a["first"] + 1
    while j < a["end"] and ev[j]["id"] in (241, 36):
        j += 1
    return j, False


def _place_pattern(d, pid, pos, length, track, offsets=None, muted=False):
    """Put a clip of pattern `pid` in the current arrangement's playlist. The clip record is copied from an existing
    pattern clip, else from FL's own clip record (fl_blocks), so empty projects work too. offsets: (start, end) of
    the clip's window in its pattern (default the pattern from 0); the new clip plays (not muted) unless muted."""
    import fl_blocks
    ev = _events(d)
    k, have = _playlist_anchor(d, ev)
    _, size, recs = _playlist_at(d, ev)
    tmpl = next((r for r in recs if struct.unpack("<H", r[6:8])[0] > PATTERN_BASE), None)
    if tmpl is None:                                              # PC-VERIFY: a pattern clip made from this record plays
        tmpl = _clip_template(fl_blocks.AUTOMATION_CLIP, size)
    r = bytearray(tmpl); pos, length = _clip_range(pos, length)
    r[0:4] = struct.pack("<I", int(pos)); r[6:8] = struct.pack("<H", PATTERN_BASE + pid)
    r[8:12] = struct.pack("<I", int(length)); r[12:14] = struct.pack("<H", 499 - (_check_track(track) - 1))
    s0, e0 = offsets if offsets else (0, int(length))
    r[24:28] = struct.pack("<I", int(s0)); r[28:32] = struct.pack("<I", int(e0))
    f_, = struct.unpack("<H", r[18:20])                           # the copied clip's mute bit is not this clip's
    struct.pack_into("<H", r, 18, (f_ | CLIP_MUTE) if muted else (f_ & ~CLIP_MUTE))
    if size >= 88:
        r[32:36] = struct.pack("<I", _next_clip_id([_clip_id(x, i) for i, x in enumerate(recs)]))
    return _put_clips(d, ev, recs + [r], k, have)


def flp_new_pattern(path, name, output=None, place_at_bar=None, length_bars=4, playlist_track=None):
    """Create a new empty, named pattern; optionally place it in the playlist at a bar."""
    output = output or path
    def run():
        writable(output)
        d = _load(path); P = _ppq(d)
        d, pid = _add_pattern(d, name)
        res = {"output": output, "pattern": pid, "name": name}
        if place_at_bar:
            track = _check_track(playlist_track) if playlist_track else _free_track(d)
            meters = _meter_map(d, _events(d)); at = _bar_to_tick(place_at_bar, meters, P)
            ln = _bar_to_tick(float(place_at_bar) + float(length_bars), meters, P) - at
            d = _place_pattern(d, pid, at, ln, track)
            res.update(placed_at_bar=float(place_at_bar), playlist_track=track)
        _save(d, output)
        return res
    return _with_open_project(path, output, run)


def flp_drum_pattern(path, style, channels, pattern=None, output=None, bars=4, ghost_notes=True, variation=True,
                     swing=None, humanize=True, key=60, seed=1):
    """Program a drum groove into a pattern. channels maps parts to channel indexes:
    {"kick": 0, "snare": 1, "clap": 2, "hat": 3, "openhat": 4, "perc": 5} (leave parts out to skip them).
    Styles: house, techno, trap, boombap, lofi, dnb, rock, pop, reggaeton, afrobeats. Every 4th bar gets a fill;
    the parts' channels are cleared in that pattern first."""
    output = output or path
    def run():
        writable(output)
        d = _load(path); ev = _events(d); P = _ppq(d)
        pid = _pattern_id(d, ev, pattern) if pattern is not None else None
        if pid is None:
            raise ValueError("give a pattern (create one with flp_new_pattern)")
        chs = {k: int(v) for k, v in channels.items() if v is not None}
        notes = fl_music.drum_notes(style, bars, P, chs, ghost_notes, variation, int(key), seed)
        sw = swing if swing is not None else fl_music.STYLE_DEFAULTS.get(style, {}).get("swing")
        if sw and float(sw) != 0.5:
            notes = fl_music.apply(notes, {"op": "swing", "grid": "1/16", "amount": float(sw)}, P)
        if humanize:
            notes = fl_music.apply(notes, {"op": "humanize", "timing_ms": 6, "velocity": 6, "seed": seed}, P)
        cur = [n for n in map(_rec_to_note, _patterns(d, ev).get(pid, {"notes": []})["notes"]) if n["ch"] not in chs.values()]
        tmpl = {ch: next((n["_r"] for n in map(_rec_to_note, _patterns(d, ev)[pid]["notes"]) if n["ch"] == ch), None)
                for ch in chs.values()}
        for n in notes:
            n["_r"] = tmpl.get(n["ch"])
        _save(_write_pattern_notes(d, ev, pid, cur + notes), output)
        return {"output": output, "pattern": pid, "style": style, "bars": int(bars), "notes": len(notes),
                "swing": sw, "parts": sorted(chs)}
    return _with_open_project(path, output, run)


def _expand_sample(p, project):
    try:
        fl_dir = os.path.dirname(fl_exe()) if IS_WINDOWS else ""
    except FileNotFoundError:
        fl_dir = ""
    user = _fl_userdata()
    q = p.replace("%FLStudioFactoryData%", fl_dir)
    if "%FLStudioUserData%" in q:                                 # FL's variable may name either level of the folder
        opts = [q.replace("%FLStudioUserData%", u) for u in (user, os.path.dirname(user)) if u]
        q = next((o for o in opts if os.path.exists(o)), opts[0] if opts else q)
    if "%FLStudioDownloadsData%" in q:                            # FL rewrites downloaded content (FLEX/Nebula packs)
        roots = []                                                # as ...\Image-Line\Downloads; Documents may be
        if user:                                                  # redirected (OneDrive), so try every candidate
            roots += [os.path.join(user, "Downloads"), os.path.join(os.path.dirname(user), "Downloads"),
                      os.path.join(os.path.dirname(os.path.dirname(user)), "Downloads")]
        try:
            kd = _known_documents()
        except Exception:
            kd = None
        kd = list(kd) if isinstance(kd, (list, tuple)) else [kd]
        for d in kd + [os.path.join(os.path.expanduser("~"), "Documents"),
                  os.path.join(os.path.expanduser("~"), "OneDrive", "Documents")]:
            if d and isinstance(d, str):
                roots.append(os.path.join(d, "Image-Line", "Downloads"))
        opts = [q.replace("%FLStudioDownloadsData%", r) for r in dict.fromkeys(roots)]
        q = next((o for o in opts if os.path.exists(o)), opts[0] if opts else q)
    if not os.path.isabs(q):
        q = os.path.join(os.path.dirname(os.path.abspath(project)), q)
    return q


def _wrapper_path(state):
    i = 0
    while True:
        i = state.find(b"\x37\x00\x00\x00", i)
        if i < 0 or i + 12 > len(state):
            return None
        n = struct.unpack("<Q", state[i + 4:i + 12])[0]; txt = state[i + 12:i + 12 + n]
        if 3 < n < 400 and all(32 <= c < 127 for c in txt):
            return txt.decode("ascii")
        i += 1


def flp_health(path):
    """Project health check: missing samples, VST plugins not installed, unused channels, empty or unplaced
    patterns, effect counts per mixer track, and size facts."""
    d = _load(path); ev = _events(d); P = _ppq(d); evs, chans, fx = _structure(d)
    pats = _patterns(d, ev); clips = _clips(d, ev)
    issues = []
    samples = []; cur = None
    for e in ev:
        if e["id"] == EV_CHANNEL:
            cur = struct.unpack("<H", _payload(d, e))[0]
        elif e["id"] == EV_SAMPLE_PATH and _payload(d, e).strip(b"\x00"):
            raw = _text16(_payload(d, e)); full = _expand_sample(raw, path)
            samples.append({"channel": cur, "path": raw, "found": os.path.isfile(full)})
    for sm in samples:
        if not sm["found"]:
            issues.append(f"missing sample on channel {sm['channel']}: {sm['path']}")
    plugins = []
    for c in chans.values():
        if c.get("plugin") == "Fruity Wrapper" and "state" in c:
            st = _payload(d, evs[c["state"]]); dll = _wrapper_path(st)
            ok = bool(dll and os.path.exists(dll)) if os.name == "nt" else None
            plugins.append({"channel": c["index"], "vst": _wrapper_name(st), "file": dll, "installed": ok})
            if ok is False:
                issues.append(f"VST not found for channel {c['index']} ({_wrapper_name(st)}): {dll}")
    for (t, sl), f in fx.items():
        if f.get("plugin") == "Fruity Wrapper" and "state" in f:
            st = _payload(d, evs[f["state"]]); dll = _wrapper_path(st)
            if os.name == "nt" and dll and not os.path.exists(dll):
                issues.append(f"VST effect not found on mixer track {t} slot {sl} ({_wrapper_name(st)}): {dll}")
    used = {r[2] for v in pats.values() for r in v["notes"]}
    used |= {struct.unpack("<H", r[6:8])[0] for _, _, r in clips if struct.unpack("<H", r[6:8])[0] < PATTERN_BASE}
    unused = [{"channel": c["index"], "name": c.get("name")} for c in chans.values() if c["index"] not in used]
    if unused:
        issues.append(f"{len(unused)} channel(s) never play: " + ", ".join(f"{u['channel']} {u['name'] or ''}".strip() for u in unused))
    placed = {struct.unpack("<H", r[6:8])[0] - PATTERN_BASE for _, _, r in clips if struct.unpack("<H", r[6:8])[0] > PATTERN_BASE}
    for pid, v in pats.items():
        tempo_only = not v["notes"] and v["ctrl"]
        if not v["notes"] and not tempo_only:
            issues.append(f"pattern {pid} '{v['name']}' is empty" + (" but placed in the playlist" if pid in placed else ""))
        elif pid not in placed:
            issues.append(f"pattern {pid} '{v['name']}' has notes but isn't in the playlist")
    per_track = {}
    for (t, sl) in fx:
        per_track[t] = per_track.get(t, 0) + 1
    heavy = {t: n for t, n in per_track.items() if n >= 6}
    if heavy:
        issues.append(f"mixer tracks with 6+ effects (CPU): {heavy}")
    return {"path": path, "ok": not issues, "issues": issues, "channels": len(chans), "patterns": len(pats),
            "playlist_clips": len(clips), "effects": len(fx), "samples": samples, "vst_plugins": plugins,
            "unused_channels": unused}


def _same_file(a, b):
    import hashlib
    try:
        if os.path.getsize(a) != os.path.getsize(b):
            return False
        h = lambda p: hashlib.sha1(open(p, "rb").read()).digest()
        return h(a) == h(b)
    except OSError:
        return False


def _collect_target(dest, full):
    """Where a sample goes in the collect folder: its own name, unless a DIFFERENT file already has that name
    there - then 'name (2).ext', 'name (3).ext'... (an identical copy is reused)."""
    stem, ext = os.path.splitext(os.path.basename(full))
    for n in range(1, 1000):
        cand = os.path.join(dest, (stem if n == 1 else f"{stem} ({n})") + ext)
        if not os.path.exists(cand) or _same_file(cand, full):
            return cand
    raise RuntimeError(f"too many different samples named {stem}{ext}")


def flp_collect_samples(path, output=None, folder="Samples"):
    """Copy every sample the project uses into a folder next to it and point the project at the copies, so the
    project folder is self-contained (portable / ready to back up or share)."""
    output = output or path
    def run():
        writable(output)
        d = _load(path); ev = _events(d)
        dest = os.path.join(os.path.dirname(os.path.abspath(output)), folder); writable(dest)
        edits = []; copied = []; missing = []; factory = []; renamed = {}; placed = {}

        def same(a, b):
            if os.path.getsize(a) != os.path.getsize(b):
                return False
            with open(a, "rb") as fa, open(b, "rb") as fb:
                while True:
                    x, y = fa.read(1 << 20), fb.read(1 << 20)
                    if x != y:
                        return False
                    if not x:
                        return True
        for k, e in enumerate(ev):
            if e["id"] != EV_SAMPLE_PATH or not _payload(d, e).strip(b"\x00"):
                continue
            raw = _text16(_payload(d, e))
            if "%FLStudioFactoryData%" in raw:                    # FL's own samples ship with every FL: keep the
                factory.append(raw); continue                     # reference (and never copy/redistribute them)
            full = _expand_sample(raw, path)
            if not os.path.isfile(full):
                missing.append(raw); continue
            if os.path.normcase(os.path.dirname(full)) == os.path.normcase(dest):
                continue
            os.makedirs(dest, exist_ok=True)
            key = os.path.normcase(os.path.abspath(full))
            target = placed.get(key)
            if target is None:                                    # same name, different sound: "kick (2).wav"
                stem, ext = os.path.splitext(os.path.basename(full)); n = 1
                target = os.path.join(dest, stem + ext)
                while os.path.exists(target) and not same(full, target):
                    n += 1; target = os.path.join(dest, f"{stem} ({n}){ext}")
                if not os.path.exists(target):
                    shutil.copy2(full, target)
                placed[key] = target
                if n > 1:
                    renamed[raw] = os.path.basename(target)
            edits.append((k, k + 1, _data_event(EV_SAMPLE_PATH, target.encode("utf-16-le") + b"\x00\x00")))
            copied.append(os.path.basename(target))
        _save(_splice(d, ev, edits), output)
        r = {"output": output, "folder": dest, "collected": sorted(set(copied)), "missing": missing}
        if renamed:
            r["renamed"] = renamed                                # different samples that shared a file name
        if factory:
            r["factory_samples_kept"] = len(factory)              # FL's own samples stay where FL keeps them
        return r
    return _with_open_project(path, output, run)


# ----------------------------------------------------------------------------- mixing helpers
def _channel_types(d, ev):
    out, cur = {}, None
    for k, e in enumerate(ev):
        if e["id"] == EV_CHANNEL:
            cur = struct.unpack("<H", _payload(d, e))[0]
            if k + 1 < len(ev) and ev[k + 1]["id"] == 21:
                out[cur] = _payload(d, ev[k + 1])[0]
    return out                                                   # 0 sampler, 2 plugin, 4 audio clip, 5 automation


def _stem_bytes(d, keep):
    """Project copy where only channel `keep` (or the channels in a set) makes sound (other channels' notes and audio
    clips removed; automation stays so the mix moves the same way)."""
    keep = set(keep) if isinstance(keep, (set, list, tuple, frozenset)) else {keep}
    ev = _events(d); types = _channel_types(d, ev); edits = []
    for k, e in enumerate(ev):
        if e["id"] == EV_NOTES and e["len"] % 24 == 0:
            p = _payload(d, e)
            recs = [p[i:i + 24] for i in range(0, len(p), 24) if struct.unpack("<H", p[i + 6:i + 8])[0] in keep]
            edits.append((k, k + 1, _data_event(EV_NOTES, b"".join(recs))))
        elif e["id"] == EV_PLAYLIST:
            p = _payload(d, e); recs = []; size = _clip_size(d, ev, p)
            for i in range(0, len(p), size):
                item = struct.unpack("<H", p[i + 6:i + 8])[0]
                if item < PATTERN_BASE and types.get(item) == 4 and item not in keep:
                    continue
                recs.append(p[i:i + size])
            edits.append((k, k + 1, _data_event(EV_PLAYLIST, b"".join(recs))))
    return _splice(d, ev, edits)


def _safe_name(text):
    return "".join(c for c in str(text) if c not in '<>:"/\\|?*').strip()


STEM_GROUPS = {"drums": ("kick", "snare", "clap", "hat", "openhat", "rim", "perc", "shaker", "ride", "crash", "tom",
                          "drums", "fx_drum", "drum", "hihat", "hihats", "hats", "hh", "oh", "kit", "fpc", "kik", "bd",
                          "snr", "cymbal", "tambourine", "conga", "bongo", "percussion", "breakbeat", "drum loop"),
               "bass": ("bass", "808", "sub", "boobass", "bassline", "subbass", "reese"),
               "vocals": ("vocal", "vocals", "voice", "vox", "adlib", "adlibs", "rap", "lead vocal", "backing vocal",
                          "vocal chop", "acapella", "acappella", "verse vox", "hook vox", "choir vox", "bv", "bvs")}
_STEM_PLUGIN = {"fpc": "drums", "fruity kick": "drums", "drumaxx": "drums", "fruity drumsynth live": "drums",
                "battery": "drums", "boobass": "bass"}


def _journal_get(project):
    st = sys.modules.get("flh_store")
    if st is None:
        try:
            import flh_store as st
        except Exception:
            return {}
    try:
        return st.journal_get(project) or {}
    except Exception:
        return {}


def _mixer_names(d, ev):
    """{mixer track: name} for named tracks (0 = Master)."""
    out = {}
    tr = [k for k, e in enumerate(ev) if e["id"] == EV_MIXER_TRACK]
    for t, k in enumerate(tr):
        a = k
        while a > 0 and ev[a - 1]["id"] in (EV_MIXER_COLOR, EV_MIXER_HASPROPS, EV_MIXER_NAME):
            a -= 1
        nm = next((_text16(_payload(d, ev[j])) for j in range(a, k) if ev[j]["id"] == EV_MIXER_NAME), "")
        if nm:
            out[t] = nm
    return out


def _stem_groups(project, d, ev, playing, groups):
    """[(name, set of channels)] for grouped stems: 'roles' (drums / bass / music / vocals by the song journal's
    channel roles, else channel names), 'instrumental' (everything but vocals, plus the vocals alone), or a list
    [{name, channels}]."""
    _, chans, _ = _structure(d)
    if isinstance(groups, list):
        return [(str(g["name"]), {int(c) for c in g["channels"]} & playing) for g in groups]
    try:
        ins, mix_names = _channel_inserts(d, ev), _mixer_names(d, ev)
    except Exception:                                             # noqa: BLE001 - names alone still work
        ins, mix_names = {}, {}
    try:
        jr = (_journal_get(project) or {}).get("channels") or {}
    except Exception:
        jr = {}
    def role_of(c):
        r = str((jr.get(str(c)) or {}).get("role") or "").lower()
        nm = str(chans.get(c, {}).get("name") or "").lower()
        toks = set(re.split(r"[^a-z0-9]+", nm)) - {""}           # 'Vocals_01', 'HH-closed', '808 (glide)'
        joined = " ".join(re.split(r"[^a-z0-9]+", nm)).strip()
        if r:
            for g, words in STEM_GROUPS.items():
                if r in words:
                    return g
            return "music"                                        # the journal's role decides
        for g in ("vocals", "bass", "drums"):
            words = STEM_GROUPS[g]
            if any((w in toks) if " " not in w else (w in joined) for w in words):
                if g == "bass" and toks & {"drum", "kick"}:       # 'Bass Drum' = a kick
                    return "drums"
                return g
        plug = str(chans.get(c, {}).get("plugin") or "").lower()
        if plug in _STEM_PLUGIN:
            return _STEM_PLUGIN[plug]
        mnm = str(mix_names.get(ins.get(c), "")).lower()           # a take 'Insert 2_03' on the mixer track 'Vocal'
        mt = set(re.split(r"[^a-z0-9]+", mnm)) - {""}
        for g in ("vocals", "bass", "drums"):
            if any(w in mt for w in STEM_GROUPS[g] if " " not in w):
                return g
        return "music"
    by = {}
    for c in sorted(playing):
        by.setdefault(role_of(c), set()).add(c)
    if str(groups).lower() in ("instrumental", "instrumental+vocals"):
        voc = by.get("vocals", set())
        out = [("Instrumental", set(playing) - voc)]
        if voc:
            out.append(("Vocals", voc))
        return out
    return [(g.capitalize(), by[g]) for g in ("drums", "bass", "music", "vocals") if by.get(g)]


def _stem_report(path, fs_x=None):
    """Level of a rendered stem (measured on this PC: nothing to download): lufs, peak, silent."""
    x, fs, _ = fs_x or _wav_load(path)
    m = _measure(x, fs)
    silent = m["peak_dbfs"] < -70
    return {"lufs": m["lufs"], "peak_dbfs": m["peak_dbfs"], "centroid_hz": m["centroid_hz"],
            **({"silent": True} if silent else {})}


def _instrument_pack_of(project, ch):
    """The downloaded INSTRUMENT pack a channel's saved state plays (its META family), or None."""
    try:
        d = _load(project); ev = _events(d)
        _, ks = _channel_block(d, ev, int(ch))
        st = _payload(d, ev[ks])
        m_ = re.search(rb'<META family="([^"]*)"', st)
        if not m_ or not _is_splice_instrument(_wrapper_name(st)):
            return None
        fam = m_.group(1).decode("utf-8", "replace").strip().lower()
        for x in flp_instrument_sounds()["packs"]:
            if re.sub(r"^(LABS|Spitfire Audio|Splice)\s*-\s*", "", x["pack"]).strip().lower() == fam:
                return x["pack"]
    except Exception:
        return None
    return None


def _clear_silent_pack(project, ch):
    """A channel rendered with sound: its INSTRUMENT pack is taken off the silent list (it plays on this PC)."""
    try:
        sp = dict((_state() or {}).get("silent_packs") or {})
        if not sp:
            return None
        pack = _instrument_pack_of(project, ch)
        if pack and pack in sp:
            sp.pop(pack)
            _state({"silent_packs": sp})
            return pack
    except Exception:
        return None
    return None


def _note_silent_pack(project, ch):
    """A channel rendered silent although it has notes: if it plays a LABS / INSTRUMENT pack, remember the pack so
    the catalog and new songs stop picking it (it probably isn't supported by the installed INSTRUMENT)."""
    try:
        jr = ((_journal_get(project) or {}).get("channels") or {}).get(str(ch)) or {}
    except Exception:
        jr = {}
    snd = str(jr.get("sound") or "")
    pack = snd.split(" / ")[0].strip() if ("INSTRUMENT" in str(jr.get("plugin") or "") or " / " in snd) else ""
    if not pack:                                  # switched with flp_instrument_sound: the journal doesn't know -
        pack = _instrument_pack_of(project, ch)   # the channel's own INSTRUMENT state says which pack
    if not pack:
        return None
    st = _state() or {}
    sp = dict(st.get("silent_packs") or {})
    sp[pack] = {"seen": time.strftime("%Y-%m-%d"), "project": os.path.basename(project), "channel": ch}
    _state({"silent_packs": sp})
    return pack


def _render_stems(project, output_dir, channels, formats, close_fl, reopen, groups=None, measure=True, method="auto"):
    n0 = _renders_here(); T0 = time.time()
    project = os.path.abspath(project); d = _load(project); ev = _events(d)
    _, chans, _ = _structure(d); types = _channel_types(d, ev)
    playing = {r[2] for v in _patterns(d, ev).values() for r in v["notes"]}
    playing |= {struct.unpack("<H", r[6:8])[0] for _, _, r in _clips(d, ev)
                if struct.unpack("<H", r[6:8])[0] < PATTERN_BASE and types.get(struct.unpack("<H", r[6:8])[0]) == 4}
    if channels is not None:
        playing &= {int(x) for x in channels}
    if groups:
        todo = [(nm, chs) for nm, chs in _stem_groups(project, d, ev, playing, groups) if chs]
    else:
        todo = [(_safe_name(chans.get(c, {}).get("name") or f"channel {c}"), {c}) for c in sorted(playing)]
    out_dir = os.path.abspath(output_dir or os.path.join(os.path.dirname(project), "Stems")); writable(out_dir)
    os.makedirs(out_dir, exist_ok=True)
    want = [f.strip().lower() for f in str(formats or "flac").split(",") if f.strip()]
    flac = "flac" in want
    render_fmt = ",".join(sorted(set(["wav"] if flac else []) | (set(want) - {"flac"}))) or "wav"
    if method in ("auto", "split") and set(want) <= {"flac", "wav"}:
        sp_ok, sp_why = _split_ready()
        if sp_ok and method == "split" or (sp_ok and (_state().get("in_fl_split") or {}).get("on") is True):
            try:
                return _render_stems_split(project, d, todo, groups, out_dir, want, measure)
            except InFlUnavailable as e:
                if method == "split":
                    raise RuntimeError(f"FL's split export didn't work: {e}") from e
        elif method == "split":
            raise RuntimeError(f"one-export stems aren't available: {sp_why}")
        method = "auto"
    route = _render_method(project, render_fmt, method)          # in_fl: FL's own export, others muted live
    if method == "auto" and route == "in_fl" and not (_state().get("in_fl_mutes_ok")):
        route = "cli"                                             # until a check proved FL's export follows live
                                                                  # mutes (fl_pc_check render.stems_in_fl)
    live, switched_from = {}, None
    if route == "in_fl":
        try:
            cur, _ = _open_project_guess()
            if not cur or _ud_key(cur) != _ud_key(project):        # its mutes are read from the open project
                switched_from = cur if cur and os.path.isfile(cur) else None
                fl_open(project)
                if not _wait_open_in_fl(project, 240):
                    raise InFlUnavailable(_open_fail(project))
            _sync_before("stems", project)                        # a reload later would drop the live mutes
            _live_mutes_ready(project, "stems")                   # FL shows it, no switch / merged reload pending
            live = {int(c["index"]): bool(c.get("muted")) for c in (fl_state().get("channels") or [])
                    if int(c.get("index", -1)) >= 0}
        except Exception as e:                                    # noqa: BLE001
            if not close_fl or method == "in_fl":                 # asked for the open FL: never close it instead
                raise RuntimeError(f"live stems in the open FL couldn't start ({e})") from e
            route = "cli"
    closed = None
    if route == "cli" and fl_running():
        if not close_fl:
            raise RuntimeError("FL is open; pass close_fl=true (or method='in_fl' to export from the open FL)")
        closed = fl_close(save=True)
    stems, report, silent_notes = [], [], []
    base = os.path.splitext(os.path.basename(project))[0]
    fallback = None
    autos = {c for c, t in types.items() if t == 5}             # never muted for a stem (automation stays)

    mute_warn = []

    def in_fl(chs, stem_name):
        # the same guards as fl_preview (PC 2026-10-23: live mutes went into another project when FL switched
        # mid-way): FL must show this project before muting and before unmuting, no save while they're on, the
        # unmutes read back (retried), a leftover reported and kept from being saved into the file
        muted = []; mk = _ud_key(project)
        # FL holds the file BEFORE the mutes go on (PC: a stems run failed mid-way with 'nothing was opened: ... muted
        # live' and left 10 channels muted - its export tried to prove / open the project with its own mutes on).
        # PC-VERIFY: a failed stem leaves no channel muted (checklists/core.md 'Release bug hunt: live layer' 3)
        _fl_load_file(project, "stems")
        if not _preview_fl_on(project):
            raise InFlUnavailable(f"FL doesn't show {os.path.basename(project)} (or is loading / switching), so no "
                                  "channel was muted")
        _PREVIEW_MUTES[mk] = {"project": project, "channels": muted, "active": True}   # no save while they're on
        try:
            for i, was in live.items():
                if i not in chs and not was and i not in autos:  # automation clips keep moving their targets
                    muted.append(i); fl_channel_set(i, muted=True)
            r = _render_in_fl(project, out_dir, render_fmt, 900, out_stem=stem_name)
            _split_drop(r.pop("split", None))                     # live mutes aren't in the file: not cached
            return r["rendered"]
        finally:
            left = []
            if muted:                                             # put back exactly what was changed - only into
                try:                                              # this project, read back
                    left = _preview_unmute(project, muted)
                except Exception:                                 # noqa: BLE001
                    left = None
            if left == []:
                _PREVIEW_MUTES.pop(mk, None)
            else:
                _PREVIEW_MUTES[mk] = {"project": project, "channels": list(left or muted), "active": False}
                mute_warn.append(f"stem '{stem_name}': channel(s) {list(left or muted)[:16]} muted for it couldn't "
                                 "be confirmed unmuted " + ("(FL no longer shows this project)" if left is None else
                                                           "(FL still reports them muted)"))
    try:
        for i, (nm, chs) in enumerate(todo):
            _job_progress(step="render stem", stem=nm, n=f"{i + 1}/{len(todo)}", method=route)
            tag = f"{min(chs):02d} {nm}" if not groups else nm
            got = None
            if route == "in_fl":
                try:
                    got = in_fl(chs, f"{base} - {tag}")
                    if mute_warn:                                 # a channel stayed muted: the next stems would be
                        raise RuntimeError(f"stems stopped after '{nm}': {mute_warn[-1]}. Unmute them in FL, then "
                                           "run fl_render_stems again; fl-headless won't save FL over this project "
                                           "until they are back")   # wrong, and the mutes must not reach the file
                except InFlUnavailable as e:
                    if i or not close_fl or method == "in_fl":     # half the stems one way, half the other: no
                        raise RuntimeError(f"FL's own export stopped at stem '{nm}': {e}") from e
                    fallback = f"FL's own export didn't start ({e}); used the command line"
                    route = "cli"
                    if fl_running():
                        closed = fl_close(save=True)
            if got is None:
                got = _render(project, out_dir, render_fmt, 900, data=_stem_bytes(d, chs),
                              out_stem=f"{base} - {tag}")["rendered"]
            entry = {"stem": nm, "channels": sorted(chs)}
            for f in got:
                if f.lower().endswith(".wav") and (measure or flac):
                    try:
                        xfs = _wav_load(f)
                    except Exception as e:                        # noqa: BLE001 - the stem is there; say why
                        entry["read_error"] = f"{type(e).__name__}: {e}"
                        stems.append(f)
                        continue
                    if measure:
                        entry.update(_stem_report(f, xfs))
                        if entry.get("silent") and len(chs) == 1:
                            pack = _note_silent_pack(project, min(chs))
                            silent_notes.append(f"channel {min(chs)} '{nm}' rendered silent although it has notes" +
                                                (f": its pack '{pack}' probably isn't supported by the installed "
                                                 "INSTRUMENT (noted: new songs and the catalog avoid it)" if pack else
                                                 ": the sound probably didn't load, or it has no notes in its playable "
                                                 "range - pick another sound (open its window in FL to check)"))
                        elif entry.get("silent"):
                            silent_notes.append(f"stem '{nm}' (channels {sorted(chs)[:16]}) rendered silent: its "
                                                "sounds probably didn't load - fl_render_stems without groups shows "
                                                "which channel")
                    if flac:
                        import numpy as np
                        import flac_lite
                        x = np.clip(xfs[0], -1, 1)
                        fp = f[:-4] + ".flac"
                        try:
                            flac_lite.encode(fp, np.round(x * 8388607).astype(np.int32), xfs[1], 24)
                        except Exception as e:                    # noqa: BLE001 - the WAV stays: nothing lost
                            entry["flac_error"] = f"{type(e).__name__}: {e} (kept the WAV)"
                            stems.append(f)
                            continue
                        if "wav" not in want:
                            os.remove(f); f = fp
                        stems.append(fp)
                        if "wav" in want:
                            stems.append(f)
                        continue
                stems.append(f)
            report.append(entry)
    except Exception as e:                                        # a stem failed: mutes put back for sure
        left = _stems_mutes_restore(project)
        if left:
            raise RuntimeError(f"{e}. ALSO: channel(s) {left[:16]} muted for the stems couldn't be confirmed unmuted "
                               "- unmute them in FL; fl-headless won't save FL over this project until they are "
                               "back") from e
        raise
    finally:
        if closed and reopen and closed.get("project") and os.path.isfile(closed["project"]):
            fl_open(closed["project"])
        elif switched_from and reopen and route == "in_fl":        # back to the song FL had open
            try:
                fl_open(switched_from)
            except Exception:                                     # noqa: BLE001
                pass
    res = {"stems": stems, "folder": out_dir, "levels": report, "method": route, "renders": _renders_here() - n0,
           "steps_s": {"total": round(time.time() - T0, 1)}}
    if fallback:
        res["fallback"] = fallback
    loud = [r for r in report if r.get("lufs") is not None]
    if loud:
        top = max(loud, key=lambda r: r["lufs"])
        buried = [r["stem"] for r in loud if r is not top and r["lufs"] < top["lufs"] - 25]
        if buried:
            res["buried"] = f"more than 25 LU under '{top['stem']}': {', '.join(buried)}"
    if silent_notes:
        res["silent"] = silent_notes
    if route == "in_fl" and len(loud) >= 2:                       # every stem the same = the whole mix each time
        L = [r["lufs"] for r in loud]; Cn = [r.get("centroid_hz") or 0 for r in loud]
        if max(L) - min(L) < 0.3 and max(Cn) - min(Cn) <= 0.03 * max(1, max(Cn)):
            res["warning"] = ("every stem measures the same, so FL's export probably ignored the live mutes and each "
                              "file holds the whole song: run fl_render_stems again with method='cli' (FL closes "
                              "once) and tell the fl-headless author")
            _state({"in_fl_mutes_ok": False})
    return res


def _stems_mutes_restore(project):
    """After a failed in-FL stems run: channels it muted that are still recorded as muted (its own put-back failed) get
    one more put-back (waits while FL loads). -> the channels still muted ([] = all back)."""
    e = _PREVIEW_MUTES.get(_ud_key(project))
    if not e or not e.get("channels"):
        _PREVIEW_MUTES.pop(_ud_key(project), None)
        return []
    e["active"] = False
    try:
        left = _preview_unmute(project, e["channels"])
    except Exception:                                             # noqa: BLE001
        left = None
    if left == []:
        _PREVIEW_MUTES.pop(_ud_key(project), None)
        return []
    e["channels"] = list(left or e["channels"])
    return e["channels"]


def _render_stems_split(project, d, todo, groups, out_dir, want, measure):
    """All stems from ONE in-FL export with 'Split mixer tracks': each stem = the mixer tracks its channels play
    into (a group = the sum of its tracks). A stem whose channels share a track with channels outside it can't be cut
    from per-track files: InFlUnavailable (the caller falls back to one export per stem)."""
    import numpy as np
    import flac_lite
    import fl_audio_edit as AE
    ins = {c: (0 if t < 0 else t) for c, t in _channel_inserts(d, _events(d)).items()}
    plan = []
    for nm, chs in todo:
        ts = sorted({ins[c] for c in chs if c in ins})
        if not ts or any(c not in ins for c in chs) or any(t == 0 or {c for c in ins if ins[c] == t} - set(chs)
                                                            for t in ts):
            raise InFlUnavailable(f"stem '{nm}' shares a mixer track with other channels")
        plan.append((nm, chs, ts))
    _sync_before("stems", project)
    if not _project_is_open(project):
        fl_open(project)
        if not _wait_open_in_fl(project, 240):
            raise InFlUnavailable(_open_fail(project))
    _rc_project_fp(project, live=True)                            # FL saved first when it had changes
    work = _own_temp("flh_stems_"); T = time.time(); n0 = _renders_here()
    try:
        r = _render_in_fl(project, work, "wav", 1800, out_stem="mix", split=True)
        sp = r.get("split")
        if not sp:
            mix = (r.get("rendered") or [None])[0]
            if mix:
                _quiet_rm(mix)
            raise InFlUnavailable("FL wrote one file, not one per mixer track ('Split mixer tracks' is off)")
        files = sp["files"]; base = os.path.splitext(os.path.basename(project))[0]
        stems, report = [], []
        for nm, chs, ts in plan:
            if any(t not in files for t in ts):
                report.append({"stem": nm, "channels": sorted(chs), "error": "FL wrote no file for its mixer track"})
                continue
            acc, fs, bits = None, None, 24
            for t in ts:
                x, fs, bits = _wav_load(files[t])
                acc = x if acc is None else _rc()._add(acc, x)
            tag = f"{min(chs):02d} {nm}" if not groups else nm
            entry = {"stem": nm, "channels": sorted(chs), "mixer_tracks": ts}
            if measure:
                entry.update(_stem_report(None, (acc, fs, bits)))
            for fmt in want:
                dst = _render_dest(out_dir, f"{base} - {tag}", "." + fmt)
                if fmt == "flac":
                    flac_lite.encode(dst, np.round(np.clip(acc, -1, 1) * 8388607).astype(np.int32), fs, 24)
                elif fmt == "wav":
                    AE.save(dst, acc, fs, 24 if bits != 16 else 16)
                else:
                    continue
                _note_render(dst); stems.append(dst)
            report.append(entry)
        n_split = len(files)
        _rc_store_split(project, sp, "in_fl")                     # and the cache keeps them for offline mixing
        res = {"stems": stems, "folder": out_dir, "levels": report, "method": "split",
               "note": f"one export with FL's 'Split mixer tracks' ({n_split} track files): each stem is its channels' "
                       "mixer track(s) - insert effects in, bus and master effects not",
               "renders": _renders_here() - n0, "steps_s": {"split_export_and_write": round(time.time() - T, 1)}}
        mix = (r.get("rendered") or [None])[0]
        if mix:
            _quiet_rm(mix)
        return res
    finally:
        _own_temp_done(work)


def _quiet_rm(path):
    try:
        os.remove(path)
    except OSError:
        pass


def fl_render_stems(project, output_dir=None, channels=None, formats="flac", close_fl=True, reopen=True, groups=None,
                    measure=True, method="auto"):
    """Render one stem per channel that plays (others silenced, automation kept) - or grouped stems: groups='roles'
    (drums / bass / music / vocals), 'instrumental' (everything but vocals + the vocals alone), or [{name, channels}] -
    as a background job (fl_job). FLAC by default (24-bit, ~half a WAV's size); each stem's level is measured here
    (lufs, peak, silent) so nothing has to be downloaded to check them. Default folder: 'Stems' next to the project.
    method: auto (ONE in-FL export with 'Split mixer tracks' once FL is seen splitting; else FL's own export in the
    open FL with the other channels muted live, once fl_pc_check has shown that works on this PC - FL stays open;
    else the command line, which closes FL once for all stems) | split | in_fl | cli.
    PC-VERIFY: in_fl stems - each stem holds only its channels and the user's mutes are back afterwards."""
    return _start_job("stems", _render_stems, project, output_dir, channels, formats, close_fl, reopen, groups,
                      measure, method, fl=True)


PREVIEW_TITLE_WAIT_S = 6.0                                       # FL's title naming the open song (scaled per PC)
PREVIEW_LOADING_WAIT_S = 20.0                                    # ... longer while the title names no song yet


def _preview_project():
    """The .flp FL has open, for fl_preview -> (path, how). FL's title is mapped to a file by _open_project_guess;
    when that can't tell (several files with that name, the title still settling on a slow PC), the project
    fl-headless itself last opened in FL counts when FL's title names it. While FL's title names no song or FL's
    default name (FL still loading), waits up to PREVIEW_LOADING_WAIT_S (scaled); an untitled project FL isn't busy
    with ends sooner. Raises with what FL's title shows."""
    t0 = time.time(); short = _scaled(PREVIEW_TITLE_WAIT_S); long_ = max(short, _scaled(PREVIEW_LOADING_WAIT_S))
    mt = ""
    while True:
        try:
            cur, _ = _open_project_guess()
        except Exception:
            cur = None
        if cur and os.path.isfile(cur):
            return cur, "FL's title"
        mt = _main_title(); stem = _title_stem(mt)
        try:
            last = _state().get("last_opened")
        except Exception:
            last = None
        if stem and not _is_untitled(mt) and last and os.path.isfile(last) and stem.lower() in _project_names(last):
            return os.path.abspath(last), "the project fl-headless last opened (FL's title names it)"
        loading = not stem or _is_untitled(mt)
        waited = time.time() - t0
        if waited >= long_ or (waited >= short and not (loading and (last or _fl_still_working()))):
            break
        time.sleep(0.5)
    why = _GUESS_WHY.get("why")
    shows = f"FL's title is '{mt}'" if mt else "FL's window title names no project"
    raise RuntimeError(f"FL's open project has no file yet (save it once), so it can't be exported ({shows}"
                       + (f"; {why}" if why else "") + ")")


_PREVIEW_MUTES = {}               # ud key -> {project, channels, active}: channels fl_preview muted live and hasn't
                                  # seen back unmuted in FL yet
PREVIEW_UNMUTE_TRIES = 3          # unmute + read back through fl_state, this many rounds


def _preview_fl_on(project, wait_s=None):
    """True when FL shows `project` and isn't loading (waits up to wait_s - default PREVIEW_LOADING_WAIT_S, scaled -
    while FL loads or an fl_open is still switching); False when FL shows another project / stays busy."""
    t0 = time.time(); wait_s = _scaled(PREVIEW_LOADING_WAIT_S) if wait_s is None else float(wait_s)
    while True:
        pend = _open_pending_now()                                # an fl_open not landed yet
        loading = bool(_fl_loading_title()) or bool(pend and _ud_key(pend) != _ud_key(project))
        if not loading and (_title_is_one_of([project]) or _open_state(project) == "open"):
            return True
        if time.time() - t0 >= wait_s:
            return False
        time.sleep(0.25)


def _live_mutes_ready(project, what="preview"):
    """Before live mutes (fl_preview, fl_render_stems in FL): no fl_open still switching, no merged reload going in,
    and FL showing `project` (waits while FL loads). Raises with the reason - nothing was muted."""
    pend = _open_pending_now()
    if pend and _ud_key(pend) != _ud_key(project):
        raise RuntimeError(f"FL is still switching to {os.path.basename(pend)} (fl_open), so nothing was muted for "
                           f"the {what}; try again once FL shows {os.path.basename(project)}")
    if _INFLIGHT.get(_ud_key(project)):
        raise RuntimeError(f"queued edits of this project are going into FL right now (a merged reload), so nothing "
                           f"was muted for the {what}; try again in a few seconds")
    if not _preview_fl_on(project):
        raise RuntimeError(f"FL is still loading, or shows another project (FL's title: '{_main_title()}'), so "
                           f"nothing was muted for the {what}; try again once FL shows {os.path.basename(project)}")


def _preview_unmute(project, chans, wait_s=None):
    """Unmute fl_preview's channels live - only while FL shows `project` (never into another project) - and read them
    back through fl_state, retrying. -> the channels still muted ([] = all back), or None when FL doesn't show the
    project (nothing sent)."""
    left = sorted({int(c) for c in chans})
    for _ in range(max(1, PREVIEW_UNMUTE_TRIES)):
        if not left:
            break
        if not _preview_fl_on(project, wait_s):
            return None
        for i in left:
            try:
                fl_channel_set(i, muted=False)
            except Exception:                                     # noqa: BLE001 - read back below
                pass
        try:
            st = fl_state()
            muted = {int(c.get("index", -1)) for c in st.get("channels") or [] if c.get("muted")}
            left = [i for i in left if i in muted]
        except Exception:                                         # noqa: BLE001 - not confirmed: still counts
            pass
    return left


def _preview_mutes_on(project=None):
    """Why FL must not be saved now (a save would write fl_preview's live mutes into the file), or None: a preview
    is muting channels right now, or an earlier one couldn't confirm it put them back and FL still shows that
    project. A leftover is first put back (unmuted live, read back through fl_state) when FL shows its project.
    project: only that project's mutes (default: any project FL's title names)."""
    for k, e in list(_PREVIEW_MUTES.items()):
        if project is not None and k != _ud_key(project):
            continue
        if not e.get("active"):
            if not (_title_is_one_of([e["project"]]) or _open_state(e["project"]) == "open"):
                continue                                          # FL shows another project: not in its copy
            try:
                left = _preview_unmute(e["project"], e["channels"], wait_s=0)
            except Exception:                                     # noqa: BLE001
                left = None
            if left == []:
                _PREVIEW_MUTES.pop(k, None)
                continue
            if left:
                e["channels"] = left
        return (f"not saved: fl_preview has channel(s) {e['channels'][:16]} of {os.path.basename(e['project'])} muted "
                "live" + (" for its render" if e.get("active") else " and couldn't confirm they were put back")
                + ", and a save through FL would write those mutes into the file. Unmute them in FL (or run "
                "fl_preview again with that project open), then save")
    return None


def _live_mutes_active(project=None):
    """The _PREVIEW_MUTES entry of a solo preview / in-FL stem whose live mutes are on right now (any project, or only
    `project`'s), else None. While it is, FL must not load or open anything: a load drops the live mutes (the 'solo'
    export would be the whole mix)."""
    for k, e in list(_PREVIEW_MUTES.items()):
        if e.get("active") and (project is None or k == _ud_key(project)):
            return e
    return None


def _live_mutes_intact(project):
    """Right before FL's export: None when the channels muted live for this solo render are still muted in FL (or
    none are), else why not (FL reloaded / switched meanwhile, or its state can't be read): the export would not be
    the solo it claims. PC-VERIFY: fl_state reports a live-muted channel as muted right before the export
    (checklists/core.md 'solo renders')."""
    e = _PREVIEW_MUTES.get(_ud_key(project))
    if not e or not e.get("active") or not e.get("channels"):
        return None
    try:
        st = fl_state()
    except Exception as ex:                                       # noqa: BLE001
        return f"FL's channel mutes couldn't be read back before the export ({type(ex).__name__}: {ex})"
    muted = {int(c.get("index", -1)) for c in st.get("channels") or [] if c.get("muted")}
    gone = [i for i in e["channels"] if i not in muted]
    if gone:
        return (f"channel(s) {gone[:16]} muted live for this solo render are no longer muted in FL (FL reloaded or "
                "switched the project meanwhile), so the export would be the whole mix: nothing was rendered")
    return None


def _automation_channels(d):
    """Channel indices of automation clips in project bytes `d` (type 5): a solo render never mutes them - a muted
    automation clip stops moving its target (sidechain ducks, filter sweeps, volume rides)."""
    if d is None:
        return set()
    try:
        return {c for c, t in _channel_types(d, _events(d)).items() if t == 5}
    except Exception:                                             # noqa: BLE001 - unreadable: nothing skipped
        return set()


SILENT_HINT = ("renders silent: the sound probably didn't load, or it has no notes in its playable range (a pack the "
               "installed plugin doesn't support, a patch with no keys there) - pick another sound")


def _channel_plays(d, ch, start_bar=None, end_bar=None):
    """True when the song plays at least one note of channel `ch` (unmuted pattern clips) between start_bar and
    end_bar (None = the song's start / end); None when the file can't say."""
    try:
        ev = _events(d); P = _ppq(d); meters = _meter_map(d, ev); pats = _patterns(d, ev)
        t0 = _bar_to_tick(start_bar, meters, P) if start_bar else 0
        t1 = _bar_to_tick(end_bar, meters, P) if end_bar else None
        for _, _, r in _clips(d, ev):
            item = struct.unpack("<H", r[6:8])[0]
            if item < PATTERN_BASE or struct.unpack("<H", r[18:20])[0] & CLIP_MUTE:
                continue
            pat = pats.get(item - PATTERN_BASE)
            if not pat:
                continue
            pos = struct.unpack("<I", r[0:4])[0]; ln = struct.unpack("<I", r[8:12])[0]; s0 = _clip_offsets(r)[0]
            for n in pat["notes"]:
                if n[2] != ch or not (s0 <= n[0] < s0 + ln):
                    continue
                st = pos + n[0] - s0; en = st + max(1, n[3])
                if en > t0 and (t1 is None or st < t1):
                    return True
        return False
    except Exception:                                             # noqa: BLE001
        return None


def _silent_channel_hint(project, d, chans, rng=None):
    """Hints for channels that rendered silent alone; a LABS / INSTRUMENT pack among them is noted (silent_packs) so
    the sound catalog and new songs rank it down - only when the channel has notes in what was rendered (a channel
    with nothing to play is silent for that reason, not because its sound failed)."""
    try:
        names = _structure(d)[1] if d is not None else {}
    except Exception:                                             # noqa: BLE001
        names = {}
    out = []
    for c in sorted(chans):
        nm = (names.get(c) or {}).get("name") or f"channel {c}"
        plays = _channel_plays(d, c, (rng or {}).get("start_bar"), (rng or {}).get("end_bar")) if d is not None else None
        if plays is False:
            out.append(f"channel {c} '{nm}' has no notes playing " + ("in this range" if rng else "in the song") +
                       ": nothing to hear (its sound wasn't tested)")
            continue
        pack = _note_silent_pack(project, c) if len(chans) == 1 else None
        out.append(f"channel {c} '{nm}' {SILENT_HINT}" + (f" (its pack '{pack}' is noted: the catalog and new songs "
                                                           "rank it down)" if pack else ""))
    return out


PREVIEW_FORMATS = ("wav", "mp3", "flac")
PREVIEW_AUDIO = (".wav", ".mp3", ".flac")
PREVIEW_TAIL_S = 1.0              # a bar-range preview's FILE runs this much past end_bar (the last notes ring out);
                                  # its numbers cover the range only
PREVIEW_FADE_S = (0.005, 0.03)    # fade in / out at a WAV / FLAC range cut (no click); an MP3 cut is FL's frames as-is


def _preview_range(project, d, start_bar=None, end_bar=None, section=None):
    """fl_preview's bar range -> {start_bar, end_bar (None: to the song's end), section?, section_from?} or None for
    the whole song. section: a playlist marker's name (that marker to the next one), else a section of the song's
    journal; the exact name first, then a name starting with it (case-insensitive). end_bar is where it stops."""
    if section is None and start_bar is None and end_bar is None:
        return None
    out = {}
    if section is not None:
        if start_bar is not None or end_bar is not None:
            raise ValueError("give section OR start_bar / end_bar, not both")
        name = str(section).strip(); low = name.lower()
        if not low:
            raise ValueError("section: the name of a playlist marker (or of a section in the song's journal)")
        ev = _events(d); P = _ppq(d); meters = _meter_map(d, ev)
        mks = sorted((mk for mk in _markers(d, ev) if not mk.get("signature") and str(mk.get("name") or "").strip()),
                     key=lambda mk: mk["tick"])
        nm = lambda s: str(s).strip().lower()
        hits = [k for k, mk in enumerate(mks) if nm(mk["name"]) == low] or \
               [k for k, mk in enumerate(mks) if nm(mk["name"]).startswith(low)]
        jsecs = []
        if hits:
            k = hits[0]
            start_bar = _tick_to_bar(mks[k]["tick"], meters, P)
            end_bar = _tick_to_bar(mks[k + 1]["tick"], meters, P) if k + 1 < len(mks) else None
            out.update(section=mks[k]["name"], section_from="playlist marker")
            if len(hits) > 1:
                out["section_note"] = (f"{len(hits)} markers match '{name}': the first one (bar {start_bar:g}); "
                                       "start_bar / end_bar for another")
        else:
            try:
                import flh_store
                jsecs = sorted((s for s in (flh_store.journal_get(project) or {}).get("sections") or []
                                if isinstance(s, dict) and s.get("name") and s.get("bar") is not None),
                               key=lambda s: float(s["bar"]))
            except Exception:                                     # noqa: BLE001 - no journal: markers only
                jsecs = []
            js = [k for k, s in enumerate(jsecs) if nm(s["name"]) == low] or \
                 [k for k, s in enumerate(jsecs) if nm(s["name"]).startswith(low)]
            if not js:
                raise ValueError(f"no section '{name}': playlist markers {[mk['name'] for mk in mks][:20]}, journal "
                                 f"sections {[s['name'] for s in jsecs][:20]} - or give start_bar / end_bar")
            s = jsecs[js[0]]
            start_bar = float(s["bar"])
            end_bar = s.get("end_bar") or (jsecs[js[0] + 1]["bar"] if js[0] + 1 < len(jsecs) else None)
            out.update(section=s["name"], section_from="song journal")
    a = 1.0 if start_bar is None else float(start_bar)
    b = None if end_bar is None else float(end_bar)
    if a < 1:
        raise ValueError("start_bar: 1 or later (bar 1 is where the song starts)")
    if b is not None and b <= a:
        raise ValueError("end_bar must be after start_bar (end_bar is the bar where the preview stops)")
    out.update(start_bar=round(a, 3), end_bar=None if b is None else round(b, 3))
    return out


def _preview_clear(out_dir, keep=()):
    """Earlier previews in the song's '_preview' folder (fl-headless's own folder) go: one preview at a time."""
    keep = {os.path.normcase(os.path.abspath(p)) for p in keep if p}
    for old in glob.glob(os.path.join(glob.escape(out_dir), "*")):
        if old.lower().endswith(PREVIEW_AUDIO) and os.path.normcase(os.path.abspath(old)) not in keep:
            try:
                os.remove(old)
            except OSError:
                pass


def _preview_short(project, audio_s):
    """(render s, song s) when a render is clearly shorter than the song (FL's export stopped early: a playlist time
    selection or a loop / stop marker), else None."""
    try:
        song = _song_seconds(project)[0]
    except Exception:                                             # noqa: BLE001 - no model, no check
        return None
    if audio_s and song and audio_s < song - max(RENDER_SHORT_TOL_S, RENDER_SHORT_TOL_FRAC * song):
        return round(audio_s, 2), round(song, 2)
    return None


def fl_preview(channels=None, measure=True, keep=None, rules=None, timeout_s=900, exact=False, format="wav",
               start_bar=None, end_bar=None, section=None):
    """Hear (measure) the song - or only some channels, or only some bars - with FL's own export in the open FL: no
    closing. channels: only these play (the others are muted live for the render, then put back as they were).
    format: wav | mp3 | flac. mp3 is FL's own MP3 export (Ctrl+Shift+R, FL's last MP3 settings): one export, nothing
    converted here - the small file to send. Its numbers come from a WAV FL wrote beside it (export window with both
    formats ticked) or from decoding the MP3 (Windows' decoder); where neither works, measure_skipped says so.
    start_bar / end_bar (end_bar: where it stops; default the song's end) or section (a playlist marker's name, else a
    journal section): only that range. FL's export always renders the whole song, so the range is CUT from the
    whole-song render - from the render cache when the song is unchanged since a render of that format (no export at
    all), else from one fresh export; WAV / FLAC are cut sample-exact (short fades), an MP3 at frame boundaries with
    no re-encode. The file runs PREVIEW_TAIL_S past the range; the numbers cover the range only.
    keep (default true for mp3, else false): the file goes to '_preview' next to the song as '<song> preview.<ext>'
    (replacing the last preview) -> share_path / share_bytes. Nothing is exported again when the song is unchanged
    since an earlier render of that format (reused); after fader / pan changes only, whole-song numbers are mixed
    offline from cached stems when there are some (exact=true always renders). FL is saved first when it has unsaved
    changes (so the cache sees them).
    PC-VERIFY: FL's export renders the live channel mutes (not saved to the file)."""
    fmt = str(format or "wav").strip().lower().lstrip(".")
    fmt = "wav" if fmt == "wave" else fmt
    if fmt not in PREVIEW_FORMATS:
        raise ValueError(f"format: {' | '.join(PREVIEW_FORMATS)} (got '{format}')")
    keep = (fmt == "mp3") if keep is None else bool(keep)
    if not fl_running():
        raise RuntimeError("FL isn't open")
    # a slow PC still loading the song shows no name yet (PC 2026-10-22, 2 cores: 'no file yet' right after the bench
    # opened it; 2026-10-23: sound.shape right after the check opened its sandbox song)
    T_ = time.time()
    cur, cur_how = _preview_project()
    T0 = time.time(); n0 = _renders_here(); steps = {}
    if T0 - T_ > 1.0 or cur_how != "FL's title":
        steps["find_project"] = round(T0 - T_, 2)
    out_dir = os.path.join(os.path.dirname(cur), "_preview"); writable(os.path.join(out_dir, "x.wav"))
    # never while FL is still switching (an fl_open not landed yet) or loading: live mutes would go to the wrong
    # project (PC 2026-10-23: preview mutes stayed in a song, and a later preview's save wrote them into its file)
    if not _preview_fl_on(cur):
        pend = _OPEN_PENDING.get("project")
        raise RuntimeError("FL is " + (f"still switching to {os.path.basename(pend)} (fl_open)" if pend and
                                       _ud_key(pend) != _ud_key(cur) else "still loading, or shows another project")
                           + f", so nothing was previewed (FL's title: '{_main_title()}'); try again once FL shows "
                           f"{os.path.basename(cur)}")
    _sync_before("preview", cur)                                  # now: a reload during the export drops live mutes
    if _INFLIGHT.get(_ud_key(cur)):
        raise RuntimeError("queued edits of this project are going into FL right now (a merged reload), so nothing "
                           "was previewed; try again in a few seconds")
    RC = _rc()
    sel = sorted({int(c) for c in channels}) if channels is not None else None
    fp, cnote = _rc_project_fp(cur, live=True)
    key = None
    if fp:                                                        # the format is part of the key (wav as before)
        key = RC.solo_key(fp, sel, formats=fmt) if sel is not None else RC.mix_key(fp, formats=fmt)
    steps["cache_check"] = round(time.time() - T0, 2)
    try:
        d = _read_flp_bytes(cur)
    except Exception:                                             # noqa: BLE001
        d = None
    try:
        secs = RC.sections_s(d) if fp and d is not None else None
    except Exception:                                             # noqa: BLE001
        secs = None
    rng = None
    if section is not None or start_bar is not None or end_bar is not None:
        if d is None:
            raise RuntimeError(f"{os.path.basename(cur)} can't be read, so its bars can't be found in the render")
        rng = _preview_range(cur, d, start_bar, end_bar, section)
        _ts, bar_s, _P, _mm = RC.timeline(d)
        rng["start_s"] = round(bar_s(rng["start_bar"]), 3)
        rng["end_s"] = round(bar_s(rng["end_bar"]), 3) if rng["end_bar"] else None
        try:
            song_s = _song_seconds(cur)[0]
        except Exception:                                         # noqa: BLE001 - checked against the render below
            song_s = None
        if song_s and rng["start_s"] >= song_s - 0.05:            # before any export: nothing there to hear
            raise ValueError(f"bar {rng['start_bar']:g} starts at {rng['start_s']:g} s, after the song's end "
                             f"({song_s:.1f} s, bar {_song_seconds(cur)[1] + 1:g})")
    res = {"project": cur, "channels": sel if sel is not None else "all", "format": fmt}
    if cur_how != "FL's title":
        res["project_from"] = cur_how
    if rng:
        res["range"] = {k: v for k, v in rng.items() if v is not None}
    hit = RC.get(key) if key else None                           # an identical render is exact: reused even then
    x = fs = None; src = None; r = None
    f = None                    # the whole-song file: the cache's (hit) or FL's fresh export in '_preview'
    hit_file = hit["files"][0] if hit else None
    meas = None                 # a WAV FL wrote beside a fresh MP3: the numbers come from it
    if hit:
        src = f"reused render (unchanged since {_when(hit['created'])})"
        res["reused"] = src; _note_reuse()
        f = hit_file["path"]
        m0 = (hit.get("meta") or {}).get("measure")
        if m0 and rng is None and rules is None:
            res.update(m0)
    elif fp and sel is None and not exact and measure and not keep and rng is None:
        r_off, why = _preview_offline(fp, secs)
        if r_off:
            res.update(r_off); src = "offline"
            if rules is not None:
                res["rules_note"] = "rules need a real render: fl_preview(rules=..., exact=true)"
        elif why:
            res["offline_skipped"] = why[:160]
    if src is None:                                               # render it
        os.makedirs(out_dir, exist_ok=True)
        muted = []; mk = _ud_key(cur)
        if sel is not None:
            want = set(sel); autos = _automation_channels(d)
            # FL must hold the file BEFORE the mutes go on: a reload of an older copy afterwards (in the export) would
            # drop them and the 'solo' would be the whole mix
            T = time.time()
            try:
                ld = _fl_load_file(cur, "preview")
            except InFlUnavailable as e:
                raise RuntimeError(f"nothing was muted or previewed: {e}") from e
            if ld.get("how") not in ("already", "fl_closed"):
                steps["load_first"] = round(time.time() - T, 1)
            if not _preview_fl_on(cur):                           # checked again right before muting
                raise RuntimeError(f"FL doesn't show {os.path.basename(cur)} (or is loading), so no channel was muted "
                                   "and nothing was previewed")
            st = fl_state()
            _PREVIEW_MUTES[mk] = {"project": cur, "channels": muted, "active": True}   # no save while they're on
        try:
            for c in ((st.get("channels") or []) if sel is not None else []):
                i = int(c.get("index", -1))
                if i >= 0 and i not in want and i not in autos and not c.get("muted"):
                    muted.append(i); fl_channel_set(i, muted=True)
            _preview_clear(out_dir)                               # one preview at a time: no pile-up
            T = time.time()
            # PC-VERIFY: format='mp3' is FL's own MP3 export (Ctrl+Shift+R, FL's last MP3 settings) in the open FL;
            # checklists/core.md 'fl_preview format=mp3 and bar ranges'
            r = _render_in_fl(cur, out_dir, fmt, timeout_s)
            steps["render"] = round(time.time() - T, 1)
        finally:
            if muted:                                             # back only into this project, read back after
                left = None
                try:
                    left = _preview_unmute(cur, muted)
                except Exception:                                 # noqa: BLE001 - reported below
                    left = None
                if left == []:
                    _PREVIEW_MUTES.pop(mk, None)
                else:
                    _PREVIEW_MUTES[mk] = {"project": cur, "channels": list(left or muted), "active": False}
                    res["WARNING"] = (f"channel(s) {list(left or muted)[:16]} muted for this preview couldn't be "
                                      "confirmed unmuted " + ("(FL no longer shows this project)" if left is None else
                                                              "(FL still reports them muted)")
                                      + ": unmute them in FL. fl-headless won't save FL over this project until they "
                                        "are back (the mutes would go into the file)")
            elif mk in _PREVIEW_MUTES and _PREVIEW_MUTES[mk].get("active"):
                _PREVIEW_MUTES.pop(mk, None)
        sp = r.pop("split", None) if isinstance(r, dict) else None
        if sp and sel is None and fp:                             # FL split the export: every track's stem, kept
            res["split_stems"] = len(sp.get("files") or {}) if _rc_store_split(cur, sp, "in_fl") else 0
        else:
            _split_drop(sp)                                       # live mutes aren't in the file: no stems from it
        f = (r.get("rendered") or [None])[0]
        res["seconds_render"] = r.get("seconds")
        for a in r.get("also_rendered") or []:                    # FL's export window had another format ticked too
            if meas is None and fmt == "mp3" and str(a).lower().endswith(".wav"):
                meas = a
        if sel is not None and not _state().get("in_fl_mutes_ok"):
            res["unverified"] = ("that FL's export leaves out live-muted channels isn't proven on this PC yet "
                                 "(fl_pc_check render.preview_mutes): compare with fl_preview() of the whole song")
    elif hit and rng is not None:
        res["seconds_render"] = 0.0
    want_numbers = (measure and "lufs" not in res) or (rules is not None and rng is None)
    # ---- the samples: a WAV / FLAC source always when needed; an MP3 from FL's WAV beside it, else decoded
    if f and src != "offline":
        T = time.time()
        need = want_numbers or (fmt != "mp3" and (rng is not None or (keep and hit_file is not None and
                                                                      (hit_file.get("q") or
                                                                       float(hit_file.get("scale") or 1) != 1.0))))
        try:
            if need and fmt != "mp3":
                x, fs = RC.load(hit_file) if hit_file is not None else _wav_load(f)[:2]
                if want_numbers:
                    res["measured_from"] = fmt
            elif need and want_numbers:
                if meas:
                    x, fs = _wav_load(meas)[:2]; res["measured_from"] = "wav (FL wrote one beside the MP3)"
                else:
                    x, fs = _wav_load(f)[:2]; res["measured_from"] = "mp3"
                    res["measure_note"] = ("measured from the MP3 (lossy): loudness is close to the WAV's; peak / true "
                                           "peak and the top band can differ - format='wav' for exact numbers")
        except (OSError, ValueError) as e:
            if fmt != "mp3":
                raise
            x = fs = None
            res["measure_skipped"] = (f"{str(e)[:140]}: the MP3 can't be decoded on this PC - fl_preview(format='wav') "
                                      "for the numbers")
        if x is not None:
            steps["load"] = round(time.time() - T, 2)
    # ---- the range: inside the render? then cut. FL's export always renders the whole song (no bar range can be
    # handed to it from here), so the range is cut from it. PC-VERIFY: the cut starts where FL's playlist ruler shows
    # start_bar (tempo / meter map); a time selection left in FL shortens the export -> refused (checklists/core.md)
    i0 = j0 = None
    if rng is not None and f:
        audio_s = (len(x) / fs) if x is not None else (_mp3_seconds(f) if fmt == "mp3" else _wav_header_seconds(f))
        short = _preview_short(cur, audio_s)
        if short:
            if hit and key:
                RC.drop(hit.get("key") or key)                    # a render of another state: never reused again
            for p in ([f] if not hit else []) + list((r or {}).get("also_rendered") or []):
                try:                                              # not cached, not kept
                    os.remove(p)
                except OSError:
                    pass
            raise RuntimeError(f"FL's export gave {short[0]:g} s but the song runs {short[1]:g} s (a playlist time "
                               "selection or a loop / stop marker in FL stops its export early), so bars can't be cut "
                               "from it reliably: clear it in FL and preview again")
        if audio_s and rng["start_s"] >= audio_s - 0.05:
            raise ValueError(f"bar {rng['start_bar']:g} starts at {rng['start_s']:g} s, after the render's end "
                             f"({audio_s:.1f} s)")
        res["range_route"] = ("cut from the cached whole-song render (song unchanged: no export)" if hit else
                              "cut from one whole-song export (FL's export renders the whole song)")
        if x is not None:
            i0 = int(round(rng["start_s"] * fs))
            j0 = len(x) if rng["end_s"] is None else min(len(x), int(round(rng["end_s"] * fs)))
    # ---- numbers
    if x is not None and want_numbers and measure and "lufs" not in res:
        T = time.time()
        if rng is None:
            res.update(RC.measure(x, fs, secs if sel is None else None))
        else:
            a_s = rng["start_s"]; b_s = j0 / fs
            sub = [(n, max(s0, a_s) - a_s, min(s1, b_s) - a_s) for n, s0, s1 in (secs or []) if s1 > a_s and s0 < b_s]
            res.update(RC.measure(x[i0:j0], fs, sub if sel is None and len(sub) > 1 else None))
        steps["measure"] = round(time.time() - T, 2)
    if res.get("silent"):                                         # nothing to hear: say why, plainly
        if sel is not None:
            res["silent_hint"] = _silent_channel_hint(cur, d, sel, rng)
        else:
            res["silent_hint"] = ("the whole song renders silent: no channel made a sound in FL's export (master "
                                  "muted / turned down, every channel muted, or the sounds didn't load) - check FL "
                                  "before trusting anything measured")
    elif sel is not None and len(sel) == 1 and res.get("lufs") is not None and \
            _channel_plays(d, list(sel)[0], (rng or {}).get("start_bar"), (rng or {}).get("end_bar")):   # it plays: a pack noted silent before
        _clear_silent_pack(cur, list(sel)[0])                                 # (e.g. switched badly) is cleared
    if rules is not None:
        if rng is not None:
            res["rules_note"] = "rules check the whole song: fl_preview(rules=...) without a range"
        elif x is not None:
            try:
                import flh_finalize
                res["rules"] = flh_finalize.rule_check(x, fs, rules or None)
            except Exception as e:
                res["rules_error"] = str(e)[:120]
    # ---- the file to keep / send: '<song> preview.<ext>' in '_preview' (the last preview replaced)
    share = None
    if keep and f:
        T = time.time()
        os.makedirs(out_dir, exist_ok=True)
        share = _render_dest(out_dir, os.path.splitext(os.path.basename(cur))[0] + " preview", "." + fmt)
        _preview_clear(out_dir, keep=[share, f if not hit else None, meas])
        fresh = hit is None
        if rng is None:
            if fresh:
                if os.path.normcase(os.path.abspath(f)) != os.path.normcase(os.path.abspath(share)):
                    shutil.move(f, share)
                f = share
            elif fmt != "mp3" and x is not None and (hit_file.get("q") or float(hit_file.get("scale") or 1) != 1.0):
                import fl_audio_edit as AE                        # the cache keeps a 16-bit measuring copy: 24-bit
                AE.save(share, x, fs, 24)
            else:
                shutil.copy2(f, share)                            # FL's own file
        elif fmt == "mp3":
            c = _mp3_cut(f, share, rng["start_s"], None if rng["end_s"] is None else rng["end_s"] + PREVIEW_TAIL_S)
            res["share_cut"] = {"starts_s": round(rng["start_s"] - c["start_s"], 3), "seconds": c["seconds"],
                                "how": "whole MP3 frames, no re-encode (starts a moment before start_bar)"}
        else:
            import numpy as np
            import fl_audio_edit as AE
            jt = len(x) if rng["end_s"] is None else min(len(x), j0 + int(PREVIEW_TAIL_S * fs))
            y = np.array(x[i0:jt], dtype=np.float64)
            fi, fo = min(len(y), int(PREVIEW_FADE_S[0] * fs)), min(len(y), int(PREVIEW_FADE_S[1] * fs))
            if i0 > 0 and fi:
                y[:fi] *= np.linspace(0.0, 1.0, fi)[:, None]
            if jt < len(x) and fo:
                y[-fo:] *= np.linspace(1.0, 0.0, fo)[:, None]
            if fmt == "wav":
                AE.save(share, y, fs, 24)
            else:
                AE.save(os.path.splitext(share)[0] + ".wav", y, fs, 24)
                share = _wav_to_flac(os.path.splitext(share)[0] + ".wav")
        _note_render(share)
        steps["share" if rng is None else "cut"] = round(time.time() - T, 2)
        res["share_path"] = share
        res["share_bytes"] = os.path.getsize(share); res["share_mb"] = round(res["share_bytes"] / 1048576.0, 2)
        if fmt == "wav":
            res["wav"] = share                                    # as before
    # ---- the whole-song export goes to the cache (by format) for the next identical preview / range
    if src is None and f and os.path.exists(f):
        if key:
            own = os.path.normcase(os.path.abspath(f)) != os.path.normcase(os.path.abspath(share or ""))
            meta = {}
            if rng is None and x is not None and "lufs" in res:
                meta["measure"] = {k: res[k] for k in ("lufs", "peak_dbfs", "true_peak_dbfs", "bands_db", "centroid_hz",
                                                       "seconds", "silent", "sections", "measured_from") if k in res}
            files = [{"src": f, "name": "mix." + fmt, "owned_src": own and fmt == "wav",
                      "mode": "measure" if fmt == "wav" else ("move" if own else "copy")}]
            RC.put(key, "preview" if sel is not None else "render", files, meta=meta, route="in_fl", project=cur)
        if os.path.exists(f) and os.path.normcase(os.path.abspath(f)) != os.path.normcase(os.path.abspath(share or "")):
            try:
                os.remove(f)                                      # the export itself isn't kept in the song folder
            except OSError:
                pass
    for a in (r or {}).get("also_rendered") or []:                # other formats FL wrote: measured from, not kept
        try:
            if os.path.exists(a):
                os.remove(a)
        except OSError:
            pass
    try:
        if os.path.isdir(out_dir) and not os.listdir(out_dir):    # no empty '_preview' folder left in the song
            os.rmdir(out_dir)
    except OSError:
        pass
    if cnote:
        res["cache_note"] = cnote
    res["renders"] = _renders_here() - n0
    steps["total"] = round(time.time() - T0, 2)
    res["steps_s"] = steps
    return res


OCTAVES = [31, 63, 125, 250, 500, 1000, 2000, 4000, 8000, 16000]


def _octave_db(x, fs):
    import numpy as np
    mono = x.mean(1); f, S = _spectrum(mono, fs); out = []
    for c in OCTAVES:
        m = (f >= c / 1.414) & (f < c * 1.414)
        out.append(10 * np.log10(S[m].sum() + 1e-20))
    return out


def audio_mix_report(files=None, folder=None, reference=None):
    """Mix check from stems: level and peaks per stem (gain staging), which stems fight in the same frequency
    range (masking), and suggestions; with reference (a profile or WAV) also how the summed mix compares."""
    import numpy as np
    if folder:
        files = sorted(glob.glob(os.path.join(folder, "*.wav")) + glob.glob(os.path.join(folder, "*.flac")))
    if not files:
        raise ValueError("give files or a folder of WAV/FLAC stems")
    stems = []; total = None; fs0 = None
    for f in files:
        x, fs, _ = _wav_load(f); fs0 = fs0 or fs
        m = _measure(x, fs); bands = _octave_db(x, fs)
        stems.append({"file": os.path.basename(f), "lufs": m["lufs"], "peak_dbfs": m["peak_dbfs"],
                      "true_peak_dbfs": round(_true_peak(x), 2), "crest_db": m["crest_db"], "_bands": bands})
        if fs == fs0:
            total = x if total is None else (total[:len(x)] + x[:len(total)] if len(x) != len(total) else total + x)
    notes = []
    for s_ in stems:
        if s_["true_peak_dbfs"] > -1:
            notes.append(f"{s_['file']}: peaks at {s_['true_peak_dbfs']} dBFS on its own - lower it (gain staging)")
    loud = [s_ for s_ in stems if s_["lufs"] is not None]
    if loud:
        top = max(loud, key=lambda s_: s_["lufs"])
        for s_ in loud:
            if s_ is not top and s_["lufs"] < top["lufs"] - 25:
                notes.append(f"{s_['file']} is {top['lufs'] - s_['lufs']:.0f} LU below {top['file']} - may be buried")
    clashes = []
    for i in range(len(stems)):
        for j in range(i + 1, len(stems)):
            a, b = stems[i]["_bands"], stems[j]["_bands"]
            for k, c in enumerate(OCTAVES):
                if a[k] > max(a) - 6 and b[k] > max(b) - 6 and abs(a[k] - b[k]) < 6 and c <= 4000:
                    clashes.append(f"{stems[i]['file']} and {stems[j]['file']} both peak around {c} Hz - "
                                   f"cut one there (EQ) or move one an octave")
    res = {"stems": [{k: v for k, v in s_.items() if k != "_bands"} for s_ in stems], "suggestions": notes,
           "masking": clashes[:30]}
    if total is not None:
        mix = _measure(total, fs0); res["summed_mix"] = {"lufs": mix["lufs"], "peak_dbfs": mix["peak_dbfs"],
                                                          "bands_db": mix["bands_db"]}
        if reference:
            rp = os.path.join(PROFILES, str(reference) + ".json")
            ref = json.load(open(rp)) if os.path.isfile(rp) else (json.load(open(reference)) if str(reference).endswith(".json")
                                                                else _measure(*_wav_load(reference)[:2]))
            res["compared_to_reference"] = _verdict(mix, ref)
    return res


def _track_volume_db(d, track):
    ev = _events(d)
    k = next((k for k, e in enumerate(ev) if e["id"] == EV_MIXER_PARAMS), None)
    if k is None:
        return 0.0
    p = _payload(d, ev[k]); code = 0x7000 + (int(track) << 6)
    for i in range(0, len(p) - 11, 12):
        if struct.unpack("<H", p[i + 6:i + 8])[0] == code and p[i + 4] == MIX_VOLUME:
            return round(_fader_db(struct.unpack("<i", p[i + 8:i + 12])[0] / 16000), 2)
    return 0.0


def flp_duck(project, trigger_channel, track, depth_db=6.0, release_beats=0.5, output=None, start_bar=None,
             end_bar=None):
    """Ducking ('sidechain pump') without a compressor: an automation clip on mixer `track`'s volume dips by
    depth_db on every note of trigger_channel (e.g. the kick) and recovers over release_beats."""
    output = output or project
    def run():
        d = _load(project); ev = _events(d); P = _ppq(d)
        base = _track_volume_db(d, track)
        hits = sorted({n[0] for n in _song(d, ev)[0] if n[2] == int(trigger_channel)})
        meters = _meter_map(d, ev)                                # song bars follow the time signature (3/4 too)
        a = _bar_to_tick(start_bar, meters, P) if start_bar else 0
        b = _bar_to_tick(end_bar, meters, P) if end_bar else float("inf")
        hits = [h for h in hits if a <= h < b]
        if not hits:
            raise ValueError(f"channel {trigger_channel} plays no notes there")
        rel = float(release_beats) * P; pts = []; up, down = _fader(base), _fader(base - float(depth_db))
        for i, h in enumerate(hits):
            nxt = hits[i + 1] if i + 1 < len(hits) else h + rel + 1
            pre = max(h - 1, pts[-1][0] + 1 if pts else 0)
            if not pts or pts[-1][1] != up:
                pts.append((pre, up))
            pts.append((h, down))
            pts.append((min(h + rel, nxt - 2), up))
        pts = [(t, v) for i, (t, v) in enumerate(pts) if i == 0 or t > pts[i - 1][0]]
        points = [{"bar": _tick_to_bar(t, meters, P, nd=None), "value": v} for t, v in pts]
        res = flp_add_automation(project, output, points, track=int(track), param="volume",
                                 name=f"Duck {'Master' if int(track) == 0 else f'Insert {track}'} by ch {trigger_channel}")
        res.update(hits=len(hits), depth_db=float(depth_db), base_db=base)
        return res
    return _with_open_project(project, output, run)


# ----------------------------------------------------------------------------- arranging
def _shift_clips(d, at, delta, clip_filter=None):
    """Move playlist clips starting at/after tick `at` by `delta` ticks."""
    ev = _events(d)
    k, _, recs = _playlist_at(d, ev)                              # the arrangement FL plays
    if k is None:
        return d
    for r in recs:
        pos = struct.unpack("<I", r[0:4])[0]
        if pos >= at:
            struct.pack_into("<I", r, 0, max(0, pos + delta))
    return _put_clips(d, ev, recs, k, True)


def _ctrl_lanes(pats):
    """Pattern ids that are controller lanes only (a tempo map: controller rows, no notes). A pattern that also holds
    notes (every FL/MIDI-imported pattern has a tempo row at tick 0) is a note pattern: its clips are split/trimmed."""
    return {pid for pid, p in pats.items() if p.get("ctrl") and not p.get("notes")}


def _ctrl_hold(d, holds):
    """holds {pattern id: {pattern tick, ...}}: for clips of a note pattern that now start at pattern tick t (split,
    trimmed, copied), the controller values in force at t (tempo...) are written again at t, one row per controller,
    so such a clip starts with the right value. The row repeats the value already in force at t, so every other clip
    of the pattern plays exactly as before."""
    holds = {pid: ts for pid, ts in holds.items() if ts}
    if not holds:
        return d
    ev = _events(d); edits = []; cur = None
    for i, e in enumerate(ev):
        if e["id"] == EV_PATTERN_NEW:
            cur = struct.unpack("<H", _payload(d, e))[0]
        elif e["id"] == EV_PATTERN_CTRL and cur in holds:
            rows = [bytes(r) for r in _ctrl_records(_payload(d, e))]; add = []
            for t in sorted(holds[cur]):
                last, at = {}, set()
                for row in rows:
                    rt, = struct.unpack("<I", row[:4])
                    if rt < t:
                        last[row[4:8]] = row
                    elif rt == t:
                        at.add(row[4:8])
                add += [struct.pack("<I", t) + row[4:] for key, row in last.items() if key not in at]
            if add:
                rows = sorted(rows + add, key=lambda r: struct.unpack("<I", r[:4])[0])
                edits.append((i, i + 1, _data_event(EV_PATTERN_CTRL, b"".join(rows))))
    return _splice(d, ev, edits) if edits else d


def _auto_rebuild(head, pts, tail):
    body = b""; prev = pts[0][0] if pts else 0.0
    for i, (beat, val, ten, flag) in enumerate(pts):
        body += struct.pack("<ddf", beat - prev, val, ten) + (b"\x00" * 4 if i == 0 else bytes(flag)); prev = beat
    return head + struct.pack("<I", len(pts)) + body + tail


def _auto_value(pts, x):
    before = [q for q in pts if q[0] <= x]; after = [q for q in pts if q[0] > x]
    if before and after:
        a, b = before[-1], after[0]
        return a[1] + (b[1] - a[1]) * (x - a[0]) / ((b[0] - a[0]) or 1)
    return (before or after)[-1 if before else 0][1]


def _auto_stretch(p, at, n):
    """Automation points with `n` beats of flat value inserted at clip beat `at` (later points move on by n).
    PC-VERIFY: FL draws the flat stretch and the moved curve (checklists/core.md ARR-AUTO)."""
    pts, head, tail = _auto_points(p)
    if not pts:
        return p
    v = _auto_value(pts, at); z = b"\x00" * 4
    new = [q for q in pts if q[0] < at] + [[at, v, 0.0, z]]
    if not any(abs(q[0] - at) < 1e-9 for q in pts):
        new.append([at + n, v, 0.0, z])
    new += [[q[0] + n] + q[1:] for q in pts if q[0] >= at]
    return _auto_rebuild(head, new, tail)


def _auto_cut(p, lo, hi, eps, keep_after=True):
    """Automation points with clip beats [lo, hi) removed: the curve runs to its value at lo, then (keep_after) goes
    on from its value at hi, `eps` beats later; later points move back by hi - lo. PC-VERIFY: FL draws the jump
    (checklists/core.md ARR-AUTO)."""
    pts, head, tail = _auto_points(p)
    if not pts:
        return p
    v_lo, v_hi = _auto_value(pts, lo), _auto_value(pts, hi + eps); z = b"\x00" * 4
    new = [q for q in pts if q[0] < lo] + [[lo, v_lo, 0.0, z]]
    if keep_after:
        later = [[q[0] - (hi - lo)] + q[1:] for q in pts if q[0] >= hi + eps]
        if abs(v_hi - v_lo) > 1e-12 and not (later and abs(later[0][0] - (lo + eps)) < 1e-9):
            new.append([lo + eps, v_hi, 0.0, z])
        new += later
    return _auto_rebuild(head, new, tail)


def _auto_editable(r, counts, item):
    """An automation clip whose points can be edited for it alone: the only clip of its channel, no clip offsets."""
    return counts.get(item, 0) == 1 and struct.unpack("<ff", bytes(r[24:32])) == (-1.0, -1.0)


def _stretch_tempo_patterns(d, at, delta, notes=None):
    """Keep lanes in line with bars inserted at song tick `at`: tempo/controller lanes (patterns with no notes) whose
    clip spans `at` get their events at/after `at` moved by delta and the clip gets longer; an automation clip that
    spans `at` gets a flat stretch (its value at `at`) of that length and gets longer too. An audio clip spanning
    `at` can't be split (no safe offsets): it is left as is and said in `notes`."""
    ev = _events(d); pats = _patterns(d, ev); edits = []; lanes = _ctrl_lanes(pats)
    auto_ev = _automation_events(d, ev); P = _ppq(d)
    span = {}; autos = {}; counts = {}
    for _, _, r in _clips(d, ev):
        item, = struct.unpack("<H", r[6:8]); counts[item] = counts.get(item, 0) + 1
    for _, _, r in _clips(d, ev):
        item = struct.unpack("<H", r[6:8])[0]; pos = struct.unpack("<I", r[0:4])[0]; ln = struct.unpack("<I", r[8:12])[0]
        if not pos < at < pos + ln:
            continue
        if item >= PATTERN_BASE:
            if item - PATTERN_BASE in lanes:
                span.setdefault(item - PATTERN_BASE, pos - _clip_offsets(r)[0])   # pattern tick 0 in song time
        elif item in auto_ev and _auto_editable(r, counts, item):
            autos[item] = pos
        elif notes is not None:
            what = "automation" if item in auto_ev else "audio"
            notes.append(f"an {what} clip at tick {pos} runs across the inserted bars: left as is (it plays on through "
                         "the new bars, so after them it is that much ahead of the music) - split or move it in FL")
    if not span and not autos:
        return d
    cur = None
    for k, e in enumerate(ev):
        if e["id"] == EV_PATTERN_NEW:
            cur = struct.unpack("<H", _payload(d, e))[0]
        elif e["id"] == EV_PATTERN_CTRL and cur in span:
            p = bytearray(_payload(d, e)); cut = at - span[cur]
            for i in range(0, len(p) - 11, 12):
                t = struct.unpack("<I", p[i:i + 4])[0]
                if t >= cut:
                    struct.pack_into("<I", p, i, max(cut, t + delta))
            edits.append((k, k + 1, _data_event(EV_PATTERN_CTRL, bytes(p))))
    for ch, pos in autos.items():
        k = auto_ev[ch]
        edits.append((k, k + 1, _data_event(EV_AUTOMATION, _auto_stretch(_payload(d, ev[k]), (at - pos) / P, delta / P))))
    d = _splice(d, ev, sorted(edits)); ev = _events(d)
    k, _, recs = _playlist_at(d, ev)
    if k is None:
        return d
    for r in recs:
        item = struct.unpack("<H", r[6:8])[0]; pos = struct.unpack("<I", r[0:4])[0]; ln = struct.unpack("<I", r[8:12])[0]
        if not pos < at < pos + ln:
            continue
        if item >= PATTERN_BASE and item - PATTERN_BASE in span:
            s, _ = _clip_offsets(r)
            struct.pack_into("<I", r, 8, ln + delta); struct.pack_into("<I", r, 28, s + ln + delta)
        elif item in autos:
            struct.pack_into("<I", r, 8, ln + delta)
    return _splice(d, ev, [(k, k + 1, _data_event(EV_PLAYLIST, b"".join(bytes(r) for r in recs)))])


def flp_arrange(project, ops, output=None):
    """Song-structure edits on the playlist, in order (bars are song bars):
    {"op": "insert_bars", "at": 17, "bars": 4}  {"op": "delete_bars", "from": 33, "to": 37}
    {"op": "duplicate", "from": 25, "to": 33}   (copies those bars right after themselves, pushing the rest later)
    Tempo maps stay in line; pattern clips crossing an edit point are split/trimmed (notes and their tempo rows
    alike); automation clips are stretched/cut with the bars; audio clips can't be cut (no safe offsets): what
    happened to them is said in `notes`."""
    output = output or project
    def run():
        writable(output)
        d = _load(project); P = _ppq(d); done = []; notes = []
        for op in ops:
            kind = op.get("op")
            meters = _meter_map(d, _events(d))                    # song bars follow the time signature (and markers)
            tick = lambda b_: _bar_to_tick(float(b_), meters, P)
            if any(float(op[k]) < 1 for k in ("at", "from", "to") if op.get(k) is not None) or \
                    (kind == "insert_bars" and not float(op.get("bars") or 0) > 0) or \
                    (kind in ("delete_bars", "duplicate") and not float(op["to"]) > float(op["from"])):
                raise ValueError(f"{op}: bars start at 1, 'to' is after 'from' (the end bar, not included) and "
                                 "insert_bars needs bars > 0")             # (from 5 to 3 moved later clips LATER)
            if kind == "insert_bars":
                at = tick(op["at"])                               # the new bars take the meter in force before
                _, num, den = ([x for x in meters if x[0] < at] or meters[:1])[-1]   # `at` (markers at `at` move on)
                n = int(round(float(op["bars"]) * P * num * 4.0 / den))
                d = _split_clips_at(d, at)
                d = _stretch_tempo_patterns(d, at, n, notes); d = _shift_clips(d, at, n); d = _shift_markers(d, at, n)
            elif kind == "delete_bars":
                a = tick(op["from"]); b = tick(op["to"])
                d, note = _delete_range(d, a, b)
                if b > a:
                    d = _shift_markers(d, a, a - b, cut_end=b)
                if note:
                    notes.extend(note)
            elif kind == "duplicate":
                a = tick(op["from"]); b = tick(op["to"])
                d = _dup_range(d, a, b)
                if b > a:
                    d = _shift_markers(d, b, b - a)
            else:
                raise ValueError("op must be insert_bars, delete_bars or duplicate")
            done.append(kind)
        _save(d, output)
        info = flp_info(output)
        r = {"output": output, "done": done, "song_length_bars": info.get("song_length_bars")}
        if notes:
            r["notes"] = notes
        return r
    return _with_open_project(project, output, run)


def _shift_markers(d, at, delta, cut_end=None):
    """Playlist markers (sections, time signature changes) of the current arrangement at/after tick `at` move by
    `delta`, as the clips do; with cut_end (bars deleted), markers inside [at, cut_end) go to `at` and those at/after
    cut_end move by delta."""
    ev = _events(d); a = _arrangement(d, ev)
    if a is None:
        return d
    edits = []; frm = at if cut_end is None else cut_end
    for k in range(a["first"] + 1, a["end"]):
        e = ev[k]
        if e["id"] != EV_MARKER_POS or e["len"] != 4:
            continue
        v, = struct.unpack("<I", _payload(d, e)); t = v & 0x07FFFFFF
        if cut_end is not None and at <= t < cut_end:
            nt = at
        elif t >= frm:
            nt = max(0, min(0x07FFFFFF, t + delta))
        else:
            continue
        if nt != t:
            edits.append((k, k + 1, bytes([EV_MARKER_POS]) + struct.pack("<I", (v & ~0x07FFFFFF) | nt)))
    return _splice(d, ev, edits) if edits else d


def _clip_offsets(r):
    """(start, end) offsets of a pattern clip inside its pattern, in ticks."""
    s, e = struct.unpack("<II", r[24:32]); ln = struct.unpack("<I", r[8:12])[0]
    if s > 1 << 28 or e > 1 << 28 or e < s:                       # unset (-1.0f) -> whole pattern from 0
        s, e = 0, ln
    return s, e


def _split_clips_at(d, at):
    """Split note-pattern clips that cross tick `at` into two clips (tempo/controller lanes - no notes - stay whole;
    a note pattern's own tempo rows are held into the second clip, see _ctrl_hold)."""
    ev = _events(d); pats = _patterns(d, ev); lanes = _ctrl_lanes(pats)
    k, size, recs = _playlist_at(d, ev)
    if k is None:
        return d
    recs = [bytes(r) for r in recs]
    ids = [_clip_id(r, i) for i, r in enumerate(recs)]; out = []; holds = {}
    for r in recs:
        pos, = struct.unpack("<I", r[0:4]); ln, = struct.unpack("<I", r[8:12]); item, = struct.unpack("<H", r[6:8])
        pid = item - PATTERN_BASE
        if item >= PATTERN_BASE and pid not in lanes and pos < at < pos + ln:
            s, e = _clip_offsets(r); cut = at - pos
            if pats.get(pid, {}).get("ctrl"):
                holds.setdefault(pid, set()).add(s + cut)
            h = bytearray(r); struct.pack_into("<I", h, 8, cut); struct.pack_into("<II", h, 24, s, s + cut)
            t = bytearray(r); struct.pack_into("<I", t, 0, at); struct.pack_into("<I", t, 8, ln - cut)
            struct.pack_into("<II", t, 24, s + cut, e)
            if size >= 88:
                nid = _next_clip_id(ids); ids.append(nid); struct.pack_into("<I", t, 32, nid)
            out += [bytes(h), bytes(t)]
        else:
            out.append(r)
    out.sort(key=lambda x: struct.unpack("<I", x[:4])[0])
    return _ctrl_hold(_splice(d, ev, [(k, k + 1, _data_event(EV_PLAYLIST, b"".join(out)))]), holds)


def _dup_range(d, a, b):
    """Copy song time [a, b) right after itself. Pattern clips crossing the edges are split so the copied
    slice really repeats; tempo/controller lanes (no notes) get their events in the slice copied too."""
    n = b - a
    ev = _events(d); pats = _patterns(d, ev)
    ctrl = _ctrl_lanes(pats); holds = {}
    k, size, recs = _playlist_at(d, ev)
    if k is None or n <= 0:
        return d
    recs = [bytes(r) for r in recs]
    ids = [_clip_id(r, i) for i, r in enumerate(recs)]; out = []; cuts = {}

    def fresh(c):
        if size >= 88:
            nid = _next_clip_id(ids); ids.append(nid); struct.pack_into("<I", c, 32, nid)

    def piece(r, pos, ln, s, e, new_id):
        c = bytearray(r); struct.pack_into("<I", c, 0, pos); struct.pack_into("<I", c, 8, ln)
        struct.pack_into("<II", c, 24, s, e)
        if new_id:
            fresh(c)
        return bytes(c)

    for r in recs:
        pos, = struct.unpack("<I", r[0:4]); ln, = struct.unpack("<I", r[8:12]); end = pos + ln
        item, = struct.unpack("<H", r[6:8]); is_pat = item >= PATTERN_BASE; pid = item - PATTERN_BASE
        if end <= a:
            out.append(r); continue
        if pos >= b:
            c = bytearray(r); struct.pack_into("<I", c, 0, pos + n); out.append(bytes(c)); continue
        if not is_pat:                                            # audio / automation: copy if it starts inside
            out.append(r)
            if pos >= a:
                c = bytearray(r); struct.pack_into("<I", c, 0, pos + n)
                fresh(c); out.append(bytes(c))
            continue
        s, e = _clip_offsets(r)
        lo, hi = max(pos, a) - pos, min(end, b) - pos               # overlap, in clip time
        if pid in ctrl:                                           # one clip, longer; events copied
            cuts[pid] = (lo + s, hi + s, end > b)
            out.append(piece(r, pos, ln + n, s, e + n, False)); continue
        if pats.get(pid, {}).get("ctrl"):                         # a note pattern's tempo rows: the copy starts with
            holds.setdefault(pid, set()).add(s + lo)              # the value in force where it starts
        out.append(piece(r, pos, hi, s, s + hi, False))           # up to b (or its end)
        out.append(piece(r, pos + lo + n, hi - lo, s + lo, s + hi, True))   # the copied slice
        if end > b:
            out.append(piece(r, b + n, end - b, s + hi, e, True))           # the rest, after the copy
    out.sort(key=lambda x: struct.unpack("<I", x[:4])[0])
    d = _splice(d, ev, [(k, k + 1, _data_event(EV_PLAYLIST, b"".join(out)))])
    if cuts:
        ev = _events(d); edits = []; cur = None
        for i, e in enumerate(ev):
            if e["id"] == EV_PATTERN_NEW:
                cur = struct.unpack("<H", _payload(d, e))[0]
            elif e["id"] == EV_PATTERN_CTRL and cur in cuts:
                lo, hi, _ = cuts[cur]; q = _payload(d, e); rows = []; nn = b - a
                at_lo, at_hi, last_lo, last_hi = set(), set(), {}, {}
                for j in range(0, len(q) - 11, 12):
                    row = bytearray(q[j:j + 12]); t, = struct.unpack("<I", row[0:4]); key = bytes(row[4:8])
                    if t <= lo:
                        last_lo[key] = bytes(row)
                    if t < hi:
                        last_hi[key] = bytes(row)
                    if t == lo:
                        at_lo.add(key)
                    if t == hi:
                        at_hi.add(key)
                    if t < lo:
                        rows.append(row)
                    elif t < hi:
                        rows.append(row)
                        c = bytearray(row); struct.pack_into("<I", c, 0, t + nn); rows.append(c)
                    else:
                        struct.pack_into("<I", row, 0, t + nn); rows.append(row)
                for key, src in last_lo.items():                  # the copy starts with the value at its start
                    if key not in at_lo:
                        c = bytearray(src); struct.pack_into("<I", c, 0, lo + nn); rows.append(c)
                for key, src in last_hi.items():                  # and the old value returns after it
                    if key not in at_hi:
                        c = bytearray(src); struct.pack_into("<I", c, 0, hi + nn); rows.append(c)
                rows.sort(key=lambda r: struct.unpack("<I", r[0:4])[0])
                edits.append((i, i + 1, _data_event(EV_PATTERN_CTRL, b"".join(bytes(r) for r in rows))))
        d = _splice(d, ev, edits)
    return _ctrl_hold(d, holds)


def _delete_range(d, a, b):
    """Remove song time [a, b): later clips move back; pattern clips are trimmed or split at the edges;
    tempo/controller patterns lose the events inside and keep the value that was in force at b."""
    n = b - a; notes = []
    ev = _events(d); pats = _patterns(d, ev); P = _ppq(d)
    ctrl = _ctrl_lanes(pats); holds = {}
    cuts = {}                                                     # ctrl pattern -> (lo, hi) in pattern time
    k, size, recs = _playlist_at(d, ev)
    if k is None:
        return d, notes
    recs = [bytes(r) for r in recs]
    ids = [_clip_id(r, i) for i, r in enumerate(recs)]; out = []
    auto_ev = _automation_events(d, ev); auto_cut = {}           # automation channel -> beats cut from its start
    auto_mid = {}                                                 # automation channel -> (lo, hi, keep_after) beats
    counts = {}
    for r in recs:
        it, = struct.unpack("<H", r[6:8]); counts[it] = counts.get(it, 0) + 1
    for r in recs:
        pos, = struct.unpack("<I", r[0:4]); ln, = struct.unpack("<I", r[8:12]); end = pos + ln
        item, = struct.unpack("<H", r[6:8]); is_pat = item >= PATTERN_BASE; pid = item - PATTERN_BASE
        c = bytearray(r)
        if pos >= b:                                              # after the cut: move back
            struct.pack_into("<I", c, 0, pos - n); out.append(bytes(c)); continue
        if end <= a:                                              # before the cut: untouched
            out.append(r); continue
        if is_pat and pid in ctrl:                                # tempo map etc.: cut out its middle
            lo, hi = max(a, pos) - pos, min(b, end) - pos
            s, _ = _clip_offsets(r); cuts[pid] = (lo + s, hi + s)
            struct.pack_into("<I", c, 0, min(pos, a)); struct.pack_into("<I", c, 8, ln - (hi - lo))
            struct.pack_into("<I", c, 28, s + ln - (hi - lo)); out.append(bytes(c)); continue
        if not is_pat:                                            # audio / automation clips
            what = "automation" if item in auto_ev else "audio"
            if a <= pos:
                if end > b and item in auto_ev and item not in auto_cut and item not in auto_mid:
                    # an automation clip that runs on past the cut (a whole-song volume curve...): keep it, starting
                    # at a, with its points re-cut to begin where the cut ends (value there interpolated)
                    auto_cut[item] = (b - pos) / P
                    struct.pack_into("<I", c, 0, a); struct.pack_into("<I", c, 8, end - b)
                    out.append(bytes(c))
                    notes.append(f"trimmed an automation clip that started inside the cut (tick {pos}): it now starts "
                                 f"at the cut, with its curve from where the cut ends")
                    continue
                if end > b and what == "audio":
                    # it runs on past the cut: kept, starting at the cut with what was left of it. FL's audio clips
                    # have no start offset this file layer can set safely, so its sound still plays from the start
                    struct.pack_into("<I", c, 0, a); struct.pack_into("<I", c, 8, end - b)
                    out.append(bytes(c))
                    notes.append(f"an audio clip that started inside the cut (tick {pos}) now starts at the cut "
                                 f"(tick {a}), {round((end - b) / P, 2)} beats long; it still plays its sound from the "
                                 f"start ({round((b - pos) / P, 2)} beats of it were meant to be cut): set its start in "
                                 "flp_audio_clip_settings or FL")
                    continue
                notes.append(f"removed an {what} clip {'lying wholly inside' if end <= b else 'starting inside'} "
                             f"the cut (tick {pos})")
                continue
            # starts before the cut and runs into it
            stop = min(end, b)
            if what == "automation" and item not in auto_cut and item not in auto_mid and \
                    _auto_editable(r, counts, item):
                auto_mid[item] = ((a - pos) / P, (stop - pos) / P, end > b)
                struct.pack_into("<I", c, 8, ln - (stop - a)); out.append(bytes(c))
                notes.append(f"cut the deleted bars out of an automation clip that crosses the cut (tick {pos})")
                continue
            if end <= b:                                          # ends inside the cut: it now ends at the cut
                struct.pack_into("<I", c, 8, a - pos); out.append(bytes(c))
                notes.append(f"shortened an {what} clip (tick {pos}) that ended inside the cut: it now ends at the cut")
                continue
            out.append(r)
            notes.append(f"an {what} clip at tick {pos} runs across the cut: left as is (it plays on over the cut, so "
                         "after it it is behind the music) - split it in FL")
            continue
        s, e = _clip_offsets(r)
        if pos < a:                                               # head part ends at a
            head = bytearray(r); struct.pack_into("<I", head, 8, a - pos); struct.pack_into("<II", head, 24, s, s + a - pos)
            out.append(bytes(head))
        if end > b:                                               # tail part starts at a (was b)
            cut = b - pos; tail = bytearray(r)
            if pats.get(pid, {}).get("ctrl"):                     # a note pattern's tempo rows: the tail starts
                holds.setdefault(pid, set()).add(s + cut)         # with the value in force at b
            struct.pack_into("<I", tail, 0, a); struct.pack_into("<I", tail, 8, end - b)
            struct.pack_into("<II", tail, 24, s + cut, e)
            if pos < a and size >= 88:
                nid = _next_clip_id(ids); ids.append(nid); struct.pack_into("<I", tail, 32, nid)
            out.append(bytes(tail))
    out.sort(key=lambda x: struct.unpack("<I", x[:4])[0])
    d = _splice(d, ev, [(k, k + 1, _data_event(EV_PLAYLIST, b"".join(out)))])
    if auto_cut or auto_mid:                                      # re-cut the kept automation clips' points
        ev = _events(d); aev = _automation_events(d, ev)
        edits = [(aev[ch], aev[ch] + 1, _data_event(EV_AUTOMATION, _auto_trim(_payload(d, ev[aev[ch]]), cut)))
                 for ch, cut in auto_cut.items() if ch in aev]
        edits += [(aev[ch], aev[ch] + 1, _data_event(EV_AUTOMATION, _auto_cut(_payload(d, ev[aev[ch]]), lo, hi, 1.0 / P,
                                                                             after)))
                  for ch, (lo, hi, after) in auto_mid.items() if ch in aev]
        edits.sort(key=lambda x: x[0])
        d = _splice(d, ev, edits)
    if cuts:                                                      # edit the controller patterns' events
        ev = _events(d); edits = []; cur = None
        for i, e in enumerate(ev):
            if e["id"] == EV_PATTERN_NEW:
                cur = struct.unpack("<H", _payload(d, e))[0]
            elif e["id"] == EV_PATTERN_CTRL and cur in cuts:
                lo, hi = cuts[cur]; q = _payload(d, e)
                rows = [bytearray(q[j:j + 12]) for j in range(0, len(q) - 11, 12)]
                keep = []; held = {}
                for row in rows:
                    t, = struct.unpack("<I", row[0:4]); key = bytes(row[4:8])
                    if t < lo:
                        keep.append(row)
                    elif t < hi:
                        held[key] = row                           # last value inside the cut, per controller
                    else:
                        struct.pack_into("<I", row, 0, t - (hi - lo)); keep.append(row)
                at_lo = {bytes(r[4:8]) for r in keep if struct.unpack("<I", r[0:4])[0] == lo}
                for key, row in held.items():
                    if key not in at_lo:
                        struct.pack_into("<I", row, 0, lo); keep.append(row)
                keep.sort(key=lambda r: struct.unpack("<I", r[0:4])[0])
                edits.append((i, i + 1, _data_event(EV_PATTERN_CTRL, b"".join(bytes(r) for r in keep))))
        d = _splice(d, ev, edits)
    return _ctrl_hold(d, holds), notes


def flp_pattern_tools(project, action, pattern=None, name=None, output=None):
    """Pattern housekeeping: clone (a copy named `name`), split (one pattern per channel, placed where the
    original was), remove_empty (empty patterns that aren't in the playlist)."""
    output = output or project
    def run():
        writable(output)
        d = _load(project); ev = _events(d); P = _ppq(d); pats = _patterns(d, ev)
        if action == "clone":
            pid = _pattern_id(d, ev, pattern); src = pats[pid]
            r = flp_new_pattern(project, name or f"{src['name']} copy", output=output)
            d = _load(output); ev = _events(d)
            d = _write_pattern_notes(d, ev, r["pattern"], list(map(_rec_to_note, src["notes"])))
            _save(d, output)
            return {"output": output, "cloned": pid, "new_pattern": r["pattern"]}
        if action == "split":
            pid = _pattern_id(d, ev, pattern); src = pats[pid]
            chs = sorted({r[2] for r in src["notes"]})
            places = [(struct.unpack("<I", r[0:4])[0], struct.unpack("<I", r[8:12])[0], _clip_offsets(r),
                       bool(struct.unpack("<H", r[18:20])[0] & CLIP_MUTE), 499 - struct.unpack("<H", r[12:14])[0] + 1)
                      for _, _, r in _clips(d, ev) if struct.unpack("<H", r[6:8])[0] == PATTERN_BASE + pid]
            _, chans, _ = _structure(d); made = []
            cur_path = project
            for ch in chs:
                cname = chans.get(ch, {}).get("name") or f"ch {ch}"
                r = flp_new_pattern(cur_path, f"{src['name']} - {cname}", output=output); cur_path = output
                dd = _load(output); ee = _events(dd)
                dd = _write_pattern_notes(dd, ee, r["pattern"], [n for n in map(_rec_to_note, src["notes"]) if n["ch"] == ch])
                for pos, ln, offs, muted, track in places:          # where, which window, muted, track: as it was
                    dd = _place_pattern(dd, r["pattern"], pos, ln, track, offsets=offs, muted=muted)
                _save(dd, output); made.append(r["pattern"])
            dd = _load(output); ee = _events(dd)
            k, _, recs = _playlist_at(dd, ee)
            if k is not None:
                recs = [r for r in recs if struct.unpack("<H", r[6:8])[0] != PATTERN_BASE + pid]
                dd = _splice(dd, ee, [(k, k + 1, _data_event(EV_PLAYLIST, b"".join(bytes(r) for r in recs)))])
            _save(dd, output)
            return {"output": output, "split": pid, "new_patterns": made, "original_removed_from_playlist": True}
        if action == "remove_empty":
            placed = {struct.unpack("<H", r[6:8])[0] - PATTERN_BASE      # in ANY arrangement: a clip of another
                      for a in _arrangements(d, ev) for r in _playlist_at(d, ev, a["index"])[2]}   # must keep its pattern
            gone = [pid for pid, v in pats.items() if not v["notes"] and not v["ctrl"] and pid not in placed]
            edits = [(a, b, b"") for kind, pid, a, b in _pattern_groups(d, ev) if pid in gone]
            _save(_splice(d, ev, edits), output)
            return {"output": output, "removed": gone}
        raise ValueError("action: clone, split or remove_empty")
    return _with_open_project(project, output, run)


# ----------------------------------------------------------------------------- across projects
def _projects(folder=None):
    bases = [folder] if folder else roots()
    for r in bases:
        for f in glob.glob(os.path.join(r, "**", "*.flp"), recursive=True):
            if os.sep + "backup" + os.sep not in os.path.normcase(f):
                yield f


def flp_search(query, folder=None, limit=100):
    """Find projects by what's inside them: channel, plugin (VSTs too), sample, pattern names, title/artist/genre."""
    q = str(query).lower(); out = []
    for f in _projects(folder):
        try:
            d = _load(f); ev = _events(d); evs, chans, fx = _structure(d)
        except Exception:
            continue
        hits = set()
        for c in chans.values():
            for v in (c.get("name"), c.get("plugin")):
                if v and q in v.lower():
                    hits.add(f"channel {c['index']}: {v}")
            if c.get("plugin") == "Fruity Wrapper" and "state" in c:
                vst = _wrapper_name(_payload(d, evs[c["state"]]))
                if vst and q in vst.lower():
                    hits.add(f"channel {c['index']}: {vst}")
        for (t, sl), fx_ in fx.items():
            name = fx_.get("plugin") or ""
            if fx_.get("plugin") == "Fruity Wrapper" and "state" in fx_:
                name = _wrapper_name(_payload(d, evs[fx_["state"]])) or name
            if q in name.lower():
                hits.add(f"mixer {t} slot {sl}: {name}")
        for e in ev:
            if e["id"] in (EV_SAMPLE_PATH, EV_PATTERN_NAME, 194, 206, 207):
                t = _text16(_payload(d, e))
                if t and q in t.lower():
                    hits.add(t)
        if hits:
            out.append({"project": f, "matches": sorted(hits)[:10]})
            if len(out) >= int(limit):
                break
    return {"query": query, "projects": out}


def _export_all(folder, formats, output_dir, close_fl, reopen):
    files = sorted(_projects(folder))
    if not files:
        raise ValueError("no projects found")
    return _render_batch(files, output_dir or os.path.join(folder, "Exports"), formats, 1800, close_fl, reopen)


def fl_export_all(folder, formats="mp3", output_dir=None, close_fl=True, reopen=True):
    """Render every project in a folder (subfolders included, backups skipped) as a background job (fl_job).
    Default output: an 'Exports' folder inside it."""
    writable(output_dir or os.path.join(folder, "Exports")); os.makedirs(output_dir or os.path.join(folder, "Exports"), exist_ok=True)
    return _start_job("export", _export_all, folder, formats, output_dir, close_fl, reopen, fl=True)


# ----------------------------------------------------------------------------- samples and controllers
def _tempo_prior(bpm):
    """Listeners favour ~100 BPM; this stops slow music from being read at double time."""
    import numpy as np
    return float(np.exp(-0.5 * (np.log2(bpm / 100.0) / 0.9) ** 2))


def _peak_chroma(m, fs, lo=55.0, hi=3500.0, win=8192):
    """Pitch-class profile from spectral peaks only (not every FFT bin), each frame normalised, so overtones and
    noise don't drag the key: G minor material reads as G minor instead of a neighbouring key."""
    import numpy as np
    w = np.hanning(win); freqs = np.fft.rfftfreq(win, 1 / fs); ch = np.zeros(12)
    band = (freqs > lo * 0.9) & (freqs < hi)
    for s in range(0, max(1, len(m) - win), win // 2):
        S = np.abs(np.fft.rfft(m[s:s + win] * w)) if len(m) >= win else np.abs(np.fft.rfft(np.pad(m, (0, win - len(m))) * w))
        if S.max() < 1e-6:
            continue
        k = np.where((S[1:-1] > S[:-2]) & (S[1:-1] >= S[2:]) & (S[1:-1] > 4 * np.median(S[band]) + 1e-9) & band[1:-1])[0] + 1
        if not len(k):
            continue
        a, b, c = np.log(S[k - 1] + 1e-12), np.log(S[k] + 1e-12), np.log(S[k + 1] + 1e-12)
        f = (k + 0.5 * (a - c) / (a - 2 * b + c - 1e-12)) * fs / win
        pc = np.round(12 * np.log2(np.maximum(f, 1.0) / 440.0) + 69).astype(int) % 12
        fr = np.zeros(12); np.add.at(fr, pc, np.sqrt(S[k] / S.max()))
        ch += fr / fr.sum()
    return ch


def audio_detect(path, min_bpm=None, max_bpm=None):
    """Tempo (BPM) and key of a WAV sample or loop, measured on this PC. Double/half time is the usual doubt:
    give min_bpm/max_bpm (e.g. 120-180 for a drum loop) to settle it."""
    import numpy as np
    x, fs, _ = _wav_load(path); m = x.mean(1)
    hop = 128; win = 2048; n = (len(m) - win) // hop
    if n < 8:
        raise ValueError("too short")
    frames = np.stack([m[i * hop:i * hop + win] * np.hanning(win) for i in range(n)])
    S = np.abs(np.fft.rfft(frames, axis=1))
    # onset strength per band, each band normalised, so kick and snare count alike (no half-time bias)
    d = np.maximum(0, np.diff(np.log1p(S), axis=0)); edges = [0, 8, 24, 64, 160, 400, d.shape[1]]
    flux = np.zeros(d.shape[0])
    for lo, hi in zip(edges, edges[1:]):
        b = d[:, lo:hi].sum(1); sd = b.std()
        if sd > 0:
            flux += (b - b.mean()) / sd
    ac = np.correlate(flux, flux, "full")[len(flux) - 1:]
    fps = fs / hop; best = None
    for bpm in np.arange(50, 200.5, 0.5):
        lag = fps * 60 / bpm; l0 = int(lag)
        if l0 + 1 >= len(ac):
            continue
        v = ac[l0] + (ac[l0 + 1] - ac[l0]) * (lag - l0)
        v += 0.5 * np.interp(2 * lag, np.arange(len(ac)), ac) if 2 * lag < len(ac) else 0
        v *= _tempo_prior(bpm)
        if best is None or v > best[0]:
            best = (v, bpm)
    if best:                                                     # refine around the coarse peak
        def score(bpm):
            lag = fps * 60 / bpm
            return (np.interp(lag, np.arange(len(ac)), ac) + (0.5 * np.interp(2 * lag, np.arange(len(ac)), ac) if 2 * lag < len(ac) else 0)) * _tempo_prior(bpm)
        best = max(((score(b), b) for b in np.arange(best[1] - 1, best[1] + 1.01, 0.05)), key=lambda t: t[0])
        best = (best[0], round(float(best[1]), 1))
    chroma = _peak_chroma(m, fs)
    fake = [{"key": pc, "len": float(chroma[pc])} for pc in range(12)]
    keys = fl_music.detect_key(fake)
    bpm = float(best[1]) if best else None
    if bpm:
        lo, hi = _num(min_bpm, float), _num(max_bpm, float)
        while lo and bpm < lo and bpm * 2 <= (hi or 1e9):
            bpm *= 2
        while hi and bpm > hi and bpm / 2 >= (lo or 0):
            bpm /= 2
        bpm = round(bpm, 1)
    alt = [round(bpm / 2, 1), round(bpm * 2, 1)] if bpm else []
    return {"path": path, "bpm": bpm, "bpm_likely": round(bpm) if bpm else None,
            "bpm_alternatives": alt, "key": keys,
            "note": ("double/half time is a guess (leans ~100 BPM) unless min_bpm/max_bpm are given; "
                     "key reads tonal material well (relative major/minor can swap), drums give no key")}


_DOCS_CACHE = {}
KNOWN_FOLDERS = {"Documents": ("{FDD39AD0-238F-46AF-ADB4-6C85480369C7}", "Personal"),
                 "Music": ("{4BD8D571-6D19-48D3-BE97-422220080E43}", "My Music")}


def _known_folder(which="Documents"):
    """The user's real Documents / Music folder, most likely first: the Windows known-folder API (follows OneDrive,
    redirected and renamed folders), the shell-folders registry value, then ~/<which>. Non-Windows: ~/<which>."""
    if which in _DOCS_CACHE:
        return _DOCS_CACHE[which]
    fid_text, shell_name = KNOWN_FOLDERS[which]; out = []
    if IS_WINDOWS:
        try:
            import ctypes
            import uuid
            from ctypes import wintypes
            guid = (ctypes.c_byte * 16).from_buffer_copy(uuid.UUID(fid_text).bytes_le)
            ptr = ctypes.c_wchar_p()
            f = ctypes.windll.shell32.SHGetKnownFolderPath
            f.argtypes = [ctypes.c_void_p, wintypes.DWORD, wintypes.HANDLE, ctypes.POINTER(ctypes.c_wchar_p)]
            if f(ctypes.byref(guid), 0, None, ctypes.byref(ptr)) == 0 and ptr.value:
                out.append(ptr.value)
            ctypes.windll.ole32.CoTaskMemFree(ptr)
        except Exception:
            pass
        v = _reg_values("HKEY_CURRENT_USER", r"Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders")
        if v.get(shell_name):
            out.append(os.path.expandvars(str(v[shell_name])))
    out.append(os.path.join(os.path.expanduser("~"), which))
    _DOCS_CACHE[which] = list(dict.fromkeys(os.path.normpath(p) for p in out if p))
    return _DOCS_CACHE[which]


def _known_documents():
    return _known_folder("Documents")


def _ud_norm(p):
    """A user data folder candidate at the 'FL Studio' level (...\\Image-Line\\FL Studio). FL's own 'User data folder'
    setting names the Image-Line folder; users and older code give either level."""
    p = os.path.normpath(os.path.expandvars(str(p).strip().strip('"')))
    base = os.path.basename(p).lower()
    if base == "fl studio":
        return p
    if base == "image-line" or os.path.isdir(os.path.join(p, "FL Studio")):
        return os.path.join(p, "FL Studio")
    return p


def _ud_key(p):
    return os.path.normcase(os.path.abspath(p))


_UD_NAME_RE = re.compile(r"user[\s_]*data|data[\s_]*folder|user[\s_]*folder", re.I)
_UD_PATH_RE = re.compile(r"[\\/]image-line([\\/]fl studio)?[\\/]?$", re.I)


def _fl_userdata_registry_hits():
    """FL's own record of its user data folder (Options > File settings > User data folder), from HKCU\\Software\\
    Image-Line: text values NAMED like the setting ('strong'; rank 3 under the installed FL version's key) and text
    values that merely ARE an Image-Line data path ('weak', e.g. a remembered browse folder - a tie-breaker only).
    Only folders that exist count. [{path, evidence, strength, rank}]
    PC-VERIFY: which value FL 2024+/2026 really uses for the user data folder (fl_settings(query='image-line') lists
    candidates); this scan finds it by name or by shape, so a renamed value is still caught as 'weak'."""
    if not IS_WINDOWS:
        return []
    hit = _DOCS_CACHE.get("fl_userdata_reg")
    if hit and time.time() - hit[0] < 60:                         # on the bridge's hot path: cache a minute
        return list(hit[1])
    try:
        dump = _reg_dump()
    except Exception:
        dump = {}
    try:
        flkey = _fl_key()
    except Exception:
        flkey = None
    out = []
    for rel, vals in dump.items():
        for name, tv in vals.items():
            try:
                typ, val = tv
            except (TypeError, ValueError):
                continue
            if typ not in (1, 2) or not isinstance(val, str) or not 3 < len(val) < 400:
                continue
            v = os.path.expandvars(val.strip().strip('"'))
            if not (re.match(r"^([a-zA-Z]:[\\/]|\\\\)", v) or os.path.isabs(v)):
                continue
            strong = bool(_UD_NAME_RE.search(name or "")) or (not name and bool(_UD_NAME_RE.search(rel.rsplit("\\", 1)[-1])))
            weak = bool(_UD_PATH_RE.search(v))
            if not (strong or weak) or not os.path.isdir(v):
                continue
            rank = (3 if flkey and rel.split("\\")[0] == flkey else 2) if strong else 0
            out.append({"path": _ud_norm(v), "evidence": f"registry HKCU\\{REG_BASE}\\{rel}\\{name or '(default)'} = {val[:120]}",
                        "strength": "strong" if strong else "weak", "rank": rank})
    _DOCS_CACHE["fl_userdata_reg"] = (time.time(), out)
    return out


def _fl_userdata_from_registry():
    """Folders FL's registry names as its user data folder (strong hits first). Kept for older callers."""
    hits = sorted(_fl_userdata_registry_hits(), key=lambda h: -h["rank"])
    return list(dict.fromkeys(h["path"] for h in hits if h["strength"] == "strong"))


# our own files inside FL's Settings: they must never count as 'FL was active here' (installing the bridge script into
# the wrong copy would otherwise make that copy look the most recently used - exactly how a stale OneDrive copy won)
_UD_OWN = ("fl-headless mailbox", "fl-headless", "fl_headless_notes", "flh_")


def _userdata_activity(d, detail=False):
    """When FL itself last wrote into this user data folder candidate (0 if it doesn't look like one): the newest
    file FL rewrites in Settings (two levels deep), ignoring everything fl-headless writes there itself.
    detail=True: (mtime, relative path of that file)."""
    best = (0.0, None)
    for settings in (os.path.join(d, "Settings"), os.path.join(d, "FL Studio", "Settings")):
        if not os.path.isdir(settings):
            continue
        stack = [(settings, 0)]
        while stack:
            folder, depth = stack.pop()
            try:
                entries = list(os.scandir(folder))
            except OSError:
                continue
            for e in entries:
                low = e.name.lower()
                if any(low.startswith(o) for o in _UD_OWN):
                    continue
                try:
                    if e.is_dir(follow_symlinks=False):
                        if depth < 2:
                            stack.append((e.path, depth + 1))
                    elif e.is_file():
                        t = e.stat().st_mtime
                        if t > best[0]:
                            best = (t, os.path.relpath(e.path, d))
                except OSError:
                    pass
    return best if detail else best[0]


def _ud_script_evidence(cands):
    """{candidate key: [evidence]} that FL runs the bridge script from that folder:
    - 'loaded': the script inside FL reported its own file (fl_ping stores it) - the strongest proof
    - 'heartbeat': the script's mailbox heartbeat in that folder is fresh (FL versions that allow file I/O)
    - 'assigned': FL's MIDI settings use a script folder that exists only there."""
    ev = {_ud_key(c): [] for c in cands}
    try:
        seen = _state().get("fl_script_file") or {}
    except Exception:
        seen = {}
    f = seen.get("path") if isinstance(seen, dict) else None
    if f and time.time() - float(seen.get("t", 0) or 0) < 14 * 86400:
        hw = os.path.dirname(os.path.dirname(f))                   # ...\Settings\Hardware\<folder>\device_x.py
        if os.path.basename(hw).lower() == "hardware":
            k = _ud_key(os.path.dirname(os.path.dirname(hw)))
            ev.setdefault(k, []).append(("loaded", f"FL reported loading its script from {f}"))
    for c in cands:
        for settings in (os.path.join(c, "Settings"), os.path.join(c, "FL Studio", "Settings")):
            try:
                age = time.time() - os.path.getmtime(os.path.join(settings, "fl-headless mailbox", "alive.json"))
            except OSError:
                continue
            if age < 30:
                ev[_ud_key(c)].append(("heartbeat", f"the bridge script's heartbeat here is {int(age)} s old"))
    try:
        folders = set()
        if IS_WINDOWS:
            for k, vals in _reg_dump(_fl_key() + "\\Devices").items():
                if "\\MIDI input\\" in k:
                    sf = str((vals.get("ScriptFolder") or [None, ""])[1] or "")
                    if sf:
                        folders.add(sf)
        if folders:
            have = {}
            for c in cands:
                for settings in (os.path.join(c, "Settings"), os.path.join(c, "FL Studio", "Settings")):
                    for sf in folders:
                        if glob.glob(os.path.join(settings, "Hardware", glob.escape(sf), "device_*.py")):
                            have.setdefault(_ud_key(c), []).append(sf)
            if len(have) == 1:
                k, sfs = next(iter(have.items()))
                ev[k].append(("assigned", f"FL's MIDI settings load script folder(s) {sorted(set(sfs))}, found only here"))
    except Exception:
        pass
    return ev


def _userdata_candidates():
    """Every place FL's user data folder could be, normalized to the 'FL Studio' level, with where each came from."""
    c = []
    for h in sorted(_fl_userdata_registry_hits(), key=lambda h: -h["rank"]):
        c.append((h["path"], h["evidence"]))
    for docs in _known_documents():
        c.append((os.path.join(docs, "Image-Line", "FL Studio"), "Windows Documents folder (known-folder API)"))
    for var in ("OneDrive", "OneDriveConsumer", "OneDriveCommercial"):
        if os.environ.get(var):
            c.append((os.path.join(os.environ[var], "Documents", "Image-Line", "FL Studio"), f"%{var}%\\Documents"))
    c.append((os.path.join(os.path.expanduser("~"), "Documents", "Image-Line", "FL Studio"), "~\\Documents (not redirected)"))
    out = {}
    for p, why in c:
        k = _ud_key(p)
        if k not in out:
            out[k] = {"path": os.path.normpath(p), "exists": os.path.isdir(p), "found_via": [why]}
        elif why not in out[k]["found_via"]:
            out[k]["found_via"].append(why)
    return list(out.values())


def _userdata_pick(refresh=False):
    """FL's user data folder, decided by evidence in this order, with the reason and the other candidates:
    (a) FLH_FL_USERDATA, (b) the folder stored with flh_setup(action='apply', user_data=...), (c) FL's own setting in
    its registry, (d) where FL runs the bridge script from (reported by FL / heartbeat / MIDI settings), (e) only then
    the candidate FL itself wrote to most recently (files FL rewrites, never fl-headless's own), (f) Documents.
    {path, layer, why, candidates: [{path, exists, found_via, evidence}]}"""
    hit = _DOCS_CACHE.get("userdata_pick")
    if hit and not refresh and time.time() - hit[0] < 60:
        return hit[1]
    res = None
    env = os.environ.get("FLH_FL_USERDATA")
    if env:
        res = {"path": _ud_norm(env), "layer": "env", "why": "FLH_FL_USERDATA is set (it always wins)"}
    if res is None:
        try:
            stored = _state().get("fl_userdata")
        except Exception:
            stored = None
        if stored and os.path.isdir(stored):
            res = {"path": _ud_norm(stored), "layer": "setup", "why": "set with flh_setup(action='apply', user_data=...)"}
    cands = _userdata_candidates()
    have = [c for c in cands if c["exists"]]
    if res is None and len(have) == 1:
        res = {"path": have[0]["path"], "layer": "only", "why": "the only candidate that exists"}
    if res is None and have:
        hits = [h for h in _fl_userdata_registry_hits() if h["strength"] == "strong" and os.path.isdir(h["path"])]
        top = max((h["rank"] for h in hits), default=None)
        best = {_ud_key(h["path"]): h for h in hits if h["rank"] == top}
        if len(best) == 1:
            h = next(iter(best.values()))
            res = {"path": h["path"], "layer": "fl_setting", "why": "FL's own 'User data folder' setting: " + h["evidence"]}
    if res is None and have:
        sev = _ud_script_evidence([c["path"] for c in have])
        for kind in ("loaded", "heartbeat", "assigned"):
            ks = [k for k, e in sev.items() if any(x[0] == kind for x in e) and os.path.isdir(k)]
            if len(ks) == 1:
                c = next((c for c in have if _ud_key(c["path"]) == ks[0]), None)
                path = c["path"] if c else ks[0]
                res = {"path": path, "layer": "script_" + kind,
                       "why": next(x[1] for x in sev[ks[0]] if x[0] == kind)}
                break
    if res is None and have:
        acts = [(_userdata_activity(c["path"], detail=True), c) for c in have]
        acts.sort(key=lambda a: -a[0][0])
        (t, f), c = acts[0]
        if t > 0:
            weak = {_ud_key(h["path"]) for h in _fl_userdata_registry_hits() if h["strength"] == "weak"}
            res = {"path": c["path"], "layer": "activity",
                   "why": f"a guess: FL wrote here most recently ({f}, {time.strftime('%Y-%m-%d %H:%M', time.localtime(t))})"
                          + ("; FL's registry also mentions it" if _ud_key(c["path"]) in weak else "")
                          + ". If that's wrong, set it: flh_setup(action='apply', user_data=...)"}
        else:
            res = {"path": have[0]["path"], "layer": "first", "why": "no evidence either way: first candidate"}
    if res is None:
        res = {"path": cands[0]["path"] if cands else "", "layer": "none", "why": "no user data folder exists yet"}
    try:
        sev_all = _ud_script_evidence([c["path"] for c in have]) if have else {}
    except Exception:
        sev_all = {}
    acts_all = {}
    for c in have:
        t, f = _userdata_activity(c["path"], detail=True)
        acts_all[_ud_key(c["path"])] = (f"newest FL file {f} ({time.strftime('%Y-%m-%d %H:%M', time.localtime(t))})"
                                        if t else "no FL settings files")
    res["candidates"] = [dict(c, chosen=_ud_key(c["path"]) == _ud_key(res["path"]),
                              evidence=[x[1] for x in sev_all.get(_ud_key(c["path"]), [])]
                              + ([acts_all[_ud_key(c["path"])]] if _ud_key(c["path"]) in acts_all else []))
                         for c in cands]
    _DOCS_CACHE["userdata_pick"] = (time.time(), res)
    return res


def _documents_dirs():
    """Possible FL user data folders, the one FL really uses first (see _userdata_pick), then the other candidates."""
    try:
        pick = _userdata_pick()
    except Exception:
        pick = {"path": "", "candidates": []}
    out = [pick["path"]] if pick.get("path") else []
    out += [c["path"] for c in pick.get("candidates", [])]
    return list(dict.fromkeys(os.path.normpath(p) for p in out if p))


def _fl_userdata():
    """FL's user data folder ('...\\Image-Line\\FL Studio'): see _userdata_pick."""
    try:
        return _userdata_pick()["path"]
    except Exception:
        return os.environ.get("FLH_FL_USERDATA", "")


def _hardware_dir():
    """FL's Settings\\Hardware (MIDI scripts) inside the user data folder FL really uses (see _userdata_pick)."""
    win = _fl_userdata()
    for settings in ((os.path.join(win, "Settings"), os.path.join(win, "FL Studio", "Settings")) if win else ()):
        if os.path.isdir(settings):                               # the chosen folder, even before Hardware exists
            return os.path.join(settings, "Hardware")
    for docs in _documents_dirs():
        for c in (os.path.join(docs, "FL Studio", "Settings", "Hardware"), os.path.join(docs, "Settings", "Hardware")):
            if os.path.isdir(c):
                return c
    raise FileNotFoundError("FL's Settings\\Hardware folder wasn't found (start FL once; or set FLH_FL_USERDATA to "
                            "FL's user data folder)")


CONTROLLER_TEMPLATE = '''# name={name}
# supportedDevices={device}
"""{name}: controller mapping written by fl-headless. Edit MAP to change what each knob/pad does."""
import channels
import mixer
import plugins
import transport

MAP = {{int(k): v for k, v in ({mapping}).items()}}


def OnControlChange(event):
    m = MAP.get(event.data1)
    if not m:
        return
    v = event.data2 / 127.0; kind = m["do"]
    if kind == "mixer_volume":
        mixer.setTrackVolume(m["track"], v * 1.0)
    elif kind == "mixer_pan":
        mixer.setTrackPan(m["track"], v * 2 - 1)
    elif kind == "channel_volume":
        channels.setChannelVolume(m["channel"], v)
    elif kind == "channel_pan":
        channels.setChannelPan(m["channel"], v * 2 - 1)
    elif kind == "plugin_param":
        plugins.setParamValue(v, m["param"], m["index"], m.get("slot", -1))
    elif kind in ("play", "stop", "record") and event.data2 > 0:
        {{"play": transport.start, "stop": transport.stop, "record": transport.record}}[kind]()
    event.handled = True
'''


_DEVICE_RE = re.compile(r"^[\w .,()+#&'/:\-]{1,64}$")


def _safe_device(device):
    """A MIDI device name as FL lists it. It ends up in a Python comment FL runs ('# supportedDevices=...') and in a
    registry key name: no line breaks or control characters (they could add code lines), no backslashes."""
    if device is None:
        return None
    d = str(device).strip()
    if not _DEVICE_RE.match(d) or any(ord(c) < 32 or c in "\u2028\u2029\x85" for c in d):
        raise ValueError("device: give the MIDI device's name as FL lists it (letters, digits, spaces and . , ( ) + # "
                         "& ' / : - only, at most 64 characters)")
    return d


def fl_controller_script(name, mappings, device=None, assign=False, restart_fl=False):
    """Write a MIDI controller script for FL (e.g. for the MPK mini): mappings [{cc: 70, do: "mixer_volume",
    track: 1}, {cc: 71, do: "plugin_param", index: 0, slot: 0, param: 1}, {cc: 20, do: "play"}...]. do: mixer_volume,
    mixer_pan, channel_volume, channel_pan, plugin_param, play, stop, record. assign=true also selects the script
    for `device` in FL's MIDI settings: with FL open that RESTARTS FL and needs restart_fl=true (settings snapshot
    first)."""
    device = _safe_device(device)
    clean = "".join(c for c in str(name) if c.isalnum() or c in " _-").strip()
    if not clean:
        raise ValueError("give the script a name")
    allowed = {"mixer_volume": {"track"}, "mixer_pan": {"track"}, "channel_volume": {"channel"},
               "channel_pan": {"channel"}, "plugin_param": {"index", "param"}, "play": set(), "stop": set(),
               "record": set()}
    table = {}
    for m_ in mappings:
        do = m_.get("do")
        if do not in allowed:
            raise ValueError(f"do must be one of {', '.join(allowed)}")
        missing = allowed[do] - set(m_)
        if missing:
            raise ValueError(f"{do} needs {sorted(missing)}")
        table[int(m_["cc"])] = {k: (int(v) if k != "do" else v) for k, v in m_.items() if k != "cc"}
    folder = os.path.join(_hardware_dir(), clean)
    os.makedirs(folder, exist_ok=True)
    path = os.path.join(folder, f"device_{clean.replace(' ', '_')}.py")
    with open(path, "w", encoding="utf-8") as f:
        f.write(CONTROLLER_TEMPLATE.format(name=clean, device=device or clean, mapping=json.dumps(table, indent=1)))
    res = {"script": path, "mappings": len(table)}
    if assign:
        if not device:
            raise ValueError("assign needs the device name as FL lists it (see fl_settings_summary midi_inputs)")
        _restart_ok(restart_fl, None, "FL loads MIDI scripts only when it starts (the script file was written)")
        fk = _fl_key()
        res["assigned"] = fl_settings_set([{"key": f"{fk}\\Devices\\MIDI input\\{device}", "name": "ScriptFolder", "value": clean},
                                           {"key": f"{fk}\\Devices\\MIDI input\\{device}", "name": "Type", "value": "-3"}],
                                          restart_fl=True)
    return res


def flp_copy_state(source, target, output, channels=None, effects=None, force=False):
    """Copy instrument/effect states (preset + every knob) between projects.
    channels: [{"from": 0, "to": 0}]   effects: [{"from": [track, slot], "to": [track, slot]}]"""
    writable(output)
    sd, td = _load(source), _load(target)
    sev, sch, sfx = _structure(sd); tev, tch, tfx = _structure(td)
    edits, done = [], []
    for m in channels or []:
        a, b = sch.get(int(m["from"])), tch.get(int(m["to"]))
        if not a or "state" not in a or not b or "state" not in b:
            raise ValueError(f"channel {m} has no plugin in source or target")
        same = (a.get("plugin"), _payload(sd, sev[a["state"]])[:8]) == (b.get("plugin"), _payload(td, tev[b["state"]])[:8])
        if not same and not force:
            raise ValueError(f"channel {m}: different plugins ({a.get('plugin')} vs {b.get('plugin')}); pass force=true")
        edits.append((b["state"], b["state"] + 1, _raw(sd, sev[a["state"]])))
        done.append(f"channel {m['from']} -> {m['to']} ({a.get('name')})")
    for m in effects or []:
        a, b = sfx.get(tuple(m["from"])), tfx.get(tuple(m["to"]))
        if not a or not b:
            raise ValueError(f"effect {m} not found in source or target")
        if a.get("plugin") != b.get("plugin") and not force:
            raise ValueError(f"effect {m}: {a.get('plugin')} vs {b.get('plugin')}; pass force=true")
        edits.append((b["state"], b["state"] + 1, _raw(sd, sev[a["state"]])))
        done.append(f"effect {m['from']} -> {m['to']} ({a.get('plugin')})")
    if not edits:
        raise ValueError("nothing to copy")
    if len({e[0] for e in edits}) != len(edits):                  # two copies into one target: both states were
        raise ValueError("a target channel / effect is listed twice; give each target once")   # written (corrupt)
    _save(_splice(td, tev, edits), output)
    return {"output": output, "copied": done}


def flp_load_plugin(project, output, preset, channel=None, track=None, slot=None):
    """Load a plugin with its settings from a .fst preset onto a channel, or into a mixer track slot."""
    writable(output)
    d = _load(project); ev = _events(d)
    blk, pname = _fst_block(preset)
    if channel is not None:
        a, b = _channel_block(d, ev, int(channel))
        _save(_splice(d, ev, [(a, b + 1, b"".join(raw for _, _, raw in blk))]), output)
        return {"output": output, "loaded": pname, "channel": int(channel)}
    if track is None or slot is None:
        raise ValueError("give a channel, or a mixer track and slot")
    t, s = int(track), int(slot)
    slots = _mixer_slots(d, ev)
    if (t, s) not in slots:
        raise ValueError(f"mixer track {t} slot {s} not found")
    first, marker = slots[(t, s)]
    new = b""
    for eid, p, raw in blk:
        if eid == EV_PLUGIN_HEADER:                                      # point the header at the target slot
            h = bytearray(p); h[0:8] = struct.pack("<ii", t, s)
            new += _data_event(EV_PLUGIN_HEADER, bytes(h))
        else:
            new += raw
    _save(_splice(d, ev, [(first if first is not None else marker, marker, new)]), output)
    return {"output": output, "loaded": pname, "track": t, "slot": s, "replaced": first is not None}


def flp_remove_effect(project, output, track, slot):
    writable(output)
    d = _load(project); ev = _events(d)
    first, marker = _mixer_slots(d, ev).get((int(track), int(slot)), (None, None))
    if first is None:
        raise ValueError(f"no effect in track {track} slot {slot}")
    name = _text16(_payload(d, ev[first]))
    _save(_splice(d, ev, [(first, marker, b"")]), output)
    return {"output": output, "removed": name, "track": int(track), "slot": int(slot)}


def _free_mixer_insert(d, ev):
    """A mixer insert no channel plays into and that isn't a named bus / send ('Insert N' or unnamed), or None
    (flh_newsong's rule, which knows FL's last 'Current' track; a plain fallback without it)."""
    NS = sys.modules.get("flh_newsong")
    if NS is not None and hasattr(NS, "_free_insert"):
        try:
            return NS._free_insert(d, ev)
        except Exception:                                         # noqa: BLE001 - the fallback below
            pass
    used = set(_channel_inserts(d, ev).values()); names = _mixer_names(d, ev)
    n = sum(1 for e in ev if e["id"] == EV_MIXER_TRACK)
    for t in range(1, max(0, n - 2) + 1):                         # never the master (0) or FL's last 'Current' track
        nm = (names.get(t) or "").strip()
        if t not in used and (not nm or re.fullmatch(r"(insert|track)\s*\d*", nm, re.I)):
            return t
    return None


def _set_channel_insert(d, ch, ins):
    """The project bytes with channel `ch` playing into mixer insert `ins` (event 104 word; an older file's event
    22 byte; added before the block's end when the block has neither).
    PC-VERIFY: a channel added with flp_add_channel(insert='new') plays through the named free insert in FL."""
    ev = _events(d); a, b = _channel_ranges(d, ev)[int(ch)]
    for k in range(a, b):
        e = ev[k]
        if e["id"] == EV_CHANNEL_INSERT and e["len"] == 2:
            return _splice(d, ev, [(k, k + 1, bytes([EV_CHANNEL_INSERT]) + struct.pack("<h", int(ins)))])
    for k in range(a, b):
        e = ev[k]
        if e["id"] == EV_CHANNEL_INSERT_OLD and e["len"] == 1 and -128 <= int(ins) <= 127:
            return _splice(d, ev, [(k, k + 1, bytes([EV_CHANNEL_INSERT_OLD]) + struct.pack("<b", int(ins)))])
    NS = sys.modules.get("flh_newsong")
    if NS is not None and hasattr(NS, "_chan_edit"):
        return NS._chan_edit(d, int(ch), {EV_CHANNEL_INSERT: struct.pack("<h", int(ins))})
    raise ValueError(f"channel {ch}'s block has no mixer-insert event to set")


def flp_add_channel(project, output, clone_from, preset=None, insert=None, name=None):
    """Add a channel cloned from an existing one (volume, plugin, settings); optionally load a .fst onto it.
    insert: None / 'same' = the cloned channel's mixer insert (its effects too); 'new' = a free insert of its own,
    named after the channel (PC 2026-10-27: a new channel landed on the Bass channel's EQ'd insert); a number = that
    insert. name: the new channel's name (also the new insert's)."""
    writable(output)
    d = _load(project); ev = _events(d)
    spans = [(i, a, b) for kind, i, a, b in _blocks(d, ev) if kind == "channel"]
    index = {i: (a, b) for i, a, b in spans}
    src = int(clone_from)
    if src not in index:
        raise ValueError(f"no channel {src}")
    k0, k_end = index[src]; new_index = max(index) + 1
    if ev[k_end - 1]["id"] != EV_CHANNEL_END:
        raise ValueError(f"channel {src}'s block has no end marker; can't copy it safely")
    clone = bytes([EV_CHANNEL]) + struct.pack("<H", new_index) + d[ev[k0]["end"]:ev[k_end - 1]["end"]]
    at = max(b for _, _, b in spans)                              # after the last channel (FL's rack order)
    new = bytearray(_splice(d, ev, [(at, at, clone)]))
    fmt, nch, ppq = struct.unpack("<hHH", new[8:14]); new[8:14] = struct.pack("<hHH", fmt, nch + 1, ppq)
    how = "same" if insert in (None, "", "same", "clone") else insert
    ins_res = {}
    if how != "same":
        nd = bytes(new); nev = _events(nd)
        if str(how).strip().lower() == "new":
            t = _free_mixer_insert(nd, nev)
            if t is None:
                t = 0
                ins_res["insert_note"] = ("no free mixer insert: routed to the Master (0) - add inserts in FL or pick "
                                          "one with insert=N")
        else:
            try:
                t = int(how)
            except (TypeError, ValueError):
                raise ValueError("insert: 'new' (a free mixer insert), 'same' (the cloned channel's) or a track "
                                 "number") from None
            ntr = sum(1 for e in nev if e["id"] == EV_MIXER_TRACK)
            if not 0 <= t < max(1, ntr - 1):
                raise ValueError(f"insert {t} isn't a mixer insert of this project (0..{max(0, ntr - 2)})")
        new = bytearray(_set_channel_insert(nd, new_index, t))
        ins_res["insert"] = t
    _save(bytes(new), output)
    res = {"output": output, "new_channel": new_index, "cloned_from": src, **ins_res}
    if how == "same":
        res["insert"] = _channel_inserts(bytes(new)).get(new_index)
        if res["insert"]:
            res["insert_shared_with"] = f"channel {src} (insert='new' gives the new channel its own)"
    if preset:
        res.update(flp_load_plugin(output, output, preset, channel=new_index))
    if name:
        flp_style_channels(output, output, [{"channel": new_index, "name": str(name)}])
        res["name"] = str(name)
    t = res.get("insert")
    if how != "same" and t:                                        # the new insert carries the channel's name
        nm = name
        if not nm:
            try:
                dd = _load(output); _, chans, _fx = _structure(dd)
                nm = (chans.get(new_index) or {}).get("name")
            except Exception:                                     # noqa: BLE001 - an unnamed insert is fine
                nm = None
        if nm:
            try:
                flp_mixer(output, output, [{"track": int(t), "name": str(nm)}])
                res["insert_name"] = str(nm)
            except Exception as e:                                # noqa: BLE001 - routed; only the name is missing
                res["insert_note"] = f"routed to insert {t} but its name wasn't set ({str(e)[:60]})"
    return res


def _preset_roots():
    found = [SOUNDS]
    try:
        dirs = _documents_dirs()
    except Exception:
        try:
            dirs = [os.path.join(d, "Image-Line", "FL Studio") for d in _known_documents()]
        except Exception:                                         # no winreg off Windows, odd shell folders...
            dirs = []
    for docs in dirs:
        found += [os.path.join(docs, "FL Studio", "Presets"), os.path.join(docs, "Presets")]
    try:
        found.append(os.path.join(os.path.dirname(fl_exe()), "Data", "Patches"))
    except Exception:                                             # FL not found, or no registry here
        pass
    return [r for r in found if os.path.isdir(r)]


SOUNDS = os.path.join(os.environ.get("LOCALAPPDATA", os.path.expanduser("~")), "fl-headless", "sounds")


# ---- Splice INSTRUMENT: pick a downloaded sound without its window ----------------------------------------
def _splice_lib():
    """Splice INSTRUMENT's library: FLH_SPLICE_LIB, else the first that exists of ~/Splice/INSTRUMENT and
    <Documents>/Splice/INSTRUMENT (default ~/Splice/INSTRUMENT)."""
    if os.environ.get("FLH_SPLICE_LIB"):
        return os.environ["FLH_SPLICE_LIB"]
    cands = [os.path.join(os.path.expanduser("~"), "Splice", "INSTRUMENT")] + \
        [os.path.join(d, "Splice", "INSTRUMENT") for d in _known_documents()]
    return next((c for c in cands if os.path.isdir(c)), cands[0])


INSTRUMENT_CONTENT_MIN_MB = 1.0                                  # a pack with less than this besides its presets
INSTRUMENT_WALK_FILES = 4000                                      # (counting stops here: enough to tell)


def _instrument_pack_content(pack_dir):
    """What a Splice INSTRUMENT pack folder holds besides its Presets folder -> {"mb", "files", "parts": {top-level
    name: MB}, "downloaded": True/False}. A pack whose sounds were never downloaded has (next to) nothing but its
    .zpreset files: PC 2026-10-23, 'LABS - Glass Piano' loaded silent.
    PC-VERIFY: a downloaded pack's sound files live inside its folder (parts lists where); a pack that plays shows
    downloaded=true (checklists/newsong.md 13a)."""
    tot = n = 0; parts = {}
    for root, dirs, files in os.walk(pack_dir):
        rel = os.path.relpath(root, pack_dir)
        top = "" if rel == "." else rel.split(os.sep)[0]
        if top.lower() == "presets":
            dirs[:] = []
            continue
        for f in files:
            try:
                sz = os.path.getsize(os.path.join(root, f))
            except OSError:
                continue
            tot += sz; n += 1
            parts[top or "(pack folder)"] = parts.get(top or "(pack folder)", 0) + sz
        if n >= INSTRUMENT_WALK_FILES:
            break
    mb = tot / 1e6
    return {"mb": round(mb, 1), "files": n, "downloaded": mb >= INSTRUMENT_CONTENT_MIN_MB,
            "parts": {k: round(v / 1e6, 1) for k, v in sorted(parts.items(), key=lambda kv: -kv[1])[:6]}}


def _instrument_not_downloaded(pack, content):
    return (f"'{pack}' looks not downloaded: besides its presets its folder holds {content['mb']} MB "
            f"({content['files']} file(s)), so INSTRUMENT will most likely load it silent. Download the pack in "
            "INSTRUMENT (its library page) or the Splice app, then try again - or pick a pack with "
            "downloaded=true (flp_instrument_sounds)")


_CONTENT_MEMO = {}               # (pack folder, its mtime) -> (when, _instrument_pack_content)
CONTENT_MEMO_S = 30.0


def _instrument_content_check(label, state):
    """Content check for a Splice INSTRUMENT state (its META family = a pack folder of the library): None when the
    state isn't INSTRUMENT or the library can't be found here, else {family, pack, problem} (problem None = the
    pack is installed with its sounds). Reads only the one pack folder (fast enough for fl_doctor).
    PC-VERIFY: a channel whose INSTRUMENT pack was removed (FL: 'Content Not Found') is fl_doctor's content_missing;
    a pack that plays is not flagged (checklists/review.md R2)."""
    m_ = re.search(rb'<META family="([^"]*)"', state or b"")
    if not m_ or not _is_splice_instrument(label or _wrapper_name(state)):
        return None
    fam = m_.group(1).decode("utf-8", "replace").strip()
    lib = _splice_lib()
    if not os.path.isdir(lib):
        return None
    strip = lambda p: re.sub(r"^(LABS|Spitfire Audio|Splice)\s*-\s*", "", p).strip().lower()
    try:
        packs = [p for p in os.listdir(lib) if os.path.isdir(os.path.join(lib, p, "Presets"))]
    except OSError:
        return None
    pack = next((p for p in packs if strip(p) == fam.lower()), None)
    out = {"family": "Splice INSTRUMENT", "sound": fam, "pack": pack, "problem": None}
    if not pack:
        out["problem"] = (f"its pack '{fam}' isn't in the INSTRUMENT library ({lib}): FL shows 'Content Not Found' "
                          "and the channel stays silent")
        out["fix"] = ("download the pack in INSTRUMENT / the Splice app, or switch the channel to a pack you have: "
                      "flp_instrument_sounds lists them, flp_instrument_sound switches")
        return out
    pdir = os.path.join(lib, pack)
    try:
        key = (pdir, os.path.getmtime(pdir))
    except OSError:
        key = (pdir, None)
    hit = _CONTENT_MEMO.get(key)
    if hit and time.time() - hit[0] < CONTENT_MEMO_S:             # one doctor run asks once per pack, not per channel
        content = hit[1]
    else:
        content = _instrument_pack_content(pdir)
        if len(_CONTENT_MEMO) > 64:
            _CONTENT_MEMO.clear()
        _CONTENT_MEMO[key] = (time.time(), content)
    if not content["downloaded"]:
        out["problem"] = _instrument_not_downloaded(pack, content)
        out["fix"] = "download its sounds, or switch the channel (flp_instrument_sound) to a downloaded pack"
        return out
    seen = (_state().get("silent_packs") or {}).get(pack)
    if seen:
        out["problem"] = (f"'{pack}' rendered silent on this PC before ({seen.get('seen')}, {seen.get('project')}): "
                          "the installed INSTRUMENT probably can't play it")
        out["fix"] = "update the pack in Splice, or switch the channel to another pack (flp_instrument_sound)"
        out["soft"] = True
    return out


# Content checks per instrument family fl-headless can read: name -> fn(plugin label, state bytes) -> None (not
# this family / can't tell) or {family, sound, pack, problem, fix}. Extensions add theirs (flh_flex: FLEX packs).
CONTENT_CHECKS = {"splice_instrument": _instrument_content_check}


def plugin_content_status(label, state):
    """Is the sound content a channel's saved state points at on this PC? The first CONTENT_CHECKS entry that knows
    the state answers ({family, sound, pack, problem, fix}); None = no check knows this plugin."""
    for fn in list(CONTENT_CHECKS.values()):
        try:
            r = fn(label, state)
        except Exception:                                         # noqa: BLE001 - a check must never break a reader
            r = None
        if r:
            return r
    return None


def flp_instrument_sounds():
    """Splice INSTRUMENT packs on this PC and their presets (what flp_instrument_sound can load); per pack whether
    its sounds look downloaded (MB besides the presets)."""
    lib = _splice_lib(); out = []
    if not os.path.isdir(lib):
        raise FileNotFoundError(f"no Splice INSTRUMENT library at {lib} (set FLH_SPLICE_LIB)")
    for pack in sorted(os.listdir(lib)):
        pres = os.path.join(lib, pack, "Presets")
        if not os.path.isdir(pres):
            continue
        content = _instrument_pack_content(os.path.join(lib, pack))
        for ver in sorted(os.listdir(pres)):
            vdir = os.path.join(pres, ver)
            if os.path.isdir(vdir):
                out.append({"pack": pack, "version": ver.lstrip("vV"),
                            "presets": sorted(os.path.splitext(f)[0] for f in os.listdir(vdir) if f.endswith(".zpreset")),
                            "downloaded": content["downloaded"], "content_mb": content["mb"],
                            "content_files": content["files"]})
    return {"library": lib, "packs": out}


def _juce_xml_rewrite(state, edit):
    """Rewrite the XML inside a Spitfire/Splice (JUCE) plugin state with edit(xml) -> xml, keeping the five length
    fields around it consistent (FL wrapper, VST3 'VstW', fxp 'CcnK' + chunk, 'VC2!')."""
    k = state.find(b"VC2!")
    if k < 0:
        raise ValueError("not a Spitfire/Splice plugin state (no VC2! block)")
    xs = struct.unpack("<I", state[k + 4:k + 8])[0]; xe = k + 8 + xs
    new = edit(state[k + 8:xe].decode("utf-8")).encode("utf-8"); dlt = len(new) - xs
    s_ = bytearray(state[:k + 8] + new + state[xe:])
    def bump(off, fmt):
        n = struct.calcsize(fmt); v = struct.unpack(fmt, bytes(s_[off:off + n]))[0]
        s_[off:off + n] = struct.pack(fmt, v + dlt)
    bump(k + 4, "<I")
    c = state.find(b"CcnK")
    if 0 <= c < k:
        bump(c + 4, ">I"); bump(c + 156, ">I")
    w = state.find(b"VstW")
    if 8 <= w < k and struct.unpack("<Q", state[w - 8:w])[0] + w >= xe:
        bump(w - 8, "<Q")
    for off in range(0, min(k, 1024) - 8):
        if struct.unpack("<Q", state[off:off + 8])[0] == len(state) - off - 8:
            bump(off, "<Q"); break
    return bytes(s_)


def flp_plugin_settings(project, output, channel, settings=None, articulation=None, params=None, name=None):
    """Spitfire (BBC SO, LABS) / Splice INSTRUMENT channel settings by editing its saved state, no plugin window:
    settings {id: value} for top-level SETTINGs (e.g. {"p_midiChannel": 0} = listen on every MIDI channel),
    articulation: name part to make the only active one (e.g. "Long"), params {id: value} for PARAMs (e.g.
    {"i_dynamics": 0.4} = BBC dynamics/CC1 resting value)."""
    writable(output)
    d = _load(project); ev = _events(d); ch = int(channel)
    _, ks = _channel_block(d, ev, ch); old = _payload(d, ev[ks]); report = {}
    def edit(x):
        for sid, val in (settings or {}).items():
            pat = r'(<SETTING id="' + re.escape(sid) + r'" value=")[^"]*'
            if not re.search(pat, x):
                raise ValueError(f"no setting {sid}")
            x = re.sub(pat, lambda m_: m_.group(1) + str(val), x, count=1)
        for pid, val in (params or {}).items():
            pat = r'(<PARAM id="' + re.escape(pid) + r'" value=")[^"]*'
            if not re.search(pat, x):
                raise ValueError(f"no param {pid}")
            x = re.sub(pat, lambda m_: m_.group(1) + str(val), x, count=1)
        if articulation:
            arts = re.findall(r"<ARTIC>.*?</ARTIC>", x, flags=re.S)
            names = [re.search(r'a_name" value="([^"]*)"', a).group(1) for a in arts]
            hit = [i for i, n_ in enumerate(names) if str(articulation).lower() in n_.lower()]
            if not hit:
                raise ValueError(f"no articulation like '{articulation}'; have {names}")
            for i, a in enumerate(arts):
                x = x.replace(a, re.sub(r'(a_active" value=")[^"]*', lambda m_: m_.group(1) + ("2" if i == hit[0] else "0"), a, count=1), 1)
            x = re.sub(r'(p_lastSelectedPrimaryArtic" value=")[^"]*', lambda m_: m_.group(1) + str(hit[0]), x, count=1)
            report["articulation"] = names[hit[0]]
        return x
    new = _juce_xml_rewrite(old, edit)
    edits = [(ks, ks + 1, _data_event(EV_PLUGIN_STATE, new))]
    if name:
        a = next((j for j in range(ks, -1, -1) if ev[j]["id"] == EV_CHANNEL), None)
        b_ = next((j for j in range(a + 1, len(ev)) if ev[j]["id"] in (EV_DISPLAY_NAME, EV_CHANNEL)), None)
        if b_ is not None and ev[b_]["id"] == EV_DISPLAY_NAME:
            edits.append((b_, b_ + 1, _data_event(EV_DISPLAY_NAME, str(name).encode("utf-16-le") + b"\x00\x00")))
    _save(_splice(d, ev, sorted(edits)), output)
    m_ = re.search(rb'<META [^>]*name="([^"]*)"', new)
    return {"output": output, "channel": ch, "sound": m_.group(1).decode("utf-8", "replace") if m_ else None,
            "settings": settings or {}, "params": params or {}, **report}


# An INSTRUMENT articulation plays only while its trigger matches: a state copied from a sound whose articulation was
# 'pedal down' (CC64 >= 64, latched: t_type 4) stays silent under plain notes (PC 2026-10-26: LABS Strings written
# from such a donor played nothing; the same state with this always-on trigger played)
INSTRUMENT_TRIGGER_ALWAYS = (("t_type", "0"), ("t_latch", "0"), ("t_keyswitch", "0"), ("t_cc", "32"),
                             ("t_ccValueFrom", "0"), ("t_ccValueTo", "127"), ("t_velFrom", "1"), ("t_velTo", "127"))


def _instrument_state_set(state, family, name, version, artic, tags=""):
    """Point a Splice INSTRUMENT plugin state at another pack/preset: rewrite the XML (META + the articulation)
    and fix the five length fields around it (FL wrapper, VST3 'VstW', fxp 'CcnK', fxp chunk, 'VC2!')."""
    k = state.find(b"VC2!")
    if k < 0:
        raise ValueError("this channel isn't a Splice INSTRUMENT (no INSTRUMENT state found)")
    xs = struct.unpack("<I", state[k + 4:k + 8])[0]; xe = k + 8 + xs
    xml = state[k + 8:xe].decode("utf-8")
    esc = lambda v: str(v).replace("&", "&amp;").replace('"', "&quot;").replace("<", "&lt;")
    meta = re.search(r"<META [^>]*/>", xml)
    if not meta:
        raise ValueError("INSTRUMENT state has no META")
    nm = meta.group(0)
    for attr, val in (("family", family), ("name", name), ("version", version), ("tags", tags)):
        nm = re.sub(attr + r'="[^"]*"', f'{attr}="{esc(val)}"', nm, count=1)
    xml = xml.replace(meta.group(0), nm, 1)
    arts = re.findall(r"<ARTIC>.*?</ARTIC>", xml, flags=re.S)
    if not arts:
        raise ValueError("INSTRUMENT state has no articulation")
    vparts = [int(x) for x in (re.findall(r"\d+", version) + ["0", "0", "0"])[:3]]
    av = (vparts[0] << 24) | (vparts[1] << 16) | (vparts[2] << 8)
    a0 = re.sub(r'(id="a_name" value=")[^"]*', lambda m_: m_.group(1) + esc(artic), arts[0], count=1)
    a0 = re.sub(r'(id="a_version" value=")[^"]*', lambda m_: m_.group(1) + str(av), a0, count=1)
    for tid, tv in INSTRUMENT_TRIGGER_ALWAYS:          # the copied articulation's trigger: always on (a donor's
        a0 = re.sub(r'(id="' + tid + r'" value=")[^"]*', lambda m_, v=tv: m_.group(1) + v, a0, count=1)   # pedal-
    xml = xml.replace("".join(arts), a0, 1) if xml.count("<ARTIC>") == len(arts) else xml.replace(arts[0], a0, 1)
    xml = re.sub(r' route="[^"]*"', "", xml)                       # UI page of the old preset
    new = xml.encode("utf-8"); dlt = len(new) - xs
    s = bytearray(state[:k + 8] + new + state[xe:])
    def bump(off, fmt):
        n = struct.calcsize(fmt); v = struct.unpack(fmt, bytes(s[off:off + n]))[0]
        s[off:off + n] = struct.pack(fmt, v + dlt)
    bump(k + 4, "<I")                                               # VC2! size
    c = state.find(b"CcnK")
    if 0 <= c < k:
        bump(c + 4, ">I"); bump(c + 156, ">I")                      # fxp size + chunk size (big-endian)
    w = state.find(b"VstW")
    if 8 <= w < k and struct.unpack("<Q", state[w - 8:w])[0] + w >= xe:
        bump(w - 8, "<Q")                                           # VST3 component state length
    for off in range(0, min(k, 1024) - 8):                          # FL wrapper: 8-byte length running to the end
        if struct.unpack("<Q", state[off:off + 8])[0] == len(state) - off - 8:
            bump(off, "<Q"); break
    return bytes(s)


def _is_splice_instrument(plugin):
    """True for Splice INSTRUMENT's plugin name ('Splice INSTRUMENT' / 'INSTRUMENT'), not Spitfire's BBC SO or LABS
    (their saved states look alike)."""
    n = str(plugin or "")
    return bool(re.search(r"\bINSTRUMENT\b", n, re.I)) and not re.search(r"bbc|labs|spitfire", n, re.I)


def _instrument_source(project, d, ev):
    """A .fst holding a Splice INSTRUMENT state to put on a channel: a saved sound with INSTRUMENT, else None.
    (A project channel with INSTRUMENT is copied through flp_save_sound first.)"""
    for snd in flp_sounds():                     # (Spitfire's BBC SO / LABS states hold a META too: PC 2026-10-24
        if not _is_splice_instrument(snd.get("plugin")):   # a saved 'BBC Celli' was taken, the pack never played)
            continue
        try:
            if b'<META family="' in open(snd["path"], "rb").read():
                return snd["path"]
        except OSError:
            continue
    try:                                                          # an INSTRUMENT channel in this project: save it
        for c in sorted(_channel_types(d, ev)):
            try:
                _, ks = _channel_block(d, ev, c)
            except Exception:
                continue
            st = _payload(d, ev[ks])
            if b'<META family="' in st and _is_splice_instrument(_wrapper_name(st)):
                r = flp_save_sound(project, "INSTRUMENT (from project)", channel=c)
                return r.get("saved")
    except Exception:
        return None
    return None


def _instrument_patches(pack, version):
    """Patch names (.zmulti stems, exact case) of a downloaded INSTRUMENT pack version."""
    vdir = os.path.join(_splice_lib(), pack, "Patches", "v" + str(version))
    try:
        return sorted(os.path.splitext(f)[0] for f in os.listdir(vdir) if f.lower().endswith(".zmulti"))
    except OSError:
        return []


def _name_tokens(t, drop=()):
    return [w for w in re.split(r"[^a-z0-9]+", str(t or "").lower()) if w and w not in drop]


def _name_key(t):
    return re.sub(r"[^a-z0-9]+", "", str(t or "").lower())


def _match_name(want, names, drop=()):
    """The one entry of `names` (preset / patch / pack names of any plugin) the caller meant by `want`, or None.
    Display names and file names differ in spelling: 'Glass Grand Soft' = 'Glass_Grand_Soft' = 'GLASS-GRAND SOFT'.
    Order: exact; same letters and digits; the same words (minus `drop`, e.g. the pack's own words); the one name
    holding every word asked; the one name holding the asked letters; one clearly closest spelling. Several equally
    good -> None (never a silent pick: PC 2026-10-27 'Glass Grand Soft' loaded the pack's first preset).
    -> (name or None, how, [closest names for an error])."""
    import difflib
    names = [str(n) for n in names or []]
    w = str(want or "").strip()
    if not w or not names:
        return None, "no match", names[:12]
    if w in names:
        return w, "exact", []
    key = _name_key(w)
    hits = [n for n in names if _name_key(n) == key]
    if len(hits) == 1:
        return hits[0], "same name, other spelling", []
    drop = tuple(drop or ())
    wt = set(_name_tokens(w, drop)) or set(_name_tokens(w))
    tok = {n: set(_name_tokens(n, drop)) or set(_name_tokens(n)) for n in names}
    same = [n for n in names if tok[n] == wt]
    if len(same) == 1:
        return same[0], "same words", []
    sub = [n for n in names if wt and wt <= tok[n]]
    if len(sub) == 1:
        return sub[0], "every word asked", []
    inside = [n for n in names if key and (key in _name_key(n) or
                                         (len(_name_key(n)) >= 4 and _name_key(n) in key))]
    if len(inside) == 1:
        return inside[0], "name holds it", []
    ratio = lambda n: difflib.SequenceMatcher(None, key, _name_key(n)).ratio()
    ranked = sorted(names, key=lambda n: (-(len(wt & tok[n]) / max(1, len(wt | tok[n]))), -ratio(n)))
    best = sorted(names, key=lambda n: -ratio(n))
    if best and ratio(best[0]) >= 0.85 and (len(best) == 1 or ratio(best[0]) - ratio(best[1]) >= 0.08):
        return best[0], "closest spelling", []
    many = sub if len(sub) > 1 else (inside if len(inside) > 1 else (same if len(same) > 1 else []))
    close = many or [n for n in ranked if (wt & tok[n]) or ratio(n) >= 0.5] or ranked
    return None, ("several match" if many else "no match"), close[:12]


def _instrument_artic(preset, patches):
    """(articulation name, how) for a preset: INSTRUMENT finds an articulation by its patch's name, exact case
    (PC 2026-10-26: 'LABS_CHOIR' played nothing, the patch 'LABS_Choir' played). The preset's own name when a patch
    has it; else the patch spelled differently; else the one patch whose name holds every word of the preset's."""
    if preset in patches:
        return preset, "exact"
    low = {p.lower(): p for p in patches}
    if str(preset).lower() in low:
        return low[str(preset).lower()], "patch name (case)"
    want = set(_name_tokens(preset, ("labs",)))
    hits = [p for p in patches if want and want <= set(_name_tokens(p, ("labs",)))]
    if hits:
        hits.sort(key=lambda p: (0 if "pedal_down" in p.lower() else 1, len(p)))
        return hits[0], "patch name (words)"
    if len(patches) == 1:
        return patches[0], "the pack's only patch"
    return preset, "preset name (no patch matched)"


def _instrument_saved_state(family, preset):
    """A saved sound (flp_save_sound) holding the real INSTRUMENT state of this pack + preset - picked once in
    INSTRUMENT's window, so its articulations carry INSTRUMENT's own names - or None."""
    fam = set(_name_tokens(family))
    rest = set(_name_tokens(preset, ("labs",))) - fam
    for snd in flp_sounds():
        if not _is_splice_instrument(snd.get("plugin")):
            continue
        try:
            raw = open(snd["path"], "rb").read()
        except OSError:
            continue
        m_ = re.search(rb'<META family="([^"]*)" name="([^"]*)"', raw)
        if not m_ or m_.group(1).decode("utf-8", "replace").strip().lower() != str(family).strip().lower():
            continue
        if set(_name_tokens(m_.group(2).decode("utf-8", "replace"))) - fam == rest:
            return snd
    return None


def _channel_sound_now(d, ev, ch):
    """What a channel's INSTRUMENT-style (JUCE META) state plays now, 'family / name', or None."""
    try:
        _, ks = _channel_block(d, ev, int(ch))
        st = _payload(d, ev[ks])
        m_ = re.search(rb'<META family="([^"]*)" name="([^"]*)"', st)
        if m_:
            a_ = re.search(rb'id="a_name" value="([^"]*)"', st)
            return " / ".join(dict.fromkeys(x.decode("utf-8", "replace") for x in m_.groups() if x)) + \
                (f" ({a_.group(1).decode('utf-8', 'replace')})" if a_ and a_.group(1) else "")
    except Exception:                                             # noqa: BLE001 - only used in a message
        pass
    return None


def flp_instrument_sound(project, output, channel, pack, preset=None, name=None, force=False):
    """Switch a Splice INSTRUMENT channel to another downloaded pack/preset (e.g. pack 'LABS - Choir') by editing
    its saved state - no INSTRUMENT window needed. Best for LABS packs (one sound per preset). Check by ear after.
    A preset or patch that can't be matched is REFUSED (the channel keeps the sound it has) with the names this pack
    really has: PC 2026-10-27 an unmatched patch overwrote a working, user-chosen state with one FL showed as
    'Content Not Found' (silent). force=true writes it anyway.
    PC-VERIFY: preset 'Glass Grand Soft' (display name) loads that preset, not the pack's first; an unknown preset /
    one without a patch is refused and FL's channel still plays its old sound after flh_sync (checklists/core.md
    'instrument sound refusals')."""
    writable(output)
    lib = flp_instrument_sounds()["packs"]
    want = str(pack).strip().lower()
    hit = next((x for x in lib if x["pack"].lower() == want), None) or \
        next((x for x in lib if want in x["pack"].lower()), None)
    if not hit:
        pk, _how, _close = _match_name(pack, [x["pack"] for x in lib], drop=("labs", "spitfire", "audio", "splice"))
        hit = next((x for x in lib if x["pack"] == pk), None) if pk else None
    if not hit:
        raise ValueError(f"pack '{pack}' isn't downloaded; have: {[x['pack'] for x in lib]}")
    if not hit["presets"]:
        raise ValueError(f"{hit['pack']} has no presets on disk")
    family = re.sub(r"^(LABS|Spitfire Audio|Splice)\s*-\s*", "", hit["pack"]).strip()
    pre_how = None
    if preset:
        pre, pre_how, close = _match_name(preset, hit["presets"], drop=("labs",) + tuple(_name_tokens(family)))
        if not pre:
            raise ValueError(f"NOT changed (channel {channel} keeps its sound): '{hit['pack']}' has no preset like "
                             f"'{preset}' ({pre_how}). Its presets: {hit['presets'][:30]}"
                             + (f" (+{len(hit['presets']) - 30} more: flp_instrument_sounds)" if len(hit["presets"]) > 30
                                else "") + (f"; closest: {close[:5]}" if close and pre_how == "several match" else "")
                             + ". Give one of these names")
    else:
        pre = hit["presets"][0]
    d = _load(project); ev = _events(d); ch = int(channel)
    converted = None
    saved = _instrument_saved_state(family, pre)
    if saved:                                # INSTRUMENT's own state for this sound: loaded as it is (exact)
        flp_load_plugin(project, output, saved["path"], channel=ch)
        if name:
            d = _load(output); ev = _events(d)
            _, ks = _channel_block(d, ev, ch)
            a = next((j for j in range(ks, -1, -1) if ev[j]["id"] == EV_CHANNEL), None)
            b_ = next((j for j in range(a + 1, len(ev)) if ev[j]["id"] in (EV_DISPLAY_NAME, EV_CHANNEL)), None)
            if b_ is not None and ev[b_]["id"] == EV_DISPLAY_NAME:
                _save(_splice(d, ev, [(b_, b_ + 1, _data_event(EV_DISPLAY_NAME, str(name).encode("utf-16-le") +
                                                               b"\x00\x00"))]), output)
        return {"output": output, "channel": ch, "sound": f"{hit['pack']} / {pre}", "version": hit["version"],
                "from_saved_sound": saved["name"],
                **({"preset_matched": f"'{preset}' -> '{pre}' ({pre_how})"} if pre_how not in (None, "exact") else {}),
                "how": "your saved sound of this preset (INSTRUMENT's own state, picked in its window): plays as saved"}
    patches = _instrument_patches(hit["pack"], hit["version"])
    artic, how = _instrument_artic(pre, patches)
    if how == "preset name (no patch matched)" and patches:       # the pack's patches are known and none fits
        p2, h2, _c = _match_name(pre, patches, drop=("labs",) + tuple(_name_tokens(family)))
        if p2:
            artic, how = p2, f"patch name ({h2})"
    if how == "preset name (no patch matched)" and patches and not force:
        now = _channel_sound_now(d, ev, ch)
        raise ValueError(f"NOT changed (channel {ch} keeps {repr(now) if now else 'its sound'}): no patch of "
                         f"'{hit['pack']}' matches preset '{pre}', and writing it would load as 'Content Not Found' "
                         f"(silent). The pack's patches: {patches[:20]}; its presets: {hit['presets'][:20]}. Pick a "
                         "preset named like a patch, pick the sound once in INSTRUMENT's window and save it "
                         "(flp_save_sound), or force=true to write it anyway")
    try:
        _, ks = _channel_block(d, ev, ch)
        st = _payload(d, ev[ks])
        is_inst = b'<META family="' in st and _is_splice_instrument(_wrapper_name(st))   # (not BBC SO / LABS)
    except Exception:
        is_inst = False
    if not is_inst:                          # not INSTRUMENT yet: put INSTRUMENT on it first (PC-VERIFY: from a saved sound)
        src = _instrument_source(project, d, ev)
        if not src:
            raise ValueError(f"channel {ch} isn't Splice INSTRUMENT and no INSTRUMENT state was found to copy (no "
                             "INSTRUMENT channel in this project, no saved INSTRUMENT sound): put INSTRUMENT on one "
                             "channel once in FL and save it with flp_save_sound; from then on any channel can switch")
        flp_load_plugin(project, output, src, channel=ch)
        converted = os.path.splitext(os.path.basename(src))[0]
        project = output
        d = _load(project); ev = _events(d)
        _, ks = _channel_block(d, ev, ch)
    old = _payload(d, ev[ks]); m_ = re.search(rb'<META family="([^"]*)" name="([^"]*)"', old)
    new = _instrument_state_set(old, family, family, hit["version"], artic)
    edits = [(ks, ks + 1, _data_event(EV_PLUGIN_STATE, new))]
    if name:
        a = next((j for j in range(ks, -1, -1) if ev[j]["id"] == EV_CHANNEL), None)
        b_ = next((j for j in range(a + 1, len(ev)) if ev[j]["id"] in (EV_DISPLAY_NAME, EV_CHANNEL)), None)
        if b_ is not None and ev[b_]["id"] == EV_DISPLAY_NAME:
            edits.append((b_, b_ + 1, _data_event(EV_DISPLAY_NAME, str(name).encode("utf-16-le") + b"\x00\x00")))
    _save(_splice(d, ev, sorted(edits)), output)
    res = {"output": output, "channel": ch, "sound": f"{hit['pack']} / {pre}", "version": hit["version"],
           "was": (m_.group(2).decode("utf-8", "replace") if m_ else None),
           **({"made_instrument_from": converted} if converted else {}),
           **({"preset_matched": f"'{preset}' -> '{pre}' ({pre_how})"} if pre_how not in (None, "exact") else {}),
           **({"preset_default": f"no preset asked: the pack's first, '{pre}' (others: {hit['presets'][1:8]})"}
              if not preset and len(hit["presets"]) > 1 else {}),
           **({"forced": "no patch matched: written anyway (force=true)"} if force and
              how == "preset name (no patch matched)" and patches else {}),
           "articulation": artic + ("" if how == "exact" else f" ({how})"),
           "check": "listen to it (fl_preview on this channel): an unsupported pack loads silent or keeps the old sound"}
    if how == "preset name (no patch matched)" or (patches and artic not in patches) or \
            hit["pack"].lower().startswith("spitfire audio"):        # (Spitfire-made packs: INSTRUMENT's names differ)
        res["may_be_silent"] = ("INSTRUMENT names this pack's articulations its own way (not readable from the pack's "
                                "files): if it renders silent, pick the sound once in INSTRUMENT's window and save it "
                                "with flp_save_sound - from then on flp_instrument_sound loads that exact state")
    seen = (_state().get("silent_packs") or {}).get(hit["pack"])
    if hit.get("downloaded") is False:                            # only presets on disk: says so, still written
        res["pack_downloaded"] = False
        res["warning"] = _instrument_not_downloaded(hit["pack"], {"mb": hit.get("content_mb"),
                                                                  "files": hit.get("content_files")})
    elif seen:
        res["warning"] = (f"'{hit['pack']}' rendered silent on this PC before ({seen.get('seen')}, "
                          f"{seen.get('project')}): it probably isn't supported by the installed INSTRUMENT - "
                          "update the pack in Splice/LABS, or pick another")
    return res

def flp_save_sound(project, name, channel=None, track=None, slot=None):
    """Save the exact sound of a channel's instrument (or a mixer slot's effect) from any project into the sound
    library as a .fst, so it can be loaded anywhere by name (fl_load_preset / flp_load_plugin).
    Works for any plugin, including VSTs whose own browsers FL can't see (Splice, FLEX packs...)."""
    clean = "".join(c for c in str(name) if c not in '<>:"/\\|?*').strip()
    if not clean:
        raise ValueError("give the sound a name")
    d = _load(project); ev = _events(d)
    if channel is not None:
        a, b = _channel_block(d, ev, int(channel)); kind = 1; ch_field = 2
    elif track is not None and slot is not None:
        first, marker = _mixer_slots(d, ev).get((int(track), int(slot)), (None, None))
        if first is None:
            raise ValueError(f"no effect in track {track} slot {slot}")
        a, b = first, marker - 1; kind = 3; ch_field = 4
    else:
        raise ValueError("give a channel, or a mixer track and slot")
    version = next((_payload(d, e) for e in ev if e["id"] == EV_VERSION), b"26.1.4.5589\x00")
    body = _data_event(EV_VERSION, version) + bytes([28, kind]) + b"".join(_raw(d, e) for e in ev[a:b + 1])
    fst = b"FLhd" + struct.pack("<IhHH", 6, 0x30, ch_field, _ppq(d)) + b"FLdt" + struct.pack("<I", len(body)) + body
    os.makedirs(SOUNDS, exist_ok=True)
    out = os.path.join(SOUNDS, clean + ".fst")
    with open(out, "wb") as f:
        f.write(fst)
    return {"saved": out, "plugin": _fst_label(out), "name": clean}     # (reading it back is the check)


def _wrapper_name(state):
    """Name of the VST inside a Fruity Wrapper state (record 54: u32 id, u64 length, text)."""
    i = 0
    while True:
        i = state.find(b"\x36\x00\x00\x00", i)
        if i < 0 or i + 12 > len(state):
            return None
        n = struct.unpack("<Q", state[i + 4:i + 12])[0]
        txt = state[i + 12:i + 12 + n]
        if 0 < n < 200 and all(32 <= c < 127 for c in txt):
            return txt.decode("ascii")
        i += 1


def _fst_label(path):
    blk, plug = _fst_block(path)
    if plug == "Fruity Wrapper":
        return _wrapper_name(next((p for eid, p, _ in blk if eid == EV_PLUGIN_STATE), b"")) or plug
    return plug


def flp_sounds():
    """The sound library (sounds saved with flp_save_sound)."""
    if not os.path.isdir(SOUNDS):
        return []
    out = []
    for f in sorted(os.listdir(SOUNDS)):
        if f.lower().endswith(".fst"):
            p = os.path.join(SOUNDS, f)
            try:
                plug = _fst_label(p)
            except Exception:
                plug = "?"
            out.append({"name": f[:-4], "plugin": plug, "path": p})
    return out


def fl_find_presets(query, limit=40):
    q = query.lower(); hits = []
    for r in _preset_roots():
        for root, _, files in os.walk(r):
            for f in files:
                p = os.path.join(root, f)
                if f.lower().endswith(".fst") and q in p.lower():
                    hits.append(p)
                    if len(hits) >= int(limit):
                        return {"presets": hits, "truncated": True}
    return {"presets": hits}


# ============================================================================= FL Studio process
def _update_check():
    """After an FL update (new FL64.exe version) re-read every project once and say whether the file side still
    works; the full render check (fl_selftest) is recommended but needs FL closed, so it's only suggested."""
    try:
        ver = _fl_file_version()
    except Exception:
        return None
    st = _state()
    if not ver or ver in (st.get("selftest_passed_on"), st.get("quickcheck_version")):
        return None
    seen = bad = 0; failed = []
    for r in roots():
        for f in glob.glob(os.path.join(r, "**", "*.flp"), recursive=True)[:150]:
            seen += 1
            try:
                _events(_load(f))
            except Exception as e:
                bad += 1; failed.append(f"{os.path.basename(f)}: {e}")
    _state({"quickcheck_version": ver})
    return {"fl_updated_to": ver, "projects_read": f"{seen - bad}/{seen}", "failed": failed[:5],
            "next": "run fl_selftest once with FL closed for the full render check" if not bad else
                    "some projects no longer read: report this before editing files"}


# ----------------------------------------------------------------------------- is a newer fl-headless out?
# The one host besides image-line.com that fl-headless ever contacts: this project's public releases page, at most
# once a week, a plain GET with nothing about the user in it. Off with FLH_UPDATE_CHECK=0 or flh_updates(enable=False).
UPDATE_REPO = "sertifex/fl-headless"
UPDATE_URL = f"https://api.github.com/repos/{UPDATE_REPO}/releases/latest"
UPDATE_EVERY_S = 7 * 86400
UPDATE_RETRY_S = 86400                                           # after a failed look (offline...), try a day later
UPDATE_TIMEOUT_S = 3.0


def _version_key(v):
    """'v2.10.1' -> (2, 10, 1); anything unreadable sorts lowest."""
    nums = re.findall(r"\d+", str(v or ""))[:4]
    return tuple(int(x) for x in nums) if nums else (0,)


def _http_json(url, timeout):
    import urllib.request                                          # lazy: http/ssl cost ~20 ms
    req = urllib.request.Request(url, headers={"Accept": "application/vnd.github+json",
                                               "User-Agent": f"fl-headless/{SERVER['version']}"})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read(200_000).decode("utf-8", "replace"))


def _updates_enabled():
    if os.environ.get("FLH_UPDATE_CHECK", "1").strip().lower() in ("0", "off", "no", "false"):
        return False
    return _state().get("update_check") is not False


def _release_update(force=False):
    """{available, version, url, how} when a newer fl-headless release is out, else None. Network at most once a
    week (cached in the state file); never raises, never blocks longer than UPDATE_TIMEOUT_S."""
    if not _updates_enabled():
        return None
    try:
        seen = _state().get("update_seen") or {}
        now = time.time()
        due = force or not seen.get("checked") or \
            now - seen["checked"] >= (UPDATE_EVERY_S if seen.get("ok") else UPDATE_RETRY_S)
        if due:
            try:
                rel = _http_json(UPDATE_URL, UPDATE_TIMEOUT_S)
                seen = {"checked": now, "ok": True, "tag": str(rel.get("tag_name") or ""),
                        "url": str(rel.get("html_url") or f"https://github.com/{UPDATE_REPO}/releases/latest"),
                        "name": str(rel.get("name") or "")[:80]}
            except Exception:                                      # noqa: BLE001 - offline, rate-limited, no release yet
                seen = dict(seen, checked=now, ok=False)
            _state({"update_seen": seen})
        tag = seen.get("tag")
        if tag and _version_key(tag) > _version_key(SERVER["version"]):
            ext = os.environ.get("FLH_INSTALLED_BY") == "mcpb"
            return {"available": True, "version": tag.lstrip("vV"), "installed": SERVER["version"],
                    "url": seen.get("url"),
                    "how": ("download fl-headless.mcpb from that page and install it in Claude > Settings > "
                            "Extensions > Advanced settings > Install Extension (Claude keeps your settings)") if ext else
                           ("download the new release ZIP, Unblock it, unzip it over this folder, then run flh_reload"),
                    "say": f"fl-headless {tag.lstrip('vV')} is out (you have {SERVER['version']}): {seen.get('url')}"}
    except Exception:                                              # noqa: BLE001 - a notice must never break a tool
        return None
    return None


def auto_renders():
    """Renders nobody asked for - the level balance after a new song, a sound tool's before/after check - run only
    when turned on (flh_auto_renders(enable=true), or FLH_AUTO_RENDERS=1 in the server's env). Off by default: each
    one holds FL for seconds to a minute, and a listen the user asks for (fl_preview, fl_listen, the mix tools) is
    never affected."""
    env = os.environ.get("FLH_AUTO_RENDERS")
    if env is not None and env.strip() != "":
        return env.strip().lower() not in ("0", "false", "no", "off")
    return bool((_state() or {}).get("auto_renders", False))


def flh_auto_renders(enable=None):
    """Automatic renders on or off (default off): the level balance after flh_new_song / fl_beat_from_reference
    and fl_sound_shape's before/after measuring. Renders you ask for (fl_preview, fl_listen, fl_mix_engineer,
    fl_finalize ...) always run."""
    if enable is not None:
        _state({"auto_renders": bool(enable)})
    on = auto_renders()
    return {"auto_renders": on,
            "means": ("new songs balance their levels with one export, sound tools measure before/after" if on else
                      "no render unless one is asked for: levels start from each sound's known loudness; "
                      "flp_balance(project) evens them with one export when you want"),
            **({"note": "FLH_AUTO_RENDERS in the server's env decides"} if os.environ.get("FLH_AUTO_RENDERS", "").strip()
               else {})}


def flh_updates(enable=None, check_now=False):
    """Is a newer fl-headless out? Looks at this project's GitHub releases page at most once a week (nothing about
    you is sent). enable=false turns the weekly look off (true turns it back on); check_now=true looks right away."""
    if enable is not None:
        _state({"update_check": bool(enable)})
    on = _updates_enabled()
    r = {"installed": SERVER["version"], "weekly_check": on,
         "how_to_turn_off": "flh_updates(enable=false), or FLH_UPDATE_CHECK=0 in the server's env"}
    if not on:
        r["note"] = "the weekly look is off" + (" (FLH_UPDATE_CHECK=0)" if _state().get("update_check") is not False
                                                 else "")
        return r
    upd = _release_update(force=bool(check_now))
    seen = _state().get("update_seen") or {}
    r["latest_seen"] = seen.get("tag") or None
    r["last_checked"] = time.strftime("%Y-%m-%d %H:%M", time.localtime(seen["checked"])) if seen.get("checked") else None
    if seen.get("checked") and not seen.get("ok"):
        r["note"] = "couldn't reach GitHub last time (offline?); it tries again tomorrow"
    r["update"] = upd or "you have the latest version"
    return r


def fl_status():
    try:
        exe = fl_exe()
    except FileNotFoundError as e:
        exe = str(e)
    r = {"fl_exe": exe, "fl_running": fl_running(), "writable_roots": roots()}
    if not IS_WINDOWS:
        r["platform"] = WINDOWS_ONLY_NOTE
    upd = _update_check()
    if upd:
        r["fl_update_check"] = upd
    rel = _release_update()
    if rel:
        r["fl_headless_update"] = rel["say"]
    r["bridge"] = "mailbox" if _mailbox_alive() else "midi"
    try:                                                          # 1.0 = a fast PC; more = waits scaled that much
        sv = fl_speed_view()
        r["pc_speed"] = sv["factor"] if sv["factor"] <= 1.0 and not sv.get("last_slow") else \
            {"factor": sv["factor"], **({"note": sv["last_slow"]["note"]} if sv.get("last_slow") else {})}
    except Exception:
        pass
    ext = _live().get("_EXT_STATUS") or {}
    if ext.get("errors"):
        r["extension_errors"] = ext["errors"]
    if r["fl_running"]:
        pids = _fl_pids(); main = _fl_main_window()
        r.update({"instances": len(pids), "window": main[1] if main else None, "popups": fl_dialogs()})
        if main and _is_untitled(main[1]) and not r["popups"]:   # a new project: does FL say it has changes?
            flag = _fl_changed_flag()
            if flag is not None:
                r["new_project_changed"] = bool(flag)
        if len(pids) > 1:
            r["warning"] = f"{len(pids)} copies of FL are running; only one should be. Close the extra one."
        try:
            cur, _t = _open_project_guess()
            pend = _open_pending_now()
            if pend and (not cur or _ud_key(cur) != _ud_key(pend)):
                # PC 2026-10-23: right after fl_open, fl_status still named the old project as open while FL was
                # switching - never report the project FL is leaving as the open one
                r["switching"] = {"to": pend, "since_s": round(time.time() - float(_OPEN_PENDING.get("t") or 0), 1),
                                  "note": "fl_open sent FL this project; FL hasn't shown it yet (still loading). "
                                          "open_project appears once FL's title names it"}
                if cur:
                    r["still_shown"] = cur
            elif cur:
                r["open_project"] = {"path": cur, "load_cost": project_load_cost(cur), "edits_go": _reload_mode(cur)}
        except Exception:
            pass
    try:
        mode, src = _reload_mode_setting()
        r["reload_mode"] = {"mode": mode, "from": src, "lazy_when_load_over_s": LAZY_THRESHOLD_S}
        pend = _pending_summary()
        if pend:
            r["pending_ops"] = pend
            r["pending_note"] = "queued edits reach FL at flh_sync() (or before listen/render/play/switch)"
        r["render_in_fl"] = (_state().get("in_fl_render") or {}).get("ok", False)
        r["live_mutes_in_export"] = bool(_state().get("in_fl_mutes_ok"))  # stems / previews stay in the open FL
        r["live_notes"] = bool(_live_state().get("ok"))
    except Exception:
        pass
    try:
        L = _live(); ts, src = L["_toolset_setting"]()
        r["toolset"] = {"listed": len(L["listed_tools"]()), "total": len(L["TOOLS"]), "set": ts, "from": src,
                        "more": "flh_tools() lists every tool; flh_call runs any of them"}
    except Exception:
        pass
    return r


STATE = os.path.join(os.environ.get("LOCALAPPDATA", os.path.expanduser("~")), "fl-headless", "state.json")


_STATE_LOCK = threading.RLock()                                   # state.json: threads of this server


_STATE_MEMO = {"key": None, "st": None}                          # state.json parsed, by (path, mtime_ns, size, inode)


def _state_parsed(fresh=False):
    """state.json parsed. Every tool call reads it a few times, so an unchanged file (same path, mtime, size and
    inode, and not written in the last 2 s: a rewrite inside one timestamp tick could keep all of them) is parsed
    once and that parse is shared (don't edit it; -> (dict, shared?)). Any write - ours or another server's -
    changes the key. fresh=True: a parse of its own is wanted (no copy is made when the file is read anyway)."""
    try:
        st_ = os.stat(STATE)
        key = (STATE, st_.st_mtime_ns, st_.st_size, getattr(st_, "st_ino", 0))
        if time.time() - st_.st_mtime <= 2.0:
            key = None
    except FileNotFoundError:
        return {}, False
    except OSError:
        key = None
    memo = _STATE_MEMO
    if key is not None and memo["key"] == key:
        return memo["st"], True
    bad = 0
    for _ in range(3):
        try:
            with open(STATE, encoding="utf-8-sig") as f:          # -sig: a copy hand-edited in Notepad still reads
                st = json.load(f)
            if not isinstance(st, dict):
                raise ValueError("not a JSON object")
            if key is None:
                return st, False
            memo["key"], memo["st"] = key, st
            return st, True
        except FileNotFoundError:
            return {}, False
        except ValueError:                                         # writes are atomic: twice unreadable = damaged
            bad += 1
            if bad >= 2:
                return _state_recover(), False
            time.sleep(0.05)
        except OSError:                                            # Windows: replaced this very moment - read again
            time.sleep(0.02)
    return {}, False


# ---- a damaged state.json: never wiped by the next update. It is copied aside (state.json.damaged-<time>, the
# last STATE_DAMAGED_KEEP kept), the last good copy (state.json.bak, refreshed on successful writes) is put back,
# and the next tool result says so once.
STATE_DAMAGED_KEEP = 3
STATE_BAK_EVERY_S = 30.0                                         # state.json.bak: at most one extra write per 30 s
_STATE_TL = threading.local()                                    # this thread holds the state locks (no re-lock)
_STATE_NEWS = []                                                 # 'state.json was damaged ...' for the next result
_STATE_BAK_T = [0.0]


def _state_read_strict():
    """Inside the state locks: state.json parsed, a damaged one recovered; a file another program holds for more
    than ~1 s raises (an update must never be written over a state it couldn't read)."""
    bad = 0
    for _ in range(50):
        try:
            with open(STATE, encoding="utf-8-sig") as f:
                st = json.load(f)
            if not isinstance(st, dict):
                raise ValueError("not a JSON object")
            return st
        except FileNotFoundError:
            return {}
        except ValueError:
            bad += 1
            if bad >= 2:
                return _state_recover_locked()
            time.sleep(0.05)
        except OSError:
            time.sleep(0.02)
    raise OSError(f"{STATE} can't be read right now (another program holds it): nothing was changed, try again")


def _state_recover():
    """Recover a damaged state.json (takes the state locks unless this thread holds them)."""
    if getattr(_STATE_TL, "held", False):
        return _state_recover_locked()
    try:
        with _STATE_LOCK, _file_lock(STATE + ".lock"):
            _STATE_TL.held = True
            try:
                return _state_recover_locked()
            finally:
                _STATE_TL.held = False
    except (OSError, TimeoutError):                               # can't lock now: read as empty, the next update
        return {}                                                 # (which holds the locks) recovers it


def _state_recover_locked():
    try:                                                          # another thread / server may have fixed it already
        with open(STATE, encoding="utf-8-sig") as f:
            st = json.load(f)
        if isinstance(st, dict):
            return st
    except FileNotFoundError:
        return {}
    except (OSError, ValueError):
        pass
    d = os.path.dirname(STATE); base = os.path.basename(STATE)
    stamp = time.strftime("%Y%m%d-%H%M%S"); aside = f"{STATE}.damaged-{stamp}"; n = 1
    while os.path.exists(aside):
        n += 1; aside = f"{STATE}.damaged-{stamp}-{n}"
    try:
        shutil.copy2(STATE, aside)
    except OSError:
        aside = None
    try:                                                          # keep only the newest few damaged copies
        old = sorted((f for f in os.listdir(d) if f.startswith(base + ".damaged-")),
                     key=lambda f: os.path.getmtime(os.path.join(d, f)))
        for f in old[:-STATE_DAMAGED_KEEP]:
            os.remove(os.path.join(d, f))
    except OSError:
        pass
    st, src = {}, None
    try:
        with open(STATE + ".bak", encoding="utf-8-sig") as f:
            b = json.load(f)
        if isinstance(b, dict):
            st, src = b, os.path.basename(STATE + ".bak")
    except (OSError, ValueError):
        pass
    try:
        _json_write(STATE, st)
    except OSError:
        pass
    _STATE_MEMO["key"] = None
    msg = (f"fl-headless's settings file ({base}) was damaged and couldn't be read: "
           + (f"restored the last good copy ({src}); changes since then may be missing" if src else
              "there was no good backup, so it starts empty (your FL edition, collection and theme choices may "
              "need setting again)")
           + (f". The damaged file is kept as {os.path.basename(aside)}" if aside else ""))
    if msg not in _STATE_NEWS:
        _STATE_NEWS.append(msg)
    return _jcopy(st)


def _pop_state_news():
    out = list(_STATE_NEWS); del _STATE_NEWS[:]
    return out


def _state_read():
    st, shared = _state_parsed()
    return _jcopy(st) if shared else st


def _state_get(key, default=None):
    """One value of state.json (a copy) without copying the rest: for checks that run on every call."""
    f = globals().get("_state")
    if f is not _STATE_FN:                                        # _state replaced (a test double): ask it
        return (f() or {}).get(key, default)
    st, shared = _state_parsed()
    v = st.get(key, default)
    return _jcopy(v) if shared and type(v) in (dict, list) else v


def _state(update=None):
    """fl-headless's small state file. Reads are lock-free (writes replace the file atomically); an update is a
    read-modify-write under a thread lock AND a cross-process file lock (two Claude windows = two servers), written
    to a temp file and swapped in, so no update is lost and a crash never leaves half a file."""
    if not update:
        return _state_read()
    with _STATE_LOCK:
        os.makedirs(os.path.dirname(STATE), exist_ok=True)
        with _file_lock(STATE + ".lock"):
            _STATE_TL.held = True
            try:
                st = _state_read_strict()
                st.update(update)
                _json_write(STATE, st)
                if time.time() - _STATE_BAK_T[0] >= STATE_BAK_EVERY_S or not os.path.isfile(STATE + ".bak"):
                    try:                                          # the last good copy, for a damaged state.json
                        _json_write(STATE + ".bak", st); _STATE_BAK_T[0] = time.time()
                    except OSError:
                        pass
            finally:
                _STATE_TL.held = False
    return st


_STATE_FN = _state


_PIDS_CACHE = [0.0, []]


def _fl_pids():
    if os.name != "nt":
        return []
    if time.time() - _PIDS_CACHE[0] < 0.6:                      # one process scan per burst of checks
        return list(_PIDS_CACHE[1])
    pids = _pids_toolhelp(FL_IMAGES)                            # FL64.exe; FL.exe = 32-bit FL 20 and older
    if pids is None:                                            # fallback: tasklist (its messages are localized,
        pids = []                                               # CSV rows aren't)
        for img in FL_IMAGES:
            out = subprocess.run(["tasklist", "/FI", f"IMAGENAME eq {img}", "/FO", "CSV", "/NH"],
                                 capture_output=True, text=True, errors="replace", creationflags=NO_WINDOW).stdout
            pids += [int(line.split('","')[1]) for line in out.splitlines() if line.lower().startswith(f'"{img}"')]
    _PIDS_CACHE[:] = [time.time(), pids]
    return pids


FL_IMAGES = ("fl64.exe", "fl.exe")                               # PC-VERIFY: FL 20's 32-bit FL.exe counts as running


def _pids_toolhelp(image):
    """PIDs of processes named `image` via the Toolhelp snapshot API (no console tool, no language-dependent
    text). None if the API isn't usable."""
    try:
        import ctypes
        from ctypes import wintypes

        class PE(ctypes.Structure):
            _fields_ = [("dwSize", wintypes.DWORD), ("cntUsage", wintypes.DWORD), ("th32ProcessID", wintypes.DWORD),
                        ("th32DefaultHeapID", ctypes.c_size_t), ("th32ModuleID", wintypes.DWORD),
                        ("cntThreads", wintypes.DWORD), ("th32ParentProcessID", wintypes.DWORD),
                        ("pcPriClassBase", ctypes.c_long), ("dwFlags", wintypes.DWORD),
                        ("szExeFile", ctypes.c_wchar * 260)]
        k32 = ctypes.windll.kernel32
        k32.CreateToolhelp32Snapshot.restype = wintypes.HANDLE
        k32.CreateToolhelp32Snapshot.argtypes = [wintypes.DWORD, wintypes.DWORD]
        k32.Process32FirstW.argtypes = k32.Process32NextW.argtypes = [wintypes.HANDLE, ctypes.POINTER(PE)]
        k32.CloseHandle.argtypes = [wintypes.HANDLE]
        snap = k32.CreateToolhelp32Snapshot(0x2, 0)                 # TH32CS_SNAPPROCESS
        if not snap or snap == wintypes.HANDLE(-1).value:
            return None
        try:
            pe = PE(); pe.dwSize = ctypes.sizeof(PE); out = []
            ok = k32.Process32FirstW(snap, ctypes.byref(pe))
            while ok:
                if pe.szExeFile.lower() in ((image,) if isinstance(image, str) else image):
                    out.append(int(pe.th32ProcessID))
                ok = k32.Process32NextW(snap, ctypes.byref(pe))
            return out
        finally:
            k32.CloseHandle(snap)
    except Exception:
        return None


_U32 = []


def _user32():
    """A private user32 with HWND return types (the shared ctypes.windll one returns c_int: an HWND with bit 31 set
    would come back negative and never equal the callback's value). Private, so other modules' argtypes can't clash."""
    if not _U32:
        import ctypes
        from ctypes import wintypes
        u = ctypes.WinDLL("user32", use_last_error=True)
        for fn in ("GetForegroundWindow", "GetWindow", "GetDlgItem"):
            getattr(u, fn).restype = wintypes.HWND
        u.GetWindow.argtypes = [wintypes.HWND, wintypes.UINT]
        u.GetDlgItem.argtypes = [wintypes.HWND, ctypes.c_int]
        _U32.append(u)
    return _U32[0]


def _hwnd_eq(a, b):
    """Window handles compare by their low 32 bits (handles are 32-bit values, sign-extended on 64-bit Windows)."""
    try:
        return (int(a or 0) & 0xFFFFFFFF) == (int(b or 0) & 0xFFFFFFFF)
    except (TypeError, ValueError):
        return False


def _fl_windows():
    """[(hwnd, title)] of FL's visible top-level windows."""
    import ctypes
    from ctypes import wintypes
    pids = set(_fl_pids()); found = []
    user32 = ctypes.windll.user32
    proc = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)

    def cb(hwnd, _):
        pid = wintypes.DWORD(); user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
        if pid.value in pids and user32.IsWindowVisible(hwnd):
            n = user32.GetWindowTextLengthW(hwnd); buf = ctypes.create_unicode_buffer(n + 1)
            user32.GetWindowTextW(hwnd, buf, n + 1)
            if buf.value:
                found.append((hwnd, buf.value))
        return True
    user32.EnumWindows(proc(cb), 0)
    return found


def _title_stem(title):
    """The project name in FL's MAIN window title ('Beat 2 - FL Studio 2026', '*Beat.flp - FL Studio 21'), or None
    when the title names no project (FL starting / loading, or not FL's main window)."""
    m = re.match(r"^\s*(.*?)\s+-\s+FL Studio(?:\s+[\w.]+)?\s*$", str(title or ""))
    if not m:
        return None
    stem = m.group(1).strip().strip("*").strip()
    if stem.lower().endswith(".flp"):
        stem = stem[:-4].strip()
    return stem or None


_TITLE_FAST = {}                                                  # abs path -> ((mtime, size), title or "")


def _flp_title_fast(path):
    """A project's Project-info title, read from the first 64 KB only (the info events come before the channels):
    cheap enough to check every .flp in FLH_ROOTS. '' when it has none; cached per (mtime, size)."""
    ap = os.path.abspath(path); st = os.stat(ap); key = (st.st_mtime_ns, st.st_size)
    hit = _TITLE_FAST.get(ap)
    if hit and hit[0] == key:
        return hit[1]
    with open(ap, "rb") as f:
        d = f.read(65536)
    title = ""
    if d[:4] == b"FLhd" and len(d) >= 22:
        i = 16 + struct.unpack("<I", d[4:8])[0]
        while i < len(d):
            eid = d[i]; i += 1
            if eid in EV_SIZE_EXCEPTIONS:
                n = EV_SIZE_EXCEPTIONS[eid]
            elif eid < 64:
                n = 1
            elif eid < 128:
                n = 2
            elif eid < 192:
                n = 4
            else:
                n = 0; shift = 0
                while i < len(d):
                    c = d[i]; i += 1; n |= (c & 0x7F) << shift; shift += 7
                    if not c & 0x80:
                        break
            if eid == PROJECT_TEXT["title"] and i + n <= len(d):
                title = _text16(d[i:i + n]).strip(); break
            if eid == EV_CHANNEL:
                break
            i += n
    if len(_TITLE_FAST) > 5000:
        _TITLE_FAST.clear()
    _TITLE_FAST[ap] = (key, title)
    return title


def _project_names(path):
    """Names FL may show for this project: the file's stem, and its title when the project has one."""
    names = {os.path.splitext(os.path.basename(path))[0].strip().lower()}
    try:
        t = _flp_title_fast(path)
    except (OSError, ValueError, struct.error):
        try:
            t = flp_project_info(path).get("title")               # FL shows the project's title when it has one
        except Exception:
            t = None
    if t:
        names.add(str(t).strip().lower())
    return names


# ---- a copy written under another name gets its own Project-info title ------------------------------------------
# FL's window shows the Project-info title, not the file name: two files titled alike can't be told apart by FL's
# window (PC 2026-10-23: '<Song> Rework.flp' kept '<Song> (Piano)' from the file it was copied from - the open waited
# 372 s and failed). So every project fl-headless writes under ANOTHER file stem than its input gets a title of its
# own. Central: _save applies it while a writer runs inside _write_source(input) (the open-project guard sets it
# for every guarded writer with an output; flp_edit, flp_save_version and other copy makers call _own_title_file).
_WSRC = threading.local()


class _write_source:
    """with _write_source(input_project): every project _save writes under another stem gets its own title."""
    def __init__(self, src):
        self.src = os.path.abspath(src) if src else None

    def __enter__(self):
        st = getattr(_WSRC, "st", None)
        if st is None:
            st = _WSRC.st = []
        st.append(self.src)
        return self

    def __exit__(self, *a):
        st = getattr(_WSRC, "st", None)
        if st:
            st.pop()
        return False


def _write_src():
    st = getattr(_WSRC, "st", None)
    return st[-1] if st else None


def _stem(path):
    return os.path.splitext(os.path.basename(str(path)))[0].strip()


def _derived_title(src_title, src_stem, out_stem):
    """The title a copy named `out_stem` gets when its source (stem `src_stem`) is titled `src_title`: the copy's own
    stem when the source's title is its stem, the stem + the same suffix when the title is '<stem> + suffix'
    ('Song (Piano)' from 'Song.flp' -> 'Rework (Piano)' for 'Rework.flp'), else None (no title, or a custom title
    the user set: kept)."""
    t = str(src_title or "").strip(); s = str(src_stem or "").strip(); o = str(out_stem or "").strip()
    if not t or not s or not o or o.lower() == s.lower():
        return None
    if t.lower() == s.lower():
        return o
    if t.lower().startswith(s.lower()) and len(t) > len(s) and not t[len(s)].isalnum():
        suffix = t[len(s):]                                       # 'Song (Piano)' / 'Song - Live' keep the suffix
        return o if suffix.strip().lower() in o.lower() else o + suffix   # ... once ('X (Piano) v2' stays)
    return None


def _title_of_bytes(d):
    """(event index, title) of a project's first Project-info title event (before the channels), or (None, '')."""
    ev = _events(d)
    for k, e in enumerate(ev):
        if e["id"] == EV_CHANNEL:
            break
        if e["id"] == PROJECT_TEXT["title"]:
            return k, _text16(_payload(d, e)).strip()
    return None, ""


def _own_title_bytes(d, src, out):
    """`d` (bytes about to be written to `out`, made from project `src`) with a title of its own when it still carries
    the source's derived title and `out` has another stem; unchanged otherwise (no title, a custom title, a title the
    writer set, the same stem)."""
    try:
        if not src or not out or _stem(src).lower() == _stem(out).lower():
            return d
        k, t = _title_of_bytes(d)
        if k is None or not t:
            return d
        try:
            t_src = _flp_title_fast(src) if os.path.isfile(src) else t
        except (OSError, ValueError, struct.error):
            t_src = t
        if t_src.strip().lower() != t.lower():                    # the writer gave it a title of its own: kept
            return d
        new = _derived_title(t, _stem(src), _stem(out))
        if not new or new == t:
            return d
        ev = _events(d)
        return _splice(d, ev, [(k, k + 1, _data_event(PROJECT_TEXT["title"],
                                                      new.encode("utf-16-le") + b"\x00\x00"))])
    except Exception:                                             # noqa: BLE001 - a title never costs a write
        return d


def _own_title_file(src, out, force=False):
    """After a copy of `src` was written to `out` (shutil copy, template, version, pack): give `out` its own title.
    force: a working copy fl-headless made for itself (fl_ab's [B]) - a custom title is replaced by the copy's file
    name too, so the two files never share the title FL's window shows. -> the new title, or None when it kept its
    title."""
    try:
        with open(out, "rb") as f:
            d = f.read()
        d2 = _own_title_bytes(d, src, out)
        if force and (d2 is d or d2 == d):
            k, t = _title_of_bytes(d)
            stem = _stem(out)
            if k is not None and t and t.strip().lower() != stem.strip().lower():
                d2 = _splice(d, _events(d), [(k, k + 1, _data_event(PROJECT_TEXT["title"],
                                                                     stem.encode("utf-16-le") + b"\x00\x00"))])
        if d2 is d or d2 == d:
            return None
        writable(out)
        _write_bytes(out, d2)
        return _title_of_bytes(d2)[1]
    except Exception:                                             # noqa: BLE001
        return None


_GUESS_CACHE = {}                                                 # stem -> (time, [hits]) of the roots search


def _own_folder(h):
    return _under(os.path.normcase(os.path.abspath(h)), os.path.normcase(os.path.abspath(os.path.dirname(STATE))))


FLP_SCAN_MAX = 20000                                              # .flp files listed per roots scan
FLP_SCAN_MAX_S = 3.0                                              # ... and seconds spent listing
TITLE_SCAN_MAX = 2000                                             # .flp files checked for a matching Project-info title
_BACKUP_NAME = re.compile(r"\((overwritten at|autosave|backup)\b", re.I)


def _is_backup_copy(path):
    """FL's own backup / autosave copies: a 'Backup' folder, or '<name> (overwritten at 1234h).flp' /
    '(autosave)'. They share the project's name and title but are never the file FL has open."""
    parts = os.path.abspath(path).replace("\\", "/").split("/")
    return (len(parts) > 1 and parts[-2].lower() in ("backup", "backups", "autosave")) or \
        bool(_BACKUP_NAME.search(parts[-1]))


def _scan_flps(max_age=30.0):
    """Every .flp in FLH_ROOTS (never fl-headless's own folders or FL's backup copies), walked with os.scandir and
    stopped at FLP_SCAN_MAX files / FLP_SCAN_MAX_S seconds (a root like 'D:\\' must not stall an edit). Cached
    max_age s; the identity proofs warm it before they take the FL lock. -> (files, complete)"""
    now = time.time(); hit = _GUESS_CACHE.get("\0scan")
    if hit and now - hit[0] < max_age:
        return hit[1], hit[2]
    files, complete, t0 = [], True, time.time()
    stack = [r for r in _root_entries(os.environ.get("FLH_ROOTS", ""))]
    own = os.path.normcase(os.path.abspath(os.path.dirname(STATE)))
    while stack:
        if len(files) >= FLP_SCAN_MAX or time.time() - t0 > FLP_SCAN_MAX_S:
            complete = False; break
        top = stack.pop()
        if _under(os.path.normcase(os.path.abspath(top)), own):
            continue
        try:
            with os.scandir(top) as it:
                for e in it:
                    try:
                        if e.is_dir(follow_symlinks=False):
                            if e.name.lower() not in ("backup", "backups", "autosave", "__pycache__", ".git"):
                                stack.append(e.path)
                        elif e.name.lower().endswith(".flp") and not _BACKUP_NAME.search(e.name):
                            files.append(os.path.abspath(e.path))
                    except OSError:
                        pass
        except OSError:
            pass
    files = list(dict.fromkeys(files))
    if len(_GUESS_CACHE) > 64:
        _GUESS_CACHE.clear()
    _GUESS_CACHE["\0scan"] = (now, files, complete)
    return files, complete


def _find_by_stem(stem):
    """.flp files named `stem` inside FLH_ROOTS (never fl-headless's own folders: shadow copies and backups share
    the project's name). From the cached, bounded roots scan."""
    want = stem.lower() + ".flp"
    hits = [h for h in _scan_flps()[0] if os.path.basename(h).lower() == want and os.path.isfile(h)]
    if not hits:                                                  # a file saved since the scan: look again (2 s+)
        hits = [h for h in _scan_flps(2.0)[0] if os.path.basename(h).lower() == want and os.path.isfile(h)]
    return hits


def _find_by_title(name):
    """.flp files in FLH_ROOTS whose Project-info title is `name` (FL's window shows the title when there is one, so
    a project saved as 'mysong_v3.flp' titled 'My Song' shows as 'My Song'). The first TITLE_SCAN_MAX files of the
    cached roots scan; titles are read per file (a fast header read)."""
    want = str(name).strip().lower(); out = []
    if not want:
        return out
    for f in _scan_flps()[0][:TITLE_SCAN_MAX]:
        try:
            if _flp_title_fast(f).lower() == want:
                out.append(f)
        except (OSError, ValueError, struct.error):
            pass
    return out


def _name_candidates(stem):
    """Every project file FL could mean when its window shows `stem`: files named so in FLH_ROOTS, files titled so
    (Project info), and the project last opened through fl-headless when its name matches."""
    hits = list(_find_by_stem(stem)) + _find_by_title(stem)
    try:
        last = _state().get("last_opened")
    except Exception:
        last = None
    if last and os.path.isfile(last) and stem.lower() in _project_names(last):
        hits.append(os.path.abspath(last))
    out, seen = [], set()
    for h in hits:
        k = _ud_key(h)
        if k not in seen:
            seen.add(k); out.append(h)
    return out


OPEN_PROOF_TTL_S = 15.0                                           # how long a save-identity proof names the open file
_OPEN_PROOF = {"path": None, "title": None, "t": 0.0}
_GUESS_WHY = {"why": None}                                        # why the open project couldn't be named (messages)


def _main_title():
    try:
        main = _fl_main_window()
    except Exception:
        return ""
    return (main[1] if main else "") or ""


def _note_open_proof(path):
    """FL saved through the bridge and THIS file changed: proof that it is the project FL has open (and FL holds
    exactly what is in the file now)."""
    _OPEN_PROOF.update(path=os.path.abspath(path), title=_main_title(), t=time.time())
    _note_proven_open(path, "save", persist=False)
    _note_fl_holds(path)                                          # (writes the hold record, the proof with it)


def _proof_for(title, ttl=OPEN_PROOF_TTL_S):
    p = _OPEN_PROOF.get("path")
    if p and title and _OPEN_PROOF.get("title") == title and time.time() - _OPEN_PROOF.get("t", 0) < ttl \
            and os.path.isfile(p):
        return p
    return None


def _proven_open(project, ttl=120.0):
    """True when a save through the bridge proved (within `ttl` s, FL's title unchanged since) that FL has exactly
    this file open."""
    p = _proof_for(_main_title(), ttl)
    return bool(p) and _ud_key(p) == _ud_key(project)


def _rel(p):
    for r in _root_entries(os.environ.get("FLH_ROOTS", "")):
        if _under(os.path.normcase(os.path.abspath(p)), os.path.normcase(os.path.abspath(r))):
            return os.path.relpath(p, r)
    return p


def _open_project_guess():
    """(path, titles) of the project FL has open. Only FL's MAIN window title counts (floating plugin and channel
    windows are top-level windows too), and its project name must equal the file's stem (or the project's title)
    exactly - 'Beat' never matches 'Beat 2'. FL's title shows only a name, so the answer is a file only when one
    file can be meant: exactly one project in FLH_ROOTS (or the last one opened) has that name or title, or a save
    through the bridge just showed which file FL writes. None when it can't be told for sure (loading, FL's
    default 'Project 3' name, several files with that name) - _GUESS_WHY says why."""
    titles = [t for _, t in _fl_windows()]
    main = _fl_main_window(); mt = main[1] if main else ""
    stem = _title_stem(mt)
    _GUESS_WHY["why"] = None
    if not stem:
        _GUESS_WHY["why"] = "FL's window title names no project yet (FL is starting or loading a project)"
        return None, titles
    proof = _proof_for(mt)
    if proof and stem.lower() in _project_names(proof):
        return proof, titles
    cands = _name_candidates(stem)
    if _is_untitled(mt):                                          # FL's default name: maybe never saved at all
        _GUESS_WHY["why"] = (f"FL shows '{stem}', FL's default name for a new project: it may never have been saved, "
                             "so only a save through FL can tell which file (if any) it is")
        return None, titles
    if len(cands) == 1:
        return cands[0], titles
    if not cands:
        _GUESS_WHY["why"] = (f"FL shows '{stem}', but no project in FLH_ROOTS has that file name or title (it was "
                             "opened from another folder, or is new and unsaved)")
    else:
        fix = None
        try:
            fix = (_title_warning(cands[0]) or {}).get("fix")
        except Exception:                                         # noqa: BLE001
            fix = None
        _GUESS_WHY["why"] = (f"FL shows '{stem}' and {len(cands)} project files have that name or title "
                             f"({'; '.join(_rel(c) for c in cands[:4])}); FL's title doesn't say which one is open. "
                             "Fix: fl_open(<the one you mean>) once (fl-headless then knows which), or give them "
                             "distinct titles" + (f": {fix}" if fix else " (flp_project_info title=...)"))
    return None, titles


def _open_project_identify(wait_s=6.0):
    """(path, how) of the project FL has open, PROVEN - for tools that act on 'the open project' (fl_save, adding
    effects in the open song). FL's title when it names one file. When several files share the name / title FL's
    window shows ('Song.flp' and 'Song (v2).flp' both titled 'Song'), a save through FL shows which (FL writes only
    its own file; every candidate's guards are checked first: none FL holds an older copy of, none changed behind FL,
    no live preview mutes) - the file fl-headless last proved open (a save landed, the reload marker read back, an open
    it watched: _LAST_PROVEN) tried first. Never a guess from the title alone: a twin switched by hand in FL shows the
    same title. Raises RuntimeError with the reason and the fix when nothing proves it."""
    cur, _ = _open_project_guess()
    if cur:
        return cur, "FL's title"
    stem = _title_stem(_main_title())
    cands = _name_candidates(stem) if stem else []
    why = _GUESS_WHY.get("why") or "FL's window title names no project"
    if len(cands) < 2 or _is_untitled(_main_title()):
        raise RuntimeError(why)
    pv = _proven_pick(cands, stem)
    if pv:
        cands = [pv] + [c for c in cands if _ud_key(c) != _ud_key(pv)]
    got = _prove_open(cands[0], wait_s=wait_s)                    # raises with the guard's reason
    if isinstance(got, str) and got != "never_saved":
        return got, f"FL's save landed in it ({len(cands)} files share the title '{stem}')"
    raise RuntimeError(f"FL was asked to save, but the save landed in none of {[_rel(c) for c in cands[:4]]}: {why}")


def _open_state(project):
    """'open' (FL shows exactly this project), 'not_open', or 'unknown' (FL runs but its main window names no project
    yet, or names one with this project's name that couldn't be pinned to this file). Writers refuse on 'unknown'
    rather than write behind FL's back - after first trying to prove it with a save (_with_open_project)."""
    try:
        if not fl_running():
            return "not_open"
    except Exception:
        return "not_open"
    try:
        cur, _t = _open_project_guess()
    except Exception:
        cur = None
    if cur:
        return "open" if _ud_key(cur) == _ud_key(project) else "not_open"
    try:
        main = _fl_main_window()
    except Exception:                                             # windows can't be read here (not Windows)
        return "not_open"
    if not main:
        _GUESS_WHY["why"] = "FL has no main window right now (starting or closing)"
        return "unknown"                                          # FL starting or closing
    stem = _title_stem(main[1])
    if not stem:
        return "not_open" if _is_untitled(main[1]) and " - fl studio" in str(main[1]).lower() else "unknown"
    return "unknown" if stem.lower() in _project_names(project) else "not_open"


def _open_why(project):
    """A sentence on why it couldn't be told whether FL has `project` open."""
    return _GUESS_WHY.get("why") or f"FL's window title can't be matched to {os.path.basename(project)} for sure"


def _title_is_one_of(paths):
    """True when FL's main window names one of these projects exactly (before answering 'No' to 'save changes?')."""
    try:
        main = _fl_main_window()
    except Exception:
        return False
    stem = _title_stem(main[1] if main else "")
    if not stem:
        return False
    return any(stem.lower() in _project_names(p) for p in paths if p)


def _fl_main_window():
    """(hwnd, title) of FL's main window: the one titled '... - FL Studio <ver>' or 'FL Studio <ver>', else the
    largest. Floating plugin / channel windows are top-level windows too and must not get the close message."""
    import ctypes
    from ctypes import wintypes
    wins = _fl_windows()
    named = [w for w in wins if re.search(r"(^| - )FL Studio( \d+)?\s*$", w[1])]
    if named:
        return named[0]
    best, area = None, -1
    for hwnd, t in wins:
        r = wintypes.RECT(); ctypes.windll.user32.GetWindowRect(hwnd, ctypes.byref(r))
        a = (r.right - r.left) * (r.bottom - r.top)
        if a > area:
            best, area = (hwnd, t), a
    return best


def _is_untitled(title):
    """FL 2026 calls new projects 'Project 2' etc. ('Untitled' before); saving those opens a Save As box."""
    t = (title or "").strip().lstrip("*").strip()
    if " - fl studio" not in t.lower():
        return True
    stem = t[:t.lower().index(" - fl studio")].strip().rstrip("*").strip()
    return bool(re.fullmatch(r"(%s)([ _]\d+)?" % "|".join(UNTITLED_WORDS), stem, re.I))   # 'Project_2' (FL 2026.1.7)


# FL's default project names in its UI languages (and older 'Untitled'): saving those asks for a path
UNTITLED_WORDS = ("untitled", "project", "unbenannt", "projekt", "sans titre", "projet", "sin título", "proyecto",
                  "senza titolo", "progetto", "sem título", "projeto", "naamloos", "bez tytułu", "без названия",
                  "проект", "無題", "プロジェクト", "未命名", "项目", "專案", "제목 없음", "프로젝트")


def _blank_project():
    """An empty project to switch to when FL must re-read the project it has open (FL ignores a request to open
    the project that is already open): FLH_BLANK, else FL's own empty template (factory or user templates)."""
    cands = [os.environ.get("FLH_BLANK", "")]
    try:
        base = os.path.dirname(fl_exe())
        cands += glob.glob(os.path.join(base, "Data", "Templates", "**", "Empty*.flp"), recursive=True)
        cands += glob.glob(os.path.join(base, "Data", "Templates", "Minimal", "**", "*.flp"), recursive=True)
    except Exception:
        pass
    for docs in _documents_dirs():
        for t in (("Projects", "Templates"), ("FL Studio", "Projects", "Templates"), ("Templates",)):
            if os.path.isdir(os.path.join(docs, *t)):
                cands += glob.glob(os.path.join(docs, *t, "**", "Empty*.flp"), recursive=True)
    return next((c for c in cands if c and os.path.isfile(c)), None)


# Popup words in FL's / Windows' UI languages. Text matching is only a first guess: structure (dialog class, file
# view, standard control ids) and FL's own message-box class are checked too, so other languages still work.
DIALOG_WORDS = {
    "save_as": ("save as", "name and location", "speichern unter", "enregistrer sous", "guardar como", "salva con nome",
                "salvar como", "opslaan als", "zapisz jako", "сохранить как", "名前を付けて保存", "另存为", "另存新檔",
                "다른 이름으로 저장"),
    "save": ("save", "speichern", "enregistrer", "guardar", "salva", "salvar", "opslaan", "zapisz", "сохран", "保存",
             "儲存", "저장"),
    "changes": ("change", "modified", "before", "änderung", "modif", "cambio", "modific", "alteraç", "wijziging",
                "zmian", "измен", "変更", "更改", "修改", "變更", "변경"),
    "missing": ("missing", "not found", "couldn't", "could not", "nicht gefunden", "fehlt", "introuvable", "manquant",
                "no se encontr", "falta", "non trovat", "mancant", "não encontrad", "niet gevonden", "nie znaleziono",
                "не найден", "отсутств", "見つかりません", "找不到", "缺少", "찾을 수 없"),
    "open": ("open", "öffnen", "ouvrir", "abrir", "apri", "openen", "otwórz", "открыт", "開く", "打开", "開啟", "열기"),
}


def _has(t, group):
    return any(w in t for w in DIALOG_WORDS[group])


def _dialog_kind(title, texts):
    t = (title + " " + " ".join(texts)).lower()
    if _has(t, "save_as"):
        return "save_as"
    if _has(t, "save") and _has(t, "changes"):
        return "save_changes"
    if _has(t, "missing"):
        return "missing_file"
    return "other"


def _is_file_dialog(hwnd):
    """A Windows file dialog (Open / Save As) in any language: a #32770 with a shell file view or a file-name box."""
    import ctypes
    from ctypes import wintypes
    user32 = ctypes.windll.user32; seen = set()
    proc = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)

    def cb(ch, _):
        c = ctypes.create_unicode_buffer(64); user32.GetClassNameW(ch, c, 64); seen.add(c.value)
        return True
    user32.EnumChildWindows(wintypes.HWND(hwnd), proc(cb), 0)
    return bool(seen & {"SHELLDLL_DefView", "DUIViewWndClassName", "DirectUIHWND"}) and \
        bool(seen & {"Edit", "ComboBoxEx32"})


def fl_dialogs():
    """FL's open popups (save prompts, Save As, warnings): title, the text and buttons found in them, and a kind."""
    import ctypes
    from ctypes import wintypes
    user32 = ctypes.windll.user32; main = _fl_main_window(); out = []
    for hwnd, title in _fl_windows():
        if main and hwnd == main[0]:
            continue
        cls = ctypes.create_unicode_buffer(256); user32.GetClassNameW(hwnd, cls, 256)
        owner = _user32().GetWindow(hwnd, 4)                       # GW_OWNER: dialogs are owned by FL
        enabled_main = bool(main) and bool(user32.IsWindowEnabled(main[0]))
        if cls.value != "#32770" and not owner and enabled_main:
            continue                                             # a floating editor window, not a popup
        texts, buttons = [], []
        proc = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)

        def cb(ch, _):
            n = user32.GetWindowTextLengthW(ch); b = ctypes.create_unicode_buffer(n + 1); user32.GetWindowTextW(ch, b, n + 1)
            c = ctypes.create_unicode_buffer(64); user32.GetClassNameW(ch, c, 64)
            if b.value:
                (buttons if "button" in c.value.lower() else texts).append(b.value)
            return True
        user32.EnumChildWindows(hwnd, proc(cb), 0)
        kind = "save_changes" if (cls.value == "TMsgForm" and title.strip().lower() == "confirm") \
            else _dialog_kind(title, texts)
        fdlg = cls.value == "#32770" and kind == "other" and _is_file_dialog(hwnd)
        if fdlg:                                                 # a file dialog: Open, else (any language) Save As
            kind = "open_dialog" if _has(title.lower(), "open") else "save_as"
        d = {"hwnd": int(hwnd), "title": title, "class": cls.value, "text": texts[:8], "buttons": buttons[:8],
             "kind": kind, "blocks_fl": not enabled_main}
        if fdlg:
            d["file_dialog"] = True
        out.append(d)
    return out


AUDIO_FILE_RE = re.compile(r"\.(wav|flac|mp3|ogg|aiff?|m4a)\s*$", re.I)


def _popup_info(hwnd):
    """A fl_dialogs()-style entry for one window (title, class, texts, buttons, kind, file_dialog)."""
    import ctypes
    from ctypes import wintypes
    user32 = ctypes.windll.user32
    n = user32.GetWindowTextLengthW(hwnd); b = ctypes.create_unicode_buffer(n + 1); user32.GetWindowTextW(hwnd, b, n + 1)
    cls = ctypes.create_unicode_buffer(256); user32.GetClassNameW(hwnd, cls, 256)
    texts, buttons = [], []
    proc = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)

    def cb(ch, _):
        k = user32.GetWindowTextLengthW(ch); t = ctypes.create_unicode_buffer(k + 1); user32.GetWindowTextW(ch, t, k + 1)
        c = ctypes.create_unicode_buffer(64); user32.GetClassNameW(ch, c, 64)
        if t.value:
            (buttons if "button" in c.value.lower() else texts).append(t.value)
        return True
    user32.EnumChildWindows(wintypes.HWND(hwnd), proc(cb), 0)
    title = b.value; kind = _dialog_kind(title, texts)
    fdlg = cls.value == "#32770" and _is_file_dialog(hwnd)
    if fdlg and kind == "other":
        kind = "open_dialog" if _has(title.lower(), "open") else "save_as"
    d = {"hwnd": int(hwnd or 0), "title": title, "class": cls.value, "text": texts[:8], "buttons": buttons[:8],
         "kind": kind, "blocks_fl": True}
    if fdlg:
        d["file_dialog"] = True
    return d


def _fl_blocking_popup():
    """The popup FL is stuck on, or None: a modal box that disables FL's main window, or a file dialog (Open / Save
    As) FL shows - while one is up FL ignores Ctrl+O. When fl_dialogs() misses it (a plugin's own file dialog, e.g.
    Edison asking where to save a recorded take: PC 2026-10-23, fl_open said only 'FL may be busy or minimised'),
    Windows' record of the main window's enabled popup / last active popup names it.
    PC-VERIFY: record a take in Edison, leave its 'Save As' up: _fl_blocking_popup() names it, fl_open refuses with
    that title (no Ctrl+O sent), fl_pc_check's restore cancels it and reopens the song."""
    try:
        ds = list(fl_dialogs())
    except Exception:
        ds = []
    files = [d for d in ds if d.get("file_dialog") or d.get("kind") in ("save_as", "open_dialog")]
    if os.name != "nt":
        return (files or [d for d in ds if d.get("blocks_fl")] or [None])[0]
    try:
        import ctypes
        from ctypes import wintypes
        main = _fl_main_window()
        if not main or ctypes.windll.user32.IsWindowEnabled(main[0]):
            return files[0] if files else None
        u = _user32()
        cand = u.GetWindow(main[0], 6)                            # GW_ENABLEDPOPUP: the modal window FL waits on
        if not cand or _hwnd_eq(cand, main[0]):
            f = u.GetLastActivePopup; f.restype = wintypes.HWND; f.argtypes = [wintypes.HWND]
            cand = f(main[0])
        if not cand or _hwnd_eq(cand, main[0]):
            fg = u.GetForegroundWindow(); pid = wintypes.DWORD()
            ctypes.windll.user32.GetWindowThreadProcessId(fg, ctypes.byref(pid))
            cand = fg if fg and pid.value in set(_fl_pids()) and not _hwnd_eq(fg, main[0]) else None
        if not cand:
            return (files or ds or [None])[0]
        known = next((d for d in ds if _hwnd_eq(d.get("hwnd"), cand)), None)
        return known or _popup_info(cand)
    except Exception:
        return (files or [d for d in ds if d.get("blocks_fl")] or [None])[0]


def _popup_words(d):
    """'<title>' (file: <name>) for messages about a popup."""
    if not d:
        return ""
    name = next((t for t in d.get("text") or [] if AUDIO_FILE_RE.search(t) or t.lower().endswith(".flp")), None)
    return f"'{d.get('title') or d.get('class') or 'a popup'}'" + (f" (file: {name})" if name else "")


def fl_dialog(action="list", button=None, hwnd=None):
    """list: FL's popups. click: press a button by its caption (e.g. 'Yes', 'No', 'Save', 'Skip', 'Cancel') in the
    popup (hwnd, or the only one open); 'escape' / 'enter' send that key instead (for popups without real buttons)."""
    import ctypes
    from ctypes import wintypes
    ds = fl_dialogs()
    if action == "list":
        return {"dialogs": ds}
    if action != "click":
        raise ValueError("action: list or click")
    if hwnd is None:
        if len(ds) != 1:
            raise ValueError(f"{len(ds)} popups open; say which (hwnd): {[(d['hwnd'], d['title']) for d in ds]}")
        hwnd = ds[0]["hwnd"]
    key = str(button or "").strip().lower()
    d0 = next((d for d in ds if d["hwnd"] == hwnd), None)
    if _has_anyway_word(key) or (d0 and _is_save_anyway(d0) and key not in ("cancel", "no", "escape",
                                                                                             "esc", "nein", "non")):
        raise ValueError("that's FL's demo/trial 'save anyway' warning: fl-headless never answers it (house rule) - "
                         "the user decides in FL")
    if d0 and d0.get("kind") == "save_changes" and (key in ("yes", "save", "enter", "return", "ok") or
                                                    key in BUTTON_WORDS["yes"] or key in BUTTON_WORDS["save"]):
        blocked = _stale_block()                                  # FL holds an OLDER copy than the file: its save
        if blocked:                                               # would undo the newer edits on disk
            raise ValueError(blocked.replace("not saved:", f"'{button}' not pressed:", 1) +
                             ". Answer No (or Cancel) to this question instead")
    user32 = ctypes.windll.user32
    if key in ("escape", "esc", "enter", "return", "ok", "close"):
        vk = 0x1B if key.startswith("esc") else 0x0D
        how = _press_vk(hwnd, vk)
        if not how and key in ("ok", "close", "enter", "return") and not _is_save_question(hwnd):
            user32.PostMessageW(hwnd, 0x0010, 0, 0)               # WM_CLOSE: an OK-only notice just closes
            time.sleep(0.6)
            how = "closed" if not user32.IsWindow(hwnd) or not user32.IsWindowVisible(hwnd) else None
        return {"sent": key, "via": how, "dialogs_left": fl_dialogs()}
    found = []
    proc = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)
    names = {key} | set(BUTTON_WORDS.get(key, ()))

    def cb(ch, _):
        n = user32.GetWindowTextLengthW(ch); b = ctypes.create_unicode_buffer(n + 1); user32.GetWindowTextW(ch, b, n + 1)
        cap = re.sub(r"\s*\(&?\w\)$", "", b.value.replace("&", "")).strip().lower()   # 'はい(&Y)' -> 'はい'
        if cap in names:
            found.append(ch)
        return True
    user32.EnumChildWindows(wintypes.HWND(hwnd), proc(cb), 0)
    cls = ctypes.create_unicode_buffer(64); user32.GetClassNameW(wintypes.HWND(hwnd), cls, 64)
    if not found and key in BUTTON_IDS and cls.value == "#32770":   # Windows dialogs: a button's control id is
        item = _user32().GetDlgItem(hwnd, BUTTON_IDS[key])       # the same in every language
        if item:
            found.append(item)
    if not found:
        # FL's own message boxes paint their buttons (no child windows): press the button's accelerator instead,
        # first the English letter, then the one Windows' UI language uses (Ja -> J, Oui -> O, Sí -> S...)
        letters = [key[0]] if key else []
        loc = _ui_accelerator(key)
        if loc and loc not in letters:
            letters.append(loc)
        for letter in letters:
            if _press_accelerator(hwnd, letter):
                return {"clicked": button, "via": f"keyboard ({letter.upper()})", "dialogs_left": fl_dialogs()}
        raise ValueError(f"no button '{button}' in that popup and its key didn't answer it; answer it in FL")
    user32.PostMessageW(found[0], 0x00F5, 0, 0)                  # BM_CLICK
    time.sleep(0.6)
    return {"clicked": button, "dialogs_left": fl_dialogs()}


# Button captions in common UI languages (lower case, no '&') and the standard dialog control ids
BUTTON_WORDS = {
    "yes": ("ja", "oui", "sí", "si", "sì", "sim", "tak", "да", "はい", "是", "예"),
    "no": ("nein", "non", "nee", "não", "nie", "нет", "いいえ", "否", "아니요"),
    "cancel": ("abbrechen", "annuler", "cancelar", "annulla", "annuleren", "anuluj", "отмена", "キャンセル", "取消", "취소"),
    "ok": ("ок", "确定", "確定", "확인"),
    "save": ("speichern", "enregistrer", "guardar", "salva", "salvar", "opslaan", "zapisz", "сохранить", "保存", "儲存",
             "저장"),
    "skip": ("überspringen", "ignorer", "omitir", "ignora", "pular", "overslaan", "pomiń", "пропустить", "スキップ",
             "跳过", "건너뛰기"),
}
BUTTON_IDS = {"ok": 1, "cancel": 2, "abort": 3, "retry": 4, "ignore": 5, "yes": 6, "no": 7, "continue": 11}
_ACCEL = {"yes": {0x07: "j", 0x13: "j", 0x0C: "o", 0x0A: "s", 0x10: "s", 0x16: "s", 0x15: "t"},
          "no": {}}                                              # 'no' is N in nearly every Latin-script language


def _ui_accelerator(key):
    """The likely accelerator letter of a Yes button in Windows' UI language (None when it's the English one)."""
    try:
        import ctypes
        lang = ctypes.windll.kernel32.GetUserDefaultUILanguage() & 0x3FF
    except Exception:
        return None
    return _ACCEL.get(key, {}).get(lang)


def _is_save_question(hwnd):
    return any(d["hwnd"] == hwnd and d["kind"] in ("save_changes", "save_as") for d in fl_dialogs())


def _press_vk(hwnd, vk, wait_s=1.5):
    """Press a key in a popup: posted to it first, then for real with the popup in front (Delphi message boxes
    only take the latter). Returns how it closed, or None if it's still open."""
    import ctypes
    user32 = ctypes.windll.user32
    gone = lambda: not user32.IsWindow(hwnd) or not user32.IsWindowVisible(hwnd)
    user32.PostMessageW(hwnd, 0x0100, vk, 0); user32.PostMessageW(hwnd, 0x0101, vk, 0)
    t0 = time.time()
    while time.time() - t0 < wait_s:
        if gone():
            return "posted"
        time.sleep(0.1)
    user32.keybd_event(0x12, 0, 0, 0); user32.keybd_event(0x12, 0, 2, 0)   # lets a background app take focus
    user32.SetForegroundWindow(hwnd); time.sleep(0.15)
    user32.keybd_event(vk, 0, 0, 0); user32.keybd_event(vk, 0, 2, 0)
    t0 = time.time()
    while time.time() - t0 < wait_s:
        if gone():
            return "keyboard"
        time.sleep(0.1)
    return None


def _press_accelerator(hwnd, letter, wait_s=2.0):
    """Answer a popup by its button letter (Y / N / C...): first as messages to the popup, then as real key presses
    with the popup in front. True once the popup has closed."""
    import ctypes
    user32 = ctypes.windll.user32; vk = ord(letter.upper())
    tries = [lambda: (user32.PostMessageW(hwnd, 0x0100, vk, 0), user32.PostMessageW(hwnd, 0x0102, ord(letter.lower()), 0),
                      user32.PostMessageW(hwnd, 0x0101, vk, 0)),
             lambda: (user32.keybd_event(0x12, 0, 0, 0), user32.keybd_event(0x12, 0, 2, 0), user32.SetForegroundWindow(hwnd),
                      time.sleep(0.15), user32.keybd_event(vk, 0, 0, 0), user32.keybd_event(vk, 0, 2, 0))]
    for t in tries:
        t(); t0 = time.time()
        while time.time() - t0 < wait_s:
            if not user32.IsWindow(hwnd) or not user32.IsWindowVisible(hwnd):
                return True
            time.sleep(0.1)
    return False


_OPEN_REFUSAL = {"why": None}                                   # why the last Open was refused (not a failure)
_DISCARD_ANY = "*any*"            # discard_ok: 'No' to 'save changes?' whatever FL shows (fl_open save_current=false)
_OPEN_PENDING = {"project": None, "t": 0.0}                       # fl_open sent FL a project it hasn't shown yet
OPEN_SWITCH_IDLE_S = 8.0          # after an Open: FL's title unchanged and nothing loading this long -> it ignored it
OPEN_PENDING_MAX_S = 600.0        # an fl_open still 'loading' after this long no longer holds previews back
OPEN_SWITCH_CAP_S = 30.0          # fl_open waits for the switch: 2.5 x the project's load cost + this (scaled)


def _open_pending_now():
    """The project an fl_open sent FL that FL hasn't shown yet (still switching / loading), else None. Cleared once
    FL's title names it and nothing loads - or after OPEN_PENDING_MAX_S (FL was switched by hand since)."""
    pend = _OPEN_PENDING.get("project")
    if not pend:
        return None
    try:
        landed = _title_is_one_of([pend]) and not _fl_loading_title()
    except Exception:                                             # noqa: BLE001
        landed = False
    if landed or time.time() - float(_OPEN_PENDING.get("t") or 0) > _scaled(OPEN_PENDING_MAX_S):
        _OPEN_PENDING.update(project=None, t=0.0)
        return None
    return pend


def _discard_ok_now(discard_ok, project):
    """'No' to FL's 'save changes?' is allowed now: the caller said discard (save_current=false), or FL's main window
    names one of `discard_ok` (default: `project`)."""
    if discard_ok == _DISCARD_ANY:
        return True
    return _title_is_one_of(discard_ok or [project])


def _fl_ui_busy():
    """FL's UI thread is busy (loading a project): its script's heartbeat file exists but stopped beating. A slow /
    heavy load can keep FL's title unchanged for a long time without 'Opening: ...'; that is not 'FL ignored the
    Open' (a second Open into a loading FL is never sent)."""
    try:
        hb = os.path.join(_mailbox_dir(), "alive.json")
        return os.path.exists(hb) and not _mailbox_alive(max_age=3.0) and fl_running()
    except Exception:                                             # noqa: BLE001
        return False


def _await_switch(project, before_title, bridge_up=None):
    """After FL's Open dialog took `project`'s path: did FL switch? -> 'shown' (FL's title names it), 'loading' (FL
    still loading at the longest wait), 'same_name' (FL showed that name before: the title can't tell), or None (FL's
    title stayed on the old project with nothing loading for OPEN_SWITCH_IDLE_S: FL ignored the Open). The wait
    follows the project's load cost while FL shows progress (a loading title, a title change).
    PC-VERIFY: fl_open of a big project returns 'shown' after the load; an Open FL ignored is retried once."""
    names = _project_names(project)
    before_stem = (_title_stem(before_title) or "").lower()
    if before_stem and before_stem in names:
        return "same_name"
    cost = _load_cost_guess(project)[0] or 0.0
    # PC 2026-10-23: 'first_open_ignored_s 9.8 / 20.4' on songs that load in 10-26 s - FL was still loading the first
    # Open (no 'Opening: ...' in its title yet), the retry's Ctrl+O waited in FL's queue and left a 'Confirm' and an
    # Open dialog behind. 'Ignored' now needs a whole load cost of no sign at all, and FL not busy at that moment
    t0 = time.time(); idle = _scaled(max(OPEN_SWITCH_IDLE_S, OPEN_IGNORE_COST_FRAC * cost))
    cap = t0 + _scaled(max(OPEN_SWITCH_IDLE_S, 2.5 * cost + OPEN_SWITCH_CAP_S))
    seen, last_change = None, t0
    if bridge_up is None:                                         # (a bridge that answered before and stops: loading)
        bridge_up = _ping_ok()
    while True:
        mt = _main_title(); lt = _fl_loading_title(); stem = (_title_stem(mt) or "").lower()
        if not lt and ((stem and stem in names) or _open_state(project) == "open"):
            return "shown"
        now = time.time()
        if (mt, lt) != seen:
            seen, last_change = (mt, lt), now
        if lt or (mt and mt != before_title) or _fl_ui_busy():    # loading, the title moved on, or FL's UI thread
            last_change = now                                     # busy (its script's heartbeat stopped): progress
        if now >= cap:
            return "loading" if (lt or (mt and mt != before_title) or _fl_ui_busy()) else None
        if now - last_change >= idle:
            if _fl_load_busy(bridge_up):                          # FL busy (bridge silent / CPU): still loading
                last_change = now
            else:
                return None
        time.sleep(0.25)


OPEN_IGNORE_COST_FRAC = 1.0       # 'FL ignored the Open' only after this share of the project's load cost w/o a sign
OPEN_LEFTOVER_GRACE_S = 1.5       # after a retried Open: a Ctrl+O FL queued while busy surfaces within this


def _fl_load_busy(bridge_up=False, cpu=True):
    """FL looks busy loading right now: 'Opening: ...' in its title, its script's heartbeat stopped, the bridge that
    answered before (bridge_up) no longer answers, or (cpu) the FL process using CPU (Windows). A Ctrl+O sent now would
    wait in FL's queue and pop up later. PC-VERIFY: True during a 20 s load of a big project with an unchanged title."""
    try:
        if _fl_loading_title() or _fl_ui_busy():
            return True
        if bridge_up and not _ping_ok():
            return True
        return bool(_fl_cpu_busy()) if cpu else False
    except Exception:                                             # noqa: BLE001
        return False


def _wait_load_out(project, wait_s=None, bridge_up=False, cpu=True):
    """Wait while FL is busy loading (bounded by the project's load cost, scaled). -> seconds waited. cpu=False: FL's
    CPU use alone isn't 'loading' (sample streamers keep it busy for good once a song is in: PC 2026-10-26, every
    reload of a LABS/Spitfire song waited out the whole 30 s cap after the load had long finished)."""
    t0 = time.time()
    cost = (_load_cost_guess(project)[0] or 0.0) if project else 0.0
    limit = _scaled(wait_s if wait_s is not None else max(OPEN_SWITCH_IDLE_S, 1.5 * cost + 10.0))
    while time.time() - t0 < limit and _fl_load_busy(bridge_up, cpu=cpu):
        time.sleep(0.25)
    return round(time.time() - t0, 1)


def _sweep_leftover_popups(before, save_current, rounds=3):
    """After an open / switch / reload: close the file dialogs and save prompts that appeared since `before` (a set of
    popup hwnds) - the ones fl-headless' own Ctrl+O left behind (an Open FL showed late, its 'save changes?'). An Open
    dialog gets Cancel; a 'save changes?' gets No when save_current is false (the caller said: don't save), else
    Cancel (it asks about the project just opened, nothing asked to save it; Cancel also stops the Open behind it);
    a Save As gets Esc (never a path typed). A demo 'Save anyway' box gets Cancel (never answered). Other popups (FL's
    own notices about the loaded song) are left alone. -> [{popup, kind, did}] of what was closed.
    PC-VERIFY: a retried fl_open on a big song leaves no 'Confirm' / Open dialog behind (checklists/core.md)."""
    done = []; handled = set(before or ())
    for _ in range(rounds):
        try:
            ds = [d for d in fl_dialogs() if d.get("hwnd") not in handled]
        except Exception:                                         # noqa: BLE001 - no window access: nothing to do
            return done
        acted = False
        for d in ds:
            kind = d.get("kind"); h = d.get("hwnd"); did = None
            handled.add(h)
            try:
                if _is_save_anyway(d):
                    did = "cancel" if _press_vk(h, 0x1B) else None
                elif kind == "save_changes":
                    if save_current is False and _answer_one(h, "no"):
                        did = "no"
                    else:
                        did = "cancel" if _press_vk(h, 0x1B) else None
                elif kind == "open_dialog" or (d.get("file_dialog") and kind != "save_as"):
                    did = "cancel" if _press_vk(h, 0x1B) else None
                elif kind == "save_as":
                    did = "esc" if _press_vk(h, 0x1B) else None
            except Exception:                                     # noqa: BLE001
                did = None
            if kind in ("save_changes", "open_dialog", "save_as") or d.get("file_dialog") or did:
                done.append({"popup": d.get("title") or d.get("class"), "kind": kind, "did": did or "couldn't close"})
                acted = acted or bool(did)
        if not acted:
            break
        time.sleep(0.3)                                           # 'No' to 'save changes?' brings FL's Open dialog
    return done


def _popups_said(done):
    return "; ".join(f"'{d.get('popup')}' ({d.get('kind')}): {d.get('did')}" for d in done[:6])


def _await_switch_quick(project):
    """FL's title names `project` right now and nothing loads -> 'shown', else None (one look, no waiting)."""
    try:
        stem = (_title_stem(_main_title()) or "").lower()
        if not _fl_loading_title() and ((stem and stem in _project_names(project)) or _open_state(project) == "open"):
            return "shown"
    except Exception:                                             # noqa: BLE001
        pass
    return None
# FL's demo/trial warning on save is recognized by its OWN wording - multi-word phrases in its body text or a button
# caption - never by single words that a project name can hold ("Demo 2", "trial run", "toch", "comunque").
# PC-VERIFY: FL's exact warning text and buttons when saving with a demo plugin (FL 20/21/2024/2026, en/de/fr/es).
SAVE_ANYWAY_PHRASES = ("save anyway", "saving anyway", "demo version", "demo mode", "in demo", "trial version",
                       "trial mode", "unregistered", "unlock", "not registered", "purchase",
                       "trotzdem speichern", "demoversion", "demo-version", "demomodus", "testversion",
                       "enregistrer quand même", "enregistrer quand meme", "version de démonstration", "mode démo",
                       "guardar de todos modos", "guardar igualmente", "versión de demostración", "modo demo",
                       "salva comunque", "salvare comunque", "versione demo", "modalità demo",
                       "salvar mesmo assim", "salvar assim mesmo", "versão de demonstração", "versão demo",
                       "toch opslaan", "demoversie", "zapisz mimo to", "wersja demo", "wersja próbna",
                       "всё равно сохранить", "все равно сохранить", "сохранить всё равно", "сохранить все равно",
                       "демо-версия", "демоверсия", "демо-режим",
                       "とにかく保存", "体験版", "デモ版", "デモモード", "仍然保存", "仍要保存", "试用版", "演示版", "試用版",
                       "그래도 저장", "체험판", "데모 버전")
SAVE_ANYWAY_BUTTON_WORDS = ("anyway", "trotzdem", "quand même", "quand meme", "de todos modos", "igualmente",
                            "comunque", "mesmo assim", "assim mesmo", "toch", "mimo to", "всё равно", "все равно",
                            "とにかく", "仍然", "仍要", "그래도")
_QUOTED = re.compile(r"'[^']*'|\"[^\"]*\"|“[^”]*”|„[^“”]*[“”]|«[^»]*»|‘[^’]*’|「[^」]*」")
_SAVE_TO = re.compile(r"(save (the )?changes? (made )?to|änderungen (an|in) .{0,20}speichern|enregistrer les modifications "
                      r"(de|dans|à)|guardar (los )?cambios (en|de)|salvare le modifiche (a|in)|salvar (as )?alterações "
                      r"(em|de|no)|wijzigingen (in|aan) .{0,40}opslaan|zmiany w .{0,40}zapisa)(\W[^?!\n]*)?", re.I)


def _strip_names(t, extra=()):
    """Dialog text without project names: quoted parts, the name after 'save changes to', and FL's current title."""
    t = _QUOTED.sub(" ", t)
    t = _SAVE_TO.sub(" ", t)
    for n in extra:
        if n and len(n) > 1:
            t = re.sub(re.escape(n.lower()), " ", t)
    return t


def _is_save_anyway(d):
    """FL's demo/trial warning ('Save anyway'): never answered by fl-headless (house rule). Structural: a button
    captioned 'Save anyway' (any UI language), or the warning's own phrases in the body text once project names are
    taken out. A save question about a project called 'Demo 2' or 'trial run' is not one."""
    for b in d.get("buttons") or []:
        cap = str(b).replace("&", "").strip().lower()
        if any(w in cap for w in SAVE_ANYWAY_BUTTON_WORDS) or any(p in cap for p in SAVE_ANYWAY_PHRASES):
            return True
    names = []
    try:
        main = _fl_main_window()
        names.append(str(_title_stem(main[1] if main else "") or "").lower())
    except Exception:
        pass
    body = _strip_names(" ".join(str(x) for x in d.get("text") or []).replace("&", "").lower(), names)
    return any(p in body for p in SAVE_ANYWAY_PHRASES)


def _has_anyway_word(t):
    """A button caption the caller wants pressed that means 'save anyway' (fl_dialog refuses it)."""
    t = str(t or "").replace("&", "").strip().lower()
    return bool(t) and (any(w in t for w in SAVE_ANYWAY_BUTTON_WORDS) or any(p in t for p in SAVE_ANYWAY_PHRASES))


UNSAVED_NEW_MSG = ("FL has an unsaved new project open: save it or close it in FL first. fl-headless pressed Cancel, "
                   "so nothing was saved, overwritten or opened")


def _untitled_open():
    """FL's main window shows a new, never-saved project ('Project 3', 'Untitled'): saving it opens Save As."""
    t = _main_title()
    return bool(t) and _is_untitled(t)


def _fl_changed_flag():
    """FL's own 'project changed' flag through the bridge (general.getChangedFlag: 0 = nothing changed since it was
    created or loaded), or None when the bridge doesn't answer / an older script doesn't report it."""
    try:
        v = BRIDGE.call("state", timeout=3.0, light=True).get("changed")
        return int(v) if v is not None else None
    except Exception:
        return None


_TRUST_FRESH = {"until": 0.0}                                    # fl_pc_check: the person just made FL's project new


def _fresh_untitled():
    """FL shows a new, never-saved project that FL itself says is unchanged (File > New, nothing done since): leaving
    it loses nothing, so its 'save?' question may be answered No / Skip. PC-VERIFY: FL 2026's Ctrl+O on a fresh
    'Project_2' (the user's 2026-10-20 run left one; fl_open refused it)."""
    if not _untitled_open():
        return False
    if time.time() < _TRUST_FRESH["until"]:                       # once: the next open uses it up
        _TRUST_FRESH["until"] = 0.0
        return True
    return _fl_changed_flag() == 0


def _await_open_dialog(before, project, timeout_s=8.0, on_save="no", discard_ok=None, fresh_untitled=False):
    """After Ctrl+O: answer FL's 'save changes?' by policy and return FL's Open dialog (a fl_dialogs() entry), or None
    (with _OPEN_REFUSAL['why'] set when it was refused on purpose). Only the Open dialog is ever used: a Save As (FL
    saving a never-saved project) or any other new box gets Esc and a refusal, so the target's path is never typed
    into Save As (that would overwrite the target with the unsaved project).
    PC-VERIFY: with a modified 'Project N' in FL, Ctrl+O's 'save changes?' gets Cancel and FL keeps the project; in
    a UI language whose 'Project' isn't in UNTITLED_WORDS, the Save As after Yes gets Esc and nothing is saved."""
    t0, handled, answered_yes = time.time(), set(), False
    timeout_s = _scaled(timeout_s)                                # a slow PC shows FL's dialogs later
    while time.time() - t0 < timeout_s:
        time.sleep(0.05)
        for d in fl_dialogs():
            if d["hwnd"] in before or d["hwnd"] in handled:
                continue
            kind = d.get("kind")
            # FL asks before leaving a changed project. Its 'Confirm' box is recognized by title; in another UI
            # language, an FL message box (TMsgForm) popping up right after Ctrl+O is that same question
            if kind == "save_changes" or (d.get("class") == "TMsgForm" and kind == "other"):
                handled.add(d["hwnd"])
                if _is_save_anyway(d):                           # a demo/trial 'Save anyway' box: never answered
                    _press_vk(d["hwnd"], 0x1B)                    # Esc = Cancel: no popup left behind, nothing saved
                    _OPEN_REFUSAL["why"] = (f"FL shows '{d['title']}' (a demo/trial save warning: a plugin in the "
                                            "project runs as a demo); fl-headless never answers 'Save anyway', so it "
                                            "pressed Cancel and stopped - remove or replace that plugin, or decide in FL")
                    return None
                if on_save == "no" and not _discard_ok_now(discard_ok, project):
                    _press_vk(d["hwnd"], 0x1B)                    # Cancel: FL keeps the other project as it is
                    _OPEN_REFUSAL["why"] = ("FL asked to save changes to a project other than the one being reloaded; "
                                            "answered Cancel (nothing thrown away) and stopped - save or close it in FL")
                    return None
                if fresh_untitled and _untitled_open() and (_answer_one(d["hwnd"], "no") or
                                                              _answer_one(d["hwnd"], "skip")):
                    t0 = time.time(); break                       # a fresh, unchanged new project: nothing to lose
                if on_save == "yes" and _untitled_open():         # Yes would bring up Save As: the user decides
                    _press_vk(d["hwnd"], 0x1B)
                    _OPEN_REFUSAL["why"] = UNSAVED_NEW_MSG
                    return None
                if on_save not in ("yes", "no") or not _answer_one(d["hwnd"], on_save):
                    return None
                answered_yes = answered_yes or on_save == "yes"
                t0 = time.time(); break
            title = str(d.get("title") or "")
            if kind == "open_dialog" or (d.get("file_dialog") and not answered_yes
                                         and not _has(title.lower(), "save_as")):
                return d                                          # (a file dialog right after Ctrl+O: Open, any language)
            if kind == "save_as" and not d.get("file_dialog") and _untitled_open() and \
                    (fresh_untitled or (on_save == "no" and discard_ok == _DISCARD_ANY)):
                handled.add(d["hwnd"])                            # FL 2026's own 'Save as' box (Skip/Save/Cancel)
                if _answer_one(d["hwnd"], "skip"):                # for a fresh, unchanged new project (or the caller
                                                                  # said save_current=false): Skip
                    t0 = time.time(); continue
            if kind == "save_as" or d.get("file_dialog") or d.get("class") == "#32770":
                handled.add(d["hwnd"])
                try:
                    _press_vk(d["hwnd"], 0x1B)                    # Esc: never type a path into it
                except Exception:
                    pass
                if (kind == "save_as" or d.get("file_dialog")) and any(AUDIO_FILE_RE.search(str(t))
                                                                        for t in d.get("text") or []):
                    _OPEN_REFUSAL["why"] = (f"FL showed {_popup_words(d)} instead of its Open dialog: a plugin (e.g. "
                                            "Edison with an unsaved recording) asking where to save audio. fl-headless "
                                            "pressed Esc and stopped (nothing was opened) - save or discard that "
                                            "audio in FL, then try again")
                elif kind == "save_as" or d.get("file_dialog"):
                    _OPEN_REFUSAL["why"] = UNSAVED_NEW_MSG
                else:
                    _OPEN_REFUSAL["why"] = (f"FL showed '{title}' instead of its Open dialog; fl-headless pressed Esc "
                                            "and stopped (nothing was opened) - check FL, then try again")
                return None
    return None


def _answer_save_prompts(on_save, discard_ok=None):
    """Answer FL's 'save changes?' questions: on_save 'no' (the file on disk is newer - it was just edited) or 'yes'.
    'No' only while FL shows one of `discard_ok`. Returns what was answered."""
    done = []
    if on_save == "yes" and _untitled_open():
        return done                                               # Yes would open Save As for a never-saved project
    for d in fl_dialogs():
        if _is_save_anyway(d):
            continue
        if on_save == "no" and not (discard_ok and _discard_ok_now(discard_ok, None)):
            continue
        if d["kind"] == "save_changes" and on_save in ("yes", "no"):
            done.append({"popup": d["title"], "answered": on_save if _answer_one(d["hwnd"], on_save) else None})
    return done


def _answer_one(hwnd, on_save):
    try:
        return fl_dialog("click", on_save.capitalize(), hwnd).get("clicked") is not None
    except Exception:
        return False


def _open_running_or_fail(project, on_save="no", discard_ok=None):
    """Open `project` in the running FL via its Open dialog; one retry after clearing stray popups. Never launches
    the file (that can start a second FL): raises instead, so the caller reports it rather than spawning FL.
    on_save: how to answer FL's 'save changes?' ('no' after the file was edited on disk, else 'yes'). 'No' is only
    given while FL's main window shows one of `discard_ok` (default: `project` itself) - never for another project."""
    discard_ok = discard_ok or [project]
    _OPEN_REFUSAL["why"] = None
    stuck = _fl_blocking_popup()                                  # a file dialog already up (a plugin's Save As, the
    if stuck and (stuck.get("file_dialog") or stuck.get("kind") in ("save_as", "open_dialog")):   # user's own Open):
        raise RuntimeError(f"FL is showing the file dialog {_popup_words(stuck)}, so it can't open another project; "
                           "close that dialog in FL (Cancel, or finish it), then try again. fl-headless doesn't type "
                           "into a dialog it didn't open")       # Ctrl+O does nothing then, and it isn't ours to answer
    if _OPEN_PROOF.get("path") and _ud_key(_OPEN_PROOF["path"]) != _ud_key(project):
        _OPEN_PROOF["path"] = None                                # FL is about to show another file
    if _open_in_running_fl(project, on_save=on_save, discard_ok=discard_ok):
        return True
    if _OPEN_REFUSAL["why"]:
        raise RuntimeError(_OPEN_REFUSAL["why"])
    # No Open dialog came: FL may be busy loading (PC 2026-10-23), and then the Ctrl+O waits in its queue and pops up
    # once it's done. Wait that out first, so that dialog is found and closed below - never a second Ctrl+O on top
    _wait_load_out(project)
    _answer_save_prompts(on_save, discard_ok)
    for d in fl_dialogs():                                       # a leftover popup can swallow Ctrl+O
        if d["kind"] not in ("save_changes", "save_as"):   # never dismiss a save question
            try:
                fl_dialog("click", "escape", d["hwnd"])
            except Exception:
                pass
    time.sleep(0.8)
    if _open_in_running_fl(project, on_save=on_save, discard_ok=discard_ok):
        return True
    if _OPEN_REFUSAL["why"]:
        raise RuntimeError(_OPEN_REFUSAL["why"])
    pops = [d["title"] for d in fl_dialogs()]
    stuck = _fl_blocking_popup()
    if stuck and stuck.get("title") not in pops:
        pops.append(stuck.get("title") or stuck.get("class") or "an untitled popup")
    raise RuntimeError("couldn't drive FL's Open dialog" + (f" (FL is showing: {pops}; answer with fl_dialog)" if pops
                       else f" ({_fg_note()})") +
                       ". Not launching the file, since that can start a second FL. Open it in FL with Ctrl+O, or retry.")



def _desktop_locked():
    """True when Windows' input desktop isn't the user's (the PC is locked, or the secure desktop of a UAC prompt is
    up): keystrokes and window focus can't reach FL then, so its dialogs (Open, Export) can't be driven, while the
    bridge, file edits and live changes still work. None when it can't be told (not Windows)."""
    if not IS_WINDOWS:
        return None
    try:
        import ctypes
        u = ctypes.windll.user32
        h = u.OpenInputDesktop(0, False, 0x0001)                      # DESKTOP_READOBJECTS
        if not h:
            return True                                               # access denied: Winlogon's desktop is active
        try:
            buf = ctypes.create_unicode_buffer(256); need = ctypes.c_ulong(0)
            if u.GetUserObjectInformationW(h, 2, buf, ctypes.sizeof(buf), ctypes.byref(need)):   # UOI_NAME
                return buf.value.lower() != "default"
            return None
        finally:
            u.CloseDesktop(h)
    except Exception:
        return None


LOCKED_NOTE = ("Windows is locked (or a secure prompt is up), so FL's dialogs can't be driven until someone unlocks "
               "the PC; edits, the bridge and live changes still work")

def _fl_load_seen(wait_s, ignore_after_s=2.5):
    """True once FL shows it (re)loaded a project, False if it plainly didn't. While loading, FL's UI thread is
    busy and the bridge stops answering; once loaded, FL starts playback. If the bridge keeps answering and nothing
    plays for ignore_after_s, FL ignored the request."""
    t0 = time.time(); busy = False
    wait_s = _scaled(wait_s); ignore_after_s = _scaled(ignore_after_s)   # a slow PC starts / loads later
    while time.time() - t0 < wait_s:
        try:
            if _bridge_state_light(timeout=1.0).get("playing"):
                return True
        except Exception:
            busy = True                                           # loading
        if not busy and time.time() - t0 > ignore_after_s:
            return False
        time.sleep(0.1)
    return busy


def _mark_changed():
    """Make FL treat the open project as changed (a master-fader nudge and back), so reopening it really reloads it
    after a 'save changes?' that is answered No - much faster than going through an empty project."""
    # By the fader's 0..1 position (script v7) and back to exactly that position. An older script has no 'volume' in
    # its reply and sets volume_db by a search over FL's read-back, which on FL 2026 lags the set and runs the fader to
    # an end (PC 2026-10-23: tracks at +5.59 dB / silent): no nudge then (the caller takes the slower path).
    for t in range(1, 20):                                       # the master's fader doesn't read back; inserts do
        try:
            r = BRIDGE.call("mixer_set", track=t, timeout=2.0)
            if not isinstance(r, dict) or "volume" not in r:
                return False                                      # older script: never nudge with its search
            v = _numf(r.get("volume"))
            if v is None or v <= 0.002:
                continue
            BRIDGE.call("mixer_set", track=t, volume=v - 0.002, timeout=2.0)
            BRIDGE.call("mixer_set", track=t, volume=v, timeout=2.0)
            return True
        except Exception:
            return False
    return False


_PROBE_RELOAD = False


# fl_* tools that also work off Windows (they read files / caches, or report status)
CROSS_PLATFORM = {"fl_help", "fl_manual_page", "fl_status", "fl_timings", "fl_job", "fl_find_presets", "fl_doctor",
                  "fl_review", "fl_sound_catalog",
                  # offline-capable modes (files / audio / measurements in, no FL): the FL parts fail on their own
                  "fl_vocal_comp", "fl_vocal_clean", "fl_vocal_double", "fl_vocal_chain", "fl_vocal_balance",
                  "audio_to_midi", "capture_from_midi_file", "flp_score", "flp_clashes", "fl_reference_match",
                  "fl_verify_intent", "fl_platform_preview", "fl_masking", "fl_mix_engineer"}


def _windows_only(name):
    """True when `name` needs Windows (it drives FL, its window, MIDI, registry or Recycle Bin) and this isn't it."""
    if IS_WINDOWS or name in CROSS_PLATFORM:
        return False
    return name.startswith("fl_") or name in ("files_recycle",)


def _flh_call(tool, args=None):
    L = _live(); T = L["TOOLS"]
    if tool == "flh_call":                                        # flh_run guards its own nesting
        raise ValueError("flh_call can't call itself: call the tool directly")
    if tool not in T:
        raise ValueError((L.get("_unknown_tool") or _unknown_tool)(tool, T))
    if _windows_only(tool):
        raise RuntimeError(f"{tool}: {WINDOWS_ONLY_NOTE}")
    if isinstance(args, str) and args.strip()[:1] == "{":
        args = json.loads(args)                                   # args sent as a JSON string
    return T[tool][0](**(L.get("_check_args") or _check_args)(tool, args or {}, T[tool]))


_PREV_RE = re.compile(r"^\$prev\.([\w.\-\[\]]+)$")


_PREV_ALIASES = {"output": ("output", "path", "project", "out", "saved"), "path": ("path", "output", "project"),
                 "project": ("project", "output", "path")}


def _prev_lookup(prev, path):
    """'rendered[0]' / 'job' / 'result.output' from the previous step's result. output / path / project stand in
    for each other (writers name the written file differently: flp_set_tempo 'path', flh_new_song 'project')."""
    cur = prev
    for part in re.findall(r"[^.\[\]]+|\[\d+\]", path):
        if part.startswith("["):
            cur = cur[int(part[1:-1])]
        elif isinstance(cur, dict):
            if part not in cur and part in _PREV_ALIASES:
                part = next((a for a in _PREV_ALIASES[part] if a in cur), part)
            cur = cur[part]
        elif isinstance(cur, list) and part.lstrip("-").isdigit():
            cur = cur[int(part)]
        else:
            raise KeyError(part)
    return cur


def _subst_prev(v, prev):
    if isinstance(v, str):
        m = _PREV_RE.match(v.strip())
        if m:
            if prev is None:
                raise ValueError(f"'{v}': there is no previous result")
            try:
                return _prev_lookup(prev, m.group(1))
            except (KeyError, IndexError, TypeError, ValueError):
                raise ValueError(f"'{v}': the previous result has no {m.group(1)}; it has: "
                                 f"{', '.join(map(str, sorted(prev)[:25])) if isinstance(prev, dict) else type(prev).__name__}"
                                 " (use '$prev.<one of these>')")
        return v
    if isinstance(v, dict):
        return {k: _subst_prev(x, prev) for k, x in v.items()}
    if isinstance(v, list):
        return [_subst_prev(x, prev) for x in v]
    return v


def _compact_result(r):
    """A step's result without timing noise (took_s / steps_s); errors and everything else kept."""
    if isinstance(r, dict):
        c = {k: v for k, v in r.items() if k not in ("took_s", "steps_s", "_image_png")}
        if "_image_png" in r:
            c["image"] = "not returned inside flh_run: call fl_snapshot directly to see it"
        return c
    return r


# Steps flh_run may run side by side: they only read files (no FL, no writes). Conditional readers (flp_playlist
# list, flp_project_info without output...) are checked with _read_only_call.
PARALLEL_SAFE = {"flp_info", "flp_list", "flp_notes", "flp_patterns", "flp_tempo_map", "flp_analyze_music", "flp_diff",
                 "flp_score", "flp_clashes", "fl_doctor", "flp_health", "flp_search", "flp_versions", "flh_tools",
                 "flh_genres", "audio_info", "audio_analyze", "audio_detect", "audio_profiles", "files_list",
                 "files_hash", "fl_help", "fl_manual_page", "flp_sounds", "flp_instrument_sounds", "fl_find_presets",
                 "flh_handbook_search", "flh_handbook_card", "fl_timings", "flh_recipe_list", "flh_usage"}
_FL_LOCK = threading.RLock()                                     # one process-wide lock for everything driving FL


def _fl_acquire():
    """Take the FL lock for a foreground step: at once when free (or already ours); a background check of the last
    edit is asked to step aside; a background JOB holding FL means 'busy' after 2 s (renders take minutes)."""
    if _FL_LOCK.acquire(blocking=False):
        return True
    what = str(_FL_HOLDER.get("what") or "")
    job = what.startswith("job")
    _VERIFY_STOP.set()
    try:                                                          # a new song's level balance: worth waiting for
        return _FL_LOCK.acquire(timeout=2.0 if job else (90.0 if what.startswith("balancing") else FL_LOCK_WAIT_S)
                                * (1.0 if job else _speed_factor()))
    finally:
        _VERIFY_STOP.clear()                                      # refused or not, nobody is waiting any more (a
                                                                  # check can't run while we hold FL anyway)


# Tools that only look at FL (or answer its popups) and so never wait for the FL lock: while a job holds FL they run
# beside it - Claude must be able to see FL and answer a popup a render or finalize is stuck on. Values: a test of
# the call's arguments (False = this call changes FL, so it takes the lock like any other).
FL_LOCK_FREE = {"fl_dialog": None, "fl_snapshot": None, "fl_context": None, "fl_where": None, "fl_ping": None,
                "fl_ports": None, "fl_settings": None, "fl_settings_summary": None, "fl_settings_diff": None,
                "fl_state": None, "fl_watchdog": lambda kw: not kw.get("heal")}


def _lock_free(name, kw):
    if name not in FL_LOCK_FREE:
        return False
    test = FL_LOCK_FREE[name]
    try:
        return True if test is None else bool(test(kw))
    except Exception:
        return False


# live tools that act on the open project's channels, mixer, patterns or plugins: they wait while FL is still loading,
# and one that targets what only a queued edit makes gets the queue in first (PC 2026-10-26: fl_channel_set right
# after an edit hit FL mid-reload: 'no channel 8')
LIVE_ORDERED_TOOLS = {"fl_state", "fl_channel_set", "fl_mixer_set", "fl_playlist_track_set", "fl_pattern_set",
                      "fl_pattern_new", "fl_steps", "fl_batch", "fl_organize", "fl_mixer_info", "fl_plugin_params",
                      "fl_plugin_set", "fl_plugin_set_value", "fl_plugin_preset", "fl_plugin_presets", "fl_plugin_info",
                      "fl_plugin_preset_find", "fl_plugin_probe", "fl_plugin_map_learn", "fl_plugin_set_named"}


_LIVE_MISSING_RE = re.compile(r"(?i)\bno (channel|mixer track|track|insert|pattern|plugin|effect)\b")


def _live_ready(name):
    """Before a live tool: wait (bounded) while FL is still loading a project. Queued edits are NOT forced in (a
    build's edits keep sharing one reload; FL's own save keeps the live change when they go in) - unless the tool
    targets something only a queued edit makes (then: in once, and the tool again)."""
    if getattr(_SYNC_LOCAL, "busy", False):
        return
    try:                                                          # only FL's own loading signs: its CPU use is
        if IS_WINDOWS and _fl_loading_now():                      # no sign (a loaded INSTRUMENT keeps FL busy:
            proj = _open_project_guess()[0]                       # PC 2026-10-26 every live call waited 14 s)
            cost = (_load_cost_guess(proj)[0] or 0.0) if proj else 0.0
            t0 = time.time(); limit = _scaled(max(OPEN_SWITCH_IDLE_S, 1.5 * cost + 10.0))
            while time.time() - t0 < limit and _fl_loading_now():
                time.sleep(0.25)
    except Exception:                                             # noqa: BLE001
        pass


def _fl_loading_now():
    """FL is loading a project right now: 'Opening: ...' in its title, or its script's heartbeat stopped."""
    try:
        return bool(_fl_loading_title() or _fl_ui_busy())
    except Exception:                                             # noqa: BLE001
        return False


def _fl_locked(name, fn):
    """TOOLS wrapper for a tool that drives FL: holds the FL lock while it runs (re-entrant). A background job
    holding FL refuses the call at once with 'busy'; a background check of the last edit steps aside. Read-only /
    popup tools (FL_LOCK_FREE) never wait: they run beside whoever holds FL."""
    if name in LIVE_CHANGE_TOOLS:                                 # its change is FL's, not the file's: logged
        fn = _live_noting(name, fn)

    def run(*a, **kw):
        if _lock_free(name, kw):
            if not _FL_LOCK.acquire(blocking=False):
                return fn(*a, **kw)                               # FL is held (a job): look / answer anyway
            try:
                return fn(*a, **kw)
            finally:
                _FL_LOCK.release()
        if _PLAYS_RE.search(name):
            _AUTOPLAY["gen"] += 1                                 # starts playback on purpose: no autoplay stop
        if not _fl_acquire():
            raise RuntimeError(f"FL is busy ({_fl_busy_with()}), so {name} did nothing; try again when that's done")
        try:
            if name in LIVE_ORDERED_TOOLS:
                _live_ready(name)
                try:
                    return fn(*a, **kw)
                except (ValueError, RuntimeError) as e:            # it targets what a queued edit makes: the
                    if not (_LIVE_MISSING_RE.search(str(e)) and _pending_all()):   # queue goes in, once
                        raise
                    _sync_before(name)
                    _live_ready(name)
                    return fn(*a, **kw)
            return fn(*a, **kw)
        finally:
            _FL_LOCK.release()
    run.__wrapped__ = getattr(fn, "__wrapped__", fn)
    for attr in ("__lazy__",):
        if hasattr(fn, attr):
            setattr(run, attr, getattr(fn, attr))
    run.__fl_locked__ = True
    return run


def _schema_arrays_fix(sch):
    """Every 'array' in a tool schema gets an 'items' (strict JSON-schema validators in some clients reject arrays
    without one); {} = any item. In place."""
    if isinstance(sch, dict):
        t = sch.get("type")
        if (t == "array" or (isinstance(t, list) and "array" in t)) and "items" not in sch:
            sch["items"] = {}
        for v in list(sch.values()):
            _schema_arrays_fix(v)
    elif isinstance(sch, list):
        for v in sch:
            _schema_arrays_fix(v)
    return sch


def _install_fl_lock(ns):
    """Wrap every FL-driving tool (core and extensions) with the FL lock - whoever calls it: the client, flh_run,
    flh_call or a recipe."""
    T = ns["TOOLS"]
    for name in list(T):
        ent = T[name]
        try:
            _schema_arrays_fix(ent[2])
        except Exception:
            pass
        if _touches_fl(name) and not getattr(ent[0], "__fl_locked__", False):
            T[name] = (_fl_locked(name, ent[0]),) + tuple(ent[1:])


# Tools that READ the project to build an edit of it (the composer layer): with the project open in FL they must
# read what FL holds - FL saves first. PC 2026-10-23: flp_compose 'read the file on disk: FL is busy (checking that
# FL holds the last edit), so it wasn't asked to save first' - its edit then went in by a reload that dropped what had
# been changed in FL. Now the call waits for FL (a background check steps aside), FL saves, then the tool reads; when
# FL can't save, nothing is read or changed. FRESH_READ_ONLY tools (and dry runs) still read the file then, with the
# tool's own note.
FRESH_READ_TOOLS = {"flp_compose", "flp_arrange_song", "flp_adjust", "flp_build_rise", "flp_musicality"}
FRESH_READ_ONLY = {"flp_musicality"}
_FRESH_TL = threading.local()       # .on: inside a fresh-read tool on this thread; .saved: (ud key, file sig) FL wrote


def _fresh_read_first(name, project):
    """Inside the FL lock: make the file hold what FL has (FL saves when it has unsaved changes). None when the file
    can be read, else why not (nothing may be read or changed)."""
    st = _open_state(project)
    if st == "unknown":                                           # FL's title can't tell: one save proves it (and
        try:                                                      # puts FL's work into whichever file it holds)
            _prove_open(project)
        except Exception as e:                                    # noqa: BLE001
            return f"{e}"
        st = _open_state(project)
    if st != "open" or _stale_get(project):                       # FL holds another file - or an OLDER copy of this
        return None                                               # one: the file is what counts
    flag = _fl_changed_flag()
    if flag == 0:                                                 # FL has nothing unsaved: the file is FL's state
        return None
    if flag is None and not _ping_ok():                           # no bridge at all: FL can't be asked (the edit's
        return None                                               # own path handles FL), the tool says it read the file
    older = _fl_copy_older(project)
    if older:
        return (older + ", and FL has unsaved changes (or can't say), so " + name + " did nothing: an edit of the "
                "file would be reloaded over FL's changes. fl_open(project, save_current=false) loads the file (FL's "
                "changes dropped); fl_save() keeps FL's version instead")
    mutes = _preview_mutes_on(project)
    if mutes:
        return mutes.replace("not saved:", f"{name} did nothing:", 1)
    cost = _load_cost_ref(project) or 0.0
    wait = max(8.0, 0.5 * cost)                                   # a heavy project saves slower
    if _save_in_fl_and_wait(project, wait_s=wait):
        try:
            _FRESH_TL.saved = (_ud_key(project), tuple(_file_sig(project)))
        except OSError:
            _FRESH_TL.saved = None
        return None
    return (f"FL didn't save {os.path.basename(project)} within {wait:.0f} s, so {name} did nothing: an edit built "
            "from the file on disk would miss what was changed in FL since its last save (and the reload after it "
            "would drop that). Check FL for a popup (fl_dialog), then try again")


def _fresh_read_tool(name, fn):
    """TOOLS wrapper for FRESH_READ_TOOLS: the project open in FL -> wait for FL (the FL lock; a background check
    steps aside), FL saves, then the tool reads and edits - all inside the lock, so no other FL step changes FL in
    between. FL busy with a job / can't save -> nothing done (read-only calls / dry runs: run on the file as before)."""
    def run(*a, **kw):
        proj = kw.get("project")
        if getattr(_FRESH_TL, "on", False) or not isinstance(proj, str) or not os.path.isfile(proj):
            return fn(*a, **kw)
        try:
            here = fl_running() and _open_state(proj) != "not_open"
        except Exception:                                         # noqa: BLE001
            here = False
        if not here:
            return fn(*a, **kw)
        strict = name not in FRESH_READ_ONLY and kw.get("dry_run") is not True
        if not (_fl_acquire() if strict else _FL_LOCK.acquire(blocking=False)):
            if not strict:                                        # a look / dry run never waits: it reads the file
                return fn(*a, **kw)                               # (the tool's own read_note says so)
            raise RuntimeError(f"FL is busy ({_fl_busy_with()}) and has {os.path.basename(proj)} open, so {name} did "
                               "nothing: an edit built from the file on disk would miss what was changed in FL since "
                               "its last save (and the reload after it would drop that). Try again when FL is free")
        _FRESH_TL.on = True; _FRESH_TL.saved = None
        try:
            why = _fresh_read_first(name, proj) if strict else None
            if why:
                raise RuntimeError(why)
            return fn(*a, **kw)
        finally:
            _FRESH_TL.on = False; _FRESH_TL.saved = None
            _FL_LOCK.release()
    run.__wrapped__ = getattr(fn, "__wrapped__", fn)
    for attr in ("__lazy__", "__fl_locked__"):
        if hasattr(fn, attr):
            setattr(run, attr, getattr(fn, attr))
    run.__fresh_read__ = True
    return run


def _install_fresh_reads(ns):
    T = ns["TOOLS"]
    for name in FRESH_READ_TOOLS:
        if name in T and not getattr(T[name][0], "__fresh_read__", False):
            T[name] = (_fresh_read_tool(name, T[name][0]),) + tuple(T[name][1:])


def _parallel_ok(name, args):
    return name in PARALLEL_SAFE or (name in ("flp_playlist", "flp_project_info", "flp_audio_clip_settings")
                                     and _read_only_call(name, args or {}))


def _touches_fl(name):
    return (name.startswith("fl_") and name not in CROSS_PLATFORM) or name in ("flh_sync", "files_recycle")


def _has_prev(v):
    if isinstance(v, str):
        return bool(_PREV_RE.match(v.strip()))
    if isinstance(v, dict):
        return any(_has_prev(x) for x in v.values())
    if isinstance(v, list):
        return any(_has_prev(x) for x in v)
    return False


def _run_step(st, i):
    """One flh_run step in the shape the runner uses ({"tool", "args", "parallel"?}). Also accepted: the MCP shape
    {"name", "arguments"} and args sent as a JSON string (as flh_call takes them)."""
    usage = 'each step is {"tool": "<tool name>", "args": {...}} (or {"name": ..., "arguments": ...})'
    if isinstance(st, str) and st.strip()[:1] == "{":
        try:
            st = json.loads(st)
        except ValueError:
            pass
    if not isinstance(st, dict):
        raise ValueError(f"step {i + 1}: {usage}; got {json.dumps(st, default=str)[:80]}")
    st = dict(st)
    tool = st.pop("tool", None) or st.pop("name", None)
    args = st.pop("args", None) if "args" in st else st.pop("arguments", None)
    st.pop("name", None); st.pop("arguments", None)
    if not isinstance(tool, str) or not tool.strip():
        raise ValueError(f"step {i + 1}: no tool named; {usage}")
    if isinstance(args, str):
        try:
            args = json.loads(args) if args.strip() else {}
        except ValueError as e:
            raise ValueError(f"step {i + 1} ({tool}): args is a string that isn't JSON ({e}); {usage}")
    if args is not None and not isinstance(args, dict):
        raise ValueError(f"step {i + 1} ({tool}): args must be an object {{name: value}}; {usage}")
    st.update(tool=tool.strip(), args=args or {})
    return st


def _run_groups(steps, parallel):
    """[[step index, ...], ...]: consecutive steps that may run at once share a group. parallel: 'auto' groups
    read-only steps without $prev; true also honours "parallel": true on any step (writers excepted)."""
    groups, cur = [], []
    for i, st in enumerate(steps):
        name = st.get("tool"); args = st.get("args") or {}
        safe = _parallel_ok(name, args) or (_touches_fl(name) and not str(name).startswith("flp_"))
        want = (st.get("parallel") is True and parallel is not False and safe) or \
               (parallel in ("auto", True) and _parallel_ok(name, args) and not _has_prev(args) and
                st.get("parallel") is not False)
        if want:
            cur.append(i)
            continue
        if cur:
            groups.append(cur); cur = []
        groups.append([i])
    if cur:
        groups.append(cur)
    return groups


def flh_run(steps, stop_on_error=True, sync=False, parallel="auto", dry_run=False):
    """Several tool calls in one round trip: steps [{"tool": name, "args": {...}, "parallel": bool?}, ...].
    An argument "$prev.<key>" (e.g. "$prev.output", "$prev.rendered[0]") takes that value from the previous step's
    result (inside a parallel group: the result before the group). parallel: 'auto' (default) runs consecutive
    read-only file steps (readers of .flp/.mid/audio, no $prev) at the same time; true also runs steps marked
    "parallel": true together (FL-touching ones still one at a time); false = strictly in order. Writers always run
    alone, in order. dry_run: the plan with estimated seconds, nothing runs. stop_on_error: stop at the first failure
    (default) or carry on. Results are compacted (no timings). sync: at the end, apply edits queued in lazy mode."""
    if not isinstance(steps, list) or not steps:
        raise ValueError('give steps: [{"tool": "...", "args": {...}}, ...]')
    L = _live(); T = L["TOOLS"]
    steps = [_run_step(st, i) for i, st in enumerate(steps)]
    if isinstance(parallel, str) and parallel.lower() in ("true", "false"):
        parallel = parallel.lower() == "true"
    groups = _run_groups(steps, parallel)
    if dry_run:
        plan, total = [], 0.0
        for gi, g in enumerate(groups):
            ests = []
            for i in g:
                st = steps[i]; name = st.get("tool"); row = {"step": i + 1, "tool": name}
                if len(g) > 1:
                    row["parallel_group"] = gi + 1
                if name not in T or name in ("flh_run", "flh_call"):
                    row["error"] = f"no tool '{name}'" if name not in T else f"{name} can't run inside flh_run"
                else:
                    try:
                        e = L["estimate"](name, st.get("args") or {})
                        row["estimate_s"] = e["estimate_s"]; row["basis"] = e["basis"]; ests.append(e["estimate_s"])
                    except Exception as ex:                       # noqa: BLE001
                        row["estimate_s"] = None; row["basis"] = f"no estimate ({type(ex).__name__})"
                    if _has_prev(st.get("args") or {}):
                        row["uses_prev"] = True
                    if not _parallel_ok(name, st.get("args") or {}) and str(name).startswith("flp_"):
                        row["writes"] = True
                plan.append(row)
            total += (max(ests) if len(g) > 1 else sum(ests)) if ests else 0.0
        return {"dry_run": True, "steps": len(steps), "groups": len(groups),
                "parallel_groups": sum(1 for g in groups if len(g) > 1), "estimate_s": round(total, 1), "plan": plan}

    def one(i, prev):
        st = steps[i]; name = st.get("tool"); t0 = time.time()
        try:
            if name in ("flh_run", "flh_call"):
                raise ValueError(f"{name} can't run inside flh_run")
            if name not in T:
                raise ValueError((L.get("_unknown_tool") or _unknown_tool)(name, T))
            if L["_windows_only"](name):
                raise RuntimeError(f"{name}: {L['WINDOWS_ONLY_NOTE']}")
            args = _subst_prev(dict(st.get("args") or {}), prev)
            args = (L.get("_check_args") or _check_args)(name, args, T[name])
            fn = T[name][0]
            if _touches_fl(name) and not getattr(fn, "__fl_locked__", False):
                if not _fl_acquire():                             # never wait on a job: same 2 s 'busy' as direct
                    raise RuntimeError(f"FL is busy ({_fl_busy_with()}), so {name} did nothing; try again when "
                                       "that's done")
                try:
                    res = fn(**args)
                finally:
                    _FL_LOCK.release()
            else:
                res = fn(**args)                                  # FL tools take the FL lock themselves (busy = 2 s)
            try:
                L["_timing_note"](name, round(time.time() - t0, 2), res)
            except Exception:
                pass
            try:
                img = res.pop("_image_png", None) if isinstance(res, dict) else None
                res = (L.get("_post_result") or _post_result)(name, args, res, round(time.time() - t0, 2))
                if img and isinstance(res, dict):
                    res["_image_png"] = img
            except Exception:
                pass
            return i, True, res, round(time.time() - t0, 3)
        except Exception as e:                                   # noqa: BLE001
            try:
                (L.get("_note_error_hook") or _note_error_hook)(name, st.get("args") or {}, e,
                                                                 took=round(time.time() - t0, 2))
            except Exception:
                pass
            L["_note_tool_error"](f"flh_run:{name}", e)
            return i, False, f"{type(e).__name__}: {e}", round(time.time() - t0, 3)

    out = []; prev = None; ok = True; T0 = time.time(); busy = 0.0; ran = 0; stopped = False
    for gi, g in enumerate(groups):
        if len(g) == 1:
            got = [one(g[0], prev)]
        else:
            import concurrent.futures as cf
            with cf.ThreadPoolExecutor(max_workers=min(4, len(g))) as pool:
                got = sorted(pool.map(lambda i: one(i, prev), g))
        for i, good, res, took in got:
            busy += took; ran += 1
            row = {"step": i + 1, "tool": steps[i].get("tool")}
            if len(g) > 1:
                row["parallel_group"] = gi + 1
            if good:
                row["result"] = _compact_result(res); prev = res
            else:
                ok = False; row["error"] = res
                if "FL is busy" in str(res):
                    row["busy"] = True                            # nothing was done: retry this step later
            out.append(row)
        if not ok and stop_on_error:
            stopped = True
            break
    r = {"ok": ok, "ran": ran, "of": len(steps), "steps": out}
    if any(len(g) > 1 for g in groups):
        r["parallel"] = {"groups": sum(1 for g in groups if len(g) > 1), "wall_s": round(time.time() - T0, 2),
                         "sum_of_steps_s": round(busy, 2)}
    if stopped and ran < len(steps):
        r["stopped"] = f"stopped at step {out[-1]['step']}; {len(steps) - ran} step(s) not run"
    if sync:
        try:
            r["synced"] = _sync_before("flh_run") or {}
        except Exception as e:                                   # noqa: BLE001
            r["ok"] = False; r["sync_error"] = str(e)
    return r


# ---- cost estimates (flh_run dry_run, eta_s) -------------------------------------------------------------------
DEFAULT_COST_S = {"read": 0.3, "write": 0.6, "live": 0.4, "audio": 2.0, "other": 1.0}
SAVE_RELOAD_S = 2.5                                               # FL save + reopen overhead besides the load itself
REALTIME_TOOLS = {"fl_listen", "fl_mix_check", "fl_review", "fl_vocal_record", "fl_capture_idea",
                  "fl_vocal_level_check", "fl_mix_engineer", "fl_masking"}


def _song_seconds(project):
    """(song seconds, song bars, beats per bar) of a project from its clips/notes and tempo map (cached parse)."""
    d = _load(project); ev = _events(d); P = _ppq(d)
    notes, tm = _song(d, ev)
    num, den = _project_meter(d, ev); bpb = num * 4.0 / den
    end = max([n[0] + n[1] for n in notes] + [struct.unpack("<I", r[0:4])[0] + struct.unpack("<I", r[8:12])[0]
                                             for _, _, r in _clips(d, ev)] + [0])
    secs, t_prev, bpm = 0.0, 0, tm[0][1] if tm else 120.0
    for t, b in tm[1:] if tm else []:
        if t >= end:
            break
        secs += (t - t_prev) / P * 60.0 / bpm; t_prev, bpm = t, b
    secs += max(0, end - t_prev) / P * 60.0 / bpm
    return secs, end / (P * bpb) if end else 0.0, bpb


def estimate(tool, args=None):
    """Rough seconds a tool call will take on this PC: {"estimate_s", "basis"}. Uses this session's measured
    timings (fl_timings), the project's FL load cost, the song's length (real-time tools play it) and the learned
    render speed. A guess, said as one."""
    args = dict(args or {}); L = _live(); basis = []
    proj = args.get("project") or args.get("path") or args.get("template")
    t = (L.get("_TIMINGS") or {}).get(tool)
    if t and t.get("calls"):
        base = t["total_s"] / t["calls"]; basis.append(f"measured avg of {t['calls']} call(s) this session")
    else:
        kind = ("read" if _parallel_ok(tool, args) else "write" if tool.startswith("flp_") else
                "audio" if tool.startswith("audio_") else "live" if tool.startswith("fl_") else "other")
        base = DEFAULT_COST_S[kind]; basis.append(f"default for a {kind} tool")
    est = base
    song = None
    if isinstance(proj, str) and proj.lower().endswith(".flp") and os.path.isfile(proj):
        try:
            song = _song_seconds(proj)
        except Exception:
            song = None
    bar_s = (song[0] / song[1]) if song and song[1] else 2.0
    if tool in REALTIME_TOOLS and not (t and t.get("calls")):
        if tool == "fl_listen":
            if args.get("seconds"):
                play = float(args["seconds"])
            elif args.get("end_bar") is not None:
                play = (float(args["end_bar"]) - float(args.get("start_bar") or 1)) * bar_s
            else:
                play = song[0] if song else 60.0
            est = play + 4; basis.append("plays in real time")
        elif tool in ("fl_review",) and not args.get("audio"):
            est = (song[0] if song else 180.0) + 8; basis.append("live review plays the song")
        elif tool in ("fl_mix_check", "fl_mix_engineer") and not args.get("stems") and not args.get("measurements"):
            n = len(args.get("tracks") or []) or 8; w = float(args.get("window_s") or 8)
            est = (1 + n) * (w + 4); basis.append(f"{1 + n} live passes of ~{w:g} s")
        elif tool == "fl_vocal_record":
            bars = float(args.get("end_bar", 9)) - float(args.get("start_bar", 1)) + float(args.get("pre_roll_bars", 1))
            est = int(args.get("takes") or 1) * bars * bar_s + 5; basis.append("records in real time")
        elif tool == "fl_capture_idea":
            est = float(args.get("seconds") or (float(args.get("bars") or 4) + float(args.get("count_in_bars") or 1)) * bar_s) + 4
            basis.append("records in real time")
        elif tool == "fl_vocal_level_check":
            est = float(args.get("seconds") or 5) + 2; basis.append("listens for `seconds`")
    if tool in ("fl_render", "fl_finalize", "fl_render_stems", "fl_render_batch") and not (t and t.get("calls")):
        try:
            ratio = float((L["render_speed"]() if "render_speed" in L else {}).get("ratio") or 0.4)
        except Exception:
            ratio = 0.4
        n = len(args.get("projects") or []) or 1
        est = n * ratio * (song[0] if song else 180.0) + (5 if tool != "fl_finalize" else 10)
        basis.append(f"render speed {ratio:g} s per song second on this PC")
    if tool == "fl_open" and isinstance(proj, str):
        c = project_load_cost(proj).get("seconds")
        if c:
            est = c + 2; basis.append("this project's measured FL load time")
    elif tool.startswith("flp_") and not _parallel_ok(tool, args) and isinstance(proj, str):
        try:
            if _open_in_fl(proj):
                if _reload_mode(proj) == "lazy":
                    basis.append("queued (lazy): no reload now")
                else:
                    c = project_load_cost(proj).get("seconds") or 6.0
                    est += SAVE_RELOAD_S + c; basis.append(f"open in FL: save + reload (~{c:g} s load)")
        except Exception:
            pass
    return {"tool": tool, "estimate_s": max(0.1, round(est, 1)), "basis": "; ".join(basis)}


def fl_reload_probe(project):
    """Diagnostics: does reopening the open project make FL re-read it? Renames mixer track 9 live, reopens
    directly, and watches the bridge (busy?), playback and whether the rename survived. The track's name is put back
    if FL didn't re-read the file."""
    got = _proven_open(project, ttl=OPEN_PROOF_TTL_S) or _prove_open(project)
    if got is not True and not (isinstance(got, str) and got != "never_saved" and _ud_key(got) == _ud_key(project)):
        raise RuntimeError(f"FL's save didn't land in {os.path.basename(project)}, so it isn't proven to be the "
                           "project FL has open; the probe only runs on that one (it answers 'No' to 'save changes?')")
    t = 9
    orig = BRIDGE.call("mixer_set", track=t).get("name")
    BRIDGE.call("mixer_set", track=t, name="flh-probe")
    log = []
    try:
        marked = _mark_changed(); t0 = time.time()
        _open_running_or_fail(project, on_save="no"); opened = round(time.time() - t0, 1)
        t1 = time.time()
        while time.time() - t1 < 15:
            try:
                st = _bridge_state_light(timeout=1.0)
                nm = BRIDGE.call("mixer_set", track=t, timeout=1.0).get("name")
                log.append((round(time.time() - t1, 1), "ok", bool(st.get("playing")), nm))
            except Exception as e:
                log.append((round(time.time() - t1, 1), "busy", str(e)[:40]))
            time.sleep(0.5)
        try:
            BRIDGE.call("transport", action="stop")
        except Exception:
            pass
    finally:
        try:
            if BRIDGE.call("mixer_set", track=t, timeout=2.0).get("name") == "flh-probe":
                BRIDGE.call("mixer_set", track=t, name=orig or "", timeout=2.0)
        except Exception:
            pass
    return {"marked": marked, "open_s": opened, "log": log}


RELOAD_TAG = " ~flh"                   # a mixer track name carrying this was tagged live: gone = FL re-read the file
_TAG_RE = re.compile(r"(?: ~flh[0-9a-f]{0,8})+$")   # a reload tag at the end of a name (one left behind is stripped)
_TAG_NOW = {"track": None, "name": None, "leftover": None}   # the tag of the reload under way (unique per reload)


def _tag_track():
    """Tag a mixer track's name live (FL then counts the project as changed). Returns (track, original name).
    Every reload gets its own tag (' ~flh' + 4 hex), compared exactly: a tag an earlier reload left in the name (its
    put-back timed out and FL saved it into the file) is stripped first, so it can't look like this reload's tag and
    the original name comes back clean.
    The tag is read back: a name FL didn't take as sent (cut to a length, trimmed, refused) would look 'gone' at once
    and 'prove' a reload that never happened (PC 2026-10-23: 'merged edits in FL now (one reload, 1.2 s)' on a song
    that loads in 10-60 s). Then a short name is tried; still not readable -> (None, None): the slower route that
    loads an empty project first is used, and its load is checked."""
    _TAG_NOW.update(track=None, name=None, leftover=None)
    for t in range(1, 10):
        try:
            nm = BRIDGE.call("mixer_set", track=t, timeout=2.0).get("name")
        except Exception:
            return None, None
        if nm is None:
            continue
        nm = str(nm); base = _TAG_RE.sub("", nm)
        # PC-VERIFY: FL takes the ' ~flh' + 4 hex tag as sent (or the short 't<n> ~flh....' one) and a reload clears
        # it (checklists/core.md 'Release bug hunt: live layer' 6)
        tag = RELOAD_TAG + os.urandom(2).hex()
        while f"{base}{tag}" == nm:                               # never the name FL (or the file) has already
            tag = RELOAD_TAG + os.urandom(2).hex()
        for name in (f"{base}{tag}", f"t{t}{tag}"):
            try:
                BRIDGE.call("mixer_set", track=t, name=name, timeout=2.0)
                back = (BRIDGE.call("mixer_set", track=t, timeout=2.0) or {}).get("name")
            except Exception:
                back = None
            if back is not None and str(back) == name:
                _TAG_NOW.update(track=t, name=name, leftover=nm if base != nm else None)
                return t, base
        try:                                                      # FL won't hold a tag on this track: put the name
            BRIDGE.call("mixer_set", track=t, name=base, timeout=2.0)   # back (a leftover tag stripped), say no tag
        except Exception:
            pass
        return None, None
    return None, None


def _tag_gone(t, wait_s, tag=None, cost=None):
    """True once this reload's tag (exactly) is gone from the track's name, i.e. FL re-read the project from disk. A
    slow PC gets its speed factor's worth longer, and once more when FL is still busy loading at the end (the bridge
    doesn't answer). With the song's load cost (s): while FL is plainly loading at the deadline, the wait goes on up
    to ~2x that cost (PC 2026-10-24: a 29 s song's reopen was judged 'no reload' after 6 s mid-load, then loaded a
    second time through the empty template: 108 s instead of ~35)."""
    want = tag if tag is not None else (_TAG_NOW.get("name") if _TAG_NOW.get("track") == t else None)
    t0 = time.time(); base = float(wait_s); wait_s = _scaled(base); extra = _speed_extra(base, wait_s); busy = False
    load_cap = _scaled(2.0 * float(cost) + 10.0) if cost else 0.0
    while True:
        if time.time() - t0 >= wait_s:
            if extra > 0 and busy and _fl_still_working():
                wait_s += extra; extra = 0.0
                _slow_note(f"FL is still working (slow PC): reloading took over a fast PC's {base:g} s; waited longer")
                continue
            if busy and time.time() - t0 < load_cap and _fl_load_busy(False):
                wait_s = min(load_cap, time.time() - t0 + 1.0)    # a second more, polling the tag again
                continue
            return False
        try:
            nm = (BRIDGE.call("mixer_set", track=t, timeout=1.0) or {}).get("name")
            if nm is None:                                        # a reply without the track's name proves nothing
                busy = True                                       # (FL mid-load answers oddly): keep watching
            elif (str(nm) != want) if want is not None else not _TAG_RE.search(str(nm)):
                return True
            else:
                busy = False
        except Exception:
            busy = True                                           # busy loading
        time.sleep(0.1)


def _tag_left_note(tr, orig):
    return (f"mixer track {tr} may still carry the reload tag ('{_TAG_NOW.get('name') or RELOAD_TAG}') in FL: putting "
            f"its name back ('{orig or ''}') got no answer from FL - rename it in FL's mixer (the next reload strips "
            "it too)")


def _reload_in_fl(project, discard=False, force_blank=False):
    """Make FL re-read `project` from disk without quitting. Returns per-step seconds (+ 'proof' / 'unproven').
    Fast path (FL's copy isn't known to differ - fl-headless's own edit, checked afterwards by FL's save): tag a mixer
    track name live, reopen the project directly ('save changes?' -> No), wait for the tag to vanish and FL to settle
    on the file; implausibly fast for this song -> checked by content the bridge reads. Not trusted, or FL's copy is
    known to differ from the file (with _reload_verified(), e.g. fl_open / fl_reload_from_disk of a file changed
    behind FL), or force_blank: _reload_marked() - a marker only the file has, the empty template loaded first, then
    the file, the marker read back through the bridge. Disproven -> raises, FL marked as holding an OLDER copy (no
    save over the file); can't be proven (no bridge, file unwritable) -> 'unproven', FL marked the same. What FL
    holds (_note_fl_holds) is only updated on proof.
    Refuses (raises) unless FL's main window shows exactly this project: answering 'No' for another project would
    throw away its unsaved work - unless `discard` (fl_open save_current=false, or FL reports no unsaved changes:
    then nothing is lost whichever same-name file FL holds). The tag never stays behind (removed in a finally when FL
    didn't re-read)."""
    where = _open_state(project)
    if discard and where != "not_open" and _title_is_one_of([project]):
        where = "open"
    if where != "open" and not _proven_open(project):            # proven = a bridge save just landed in this file
        raise RuntimeError(f"FL doesn't show {os.path.basename(project)} for sure right now ({where}"
                           + (f": {_open_why(project)}" if where == "unknown" else "") + "); not reloading, because "
                           "answering 'No' to 'save changes?' could throw away another project's unsaved work")
    steps = {}; t = time.time()
    prior = _load_cost_ref(project)                               # before this reload adds its own time
    verify = bool(getattr(_RELOAD_CTX, "verify", False))          # FL's copy is known to differ from the file
    dlg0 = _dialog_ids()
    # PC 2026-10-23: fl_open(<the open song>, save_current=false) after the file was rewritten on disk (note lengths
    # only) said 'reloaded ... through an empty project first, seen in FL's title' - FL still held its OLD notes, and
    # fl_finalize's 'saved FL first' then wrote them over the file (the edit was lost). Neither the live tag going, nor
    # FL's title passing through the template, nor the channel count proves which copy FL holds. A reopen of a file
    # that changed behind FL now goes FL's own route (the template LOADED first) and is proven by a marker that only
    # the file has (_reload_marked); what FL holds is recorded only on that proof
    escalate = None                                               # why the fast route wasn't trusted
    if verify or force_blank:
        escalate = ("the file changed behind FL" if verify else "FL ignored a direct reopen")
        steps["direct"] = "empty project first"
    else:
        suspectable = float(prior or 0) >= RELOAD_SUSPECT_MIN_COST_S
        pre = _fl_visible() if suspectable else None              # what FL shows now
        # a fast reopen of a song that 'should' load slowly gets a file-only marker up front, so a quick reload is
        # proven on the spot instead of loading the song again through the empty template (PC 2026-10-26: every
        # reload of a note/plugin edit was 'too fast to trust', content 'can't tell' -> +40 s each)
        fmk = forig = None
        if suspectable and FAST_RELOAD_MARKER and _ping_ok():
            try:
                with open(project, "rb") as f:
                    forig = f.read()
                fmk, _no = _reload_marker_stamp(project, forig)
                if _no:
                    steps["fast_marker"] = f"none: {_no}"[:120]
            except Exception as e:                                # noqa: BLE001
                fmk = None; steps["fast_marker"] = f"none: {type(e).__name__}"
        tr, orig = _tag_track()
        gone = False
        try:
            _open_running_or_fail(project, on_save="no"); steps["open_dialog"] = round(time.time() - t, 1)
            t = time.time()
            if tr is not None and _tag_gone(tr, 6.0, cost=prior):
                gone = True
                if _TAG_NOW.get("leftover"):                      # the file had an earlier reload's tag in this
                    try:                                          # name: FL shows it clean again (saved later)
                        BRIDGE.call("mixer_set", track=tr, name=orig or "", timeout=2.0)
                        steps["tag_cleaned"] = f"mixer track {tr}: an earlier reload's tag taken out of its name"
                    except Exception:                             # noqa: BLE001
                        steps["tag_left"] = _tag_left_note(tr, orig)
                settled = _load_settled(project, prior)           # the tag going only says FL STARTED loading
                steps["load"] = round(time.time() - t, 1)
                if settled is None:
                    steps["unsettled"] = True
                sus = _reload_suspect(prior, steps)
                if sus and fmk and not steps.get("unsettled"):
                    T3 = time.time()
                    seen_fast = _await_marker(project, fmk[0], fmk[1], prior)
                    steps["fast_marker"] = {True: "seen", False: "not seen (FL showed another copy)",
                                            None: "no answer"}[seen_fast]
                    if seen_fast is True:
                        steps["marker_wait"] = round(time.time() - T3, 1)
                        steps["proof"] = "marker"; sus = None
                        _marker_put_back_live(project, fmk, forig, steps)
                        fmk = None
                if sus:
                    chk, why = _reload_content_check(project, pre, skip_track=tr,
                                                     skip_more=(fmk[0],) if fmk else ())
                    steps["content_check"] = {True: "file", False: "old copy", None: "can't tell"}[chk]
                    if chk is True:
                        steps["proof"] = "content"; steps.pop("unsettled", None)
                    else:
                        escalate = ((f"FL's reload took {sus[0]:g} s for a project that loads in ~{sus[1]:g} s"
                                     if not steps.get("unsettled") else "FL didn't settle on the file's content")
                                    + f"; {why}")
            else:
                if _untag(tr, orig) is False:
                    steps["tag_left"] = _tag_left_note(tr, orig)
                tr = None
                steps["no_reload_s"] = round(time.time() - t, 1)
                escalate = "FL showed no sign of re-reading the file after a direct reopen"
        finally:
            if tr is not None and not gone:
                if _untag(tr, orig) is False:
                    steps["tag_left"] = _tag_left_note(tr, orig)
            if fmk:                                               # the up-front marker wasn't used as the proof:
                if gone and not escalate:                         # FL took the file (trusted): its name out of FL too
                    _marker_put_back_live(project, fmk, forig, steps, proven=False)
                else:                                             # the file as it was, before any slower route
                    _reload_marker_put_back(project, fmk, forig)
        if gone and escalate:                                     # the fast 'reload' isn't counted as the load
            steps["fast_load"] = steps.pop("load", None); steps.pop("unsettled", None)
    if escalate:
        try:
            _reload_marked(project, prior, steps, escalate)       # raises when disproven (FL marked stale)
        except Exception as e:
            left_pop = _sweep_leftover_popups(dlg0, False)
            if left_pop:
                raise RuntimeError(f"{e}. Closed what the Opens left: {_popups_said(left_pop)}") from e
            raise
    elif not steps.get("unsettled"):                              # the fast route held (unsettled: no claim)
        _stale_clear(project)                                     # FL loaded the file: it holds the newest edits
        _note_fl_holds(project)
        _note_proven_open(project, "reload")
    left_pop = _sweep_leftover_popups(dlg0, False)
    if left_pop:
        steps["popups_closed"] = left_pop
    _state({"last_opened": os.path.abspath(project)})
    try:
        cost = _reload_took(steps)
        if steps.get("proof") in ("marker", "content") or (not steps.get("unproven")
                                                           and not _reload_suspect(prior, steps)):
            _note_load_cost(project, cost, "reload")              # a 'reload' far faster than this project loads
    except Exception:                                             # isn't averaged in unless it's proven
        pass
    return steps


RELOAD_SETTLE_S = 30.0            # after a reload's tag vanished: this long (or 2.5 x the load cost) for FL to finish
BLANK_LEAVE_S = 15.0              # the empty-project route: FL lets go of the song within this, or this share of
BLANK_LEAVE_COST_FRAC = 1.0       # the song's load cost (a heavy song unloads its plugins first), + BLANK_LOAD_S
_RELOAD_CTX = threading.local()   # .verify: the caller knows FL's copy differs from the file (fl_open of a changed file)


class _reload_verified:
    """with _reload_verified(): _reload_in_fl() inside must PROVE FL took the file - straight to _reload_marked (the
    empty template loaded first, then the file, a marker only the file has read back) - used where FL's copy may
    differ from the file (it changed on disk behind FL, FL holds an older copy, a reopen of the open project). A
    context, not an argument: tests and callers replace _reload_in_fl with fakes."""
    def __enter__(self):
        self.prev = getattr(_RELOAD_CTX, "verify", False); _RELOAD_CTX.verify = True
        return self

    def __exit__(self, *exc):
        _RELOAD_CTX.verify = self.prev
        return False


def _fl_visible():
    """What the bridge reads of FL's project that the file holds too: {key: value} (tempo, channel count, named
    patterns, mixer track names), or None when the bridge doesn't answer."""
    try:
        st = BRIDGE.call("state", timeout=4.0) or {}
    except Exception:                                             # noqa: BLE001
        return None
    out = {}
    n = st.get("channel_count")
    if n is None and isinstance(st.get("channels"), list):
        n = len(st["channels"])
    if n is not None:
        out["channels"] = int(n)
    if st.get("tempo") is not None:
        try:
            out["tempo"] = round(float(st["tempo"]), 2)
        except (TypeError, ValueError):
            pass
    for p in st.get("patterns") or []:
        if isinstance(p, dict) and p.get("index") is not None:
            out[f"pattern {int(p['index'])}"] = str(p.get("name") or "").strip()
    for t in st.get("mixer") or []:
        if isinstance(t, dict) and t.get("index") is not None:
            out[f"mixer {int(t['index'])}"] = str(t.get("name") or "").strip()
    return out


def _file_visible(project):
    """The same keys as _fl_visible() from the file (only named patterns / mixer tracks: FL shows defaults for the
    others), or None when it can't be read."""
    try:
        d = _load(project); ev = _events(d)
        out = {"channels": sum(1 for e in ev if e["id"] == EV_CHANNEL)}
        tempo = next((struct.unpack("<I", _payload(d, e))[0] for e in ev if e["id"] == EV_TEMPO and e["len"] == 4), None)
        if tempo:
            out["tempo"] = round(tempo / 1000.0, 2)
        for pid, p in _patterns(d, ev).items():
            if p.get("name"):
                out[f"pattern {int(pid)}"] = str(p["name"]).strip()
        for t, nm in _mixer_names(d, ev).items():
            if t > 0 and nm:
                out[f"mixer {int(t)}"] = str(nm).strip()
        return out
    except Exception:                                             # noqa: BLE001
        return None


def _visible_diff(want, pre, skip=()):
    """Keys where the file (want) and what FL showed (pre) differ - the ones a content check can judge."""
    if not want or not pre:
        return []
    return [k for k in want if k in pre and k not in skip and pre[k] is not None and pre[k] != want[k]]


def _reload_content_check(project, pre, skip_track=None, skip_more=()):
    """After a reload: does FL show the FILE where the file differs from what FL showed before (pre)? -> (True |
    False | None, why). True: FL shows the file's values there; False: still its old ones (it didn't load); None:
    can't tell (no difference the bridge can read - notes, velocities, plugin settings aren't readable - or no
    answer, or a mix)."""
    skip = tuple(f"mixer {int(t)}" for t in ((skip_track,) if skip_track is not None else ()) + tuple(skip_more))
    want = _file_visible(project)
    keys = _visible_diff(want, pre, skip)
    if not keys:
        return None, ("the file differs from FL's copy only where the bridge can't read (notes, velocities, plugin "
                      "settings)" if want and pre else "FL's or the file's content couldn't be read")
    now = _fl_visible()
    if not now:
        return None, "the bridge didn't answer after the reload"
    if all(now.get(k) == want[k] for k in keys):
        return True, f"FL shows the file's {', '.join(keys[:3])}"
    if all(now.get(k) == pre[k] for k in keys):
        return False, f"FL still shows its old {', '.join(keys[:3])} (the file has other values)"
    return None, f"FL shows neither the file's nor its old {', '.join(keys[:3])}"


def _template_loaded(blank, project, wait_s):
    """After FL was asked to open the empty template `blank`: True once FL shows it LOADED - nothing 'Opening: ...',
    FL's title (window, and the bridge's) no longer naming `project`, and the bridge answering with the template's
    channel count, twice in a row (with no readable title, only when that count tells the template from the song).
    False when FL didn't get there within wait_s; None when neither FL's title nor its bridge could be read (or the
    title left the song but the bridge never said what FL holds).
    PC 2026-10-23: 'Opening: ...' in FL's title (FL still busy with the song itself) counted as 'FL left the song';
    the song's Open then went into an FL that had never let go of its old copy.
    PC-VERIFY: state(light=1) reports the template's channel count / title only once it is in (core.md
    '_template_loaded')."""
    names = _project_names(project); bnames = _project_names(blank)
    try:
        want = _fingerprint(blank).get("channels")
    except Exception:                                             # noqa: BLE001
        want = None
    try:
        song_n = _fingerprint(project).get("channels")
    except Exception:                                             # noqa: BLE001
        song_n = None
    t0 = time.time(); hits = 0; seen = left_seen = counted = False
    while True:
        ok = False
        try:
            if not _fl_loading_title():
                mt = _main_title() or ""
                stem = (_title_stem(mt) or "").lower()
                title_ok = None if not mt else bool(stem) and (stem in bnames or stem not in names)
                seen = seen or bool(mt)
                left_seen = left_seen or title_ok is True
                st = None
                if title_ok is not False:
                    try:
                        st = _bridge_state_light(timeout=1.5) or {}
                    except Exception:                             # noqa: BLE001 - FL busy loading: not yet
                        st = None
                if st:
                    bstem = (_title_stem(st.get("title")) or "").lower()
                    if bstem and bstem in names and bstem not in bnames:
                        title_ok = False                          # the bridge's FL still names the song
                    n = st.get("channel_count")
                    if n is None and isinstance(st.get("channels"), list):
                        n = len(st["channels"])
                    seen = seen or n is not None; counted = counted or n is not None
                    count_ok = n is not None and (want is None or int(n) == int(want))
                    tells = want is not None and song_n is not None and int(want) != int(song_n)
                    ok = count_ok and (title_ok is True or (title_ok is None and tells))
        except Exception:                                         # noqa: BLE001
            ok = False
        hits = hits + 1 if ok else 0
        if hits >= 2:
            return True
        el = time.time() - t0
        if el >= wait_s or (not seen and el >= TEMPLATE_UNREADABLE_S):   # nothing readable at all: can't tell
            if left_seen and not counted:                         # FL's title left the song, its bridge never said
                return None                                       # what it holds: can't tell (the marker judges)
            return False if seen else None
        time.sleep(0.25)


TEMPLATE_UNREADABLE_S = 3.0       # neither FL's title nor the bridge's channel count readable this long: can't tell


def _reload_via_blank(project, prior):
    """FL's own route to re-read the open project: the empty template first - LOADED (_template_loaded: FL's title and
    its bridge show the template, never just 'Opening: ...') - then the file. -> (left, blank): left True / False /
    None (FL showed the template loaded / didn't within the wait: the song isn't opened then / can't be read, or no
    empty template: the song is reopened directly). What FL then holds is judged by the caller (_reload_marked).
    PC-VERIFY: fl_open(<open song>, save_current=false) after the file changed on disk shows the empty template in
    FL's title, then the song, and FL plays the file's version (checklists/core.md 'fl_open reload proof')."""
    blank = _blank_project(); left = None
    if blank and os.path.normcase(os.path.abspath(blank)) != os.path.normcase(os.path.abspath(project)):
        _open_running_or_fail(blank, on_save="no", discard_ok=[project])
        left = _template_loaded(blank, project, _scaled(max(BLANK_LEAVE_S, BLANK_LEAVE_COST_FRAC * float(prior or 0))
                                                        + BLANK_LOAD_S))
        if left is False:
            return left, blank
        if left is None:
            _fl_load_seen(20.0)
    else:
        blank = None
    _open_running_or_fail(project, on_save="no", discard_ok=[project] + ([blank] if blank else []))
    return left, blank


BLANK_LOAD_S = 10.0               # the empty template itself loads within this (after FL let go of the song)
_PROOF_SAID = {"marker": "proven: FL shows the marker stamped into the file for this reload",
               "content": "proven by its content (what the bridge reads differs between the versions)"}
MARKER_GRACE_S = 5.0              # FL settled on the song (title, bridge answering) without the marker this long: old copy
RELOAD_MARK = "flh-"              # a reload marker: RELOAD_MARK + 6 hex digits as a mixer track's name, only in the file


def _mixer_name_bytes(d, ev, t, name):
    """The project bytes with mixer track t's name set to `name` (the layout flp_mixer writes; an empty name = the
    layout FL writes for an unnamed track: its props flag 0, no name event)."""
    tr = [k for k, e in enumerate(ev) if e["id"] == EV_MIXER_TRACK]
    k236 = tr[t]; a = k236
    while a > 0 and ev[a - 1]["id"] in (EV_MIXER_COLOR, EV_MIXER_HASPROPS, EV_MIXER_NAME):
        a -= 1
    color = {ev[k]["id"]: _payload(d, ev[k]) for k in range(a, k236)}.get(EV_MIXER_COLOR)
    new = (bytes([EV_MIXER_COLOR]) + color if color else b"") + bytes([EV_MIXER_HASPROPS, 1 if name else 0])
    if name:
        new += _data_event(EV_MIXER_NAME, str(name).encode("utf-16-le") + b"\x00\x00")
    return _splice(d, ev, [(a, k236, new)])


def _reload_marker_stamp(project, data):
    """Stamp a marker that only the file will have into it, on disk: a mixer track's name (one a channel plays
    through, so FL has it; else insert 1) -> 'flh-xxxxxx'. -> ((track, marker, old name, stamped bytes), None), or
    (None, why not)."""
    if not data:
        return None, "the file couldn't be read"
    try:
        writable(project)
    except Exception:                                             # noqa: BLE001
        return None, "the file is outside the allowed folders (FLH_ROOTS), so no marker could be written into it"
    try:
        ev = _events(data)
        tr = [k for k, e in enumerate(ev) if e["id"] == EV_MIXER_TRACK]
        if not tr:
            return None, "the file has no mixer to carry a marker"
        routed = sorted({int(i) for i in _channel_inserts(data, ev).values() if 0 < int(i) < len(tr) - 1})
        t = routed[0] if routed else (1 if len(tr) > 2 else 0)
        old = _mixer_names(data, ev).get(t, "")
        marker = RELOAD_MARK + os.urandom(3).hex()
        stamped = _mixer_name_bytes(data, ev, t, marker)
        if _mixer_names(stamped, _events(stamped)).get(t) != marker:
            return None, "the marker didn't read back from the file"
        _write_bytes(project, stamped)
        return (t, marker, old, stamped), None
    except Exception as e:                                        # noqa: BLE001
        return None, f"no marker could be written into the file ({type(e).__name__}: {e})"


def _reload_marker_put_back(project, mk, orig):
    """The file as it was before the marker (only while it still holds the stamped copy: never over a newer write)."""
    try:
        with open(project, "rb") as f:
            now = f.read()
        if now == mk[3]:
            _write_bytes(project, orig)
            return True
    except OSError:
        pass
    return False


FAST_RELOAD_MARKER = True         # a fast reopen of a slow-loading song carries a file-only marker (proof on the spot)


def _marker_put_back_live(project, mk, orig, steps, proven=True):
    """After FL loaded the file with marker mk in it: the track's name back in FL, then the file as it was (only while
    it still holds the stamped copy). proven: FL showed the marker - recorded as what FL holds, steps['proof']."""
    # PC-VERIFY: mixer_set(track, name="") gives an unnamed track FL's default name back (core.md 'reload marker')
    try:
        BRIDGE.call("mixer_set", track=mk[0], name=mk[2] or "", timeout=2.0)
        back = (BRIDGE.call("mixer_set", track=mk[0], timeout=2.0) or {}).get("name")
    except Exception:                                             # noqa: BLE001
        back = None
    restored = back is not None and str(back).strip() != mk[1]
    if restored:
        restored = _reload_marker_put_back(project, mk, orig)
    elif proven:
        steps["marker_left"] = (f"mixer track {mk[0]} is still named '{mk[1]}' in FL and in the file (FL didn't "
                                "take its name back): rename it in FL's mixer")
    else:                                                         # not proven FL shows it: the file as it was
        _reload_marker_put_back(project, mk, orig)
    if proven:
        _stale_clear(project)
        _note_fl_holds(project, orig if restored else mk[3])      # recorded only on the marker's proof
        _note_proven_open(project, "marker")
        steps["proof"] = "marker"
    return restored


def _await_marker(project, track, marker, cost=None):
    """After FL was asked to open `project`: True once the bridge reads `marker` as mixer track `track`'s name - only
    the file has it, so FL read the file (an in-memory copy, an undo state or an autosave can't have it). False when FL
    settled on the song without it (FL's title names it, nothing loads, the bridge answers) for MARKER_GRACE_S, or
    answered but never showed it by the end of the wait; None when the bridge never answered.
    PC-VERIFY: the marker is read within a second of FL finishing a 20 s load (checklists/core.md 'reload marker')."""
    names = _project_names(project)
    t0 = time.time(); limit = _scaled(max(RELOAD_SETTLE_S, 2.5 * float(cost or 0))); grace = _scaled(MARKER_GRACE_S)
    since = None; answered = False
    while True:
        now = time.time(); nm = None; on_song = False
        try:
            if not _fl_loading_title():
                stem = (_title_stem(_main_title()) or "").lower()
                on_song = not stem or stem in names               # no readable title: the bridge alone judges
                nm = (BRIDGE.call("mixer_set", track=int(track), timeout=1.5) or {}).get("name")
        except Exception:                                         # noqa: BLE001 - FL busy loading
            nm = None
        if nm is not None:
            answered = True
            if str(nm).strip() == marker:
                return True
        if nm is not None and on_song and not _fl_load_busy(False, cpu=False):
            since = since if since is not None else now
            if now - since >= grace:
                return False
        else:
            since = None
        if now - t0 >= limit:
            return False if answered else None
        time.sleep(0.25)


def _reload_marked(project, prior, steps, why):
    """FL re-reads the open project, PROVEN (fl_reload_from_disk's route): a marker only the file has is stamped into
    it (a mixer track's name), FL loads the empty template - waited until FL shows it loaded - then the file, and the
    bridge must read the marker back. Proven: FL's track name and the file are put back as they were (FL then counts
    the project as changed), what FL holds is recorded, steps['proof'] = 'marker'. Disproven (FL never showed the
    template / showed its old copy): the file is put back, FL is marked as holding an OLDER copy (no save over the
    file, no render of FL taken as the file's) and RuntimeError is raised. Can't be proven (no bridge, file not
    writable): marked the same, steps['unproven'] says why. Without an empty template the file is reopened directly
    (still proven by the marker)."""
    try:                                          # a fast reopen that wasn't trusted may still be loading the file:
        w = _wait_load_out(project, bridge_up=True, cpu=False)   # FL holds it open meanwhile (PC 2026-10-24
        if w >= 0.5:                                  # lazy.big_project: the marker's write hit WinError 5 mid-load;
            steps["load_out_wait"] = w                # a file still held is retried below)
    except Exception:                                             # noqa: BLE001
        pass
    try:
        with open(project, "rb") as f:
            orig = f.read()
    except OSError:
        orig = None
    mk, no_mark = (None, "the bridge doesn't answer, so FL's content can't be read") if not _ping_ok() else \
        _reload_marker_stamp(project, orig)
    if no_mark and "PermissionError" in no_mark:                  # still held (a scan, a late load): once more
        steps["marker_retry"] = no_mark[:120]
        try:
            _wait_load_out(project, bridge_up=True)
        except Exception:                                         # noqa: BLE001
            pass
        mk, no_mark = _reload_marker_stamp(project, orig)
    if no_mark:
        steps["marker"] = f"none: {no_mark}"
    T = time.time(); seen = None
    try:
        left, blank = _reload_via_blank(project, prior)
        if blank is None:
            steps["route"] = "the file reopened directly (no empty template: FLH_BLANK names one)"
        if left is not False:
            if mk:
                T2 = time.time()
                seen = _await_marker(project, mk[0], mk[1], prior)
                steps["marker_wait"] = round(time.time() - T2, 1)
            elif left:
                seen = None if _load_settled(project, prior) is None else "settled"
            else:
                _fl_load_seen(30.0)
            steps["fallback_load"] = round(time.time() - T, 1)
        else:
            steps["template_load"] = round(time.time() - T, 1)
    except BaseException:
        if mk:
            _reload_marker_put_back(project, mk, orig)
        _stale_mark(project, f"reload not taken: {why}; FL's Open failed", orig)
        raise
    if seen is True:                                              # FL read the file: put the marker back out
        _marker_put_back_live(project, mk, orig, steps)
        return steps
    if mk:
        _reload_marker_put_back(project, mk, orig)                # the file keeps exactly what was written into it
    name = os.path.basename(project)
    if left is False or seen is False:
        _stale_mark(project, f"reload not taken: {why}", orig)
        raise RuntimeError(
            f"FL didn't load {name} from disk: {why}; " + (
                "FL didn't show the empty template loaded first (its title / bridge kept the song)" if left is False
                else "FL settled on the song without the marker stamped into the file for this reload (it showed its "
                     "old copy: an in-memory copy, undo state or autosave, not the file)"
                + ("" if blank else ". No empty template was found to load first: set FLH_BLANK to an empty .flp"))
            + ". FL still holds its OLDER copy: fl-headless won't save FL over the file, and renders / previews of FL "
              "aren't taken as the file's. fl_reload_from_disk(project) tries again; or in FL: File > Open another "
              "project, then this one (answer No to 'save changes?')")
    why_not = (no_mark if mk is None and no_mark else
               "the bridge didn't answer after the load" if mk else "FL's title / content couldn't be checked")
    _stale_mark(project, f"reload unproven: {why_not}", orig)     # no 'FL holds it' claim, no save over the file
    steps["unproven"] = (f"FL was told to load the file, but that isn't proven ({why_not}); fl-headless won't save FL "
                         "over the file until a reload is proven (fl_reload_from_disk) - listen before trusting a "
                         "render of FL")
    return steps


def _load_settled(project, cost=None):
    """After the reload tag vanished (FL started reading the file): wait until the load has finished - nothing
    'Opening: ...', FL's title not naming another project, the bridge answering, and FL holding the file's channel
    count (by content: what FL reports vs the file). -> seconds waited, or None when it didn't within
    RELOAD_SETTLE_S / 2.5 x the load cost (scaled). PC 2026-10-23: 'one reload, 1.2 s' on a song that loads in
    10-60 s - the tag can vanish as FL clears the old project, long before the new one is in."""
    try:
        want = _fingerprint(project).get("channels")
    except Exception:                                             # noqa: BLE001
        want = None
    names = _project_names(project)
    t0 = time.time(); limit = _scaled(max(RELOAD_SETTLE_S, 2.5 * float(cost or 0)))
    while True:
        ok = False
        try:
            if not fl_running():                                  # nothing to wait for (FL gone: nothing claimed)
                return round(time.time() - t0, 1)
            stem = (_title_stem(_main_title()) or "").lower()
            if not _fl_loading_title() and not (stem and stem not in names):
                st = _bridge_state_light(timeout=1.5) or {}
                n = st.get("channel_count")
                if n is None and isinstance(st.get("channels"), list) and st.get("channels"):
                    n = len(st["channels"])
                ok = want is None or n is None or int(n) == int(want)
        except Exception:                                         # noqa: BLE001 - FL busy loading: not yet
            ok = False
        if ok:
            return round(time.time() - t0, 1)
        if time.time() - t0 >= limit:
            return None
        time.sleep(0.25)


RELOAD_SUSPECT_MIN_COST_S = 10.0  # a project that loads at least this slowly ...
RELOAD_SUSPECT_FRAC = 0.25        # ... 'reloaded' in under this share of its load time
RELOAD_SUSPECT_ABS_S = 4.0        # (and at least under this) is checked by the content of FL's save


def _reload_took(steps):
    return float(steps.get("open_dialog", 0) or 0) + float(steps["load"] if "load" in steps
                                                           else steps.get("fallback_load", 0) or 0)


def _reload_suspect(cost, steps):
    """(took_s, load_cost_s) when a reload was implausibly fast for this project (PC 2026-10-23: '2 merged edits are
    in FL now (one reload, 2.5 s)' on an orchestral song that loads in 10-60 s; the FINAL then had none of them),
    else None."""
    try:
        cost = float(cost or 0)
    except (TypeError, ValueError):
        return None
    took = _reload_took(steps)
    if steps.get("unsettled"):                                    # FL didn't end up holding the file's content
        return (round(took, 1), round(cost, 1))
    if cost < RELOAD_SUSPECT_MIN_COST_S:
        return None
    return (round(took, 1), round(cost, 1)) if took < max(RELOAD_SUSPECT_ABS_S, RELOAD_SUSPECT_FRAC * cost) else None


def _untag(tr, orig):
    """Put a tagged mixer track's name back - only while it still carries a reload tag (after a reload the track
    holds the file's name, which never had it). -> True (back, or nothing to do), False (FL didn't answer / didn't
    take the name: the tag may be left in FL - the caller reports it), None (no track)."""
    if tr is None:
        return None
    try:
        cur = str(BRIDGE.call("mixer_set", track=tr, timeout=2.0).get("name") or "")
        if cur == _TAG_NOW.get("name") or _TAG_RE.search(cur):
            BRIDGE.call("mixer_set", track=tr, name=orig or "", timeout=2.0)
            back = (BRIDGE.call("mixer_set", track=tr, timeout=2.0) or {}).get("name")
            return back is None or not _TAG_RE.search(str(back))
        return True
    except Exception:                                             # noqa: BLE001 - reported by the caller
        return False


def fl_close(save=True, timeout_s=25):
    """Close the running FL politely (like clicking X). Saves first through the bridge when save is true.
    Never forces: if FL asks something (e.g. unsaved changes) it stays open and this reports it."""
    if not fl_running():
        _sync_before("fl_close")
        return {"closed": True, "was_running": False}
    project, titles = _open_project_guess()
    main = _fl_main_window()
    main_title = main[1] if main else ""
    if not project and " - fl studio" not in main_title.lower():   # still loading: no name in the title yet
        project = _state().get("last_opened")
    saved = None
    untitled = _is_untitled(main_title)
    blocked = (_stale_block(project) if project else _stale_block()) or _preview_mutes_on(project) \
        or (_fl_copy_older(project) if project else None)        # a file put over the song behind FL: no save over it
    if save and untitled:
        saved = "untitled project: not saved (FL would ask where); FL will ask about unsaved changes itself"
    elif save and blocked:                                        # FL's save would undo the newer edits on disk
        saved = blocked + " - answer No if FL asks to save changes"
    elif save:
        try:
            BRIDGE.call("transport", action="save"); saved = True; time.sleep(1.5)
        except Exception as e:                                   # bridge not set up: FL will ask if unsaved
            saved = f"not saved by the bridge ({e})"
    import ctypes
    if main:                                                     # the main window: a floating plugin/channel window
        ctypes.windll.user32.PostMessageW(main[0], 0x0010, 0, 0)  # would only close itself (WM_CLOSE)
    t0 = time.time(); base_s = float(timeout_s); timeout_s = _scaled(base_s)   # a slow PC closes slower
    while time.time() - t0 < timeout_s and fl_running():
        time.sleep(0.5)
    if fl_running() and not fl_dialogs() and _fl_cpu_busy():     # no question asked, FL still busy: once more
        _slow_note("FL is still working (slow PC): closing took longer than usual; waited longer")
        t1 = time.time()
        while time.time() - t1 < timeout_s and fl_running():
            time.sleep(0.5)
    if fl_running():
        pops = fl_dialogs()
        what = "; ".join(f"'{d['title']}' ({d['kind']}: {' / '.join(d['text'][:2])} buttons {d['buttons']})" for d in pops)
        raise RuntimeError("FL didn't close: " + (f"it's showing {what}. Answer with fl_dialog (click) or in FL."
                           if pops else "no popup found; FL may still be busy. Nothing was forced."
                           + _slow_why(base_s, time.time() - t0))
                           + (f" NOTE: {saved}" if save and blocked else ""))   # stale: 'No' keeps the newer file
    _fl_forget()                                                 # FL is gone: it holds no project any more
    synced = _sync_before("fl_close")                            # FL saved and is gone: queued edits go into the
    r = {"closed": True, "was_running": True, "project": project, "saved": saved, "titles": titles}   # file (no reload)
    if synced:
        r["synced"] = synced
    return r


def _fl_close_tool(confirm=False, save=True, timeout_s=25):
    """The fl_close TOOL: fl-headless never closes FL on its own (house rule; renders close it themselves when told
    close_fl=true) - only when the user asked for it."""
    if confirm is not True:
        raise ValueError("fl_close closes FL Studio: only do that when the user asked for it, then call it with "
                         "confirm=true")
    return fl_close(save=save, timeout_s=timeout_s)


def _open_in_running_fl(project, timeout_s=8.0, on_save="no", discard_ok=None):
    """Open `project` in the FL that's already running through its own File > Open dialog (Ctrl+O), because
    launching the .flp file can start a second FL (seen on FL 2026.1.7). Returns True when the dialog took the path."""
    if os.name != "nt":
        return False
    import ctypes
    from ctypes import wintypes
    user32 = ctypes.windll.user32; main = _fl_main_window()
    if not main:
        return False
    hwnd = main[0]
    if not _fl_foreground():                                      # FL to the front (ALT tap, then input attach)
        return False
    fresh = _fresh_untitled()                                     # asked before Ctrl+O: FL's UI is free now
    dlg = None
    for attempt in range(2):
        _focus_main_keys(hwnd)                                    # keys to FL's main window, not a plugin window
        before = {d["hwnd"] for d in fl_dialogs()}
        user32.keybd_event(0x11, 0, 0, 0); user32.keybd_event(0x4F, 0, 0, 0)          # Ctrl+O
        user32.keybd_event(0x4F, 0, 2, 0); user32.keybd_event(0x11, 0, 2, 0)
        got = _await_open_dialog(before, project, timeout_s, on_save, discard_ok, fresh_untitled=fresh)
        dlg = got["hwnd"] if got else None
        if dlg is None or not _audio_open_dialog(got):
            break
        # PC 2026-10-23: with Edison's window holding the keyboard focus, Ctrl+O was Edison's 'Load sample': the
        # song's path went into it and FL stayed on the old project. Close it, give FL's main window the keys, again
        # PC-VERIFY: after _focus_main_keys, Ctrl+O opens FL's project Open dialog even with Edison's window open
        user32.PostMessageW(dlg, 0x0010, 0, 0)
        _wait_for(lambda: not user32.IsWindow(dlg), 2.0, 0.1)
        if attempt == 1:
            _OPEN_REFUSAL["why"] = (f"Ctrl+O reached a plugin window, not FL: FL showed {_popup_words(got)} (a dialog "
                                    "that loads audio, e.g. Edison's 'Load sample') instead of its project Open. "
                                    "fl-headless closed it (nothing was loaded): close that plugin's window in FL "
                                    "(e.g. Edison), then try again")
            return False
        dlg = None
    if dlg is None:
        return False
    box = _file_name_edit(dlg)
    if not box:
        user32.PostMessageW(dlg, 0x0010, 0, 0)                      # close it again, nothing changed
        return False
    user32.SendMessageW(box, 0x000C, 0, ctypes.c_wchar_p(os.path.abspath(project)))   # WM_SETTEXT
    user32.SendMessageW(dlg, 0x0111, 1, 0)                          # WM_COMMAND IDOK = Open
    t0 = time.time()
    while time.time() - t0 < 5 and user32.IsWindow(dlg):
        time.sleep(0.2)
    return not user32.IsWindow(dlg)


def fl_save(wait_s=8.0):
    """Save the project open in FL (like Ctrl+S), and say which file it went to. An untitled project isn't saved
    (FL would ask for a name): fl-headless says so instead."""
    if not fl_running():
        raise RuntimeError("FL Studio isn't running: nothing to save")
    try:
        title = (_fl_main_window() or (None, ""))[1] or ""
    except Exception:
        title = ""
    if title and _is_untitled(title):
        return {"saved": None, "why": "FL's project has no file yet (untitled): save it once in FL (File > Save as), "
                                      "then fl_save works"}
    cur, _ = _open_project_guess()
    blocked = (_stale_block(cur) if cur else _stale_block()) or _preview_mutes_on(cur)
    if blocked:                                                   # FL holds an older copy than the file, or a
        return {"saved": None, "file": cur, "why": blocked}       # preview's live mutes: refused
    if cur and os.path.isfile(cur):
        ok = _save_in_fl_and_wait(cur, wait_s=wait_s, explicit=True)
        if ok:
            return {"saved": cur}
        if _save_refused_why():
            return {"saved": None, "file": cur, "why": _save_refused_why()}
        return {"saved": None, "file": cur, "why": f"FL didn't write {os.path.basename(cur)} within {wait_s:.0f} s "
                                                     "(a dialog open in FL?): fl_dialog shows what's on screen"}
    stem = _title_stem(title)
    cands = _name_candidates(stem) if stem else []
    if len(cands) > 1:                                            # two files share FL's title: never a save into a
        why = _GUESS_WHY.get("why")                               # guessed one - the save itself tells which
        try:                                                      # (every candidate's guards checked first)
            got, how = _open_project_identify(wait_s=wait_s)
        except RuntimeError as e:
            return {"saved": None, "why": f"{e} ({why})" if why and why not in str(e) else str(e)}
        return {"saved": got, "identified_by": how, "fix": why}
    BRIDGE.call("transport", action="save")
    return {"saved": "the open project (its file couldn't be identified)", "title": title}


def fl_open(project, save_current=True):
    """Open a project in the running FL (or start FL with it); then the follow-ups extensions registered
    (_AFTER_OPEN: e.g. a new song's pending level balance starts in the background)."""
    r = _fl_open_raw(project, save_current)
    _after_open(project, r)
    return r


def fl_reload_from_disk(project):
    """Load the open project's FILE into FL again, proven - for after its .flp changed on disk (a copy put over it,
    another program's write) while FL has it open. A marker only the file has is stamped into it (a mixer track's
    name), FL loads the empty template - waited until FL shows it loaded - then the file, and the bridge must read the
    marker back; then FL's track name and the file are put back as they were. FL's unsaved changes are dropped.
    -> {reloaded, proof, steps_s} or an honest error: FL kept its old copy (it is then marked so: nothing saves FL
    over the file, renders of FL aren't taken as the file's). fl_open(<the open project>, save_current=false) does
    the same."""
    if not os.path.isfile(project):
        raise FileNotFoundError(project)
    project = os.path.abspath(project)
    if not fl_running():
        raise RuntimeError("FL isn't running: fl_open(project) opens it (FL reads the file then)")
    where = _open_state(project)
    if where == "not_open":
        raise RuntimeError(f"FL doesn't have {os.path.basename(project)} open: fl_open(project) opens it (FL reads "
                           "the file then)")
    if _pending_get(project):                                     # queued edits go into the FILE first (FL isn't
        _sync_before("fl_reload_from_disk", project, file_only=True)   # saved: its changes are dropped anyway)
    T = time.time()
    with _reload_verified():
        steps = dict(_reload_in_fl(project, discard=True) or {})
    steps["reload"] = round(time.time() - T, 1)
    _OPEN_PROOF["path"] = None
    _state({"last_opened": project}); _stop_autoplay_later()
    r = {"reloaded": project}
    proof = steps.pop("proof", None)
    if proof:
        r["proof"] = _PROOF_SAID.get(proof, proof)
    for k, k2 in (("unproven", "reload_unproven"), ("popups_closed", "popups_closed"), ("marker_left", "marker_left"),
                  ("tag_left", "tag_left")):
        if steps.get(k):
            r[k2] = steps.pop(k)
    r["steps_s"] = steps
    return r


def _fl_open_raw(project, save_current=True):
    if not os.path.isfile(project):
        raise FileNotFoundError(project)
    if _pending_get(project) and save_current is False:          # queued edits go into the FILE only: FL isn't
        _sync_before("fl_open", project, file_only=True)          # saved (the caller said so); FL then loads it
    elif _pending_get(project):                                  # queued edits of the project to open go in first
        refresh = _open_in_fl(project)                           # (open in FL: one save+reload; else: the file)
        synced = _sync_before("fl_open", project)
        if refresh and synced:
            return {"opened": project, "via": "applying its queued edits reloaded it", "synced": synced}
    t0 = time.time()                                             # an FL that is shutting down (after a render) or
    while os.name == "nt" and fl_running() and not _fl_main_window() and time.time() - t0 < 30:   # still starting
        time.sleep(0.5)
    if fl_running():
        bridge_up = False
        try:
            BRIDGE.call("transport", action="stop", timeout=3.0)   # FL won't switch projects mid-playback
            bridge_up = True                                      # (it answered: silence later = FL busy loading)
        except Exception:
            pass
        cur, _titles = _open_project_guess()
        pids = set(_fl_pids()); probe = None; steps = {}; proven = None; note = None; switch_seen = None
        popups_closed = []                                        # what fl-headless' own Opens left behind, closed
        if t0 and time.time() - t0 > 0.5:
            steps["wait_fl_window"] = round(time.time() - t0, 1)
        stem = _title_stem(_main_title())
        if _stale_get(project) and _open_state(project) == "open":
            # FL holds an OLDER copy of this very file (its last reload failed): load the file, never save FL first
            # (that save would undo the edits on disk). PC-VERIFY: fl_open after a timed-out reload loads the
            # edited file without a save (the file's mtime doesn't change before the load)
            T = time.time()
            with _reload_verified():                              # FL's copy is known to be older: proven reload
                steps.update(_reload_in_fl(project) or {})
            steps["stale_reload"] = round(time.time() - T, 1)
            _state({"last_opened": os.path.abspath(project)}); _stop_autoplay_later()
            r = {"opened": project, "via": "reloaded the file (FL held an older copy; not saved first)",
                 "steps_s": steps}
            for k, k2 in (("unproven", "reload_unproven"), ("popups_closed", "popups_closed"),
                          ("marker_left", "marker_left"), ("tag_left", "tag_left")):
                if steps.get(k):
                    r[k2] = steps.pop(k)
            if steps.get("proof"):
                r["proof"] = _PROOF_SAID.get(steps["proof"], steps["proof"])
            return r
        user_discard = save_current is False                      # the caller said: don't save FL's project
        stale_cur = cur if cur and _ud_key(cur) != _ud_key(project) and _stale_get(cur) else None
        if stale_cur:                                             # leaving a project FL holds an older copy of:
            save_current = False                                  # 'No' to 'save changes?' (the file is newer)
            note = (f"{os.path.basename(stale_cur)} wasn't saved before switching: FL held an older copy than its "
                    "file (its last reload failed), so the file on disk keeps the newer edits")
        mutes = None if user_discard else _preview_mutes_on(cur if cur and _ud_key(cur) != _ud_key(project) else None)
        if mutes:                                                 # 'Yes' to 'save changes?' would write a preview's
            raise RuntimeError(mutes.replace("not saved:", "nothing was opened:", 1)   # live mutes into the file
                               + f"; or fl_open('{project}', save_current=false) switches without saving")
        if not stale_cur and cur and _ud_key(cur) != _ud_key(project) and not user_discard:
            older = _fl_copy_older(cur)                           # leaving a project whose file changed behind FL:
            if older:                                             # 'Yes' to 'save changes?' would overwrite it
                if _fl_changed_flag() != 0:
                    raise RuntimeError(older + ", and FL has unsaved changes in it (or can't say). Nothing was "
                                       f"opened: fl_open('{project}', save_current=false) switches without saving "
                                       "(FL's changes are dropped, the file keeps what's on disk); to keep FL's work "
                                       "too, save it in FL under another name (File > Save as) first")
                save_current = False                              # nothing unsaved in FL: 'No' loses nothing
                note = f"{os.path.basename(cur)} wasn't saved before switching: its file changed after FL loaded it"
        if (cur and _ud_key(cur) == _ud_key(project)) or (not cur and stem and stem.lower() in _project_names(project)):
            # FL shows this project's name: reloading answers 'No' to 'save changes?'. Nothing to save (the caller
            # said save_current=false, or FL reports no unsaved changes): reload, never a save. Else first prove with
            # a save through the bridge that FL's project IS this file (its work is then on disk; nothing can be
            # lost) - but never a save over a file that changed on disk after FL loaded it (PC 2026-10-23: the
            # identity save wrote FL's older copy over a restored file, with save_current=false, twice)
            flag = _fl_changed_flag()
            older = _fl_copy_older(project)
            if user_discard or flag == 0:
                if not user_discard and not older and cur and _ud_key(cur) == _ud_key(project) \
                        and _fl_held(project):
                    _state({"last_opened": os.path.abspath(project)})
                    return {"opened": project, "via": "already open in FL (it holds this file as it is on disk and "
                                                      "has no unsaved changes): nothing to do", "steps_s": steps}
                T = time.time()
                # a reopen of the open project = fl_reload_from_disk: FL serves a direct reopen of the same path from
                # its own copy (PC 2026-10-23), so the empty template first and a marker only the file has, read back
                with _reload_verified():
                    steps.update(_reload_in_fl(project, discard=True) or {})
                steps["reload"] = round(time.time() - T, 1)
                _OPEN_PROOF["path"] = None
                _state({"last_opened": os.path.abspath(project)}); _stop_autoplay_later()
                why = ("save_current=false" if user_discard else "FL had no unsaved changes")
                r = {"opened": project, "via": f"reloaded the file in FL ({why}: not saved first)", "steps_s": steps}
                pops = steps.pop("popups_closed", None)
                if pops:
                    r["popups_closed"] = pops
                proof = steps.pop("proof", None); unproven = steps.pop("unproven", None)
                if unproven:
                    r["reload_unproven"] = unproven
                if proof:
                    r["proof"] = _PROOF_SAID.get(proof, proof)
                for k in ("marker_left", "tag_left"):
                    if steps.get(k):
                        r[k] = steps.pop(k)
                if older:
                    r["note"] = ("the file had changed on disk since FL loaded it: " + (
                        "FL was told to load it, but that isn't proven (reload_unproven)" if unproven else
                        "FL now shows the file's version (" + _PROOF_SAID.get(proof, "reloaded") + ")"))
                return r
            if older:
                raise RuntimeError(older + ", and FL has unsaved changes (or its bridge can't say). Nothing was saved "
                                   f"or reloaded: fl_open('{project}', save_current=false) loads the file (FL's unsaved "
                                   "changes are dropped); to keep FL's work too, save it in FL under another name "
                                   "(File > Save as) first. If the change on disk was your own save in FL, fl_save() "
                                   "once, then fl_open again")
            if not _fl_held(project):               # nothing known about what FL holds: the file on
                try:                                              # disk stays restorable whatever the save writes
                    _backup_once(project); steps["backup_first"] = True
                except Exception:
                    pass
            T = time.time(); proven = _prove_open(project); steps["identity_save"] = round(time.time() - T, 1)
            if proven and proven != "never_saved":
                cur = proven
            elif cur:
                note = (f"FL shows '{stem}', but its save didn't land in {os.path.basename(project)}, so it wasn't "
                        "reloaded in place; opened through FL's Open dialog instead (answering Yes to 'save changes?'"
                        ", so nothing is lost)")
                cur = None
        if cur and proven and _ud_key(cur) == _ud_key(project):
            probe = _PROBE_RELOAD and fl_reload_probe(project)
            if not probe:
                steps.update(_reload_in_fl(project) or {})       # FL ignores opening what it already has open
        else:
            try:
                main_title = (_fl_main_window() or (None, ""))[1] or ""
            except Exception:
                main_title = ""
            T = time.time()
            saved_first = None
            if save_current and not proven and main_title and not _is_untitled(main_title):
                # 'Yes' to 'save changes?' / the save below writes FL's copy into FL's file - whichever same-title
                # file that is: never over one FL holds an older copy of (K1: a save into the OTHER 'Song')
                twin_why = None
                for c in ([cur] if cur else []) + [c for c in (_name_candidates(stem) if stem else [])
                                                   if not cur or _ud_key(c) != _ud_key(cur)]:
                    twin_why = _stale_block(c) if _stale_get(c) else _fl_copy_older(c)
                    if twin_why:
                        break
                if twin_why:
                    raise RuntimeError(twin_why.replace("not saved:", "nothing was opened:", 1)
                                       + f"; fl_open('{project}', save_current=false) switches without saving")
            if cur and main_title and not _is_untitled(main_title) and not proven and save_current:
                saved_first = cur
                dlg0 = _dialog_ids()
                try:
                    BRIDGE.call("transport", action="save", timeout=5.0); time.sleep(1.0)   # no 'save changes?' then
                except Exception:
                    pass
                trial = _cancel_trial_warning(dlg0)
                if trial:                                         # never Ctrl+O into a blocked FL
                    raise RuntimeError(trial)
                steps["save_current"] = round(time.time() - T, 1); T = time.time()
            if not save_current and not cur:                      # its file is gone (deleted or moved): the last one
                last = _state().get("last_opened")                # opened, when FL's title names exactly that one
                if last and not os.path.isfile(last) and _title_is_one_of([last]):
                    cur = last

            def send_open():
                if save_current:
                    _open_running_or_fail(project, on_save="yes")   # FL's own Open dialog: never a second FL
                else:                                             # 'No' to 'save changes?': for the file FL had - or
                    _open_running_or_fail(project, on_save="no",  # whatever FL shows when the caller said
                                          discard_ok=_DISCARD_ANY if user_discard else ([cur] if cur else None))
            _OPEN_PENDING.update(project=os.path.abspath(project), t=time.time())
            dlg_before = _dialog_ids()                            # popups up before: never ours to close
            retried = False
            try:
                send_open()
                # PC 2026-10-23: the Open dialog took the path, yet FL stayed on the old project (its title 20 s later);
                # a second fl_open worked. The switch is checked: FL's title must name the project (or FL be loading)
                seen = _await_switch(project, main_title, bridge_up)
                if seen is None:
                    steps["first_open_ignored_s"] = round(time.time() - T, 1)
                    # never a second Ctrl+O into a busy FL, nor on top of a late Open / 'save changes?' of the first
                    w = _wait_load_out(project, bridge_up=bridge_up)
                    if w >= 0.5:
                        steps["waited_busy_s"] = w
                    seen = _await_switch_quick(project)
                    if seen is None:
                        left = _sweep_leftover_popups(dlg_before, save_current)
                        if left:
                            popups_closed.extend(left)
                        retried = True
                        send_open()
                        seen = _await_switch(project, main_title, bridge_up)
                if seen is None:
                    left = _sweep_leftover_popups(dlg_before, save_current)
                    raise RuntimeError(f"FL didn't switch to {os.path.basename(project)}: its Open dialog took the path "
                                       f"twice, but FL's title still shows '{_main_title() or main_title}' (no loading "
                                       "seen). Nothing else was changed" + (f"; closed what the Opens left: "
                                       f"{_popups_said(popups_closed + left)}" if popups_closed or left else "")
                                       + "; check FL for a popup (fl_dialog) and try again")
            except BaseException:
                _OPEN_PENDING.update(project=None, t=0.0)
                raise
            if retried:                                           # a Ctrl+O FL queued while busy pops up after the load:
                w = _wait_load_out(project, bridge_up=bridge_up)  # wait it out, then look once more
                if w >= 0.5:
                    steps["waited_load_s"] = w
                if _await_switch_quick(project) == "shown":
                    seen = "shown"
                time.sleep(_scaled(OPEN_LEFTOVER_GRACE_S))
            popups_closed.extend(_sweep_leftover_popups(dlg_before, save_current))
            if seen != "loading":
                _OPEN_PENDING.update(project=None, t=0.0)
            switch_seen = seen
            _OPEN_PROOF["path"] = None                            # FL switched files: an older proof is void
            if cur and _ud_key(cur) != _ud_key(project):
                _fl_forget(cur)                                   # FL left it: a later load reads the file fresh
            _note_fl_holds(project)                               # FL loads the file as it is now
            if seen == "same_name":                               # the title can't show the switch: no proof
                _LAST_PROVEN.clear()
            else:                                                 # FL's title switched to the path it was given
                _note_proven_open(project, "open")
            steps["open_dialog"] = round(time.time() - T, 1)
            _measure_load_later(project, T, shown_before=stem or "")
        _state({"last_opened": os.path.abspath(project)}); _stop_autoplay_later()
        if cur and _ud_key(cur) != _ud_key(project) and _pending_get(cur):   # the project FL left (FL saved it):
            _sync_before("fl_open", cur, file_only=True)          # its queued edits go into the file, no reload
        r = {"opened": project, "via": "FL's Open dialog", "steps_s": steps}
        if switch_seen == "loading":
            r["loading"] = ("FL is still loading it (its title doesn't name it yet); tools that need it wait for the "
                            "load")
        elif switch_seen == "same_name":
            r["switch_unproven"] = ("FL's title showed the same name before, so the switch can't be seen in it; "
                                    "fl_status / the next tool proves which file FL holds")
        tw = _title_warning(project)
        if tw:                                                    # a same-title copy: say it, with the fix
            r["title_warning"] = tw
        if locals().get("saved_first"):
            r["saved_first"] = saved_first                       # said, not hidden: the file FL saved before switching
        elif not save_current and cur and _ud_key(cur) != _ud_key(project):
            r["not_saved"] = cur
        if note:
            r["note"] = note
        if probe:
            r["probe"] = probe
        if popups_closed:
            r["popups_closed"] = popups_closed
        extra = set(_fl_pids()) - pids
        if extra:
            r["warning"] = (f"a second FL appeared (pid {sorted(extra)}); close the extra window so only one FL runs")
        return r
    for hook in list(_BEFORE_FL_START):                          # e.g. a waiting theme switch (FL is closed now)
        try:
            hook()
        except Exception:
            pass
    try:                                                         # FL not running: start THIS FL with the project
        subprocess.Popen([fl_exe(), os.path.abspath(project)])   # PC-VERIFY: FL opens the project
    except (FileNotFoundError, OSError):                         # (the .flp association may be another version)
        os.startfile(project)
    _state({"last_opened": os.path.abspath(project)})
    _fl_forget(); _note_fl_holds(project)                        # a fresh FL holds only this file
    _measure_load_later(project, time.time(), wait_s=300)       # includes FL's own start-up
    _stop_autoplay_later()
    return {"opened": project}


_AUTOPLAY = {"gen": 0}                                             # bumped when a tool starts playback on purpose
_PLAYS_RE = re.compile(r"play|listen|review|audition|mix_check|record|capture|transport|_ab$|masking|mix_engineer|"
                       r"level_check|reference|vocal_balance|second_opinion")


def _stop_autoplay_later(wait_s=40):
    """FL starts playing after it loads a project; stop that once the bridge answers (in the background). Stands
    down when a tool meanwhile starts playback on purpose (fl_listen, fl_play...), and only stops while no other FL
    step runs (it takes the FL lock without waiting)."""
    gen = _AUTOPLAY["gen"]

    def run():
        time.sleep(2.0); t0 = time.time(); limit = _scaled(wait_s)
        while time.time() - t0 < limit:
            if _AUTOPLAY["gen"] != gen:
                return
            if not _FL_LOCK.acquire(blocking=False):
                time.sleep(1.0); continue
            try:
                if _AUTOPLAY["gen"] != gen:
                    return
                BRIDGE.call("ping", timeout=2.0)
                time.sleep(1.0)
                if _AUTOPLAY["gen"] != gen:
                    return
                BRIDGE.call("transport", action="stop"); return
            except Exception:
                pass
            finally:
                _FL_LOCK.release()
            time.sleep(1.0)
    threading.Thread(target=run, daemon=True).start()


def _automation_events(d, ev):
    """{channel index: event index of its automation points} for automation clip channels."""
    out, cur = {}, None
    for k, e in enumerate(ev):
        if e["id"] == EV_CHANNEL:
            cur = struct.unpack("<H", _payload(d, e))[0]
        elif e["id"] == EV_AUTOMATION and cur is not None:
            out[cur] = k
    return out


def _auto_points(p):
    cnt = struct.unpack("<I", p[17:21])[0]; o = 21; pts = []; beat = 0.0
    for _ in range(cnt):
        off, val, ten = struct.unpack("<ddf", p[o:o + 20]); beat += off
        pts.append([beat, val, ten, p[o + 20:o + 24]]); o += 24
    return pts, p[:17], p[o:]


def _auto_trim(p, cut):
    """Automation points re-cut to start `cut` beats into the clip (value at the cut interpolated)."""
    pts, head, tail = _auto_points(p)
    before = [q for q in pts if q[0] <= cut]; after = [q for q in pts if q[0] > cut]
    if before and after:
        a, b = before[-1], after[0]
        v = a[1] + (b[1] - a[1]) * (cut - a[0]) / ((b[0] - a[0]) or 1)
    else:
        v = (before or after)[-1 if before else 0][1]
    new = [[cut, v, 0.0, b"\x00" * 4]] + after
    body = b""; prev = cut
    for i, (beat, val, ten, flag) in enumerate(new):
        body += struct.pack("<ddf", beat - prev, val, ten) + (b"\x00" * 4 if i == 0 else flag); prev = beat
    return head + struct.pack("<I", len(new)) + body + tail


def _section_bytes(d, start_bar, end_bar=None):
    """A copy of the project that plays only bars [start_bar, end_bar): clips are cut to the window and moved to
    bar 1, and the project tempo is set to the tempo at start_bar."""
    ev = _events(d); P = _ppq(d); meters = _meter_map(d, ev)
    S = _bar_to_tick(start_bar, meters, P)                        # bars follow the time signature (and its markers)
    _, tempos = _song(d, ev)
    clips_end = max((struct.unpack("<I", r[0:4])[0] + struct.unpack("<I", r[8:12])[0] for _, _, r in _clips(d, ev)), default=0)
    E = _bar_to_tick(end_bar, meters, P) if end_bar else clips_end
    if E <= S:
        raise ValueError("end_bar must be after start_bar")
    edits = []; skipped = 0; trims = {}
    autos = _automation_events(d, ev)
    k_pl, _, recs_pl = _playlist_at(d, ev)                        # the arrangement FL plays
    if k_pl is not None:
        keep = []
        for r in recs_pl:
            pos, ln = struct.unpack("<I", r[0:4])[0], struct.unpack("<I", r[8:12])[0]
            so = struct.unpack("<I", r[24:28])[0]
            a, b = max(pos, S), min(pos + ln, E)
            if b <= a:
                continue
            cut = a - pos
            item = struct.unpack("<H", r[6:8])[0]
            if item < PATTERN_BASE:                              # audio / automation clip
                if cut:
                    if item in autos and struct.unpack("<ff", bytes(r[24:32])) == (-1.0, -1.0):
                        trims[item] = cut / P                    # automation: re-cut its points below
                    else:
                        skipped += 1; continue                   # audio starting before the window
                r[0:4] = struct.pack("<I", a - S); r[8:12] = struct.pack("<I", b - a)
                keep.append(bytes(r)); continue
            r[0:4] = struct.pack("<I", a - S); r[8:12] = struct.pack("<I", b - a)
            r[24:28] = struct.pack("<I", so + cut); r[28:32] = struct.pack("<I", so + cut + (b - a))
            keep.append(bytes(r))
        edits.append((k_pl, k_pl + 1, _data_event(EV_PLAYLIST, b"".join(keep))))
    for ch, cut_beats in trims.items():
        k = autos[ch]
        edits.append((k, k + 1, _data_event(EV_AUTOMATION, _auto_trim(_payload(d, ev[k]), cut_beats))))
    t_at = [b for t, b in tempos if t <= S][-1]
    for k, e in enumerate(ev):
        if e["id"] == EV_TEMPO:
            edits.append((k, k + 1, bytes([EV_TEMPO]) + struct.pack("<I", int(round(t_at * 1000)))))
    return _splice(d, ev, edits), round(t_at, 2), round(_tick_to_bar(E, meters, P) - _tick_to_bar(S, meters, P), 2), skipped


def fl_render(project, output_dir=None, formats="wav", timeout_s=900, allow_while_running=False, close_fl=False,
              reopen=True, start_bar=None, end_bar=None, method="auto"):
    """Render a project. method in_fl: FL's own export in the open FL (no close, no extra loads); cli: FL's
    command-line export (FL64.exe /R /E<formats> /O<folder> <project>) on a temp copy with a space-free name - FL
    must be closed (close_fl: save, close politely, render, reopen what was open). auto: in_fl when FL is running and
    an in-FL export has worked on this PC, else cli; an in-FL export that can't start falls back to cli when
    close_fl allows it."""
    project = os.path.abspath(project)
    out_dir = os.path.abspath(output_dir or os.path.dirname(project)); writable(out_dir); os.makedirs(out_dir, exist_ok=True)
    n0 = _renders_here(); T0 = time.time()
    hit = _fl_render_reuse(project, out_dir, formats, method, start_bar, end_bar)
    if hit:
        return hit
    fallback = None
    if _render_method(project, formats, method, start_bar) == "in_fl":
        if start_bar:
            raise ValueError("FL's own export renders the whole song: section previews use method='cli' (or fl_listen)")
        try:
            r = _render_cached(project, out_dir, formats, timeout_s, method="in_fl", close_fl=False, store="external")
            r["renders"] = _renders_here() - n0
            r.setdefault("steps_s", {})["total"] = round(time.time() - T0, 1)
            return r
        except InFlUnavailable as e:
            if not close_fl:
                raise RuntimeError(f"FL's own export didn't start: {e}. Nothing was rendered; pass close_fl=true to "
                                   "use the command line instead (FL is saved and closed first)") from e
            fallback = f"FL's own export didn't start ({e}); used the command line"
    if allow_while_running:
        raise ValueError("allow_while_running is no longer supported: fl-headless never starts a second FL. Use "
                         "method='in_fl' (export from the open FL) or close_fl=true")
    closed = None; steps = {}; T = time.time()
    if fl_running():
        if not close_fl:
            raise RuntimeError("FL Studio is open. Pass close_fl=true to save, close, render and reopen it "
                               "automatically, close it yourself first, or method='in_fl' to export from the open FL.")
        closed = fl_close(save=True); steps["close_fl"] = round(time.time() - T, 1)
    T = time.time()
    try:
        if start_bar:
            data, bpm, bars, skipped = _section_bytes(_load(project), start_bar, end_bar)
            stem = f"{os.path.splitext(os.path.basename(project))[0]} (bars {int(float(start_bar))}-{int(float(start_bar) + bars)})"
            res = _render(project, out_dir, formats, timeout_s, data=data, out_stem=stem)
            res.update({"section_bars": bars, "start_tempo": bpm})
            if skipped:
                res["note"] = f"{skipped} audio clip(s) start before the section and were left out"
        else:
            res = _render(project, out_dir, formats, timeout_s)
        steps["render"] = round(time.time() - T, 1)
    finally:
        if closed and reopen:
            back = closed.get("project")
            if back and os.path.isfile(back):
                T = time.time(); fl_open(back); steps["reopen"] = round(time.time() - T, 1)
    res["steps_s"] = steps; res["method"] = "cli"
    _fl_render_store(project, res, formats, start_bar, end_bar)
    res["renders"] = _renders_here() - n0
    if fallback:
        res["in_fl_fallback"] = fallback
    if closed:
        res["fl_was_closed_and_reopened"] = bool(reopen and closed.get("project"))
        res["reopened"] = closed.get("project") if reopen else None
    return res


def _fl_render_reuse(project, out_dir, formats, method, start_bar, end_bar):
    """fl_render of a song (or bar range) that was rendered unchanged before: the earlier file is handed back (copied
    when another folder / name was asked) - no FL export, no closing. A range is also cut from a cached full render."""
    RC = _rc(); T = time.time()
    fmt = ",".join(f.strip().lower() for f in str(formats).split(",") if f.strip())
    if "," in fmt or not RC.enabled():
        return None
    try:
        _sync_before("render", project)
        fp, note = _rc_project_fp(project, live=_project_is_open(project) and fl_running())
    except Exception:                                             # noqa: BLE001
        return None
    if not fp:
        return None
    opts = {"formats": fmt} if not start_bar else {"formats": fmt, "start_bar": float(start_bar),
                                                    "end_bar": float(end_bar) if end_bar else None}
    hit = RC.get(RC.mix_key(fp, **opts), exact=True)
    base = os.path.splitext(os.path.basename(project))[0]
    stem = base if not start_bar else None
    if hit:
        src = hit["files"][0]["path"]
        if stem is None:
            stem = hit.get("meta", {}).get("stem") or f"{base} (bars {int(float(start_bar))}-)"
        dst = _render_dest(out_dir, stem, os.path.splitext(src)[1])
        if os.path.normcase(os.path.abspath(src)) != os.path.normcase(os.path.abspath(dst)):
            shutil.copy2(src, dst); _note_render(dst)
        _note_reuse()
        r = {"rendered": [dst], "seconds": 0.0, "method": hit.get("route"), "renders": 0,
             "reused": f"reused render (unchanged since {_when(hit['created'])})",
             "steps_s": {"cache": round(time.time() - T, 2)}}
        return dict(r, note=note) if note else r
    if start_bar and fmt == "wav":                                # a section of a cached full render
        full = RC.get(RC.mix_key(fp, formats="wav"), exact=True)
        if full:
            d = _read_flp_bytes(project)
            _ts, bar_s, _P, _m = RC.timeline(d)
            x, fs = RC.load(full["files"][0])
            i = int(bar_s(float(start_bar)) * fs); j = int(bar_s(float(end_bar)) * fs) if end_bar else len(x)
            import fl_audio_edit as AE
            dst = _render_dest(out_dir, f"{base} (bars {int(float(start_bar))}-{int(float(end_bar)) if end_bar else 'end'})",
                               ".wav")
            AE.save(dst, x[i:j], fs, 24); _note_render(dst); _note_reuse()
            return {"rendered": [dst], "seconds": 0.0, "renders": 0, "method": full.get("route"),
                    "reused": f"cut from the cached full render ({_when(full['created'])}): no export",
                    "steps_s": {"cache": round(time.time() - T, 2)}}
    return None


def _fl_render_store(project, res, formats, start_bar, end_bar):
    """Remember fl_render's output (referenced where it was written, never copied) for the next identical render."""
    try:
        RC = _rc(); files = res.get("rendered") or []
        fmt = ",".join(f.strip().lower() for f in str(formats).split(",") if f.strip())
        if len(files) != 1 or "," in fmt or not RC.enabled():
            return
        fp = RC.fingerprint(_read_flp_bytes(project))                # FL closed (saved): the file is what rendered
        opts = {"formats": fmt} if not start_bar else {"formats": fmt, "start_bar": float(start_bar),
                                                        "end_bar": float(end_bar) if end_bar else None}
        RC.put(RC.mix_key(fp, **opts), "render", [{"src": files[0], "mode": "external", "name": "mix"}],
               meta={"stem": os.path.splitext(os.path.basename(files[0]))[0]}, route="cli", project=project)
    except Exception:                                             # noqa: BLE001
        pass


def _safe_stem(path):
    """An ASCII, space-free name for the temp copy FL renders (FL's command line dislikes spaces; accents and
    other scripts are dropped too - the output still gets the project's real name)."""
    return "".join(c for c in os.path.splitext(os.path.basename(path))[0]
                   if (c.isascii() and c.isalnum()) or c in "_-") or "song"


def _cmd_safe(path):
    return path.isascii() and " " not in path


def _short_path(path):
    """Windows 8.3 short form of an existing path (ASCII, no spaces) when the volume has short names, else path."""
    if not IS_WINDOWS:
        return path
    try:
        import ctypes
        buf = ctypes.create_unicode_buffer(1024)
        n = ctypes.windll.kernel32.GetShortPathNameW(path, buf, 1024)
        return buf.value if 0 < n < 1024 else path
    except Exception:
        return path


def _render_workdir():
    """A temp folder FL's command line can take: %TEMP% holds the user name, which may have spaces or accents
    (C:\\Users\\José García\\...). Returns (real path, path to hand FL): the short 8.3 form when that is safer."""
    work = tempfile.mkdtemp(prefix="flh_")
    if _cmd_safe(work):
        return work, work
    short = _short_path(work)
    return work, (short if _cmd_safe(short) else work)


def _run_fl(target, rend, formats, expected, timeout_s):
    """Run FL's command-line export on one project; wait for `expected` audio files."""
    if fl_running():                                              # house rule: never a second FL
        raise RuntimeError("FL is running, and the command-line export would start a second FL; close FL first "
                           "(close_fl=true) or render from the open FL (method='in_fl')")
    cmd = [fl_exe(), "/R", "/E" + formats, "/O" + rend, target]
    exts = [f.strip().lower() for f in formats.split(",") if f.strip()]
    t0 = time.time(); proc = subprocess.Popen(cmd)
    produced, stable, last = {}, 0, None
    base = float(timeout_s); timeout_s = _scaled(base); extra = _speed_extra(base, timeout_s); grew = 0.0
    start_s = _scaled(20)                                        # a slow PC starts FL (and writes the 1st file) later
    while True:
        if time.time() - t0 >= timeout_s:
            if extra > 0 and proc.poll() is None and time.time() - grew < 10.0:   # files still growing: once more
                timeout_s += extra; extra = 0.0
                _slow_note(f"FL is still working (slow PC): the command-line render ran past {base:g} s; waited longer")
            else:
                break
        time.sleep(2)
        files = {f: os.path.getsize(os.path.join(rend, f)) for f in os.listdir(rend)}
        done = [f for f in files if os.path.splitext(f)[1].lower().lstrip(".") in exts]
        stable = stable + 1 if done and files == last else 0
        if files != last:
            grew = time.time()
        last = files; produced = files
        if done and len(done) >= expected and (proc.poll() is not None or stable >= 5):
            break
        if proc.poll() is not None and (stable >= 2 or (not done and time.time() - t0 > start_s)):
            break
    for _ in range(int(_scaled(45))):                            # let FL close on its own
        if proc.poll() is not None:
            break
        time.sleep(1)
    exited = proc.poll() is not None
    if not exited:
        proc.terminate()                                         # only the instance started here
    return produced, exited, round(time.time() - t0, 1), cmd


def _our_renders():
    try:
        return set(_state().get("renders") or [])
    except Exception:
        return set()


def _note_render(path):
    """Remember files fl-headless rendered: re-renders may overwrite those (check renders aren't piled up)."""
    try:
        have = [p for p in (_state().get("renders") or []) if p != _ud_key(path)]
        _state({"renders": (have + [_ud_key(path)])[-500:]})
    except Exception:
        pass


def _render_dest(out_dir, stem, ext):
    """Where a render goes: '<stem><ext>', overwriting only an earlier render of ours. A file of the user's own with
    that name (their own bounce, a stem the project uses) is never overwritten: '<stem> (render)<ext>' instead."""
    for n in range(1, 100):
        name = stem if n == 1 else (f"{stem} (render)" if n == 2 else f"{stem} (render {n - 1})")
        dst = os.path.join(out_dir, name + ext)
        if not os.path.exists(dst) or _ud_key(dst) in _our_renders():
            writable(dst)
            return dst
    raise RuntimeError(f"too many files named like {stem}{ext} in {out_dir}")


def _render(project, out_dir, formats, timeout_s, data=None, out_stem=None):
    _sync_before("render")                                       # the file must hold queued edits
    work, fl_work = _render_workdir()
    try:
        src = os.path.join(work, _safe_stem(project) + ".flp")
        if data is None:
            shutil.copy2(project, src)
        else:
            with open(src, "wb") as f:
                f.write(data)
        rend = os.path.join(work, "out"); os.makedirs(rend)
        exts = [f.strip().lower() for f in formats.split(",") if f.strip()]
        fl_src, fl_rend = (os.path.join(fl_work, os.path.basename(src)), os.path.join(fl_work, "out")) \
            if fl_work != work else (src, rend)
        produced, exited, secs, cmd = _run_fl(fl_src, fl_rend, formats, len(exts), timeout_s)
        _note_export("cli", secs)
        results = []
        for f in sorted(produced):
            if os.path.splitext(f)[1].lower().lstrip(".") not in exts:
                continue
            dst = _render_dest(out_dir, out_stem or os.path.splitext(os.path.basename(project))[0], os.path.splitext(f)[1])
            shutil.move(os.path.join(rend, f), dst); results.append(dst); _note_render(dst)
        if not results:
            raise RuntimeError(f"no audio produced after {int(secs)} s (FL exited: {exited}). Command: {' '.join(cmd)}")
        return {"rendered": results, "seconds": secs, "fl_closed_by_itself": exited}
    finally:
        shutil.rmtree(work, ignore_errors=True)


def fl_render_batch(projects, output_dir=None, formats="wav", timeout_s=1800, close_fl=False, reopen=True,
                    background=True):
    """See _render_batch; runs as a background job by default (check with fl_job)."""
    if background:
        return _start_job("batch", _render_batch, projects, output_dir, formats, timeout_s, close_fl, reopen,
                          fl=True)
    return _render_batch(projects, output_dir, formats, timeout_s, close_fl, reopen)


def _render_batch(projects, output_dir=None, formats="wav", timeout_s=1800, close_fl=False, reopen=True):
    """Render several projects one after another, closing FL once and reopening it once at the end.
    (FL's command line renders one project per launch: a folder argument doesn't render its projects.)"""
    projects = [os.path.abspath(p) for p in projects]; n0 = _renders_here()
    for p in projects:
        if not os.path.isfile(p):
            raise FileNotFoundError(p)
    out_dir = os.path.abspath(output_dir or os.path.dirname(projects[0])); writable(out_dir); os.makedirs(out_dir, exist_ok=True)
    closed = None; steps = {}; t0 = time.time()
    if fl_running():
        if not close_fl:
            raise RuntimeError("FL Studio is open. Pass close_fl=true to save, close, render and reopen it.")
        _job_progress(step="close_fl")
        closed = fl_close(save=True); steps["close_fl"] = round(time.time() - t0, 1)
    t0 = time.time(); results = []; res = {}
    try:
        for i, p in enumerate(projects):
            _job_progress(step="render", project=os.path.basename(p), n=f"{i + 1}/{len(projects)}")
            T = time.time()
            results += _render(p, out_dir, formats, timeout_s)["rendered"]
            steps[f"render {os.path.splitext(os.path.basename(p))[0]}"] = round(time.time() - T, 1)
        res = {"rendered": results, "seconds": round(time.time() - t0, 1), "steps_s": steps,
               "renders": _renders_here() - n0}
        return res
    finally:
        if closed and reopen and closed.get("project") and os.path.isfile(closed["project"]):
            _job_progress(step="reopen")
            T = time.time(); fl_open(closed["project"]); steps["reopen"] = round(time.time() - T, 1)


# ----------------------------------------------------------------------------- background jobs
# Remote bridges time out long calls (about 60 s), so long renders run in a thread and are polled with fl_job.
JOBS = {}
_JOB_EVENTS = {}                                                 # job id -> Event set when it finishes (kept on reload)
_JOB_LOCAL = threading.local()                                   # the job the current thread is running
_JOB_SEQ = [0, threading.Lock()]                                 # job number counter + its lock (kept on reload)


def _job_id(kind, reserve=None):
    """A new unique job id '<kind>-N' (a locked counter: two calls at once never get the same id). reserve: a dict
    put into JOBS under the id inside the same lock."""
    with _JOB_SEQ[1]:
        while True:
            _JOB_SEQ[0] += 1
            jid = f"{kind}-{_JOB_SEQ[0]}"
            if jid not in JOBS:
                break
        if reserve is not None:
            JOBS[jid] = dict(reserve, job=jid)
    return jid


NON_FL_JOBS = {"collab", "recipe", "handbook", "export_midi", "catalog", "index", "vocal_comp", "vocal_clean",
               "vocal_double", "transcribe", "comp"}               # job kinds that never drive FL
# kinds that drive FL only in some modes, when the caller doesn't say (fl=...): decided from the job's arguments
_JOB_FL_BY_ARGS = {
    "masking": lambda kw: bool(kw.get("live")),
    "refmatch": lambda kw: kw.get("mix") is None and bool(kw.get("live_seconds")),
    "mixeng": lambda kw: kw.get("measurements") is None and not kw.get("stems") and not kw.get("revert_last"),
    "vocal_balance": lambda kw: not (kw.get("vocal_wav") and kw.get("beat_wav")),
}


def _job_drives_fl(kind, fl=None, kw=None):
    """Does a job of this kind (with these arguments) drive FL? An explicit fl=True/False from the caller wins."""
    if fl is not None:
        return bool(fl)
    if kind in NON_FL_JOBS:
        return False
    rule = _JOB_FL_BY_ARGS.get(kind)
    if rule and kw is not None:
        try:
            return bool(rule(kw))
        except Exception:
            return True
    return True


def _start_job(kind, fn, /, *a, fl=None, **k):
    """Run fn in the background as job '<kind>-N'. fl=True: the job drives FL (renders, finalize, live listening,
    recording) and holds the FL lock while it runs, so no foreground FL tool or other job types into FL's dialogs
    meanwhile (those are refused with 'FL is busy (job ...)'); read-only / popup tools still work. fl=False: a
    file-only job (analysis of stems or files, packing, indexing) that never touches FL and never blocks it.
    fl=None (old callers): decided from the kind (NON_FL_JOBS) and, for mixed kinds, the keyword arguments."""
    jid = _job_id(kind, {"status": "running", "started": time.strftime("%H:%M:%S")})
    ev = _JOB_EVENTS[jid] = threading.Event()
    drives_fl = _job_drives_fl(kind, fl, k)
    JOBS[jid]["drives_fl"] = drives_fl
    parent = getattr(_JOB_LOCAL, "job", None)
    if drives_fl and parent and (JOBS.get(parent) or {}).get("drives_fl") and parent != jid:
        # inside a job that already holds FL (fl_pc_check, a recipe): run right here - a new thread would wait for
        # that job's own FL lock forever (PC 2026-10-21: the stems check hung)
        t0 = time.time(); JOBS[jid]["inside"] = parent
        try:
            res = fn(*a, **k)
            JOBS[jid].update(status="done", result=res)
            return res
        except Exception as e:
            JOBS[jid].update(status="failed", error=f"{type(e).__name__}: {e}")
            raise
        finally:
            JOBS[jid]["seconds"] = round(time.time() - t0, 1)
            ev.set()

    def run():
        t0 = time.time(); _JOB_LOCAL.job = jid; _JOB_LOCAL.t0 = t0; held = False
        try:
            if drives_fl:
                while not _FL_LOCK.acquire(timeout=1.0):           # wait for the FL step that started us
                    JOBS[jid]["progress"] = {"step": f"waiting for FL ({_fl_busy_with()})",
                                             "at": round(time.time() - t0, 1)}
                held = True; _FL_HOLDER["what"] = f"job {jid} (fl_job)"
            JOBS[jid].update(status="done", result=fn(*a, **k))
        except Exception as e:
            JOBS[jid].update(status="failed", error=f"{type(e).__name__}: {e}")
        finally:
            if held:
                _FL_HOLDER["what"] = None; _FL_LOCK.release()
            JOBS[jid]["seconds"] = round(time.time() - t0, 1); _JOB_LOCAL.job = None
            ev.set()
    threading.Thread(target=run, daemon=True).start()
    return {"job": jid, "status": "running", "note": "check with fl_job (it returns the moment the job finishes)"}


def _job_progress(**fields):
    """Inside a background job: show where it is (fl_job lists it live). No-op outside a job."""
    jid = getattr(_JOB_LOCAL, "job", None); t0 = getattr(_JOB_LOCAL, "t0", None)
    if not jid:                                                   # a long call handed over as a job
        jid, t0 = (globals().get("_OVERRUN_THREADS") or {}).get(threading.get_ident(), (None, None))
    if not jid or jid not in JOBS:
        return
    fields["at"] = round(time.time() - (t0 or time.time()), 1)
    JOBS[jid]["progress"] = fields


def _job_progress_get():
    """This job's current progress fields (a copy), or None outside a job / before any progress."""
    jid = getattr(_JOB_LOCAL, "job", None)
    if not jid:
        jid = ((globals().get("_OVERRUN_THREADS") or {}).get(threading.get_ident(), (None, None)))[0]
    pr = (JOBS.get(jid) or {}).get("progress") if jid else None
    return dict(pr) if isinstance(pr, dict) else None


JOB_WAIT_MAX_S = 40.0
JOB_WAIT_CLIENT_S = 55.0                                          # MCP clients give up on a call after ~60 s


def _job_wait_max():
    """fl_job's longest wait: JOB_WAIT_MAX_S times the speed factor (fewer polls on a slow PC), never past what MCP
    clients wait for one call."""
    return min(JOB_WAIT_CLIENT_S, max(JOB_WAIT_MAX_S, _scaled(JOB_WAIT_MAX_S)))


def _job_wait(jid, wait_s):
    ev = _JOB_EVENTS.get(jid)
    if ev is not None:
        ev.wait(max(0.0, float(wait_s)))
        return
    t0 = time.time()                                             # a job started by older code: poll
    while JOBS[jid].get("status") == "running" and time.time() - t0 < float(wait_s):
        time.sleep(0.2)


def fl_job(job=None, wait_s=40):
    """Status / result of a background job; waits up to wait_s and returns the moment it finishes.
    No job: the one running job (waited on) or a list of all with their progress."""
    if not job:
        running = [j for j, v in JOBS.items() if v.get("status") == "running"]
        if len(running) == 1 and float(wait_s or 0) > 0 and not running[0].startswith("verify-"):
            job = running[0]
        else:
            ver = [j for j, v in JOBS.items() if j.startswith("verify-") and v.get("status") != "running"]
            hide = set(ver[:-2])                                  # one check per edit: only the last two listed
            return [{k: v for k, v in j.items() if k not in ("result", "took_s")} for jid, j in JOBS.items()
                    if jid not in hide]
    if job not in JOBS:
        raise ValueError(f"no job {job}")
    JOBS[job].pop("took_s", None)
    if JOBS[job].get("status") == "running":                    # capped: MCP clients give up on a call after ~60 s
        _job_wait(job, min(float(wait_s or 0), _job_wait_max()))  # and calls queue behind a long wait
    r = dict(JOBS[job])                                          # a copy: the dispatcher adds took_s/ALERT to it
    if r.get("status") == "running":                             # when asking again is worth it (no busy polling)
        eta = (r.get("progress") or {}).get("eta_s")
        r["check_again_s"] = int(max(5, min(JOB_WAIT_MAX_S, eta))) if isinstance(eta, (int, float)) else int(JOB_WAIT_MAX_S)
    return r


# ============================================================================= FL settings (registry) and project info
REG_BASE = r"Software\Image-Line"                              # everything FL stores under HKEY_CURRENT_USER
SETTINGS_BACKUPS = os.path.join(os.path.dirname(STATE), "settings_backups")


def _reg():
    if os.name != "nt":
        raise RuntimeError("FL's settings live in the Windows registry; this only works on Windows")
    import winreg
    return winreg


def _reg_key(sub):
    sub = (sub or "").strip("\\")
    if ".." in sub.split("\\"):
        raise ValueError("bad key")
    return REG_BASE + ("\\" + sub if sub else "")


def _reg_dump(sub=""):
    """{relative key: {value name: [type, value]}} for the key and all subkeys (binary as hex)."""
    wr = _reg(); out = {}
    def walk(rel):
        try:
            k = wr.OpenKey(wr.HKEY_CURRENT_USER, _reg_key(rel))
        except OSError:
            return
        with k:
            vals = {}; i = 0
            while True:
                try:
                    name, val, typ = wr.EnumValue(k, i)
                except OSError:
                    break
                vals[name] = [typ, val.hex() if isinstance(val, bytes) else val]; i += 1
            out[rel] = vals; i = 0; subs = []
            while True:
                try:
                    subs.append(wr.EnumKey(k, i))
                except OSError:
                    break
                i += 1
        for s_ in subs:
            walk(rel + "\\" + s_ if rel else s_)
    walk(sub.strip("\\"))
    return out


TYPE_NAMES = {1: "text", 2: "text (expands %vars%)", 3: "binary", 4: "number", 7: "text list", 11: "number (64-bit)"}


def fl_settings(query="", key="", limit=200):
    """Read FL Studio's settings (Windows registry, HKEY_CURRENT_USER\\Software\\Image-Line). query filters on key,
    name or value text."""
    q = str(query).lower(); rows = []; total = 0
    for rel, vals in _reg_dump(key).items():
        for name, (typ, val) in vals.items():
            shown = val if typ != 3 else (val[:96] + ("…" if len(val) > 96 else ""))
            if q and q not in rel.lower() and q not in name.lower() and q not in str(val).lower():
                continue
            total += 1
            if len(rows) < int(limit):
                rows.append({"key": rel, "name": name, "type": TYPE_NAMES.get(typ, typ), "value": shown})
    return {"matches": total, "shown": len(rows), "settings": rows}


def _settings_backup(label="backup"):
    os.makedirs(SETTINGS_BACKUPS, exist_ok=True)
    path = os.path.join(SETTINGS_BACKUPS, time.strftime("%Y%m%d-%H%M%S-") + f"{int(time.time() * 1000) % 1000:03d}-" + "".join(c for c in label if c.isalnum() or c in "-_")[:40] + ".json")
    _json_write(path, _reg_dump())                               # temp file + replace: never half a snapshot
    olds = sorted(glob.glob(os.path.join(SETTINGS_BACKUPS, "*.json")))
    for f in olds[:-30]:
        os.remove(f)                                             # our own backup copies only
    return path


def _fl_key():
    keys = [k for k in _reg_dump_keys() if k.startswith("FL Studio ") and k[10:].isdigit()]
    if not keys:
        raise ValueError("no FL Studio settings found")
    return max(keys, key=lambda k: int(k[10:]))


def _reg_dump_keys():
    wr = _reg(); out = []
    with wr.OpenKey(wr.HKEY_CURRENT_USER, REG_BASE) as k:
        i = 0
        while True:
            try:
                out.append(wr.EnumKey(k, i)); i += 1
            except OSError:
                return out


def fl_settings_summary():
    """The settings that matter most, in plain words (for the installed FL version), with the key/name to change
    each one with fl_settings_set."""
    fk = _fl_key(); d = _reg_dump(fk)
    def g(sub, name):
        rel = fk + ("\\" + sub if sub else "")
        return {"value": d.get(rel, {}).get(name, [None, None])[1], "key": rel, "name": name}
    dev = fk + "\\Devices"
    mins = sorted(k.split("\\")[-1] for k in d if k.startswith(dev + "\\MIDI input\\"))
    mouts = sorted(k.split("\\")[-1] for k in d if k.startswith(dev + "\\MIDI output\\"))
    return {
        "fl_version_key": fk,
        "audio": {"device": g("Devices\\Audio output", "Device name"), "sample_rate": g("Devices\\Audio output", "Sample rate"),
                  "buffer_length": g("Devices\\Audio output", "Buffer length (DS)")},
        "midi_inputs": {m: {"enabled": g(f"Devices\\MIDI input\\{m}", "Enabled")["value"],
                            "port": g(f"Devices\\MIDI input\\{m}", "Port")["value"],
                            "script": g(f"Devices\\MIDI input\\{m}", "ScriptFolder")["value"]} for m in mins},
        "midi_outputs": {m: {"port": g(f"Devices\\MIDI output\\{m}", "Port")["value"]} for m in mouts},
        "autosave": g("General\\MIDIForm", "AutoSaveBox"),
        "autosave_list_max": g("General\\FruityLoopsMainForm", "AutoSaveListMax"),
        "last_backup": g("General", "LastSavedBackup")["value"],
        "run_counter": g("General", "Run counter")["value"],
        "note": "everything else: fl_settings(query=...); to find where a setting lives: fl_settings_snapshot, "
                "change it in FL and close FL, then fl_settings_diff",
    }


def fl_settings_snapshot(label="snapshot"):
    """Save all of FL's settings now (to compare with fl_settings_diff, or restore with fl_settings_restore)."""
    return {"snapshot": _settings_backup(label)}


def _latest_backup():
    olds = sorted(glob.glob(os.path.join(SETTINGS_BACKUPS, "*.json")))
    if not olds:
        raise ValueError("no settings snapshot yet")
    return olds[-1]


def fl_settings_diff(snapshot=None):
    """What changed in FL's settings since a snapshot (default: the newest). Change a setting in FL, then run this
    to see where FL keeps it."""
    path = snapshot or _latest_backup()
    old = json.load(open(path, encoding="utf-8")); new = _reg_dump(); out = []
    for rel in sorted(set(old) | set(new)):
        a, b = old.get(rel, {}), new.get(rel, {})
        for name in sorted(set(a) | set(b)):
            if a.get(name) != b.get(name):
                out.append({"key": rel, "name": name, "old": (a.get(name) or [None, None])[1],
                            "new": (b.get(name) or [None, None])[1]})
    return {"since": path, "changes": out}


def _reg_set(rel, name, value, typ):
    wr = _reg()
    if typ in (4, 11):
        value = int(value)
    elif typ == 3:
        value = bytes.fromhex(str(value).replace(" ", ""))
    elif typ == 7:
        value = list(value) if isinstance(value, (list, tuple)) else str(value).split("\n")
    else:
        value = str(value)
    with wr.OpenKey(wr.HKEY_CURRENT_USER, _reg_key(rel), 0, wr.KEY_SET_VALUE) as k:
        wr.SetValueEx(k, name, 0, typ, value)


def _restart_ok(restart_fl, close_fl, what):
    """Tools that need FL closed (FL rewrites its settings when it closes; MIDI scripts load at start) only close it
    when the caller explicitly says restart_fl=true (close_fl=true is the older spelling)."""
    if not fl_running():
        return False
    if restart_fl is True or close_fl is True:
        return True
    raise RuntimeError(f"FL is open: {what}. Nothing was changed. Call again with restart_fl=true to let fl-headless "
                       "save the project, close FL politely and reopen it - or close FL yourself first")


def fl_settings_set(changes, restart_fl=False, reopen=True, close_fl=None):
    """Change FL settings: changes = [{key, name, value}] (existing keys only; a new value needs "type": number |
    text | binary). FL rewrites its settings when it closes, so with FL running this needs restart_fl=true (FL is
    saved, closed politely and reopened). A snapshot of all settings is taken before anything is written."""
    current = _reg_dump(); plan = []
    for c in changes:
        rel = str(c["key"]).strip("\\"); name = str(c["name"])
        if rel not in current:
            raise ValueError(f"no settings key '{rel}' (new keys aren't created)")
        typ = current[rel].get(name, [None])[0]
        if typ is None:
            typ = {"number": 4, "text": 1, "binary": 3}.get(str(c.get("type", "")).lower())
            if typ is None:
                raise ValueError(f"'{rel}\\{name}' doesn't exist yet; give its type (number, text, binary)")
        plan.append((rel, name, c["value"], typ))
    closed = None
    if _restart_ok(restart_fl, close_fl, "it would overwrite the change when it closes"):
        closed = fl_close(save=True)
    snap = _settings_backup("before-change")
    try:
        for rel, name, value, typ in plan:
            _reg_set(rel, name, value, typ)
        after = _reg_dump()
        done = [{"key": rel, "name": name, "value": after[rel][name][1]} for rel, name, _, _ in plan]
    finally:
        if closed and reopen and closed.get("project") and os.path.isfile(closed["project"]):
            fl_open(closed["project"])
    return {"changed": done, "snapshot_before": snap, "reopened": bool(closed and reopen)}


def fl_settings_restore(snapshot=None, restart_fl=False, reopen=True, close_fl=None):
    """Put FL's settings back exactly as in a snapshot (default: the newest): values are restored, values added
    since are removed. A snapshot of the current state is taken first."""
    wr = _reg(); path = snapshot or _latest_backup()
    if os.path.normcase(os.path.dirname(os.path.abspath(path))) != os.path.normcase(SETTINGS_BACKUPS):
        raise ValueError("snapshot must come from the settings backup folder")
    old = json.load(open(path, encoding="utf-8"))
    closed = None
    if _restart_ok(restart_fl, close_fl, "it would overwrite the restored settings when it closes"):
        closed = fl_close(save=True)
    _settings_backup("before-restore")
    now = _reg_dump(); n = 0
    try:
        for rel, vals in old.items():
            if rel not in now:
                continue
            for name, (typ, val) in vals.items():
                if now[rel].get(name) != [typ, val]:
                    _reg_set(rel, name, val if typ != 3 else val, typ); n += 1
            for name in now[rel]:
                if name not in vals:
                    with wr.OpenKey(wr.HKEY_CURRENT_USER, _reg_key(rel), 0, wr.KEY_SET_VALUE) as k:
                        wr.DeleteValue(k, name); n += 1
    finally:
        if closed and reopen and closed.get("project") and os.path.isfile(closed["project"]):
            fl_open(closed["project"])
    return {"restored_from": path, "values_changed": n}


PROJECT_TEXT = {"title": 194, "comments": 195, "url": 197, "data_folder": 202, "genre": 206, "artist": 207}
PROJECT_BYTE = {"time_sig_num": 17, "time_sig_beat": 18, "show_info": 10}


def flp_project_info(path, output=None, **changes):
    """Read, or (with output) change, a project's info and project settings: title, artist, genre, comments, url,
    data_folder, time_sig_num, time_sig_beat, show_info (show the info on open), pitch (cents, -1200..1200)."""
    d = _load(path); ev = _events(d)
    first = {}
    for k, e in enumerate(ev):
        if e["id"] in set(PROJECT_TEXT.values()) | set(PROJECT_BYTE.values()) | {80} and e["id"] not in first:
            first[e["id"]] = k
        if e["id"] == EV_CHANNEL:
            break
    info = {n: _text16(_payload(d, ev[first[i]])) if i in first else "" for n, i in PROJECT_TEXT.items()}
    info.update({n: _payload(d, ev[first[i]])[0] if i in first else None for n, i in PROJECT_BYTE.items()})
    info["show_info"] = bool(info["show_info"]) if info["show_info"] is not None else None
    info["pitch"] = struct.unpack("<h", _payload(d, ev[first[80]]))[0] if 80 in first else None
    info["tempo_bpm"] = next((struct.unpack("<I", _payload(d, e))[0] / 1000 for e in ev if e["id"] == EV_TEMPO), None)
    if output is None:
        if changes:
            raise ValueError("give output= to save changes")
        return info
    writable(output)
    unknown = set(changes) - set(PROJECT_TEXT) - set(PROJECT_BYTE) - {"pitch"}
    if unknown:
        raise ValueError(f"unknown fields {sorted(unknown)}")
    edits = []; anchor = first.get(195, first.get(207))
    for n, v in changes.items():
        if v is None:
            continue
        if n in PROJECT_TEXT:
            eid = PROJECT_TEXT[n]; new = _data_event(eid, str(v).encode("utf-16-le") + b"\x00\x00")
            if eid in first:
                edits.append((first[eid], first[eid] + 1, new))
            elif anchor is not None:
                edits.append((anchor + 1, anchor + 1, new))
            else:
                raise ValueError(f"this project has no info section to add {n} to")
        elif n in PROJECT_BYTE:
            eid = PROJECT_BYTE[n]; val = int(bool(v)) if n == "show_info" else int(v)
            if n == "time_sig_num" and not 1 <= val <= 16 or n == "time_sig_beat" and val not in (2, 4, 8, 16):
                raise ValueError(f"bad {n}: {v}")
            if eid not in first:
                raise ValueError(f"this project has no {n} setting")
            edits.append((first[eid], first[eid] + 1, bytes([eid, val])))
        else:
            if 80 not in first:
                raise ValueError("this project has no pitch setting")
            edits.append((first[80], first[80] + 1, bytes([80]) + struct.pack("<h", max(-1200, min(1200, int(v))))))
    _save(_splice(d, ev, edits), output)
    return flp_project_info(output)


# ----------------------------------------------------------------------------- meter, new song from a project, pattern names
METER_NUMS, METER_DENS = range(1, 17), (2, 4, 8, 16)             # what FL's time-signature settings take


def _parse_meter(num, den=None):
    """'3/4', [3, 4], (3, 4) or num + den -> (num, den), checked against FL's ranges."""
    if den is None:
        if isinstance(num, str) and "/" in num:
            num, den = num.split("/", 1)
        elif isinstance(num, (list, tuple)) and len(num) == 2:
            num, den = num
        else:
            den = 4
    try:
        n, dd = int(str(num).strip()), int(str(den).strip())
    except (TypeError, ValueError):
        raise ValueError(f"time signature: like '3/4' or num=3, den=4 (got {num!r}/{den!r})") from None
    if n not in METER_NUMS or dd not in METER_DENS:
        raise ValueError(f"time signature {n}/{dd}: FL takes 1-16 beats over 2, 4, 8 or 16")
    return n, dd


def _midi_meters(path, P):
    """A MIDI file's time signatures (FF 58) as [(project tick, num, den)] at project PPQ P; [] when it has none."""
    try:
        with open(path, "rb") as f:
            div = struct.unpack(">H", f.read(14)[12:14])[0]
        ms = _midi_meter_drums(path)[0]
    except Exception:                                             # noqa: BLE001 - the notes reader says what's wrong
        return []
    if not div or div & 0x8000:
        return []
    return [(int(t) * P // div, n, dd) for t, n, dd in ms]


def _project_meter_bytes(d, num, den):
    """The project time signature (events 17/18 before the first channel) set to num/den; added after the project
    settings (event 80 pitch / 11 / 9) when the file has none. PC-VERIFY: a file whose 17/18 were added this way
    shows the time signature in FL (Song settings) and FL keeps it on save."""
    ev = _events(d); first = {}; stop = len(ev)
    sizes = {17: (1,), 18: (1,), 80: (2,), 11: (1,), 9: (1,)}
    for k, e in enumerate(ev):
        if e["id"] in (EV_CHANNEL, EV_PATTERN_NEW, EV_ARRANGEMENT):
            stop = k; break
        if e["id"] not in first and (e["id"] == EV_VERSION or e["len"] in sizes.get(e["id"], ())):
            first[e["id"]] = k
    edits = []
    for eid, val in ((17, num), (18, den)):
        if eid in first:
            edits.append((first[eid], first[eid] + 1, bytes([eid, int(val)])))
    missing = b"".join(bytes([eid, int(val)]) for eid, val in ((17, num), (18, den)) if eid not in first)
    if missing:
        at = next((first[i] + 1 for i in (80, 11, 9, EV_VERSION) if i in first), None)
        if at is None or at > stop:
            raise ValueError("couldn't find the project settings to put a time signature in")
        edits.append((at, at, missing))
    return _splice(d, ev, edits)


def _sig_markers(d, ev, a):
    """[(first event, end event, tick)] of the time-signature markers in arrangement a."""
    out = []
    if a is None:
        return out
    k, hi = a["first"] + 1, a["end"]
    while k < hi:
        e = ev[k]
        if e["id"] == EV_MARKER_POS and e["len"] == 4:
            v, = struct.unpack("<I", _payload(d, e)); j = _marker_group_end(ev, k, hi)
            if v & MARKER_SIGNATURE:
                out.append((k, j, v & 0x07FFFFFF))
            k = j
            continue
        k += 1
    return out


def _meter_marker_bytes(d, tick, num=None, den=None, name=None):
    """A time-signature marker at `tick` of the current arrangement: set (num/den; an existing one there gets the new
    values) or removed (num None). An arrangement without a playlist event gets an empty one first (markers go right
    after it, FL's place: _marker_slot). -> (bytes, "set" | "added" | "removed" | None)."""
    ev = _events(d); a = _arrangement(d, ev, None)
    if a is None:
        raise ValueError("this project has no arrangement (playlist) for a time-signature marker")
    hit = next((g for g in _sig_markers(d, ev, a) if g[2] == int(tick)), None)
    if num is None:
        return (_splice(d, ev, [(hit[0], hit[1], b"")]), "removed") if hit else (d, None)
    if hit:
        k, j, _ = hit; edits = []
        have = {ev[i]["id"]: i for i in range(k, j)}
        for eid, val in ((EV_MARKER_NUM, num), (EV_MARKER_DEN, den)):
            if eid in have:
                edits.append((have[eid], have[eid] + 1, bytes([eid, int(val) & 0xFF])))
        add = b"".join(bytes([eid, int(val) & 0xFF]) for eid, val in ((EV_MARKER_NUM, num), (EV_MARKER_DEN, den))
                       if eid not in have)
        if add:
            edits.append((k + 1, k + 1, add))
        return _splice(d, ev, edits), "set"
    if a.get("playlist") is None:                                 # PC-VERIFY: FL loads an arrangement whose
        j = a["first"] + 1                                        # playlist event is empty (no clips) + a marker
        while j < a["end"] and ev[j]["id"] in (241, 36):
            j += 1
        d = _splice(d, ev, [(j, j, _data_event(EV_PLAYLIST, b""))]); ev = _events(d); a = _arrangement(d, ev, None)
    slot = _marker_slot(d, ev, a)
    # PC-VERIFY: a time-signature marker written here shows on FL's playlist ruler at that bar with its meter, the
    # bars after it follow it, and FL's save keeps it (checklists/core.md 'flp_meter')
    return _splice(d, ev, [(slot, slot, _marker_event(int(tick), name or f"{num}/{den}", (num, den)))]), "added"


def _meter_map_write(d, mt):
    """Make the project's meter map `mt` [(tick, num, den)] (tick 0 first): the project time signature, a
    time-signature marker per later change; other time-signature markers of the current arrangement go.
    -> (bytes, what was done in words or None)."""
    ok, bad = [], []
    for t, n, dd in mt:
        try:
            ok.append((int(t),) + _parse_meter(n, dd))
        except ValueError:
            bad.append(f"{n}/{dd}")
    if not ok:
        return d, (f"time signature(s) {', '.join(bad)} can't be set in FL; kept the project's" if bad else None)
    clean = []
    for t, n, dd in sorted(ok):
        if clean and clean[-1][0] == t:
            clean[-1] = (t, n, dd)
        elif not clean or clean[-1][1:] != (n, dd):
            clean.append((t, n, dd))
    ev = _events(d)
    if clean[0][0] != 0:
        clean.insert(0, (0,) + _project_meter(d, ev))
    if _meter_map(d, ev) == clean:
        return d, None
    d = _project_meter_bytes(d, clean[0][1], clean[0][2])
    ev = _events(d); later = {t for t, _, _ in clean[1:]}
    old = [g for g in _sig_markers(d, ev, _arrangement(d, ev, None)) if g[2] and g[2] not in later]
    if old:                                                       # the template's other meter changes go
        d = _splice(d, ev, [(k, j, b"") for k, j, _ in old]); ev = _events(d)
    if any(g[2] == 0 for g in _sig_markers(d, ev, _arrangement(d, ev, None))):
        d, _ = _meter_marker_bytes(d, 0, *clean[0][1:])           # one at bar 1 would override the project's
    for t, n, dd in clean[1:]:
        d, _ = _meter_marker_bytes(d, t, n, dd)
    said = f"time signature {clean[0][1]}/{clean[0][2]}"
    if len(clean) > 1:
        said += f" + {len(clean) - 1} change(s) as time-signature markers ({', '.join(f'{n}/{dd}' for _, n, dd in clean[1:][:4])})"
    if bad:
        said += f"; left out {', '.join(bad)} (FL takes 1-16 over 2/4/8/16)"
    return d, said


def flp_meter(project, output=None, num=4, den=None, at_bar=1, remove=False, name=None):
    """Set the time signature: at_bar=1 = the project's own (FL's Song settings), a later bar = a time-signature
    marker there (FL's playlist ruler), which later bars follow; remove=True takes the marker at that bar out.
    num may be '3/4'. Positions are ticks in FL, so clips after a change stay where they are: the result says which
    ones no longer start on a bar line."""
    if output is None:                                            # in place: the open FL project saved/reloaded around
        return _with_open_project(project, project, lambda: flp_meter(project, project, num, den, at_bar, remove, name))
    writable(output)
    d = _load(project); ev = _events(d); P = _ppq(d); before = _meter_map(d, ev)
    if remove:
        n_ = dd = None
    else:
        n_, dd = _parse_meter(num, den)
    try:
        at = float(at_bar)
    except (TypeError, ValueError):
        raise ValueError(f"at_bar: a bar number (got {at_bar!r})") from None
    if at < 1 or abs(at - round(at)) > 1e-9:
        raise ValueError("at_bar: a whole bar, 1 or later (a time signature changes on a bar line)")
    tick = _bar_to_tick(at, before, P)
    if tick == 0:
        if remove:
            raise ValueError("bar 1 holds the project's time signature: set another one instead of removing it")
        d = _project_meter_bytes(d, n_, dd)
        if any(g[2] == 0 for g in _sig_markers(d, _events(d), _arrangement(d, _events(d), None))):
            d, _ = _meter_marker_bytes(d, 0, n_, dd)              # a marker at bar 1 would override the project's
        did = "project"
    else:
        d, did = _meter_marker_bytes(d, tick, n_, dd, name)
        if remove and did is None:
            raise ValueError(f"there's no time-signature marker at bar {at:g}")
    ev2 = _events(d); after = _meter_map(d, ev2)
    off = []
    for _, _, r in _clips(d, ev2):
        pos, = struct.unpack("<I", r[0:4])
        if pos > tick:
            b0, b1 = _tick_to_bar(pos, before, P, None), _tick_to_bar(pos, after, P, None)
            if abs(b0 - round(b0)) < 1e-6 and abs(b1 - round(b1)) > 1e-6:
                off.append(round(b1, 3))
    _save(d, output)
    res = {"output": output, "at_bar": at, "time_signature": None if remove else f"{n_}/{dd}",
           "written_as": {"project": "the project's time signature", "added": "a time-signature marker",
                          "set": "the time-signature marker there, changed", "removed": "marker removed"}[did],
           "meter_map": [{"bar": _tick_to_bar(t, after, P), "time_signature": f"{a}/{b}"} for t, a, b in after]}
    if off:
        res["clips_off_bar_lines"] = len(off)
        res["off_bar_line_bars"] = sorted(set(off))[:12]
        res["note"] = ("FL keeps clip positions in ticks: these clips after the change now start inside a bar - move "
                       "them (flp_playlist move) if they should start on one")
    return res


def _new_song_bytes(d, meter=None, tempo=None):
    """A project's bytes as a new, empty song: every pattern (notes, tempo lane, pattern markers), every playlist clip
    and marker of every arrangement go; channels, plugins, mixer and playlist track names stay; one empty 'Pattern 1'
    is made (FL's new-project shape, and what flp_write_notes fills). -> (bytes, {patterns, clips, markers})."""
    ev = _events(d)
    edits = [(a, b, b"") for _k, _pid, a, b in _pattern_groups(d, ev)]
    npat = len(_patterns(d, ev)); nclips = nmark = 0
    for a in _arrangements(d, ev):
        k = a["playlist"]
        if k is not None:                                         # FL leaves an empty arrangement without its 233
            p = _payload(d, ev[k]); nclips += len(p) // _clip_size(d, ev, p) if p else 0
            edits.append((k, k + 1, b""))
        j = a["first"] + 1
        while j < a["end"]:
            if ev[j]["id"] == EV_MARKER_POS and ev[j]["len"] == 4:
                e_ = _marker_group_end(ev, j, a["end"]); edits.append((j, e_, b"")); nmark += 1; j = e_
                continue
            j += 1
    d = _splice(d, ev, edits)
    d, pid = _add_pattern(d, "Pattern 1")
    ev = _events(d)
    for k, e in enumerate(ev):                                    # FL's current pattern: the new one
        if e["id"] in (EV_CHANNEL, EV_ARRANGEMENT):
            break
        if e["id"] == 67 and e["len"] == 2:
            d = _splice(d, ev, [(k, k + 1, bytes([67]) + struct.pack("<H", pid))])
            break
    if meter:
        d = _project_meter_bytes(d, *_parse_meter(meter))
    if tempo is not None:
        bpm = float(tempo)
        if not 10 <= bpm <= 522:
            raise ValueError(f"tempo {tempo} BPM is outside FL's range (10-522)")
        ev = _events(d)
        hits = [(k, k + 1, bytes([EV_TEMPO]) + struct.pack("<I", int(round(bpm * 1000)))) for k, e in enumerate(ev)
                if e["id"] == EV_TEMPO]
        if hits:
            d = _splice(d, ev, hits)
    return d, {"patterns": npat, "clips": nclips, "markers": nmark}


NEW_FROM_KEEP = ("channels+mixer",)


def flp_new_from(project, name, folder=None, keep="channels+mixer", meter=None, tempo=None, title=None):
    """A new song that reuses a project's sounds: the same channels (plugins and their settings), mixer and insert FX,
    with an EMPTY playlist - no clips, no patterns (one empty 'Pattern 1'), no markers, no tempo lane - and its own
    Project-info title. The source is never changed (edits queued for it and FL's unsaved changes of it are saved
    into it first, as flp_save_version). name: a song name (file <name>.flp in `folder`, default the source's) or a
    .flp path. meter '3/4' / tempo BPM set the new song's; default the source's."""
    src = os.path.abspath(project)
    if not os.path.isfile(src) or not src.lower().endswith(".flp"):
        raise FileNotFoundError(f"project: an existing .flp ({project})")
    if str(keep or "channels+mixer").strip().lower().replace(" ", "") not in NEW_FROM_KEEP:
        raise ValueError(f"keep: {' | '.join(NEW_FROM_KEEP)} (the sounds and the mixer; the song itself never)")
    nm = str(name or "").strip()
    if not nm:
        raise ValueError("name: the new song's name, e.g. 'Second Song' (or a .flp file name / path)")
    if nm.lower().endswith(".flp") or os.sep in nm or "/" in nm:
        dst = nm if os.path.isabs(nm) else os.path.join(folder or os.path.dirname(src), nm)
        dst = dst if dst.lower().endswith(".flp") else dst + ".flp"
    else:
        dst = os.path.join(folder or os.path.dirname(src), safe_file_name(nm, "song name") + ".flp")
    dst = os.path.abspath(dst)
    if os.path.normcase(dst) == os.path.normcase(src):
        raise ValueError("name: the new song needs another file than its source")
    if os.path.exists(dst):
        raise FileExistsError(f"{dst} exists already: pick another name (nothing was changed)")
    writable(dst)
    notes = []; T = time.time(); steps = {}
    try:                                                          # the source as it really is: queued edits in
        if _pending_get(src):
            _sync_before("new_from", src)
            notes.append("edits queued for the source were applied to it first")
    except Exception as e:                                        # noqa: BLE001 - said; the file on disk is used
        notes.append(f"queued edits of the source not applied first ({type(e).__name__}: {e})")
    try:                                                          # ... and FL's unsaved changes of it
        if fl_running() and _open_state(src) == "open" and _fl_changed_flag() not in (0, None) and not _stale_get(src):
            if _save_in_fl_and_wait(src, 8.0):
                notes.append("FL had unsaved changes of the source: saved first, so the new song has its sounds")
    except Exception:                                             # noqa: BLE001
        pass
    steps["source"] = round(time.time() - T, 2); T = time.time()
    with open(src, "rb") as f:
        d = f.read()
    d, info = _new_song_bytes(d, meter, tempo)
    song = os.path.splitext(os.path.basename(dst))[0]
    new_title = str(title).strip() if title is not None and str(title).strip() else song
    k, _t = _title_of_bytes(d)
    if k is not None:
        d = _splice(d, _events(d), [(k, k + 1, _data_event(PROJECT_TEXT["title"], new_title.encode("utf-16-le") + b"\x00\x00"))])
    _save(d, dst)
    if k is None:
        try:
            flp_project_info(dst, output=dst, title=new_title)
        except Exception as e:                                    # noqa: BLE001
            notes.append(f"title not set ({type(e).__name__}: {e})")
    steps["write"] = round(time.time() - T, 2)
    try:
        import flh_store
        flh_store.journal_update(dst, set={"song": song, "made_from": src,
                                           "notes": [f"new song made from {os.path.basename(src)}'s sounds and mixer "
                                                     f"({time.strftime('%Y-%m-%d')})"]})
    except Exception:                                             # noqa: BLE001 - the song is there either way
        pass
    dd = _load(dst); ev, chans, fx = _structure(dd)
    num, den = _project_meter(dd, ev)
    res = {"path": dst, "song": song, "title": new_title, "made_from": src,
           "kept": {"channels": len(chans), "mixer_effects": len(fx)},
           "left_out": info, "time_signature": f"{num}/{den}",
           "tempo_bpm": flp_project_info(dst).get("tempo_bpm"), "steps_s": steps,
           "next": "write the parts (flp_write_notes / flp_write_arrangement / flp_compose / sheet_import) into "
                   f"{song}.flp, then fl_open it; the source stays as it was"}
    if notes:
        res["notes"] = notes
    return res


def flp_patterns_set(project, output=None, patterns=None):
    """Rename / recolor patterns in the file (FL closed or not: the open project is saved and reloaded around it).
    patterns: [{"pattern": id or name, "name": "Verse", "color": "#3A4A5A"}, ...]."""
    if output is None:                                            # in place: the open FL project saved/reloaded around
        return _with_open_project(project, project, lambda: flp_patterns_set(project, project, patterns))
    writable(output)
    if not patterns:
        raise ValueError("patterns: [{pattern, name?, color?}, ...]")
    d = _load(project); ev = _events(d); pats = _patterns(d, ev)
    plan = {}
    for spec in patterns:
        if not isinstance(spec, dict) or spec.get("pattern") is None:
            raise ValueError("patterns: each {pattern: id or name, name?, color?}")
        want = spec["pattern"]
        if isinstance(want, str) and not want.strip().isdigit():
            hits = [p for p, v in pats.items() if v["name"].strip().lower() == want.strip().lower()]
            if not hits:
                raise ValueError(f"no pattern named '{want}' (flp_patterns lists them)")
            pid = hits[0]
        else:
            pid = int(want)
            if pid not in pats:
                raise ValueError(f"no pattern {pid}")
        if spec.get("name") is None and spec.get("color") is None:
            raise ValueError(f"pattern {want}: give name and/or color")
        plan.setdefault(pid, {}).update({k: v for k, v in spec.items() if k in ("name", "color") and v is not None})
    done = []
    for pid, sp in sorted(plan.items()):
        ev = _events(d)
        meta = next((g for g in _pattern_groups(d, ev) if g[1] == pid and g[0] in ("pattern_meta", "pattern")), None)
        name_ev = _data_event(EV_PATTERN_NAME, str(sp["name"]).encode("utf-16-le") + b"\x00\x00") if "name" in sp else b""
        col_ev = b""
        if "color" in sp:
            c = _hexcolor(sp["color"])
            col_ev = bytes([150, int(c[1:3], 16), int(c[3:5], 16), int(c[5:7], 16), 0])
        if meta is None:                                          # a pattern with notes but no name group yet
            j = _pattern_meta_anchor(d, ev)
            d = _splice(d, ev, [(j, j, struct.pack("<BH", EV_PATTERN_NEW, pid) + name_ev + col_ev)])
        else:
            _kind, _p, a, b = meta; edits = []
            kn = next((k for k in range(a + 1, b) if ev[k]["id"] == EV_PATTERN_NAME), None)
            kc = next((k for k in range(a + 1, b) if ev[k]["id"] == 150 and ev[k]["len"] == 4), None)
            if name_ev:
                edits.append((kn, kn + 1, name_ev) if kn is not None else (a + 1, a + 1, name_ev))
            if col_ev:
                if kc is not None:
                    edits.append((kc, kc + 1, col_ev))
                else:
                    at = (kn + 1) if kn is not None else a + 1
                    edits.append((at, at, col_ev))
            d = _splice(d, ev, edits)
        done.append({"pattern": pid, "was": pats[pid]["name"], **sp})
    _save(d, output)
    # PC-VERIFY: a pattern renamed / recolored here shows its new name and color in FL's pattern picker and on its
    # playlist clips after the reload
    return {"output": output, "patterns": done}


# ============================================================================= self-test (run after FL updates)
def _file_version(path):
    """'26.1.4.5589' from an exe's version resource (version.dll; no PowerShell, no localized text)."""
    import ctypes
    from ctypes import wintypes
    ver = ctypes.windll.version
    n = ver.GetFileVersionInfoSizeW(path, None)
    if not n:
        return None
    buf = ctypes.create_string_buffer(n)
    if not ver.GetFileVersionInfoW(path, 0, n, buf):
        return None
    p = ctypes.c_void_p(); ln = wintypes.UINT()
    ver.VerQueryValueW.argtypes = [ctypes.c_void_p, wintypes.LPCWSTR, ctypes.POINTER(ctypes.c_void_p),
                                   ctypes.POINTER(wintypes.UINT)]
    if not ver.VerQueryValueW(buf, "\\", ctypes.byref(p), ctypes.byref(ln)) or not p.value:
        return None
    ms, ls = struct.unpack("<II", ctypes.string_at(p.value + 8, 8))   # VS_FIXEDFILEINFO dwFileVersionMS / LS
    return f"{ms >> 16}.{ms & 0xFFFF}.{ls >> 16}.{ls & 0xFFFF}"


def _fl_file_version():
    if not IS_WINDOWS:
        return None
    exe = fl_exe()
    try:
        v = _file_version(exe)
        if v:
            return v
    except Exception:
        pass
    r = subprocess.run(["powershell", "-NoProfile", "-NonInteractive", "-Command",
                        "(Get-Item $env:FLH_TARGET).VersionInfo.FileVersion"], capture_output=True, text=True,
                       errors="replace", env=dict(os.environ, FLH_TARGET=exe), creationflags=NO_WINDOW)
    return r.stdout.strip() or None


def _single_pattern_template():
    best = None
    for r in roots():
        for f in glob.glob(os.path.join(r, "**", "*.flp"), recursive=True):
            if os.sep + "backup" + os.sep in os.path.normcase(f):
                continue
            try:
                d = _load(f); ev = _events(d); _notes_event(d, ev); _clip_event(d, ev)
            except Exception:
                continue
            if best is None or os.path.getmtime(f) > os.path.getmtime(best):
                best = f
    return best


def fl_selftest(template=None, close_fl=False, keep_files=False, max_projects=300):
    """Check fl-headless against the installed FL (run after every FL update): read every project, then build a
    canary song (notes + tempo map + an audio clip + a master-volume automation), render it with FL and measure
    that each part did what it should. Clear pass/fail per check."""
    import numpy as np
    import wave
    checks = []
    def check(name, ok, detail=""):
        checks.append({"check": name, "pass": bool(ok), "detail": detail})
    ver = _fl_file_version(); st = _state()
    check("FL version", True, f"{ver} (last passed: {st.get('selftest_passed_on', 'never')})")
    seen = bad = 0; bad_files = []
    for r in roots():
        for f in glob.glob(os.path.join(r, "**", "*.flp"), recursive=True):
            if seen >= int(max_projects):
                break
            seen += 1
            try:
                _events(_load(f))
            except Exception as e:
                bad += 1; bad_files.append(f"{os.path.basename(f)}: {e}")
    check("read every project", bad == 0, f"{seen - bad}/{seen} read" + (f"; failed: {bad_files[:5]}" if bad else ""))
    template = template or st.get("selftest_template") or _single_pattern_template()
    if not template:
        check("canary song", False, "no single-pattern project found to build from; pass template=")
        return {"pass": False, "checks": checks}
    work = tempfile.mkdtemp(prefix="flh_selftest_"); _TEMP_ROOTS.append(os.path.normcase(work))
    try:
        ch = next((c["index"] for c in flp_list(template)["channels"] if c.get("plugin")), 0)
        on = []
        for b in range(6):                                       # C major chord on every beat, bars 1-6
            for q in range(4):
                t = (b * 4 + q) * 96
                for k in (60, 64, 67):
                    on += [(t, bytes([0x90, k, 100])), (t + 90, bytes([0x80, k, 0]))]
        mid = os.path.join(work, "canary.mid")
        midi_write(mid, 96, [("tempo", [(0, b"\xff\x51\x03" + (500000).to_bytes(3, "big"))]), ("notes", on)])
        wav = os.path.join(work, "tone.wav"); fs = 44100
        tone = (0.5 * np.sin(2 * np.pi * 3000 * np.arange(fs) / fs) * 32767).astype("<i2")
        with wave.open(wav, "wb") as w:
            w.setnchannels(1); w.setsampwidth(2); w.setframerate(fs); w.writeframes(tone.tobytes())
        canary = os.path.join(work, "canary.flp")
        flp_write_notes(template, canary, [{"channel": ch, "midi": mid}], song_length=8)
        check("tempo map written", abs(flp_tempo_map(canary)["map"][0]["bpm"] - 120) < 0.01)
        flp_add_audio_clip(canary, canary, wav, bar=3)
        flp_add_automation(canary, canary, [{"bar": 5, "db": 0}, {"bar": 6, "value": 0.0}])
        info = flp_info(canary)
        check("canary readable", info.get("clips") == 3, f"{info.get('clips')} clips, notes {info.get('notes_per_channel')}")
        res = fl_render(canary, output_dir=work, formats="wav", close_fl=close_fl)
        x, rate, _ = _wav_load(res["rendered"][0]); m = x.mean(1)
        def rms(a, b):
            seg = m[int(a * rate):int(b * rate)]
            return 20 * np.log10(np.sqrt(np.mean(seg ** 2)) + 1e-12) if len(seg) else -240.0
        def band(a, b, f0=3000):
            seg = m[int(a * rate):int(b * rate)]
            S = np.abs(np.fft.rfft(seg * np.hanning(len(seg)))) ** 2; f = np.fft.rfftfreq(len(seg), 1 / rate)
            return 10 * np.log10(S[(f > f0 - 100) & (f < f0 + 100)].sum() / (S.sum() + 1e-20) + 1e-12)
        check("notes play", rms(0.2, 1.8) > -45, f"{rms(0.2, 1.8):.1f} dBFS in bar 1")
        lift = band(4.1, 4.9) - band(2.1, 2.9)
        check("audio clip plays at its bar", lift > 15, f"3 kHz tone +{lift:.1f} dB in bar 3")
        tail = rms(10.3, 11.8); before = rms(7.0, 8.0)
        check("automation fades the master", tail < -70 and before > -45,
              f"{before:.1f} dBFS before the fade, {tail:.1f} dBFS after it (notes still playing)")
    except Exception as e:
        check("canary song", False, f"{type(e).__name__}: {e}")
    finally:
        _TEMP_ROOTS.remove(os.path.normcase(work))
        if keep_files:
            checks.append({"check": "files kept", "pass": True, "detail": work})
        else:
            shutil.rmtree(work, ignore_errors=True)
    ok = all(c["pass"] for c in checks)
    if ok:
        _state({"selftest_passed_on": ver, "selftest_template": template})
    return {"pass": ok, "fl_version": ver, "template": template, "checks": checks}


# ============================================================================= live bridge (Windows MIDI)
# Frames: F0 7D 46 48 <dir 0=request 1=reply> <id lo> <id hi> <part> <parts> <payload> F7
# Request payload: "command;arg=type:value;..."  Reply payload: base64("OK"+repr | "ER"+message).
# Replies may arrive wrapped by a Flapi Response script (F0 7D 'Flapi' 01 ...), which is unwrapped here.
FRAME = bytes([0xF0, 0x7D, 0x46, 0x48])
FLAPI_RELAY = bytes([0xF0, 0x7D, 0x46, 0x6C, 0x61, 0x70, 0x69, 0x01])
LOOPBACK_PORT = "Default Basic App Loopback"                     # built into Windows 11 (Windows MIDI Services)


def _loopback_ports(p):
    """Single ports that loop back to themselves: Windows' basic app loopback first, then any port named *loopback*."""
    both = [n for n in p["midi_out"] if n in p["midi_in"]]
    return [n for n in both if n == LOOPBACK_PORT] + [n for n in both if "loopback" in n.lower() and n != LOOPBACK_PORT]
CHUNK = 384
MIDI_IN_BUFFERS = 512                                           # one per reply chunk in flight (2 MB of buffers)


def _parse_reply_frame(m, mid):
    """(part, parts, payload) of one reply SysEx for request `mid`, else None. Two framings: direction 1 = 7-bit part
    and count (bridge v3, up to 127 chunks); direction 3 = 14-bit part and count (bridge v4, for replies over 127
    chunks - a big project's state)."""
    if m[:4] != FRAME or len(m) < 10 or (m[5] | m[6] << 7) != mid:
        return None
    end = m.rfind(b"\xF7")
    if m[4] == 1:
        return m[7], m[8], m[9:end]
    if m[4] == 3 and len(m) >= 12:
        return m[7] | m[8] << 7, m[9] | m[10] << 7, m[11:end]
    return None


def _mailbox_dir():
    """Next to FL's own settings (Documents\\...\\FL Studio\\Settings\\fl-headless mailbox): FL and the server see the
    same real folder there even when Claude Desktop is a Store app (whose AppData writes Windows may redirect)."""
    try:
        d = os.path.join(os.path.dirname(_hardware_dir()), "fl-headless mailbox")
    except FileNotFoundError:
        d = os.path.join(os.environ.get("LOCALAPPDATA", os.path.expanduser("~")), "fl-headless", "mailbox")
    os.makedirs(d, exist_ok=True)
    return d


def _mailbox_alive(max_age=5.0):
    """True when the script inside FL wrote its heartbeat recently (FL open, script loaded with a mailbox)."""
    try:
        return time.time() - os.path.getmtime(os.path.join(_mailbox_dir(), "alive.json")) < max_age
    except OSError:
        return False


def _script_body(name_line=None):
    """The bridge script with this PC's mailbox folder filled in (and an optional '# name=' first line)."""
    src = os.path.join(os.path.dirname(os.path.abspath(__file__)), "fl_script", "device_flheadless.py")
    with open(src, encoding="utf-8") as f:
        text = f.read()
    # ascii(): a user name with accents / Cyrillic becomes \\u escapes, so the script stays pure ASCII for FL
    text = text.replace("MAILBOX = None", "MAILBOX = " + ascii(_mailbox_dir().replace("\\", "/")), 1)
    if name_line:
        lines = text.split("\n"); lines[0] = name_line; text = "\n".join(lines)
    return text


def _installed_scripts():
    """Every copy of the bridge script in FL's Hardware folders: [(path, first line)]."""
    out = []
    try:
        hw = _hardware_dir()
    except FileNotFoundError:
        return out
    for path in glob.glob(os.path.join(hw, "*", "device_*.py")):
        try:
            with open(path, encoding="utf-8", errors="replace") as f:
                head = f.read(4000)
        except OSError:
            continue
        if "fl-headless bridge" in head:
            out.append((path, head.split("\n", 1)[0]))
    return out


def _install_script(dest, name_line=None):
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    with open(dest + ".tmp", "w", encoding="utf-8", newline="\n") as f:
        f.write(_script_body(name_line))
    os.replace(dest + ".tmp", dest)


class _file_lock:
    """Cross-process lock on a file (Windows: msvcrt, elsewhere: fcntl)."""
    def __init__(self, path):
        self.path = path

    def __enter__(self):
        self.f = open(self.path, "a+")
        try:
            if os.name == "nt":
                import msvcrt
                for _ in range(600):                              # up to ~60 s
                    try:
                        self.f.seek(0); msvcrt.locking(self.f.fileno(), msvcrt.LK_NBLCK, 1); return self
                    except OSError:
                        time.sleep(0.1)
                raise TimeoutError("another fl-headless is using FL right now")
            import fcntl
            fcntl.flock(self.f.fileno(), fcntl.LOCK_EX)
            return self
        except BaseException:                                     # not locked: __exit__ won't run - close the handle
            self.f.close()
            raise

    def __exit__(self, *a):
        try:
            if os.name == "nt":
                import msvcrt
                self.f.seek(0); msvcrt.locking(self.f.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl
                fcntl.flock(self.f.fileno(), fcntl.LOCK_UN)
        finally:
            self.f.close()


def _retry_os(fn, tries=100, wait=0.01):
    """Windows: a file another process has open (FL reading it, an antivirus scan) can't be replaced or deleted for
    a moment - retry briefly."""
    for i in range(tries):
        try:
            return fn()
        except PermissionError:
            if i == tries - 1:
                raise
            time.sleep(wait)


OS_RETRY_TOTAL_S = 8.0            # a file FL (right after its load / save), OneDrive or an antivirus scan holds: a
                                  # replace is retried this long (backing off) before it fails


OS_RETRY_PER_MB_S = 1.5            # ... plus this per MB of the project (FL holds a big song longer: PC 2026-10-24
OS_RETRY_CAP_S = 45.0              # lazy.big_project's reload marker hit WinError 5 after 8 s), up to this


def _lock_wait_s(nbytes):
    """How long a project replace waits for FL / OneDrive / a scan to let go: longer for a big song, a slow PC."""
    try:
        s = OS_RETRY_TOTAL_S + OS_RETRY_PER_MB_S * max(0, int(nbytes)) / 1e6
        return min(OS_RETRY_CAP_S, _scaled(s))
    except Exception:                                             # noqa: BLE001
        return OS_RETRY_TOTAL_S


def _retry_os_long(fn, total_s=None):
    """_retry_os for replacing a project file: PermissionError (Windows: another process has the file open) is retried
    with a growing wait (20 ms .. 0.5 s) for up to total_s (default OS_RETRY_TOTAL_S) seconds in all."""
    total = OS_RETRY_TOTAL_S if total_s is None else float(total_s)
    t0 = time.time(); wait = 0.02
    while True:
        try:
            return fn()
        except PermissionError:
            if time.time() - t0 + wait > total:
                raise
            time.sleep(wait); wait = min(wait * 2.0, 0.5)


class _Bridge:
    _extended = False                                             # the last call waited past its deadline once

    def __init__(self):
        import uuid
        self.ok = False; self.seq = 1; self.lock = threading.RLock(); self.transport = None
        self.sid = uuid.uuid4().hex[:10]                         # mailbox ids never repeat across server runs

    def _setup(self):
        import ctypes
        from ctypes import wintypes as W
        self.c = ctypes; self.mm = mm = ctypes.WinDLL("winmm")

        class OUTCAPS(ctypes.Structure):
            _fields_ = [("wMid", W.WORD), ("wPid", W.WORD), ("ver", W.UINT), ("name", W.WCHAR * 32),
                        ("tech", W.WORD), ("voices", W.WORD), ("notes", W.WORD), ("mask", W.WORD), ("sup", W.DWORD)]

        class INCAPS(ctypes.Structure):
            _fields_ = [("wMid", W.WORD), ("wPid", W.WORD), ("ver", W.UINT), ("name", W.WCHAR * 32), ("sup", W.DWORD)]

        class MIDIHDR(ctypes.Structure):
            _fields_ = [("lpData", ctypes.c_void_p), ("len", W.DWORD), ("rec", W.DWORD), ("user", ctypes.c_size_t),
                        ("flags", W.DWORD), ("next", ctypes.c_void_p), ("res", ctypes.c_size_t), ("off", W.DWORD),
                        ("res2", ctypes.c_size_t * 8)]
        self.OUTCAPS, self.INCAPS, self.MIDIHDR = OUTCAPS, INCAPS, MIDIHDR
        H = ctypes.c_void_p
        sigs = {"midiOutGetNumDevs": [], "midiInGetNumDevs": [],
                "midiOutGetDevCapsW": [ctypes.c_size_t, ctypes.c_void_p, W.UINT],
                "midiInGetDevCapsW": [ctypes.c_size_t, ctypes.c_void_p, W.UINT],
                "midiOutOpen": [ctypes.POINTER(H), W.UINT, ctypes.c_size_t, ctypes.c_size_t, W.DWORD],
                "midiInOpen": [ctypes.POINTER(H), W.UINT, ctypes.c_size_t, ctypes.c_size_t, W.DWORD],
                "midiOutPrepareHeader": [H, ctypes.c_void_p, W.UINT], "midiOutUnprepareHeader": [H, ctypes.c_void_p, W.UINT],
                "midiOutLongMsg": [H, ctypes.c_void_p, W.UINT],
                "midiInPrepareHeader": [H, ctypes.c_void_p, W.UINT], "midiInUnprepareHeader": [H, ctypes.c_void_p, W.UINT],
                "midiInAddBuffer": [H, ctypes.c_void_p, W.UINT],
                "midiInStart": [H], "midiInStop": [H], "midiInReset": [H], "midiInClose": [H], "midiOutClose": [H]}
        for fn, args in sigs.items():
            f = getattr(mm, fn); f.argtypes = args; f.restype = W.UINT

    def ports(self):
        if not hasattr(self, "mm"):
            self._setup()
        outs, ins = [], []
        for i in range(self.mm.midiOutGetNumDevs()):
            c = self.OUTCAPS(); self.mm.midiOutGetDevCapsW(i, self.c.byref(c), self.c.sizeof(c)); outs.append(c.name)
        for i in range(self.mm.midiInGetNumDevs()):
            c = self.INCAPS(); self.mm.midiInGetDevCapsW(i, self.c.byref(c), self.c.sizeof(c)); ins.append(c.name)
        return {"midi_out": outs, "midi_in": ins}

    def choose(self, p=None):
        """Which ports to use: FLH_PORT_OUT/IN if set, else what fl_bridge_setup saved, else loopMIDI's Flapi pair,
        else a Windows loopback port (one port both ways: requests and replies tell themselves apart)."""
        p = p or self.ports()
        cands = []
        if os.environ.get("FLH_PORT_OUT") or os.environ.get("FLH_PORT_IN"):
            cands.append((os.environ.get("FLH_PORT_OUT", "Flapi Request"), os.environ.get("FLH_PORT_IN", "Flapi Response")))
        saved = _state().get("bridge_ports")
        if saved and len(saved) == 2:
            cands.append(tuple(saved))
        cands += [("Flapi Request", "Flapi Response")] + [(n, n) for n in _loopback_ports(p)]
        for o, i in cands:
            if o in p["midi_out"] and i in p["midi_in"]:
                return o, i
        return None

    def open(self):
        if self.ok:
            return
        p = self.ports(); c = self.c; mm = self.mm
        pick = self.choose(p)
        if not pick:
            raise RuntimeError("no bridge MIDI ports: on Windows 11 add the 'Default Basic App Loopback' (Windows MIDI "
                               "Services) and run fl_bridge_setup, or start loopMIDI with ports 'Flapi Request' / "
                               f"'Flapi Response'. Available: {p}")
        want_out, want_in = pick; self.ports_used = pick
        self._open_pair(p, want_out, want_in)

    def _open_pair(self, p, want_out, want_in):
        c, mm = self.c, self.mm
        self.hout, self.hin = c.c_void_p(), c.c_void_p()
        r = mm.midiOutOpen(c.byref(self.hout), p["midi_out"].index(want_out), 0, 0, 0)
        if r:
            raise RuntimeError(f"could not open MIDI out '{want_out}' (error {r}; is another program holding it?)")
        r = mm.midiInOpen(c.byref(self.hin), p["midi_in"].index(want_in), 0, 0, 0)
        if r:
            mm.midiOutClose(self.hout)
            raise RuntimeError(f"could not open MIDI in '{want_in}' (error {r}; is another program holding it?)")
        self.bufs = []
        for _ in range(MIDI_IN_BUFFERS):                         # big replies arrive as a burst of SysEx messages:
            mem = c.create_string_buffer(4096); h = self.MIDIHDR(); h.lpData = c.cast(mem, c.c_void_p); h.len = 4096
            mm.midiInPrepareHeader(self.hin, c.byref(h), c.sizeof(h)); mm.midiInAddBuffer(self.hin, c.byref(h), c.sizeof(h))
            self.bufs.append((mem, h))                           # one buffer each, or the tail is dropped
        mm.midiInStart(self.hin)
        self.ok = True

    def close(self):
        if not self.ok:
            return
        c, mm = self.c, self.mm
        mm.midiInStop(self.hin); mm.midiInReset(self.hin)
        for mem, h in self.bufs:
            mm.midiInUnprepareHeader(self.hin, c.byref(h), c.sizeof(h))
        mm.midiInClose(self.hin); mm.midiOutClose(self.hout); self.ok = False

    def _send(self, data):
        c, mm = self.c, self.mm
        mem = c.create_string_buffer(data, len(data)); h = self.MIDIHDR()
        h.lpData = c.cast(mem, c.c_void_p); h.len = len(data)
        mm.midiOutPrepareHeader(self.hout, c.byref(h), c.sizeof(h))
        r = mm.midiOutLongMsg(self.hout, c.byref(h), c.sizeof(h))
        t = time.time()
        while not h.flags & 1 and time.time() - t < 2:          # MHDR_DONE
            time.sleep(0.001)
        mm.midiOutUnprepareHeader(self.hout, c.byref(h), c.sizeof(h))
        if r:
            raise RuntimeError(f"MIDI send failed (error {r})")

    def _drain(self):
        c, mm, got = self.c, self.mm, []
        for mem, h in self.bufs:
            if h.flags & 1:
                got.append(mem.raw[:h.rec])
                mm.midiInUnprepareHeader(self.hin, c.byref(h), c.sizeof(h)); h.flags = 0; h.rec = 0
                mm.midiInPrepareHeader(self.hin, c.byref(h), c.sizeof(h)); mm.midiInAddBuffer(self.hin, c.byref(h), c.sizeof(h))
        return got

    @staticmethod
    def encode(cmd, args):
        import base64
        parts = [cmd]
        for k, v in args.items():
            if v is None:
                continue
            if isinstance(v, bool):
                t = "b:" + ("1" if v else "0")
            elif isinstance(v, int):
                t = f"i:{v}"
            elif isinstance(v, float):
                t = f"f:{v!r}"
            else:
                t = "s:" + base64.b64encode(str(v).encode("utf-8")).decode("ascii")
            parts.append(f"{k}={t}")
        return ";".join(parts).encode("ascii")

    def call(self, cmd, timeout=15.0, **args):
        if cmd == "transport" and args.get("action") == "save" and _STALE_FL:
            blocked = _stale_block()                             # every save, also extensions': never FL's older copy
            # PC-VERIFY: after a failed reload, fl_save / a check / flh_sync leave the .flp's mtime unchanged
            if blocked:                                          # over a file with newer edits (a reload failed)
                raise RuntimeError(blocked)
        base = float(timeout)
        timeout = _scaled(base)                                   # a slow PC gets its speed factor's worth longer
        extra = _speed_extra(base, timeout)                       # ... and once more while FL is visibly busy
        if not getattr(_JOB_LOCAL, "job", None) and timeout + extra > max(base, BRIDGE_FOREGROUND_CAP_S):
            cap = max(base, BRIDGE_FOREGROUND_CAP_S)              # a tool call answers before the client gives up
            timeout = min(timeout, cap); extra = max(0.0, cap - timeout)
        with self.lock:                                          # one request at a time (background helpers call too)
            self._extended = False; t0 = time.time()
            try:
                # FL busy (loading, a popup) pauses its idle loop and the heartbeat: stay on the mailbox while FL runs
                if _mailbox_alive() or (_mailbox_alive(max_age=600) and fl_running()):
                    r = self._call_mailbox(cmd, timeout, args, extra)
                else:
                    r = self._call_midi(cmd, timeout, args, extra)
            except TimeoutError as e:
                if base >= SPEED_MIN_SCALED_S:
                    raise TimeoutError(f"{e}{_slow_why(base, time.time() - t0, self._extended)}") from None
                raise
            took = time.time() - t0
            extended = self._extended
        if cmd == "ping":
            _speed_observe_ping(took * 1000.0)
        _speed_observe_late(f"FL's reply to '{cmd}'", base, took, extended)
        return r

    def _wait_deadline(self, t0, timeout, extra):
        """Past the deadline: extend once by `extra` while FL is visibly still working; False = give up."""
        if extra > 0 and not self._extended and _fl_still_working():
            self._extended = True
            return t0 + timeout + extra
        return None

    def _call_mailbox(self, cmd, timeout, args, extra=0.0):
        """Request/reply through the script's mailbox files (no MIDI traffic at all). Ids are unique per server
        process, requests carry an expiry (FL drops ones the server gave up on) and are removed once answered,
        and a lock file keeps two server processes (two Claude windows) from crossing replies."""
        mb = _mailbox_dir(); mid = f"{self.sid}-{self.seq}"; self.seq += 1
        req = os.path.join(mb, "req.json"); resp = os.path.join(mb, "resp.json")
        tmp = f"{req}.{os.getpid()}.tmp"
        with _file_lock(os.path.join(mb, "lock")):
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump({"id": mid, "until": time.time() + float(timeout) + float(extra),
                           "payload": self.encode(cmd, args).decode("ascii")}, f)
            _retry_os(lambda: os.replace(tmp, req))             # atomic; FL may hold the old file open a moment
            self.transport = "mailbox"; t0 = time.time(); deadline = t0 + timeout
            try:
                while True:
                    if time.time() >= deadline:
                        deadline = self._wait_deadline(t0, timeout, extra)
                        if deadline is None:
                            break
                    try:
                        with open(resp, encoding="utf-8") as f:
                            got = json.load(f)
                        if got.get("id") == mid:
                            return self._reply(got.get("reply", ""))
                    except (OSError, ValueError):                # not there yet / mid-write
                        pass
                    time.sleep(0.004)
            finally:
                try:
                    _retry_os(lambda: os.remove(req), tries=20)
                except OSError:
                    pass
        raise TimeoutError(f"no reply from FL within {timeout}s (mailbox). Is FL busy or a popup open (fl_dialog)?")

    @staticmethod
    def _reply(text):
        import ast
        kind, body = text[:2], text[2:]
        # a fader at zero reads -inf in FL; literal_eval can't parse inf/nan, so map them first (older scripts) -
        # outside string literals only ('Pad inf' stays a name)
        parts = re.split(r"""('(?:[^'\\]|\\.)*'|"(?:[^"\\]|\\.)*")""", body)
        for i in range(0, len(parts), 2):
            seg = re.sub(r"(?<![\w.])-inf\b", "-1e999", parts[i])
            seg = re.sub(r"(?<![\w.-])inf\b", "1e999", seg)
            parts[i] = re.sub(r"(?<![\w.])nan\b", "None", seg)
        body = "".join(parts)
        try:
            val = ast.literal_eval(body)                         # literals only, never code
        except (ValueError, SyntaxError):
            val = body
        if kind == "ER":
            raise RuntimeError(f"FL: {val}")
        return val

    def _call_midi(self, cmd, timeout, args, extra=0.0):
        import base64
        self.open(); self.transport = "midi"
        mid = self.seq & 0x3FFF; self.seq += 1
        data = self.encode(cmd, args)
        chunks = [data[i:i + CHUNK] for i in range(0, len(data), CHUNK)] or [b""]
        if len(chunks) > 127:
            raise ValueError("request too large")
        self._drain()
        for n, ch in enumerate(chunks):
            frame = FRAME + bytes([0, mid & 0x7F, mid >> 7, n, len(chunks)]) + ch + b"\xF7"
            try:
                self._send(frame)
            except RuntimeError:                                  # ports went away (loopMIDI restarted): reconnect once
                try:
                    self.close()
                except Exception:
                    self.ok = False
                self.open(); self._send(frame)
        parts, total, t0 = {}, None, time.time(); deadline = t0 + timeout
        while True:
            if time.time() >= deadline:
                deadline = self._wait_deadline(t0, timeout, extra)
                if deadline is None:
                    break
            for m in self._drain():
                if m[:len(FLAPI_RELAY)] == FLAPI_RELAY:
                    m = bytes([0xF0, 0x7D]) + m[len(FLAPI_RELAY):]
                got = _parse_reply_frame(m, mid)
                if got:
                    parts[got[0]] = got[2]; total = got[1]
            if total is not None and len(parts) == total:
                return self._reply(base64.b64decode(b"".join(parts[i] for i in range(total))).decode("utf-8"))
            time.sleep(0.005)
        raise TimeoutError(f"no reply from FL within {timeout}s. Is FL open with the fl-headless script on the "
                           "request port (Options > MIDI settings)?")


BRIDGE = _Bridge()


def _num(v, kind):
    return None if v is None else kind(v)


def fl_ports():
    return BRIDGE.ports()


def _script_version_shipped():
    """SCRIPT_VERSION of the bridge script next to the server (what update_script installs)."""
    try:
        src = os.path.join(os.path.dirname(os.path.abspath(__file__)), "fl_script", "device_flheadless.py")
        with open(src, encoding="utf-8") as f:
            m_ = re.search(r"^SCRIPT_VERSION = (\d+)", f.read(), re.M)
        return int(m_.group(1)) if m_ else None
    except OSError:
        return None


def _script_note(r):
    """Add 'script_outdated' to a ping reply when FL runs an older bridge script than the one shipped."""
    if isinstance(r, dict):
        have, ship = r.get("version"), _script_version_shipped()
        if ship and (have is None or int(have) < ship):
            r["script_outdated"] = (f"FL runs bridge script v{have or '1-2'}, this fl-headless ships v{ship}: run "
                                    "fl_bridge_setup(action='update_script') and restart FL (new commands: send "
                                    "levels, plugin_probe, mixer_info/arm/peaks, rec_setup, countdown, loop_record, "
                                    "pattern_new; v6: plugin_get; v7: volumes set by FL's exact fader curve in one "
                                    "step - the older scripts' search runs FL 2026's faders to an end, so volume sets "
                                    "are refused until it's updated - and FL's 'Current' mixer track refused)")
    return r


def fl_ping():
    try:
        return _script_note(BRIDGE.call("ping", timeout=5))
    except TimeoutError:                                         # first ping after a restart is often cold
        return _script_note(BRIDGE.call("ping", timeout=10))


def _note_script_location():
    """Ask the script in FL where FL loaded it from (proof of which user data folder FL uses) and remember it.
    Returns the path or None (older script / FL without __file__)."""
    try:
        f = (BRIDGE.call("where", timeout=3.0) or {}).get("file")
    except Exception:
        return None
    if f:
        try:
            if (_state().get("fl_script_file") or {}).get("path") != f:
                _DOCS_CACHE.pop("userdata_pick", None)
            _state({"fl_script_file": {"path": f, "t": int(time.time())}})
        except Exception:
            pass
    return f


def fl_state():
    return BRIDGE.call("state")


def fl_transport(action):
    if str(action) in ("play", "record"):
        _sync_before("fl_transport " + str(action))
    return BRIDGE.call("transport", action=str(action))


def fl_set_tempo(bpm):
    return BRIDGE.call("set_tempo", bpm=float(bpm))


def _hexcolor(c):
    if c is None:
        return None
    c = str(c).strip()
    named = {"red": "#E05050", "orange": "#E0903A", "yellow": "#D8C040", "green": "#5CB85C", "teal": "#3AB0A0",
             "blue": "#4A80D8", "purple": "#8A5CD0", "pink": "#D060A0", "gray": "#808080", "grey": "#808080",
             "white": "#E8E8E8"}
    c = named.get(c.lower(), c)
    if not (c.startswith("#") and len(c) == 7 and all(x in "0123456789abcdefABCDEF" for x in c[1:])):
        raise ValueError(f"color must be '#RRGGBB' or one of {', '.join(named)}")
    return c.upper()


OLD_SCRIPT_VOL = ("FL runs an older bridge script, which sets a volume by searching over FL's own read-back - on FL 2026 "
                  "that read-back lags the set and the search runs the fader to an end (silent, or +5.6 dB). Nothing "
                  "was changed. Update it: fl_bridge_setup(action='update_script'), then restart FL")


def _old_script(e):
    """Is this bridge error an older script refusing the v7 'volume' argument?"""
    s = str(e)
    return "unexpected keyword argument" in s and "volume" in s


def _bridge_vol(cmd, **kw):
    try:
        return BRIDGE.call(cmd, **kw)
    except RuntimeError as e:
        if _old_script(e):
            raise RuntimeError(f"NOT set: {OLD_SCRIPT_VOL}") from None
        raise


def fl_channel_set(index, volume_db=None, pan=None, muted=None, name=None, color=None, solo=None, select=None,
                   mixer_track=None):
    """Live channel settings. volume_db is on FL's channel scale: 0 dB = the knob at its top, FL's default (78 %) is
    -5.18 dB. Set by FL's curve in one step and read back in a later call; mixer_track must be an existing insert
    (FL's 'Current' track - the last one - is refused) and is checked after the set. Never reports a value FL
    didn't keep."""
    i = int(index)
    want = _num(volume_db, float)
    vol = None if want is None else _chan_vol(want)
    r = _bridge_vol("channel_set", index=i, volume=vol, pan=_num(pan, float), muted=_num(muted, bool), name=name,
                    color=_hexcolor(color), solo=_num(solo, bool), select=_num(select, bool),
                    mixer_track=_num(mixer_track, int))
    problems = []
    if isinstance(r, dict) and r.get("insert_not_set"):
        problems.append(f"the mixer track: {r['insert_not_set']}")
    if vol is not None:
        ok, why, now, last = _vol_verify(lambda: BRIDGE.call("channel_set", index=i, timeout=5.0), vol, r,
                                         resend=lambda: BRIDGE.call("channel_set", index=i, volume=vol), db=_chan_db)
        r = dict(last if isinstance(last, dict) else r, volume=now, default_db=round(_chan_db(CHAN_DEFAULT), 2),
                 volume_db=None if now is None else round(_chan_db(now), 2), volume_held=ok)
        if not ok:
            problems.append(f"the volume didn't take {want:g} dB: {why}")
    if problems:
        others = [k for k, v in (("pan", pan), ("muted", muted), ("name", name), ("color", color), ("solo", solo),
                                 ("select", select)) if v is not None]
        raise RuntimeError(f"NOT set: channel {i}: " + "; ".join(problems)
                           + (f" (the other settings - {', '.join(others)} - were applied)" if others else "")
                           + f". Now: volume {r.get('volume_db')} dB, insert {r.get('insert')}")
    return r


def _send_levels_arg(send_levels=None, send_db=None):
    """{dst: level 0..1} and/or {dst: dB} -> the bridge's '3:0.8,5:0.62' (0.8 = 0 dB; dB uses the fader curve,
    PC-VERIFY that send knobs follow the same curve as faders)."""
    items = []
    for src, conv in ((send_levels, float), (send_db, lambda x: _fader(float(x)))):
        if not src:
            continue
        pairs = src.items() if isinstance(src, dict) else src
        for dst, v in pairs:
            items.append(f"{int(dst)}:{max(0.0, min(1.0, conv(v))):.6f}")
    return ",".join(items) or None


# ---- live sets that must hold: automation clips override faders / knobs (PC 2026-10-23)
MIX_MOVE_TOL_DB = 1.5             # a mix move (fl_mix_engineer / fl_mix_apply) landing further off is undone
MASTER_FLOOR_DB = -12.0           # a mix move never takes the master fader below this
FADER_TOP_DB = 5.6                # FL's fader at its top
SET_VERIFY_S = 0.4                # wait before reading a live set back again (FL applies some sets after the callback)
IF_AUTOMATED = ("report", "scale_clip", "insert_gain", "fader")


def _numf(v):
    """float(v), or None when it isn't a number (None, text, nan). FL's bridge sends a fader at zero (-inf) as None."""
    try:
        f = float(v)
    except (TypeError, ValueError):
        return None
    return None if f != f else f


def _automation_links(project):
    """{(link parameter id, destination): [{channel, name, placed, kind}]} of what drives parameters in `project`:
    automation clips (placed = an unmuted clip of it is in the playlist) and other controller channels (event 227
    remote links; the same decoding as flp_remove_channels / fl_doctor). {} when the file can't be read."""
    try:
        d = _load(project); ev = _events(d)
    except Exception:
        return {}
    names = _clip_names(d, ev)
    try:
        allnames = _channel_display_names(d)
    except Exception:
        allnames = {}
    placed = set()
    try:
        for _k, _o, r in _clips(d, ev):
            item = struct.unpack("<H", r[6:8])[0]
            if item < PATTERN_BASE and not struct.unpack("<H", r[18:20])[0] & CLIP_MUTE:
                placed.add(item)
    except Exception:
        pass
    out = {}
    for e in ev:
        if e["id"] == EV_REMOTE_LINK and e["len"] >= 12:
            p = _payload(d, e)
            ch = struct.unpack("<H", p[2:4])[0]; pid, dest = struct.unpack("<HH", p[8:12])
            kind, nm = names.get(ch, (None, None))
            if kind == "audio":
                continue
            out.setdefault((pid, dest), []).append({
                "channel": ch, "name": nm or allnames.get(ch) or f"Channel {ch}",
                "kind": "automation clip" if kind == "automation" else "controller",
                "placed": (ch in placed) if kind == "automation" else True})
    return out


def _driven_by(target, project=None):
    """Automation clips / controllers in the open project's file that drive `target`: ("mixer_volume", track) or
    ("plugin", index, slot, param) (slot -1 = a channel's instrument). Placed clips first. [] when none / unknown.
    PC-VERIFY: a project whose mixer track volume is automated by a clip ('Strings fade') lists it here."""
    if project is None:
        try:
            project = _open_project_guess()[0]
        except Exception:
            project = None
    if not project or not os.path.isfile(project):
        return []
    if target[0] == "mixer_volume":
        key = (MIX_LINK["volume"], 0x7000 + (int(target[1]) << 6))
    else:
        _k, idx, slot, prm = target
        key = (0x8000 | int(prm), int(idx) if int(slot) < 0 else 0x7000 + (int(idx) << 6) + int(slot))
    got = _automation_links(project).get(key) or []
    return sorted(got, key=lambda c: (not c["placed"], c["channel"]))


VOL_TOL_NORM = 0.0015             # a fader / knob position counts as held within this (FL stores 1/16000 steps)
FL_DB_DIFF_DB = 0.5               # FL's own dB read-back further than this from the curve: said in the reply


def _vol_why(now, set_to, before, db=None, moved=None):
    db = db or _fader_db
    if now is None:
        return "FL's read-back isn't a number"
    if moved is not None and abs(moved - set_to) <= VOL_TOL_NORM:
        return (f"it took {db(set_to):.2f} dB, then read {db(now):.2f}: something moves it back (an automation clip "
                "or a controller)")
    if before is not None and abs(now - before) <= VOL_TOL_NORM and abs(before - set_to) > VOL_TOL_NORM:
        return (f"FL didn't move it (it stays at {db(now):.2f} dB): an automation clip or a controller holds it, or FL "
                "ignored the script's set")
    return (f"it reads {db(now):.2f} dB, not {db(set_to):.2f}: something moves it (an automation clip or a "
            "controller)")


def _vol_verify(read, set_to, reply, verify=True, resend=None, db=None):
    """Did a volume set to the 0..1 position `set_to` hold? The position is computed by FL's curve and set once (the
    bridge never searches). FL 2026 applies a mixer set AFTER the bridge's callback, so the set's own reply may still
    show the old value: read() (a NEW bridge call) after SET_VERIFY_S; when it doesn't match, the computed position
    is sent once more (resend) and read again - never a search, never an end of the fader nobody asked for.
    -> (ok, why, position now, the last reply)"""
    fit = (reply.get("volume_fit") if isinstance(reply, dict) else None) or {}
    before = _numf(fit.get("before"))
    now = _numf(reply.get("volume")) if isinstance(reply, dict) else None
    moved = _numf(fit.get("read_now"))
    last = reply
    if not verify:
        ok = now is not None and abs(now - set_to) <= VOL_TOL_NORM
        return ok, None if ok else _vol_why(now, set_to, before, db), now, last
    for k in range(3):
        time.sleep(SET_VERIFY_S * (2 if k == 2 else 1))
        try:
            last = read()
        except Exception as e:                                    # noqa: BLE001
            return False, f"couldn't read it back ({type(e).__name__}: {e})", now, last
        now = _numf(last.get("volume")) if isinstance(last, dict) else None
        if now is not None and abs(now - set_to) <= VOL_TOL_NORM:
            return True, None, now, last
        if k == 0 and resend is not None:
            try:
                resend()
            except Exception:                                     # noqa: BLE001 - the reads decide
                pass
    return False, _vol_why(now, set_to, before, db, moved), now, last


def _fader_read(track, timeout=5.0):
    """(position 0..1, dB on FL's curve, reply) of mixer `track` from a fresh bridge call. An older script (no
    'volume' in its reply): its dB read-back (FL 2026's can be wrong) -> position by the curve."""
    r = BRIDGE.call("mixer_set", track=int(track), timeout=timeout)
    if isinstance(r, dict) and "volume" in r:
        v = _numf(r.get("volume"))
        return v, (None if v is None else round(_fader_db(v), 2)), r
    d = _numf((r or {}).get("volume_db")) if isinstance(r, dict) else None
    return (None if d is None else _fader(d)), d, r


def _fl_db_note(reply, db_now):
    fl = _numf(reply.get("fl_db")) if isinstance(reply, dict) else None
    if fl is None or db_now is None or abs(fl - db_now) <= FL_DB_DIFF_DB:
        return None
    # PC-VERIFY: on FL 2026 getTrackVolume(t, 1) agrees with the position's dB a moment after a set
    return (f"FL's own dB read-back says {fl:g} dB; the fader's position ({reply.get('volume')}) is {db_now:g} dB on "
            "FL's fader curve - the position is what plays")


def _fader_apply(track, want_db, verify=True):
    """Set mixer `track`'s fader to `want_db` (FL's exact curve, one set) and check it held in a later read.
    -> {ok, want_db, db (reads now), volume, set_to, before (0..1 before the set), why, fl_db_note}"""
    t = int(track); want = min(float(want_db), FADER_TOP_DB); v = _fader(want)
    r = _bridge_vol("mixer_set", track=t, volume=v)
    ok, why, now, last = _vol_verify(lambda: BRIDGE.call("mixer_set", track=t, timeout=5.0), v, r, verify,
                                     resend=lambda: BRIDGE.call("mixer_set", track=t, volume=v))
    dbn = None if now is None else round(_fader_db(now), 2)
    out = {"ok": ok, "want_db": round(want, 2), "db": dbn, "volume": now, "set_to": round(v, 6),
           "before": _numf(((r or {}).get("volume_fit") or {}).get("before")), "why": why}
    note = _fl_db_note(last, dbn)
    if note:
        out["fl_db_note"] = note
    return out


def _fader_restore(track, pos):
    """Put a fader back at its 0..1 position from before a move (one set; checked by the caller if it matters)."""
    if pos is None:
        return None
    return _bridge_vol("mixer_set", track=int(track), volume=max(0.0, min(1.0, float(pos))))


def _automated_msg(what, clips, fixes):
    c = clips[0]
    more = f" (and {len(clips) - 1} more: {', '.join(repr(x['name']) for x in clips[1:4])})" if len(clips) > 1 else ""
    return (f"{what} follows the {c['kind']} '{c['name']}' (channel {c['channel']}){more}: FL's automation overrides a "
            f"live set. " + fixes)


def _vol_fixes(track, want, now, clips):
    t = int(track)
    opts = []
    if any(c["kind"] == "automation clip" for c in clips):
        opts.append(f"scale the clip: fl_mixer_set(track={t}, volume_db={want:g}, if_automated='scale_clip') "
                    "(moves every point of the clip by the difference, in dB)")
    opts.append(f"or put the change on an insert gain: fl_mixer_set(track={t}, volume_db={want:g}, "
                "if_automated='insert_gain') (Fruity Parametric EQ 2 'Main level' on that track, added if missing)")
    if clips and not any(c["placed"] for c in clips):
        opts.append(f"(the clip isn't in the playlist, so if_automated='fader' may still work)")
    return "; ".join(opts)


def _vol_delta(want, now, clips, project):
    """dB to move by: the asked level minus what the fader reads now (where the playhead is), else minus the clip's
    loudest point. -> (delta, from what)."""
    if now is not None:
        return round(float(want) - float(now), 2), f"the fader reads {now:g} dB now"
    try:
        d = _load(project); ev = _events(d); k = _automation_events(d, ev).get(clips[0]["channel"])
        top = max(v for _b, v, *_ in _auto_points(_payload(d, ev[k]))[0])
        return round(float(want) - _fader_db(top), 2), f"the clip's loudest point is {_fader_db(top):.2f} dB"
    except Exception:
        return None, None


def _vol_alternative(track, want, now, clips, how):
    """if_automated='scale_clip' / 'insert_gain': the level change made where it holds."""
    project = _open_project_guess()[0]
    delta, basis = _vol_delta(want, now, clips, project) if clips else (
        (round(float(want) - float(now), 2), f"the fader reads {now:g} dB now") if now is not None else (None, None))
    if delta is None:
        raise RuntimeError(f"can't tell how far to move mixer track {track}: the fader's level can't be read and no "
                           "automation clip was found; set the level by hand")
    if how == "scale_clip":
        auto = [c for c in clips if c["kind"] == "automation clip"]
        if not auto:
            raise RuntimeError(f"no automation clip drives mixer track {track}'s volume in the saved file; use "
                               "if_automated='insert_gain'")
        fn = globals().get("flp_scale_automation")
        if fn is None:
            raise RuntimeError("flp_scale_automation isn't loaded (flh_mixeng)")
        r = fn(project, project, [c["channel"] for c in auto], db=delta)
        return {"track": int(track), "volume_via": "automation clip scaled", "delta_db": delta, "basis": basis,
                "clips": [c["name"] for c in auto], **{k: r.get(k) for k in ("scaled", "clipped_points",
                                                                            "reloaded_in_fl", "verify_job", "WARNING")
                                                        if isinstance(r, dict) and r.get(k) is not None}}
    fn = globals().get("insert_gain")
    if fn is None:
        raise RuntimeError("insert_gain isn't loaded (flh_mixeng)")
    r = fn(int(track), delta)
    return dict(r, track=int(track), volume_via="insert gain", delta_db=delta, basis=basis)


def fl_mixer_set(track, volume_db=None, pan=None, muted=None, name=None, effects_enabled=None, color=None, solo=None,
                 route_to=None, unroute=None, reset=None, send_levels=None, send_db=None, if_automated="report"):
    """Live mixer track settings. A volume is set by FL's exact fader curve in ONE step (0.8 = 0 dB, top +5.59 dB;
    never a search over FL's read-back, which on FL 2026 lags the set) and checked in a later read: when the fader
    doesn't hold the asked level (an automation clip or a controller drives it) the call fails saying what drives it
    and where the fader is. if_automated: 'report' (default), 'scale_clip' (move the clip's points by the
    difference in dB), 'insert_gain' (Parametric EQ 2 'Main level' on the track), 'fader' (try the fader even though
    the saved file says a clip drives it). Only inserts and the master: FL's last track is its 'Current' track."""
    how = str(if_automated or "report")
    if how not in IF_AUTOMATED:
        raise ValueError(f"if_automated must be one of {', '.join(IF_AUTOMATED)}")
    lst = lambda v: None if v is None else ",".join(str(int(x)) for x in (v if isinstance(v, list) else [v]))
    t = int(track)
    want = _num(volume_db, float)
    if want is not None and not math.isfinite(want):
        raise ValueError("volume_db must be a number of dB (-150 or less = the fader at zero)")
    clips = _driven_by(("mixer_volume", t)) if want is not None else []
    live_clip = [c for c in clips if c["placed"]]
    skip_fader = bool(live_clip) and how != "fader"               # a clip drives it: a fader set can't hold
    vol = None if want is None or skip_fader else _fader(min(want, FADER_TOP_DB))
    r = _bridge_vol("mixer_set", track=t, volume=vol, pan=_num(pan, float),
                    muted=_num(muted, bool), name=name, effects_enabled=_num(effects_enabled, bool),
                    color=_hexcolor(color), solo=_num(solo, bool), route_to=lst(route_to), unroute=lst(unroute),
                    reset=_num(reset, bool), send_levels=_send_levels_arg(send_levels, send_db))
    check = vol if vol is not None else (0.8 if reset and want is None else None)
    if check is None and not skip_fader:
        return r
    read = lambda: BRIDGE.call("mixer_set", track=t, timeout=5.0)
    if skip_fader:
        ok, why, pos, last = False, "the saved project automates this fader", _numf(r.get("volume")), r
    else:
        ok, why, pos, last = _vol_verify(read, check, r, resend=lambda: BRIDGE.call("mixer_set", track=t, volume=check))
    now = None if pos is None else round(_fader_db(pos), 2)
    if ok:
        out = dict(last if isinstance(last, dict) else r, volume=pos, volume_db=now, volume_held=True)
        note = _fl_db_note(last, now)
        if note:
            out["fl_db_note"] = note
        return out
    others = [k for k, v in (("pan", pan), ("muted", muted), ("name", name), ("color", color), ("solo", solo),
                             ("routing", route_to or unroute), ("sends", send_levels or send_db)) if v is not None]
    if want is None:                                              # reset: name / pan / mute went in, the fader didn't
        raise RuntimeError(f"NOT reset: mixer track {t}'s fader didn't go to 0 dB: {why}. It reads "
                           f"{'nothing' if now is None else f'{now:g} dB'} (name, color, pan, mute were reset)")
    if how in ("scale_clip", "insert_gain"):
        res = _vol_alternative(t, want, now, clips, how)
        res["fader_left_at_db"] = now
        if others:
            res["also_set"] = others
        return res
    what = f"mixer track {t}'s volume"
    if clips:
        msg = _automated_msg(what, clips, _vol_fixes(t, want, now, clips))
    else:
        msg = (f"{what} didn't take {want:g} dB: {why}. Probably an automation clip or a controller drives it (none "
               f"in the saved file - added since the last save?). " + _vol_fixes(t, want, now, clips))
    reads = "nothing" if pos is None else ("-inf (at zero)" if pos <= 0 else f"{now:g} dB")
    raise RuntimeError(f"NOT set: {msg}. The fader now reads {reads}"
                       + (f"; the other settings ({', '.join(others)}) were applied" if others else ""))


def fl_playlist_track_set(index, name=None, color=None):
    return BRIDGE.call("playlist_track_set", index=int(index), name=name, color=_hexcolor(color))


def fl_pattern_set(index, name=None, color=None, select=None):
    return BRIDGE.call("pattern_set", index=int(index), name=name, color=_hexcolor(color), select=_num(select, bool))


def fl_steps(channel, steps, pattern=0):
    if not steps or any(c not in "xX1.-0_ " for c in steps):
        raise ValueError("steps: a string like 'x...x...x...x...' (x = on, . = off)")
    return BRIDGE.call("steps", index=int(channel), steps=steps.replace(" ", ""), pattern=int(pattern))


NOTE_RE = None


def _midi_note(n):
    if isinstance(n, int):
        return n
    import re
    m = re.fullmatch(r"([A-Ga-g])([#b]?)(-?\d)", str(n).strip())
    if not m:
        raise ValueError(f"bad note '{n}' (use names like C4, F#3, Bb5 or MIDI numbers)")
    base = {"C": 0, "D": 2, "E": 4, "F": 5, "G": 7, "A": 9, "B": 11}[m.group(1).upper()]
    return 12 * (int(m.group(3)) + 1) + base + {"#": 1, "b": -1, "": 0}[m.group(2)]


def fl_play(channel, notes=None, chord=None, length_ms=1500, velocity=90, arpeggio_ms=0, bpm=None):
    """Audition live through a channel's instrument; nothing is written to the project.
    chord: "C4 E4 G4" (optionally rolled with arpeggio_ms). notes: [{note, start, length, velocity}] with start/length
    in milliseconds, or in beats when bpm is given."""
    items = []
    if chord:
        for i, n in enumerate(str(chord).replace(",", " ").split()):
            items.append([_midi_note(n), i * float(arpeggio_ms), float(length_ms), int(velocity)])
    for it in notes or []:
        k = 60000.0 / float(bpm) if bpm else 1.0
        items.append([_midi_note(it["note"]), float(it.get("start", 0)) * k, float(it.get("length", 1 if bpm else 500)) * k,
                      int(it.get("velocity", velocity))])
    if not items:
        raise ValueError("give a chord or notes")
    _sync_before("fl_play")                                      # e.g. a queued instrument change
    return BRIDGE.call("play", channel=int(channel), notes=json.dumps(items), velocity=int(velocity))


def fl_stop_sound():
    return BRIDGE.call("stop_sound")


def fl_show(window):
    return BRIDGE.call("show", window=str(window))


BATCH_FIELDS = {"channel": {"index", "volume_db", "volume", "pan", "muted", "name", "color", "solo", "select",
                            "mixer_track"},
                "mixer": {"track", "volume_db", "volume", "pan", "muted", "name", "effects_enabled", "color", "solo", "route_to",
                          "unroute", "reset"},
                "playlist_track": {"index", "name", "color"}, "pattern": {"index", "name", "color", "select"},
                "steps": {"index", "steps", "pattern"}}


def fl_batch(ops, label="changes"):
    """Many live changes in one call (one undo step). ops: [{"op": "mixer", "track": 1, "name": "Piano", "color": "blue"}, ...]"""
    clean = []
    for o in ops:
        kind = o.get("op")
        if kind not in BATCH_FIELDS:
            raise ValueError(f"op must be one of {', '.join(BATCH_FIELDS)}")
        o = dict(o)
        for alias in ("channel", "pattern", "track", "index"):         # accept the natural name for the target
            if alias in o and alias not in BATCH_FIELDS[kind]:
                want = "track" if "track" in BATCH_FIELDS[kind] else "index"
                if want not in o:
                    o[want] = o.pop(alias)
        bad = set(o) - BATCH_FIELDS[kind] - {"op"}
        if bad:
            raise ValueError(f"{kind}: unknown fields {sorted(bad)}")
        o = dict(o)
        if "color" in o:
            o["color"] = _hexcolor(o["color"])
        if o.get("volume_db") is not None and kind in ("mixer", "channel"):   # FL's curve, one set (script v7);
            db = float(o.pop("volume_db"))                                    # an older script refuses it
            o["volume"] = round(_fader(min(db, FADER_TOP_DB)) if kind == "mixer" else _chan_vol(db), 6)
        clean.append(o)
    r = BRIDGE.call("batch", timeout=30.0, ops=json.dumps(clean), label=str(label))
    if isinstance(r, dict):
        res = r.get("results") or []
        if any(isinstance(x, dict) and _old_script(x.get("error", "")) for x in res):
            r["results"] = [dict(x, error=OLD_SCRIPT_VOL) if isinstance(x, dict) and _old_script(x.get("error", ""))
                            else x for x in res]
            r["WARNING"] = OLD_SCRIPT_VOL
    return r


# deep, muted shades (the user prefers darker colors over bright ones)
PALETTE = ["#2B4C7E", "#2E5E3A", "#7A4A1E", "#4A3570", "#1F5A55", "#6E2F50", "#6E5A1E", "#6E2A2A", "#34506A",
           "#4F5A22", "#5E3F2A", "#3A3A6E"]
ROLE_COLORS = [(("piano", "keys", "grand", "splice"), "#2B4C7E"), (("bass",), "#1F3561"), (("string", "violin", "cello",
               "viola", "orchestra", "bbc"), "#5E3F2A"), (("pad", "soft", "layer", "choir", "voice"), "#4A3570"),
               (("drum", "kick", "snare", "hat", "perc", "fpc"), "#6E2A2A"), (("lead", "synth", "flex"), "#1F5A55"),
               (("fx", "riser", "sfx"), "#6E5A1E")]


def fl_organize(color_by="role", name_mixer=True, playlist=True, colors=None):
    """Tidy the open project in one undo step: every channel's mixer track is named after the channel and gets the
    channel's color; playlist tracks are named/colored after the channels. color_by: 'role' (by name keywords),
    'distinct' (one palette color each) or 'keep' (keep channel colors). colors: optional {channel_index: color}."""
    st = fl_state(); ops = []; plan = []
    real = [c for c in st["channels"] if c.get("plugin")]          # skip automation / layer-less channels
    for i, c in enumerate(real):
        name = c.get("name") or f"Channel {c['index']}"
        col = (colors or {}).get(str(c["index"])) or (colors or {}).get(c["index"])
        if not col:
            if color_by == "keep" and c.get("color"):
                col = c["color"]
            elif color_by == "role":
                low = (name + " " + (c.get("plugin") or "")).lower()
                col = next((v for keys, v in ROLE_COLORS if any(k in low for k in keys)), PALETTE[i % len(PALETTE)])
            else:
                col = PALETTE[i % len(PALETTE)]
        col = _hexcolor(col)
        ops.append({"op": "channel", "index": c["index"], "color": col})
        ins = c.get("insert")
        if name_mixer and ins and ins > 0:                          # never rename the master
            ops.append({"op": "mixer", "track": ins, "name": name, "color": col})
        if playlist:
            ops.append({"op": "playlist_track", "index": i + 1, "name": name, "color": col})
        plan.append({"channel": c["index"], "name": name, "color": col, "mixer_track": ins})
    res = fl_batch(ops, label="organize")
    return {"plan": plan, **res}


PLUGIN_READY_WAIT_S = 6.0        # a plugin FL is still loading (right after a reload) answers with 'NoneType' errors
PLUGIN_READY_STEP_S = 0.5        # (no event says when it's ready: asked again this often, this long)
_NOT_READY_RE = re.compile(r"NoneType|cannot be interpreted as an integer|not ready|plugin is loading", re.I)


def _plugin_call(cmd, **a):
    """BRIDGE.call for a plugin command that waits briefly while the plugin isn't ready in FL (PC 2026-10-26:
    fl_plugin_params right after a reload -> "TypeError: 'NoneType' object cannot be interpreted as an integer")."""
    t_end = time.time() + PLUGIN_READY_WAIT_S; tries = 0
    while True:
        try:
            r = BRIDGE.call(cmd, **a)
            if tries and isinstance(r, dict):
                r.setdefault("ready_after_s", round(PLUGIN_READY_WAIT_S - max(0.0, t_end - time.time()), 1))
            return r
        except Exception as e:
            if not _NOT_READY_RE.search(str(e)):
                raise
            if time.time() + PLUGIN_READY_STEP_S > t_end:
                where = (f"mixer track {a.get('index')} slot {a.get('slot')}" if int(a.get("slot", -1)) >= 0
                         else f"channel {a.get('index')}")
                raise RuntimeError(f"the plugin on {where} isn't ready in FL after {PLUGIN_READY_WAIT_S:g} s ({e}): FL "
                                   "is probably still loading it - try again in a moment, or check a plugin is "
                                   "there (fl_state / fl_mixer_info)") from e
            tries += 1
            time.sleep(PLUGIN_READY_STEP_S)


_RE_META = re.compile(r"[.*+?\[\](){}^$\\]")


def fl_plugin_params(index, slot=-1, filter=""):
    """A plugin's parameters (name, 0..1 value, display text). filter: words a name must contain (case-insensitive);
    'attack|release' or a list = any of them; a regular expression ('^Band [1-3]') when it has regex signs.
    Waits briefly while the plugin isn't ready (right after a reload)."""
    i, s = int(index), int(slot)
    alts = [str(x).strip() for x in filter] if isinstance(filter, (list, tuple)) else \
        [x.strip() for x in str(filter or "").split("|")]
    alts = [x for x in alts if x]
    if not alts:
        return _plugin_call("plugin_params", index=i, slot=s, filter="")
    if len(alts) == 1 and not _RE_META.search(alts[0]):
        return _plugin_call("plugin_params", index=i, slot=s, filter=alts[0])
    if not any(_RE_META.search(x) for x in alts) and len(alts) <= 8:   # 'a|b': one filtered read per word, merged
        merged, head = {}, None
        for x in alts:
            r = _plugin_call("plugin_params", index=i, slot=s, filter=x)
            head = head or r
            for p in (r or {}).get("params") or []:
                merged.setdefault(int(p.get("param", -1)), p)
        out = dict(head or {}); out["params"] = [merged[k] for k in sorted(merged)]
        out["filter"] = {"any_of": alts}
        return out
    pat = "|".join(alts) if not isinstance(filter, (list, tuple)) else "|".join(f"(?:{x})" for x in alts)
    try:
        rx = re.compile(pat[:300], re.I)
    except re.error:                                              # not a valid regex: the words literally
        rx = None
    r = _plugin_call("plugin_params", index=i, slot=s, filter="")
    ps = (r or {}).get("params") or []
    keep = [p for p in ps if (rx and rx.search(str(p.get("name") or ""))) or   # a name with '(' etc. written
            any(x.lower() in str(p.get("name") or "").lower() for x in alts)]          # literally still matches
    out = dict(r or {}); out["params"] = keep
    out["filter"] = {"regex" if rx else "any_of": pat if rx else alts}
    if (r or {}).get("count") and len(ps) < int(r["count"]):
        out["filter_note"] = (f"matched among the first {len(ps)} of {r['count']} parameters (FL's script lists at "
                              "most 200 per read): give plain words ('a|b') to search all of them")
    return out


def fl_plugin_probe(index, param, points=17, slot=-1):
    """Sweep one plugin parameter inside FL and return the display text at each knob position (restored after)."""
    return BRIDGE.call("plugin_probe", index=int(index), param=int(param), points=int(points), slot=int(slot),
                       timeout=20.0)


def fl_pattern_new(name=None):
    """Select the next empty pattern in the open FL (no name prompt) and name it."""
    return BRIDGE.call("pattern_new", name=name, timeout=6.0)


def fl_mixer_info(tracks="all"):
    """Mixer tracks: name, armed, recording file, used by a channel, effects, muted (sends when tracks are named)."""
    t = tracks if isinstance(tracks, str) else ",".join(str(int(x)) for x in tracks)
    return BRIDGE.call("mixer_info", tracks=t, timeout=10.0)


def fl_plugin_set(index, param, value, slot=-1):
    return _plugin_call("plugin_set", index=int(index), param=int(param), value=float(value), slot=int(slot))


def fl_plugin_preset(index, direction="next", slot=-1):
    return BRIDGE.call("plugin_preset", index=int(index), direction=str(direction), slot=int(slot))


def _disp_num(text):
    """First number in FL's display text ('-38.0dB' -> -38.0, '2.4 kHz' -> 2400), None without one."""
    t = str(text or "").replace(",", "")
    m_ = re.search(r"-?\d+(?:\.\d+)?", t)
    if not m_:
        return None
    v = float(m_.group(0))
    return v * 1000 if "khz" in t.lower() else v


def _plugin_read(index, param, slot, name=None):
    """One plugin parameter read back in a NEW bridge call: {value, text} (script v6 plugin_get; older scripts:
    plugin_params filtered by the parameter's name)."""
    try:
        return BRIDGE.call("plugin_get", index=int(index), param=int(param), slot=int(slot), timeout=5.0)
    except Exception as e:
        if "unknown command" not in str(e):
            raise
    r = BRIDGE.call("plugin_params", index=int(index), slot=int(slot), filter=str(name or ""), timeout=10.0)
    return next((p for p in (r or {}).get("params") or [] if int(p.get("param", -1)) == int(param)), None) or {}


# display units: unit -> (family, factor to the family's base: ms, Hz, dB, %, semitones, cents, BPM)
DISP_UNITS = {"us": ("time", 0.001), "µs": ("time", 0.001), "ms": ("time", 1.0), "msec": ("time", 1.0),
              "s": ("time", 1000.0), "sec": ("time", 1000.0), "secs": ("time", 1000.0), "min": ("time", 60000.0),
              "hz": ("freq", 1.0), "khz": ("freq", 1000.0), "db": ("db", 1.0), "%": ("pct", 1.0),
              "st": ("semi", 1.0), "semi": ("semi", 1.0), "semitones": ("semi", 1.0), "ct": ("cent", 1.0),
              "cent": ("cent", 1.0), "cents": ("cent", 1.0), "bpm": ("bpm", 1.0)}
OFF_WORDS = ("off", "none", "bypass", "bypassed", "mute", "muted", "disabled", "silent")
SET_SEARCH_EVALS = 40            # server-side knob search (units / words): at most this many sets
SET_SEARCH_PROBE = 33            # positions a word target is looked for at (one plugin_probe call, knob restored)
_SEARCH_ERRORS = ("doesn't show a number", "never reached")


def _disp_parse(text):
    """FL's display text -> {num (in the family's base unit: ms, Hz ...) | None, fam, scale, word}: '194ms' -> 194
    time, '2.00s' -> 2000 time, '2.4 kHz' -> 2400 freq, '-inf dB' -> -inf db, 'Off' -> word 'off'."""
    low = str(text or "").strip().lower().replace(",", "")
    if not low:
        return {"num": None, "fam": None, "scale": 1.0, "word": None}
    if "inf" in low or "∞" in low:
        return {"num": float("-inf") if "-" in low else float("inf"), "fam": "db" if "db" in low else None,
                "scale": 1.0, "word": None}
    m_ = re.search(r"([-+]?\d+(?:\.\d+)?)\s*([a-zµ%]*)", low)
    if not m_:
        return {"num": None, "fam": None, "scale": 1.0,
                "word": re.sub(r"\s+", " ", re.sub(r"[^\w%]+", " ", low)).strip()}
    fam, f = DISP_UNITS.get(m_.group(2), (None, 1.0))
    if fam is None and "khz" in low:
        fam, f = "freq", 1000.0
    return {"num": float(m_.group(1)) * f, "fam": fam, "scale": f, "word": None}


def _word_norm(t):
    return re.sub(r"\s+", " ", re.sub(r"[^\w%]+", " ", str(t or "").lower())).strip()


def _target_spec(target):
    """fl_plugin_set_value's target -> {val, fam, scale, unitless} for a number (30, '30', '30 ms', '1.2 kHz': val
    in the unit written) or {word, text} for a word the knob shows ('Off')."""
    bad = "target: a value as FL shows it (e.g. -3, '250 Hz', '30 ms') or a word it shows ('Off')"
    if isinstance(target, bool):
        raise ValueError(bad)
    if isinstance(target, (int, float)):
        if not math.isfinite(float(target)):
            raise ValueError(bad)
        return {"val": float(target), "fam": None, "scale": 1.0, "unitless": True}
    t = str(target or "").strip()
    try:
        v = float(t.replace(",", ""))
        if math.isfinite(v):
            return {"val": v, "fam": None, "scale": 1.0, "unitless": True}
    except ValueError:
        pass
    p_ = _disp_parse(t)
    if p_["num"] is not None and math.isfinite(p_["num"]):
        return {"val": p_["num"] / p_["scale"], "fam": p_["fam"], "scale": p_["scale"], "unitless": p_["fam"] is None}
    if p_["word"]:
        return {"word": p_["word"], "text": t}
    raise ValueError(bad)


def _knob_value_fn(spec, ref_text=None):
    """(value_of(display text) -> number in the target's unit or None, target, tolerance, note). A unitless target
    is read in the unit the knob shows at ref_text (else the first unit it shows); a display in another unit of
    the same kind converts ('2.00s' = 2000 ms); an 'Off'-style word counts as the knob's bottom (0; -inf in dB)."""
    ref = _disp_parse(ref_text) if ref_text is not None else {"num": None, "fam": None, "scale": 1.0}
    note = None
    if spec.get("unitless"):
        unit = {"fam": ref["fam"], "scale": ref["scale"]} if ref.get("num") is not None and ref.get("fam") else {}
        if unit:
            name = next((u for u, (fa, fac) in DISP_UNITS.items() if fa == unit["fam"] and fac == unit["scale"]), "")
            note = f"read {spec['val']:g} as {name or unit['fam']}, the unit the knob showed ('{ref_text}')"
    else:
        unit = {"fam": spec.get("fam"), "scale": spec.get("scale") or 1.0}
    want = float(spec["val"])
    tol = max(0.02 * abs(want), 0.15 / max(1.0, float(unit.get("scale") or 1.0)), 1e-9)

    def value_of(text):
        p_ = _disp_parse(text)
        if p_["num"] is None:
            if p_["word"] in OFF_WORDS:
                return float("-inf") if unit.get("fam") == "db" else 0.0
            return None
        if p_["fam"] and not unit:                                 # unitless target: the first unit seen
            unit.update(fam=p_["fam"], scale=p_["scale"])
        if unit.get("fam") and p_["fam"] and p_["fam"] != unit["fam"]:
            return None
        return p_["num"] / float(unit.get("scale") or 1.0) if p_["fam"] else p_["num"]
    return value_of, want, tol, note


def _knob_search(i, p, s, value_of, want, tol, pos0, text0=None):
    """Find the knob position whose display is closest to `want` (in value_of's terms) by sets from where the knob
    is: never jumps to an end first, steps of at most 0.15, bisection once the target is bracketed (the bridge
    script's way, but reading units and 'Off'). The knob is left on the best position; a target between two of the
    knob's steps lands on the nearer one. -> {set_to, text, reached, nearest_step, evals}. Raises, knob put back at
    pos0, when nothing comes near. PC-VERIFY: a plugin that updates its display later (async) still converges."""
    pts = []                                                      # (pos, value, text)
    n = [0]

    def at(pos):
        pos = max(0.0, min(1.0, pos))
        r = _plugin_call("plugin_set", index=i, param=p, value=float(pos), slot=s)
        n[0] += 1
        tx = (r or {}).get("text")
        pts.append((pos, value_of(tx), tx))
        return pts[-1]
    if text0 is None:
        at(pos0)
    else:
        pts.append((pos0, value_of(text0), text0))
    lo = None; direction = 1.0 if pos0 <= 0.98 else -1.0; flipped = False
    pos = pos0 + 0.02 * direction
    while n[0] < SET_SEARCH_EVALS:
        valued = [(q_, v_) for q_, v_, _ in pts if v_ is not None]
        if valued and min(abs(v_ - want) for _, v_ in valued) <= 1e-9:
            break
        if any(abs(pos - q_) < 1e-6 for q_, _, _ in pts):          # been there: nothing new to learn
            break
        q, _v, _t = at(pos)
        valued = [(q_, v_) for q_, v_, _ in pts if v_ is not None]
        below = [t for t in valued if t[1] < want]; above = [t for t in valued if t[1] >= want]
        if below and above:                                       # bracketed: bisect between the closest pair
            lo = min(below, key=lambda t: abs(t[0] - q)); hi = min(above, key=lambda t: abs(t[0] - lo[0]))
            if abs(hi[0] - lo[0]) < 1e-4:
                break
            pos = (lo[0] + hi[0]) / 2.0
            continue
        two = [t for t in valued if math.isfinite(t[1])][-2:]
        if len(two) == 2 and two[1][1] != two[0][1] and two[1][0] != two[0][0]:
            (p1, w1), (p2, w2) = two
            nxt = p2 + (want - w2) * (p2 - p1) / (w2 - w1)
            nxt = max(p2 - 0.15, min(p2 + 0.15, nxt))
        else:                                                     # flat, a word, -inf: keep walking
            nxt = q + 0.05 * direction
        nxt = max(0.0, min(1.0, nxt))
        if abs(nxt - q) < 1e-9:                                    # at an end of the knob: try the other way once
            if flipped:
                break
            flipped = True; direction = -direction; nxt = max(0.0, min(1.0, pos0 + 0.02 * direction))
        pos = nxt
    valued = [t for t in pts if t[1] is not None]
    if not valued:
        _plugin_call("plugin_set", index=i, param=p, value=float(pos0), slot=s)
        shown = list(dict.fromkeys(t for _, _, t in pts if t))[:10]
        raise ValueError(f"this knob shows nothing comparable to {want:g} (it showed {shown}); left unchanged")
    err = lambda t: abs(t[1] - want) if math.isfinite(t[1]) else float("inf")
    best = min(valued, key=lambda t: (err(t), abs(t[0] - pos0)))
    reached = err(best) <= tol
    if not reached and lo is None:
        _plugin_call("plugin_set", index=i, param=p, value=float(pos0), slot=s)
        raise ValueError(f"FL's display never reached {want:g} on this knob (closest it showed: '{best[2]}'); left "
                         "unchanged")
    if best[0] >= 0.999 and pos0 < 0.999 and not reached:
        _plugin_call("plugin_set", index=i, param=p, value=float(pos0), slot=s)
        raise ValueError(f"reaching {want:g} would need the knob at its maximum; left unchanged")
    r = _plugin_call("plugin_set", index=i, param=p, value=float(best[0]), slot=s)
    return {"set_to": round(best[0], 5), "text": (r or {}).get("text", best[2]), "reached": reached,
            "nearest_step": not reached, "evals": n[0] + 1}


def _knob_text_set(i, p, s, word, pos0, text0):
    """Put a knob on the position whose display shows `word` ('Off'): where it is, then its two ends, then one
    probe sweep (the bridge puts the knob back after it) and the middle of the matching positions. Not found: the
    knob back where it was, and an error listing what it shows. -> {set_to, text}."""
    w = _word_norm(word)
    hit = lambda t: bool(t) and (_word_norm(t) == w or (len(w) >= 2 and _word_norm(t).startswith(w)))
    if hit(text0):
        return {"set_to": round(pos0, 5), "text": text0, "unchanged": True}
    seen = [text0] if text0 else []
    for end in (0.0, 1.0):
        r = _plugin_call("plugin_set", index=i, param=p, value=end, slot=s)
        seen.append((r or {}).get("text"))
        if hit((r or {}).get("text")):
            return {"set_to": end, "text": r.get("text")}
    pr = BRIDGE.call("plugin_probe", index=i, param=p, points=SET_SEARCH_PROBE, slot=s, timeout=20.0) or {}
    vals, texts = pr.get("values") or [], pr.get("texts") or []
    seen += texts
    idx = [k for k, t in enumerate(texts) if hit(t)]
    if idx:
        run = [idx[0]]
        for k in idx[1:]:
            if k != run[-1] + 1:
                break
            run.append(k)
        pos = float(vals[run[len(run) // 2]])
        r = _plugin_call("plugin_set", index=i, param=p, value=pos, slot=s)
        if hit((r or {}).get("text")):
            return {"set_to": round(pos, 5), "text": r.get("text")}
    _plugin_call("plugin_set", index=i, param=p, value=float(pos0), slot=s)
    shown = list(dict.fromkeys(t for t in seen if t))
    raise ValueError(f"this knob never shows '{word}'; it shows {shown[:12]}" + (" ..." if len(shown) > 12 else "") +
                     "; left unchanged")


def _plugin_held(r, rb, target, judge=None):
    """Did a display-target set hold? r: the set's reply (its text: what FL showed right after it), rb: the later
    read-back. Held = the read-back shows the target (judge(text), else a number within 2 % / 0.15) - or, for a
    knob that steps past it, the same nearest step the set showed - and the knob's value is the one set. -> (ok,
    why)."""
    txt = rb.get("text")
    if judge is not None:
        ok_txt = bool(judge(txt))
    else:
        tol = max(0.15, 0.02 * abs(float(target)))
        got = _disp_num(txt)
        ok_txt = got is not None and abs(got - float(target)) <= tol
    if not ok_txt and r.get("nearest_step") and txt is not None and \
            str(txt).strip() == str(r.get("text") or "").strip():
        ok_txt = True
    if not ok_txt:
        return False, f"FL shows '{txt}' now, not {target if isinstance(target, str) else format(target, 'g')}"
    v, set_to = _numf(rb.get("value")), _numf(r.get("set_to"))
    if v is not None and set_to is not None and abs(v - set_to) > 0.01:
        return False, (f"FL shows '{txt}' but the knob's value is {v:.4g}, not the {set_to:.4g} it was "
                       "set to (FL didn't keep the change; a save would store the old value)")
    return True, None


def _not_set(fn, what):
    """fn with its 'never reached' / 'never shows' ValueErrors as 'NOT set: <what>: ...' RuntimeErrors (the knob was
    put back; a wrong argument stays a ValueError)."""
    def run(*a, **k):
        try:
            return fn(*a, **k)
        except ValueError as e:
            raise RuntimeError(f"NOT set: {what}: {e}") from e
    return run


def fl_plugin_set_value(index, param, target, slot=-1):
    """Set a plugin knob so FL displays `target`, then read it back in a later bridge call (after SET_VERIFY_S) and
    report it as done only when FL kept it - PC 2026-10-23: Fruity Convolver 'Wet level' reported '-38.0dB' with the
    value unchanged, and a save + reload showed the old -30.3 dB. One retry; then an honest failure that names an
    automation clip driving the knob when the saved project has one.
    target: a number as shown (-3, 250), with a unit ('30 ms', '2 s', '1.2 kHz', '-6 dB', '50%': compared across
    the units the knob shows, '194ms' ... '2.00s'), or a word the knob shows ('Off'). A number asked on a knob
    showing 'Off' at its bottom counts 'Off' as 0. A knob that steps past the value lands on the nearest step and
    says so (asked 30 ms, it shows 31 ms: done, reported) - PC 2026-10-26.
    PC-VERIFY: fl_plugin_set_value on Fruity Convolver 'Wet level', then fl_save + reopen: the new level is kept.
    PC-VERIFY: a reverb's 'Low cut' showing 'Off' at 0: target 'Off' and target 0 land on Off, target 120 works from
    Off; a stepped pre-delay asked 30 ms reports the nearest step; a time knob showing '194ms' ... '2.00s' reaches
    target '1.2 s' and target 1200 (checklists/core.md 'plugin set_value units')."""
    i, p, s = int(index), int(param), int(slot)
    spec = _target_spec(target)
    clips = [c for c in _driven_by(("plugin", i, s, p)) if c["placed"]]
    where = f"mixer track {i} slot {s}" if s >= 0 else f"channel {i}'s plugin"
    notes = []
    knob_search = _not_set(_knob_search, f"{where} param {p}")
    knob_text_set = _not_set(_knob_text_set, f"{where} param {p}")
    asked = spec.get("text") or (str(target).strip() if isinstance(target, str) else format(spec["val"], "g"))
    if "word" in spec:                                            # 'Off': put the knob where it shows that word
        cur = _plugin_read(i, p, s)
        w = spec["word"]
        r = dict(knob_text_set(i, p, s, spec["text"], float(_numf(cur.get("value")) or 0.0), cur.get("text")),
                 param=p, name=cur.get("name"), before=_numf(cur.get("value")), searched="by its text")
        judge = lambda t: bool(t) and (_word_norm(t) == w or _word_norm(t).startswith(w))
        tgt_v = spec["text"]
    else:
        tgt_v = spec["val"]; r = None; cur = None; script_target = None
        if spec.get("unitless"):
            script_target = spec["val"]
        else:                                                     # a unit given: the bridge's search compares bare
            cur = _plugin_read(i, p, s)                           # numbers, so only when the knob shows that unit
            ref = _disp_parse(cur.get("text"))
            if ref["num"] is not None and ref["fam"] == spec["fam"]:
                base = spec["val"] * spec["scale"]
                script_target = base if spec["fam"] == "freq" else base / ref["scale"]
        if script_target is not None:                             # the bridge script's own search (one call)
            try:
                r = _plugin_call("plugin_set_value", timeout=30.0, index=i, param=p, target=script_target, slot=s)
            except Exception as e:
                if not any(x in str(e) for x in _SEARCH_ERRORS):
                    raise
                notes.append(f"the bridge script's search: {str(e)[:90]} - searched by fl-headless instead")
        if r is not None:
            value_of, want, tol, unote = _knob_value_fn(spec, r.get("text") if spec.get("unitless") else None)
            v = value_of(r.get("text"))
            if v is None or abs(v - want) > tol:                  # beside it (a step) or another unit: refine here
                at = _numf(r.get("set_to"))
                rs = knob_search(i, p, s, value_of, want, tol, at if at is not None else float(r.get("before") or 0),
                                  r.get("text") if at is not None else None)
                r = dict(r, **rs, searched="by fl-headless (after the bridge script)")
        else:                                                     # units / 'Off' / mixed scales: search here
            cur = cur or _plugin_read(i, p, s)
            value_of, want, tol, unote = _knob_value_fn(spec, cur.get("text"))
            pos0 = float(_numf(cur.get("value")) or 0.0)
            rs = knob_search(i, p, s, value_of, want, tol, pos0, cur.get("text"))
            r = dict(rs, param=p, name=cur.get("name"), before=round(pos0, 5), searched="by fl-headless")
        if unote:
            notes.append(unote)
        judge = (lambda t, vf=value_of, w_=want, tl=tol: vf(t) is not None and abs(vf(t) - w_) <= tl) \
            if r.get("reached", True) else None
    tries = []
    for attempt in (1, 2):
        time.sleep(SET_VERIFY_S)
        rb = _plugin_read(i, p, s, r.get("name"))
        ok, why = _plugin_held(r, rb, tgt_v, judge)
        tries.append({"try": attempt, "text": rb.get("text"), "value": _numf(rb.get("value")), "held": ok})
        if ok:
            out = dict(r, text=rb.get("text"), value=round(_numf(rb.get("value")) or 0.0, 5), held=True)
            out.pop("reached", None)
            if r.get("set_to") is None:
                out["held_note"] = ("checked by the display text only: FL runs an older bridge script (v6 also checks "
                                    "the knob's value: fl_bridge_setup(action='update_script'), restart FL)")
            if attempt > 1:
                out["note"] = "the first set didn't hold in FL; the second did (checked by a later read-back)"
            if r.get("nearest_step"):
                out["nearest_step"] = (f"asked {asked}: the knob steps past it, so it sits on the nearest step, "
                                       f"'{rb.get('text')}'")
            else:
                out.pop("nearest_step", None)
            if notes:
                out["notes"] = notes
            return out
        if attempt == 1:                                          # once more: the found knob position directly
            if _numf(r.get("set_to")) is not None:
                _plugin_call("plugin_set", index=i, param=p, value=float(r["set_to"]), slot=s)
            else:
                r = BRIDGE.call("plugin_set_value", timeout=30.0, index=i, param=p, target=tgt_v, slot=s)
    what = f"{where} param {p} '{r.get('name') or '?'}'"
    if clips:
        msg = _automated_msg(what, clips, f"scale or edit that clip (it sets the knob while the song plays), or "
                                          f"delete it to set the knob by hand")
    else:
        msg = (f"{what} didn't keep {asked}: {why}. FL may apply plugin changes later or the plugin ignores script "
               "sets; an automation clip added since the last save would do this too")
    raise RuntimeError(f"NOT set: {msg}. Read-backs: {json.dumps(tries)}")


def _open_bpb():
    """Beats per bar of the project open in FL (3 for a 3/4 song); 4 when unknown."""
    try:
        path, _ = _open_project_guess()
        return _qbar(flp_project_info(path)) if path else 4
    except Exception:
        return 4


def _qbar(info):
    """Quarter-note beats per bar from a project's time signature (3/4 -> 3, 6/8 -> 3, 7/8 -> 3.5)."""
    num = int(info.get("time_sig_num") or 4); den = int(info.get("time_sig_beat") or 4)
    q = num * 4.0 / den
    return int(q) if q == int(q) else q


def fl_song(action, bar=None, name=None, delta=1):
    bpb = _open_bpb()
    r = BRIDGE.call("song", action=str(action), bar=_num(bar, float), name=name, delta=int(delta), bpb=bpb)
    if action == "marker_jump":                                   # FL moves after the call returns: read again
        time.sleep(0.15); r = dict(BRIDGE.call("song", action="where", bpb=bpb), done="marker_jump")
    return r


def fl_context():
    """What you're looking at in FL right now: focused window, selected channel(s), mixer track(s), pattern, playhead
    bar, playlist selection - so 'make this quieter' or 'tighten these notes' can be resolved without naming things."""
    bpb = _open_bpb()
    r = BRIDGE.call("context", bpb=bpb)
    path, title = _open_project_guess()
    r.update({"project": path, "window_title": title, "beats_per_bar": bpb})
    return r


def _song_sections(bpb):
    """[(name, bar)] of the section patterns laid out in the open project's playlist (for per-section results)."""
    try:
        path, _ = _open_project_guess()
        clips = flp_playlist(path)["clips"] if path else []
    except Exception:
        return []
    out = sorted({(c["bar"], c["name"]) for c in clips if c.get("kind") == "pattern" and c.get("name") != "Tempo"})
    return [(n, b) for b, n in out]


def fl_listen(start_bar=None, end_bar=None, seconds=None, save=None, reference=None, max_seconds=600):
    """Hear the song in the running FL without closing it or rendering: plays from start_bar (song mode) until
    end_bar / seconds / the song stops, records what comes out of the speakers (WASAPI loopback), and measures it:
    loudness (LUFS), true peak, clipping, tone balance, stereo width, per section (the playlist's section names)
    and optionally against a saved reference. save: also keep the recording as a .flac (inside FLH_ROOTS)."""
    import fl_capture as C
    import numpy as np
    steps, t_step = {}, [time.time()]

    def step(name):
        now = time.time(); steps[name] = round(steps.get(name, 0) + now - t_step[0], 2); t_step[0] = now
    ok, why = C.available()
    if not ok:
        raise RuntimeError(f"can't record the speakers: {why}")
    step("device_check")
    _sync_before("fl_listen")                                    # FL must hold queued edits before it plays
    step("sync_queued_edits")
    if not fl_running():
        raise RuntimeError("FL isn't open")
    bpb = _open_bpb()
    song = lambda **a: BRIDGE.call("song", bpb=bpb, timeout=4.0, **a)
    BRIDGE.call("transport", action="stop")
    was_song_mode = bool(song(action="where").get("song_mode"))
    if not was_song_mode:
        song(action="song_mode")                                  # play the arrangement, not the current pattern
    if start_bar is not None:
        song(action="goto", bar=float(start_bar)); time.sleep(0.2)
    first = song(action="where")["bar"]
    step("fl_setup")
    rec = C.LoopbackRecorder(); rec.start()
    time.sleep(PREROLL_S)                                         # FL stopped: what plays now is someone else
    try:
        bg_peak = rec.recent_peak(PREROLL_S - 0.1) or 0.0
    except Exception:                                             # noqa: BLE001 - only used to end the tail early
        bg_peak = 0.0
    step("preroll")
    t_play = time.time(); t0 = t_play
    try:
        BRIDGE.call("transport", action="play")
    except BaseException:                                         # FL didn't take 'play': the speaker recording
        try:                                                      # must not run on forever in the background
            rec.stop()
        except Exception:                                         # noqa: BLE001
            pass
        raise
    stop_err = None
    timeline, limit = [(0.0, first)], float(seconds or max_seconds)
    last_move = time.time(); prev = first; cut_t = None
    try:
        while True:
            time.sleep(0.25)
            el = time.time() - t0; b = song(action="where")["bar"]
            if b < prev - 0.25:                                   # jumped back: the song ended (FL looped/stopped)
                cut_t = el; break
            timeline.append((el, b))
            if b > prev + 1e-3:
                prev, last_move = b, time.time()
            if end_bar is not None and b >= float(end_bar):
                break
            if el >= limit or time.time() - last_move > 2.0:     # time's up, or playback was stopped
                break
    finally:
        step("play")
        try:
            BRIDGE.call("transport", action="stop")
        except Exception as e:                                    # noqa: BLE001 - said below; the recording
            stop_err = e                                          # still stops (else it runs on forever)
        t_stop = time.time()                                      # keep the reverb tail: up to 1.5 s, less once
        tail_gate = max(1e-3, 3 * bg_peak)                        # it has died away (below -60 dBFS / the PC's own)
        while time.time() - t_stop < TAIL_MAX_S:
            time.sleep(0.12)
            if time.time() - t_stop < 0.35:
                continue
            try:
                pk = rec.recent_peak(0.25)
            except Exception:                                     # noqa: BLE001
                pk = None
            if pk is not None and pk < tail_gate:
                break
        sr, x = rec.stop()
        step("tail")
        if not was_song_mode:
            try:
                song(action="song_mode")                          # back to pattern mode as the user had it
            except Exception:
                pass
    stop_warn = (None if stop_err is None else      # measured, but FL may still be playing: said in the result
                 f"FL didn't answer 'stop' after listening ({type(stop_err).__name__}: {stop_err}); it may still be "
                 "playing - stop it in FL")
    if x.ndim == 1:
        x = x[:, None]
    if x.shape[1] == 1:
        x = np.repeat(x, 2, axis=1)
    x = x[:, :2]
    pre = int(PREROLL_S * sr)
    bg = _background(x[:max(0, pre - int(0.05 * sr))], sr)       # the PC's own sound while FL was stopped
    x = x[pre:]
    if cut_t is not None:
        x = x[: int((cut_t + 1.5) * sr)]
    gate = max(1e-4, 3 * bg["peak"]) if bg else 1e-4
    loud = np.abs(x).max(1); start = int(np.argmax(loud > gate)) if (loud > gate).any() else 0
    start = min(start, int(1.5 * sr)); x = x[start:]; shift = start / sr
    if not len(x) or float(np.abs(x).max()) < 1e-4:
        return {"heard": False, "seconds": round(len(x) / sr, 2),
                "why": "nothing came out of the default output device: FL may be using another device or an ASIO "
                       "interface, or its master is muted. Pick the same device in Windows and FL, then retry.",
                **({"WARNING": stop_warn} if stop_warn else {})}
    tl = [(max(0.0, t - shift), b) for t, b in timeline]
    def bar_to_s(bar):
        ts, bs = [t for t, _ in tl], [b for _, b in tl]
        return float(np.interp(bar, bs, ts))
    secs = []
    names = _song_sections(bpb)
    last_bar = tl[-1][1]
    for i, (n, b) in enumerate(names):
        nb = names[i + 1][1] if i + 1 < len(names) else last_bar
        if nb <= first or b >= last_bar:
            continue
        a, z = bar_to_s(max(b, first)), bar_to_s(min(nb, last_bar))
        if z - a >= 1.0:
            secs.append({"name": f"{n} (bar {b:g})", "start_s": a, "end_s": z})
    work = tempfile.mkdtemp(prefix="flh_listen_"); tmp = os.path.join(work, "listen.wav")
    try:
        C.write_wav(tmp, sr, x)
        res = audio_analyze(tmp, sections=secs or None, reference=reference)
        step("analyze")
    finally:
        res_path = None
        if save:
            writable(save); import flac_lite
            pcm = (np.clip(x, -1, 1) * 8388607).astype(np.int32)
            flac_lite.encode(save, pcm, sr, 24); res_path = save
        shutil.rmtree(work, ignore_errors=True)
    res.pop("path", None)
    res["steps_s"] = steps
    res.update({"heard": True, "bars": [round(first, 2), round(last_bar, 2)], "seconds": round(len(x) / sr, 2),
                "saved": res_path, "note": "recorded from the speakers: other sounds playing on the PC get in too",
                "renders": 0})                                    # played live: no FL export
    if stop_warn:
        res["WARNING"] = stop_warn
    if bg and bg["db"] > BG_WARN_DB:
        mus = float(np.sqrt(np.mean(x ** 2))) if len(x) else 0.0
        mus_db = 20 * np.log10(mus + 1e-12)
        res["background"] = {"db": round(bg["db"], 1), "hz": bg["hz"],
                             "why": (f"something else on this PC was making sound while FL was stopped "
                                     f"({bg['db']:.0f} dBFS{', around ' + str(bg['hz']) + ' Hz' if bg['hz'] else ''}: "
                                     "music, a video, a call, or a monitored microphone) - it's in this recording. "
                                     "Pause it for exact measurements")}
        if mus_db - bg["db"] < 15:
            res["background"]["unreliable"] = (f"only {mus_db - bg['db']:.0f} dB above the music: loudness, tone and "
                                               "pitch here are mostly that other sound")
    return res


PREROLL_S = 0.6                                                   # recorded before play: the PC's background sound
TAIL_MAX_S = 1.5                                                  # longest wait for a reverb tail after stop
BG_WARN_DB = -60.0


def _background(y, sr):
    """{db (RMS dBFS), peak, hz (main tone, if tonal)} of what the speakers played while FL was stopped."""
    import numpy as np
    if y is None or len(y) < int(0.1 * sr):
        return None
    m = y.mean(axis=1) if y.ndim > 1 else y
    rms = float(np.sqrt(np.mean(m ** 2))); pk = float(np.abs(y).max())
    hz = None
    if rms > 1e-5:
        n = 1 << int(np.log2(len(m)))
        P = np.abs(np.fft.rfft(m[:n] * np.hanning(n))) ** 2; f = np.fft.rfftfreq(n, 1 / sr)
        band = (f > 20) & (f < 4000)
        if band.any():
            i = int(np.argmax(np.where(band, P, 0)))
            if P[i] > 20 * np.median(P[band]):                    # a clear tone (a hum), not broadband noise
                hz = int(round(f[i]))
    return {"db": 20 * np.log10(rms + 1e-12), "peak": pk, "hz": hz}


def _listen_measure(start_bar, end_bar, seconds):
    r = fl_listen(start_bar=start_bar, end_bar=end_bar, seconds=seconds)
    if not r.get("heard"):
        return None
    return r["whole"]


def fl_mix_check(start_bar=None, end_bar=None, seconds=20, tracks=None, window_s=8):
    """Mix engineer, step 1: hear the passage once as a whole and then each mixer track solo (live, FL stays open),
    measure loudness and tone per track, and propose ranked fixes (fader moves, EQ dips where two parts fight,
    high-passes, master headroom). Nothing changes yet: apply the ones you like with fl_mix_apply.
    Fast + honest: each pass hears at most window_s seconds (0 = the whole passage), and the master's effects are
    bypassed while measuring so a limiter/maximizer can't inflate quiet solo tracks."""
    import fl_mix
    _sync_before("fl_mix_check")
    st = fl_state()
    used = sorted({c["insert"] for c in st["channels"] if c.get("plugin") and c.get("insert", 0) > 0})
    names = {m["index"]: m["name"] for m in st["mixer"]}
    todo = [int(t) for t in tracks] if tracks else used
    if window_s and float(window_s) > 0:
        est = _est_listen_s(start_bar, end_bar, seconds if end_bar is None else None) or float(seconds)
        if est > float(window_s):
            end_bar, seconds = None, float(window_s)
    master_fx = bool(next((m for m in st["mixer"] if m["index"] == 0), {}).get("effects"))
    if master_fx:
        BRIDGE.call("mixer_set", track=0, effects_enabled=False)
    try:
        mix = _listen_measure(start_bar, end_bar, seconds)
    except Exception:
        if master_fx:
            BRIDGE.call("mixer_set", track=0, effects_enabled=True)
        raise
    if mix is None:
        if master_fx:
            BRIDGE.call("mixer_set", track=0, effects_enabled=True)
        return {"heard": False, "why": "nothing came out of the speakers (see fl_listen)"}
    per = {}
    # "solo" by muting every other used track (FL's solo state can't be read back reliably, so a solo could stick)
    tracks_used = sorted({m["index"] for m in st["mixer"] if m["index"] > 0})
    was_muted = {m["index"]: bool(m.get("muted")) for m in st["mixer"]}
    def set_mutes(only):
        for u in tracks_used:
            want = was_muted.get(u, False) if only is None else (u != only or was_muted.get(u, False))
            BRIDGE.call("mixer_set", track=u, muted=want)
    try:
        for t in todo:
            set_mutes(t)
            m = _listen_measure(start_bar, end_bar, seconds)
            if m:
                per[t] = dict(m, name=names.get(t, f"Insert {t}"))
    finally:
        try:
            set_mutes(None)
        except Exception:
            pass
        if master_fx:
            try:
                BRIDGE.call("mixer_set", track=0, effects_enabled=True)
            except Exception:
                pass
    props = fl_mix.propose(per, mix)
    path, _ = _open_project_guess()
    _state({"mix_check": {"project": path, "proposals": props, "applied": []}})
    return {"mix": {k: mix[k] for k in ("lufs", "true_peak_dbfs", "bands_db") if k in mix},
            "tracks": {(names.get(t, t) if sum(1 for u in per if names.get(u, u) == names.get(t, t)) == 1
                        else f"{names.get(t, t)} ({t})"): {"index": t, **{k: m.get(k) for k in ("lufs", "bands_db", "crest_db", "width_db",
                                                                          "lr_correlation", "centroid_hz", "peak_dbfs")}}
                       for t, m in per.items()},
            "proposals": props, "next": "fl_mix_apply(ids=[...]) applies some or all; fl_mix_apply(revert=true) undoes"}


def _peq2_in(st, track):
    """The slot of a Parametric EQ 2 on mixer `track` in a state reply (full or light), else None."""
    for m_ in (st or {}).get("mixer") or []:
        if int(m_.get("index", -1)) == int(track):
            for fx in m_.get("effects") or []:
                if "parametric eq 2" in str(fx.get("name", "")).lower():
                    return int(fx["slot"])
    return None


def _peq2_slot(track):
    for m in fl_state()["mixer"]:
        if m["index"] == track:
            for fx in m.get("effects", []):
                if "parametric eq 2" in fx["name"].lower():
                    return fx["slot"]
            used = {fx["slot"] for fx in m.get("effects", [])}
            return ("free", next((i for i in range(10) if i not in used), None))
    raise RuntimeError(f"mixer track {track} isn't fed by a channel, so its effects can't be read here; "
                       "put a Fruity Parametric EQ 2 on it and retry")


def _add_peq2(track, slot):
    """Put a Fruity Parametric EQ 2 on a mixer slot: saves, edits the file, refreshes FL via a blank project."""
    path, _ = _open_project_guess()
    if not path:
        raise RuntimeError("can't tell which project is open; add an EQ to the track in FL and retry")
    pre = next((p for p in fl_find_presets("Fruity Parametric EQ 2", limit=10)["presets"]
                if p.lower().endswith("fruity parametric eq 2.fst")), None)
    if not pre:
        raise RuntimeError("Fruity Parametric EQ 2 preset not found")
    _with_open_project(path, path, lambda: flp_load_plugin(path, path, pre, track=track, slot=slot))   # fast reload


def fl_mix_apply(ids=None, revert=False):
    """Mix engineer, step 2: apply proposals from the last fl_mix_check (all, or ids=[1,3]); revert=true restores
    what was there before. Fader/master moves are live; EQ moves use (or add) a Fruity Parametric EQ 2 on the track."""
    import fl_mix
    mc = _state().get("mix_check") or {}
    if revert:
        undone = []
        for u in reversed(mc.get("applied", [])):
            if u["kind"] == "fader":
                if u.get("before_v") is not None:
                    _fader_restore(u["track"], u["before_v"])
                else:
                    _bridge_vol("mixer_set", track=u["track"], volume=_fader(float(u["before"])))
            else:
                BRIDGE.call("plugin_set", index=u["track"], slot=u["slot"], param=u["param"], value=float(u["before"]))
            undone.append(u)
        mc["applied"] = []; _state({"mix_check": mc})
        return {"reverted": len(undone)}
    props = [p for p in mc.get("proposals", []) if ids is None or p["id"] in [int(i) for i in ids]]
    if not props:
        return {"applied": [], "note": "nothing to apply (run fl_mix_check first, or check the ids)"}
    applied, done, skipped = mc.get("applied", []), [], []
    def remember(u):                                              # saved per step: an error midway keeps revert data
        applied.append(u); mc["applied"] = applied; _state({"mix_check": mc})
    for p in props:
        t = p["track"]
        if p["action"] in ("fader", "master"):
            pos, before, _r = _fader_read(t)                      # the real fader, any track
            if pos is None or pos <= 0:                           # unreadable / at zero: a relative move would jump
                skipped.append({"id": p["id"], "why": f"mixer track {t}'s fader can't be read (or is at zero): set it "
                                                      "by hand"}); continue
            want = before + float(p["db"])
            if t == 0 and want < MASTER_FLOOR_DB:                 # a mix move never buries the master
                want = max(want, min(before, MASTER_FLOOR_DB))
            remember({"kind": "fader", "track": t, "before": before, "before_v": pos})
            f = _fader_apply(t, want)
            if f["db"] is None or abs(f["db"] - want) > MIX_MOVE_TOL_DB:
                _fader_restore(t, pos)
                skipped.append({"id": p["id"], "why": f"the fader landed at {f['db']} dB, not {want:.2f} ({f['why']}): "
                                                      "put back"}); continue
            done.append(p["id"])
        elif p["action"] in ("eq_cut", "highpass"):
            slot = _peq2_slot(t)
            if isinstance(slot, tuple):
                if slot[1] is None:
                    continue
                _add_peq2(t, slot[1])
                # big projects take a while to reload: no bridge call while FL's title says it's loading, polls back
                # off, the budget follows the project's measured load (flh_mixeng's wait), FL closing stops it
                waitf = globals().get("mix_wait_fl_ready")
                slot = None
                try:
                    if waitf:
                        st_ = waitf(_open_project_guess()[0], lambda s_: _peq2_in(s_, t) is not None,
                                    what="loading the project with the added EQ", tracks=[t])
                        slot = _peq2_in(st_, t)
                    else:
                        t0 = time.time(); k = 0
                        while time.time() - t0 < _scaled(45.0) and not isinstance(slot, int):
                            time.sleep((0.5, 1.0, 2.0, 4.0)[min(k, 3)]); k += 1
                            if _fl_loading_title():
                                continue
                            try:
                                slot = _peq2_slot(t)
                            except Exception:                     # noqa: BLE001
                                slot = None
                except TimeoutError as e:
                    raise RuntimeError(f"the EQ added to mixer track {t} isn't in FL yet ({e}); it IS in the project "
                                       "file: once FL shows the project again, run fl_mix_apply again") from None
                if not isinstance(slot, int):
                    raise RuntimeError(f"adding an EQ to mixer track {t} didn't take (FL may still have been saving); retry")
            b = fl_mix.eq_band_for(p["hz"], p["action"])
            params = {q["param"]: q["value"] for q in fl_plugin_params(t, slot)["params"]}
            moves = [(7 + b, ("value", p["hz"]))]
            if p["action"] == "highpass":
                moves = [(21 + b, ("raw", 3 / 7))] + moves
            else:
                moves += [(b, ("value", p["db"]))]
            for param, (how, v) in moves:
                remember({"kind": "param", "track": t, "slot": slot, "param": param, "before": params.get(param, 0.5)})
                if how == "raw":
                    BRIDGE.call("plugin_set", index=t, slot=slot, param=param, value=float(v))
                else:
                    fl_plugin_set_value(t, param, v, slot)
            done.append(p["id"])
    mc["applied"] = applied; _state({"mix_check": mc})
    out = {"applied": done, "note": "listen again with fl_listen to compare; fl_mix_apply(revert=true) undoes; save when happy"}
    if skipped:
        out["skipped"] = skipped
    return out


def _record_notes(channel, notes, hold_s):
    """Play notes through a channel live and record the speakers: (sr, x) trimmed to the first sound."""
    import fl_capture as C
    import numpy as np
    rec = C.LoopbackRecorder(); rec.start()
    try:
        BRIDGE.call("play", channel=int(channel), notes=json.dumps([[int(n), 0, int(hold_s * 1000), 92] for n in notes]))
        time.sleep(hold_s + 1.8)                                  # hold + release tail
    finally:
        sr, x = rec.stop()
    x = x[:, :2] if x.ndim > 1 else np.stack([x, x], 1)
    loud = np.abs(x).max(1)
    if (loud > 1e-4).any():
        x = x[int(np.argmax(loud > 1e-4)):]
    return sr, x


def fl_audition(want="", query=None, channel=None, count=8, notes=None, hold_s=2.5, apply=None, apply_channel=None):
    """Find a sound by ear. With `query`: loads up to `count` matching instrument presets (.fst, see fl_find_presets)
    into a scratch project, plays a chord through each, records and describes it (attack, sustain, tone, width) and
    ranks them against `want` ('soft string pad', 'bright pluck'); your song is saved first and reopened after.
    With `channel` (no query): steps through that plugin's own presets instead (plugins that list presets in FL).
    Previews are kept as FLACs in fl-headless's own state folder (audition/previews: only the last run is kept, never
    in a song or collection folder). Presets that can't go on a plugin channel (sample-based channel presets) are
    skipped, not fatal. Ranking: fl_sound.score (the wish's words -> targets for brightness, attack, sustain, low
    end, width, distortion; the preset's name counts too: 'clean' sinks a 'DIST ...' preset).
    apply=<rank> + apply_channel=<channel>: put that sound from the last audition on a channel of the open song."""
    import fl_capture as C
    import fl_sound
    _sync_before("fl_audition")
    if apply is not None:
        last = _state().get("audition") or {}
        pick = next((r for r in last.get("ranked", []) if r["rank"] == int(apply)), None)
        if not pick or not pick.get("preset"):
            raise ValueError("nothing to apply: run fl_audition with a query first (apply needs a preset file)")
        if apply_channel is None:
            raise ValueError("give apply_channel: the channel of the open song to put the sound on")
        path, _ = _open_project_guess()
        if not path:
            raise RuntimeError("couldn't tell which saved project FL has open, so nothing was changed")
        # FL saves, the file is edited once the save has landed, FL reloads it in place (never a fixed sleep)
        res = _with_open_project(path, path, lambda: flp_load_plugin(path, path, pick["preset"],
                                                                      channel=int(apply_channel)))
        return {"applied": pick["name"], "channel": int(apply_channel), "project": path,
                **{k: res[k] for k in ("reloaded_in_fl", "verify_job", "WARNING") if isinstance(res, dict) and k in res}}
    ok, why = C.available()
    if not ok:
        raise RuntimeError(f"can't record the speakers: {why}")
    notes = notes or [45, 57, 64, 67, 72]                         # A minor 7, open voicing
    aud, prev_dir, old_note = _audition_dir()
    import flac_lite
    import numpy as np
    results = []

    def keep(i, name, sr, x, preset=None):
        d = fl_sound.describe(x, sr, hold_s=hold_s)
        fn = os.path.join(prev_dir, f"{i:02d} {re.sub(r'[^A-Za-z0-9 _-]+', '', name)[:40]}.flac")
        if not d.get("silent"):
            flac_lite.encode(fn, (np.clip(x[: int(sr * (hold_s + 2))], -1, 1) * 32767).astype(np.int32), sr, 16)
        sc = fl_sound.score(d, want, name=" ".join(x_ for x_ in (name, preset or "") if x_), detail=True)
        results.append(dict(d, name=name, preset=preset, preview=fn if not d.get("silent") else None,
                            score=sc["score"], **({"why": sc["why"]} if sc.get("why") else {})))
    if query is None:
        if channel is None:
            raise ValueError("give a query (preset files to try) or a channel (step through its plugin's presets)")
        info = fl_plugin_info(int(channel), -1)
        n = min(int(count), max(1, int(info.get("count") or 1))); steps = 0
        try:
            for i in range(n):
                if i:
                    BRIDGE.call("plugin_preset", index=int(channel), direction="next", slot=-1); steps += 1
                    time.sleep(0.6)
                name = fl_plugin_info(int(channel), -1).get("preset") or f"preset {i + 1}"
                sr, x = _record_notes(channel, notes, hold_s); keep(i + 1, name, sr, x)
        finally:
            for _ in range(steps):                                # back to where it was, even after an error
                BRIDGE.call("plugin_preset", index=int(channel), direction="prev", slot=-1)
        note = "stepped through the plugin's presets and went back to the original; pick one in the plugin by name"
    else:
        found = [p for p in fl_find_presets(str(query), limit=200)["presets"]
                 if not re.search(r"(?i)[\\/](effects|mixer presets)[\\/]", p) and "plugin database" not in p.lower()]
        found = found[: max(1, min(int(count), 12))]
        if not found:
            raise FileNotFoundError(f"no instrument presets match '{query}'")
        template = _state().get("selftest_template") or _single_pattern_template()
        if not template:
            raise RuntimeError("no project to build the audition from (needs one single-pattern .flp in FLH_ROOTS)")
        orig, _ = _open_project_guess()
        if fl_running() and not orig:
            raise RuntimeError("save your song inside FLH_ROOTS first: the audition switches FL to a scratch project "
                               "and then reopens your song")
        scratch = os.path.join(aud, "audition.flp"); shutil.copy2(template, scratch)
        chans, skipped = [], []
        for pre in found:                                         # a preset that can't go on a plugin channel (a
            keep_ = open(scratch, "rb").read()                    # sample-based channel preset ...) is skipped
            try:
                chans.append((flp_add_channel(scratch, scratch, 0, preset=pre)["new_channel"], pre))
            except Exception as e:                                # noqa: BLE001
                _write_bytes(scratch, keep_)
                skipped.append({"preset": os.path.splitext(re.split(r"[\\/]", pre)[-1])[0], "why": str(e)[:90]})
        if not chans:
            raise FileNotFoundError(f"none of the {len(found)} presets matching '{query}' can be auditioned on a plugin "
                                    f"channel: {'; '.join(s_['preset'] + ': ' + s_['why'] for s_ in skipped[:3])}")
        if orig and fl_running() and not os.path.isfile(orig):    # not on disk yet: nothing to clobber
            BRIDGE.call("transport", action="save"); time.sleep(1.0)
        elif orig and fl_running():                               # the same guarded save as everywhere: never over a
            if not _save_in_fl_and_wait(orig):                    # file changed behind FL, a stale FL or preview mutes
                why = _stale_block(orig) or ("fl_preview's live mutes are still in FL" if _preview_mutes_on(orig)
                                             else "the file changed on disk after FL last loaded or saved it")
                raise RuntimeError(f"couldn't save your song first ({why}), so the audition didn't start and nothing "
                                   "was changed: fl_save or fl_open the song, then retry")
        fl_open(scratch, save_current=False); time.sleep(2)       # just saved: switching saves nothing again
        try:
            for i, (ch, pre) in enumerate(chans, 1):
                sr, x = _record_notes(ch, notes, hold_s); keep(i, os.path.splitext(re.split(r"[\\/]", pre)[-1])[0], sr, x, pre)
        finally:
            if orig:
                fl_open(orig, save_current=False)                 # the scratch project is never saved
        note = "your song was saved and reopened; apply=<rank>, apply_channel=<n> puts a sound on a channel"
        if skipped:
            note += f"; skipped {len(skipped)} preset(s) that can't be auditioned on a plugin channel"
    ranked = sorted(results, key=lambda r: -r["score"])
    for k, r in enumerate(ranked, 1):
        r["rank"] = k
    _state({"audition": {"want": want, "ranked": ranked}})
    out = {"want": want, "ranked": ranked, "previews": prev_dir, "note": note,
           "previews_kept": "the last audition only (fl-headless's state folder)"}
    if query is not None and skipped:
        out["skipped"] = skipped
    if old_note:
        out["old_previews"] = old_note
    if want and not fl_sound.targets(want):
        out["ranking_note"] = "none of the wish's words is known to the ranking: ordered by nothing in particular"
    return out


AUDITION_DIR = None              # tests: a folder of their own; default <state folder>/audition


def _audition_dir():
    """(work folder, previews folder, note): fl-headless's own state folder (writable as one of its temp roots),
    the previews emptied first (only the last run is kept). Previews older versions left in the first FLH_ROOTS
    folder (_audition) are moved to the Recycle Bin once (Windows), else named in the note."""
    aud = AUDITION_DIR or os.path.join(os.path.dirname(STATE), "audition")
    k = os.path.normcase(os.path.abspath(aud))
    if k not in _TEMP_ROOTS:
        _TEMP_ROOTS.append(k)
    prev_dir = os.path.join(aud, "previews")
    shutil.rmtree(prev_dir, ignore_errors=True)                   # our own folder: the previous run's previews
    os.makedirs(prev_dir, exist_ok=True)
    note = None
    for r in roots()[:1]:
        old = os.path.join(r, "_audition")
        if os.path.isdir(old) and os.path.isfile(os.path.join(old, "audition.flp")):
            try:
                files_recycle([old])
                note = f"the old audition folder {old} (previews of earlier versions) went to the Recycle Bin"
            except Exception:                                     # noqa: BLE001 (not Windows / no Recycle Bin)
                note = f"an old audition folder from earlier versions is left at {old}: it can be deleted"
    return aud, prev_dir, note


def _auto_job(kind, est_s, fn, kw, background, fl=None):
    """Run long tools as a background job (remote connections cut calls at ~60 s); short ones inline. fl: does this
    run drive FL (see _start_job); None = decided from the kind and arguments."""
    if background is None:
        background = est_s is None or est_s > 40
    if background:
        r = _start_job(kind, fn, fl=_job_drives_fl(kind, fl, kw), **kw)
        r["note"] = f"running in the background (about {int(est_s) if est_s else '?'} s): fl_job('{r['job']}') for the result"
        if est_s:
            r["eta_s"] = int(round(est_s))
        return r
    return fn(**kw)


def _est_listen_s(start_bar, end_bar, seconds):
    if seconds:
        return float(seconds) + 3
    if end_bar is None:
        return None
    try:
        bpm = float((_bridge_state_light() or {}).get("tempo") or 120)
        a = float(start_bar) if start_bar is not None else BRIDGE.call("song", action="where", bpb=_open_bpb())["bar"]
        return (float(end_bar) - a) * _open_bpb() * 60.0 / bpm + 3
    except Exception:
        return None


def fl_listen_tool(start_bar=None, end_bar=None, seconds=None, save=None, reference=None, max_seconds=600,
                   background=None):
    kw = dict(start_bar=start_bar, end_bar=end_bar, seconds=seconds, save=save, reference=reference,
              max_seconds=max_seconds)
    return _auto_job("listen", _est_listen_s(start_bar, end_bar, seconds), fl_listen, kw, background)


def fl_mix_check_tool(start_bar=None, end_bar=None, seconds=20, tracks=None, background=None, window_s=8):
    one = _est_listen_s(start_bar, end_bar, seconds if end_bar is None else None) or 25
    if window_s and float(window_s) > 0:
        one = min(one, float(window_s) + 1.5)
    n = len(tracks) if tracks else 5
    kw = dict(start_bar=start_bar, end_bar=end_bar, seconds=seconds, tracks=tracks, window_s=window_s)
    return _auto_job("mixcheck", one * (n + 1), fl_mix_check, kw, background)


def fl_audition_tool(want="", query=None, channel=None, count=8, notes=None, hold_s=2.5, apply=None,
                     apply_channel=None, background=None):
    kw = dict(want=want, query=query, channel=channel, count=count, notes=notes, hold_s=hold_s, apply=apply,
              apply_channel=apply_channel)
    est = 15 if apply is not None else (20 if query else 0) + min(int(count), 12) * (float(hold_s) + 2.2)
    return _auto_job("audition", est, fl_audition, kw, background)


def fl_help(question, pages=3):
    """Answer 'how do I ... in FL Studio' from Image-Line's official online manual: the best-matching manual pages
    with their text (menu paths intact), for the assistant to quote and then do the thing with the other tools."""
    import fl_help as H
    return H.answer_context(str(question), pages=int(pages))


def fl_manual_page(page, max_chars=6000):
    """Read one page of the FL Studio manual: a URL, a file name like 'mixer.htm', or a title."""
    import fl_help as H
    return H.page(str(page), max_chars=int(max_chars))


def fl_plugin_presets(index, slot=-1, start=0, limit=300):
    return BRIDGE.call("plugin_presets", index=int(index), slot=int(slot), start=int(start), limit=int(limit))


def fl_plugin_info(index, slot=-1):
    return BRIDGE.call("plugin_info", index=int(index), slot=int(slot))


def fl_plugin_preset_find(index, name, slot=-1, wait_s=3.0):
    """Switch a plugin to the preset whose name matches `name` (exact, else first containing it), live.
    Works for plugins that list their presets to FL (FL's own plugins, FLEX's current pack). Plugins switch
    presets asynchronously, so this steps the needed number of times and then waits until FL reports the name."""
    lst = fl_plugin_presets(index, slot=slot, limit=2000)
    names, cur = lst["names"], lst.get("current") or ""
    if not names:
        raise ValueError(f"{lst.get('plugin')} doesn't list its presets to FL; save the sound as a .fst instead "
                         "(flp_save_sound) and load it with fl_load_preset")
    want = str(name).lower()
    hits = [i for i, n in enumerate(names) if (n or "").lower() == want] or \
           [i for i, n in enumerate(names) if want in (n or "").lower()]
    if not hits:
        return {"found": False, "plugin": lst.get("plugin"), "available": names[:300]}
    target = hits[0]
    if cur not in names:
        raise ValueError(f"FL doesn't report {lst.get('plugin')}'s active preset, so it can't be stepped to a name")
    n = len(names); fwd = (target - names.index(cur)) % n
    steps, direction = (fwd, "next") if fwd <= n - fwd else (n - fwd, "prev")
    for _ in range(steps):
        fl_plugin_preset(index, direction=direction, slot=slot)
    t0 = time.time(); now = cur
    while time.time() - t0 < float(wait_s):
        now = fl_plugin_info(index, slot=slot).get("preset")
        if now == names[target]:
            break
        time.sleep(0.25)
    return {"found": True, "plugin": lst.get("plugin"), "preset": now, "wanted": names[target], "steps": steps,
            "confirmed": now == names[target], "note": "save the project (fl_transport save) to keep it"}


# ============================================================================= files
def _k_weight(f, fs):
    """|H|^2 of the BS.1770 K-weighting filters (pre-filter shelf + RLB high-pass) at frequencies f."""
    import numpy as np
    def biquad_mag2(b, a, w):
        z = np.exp(-1j * w)
        return np.abs((b[0] + b[1] * z + b[2] * z * z) / (a[0] + a[1] * z + a[2] * z * z)) ** 2
    w = 2 * np.pi * f / fs
    import math
    f0, G, Q = 1681.974450955533, 3.999843853973347, 0.7071752369554196
    K = math.tan(math.pi * f0 / fs); Vh = 10 ** (G / 20); Vb = Vh ** 0.4996667741545416
    a0 = 1 + K / Q + K * K
    b1 = [(Vh + Vb * K / Q + K * K) / a0, 2 * (K * K - Vh) / a0, (Vh - Vb * K / Q + K * K) / a0]
    a1 = [1, 2 * (K * K - 1) / a0, (1 - K / Q + K * K) / a0]
    f0, Q = 38.13547087602444, 0.5003270373238773
    K = math.tan(math.pi * f0 / fs)
    a2 = [1, 2 * (K * K - 1) / (1 + K / Q + K * K), (1 - K / Q + K * K) / (1 + K / Q + K * K)]
    b2 = [1, -2, 1]
    return biquad_mag2(b1, a1, w) * biquad_mag2(b2, a2, w)


def _wav_load(path):
    """-> (samples float64 (n, channels) in -1..1, rate, bits). PCM 16/24/32-bit, 32-bit float, FLAC, Ogg."""
    import numpy as np
    d = open(path, "rb").read()
    if d[:4] == b"OggS" or (d[:4] == b"RIFF" and b"OggS" in d[:4096] and d[20:22] in (b"Og", b"Pg", b"Qg", b"og", b"pg", b"qg")):
        import ogg_vorbis_lite as OV                            # FL's compressed factory WAVs / .ogg files
        y, rate = OV.decode(d)
        return y.astype(np.float64), rate, 16
    if d[:4] == b"fLaC":                                         # FLAC finals / stems / FL's FLAC export
        import flh_review
        return flh_review.flac_load(path)
    if d[:4] == b"FORM" and d[8:12] in (b"AIFF", b"AIFC"):
        import fl_audio_edit
        return fl_audio_edit.aiff_load(path)
    if d[:4] != b"RIFF":                                         # MP3 / M4A / WMA: Windows Media Foundation
        import fl_audio_edit
        got = fl_audio_edit._media_load(path)
        if got is not None:
            return got
    if d[:4] != b"RIFF" or d[8:12] != b"WAVE":
        raise ValueError(f"{path}: not a WAV, FLAC, Ogg or AIFF file" +
                         (" (MP3/M4A are read with Windows' own decoders, on Windows)" if
                          str(path).lower().endswith((".mp3", ".m4a", ".aac", ".wma")) else ""))
    i, fmt, data = 12, None, None
    while i + 8 <= len(d):
        cid, n = d[i:i + 4], struct.unpack("<I", d[i + 4:i + 8])[0]
        if cid == b"fmt ":
            fmt = struct.unpack("<HHIIHH", d[i + 8:i + 24])
        elif cid == b"data":
            data = memoryview(d)[i + 8:i + 8 + n]                  # no copy of the samples
        i += 8 + n + (n & 1)
    if not fmt or data is None:
        raise ValueError(f"{path}: missing fmt or data chunk")
    tag, ch, rate, _, _, bits = fmt
    if tag == 0xFFFE:                                            # WAVE_FORMAT_EXTENSIBLE: real tag in the subformat
        tag = 3 if bits == 32 and b"\x03\x00\x00\x00\x00\x00\x10\x00" in d[:200] else 1
    if tag == 3 and bits == 32:
        x = np.frombuffer(data, "<f4").astype(np.float64)
    elif bits == 16:
        x = np.frombuffer(data, "<i2") / 32768.0
    elif bits == 24:
        b = np.frombuffer(data[:len(data) // 3 * 3], np.uint8).reshape(-1, 3)
        v = b[:, 0].astype(np.int32) | (b[:, 1].astype(np.int32) << 8) | (b[:, 2].view(np.int8).astype(np.int32) << 16)
        x = v / float(1 << 23)                                     # top byte signed: no wrap-around pass
    elif bits == 32:
        x = np.frombuffer(data, "<i4") / 2147483648.0
    else:
        raise ValueError(f"{bits}-bit WAV not supported")
    return x[:len(x) // ch * ch].reshape(-1, ch), rate, bits


def _lufs(x, fs):
    import numpy as np
    blk, hop = int(0.4 * fs), int(0.1 * fs)
    f = np.fft.rfftfreq(blk, 1 / fs); kw = _k_weight(f, fs)
    n = max(0, (len(x) - blk) // hop + 1); z = np.zeros(n)
    for c in range(min(x.shape[1], 2)):                          # batched 400 ms blocks (same maths, ~10x faster)
        col = np.ascontiguousarray(x[:, c], dtype=np.float64)
        for a in range(0, n, 256):
            b = min(n, a + 256)
            fr = np.lib.stride_tricks.as_strided(col[a * hop:], shape=(b - a, blk), strides=(hop * 8, 8))
            z[a:b] += (np.abs(np.fft.rfft(fr, axis=1)) ** 2 @ kw) * 2 / (blk * blk)
    L = -0.691 + 10 * np.log10(np.maximum(z, 1e-12)); L = L[L > -70]
    if not len(L):
        return None
    rel = -0.691 + 10 * np.log10(np.mean(10 ** ((L + 0.691) / 10))) - 10
    L2 = L[L > rel]
    return float(-0.691 + 10 * np.log10(np.mean(10 ** ((L2 + 0.691) / 10))))


def _true_peak(x):
    """4x oversampled true peak (dBFS)."""
    import numpy as np
    try:                                                         # overlapped FFT frames: no false edge overs
        import flh_finalize
        if len(x) >= 64:
            return 20 * np.log10(max(float(flh_finalize.tp_envelope(np.asarray(x, dtype=np.float64)).max()), 1e-9))
    except Exception:
        pass
    m = np.abs(x).max(1); top = np.argsort(m)[-64:]; best = float(m.max()) if len(m) else 0.0
    for i in top:
        a, b = max(0, i - 32), min(len(x), i + 32)
        for c in range(x.shape[1]):
            seg = x[a:b, c]; n = len(seg)
            if n < 4:
                continue
            S = np.fft.rfft(seg); up = np.fft.irfft(S, n * 4) * 4
            best = max(best, float(np.abs(up).max()))
    return 20 * np.log10(max(best, 1e-9))


def audio_info(path):
    """Duration, sample peak, RMS and integrated loudness (LUFS, BS.1770 gating) of a WAV file, on this PC."""
    try:
        import numpy as np
    except ImportError:
        return {"path": path, "note": "numpy not installed on this PC: pip install numpy"}
    x, fs, bits = _wav_load(path)
    peak = float(np.max(np.abs(x))) if len(x) else 0.0
    lufs = _lufs(x, fs)
    return {"path": path, "seconds": round(len(x) / fs, 2), "rate": fs, "channels": x.shape[1], "bits": bits,
            "peak_dbfs": round(20 * np.log10(max(peak, 1e-9)), 2),
            "rms_dbfs": round(10 * np.log10(max(float(np.mean(x ** 2)), 1e-12)), 2),
            "lufs": None if lufs is None else round(lufs, 2)}


BANDS = [("sub", 20, 60), ("bass", 60, 250), ("low_mid", 250, 800), ("mid", 800, 2500), ("presence", 2500, 6000),
         ("air", 6000, 16000)]
PROFILES = os.path.join(os.path.dirname(STATE), "profiles")
_WIN_RESERVED = {"con", "prn", "aux", "nul", *(f"com{i}" for i in range(1, 10)), *(f"lpt{i}" for i in range(1, 10))}


def safe_file_name(name, what="name", limit=64):
    """A user-chosen name that becomes a file name in one of fl-headless's own folders (collection profiles, sound
    profiles). Normal names work - apostrophes, brackets, &, commas, #, accents: "Mike's Songs", "Album (2025)".
    Refused: path separators, '..', characters Windows can't put in a file name (< > : " | ? *), control characters,
    reserved Windows names (CON, NUL, COM1...), a trailing dot, more than `limit` characters. Returns it stripped."""
    n = str(name if name is not None else "").strip()
    why = None
    if not n:
        why = "it's empty"
    elif len(n) > limit:
        why = f"it's longer than {limit} characters"
    elif any(c in n for c in '/\\<>:"|?*'):
        why = "it holds one of / \\ < > : \" | ? * (not allowed in a file name)"
    elif any(ord(c) < 32 or ord(c) == 127 for c in n):
        why = "it holds control characters"
    elif ".." in n:
        why = "it holds '..'"
    elif n.endswith("."):
        why = "it ends with a dot"
    elif n.split(".")[0].strip().lower() in _WIN_RESERVED:
        why = "it's a name Windows reserves (CON, PRN, AUX, NUL, COM1-9, LPT1-9)"
    if why:
        raise ValueError(f"{what} {str(name)[:60]!r} can't be used: {why}")
    return n


def _profile_file(name):
    """profiles/<name>.json for a sound-profile name (safe_file_name rules: no folders, no '..')."""
    n = safe_file_name(name, "profile name")
    return os.path.join(PROFILES, n + ".json")


def _spectrum(y, fs):
    """Average power spectrum of a mono signal (Hann frames)."""
    import numpy as np
    n = 8192; w = np.hanning(n); acc = None; k = 0
    for i in range(0, max(1, len(y) - n), n):
        seg = y[i:i + n]
        if len(seg) < n:
            break
        S = np.abs(np.fft.rfft(seg * w)) ** 2
        acc = S if acc is None else acc + S; k += 1
    if acc is None:
        return np.fft.rfftfreq(n, 1 / fs), np.zeros(n // 2 + 1)
    return np.fft.rfftfreq(n, 1 / fs), acc / k


def _measure(x, fs):
    import numpy as np
    mid = x.mean(1) if x.shape[1] > 1 else x[:, 0]
    side = (x[:, 0] - x[:, 1]) / 2 if x.shape[1] > 1 else np.zeros_like(mid)
    f, S = _spectrum(mid, fs); tot = S[(f >= 20) & (f < 16000)].sum() + 1e-20
    bands = {name: round(10 * np.log10(S[(f >= a) & (f < b)].sum() / tot + 1e-12), 2) for name, a, b in BANDS}
    cen = float((S * f).sum() / (S.sum() + 1e-20))
    em, es = float(np.mean(mid ** 2)) + 1e-20, float(np.mean(side ** 2)) + 1e-20
    corr = float(np.corrcoef(x[:, 0], x[:, 1])[0, 1]) if x.shape[1] > 1 and np.std(x[:, 0]) > 0 and np.std(x[:, 1]) > 0 else 1.0
    pk = float(np.abs(x).max()) + 1e-12; rms = float(np.sqrt(np.mean(x ** 2))) + 1e-12
    L = _lufs(x, fs)
    return {"lufs": None if L is None else round(L, 2), "peak_dbfs": round(20 * np.log10(pk), 2),
            "crest_db": round(20 * np.log10(pk / rms), 2), "bands_db": bands, "centroid_hz": int(cen),
            "width_db": round(10 * np.log10(es / em), 2), "lr_correlation": round(corr, 3)}


def _verdict(cur, ref):
    out = []
    d = {k: cur["bands_db"][k] - ref["bands_db"][k] for k in cur["bands_db"]}
    if d["low_mid"] > 1.5: out.append(f"muddier than the reference (+{d['low_mid']:.1f} dB at 250-800 Hz)")
    if d["low_mid"] < -2: out.append(f"less body than the reference ({d['low_mid']:.1f} dB at 250-800 Hz)")
    if d["presence"] > 2: out.append(f"harsher (+{d['presence']:.1f} dB at 2.5-6 kHz)")
    if d["presence"] < -2.5: out.append(f"less clarity ({d['presence']:.1f} dB at 2.5-6 kHz)")
    if d["bass"] < -2.5: out.append(f"thinner low end ({d['bass']:.1f} dB at 60-250 Hz)")
    if d["bass"] > 2.5: out.append(f"heavier low end (+{d['bass']:.1f} dB at 60-250 Hz)")
    if d["air"] < -3: out.append(f"duller top ({d['air']:.1f} dB above 6 kHz)")
    if d["air"] > 3: out.append(f"brighter top (+{d['air']:.1f} dB above 6 kHz)")
    dw = cur["width_db"] - ref["width_db"]
    if dw < -3: out.append(f"narrower stereo ({dw:.1f} dB side level)")
    if dw > 3: out.append(f"wider stereo (+{dw:.1f} dB side level)")
    if cur.get("lufs") is not None and ref.get("lufs") is not None and abs(cur["lufs"] - ref["lufs"]) > 1:
        out.append(f"loudness {cur['lufs'] - ref['lufs']:+.1f} LU vs the reference")
    return out or ["tonally consistent with the reference"]


def audio_analyze(path, sections=None, window_s=20, reference=None, save_profile=None):
    """'Ears': loudness, tone (6 bands), stereo width, peaks and clipping for the whole file and per section
    (sections=[{name, start_s, end_s}] or fixed windows), plus a plain-language comparison against a reference
    (a saved profile name like 'My Song final', or a WAV). save_profile=<name> stores this file as a reference."""
    import numpy as np
    x, fs, _ = _wav_load(path)
    whole = _measure(x, fs)
    whole["seconds"] = round(len(x) / fs, 2)
    whole["clipped_samples"] = int((np.abs(x) >= 0.999).sum())
    whole["true_peak_dbfs"] = round(_true_peak(x), 2)
    if not sections:
        w = int(window_s)
        sections = [{"name": f"{t // 60}:{t % 60:02d}", "start_s": t, "end_s": min(t + w, len(x) / fs)}
                    for t in range(0, int(len(x) / fs), w)]
    parts = []
    for sec in sections:
        a, b = int(float(sec["start_s"]) * fs), min(len(x), int(float(sec["end_s"]) * fs))
        if b - a < fs:
            continue
        m = _measure(x[a:b], fs); m["name"] = sec.get("name"); parts.append(m)
    res = {"path": path, "whole": whole, "sections": parts}
    ref = None
    if reference:
        rp = os.path.join(PROFILES, str(reference) + ".json")
        if str(reference).lower().endswith(".json") and os.path.isfile(str(reference)):
            ref = json.load(open(str(reference)))
        elif os.path.isfile(rp):
            ref = json.load(open(rp))
        elif os.path.isfile(str(reference)):
            rx, rfs, _ = _wav_load(reference); ref = _measure(rx, rfs)
        else:
            have = [os.path.splitext(f)[0] for f in os.listdir(PROFILES)] if os.path.isdir(PROFILES) else []
            raise FileNotFoundError(f"no reference '{reference}'. Saved profiles: {', '.join(have) or 'none'}")
        res["reference"] = str(reference)
        res["compared_to_reference"] = _verdict(whole, ref)
        res["sections_vs_reference"] = [{"name": p["name"], "notes": _verdict(p, ref)} for p in parts]
    if save_profile:
        _json_write(_profile_file(save_profile), whole)
        res["saved_profile"] = str(save_profile)
    return res


def audio_profiles():
    """Saved reference profiles (name -> loudness / tone summary)."""
    if not os.path.isdir(PROFILES):
        return {}
    return {os.path.splitext(f)[0]: json.load(open(os.path.join(PROFILES, f)))
            for f in sorted(os.listdir(PROFILES)) if f.endswith(".json")}


FINISH_DEFAULT = {"lufs": -14.0, "true_peak": -1.0, "bits": 24, "fade_s": 2.5}   # common streaming reference


def _finish_target():
    """The active collection profile's finish target (flh_store), else FINISH_DEFAULT."""
    t = dict(FINISH_DEFAULT)
    try:
        st = sys.modules.get("flh_store")
        if st is not None and getattr(st, "H", None):
            t.update({k: v for k, v in (st.profile_get().get("finish") or {}).items() if v is not None})
    except Exception:
        pass
    return t


def audio_finish(input, output, target_lufs=None, max_true_peak=None, fade_s=None, floor_db=-58.0, bits=None,
                 end_s=None, delete_input=False, save_profile=None):
    """Finishing pass on this PC: trim lead silence and the dead tail (late pedal clicks ignored), fade into the
    ring, gain to target loudness with true peak capped, write FLAC (lossless, about half a WAV).
    Unset target / peak / fade / bits come from the collection profile's finish, else -14 LUFS, -1 dBTP, 24-bit."""
    import numpy as np
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    import flac_lite
    tgt = _finish_target()
    target_lufs = tgt["lufs"] if target_lufs is None else target_lufs
    max_true_peak = tgt["true_peak"] if max_true_peak is None else max_true_peak
    fade_s = tgt.get("fade_s", 2.5) if fade_s is None else fade_s
    bits = tgt.get("bits", 24) if bits is None else bits
    if not output.lower().endswith(".flac"):
        raise ValueError("output must be a .flac file")
    writable(output)
    if delete_input:
        writable(input)
    x, fs, _ = _wav_load(input)
    if len(x) < int(0.4 * fs):
        raise ValueError(f"the file is {len(x) / fs:.2f} s long: loudness (LUFS) needs at least 0.4 s of audio")
    mono = np.abs(x).max(1)
    hop = fs // 20; nh = len(x) // hop
    rms = np.sqrt((x[:nh * hop] ** 2).mean(1).reshape(nh, hop).mean(1))
    sm = np.convolve(rms, np.ones(30) / 30, mode="same"); db = 20 * np.log10(sm + 1e-12)
    rel = min(0.0, float(db.max()) + 10.0)        # the gates follow the file's own level (a quiet file isn't "silent")
    above = np.nonzero(mono > 10 ** ((-60 + rel) / 20))[0]
    if not len(above) or float(mono.max()) <= 1e-7:
        raise ValueError("the file is silent")
    start = max(0, int(above[0]) - int(0.05 * fs))
    if end_s is None:
        last_music = int(np.nonzero(db > -40 + rel)[0][-1]) if (db > -40 + rel).any() else len(db) - 1
        below = np.nonzero(db[last_music:] < floor_db + rel)[0]
        end_i = last_music + (int(below[0]) if len(below) else len(db) - 1 - last_music)
        end = min(len(x), end_i * hop + int(0.3 * fs))
    else:
        end = min(len(x), int(float(end_s) * fs))
    y = x[start:end].copy(); n = len(y)
    fi = min(n, int(0.005 * fs)); y[:fi] *= np.linspace(0, 1, fi)[:, None]
    fo = min(n, int(float(fade_s) * fs)); y[n - fo:] *= np.linspace(1, 0, fo)[:, None]
    if n < int(0.4 * fs):
        raise ValueError(f"after trimming only {n / fs:.2f} s is left: loudness (LUFS) needs at least 0.4 s")
    L = _lufs(y, fs); tp = _true_peak(y)
    if L is None:
        raise ValueError("the audio is too quiet to measure (under the -70 LUFS gate)")
    gain = float(target_lufs) - L
    lim = None
    if tp + gain > float(max_true_peak) - 0.05:                 # margin: dither must not push it over
        limit = globals().get("_finalize_limit")                # flh_finalize's limiter, when loaded
        if limit is not None:
            y, lim = limit(y, fs, float(target_lufs), float(max_true_peak))
            gain = float(lim["gain_db"])
        else:
            gain = float(max_true_peak) - 0.05 - tp
            y *= 10 ** (gain / 20)
    else:
        y *= 10 ** (gain / 20)
    full = (1 << (int(bits) - 1)) - 1
    if int(bits) == 16:                                         # TPDF dither down to 16 bits
        rng = np.random.default_rng(1)
        y = y * full + (rng.random(y.shape) - rng.random(y.shape))
    else:
        y = y * full
    q = np.clip(np.round(y), -full - 1, full).astype(np.int64)
    info = flac_lite.encode(output, q, fs, int(bits))
    res = {"output": output, "bytes": info["bytes"], "length": f"{int(n / fs // 60)}:{n / fs % 60:05.2f}",
           "trim_start_s": round(start / fs, 3), "end_s": round(end / fs, 3), "gain_db": round(float(gain), 2),
           "lufs": round(_lufs(q / float(full), fs), 2), "true_peak_dbfs": round(_true_peak(q / float(full)), 2),
           "bits": int(bits), "limited": bool(lim and lim.get("limited"))}
    if lim and lim.get("limited"):
        res["gain_reduction_max_db"] = lim.get("gain_reduction_max_db")
        if lim.get("warning"):
            res["warning"] = lim["warning"]
    miss = float(target_lufs) - res["lufs"]
    if miss > 0.5:                                              # never a silent miss
        res["below_target_db"] = round(miss, 2)
        res["note"] = (lim.get("note") if lim and lim.get("note") else
                       f"the {float(max_true_peak):g} dBTP true-peak ceiling capped the gain" +
                       ("" if lim else " (no limiter loaded: audio_limit / fl_finalize limit to the target)"))
    if save_profile:                                            # remember this final as a tone/loudness reference
        prof = _measure(q / float(full), fs); prof["seconds"] = round(n / fs, 2)
        _json_write(_profile_file(save_profile), prof)
        res["saved_profile"] = str(save_profile)
    if delete_input:
        res["input_recycled"] = files_recycle([input])["recycled"]
    return res


def files_hash(paths):
    """SHA-256, size and modified time of files (to confirm a file arrived intact)."""
    import hashlib
    out = []
    for p in paths:
        h = hashlib.sha256()
        with open(p, "rb") as f:
            for chunk in iter(lambda: f.read(1 << 20), b""):
                h.update(chunk)
        st = os.stat(p)
        out.append({"path": p, "sha256": h.hexdigest(), "bytes": st.st_size,
                    "modified": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(st.st_mtime))})
    return out


BACKUPS = os.path.join(os.path.dirname(STATE), "backups")


BACKUP_KEEP = 40                                                  # newest backups kept per project
BACKUP_TOTAL_MB = 2048                                            # all projects together (oldest go first)


def _backup_dir(path):
    """Each project's backups live in their own folder, keyed by its full path: two 'song.flp' in different folders
    never share (or rotate away) each other's history."""
    import hashlib
    return os.path.join(BACKUPS, hashlib.sha1(_ud_key(path).encode("utf-8")).hexdigest()[:12])


LEGACY_BACKUPS = os.path.join(BACKUPS, "legacy")              # 1.16's flat backups no project could be pinned to
_LEGACY_RE = re.compile(r"^\d{8}-\d{6}-\d{3}-(?:\d+-)?(.+\.flp)$", re.I)
_MIGRATED = {"done": False}


def _migrate_flat_backups():
    """Once: backups from 1.16 sat flat in backups/<time>-<name>.flp. Each moves into its project's own folder when
    exactly one project of that file name exists in FLH_ROOTS; otherwise into backups/legacy/, where flp_versions
    lists it as a name match and flp_restore takes it with a warning. Nothing is deleted."""
    if _MIGRATED["done"]:
        return
    _MIGRATED["done"] = True
    try:
        flat = [f for f in glob.glob(os.path.join(BACKUPS, "*.flp")) if os.path.isfile(f)]
    except OSError:
        return
    for f in flat:
        m = _LEGACY_RE.match(os.path.basename(f))
        name = m.group(1) if m else os.path.basename(f)
        try:
            hits = _find_by_stem(os.path.splitext(name)[0])
        except Exception:
            hits = []
        hits = [h for h in hits if os.path.basename(h).lower() == name.lower()]
        try:
            if len(hits) == 1:
                d = _backup_dir(hits[0]); os.makedirs(d, exist_ok=True)
                pt = os.path.join(d, "project.txt")
                if not os.path.isfile(pt):
                    with open(pt, "w", encoding="utf-8") as fh:
                        fh.write(os.path.abspath(hits[0]))
                dst = os.path.join(d, os.path.basename(f))
            else:
                os.makedirs(LEGACY_BACKUPS, exist_ok=True); dst = os.path.join(LEGACY_BACKUPS, os.path.basename(f))
            if not os.path.exists(dst):
                os.replace(f, dst)
        except OSError:
            pass


def _legacy_versions(path):
    """Old flat backups (backups/legacy/) whose file name matches this project's: name match only."""
    _migrate_flat_backups()
    want = os.path.basename(path).lower(); out = []
    for f in glob.glob(os.path.join(LEGACY_BACKUPS, "*.flp")):
        m = _LEGACY_RE.match(os.path.basename(f))
        if (m.group(1) if m else os.path.basename(f)).lower() == want:
            out.append(f)
    return sorted(out, key=os.path.basename)


def _backup(path, keep=None, data=None):
    """Copy a project (or `data`, bytes standing for it) into its own backup folder before it is overwritten. Keeps
    the newest `keep` per project and a total size cap; a project's newest backup is never deleted."""
    keep = int(keep or BACKUP_KEEP)
    d = _backup_dir(path); os.makedirs(d, exist_ok=True)
    try:
        with open(os.path.join(d, "project.txt"), "w", encoding="utf-8") as f:
            f.write(os.path.abspath(path))                         # whose backups these are (flp_restore checks it)
    except OSError:
        pass
    stem = time.strftime("%Y%m%d-%H%M%S-") + f"{int(time.time() * 1000) % 1000:03d}-"
    dst = os.path.join(d, stem + os.path.basename(path)); n = 2
    while os.path.exists(dst):                                     # two backups in the same millisecond
        dst = os.path.join(d, f"{stem}{n}-" + os.path.basename(path)); n += 1
    if data is not None:
        with open(dst + ".tmp", "wb") as f:
            f.write(data)
        os.replace(dst + ".tmp", dst)
    else:
        shutil.copy2(path, dst)
    olds = _versions(path)
    for f in olds[:-keep]:
        _remove_own(f)                                             # our own backup copies only
    _backup_cap()
    return dst


def _remove_own(f):
    try:
        os.remove(f)
    except OSError:
        pass


def _backup_cap():
    """Total size cap over every project's backups: the oldest go first, but each project keeps its newest one."""
    try:
        files = []
        for sub in os.listdir(BACKUPS):
            fs = sorted(glob.glob(os.path.join(BACKUPS, sub, "*.flp")), key=os.path.basename)
            files += [(os.path.basename(f), f, i == len(fs) - 1, os.path.getsize(f)) for i, f in enumerate(fs)]
        total = sum(x[3] for x in files); cap = BACKUP_TOTAL_MB * 1024 * 1024
        for _n, f, newest, size in sorted(files):
            if total <= cap:
                break
            if not newest:
                _remove_own(f); total -= size
    except OSError:
        pass


def _versions(path):
    """This project's backups, oldest first (only ones made for this exact path)."""
    _migrate_flat_backups()
    return sorted(glob.glob(os.path.join(_backup_dir(path), "*.flp")), key=os.path.basename)


NOTE_NAMES = "C C# D Eb E F F# G Ab A Bb B".split()


def _snapshot(d):
    ev, chans, fx = _structure(d); P = _ppq(d)
    notes, tempos = _song(d, ev)
    pats = _patterns(d, ev)
    return {"P": P, "notes": notes, "tempos": tempos,
            "channels": {c["index"]: (c.get("name"), c.get("plugin")) for c in chans.values()},
            "effects": {f"{t}:{sl}": f.get("plugin") for (t, sl), f in fx.items()},
            "patterns": {i: p["name"] for i, p in pats.items()},
            "clips": sorted((struct.unpack("<I", r[0:4])[0], struct.unpack("<H", r[6:8])[0] - PATTERN_BASE,
                             struct.unpack("<I", r[8:12])[0]) for _, _, r in _clips(d, ev))}


def flp_diff(path, other=None, examples=8):
    """What changed between two versions of a project. Default: the newest automatic backup vs. the file now
    (e.g. to see what was edited by hand in FL since the last write)."""
    if other is None:
        vs = _versions(path) or _legacy_versions(path)
        if not vs:
            raise ValueError("no earlier version of this project in the backup folder")
        old_p, new_p = vs[-1], path
    else:
        old_p, new_p = path, other
    dB = _load(new_p); A, B = _snapshot(_load(old_p)), _snapshot(dB); P = B["P"]
    bt = _song_bar_ticks(dB, _events(dB), P)                      # bar.beat in the project's time signature
    def where(t):
        b, r = divmod(t, bt); return f"{b + 1}.{r // P + 1}"
    def nm(k):
        return NOTE_NAMES[k % 12] + str(k // 12 - 1)
    out = {"old": old_p, "new": new_p, "notes": {}}
    from collections import Counter
    for ch in sorted({n[2] for n in A["notes"]} | {n[2] for n in B["notes"]}):
        ca = Counter((n[0], n[3], n[1], n[4]) for n in A["notes"] if n[2] == ch)
        cb = Counter((n[0], n[3], n[1], n[4]) for n in B["notes"] if n[2] == ch)
        added, removed = cb - ca, ca - cb
        if added or removed:
            pa = Counter((p, k) for p, k, _, _ in added.elements()); pr = Counter((p, k) for p, k, _, _ in removed.elements())
            moved_len = sum((pa & pr).values())
            out["notes"][ch] = {"added": sum(added.values()) - moved_len, "removed": sum(removed.values()) - moved_len,
                                "changed_length_or_velocity": moved_len,
                                "examples": [f"+ {nm(k)} at bar {where(p)}" for p, k, _, _ in list(added.elements())[:examples]]
                                + [f"- {nm(k)} at bar {where(p)}" for p, k, _, _ in list(removed.elements())[:examples]]}
    if A["tempos"] != B["tempos"]:
        out["tempo"] = {"old_events": len(A["tempos"]), "new_events": len(B["tempos"]),
                        "old_start_bpm": A["tempos"][0][1], "new_start_bpm": B["tempos"][0][1]}
    for key in ("channels", "effects", "patterns"):
        a, b = A[key], B[key]
        ch = {str(k): {"old": a.get(k), "new": b.get(k)} for k in set(a) | set(b) if a.get(k) != b.get(k)}
        if ch:
            out[key] = ch
    if A["clips"] != B["clips"]:
        out["playlist"] = {"old_clips": len(A["clips"]), "new_clips": len(B["clips"])}
    out["identical_music"] = not out["notes"] and "tempo" not in out and "playlist" not in out
    return out


def flp_versions(path):
    """Automatic backups of a project (newest last); restore one with flp_restore. Backups from before 1.17 that
    couldn't be pinned to one project are listed with legacy: 'name match only'."""
    old = [{"backup": v, "bytes": os.path.getsize(v), "legacy": "name match only (an older fl-headless's backup of "
            "a project with this file name)"} for v in _legacy_versions(path)]
    return old + [{"backup": v, "bytes": os.path.getsize(v)} for v in _versions(path)]


def flp_restore(path, backup):
    """Put a backup back in place of the project (the current file is backed up first)."""
    _migrate_flat_backups()
    folder = os.path.normcase(os.path.dirname(os.path.abspath(backup)))
    legacy = folder == os.path.normcase(os.path.abspath(LEGACY_BACKUPS))
    if legacy:
        m = _LEGACY_RE.match(os.path.basename(backup))
        if (m.group(1) if m else os.path.basename(backup)).lower() != os.path.basename(path).lower():
            raise ValueError("that legacy backup is of a project with another file name; pick one flp_versions lists "
                             "for this project")
    elif folder == os.path.normcase(os.path.abspath(BACKUPS)) and _LEGACY_RE.match(os.path.basename(backup)):
        for moved in (os.path.join(_backup_dir(path), os.path.basename(backup)),   # a path from before the
                      os.path.join(LEGACY_BACKUPS, os.path.basename(backup))):     # migration: where it went
            if os.path.isfile(moved):
                return flp_restore(path, moved)
    if not legacy and folder != os.path.normcase(os.path.abspath(_backup_dir(path))):
        raise ValueError("backup must come from flp_versions of this same project (backups of another project, even "
                         "one with the same name, can't be restored over it)")
    _save(_load(backup), path)
    r = {"restored": path, "from": backup}
    if legacy:
        r["warning"] = ("this backup is from an older fl-headless and matched by file name only: check it's the right "
                        "song (the previous file is backed up: flp_versions)")
    return r


def _resolve_preset(preset):
    """A .fst path from a path or a name (the sound library wins over FL's preset folders)."""
    if str(preset).lower().endswith(".fst"):
        return preset
    hits = fl_find_presets(preset, limit=10)["presets"]
    exact = [h for h in hits if os.path.splitext(os.path.basename(h))[0].lower() == str(preset).lower()]
    mine = [h for h in exact if os.path.normcase(os.path.dirname(h)) == os.path.normcase(SOUNDS)]
    exact = mine or exact
    if not hits:
        raise FileNotFoundError(f"no .fst preset matching '{preset}'")
    if len(exact) != 1 and len(hits) > 1:
        raise ValueError("several presets match; pass one of these paths: " + "; ".join(hits))
    return (exact or hits)[0]


def fl_load_preset(preset, channel=None, track=None, slot=None, project=None):
    """Load a .fst preset (path, or a name to search for) onto a channel or mixer slot of a project, even while it
    is open in FL: FL saves, the project is written (backup kept) and FL reloads it in the same window."""
    if not preset.lower().endswith(".fst"):
        hits = fl_find_presets(preset, limit=10)["presets"]
        exact = [h for h in hits if os.path.splitext(os.path.basename(h))[0].lower() == preset.lower()]
        mine = [h for h in exact if os.path.normcase(os.path.dirname(h)) == os.path.normcase(SOUNDS)]
        exact = mine or exact                                    # the sound library wins
        if not hits:
            raise FileNotFoundError(f"no .fst preset matching '{preset}'")
        if len(exact) != 1 and len(hits) > 1:
            raise ValueError("several presets match; pass one of these paths: " + "; ".join(hits))
        preset = (exact or hits)[0]
    if project is None:
        project, _ = _open_project_guess()
        if not project:
            raise ValueError("no project given and the open one couldn't be identified")
    project = os.path.abspath(project); writable(project)
    # the open project is saved, edited and reloaded in place (never by closing FL)
    res = _with_open_project(project, project,
                             lambda: flp_load_plugin(project, project, preset, channel=channel, track=track, slot=slot))
    backup = (_versions(project) or [None])[-1]
    res.update({"preset": preset, "backup": backup})
    return res


def files_list(folder, pattern="*"):
    out = []
    for p in sorted(glob.glob(os.path.join(folder, pattern))):
        try:
            st = os.stat(p)
        except OSError:                                          # broken shortcut / junction (My Pictures...)
            out.append({"name": os.path.basename(p), "dir": False, "bytes": 0, "modified": None, "unreadable": True})
            continue
        out.append({"name": os.path.basename(p), "dir": os.path.isdir(p), "bytes": st.st_size,
                    "modified": time.strftime("%Y-%m-%d %H:%M", time.localtime(st.st_mtime))})
    return out


def _has_recycle_bin(path):
    """(ok, why): the drive holding `path` is a local fixed disk with a Recycle Bin. Network shares, USB sticks and
    other removable or exFAT drives have none - Windows would delete there permanently, so fl-headless refuses."""
    import ctypes
    from ctypes import wintypes
    root = os.path.splitdrive(os.path.abspath(path))[0]
    if not root or root.startswith("\\\\"):
        return False, "it's on a network share (no Recycle Bin there)"
    root += "\\"
    k32 = ctypes.WinDLL("kernel32", use_last_error=True)
    k32.GetDriveTypeW.argtypes = [wintypes.LPCWSTR]; k32.GetDriveTypeW.restype = wintypes.UINT
    kind = k32.GetDriveTypeW(root)
    if kind != 3:                                                  # DRIVE_FIXED
        return False, f"drive {root} isn't a local fixed disk (type {kind}: removable, network or optical)"

    class SHQUERYRBINFO(ctypes.Structure):
        _fields_ = [("cbSize", wintypes.DWORD), ("i64Size", ctypes.c_longlong), ("i64NumItems", ctypes.c_longlong)]
    info = SHQUERYRBINFO(); info.cbSize = ctypes.sizeof(info)
    sh = ctypes.WinDLL("shell32", use_last_error=True)
    sh.SHQueryRecycleBinW.argtypes = [wintypes.LPCWSTR, ctypes.POINTER(SHQUERYRBINFO)]
    sh.SHQueryRecycleBinW.restype = ctypes.c_long
    if sh.SHQueryRecycleBinW(root, ctypes.byref(info)) != 0:      # PC-VERIFY: fails on drives without a bin
        return False, f"drive {root} has no Recycle Bin"
    return True, ""


def _recycle_shell(path):
    """Recycle a file/folder (or a list of them, in one call) with the shell's own API. FOF_ALLOWUNDO = to the Recycle Bin; FOF_WANTNUKEWARNING:
    if Windows can't recycle it after all (too big for the bin...), it asks the user instead of deleting it
    permanently - answering No cancels, which is reported as a refusal. Returns (code, aborted)."""
    import ctypes
    from ctypes import wintypes

    class SHFILEOPSTRUCTW(ctypes.Structure):
        _fields_ = [("hwnd", wintypes.HWND), ("wFunc", wintypes.UINT), ("pFrom", wintypes.LPCWSTR),
                    ("pTo", wintypes.LPCWSTR), ("fFlags", ctypes.c_ushort), ("fAnyOperationsAborted", wintypes.BOOL),
                    ("hNameMappings", ctypes.c_void_p), ("lpszProgressTitle", wintypes.LPCWSTR)]
    FO_DELETE, FOF_SILENT, FOF_NOCONFIRMATION, FOF_ALLOWUNDO, FOF_NOERRORUI, FOF_WANTNUKEWARNING = \
        3, 0x4, 0x10, 0x40, 0x400, 0x4000
    # PC-VERIFY: with these flags a file too big for the bin shows Windows' 'delete permanently?' question
    many = [path] if isinstance(path, str) else list(path)          # several in one shell call (one undo group)
    op = SHFILEOPSTRUCTW(wFunc=FO_DELETE, pFrom="\0".join(os.path.abspath(x) for x in many) + "\0",
                         fFlags=FOF_ALLOWUNDO | FOF_NOCONFIRMATION | FOF_SILENT | FOF_NOERRORUI | FOF_WANTNUKEWARNING)
    sh = ctypes.WinDLL("shell32", use_last_error=True)
    sh.SHFileOperationW.argtypes = [ctypes.POINTER(SHFILEOPSTRUCTW)]; sh.SHFileOperationW.restype = ctypes.c_int
    return sh.SHFileOperationW(ctypes.byref(op)), bool(op.fAnyOperationsAborted)


def _recycle_tree(p, depth=0):
    """Recycle a folder piece by piece (each child, deeper ones first when a child is refused too), then the folder
    itself. Never deletes permanently; stops quietly where Windows still refuses."""
    for name in sorted(os.listdir(p)):
        c = os.path.join(p, name)
        try:
            code, aborted = _recycle_shell(c)
        except Exception:                                         # noqa: BLE001
            code, aborted = 1, False
        if aborted:
            return
        if os.path.exists(c) and os.path.isdir(c) and depth < 3:
            _recycle_tree(c, depth + 1)
    if os.path.isdir(p):
        try:
            _recycle_shell(p)
        except Exception:                                         # noqa: BLE001
            pass


def files_recycle(paths):
    """Move files/folders to the Windows Recycle Bin (restorable). Never deletes permanently: a target on a drive
    without a Recycle Bin (network share, USB stick) is refused, and nothing else is touched."""
    if not IS_WINDOWS:
        raise RuntimeError("files_recycle uses the Windows Recycle Bin: " + WINDOWS_ONLY_NOTE)
    if isinstance(paths, str):
        paths = [paths]
    for p in paths:                                               # check everything before touching anything
        writable(p)
        if not os.path.exists(p):
            raise FileNotFoundError(p)
        ok, why = _has_recycle_bin(p)
        if not ok:
            raise RuntimeError(f"not recycled: {p} - {why}. Windows would delete it permanently, so fl-headless "
                               "won't; delete it yourself if you're sure")
    done = []
    if len(paths) > 3:                                            # many: one shell call (one undo) per 200
        for i in range(0, len(paths), 200):
            chunk = paths[i:i + 200]
            try:
                _recycle_shell(chunk)
            except Exception:                                     # noqa: BLE001 - what's left goes one by one
                pass
            done += [p for p in chunk if not os.path.exists(p)]
        paths = [p for p in paths if p not in done]
    for p in paths:
        try:
            code, aborted = _recycle_shell(p)
        except Exception as e:                                   # noqa: BLE001
            raise RuntimeError(f"could not recycle {p}: {e}" + (f" (already recycled: {done})" if done else ""))
        if os.path.isdir(p) and not aborted and code:             # Windows refuses some whole folders (shell code
            _recycle_tree(p)                                      # 120 on a deep sandbox - PC 2026-10-22) that go
            code = 0 if not os.path.exists(p) else code           # fine piece by piece: children first, then it
        if os.path.exists(p) or code or aborted:
            raise RuntimeError(f"could not recycle {p} (shell code {code}{', cancelled' if aborted else ''}); nothing "
                               "was deleted permanently" + (f" (already recycled: {done})" if done else ""))
        done.append(p)
    return {"recycled": done}


# ============================================================================= MCP tool table
def _p(type_, desc="", optional=False, **extra):
    return dict({"type": type_, "description": desc}, **extra), optional


# ----------------------------------------------------------------------------- playlist clip editing
CLIP_MUTE = 0x2000                                               # item flags bit, set by FL's clip "Mute"


def _playlist_event(d, ev, which=None):
    """(event index, [bytearray clip records]) of the current arrangement (or arrangement `which`)."""
    k, _, recs = _playlist_at(d, ev, which)
    if k is None:
        raise ValueError("project has no playlist clips yet")
    return k, recs


def _clip_dict(d, ev, r, P, pats, names, bar_t=None, idx=0, meters=None):
    """A clip as the user sees it; bars through the meter map (time signature markers) when `meters` is given."""
    bar_t = bar_t or 4 * P
    pos, = struct.unpack("<I", r[0:4]); item, = struct.unpack("<H", r[6:8]); ln, = struct.unpack("<I", r[8:12])
    track = 499 - struct.unpack("<H", r[12:14])[0] + 1; flags, = struct.unpack("<H", r[18:20])
    if item >= PATTERN_BASE:
        pid = item - PATTERN_BASE; kind, name = "pattern", pats.get(pid, {}).get("name") or f"Pattern {pid}"
        s, e = _clip_offsets(r); extra = {"pattern": pid, "from_bar_in_pattern": round(1 + s / bar_t, 3)}
    else:
        kind = names.get(item, ("channel", None))[0]; name = names.get(item, (None, f"Channel {item}"))[1]
        extra = {"channel": item}
    if meters:
        bar = _tick_to_bar(pos, meters, P); length = round(_tick_to_bar(pos + ln, meters, P) - bar, 3)
    else:
        bar = round(1 + pos / bar_t, 3); length = round(ln / bar_t, 3)
    return {"id": _clip_id(r, idx), "kind": kind, "name": name, "bar": bar,
            "length_bars": length, "track": track, "muted": bool(flags & CLIP_MUTE), **extra}


def _clip_names(d, ev):
    """{channel index: (kind, name)} for audio and automation clip channels."""
    out, cur, typ, name = {}, None, None, None
    def flush():
        if cur is not None and typ in (4, 5):
            out[cur] = ("audio" if typ == 4 else "automation", name or f"Channel {cur}")
    for e in ev:
        if e["id"] == EV_CHANNEL:
            flush(); cur = struct.unpack("<H", _payload(d, e)[:2])[0]; typ = None; name = None
        elif cur is not None and e["id"] == 21:
            typ = _payload(d, e)[0]
        elif cur is not None and e["id"] == EV_DISPLAY_NAME and name is None:
            name = _text16(_payload(d, e))
    flush()
    return out


_CLIP_SIGS = {}                    # project -> {clip id: content} as the last flp_playlist list handed the ids out


def _clip_sig(r):
    """A playlist clip's content without its id (FL renumbers ids when it saves)."""
    return bytes(r[:32]) + bytes(r[36:]) if len(r) >= 88 else bytes(r)


def _clip_sig_key(project):
    return os.path.normcase(os.path.abspath(str(project)))


def flp_playlist(project, action="list", output=None, clips=None, pattern=None, channel=None, bar=None, track=None,
                 length_bars=None, repeat=1, every_bars=None, trim_start_bars=None, mute=True, names=None,
                 arrangement=None):
    """Work with individual playlist clips of the current arrangement. list: every clip (id, kind, name, bar, length,
    track, muted); arrangement=N lists another arrangement instead (edits always go to the current one).
    place: put a pattern (or an audio/automation clip channel) at `bar` on `track`; repeat N times every_bars apart.
    move: clips (ids) to `bar` and/or `track` (several keep their spacing). remove: clips. resize: clips to
    length_bars; trim_start_bars cuts that much off a pattern clip's start (it plays later into the pattern).
    mute / unmute: clips. Clip ids come from list; the project reloads in FL if it's open there."""
    pick_names = names
    d = _load(project); ev = _events(d); P = _ppq(d)
    try:
        bar_t = int(round(_qbar(flp_project_info(project)) * P))         # bars follow the time signature
    except Exception:
        bar_t = 4 * P
    meters = _meter_map(d, ev)
    pats = _patterns(d, ev); names = _clip_names(d, ev)
    if action == "list":
        k, _, recs = _playlist_at(d, ev, arrangement)             # an empty playlist lists no clips (not an error)
        items = sorted((_clip_dict(d, ev, r, P, pats, names, bar_t, i, meters) for i, r in enumerate(recs)),
                       key=lambda c: (c["bar"], c["track"]))
        if arrangement is None or _arrangement(d, ev, arrangement)["current"]:   # the ids handed out, by content:
            _CLIP_SIGS[_clip_sig_key(project)] = {_clip_id(r, i): _clip_sig(r) for i, r in enumerate(recs)}
        out = {"project": project, "clips": items, "count": len(items)}
        arrs = _arrangements(d, ev)
        if len(arrs) > 1:
            a = _arrangement(d, ev, arrangement)
            out["arrangement"] = {"index": a["index"], "name": a["name"], "current": a["current"],
                                  "others": [x["index"] for x in arrs if x is not a]}
        mk = _markers_view(d, ev, P)
        if mk:
            out["markers"] = mk
        return out
    if arrangement is not None and not _arrangement(d, ev, arrangement)["current"]:
        raise ValueError("playlist edits go to the arrangement FL plays (the current one); switch arrangements in FL "
                         "to edit another")
    output = output or project
    want = set(int(c) for c in (clips or []))
    # FL renumbers clip ids whenever it saves (and the open project is saved before it's edited), so the wanted clips
    # are remembered by their content - as the last list handed the ids out (FL may have saved since), else as the
    # file holds them now - and found again after that save
    _sig = _clip_sig
    try:
        sig_of = {_clip_id(r, i): _sig(r) for i, r in enumerate(_playlist_event(d, ev)[1])}
    except Exception:
        sig_of = {}
    sig_of.update(_CLIP_SIGS.get(_clip_sig_key(project)) or {})

    def run():
        nonlocal want
        writable(output)
        d = _load(project); ev = _events(d); done = []; have = True
        try:
            k, recs = _playlist_event(d, ev)
        except ValueError:
            if action != "place":
                raise
            (k, have), recs = _playlist_anchor(d, ev), []         # an empty playlist gets its first clip
        rid = {id(r): _clip_id(r, i) for i, r in enumerate(recs)}
        cid = lambda r: rid[id(r)]
        ids = [cid(r) for r in recs]; size = len(recs[0]) if recs else _playlist_at(d, ev)[1]
        if pick_names:                                            # clips picked by name (stable across FL saves)
            wanted = {str(n).strip().lower() for n in pick_names}
            pts_, nms_ = _patterns(d, ev), _clip_names(d, ev)
            want = want | {c["id"] for c in (_clip_dict(d, ev, r, P, pts_, nms_, bar_t, i) for i, r in enumerate(recs))
                           if str(c.get("name", "")).strip().lower() in wanted}
            if not want:
                raise ValueError(f"no clips named {sorted(pick_names)}")
        if action in ("move", "remove", "resize", "mute", "unmute") and want:
            by_sig, sig_now = {}, {}
            for i, r in zip(ids, recs):
                by_sig.setdefault(_sig(r), []).append(i); sig_now[i] = _sig(r)
            remap = set()
            for w in sorted(want):                                # an id that now names ANOTHER clip (renumbered)
                s_ = sig_of.get(w)                                # is followed to the clip it named when listed
                if s_ is None or sig_now.get(w) == s_:
                    remap.add(w)
                    continue
                cand = [c for c in by_sig.get(s_, []) if c not in remap]
                if not cand:                                      # the listed clip changed or is gone: never act
                    raise ValueError(f"clip {w} isn't where action=list saw it (the playlist changed since): list "
                                     "the clips again, or pick them by name (names=[...])")   # on whatever holds its id now
                remap.add(cand[0])
            want = remap
        if action in ("move", "remove", "resize", "mute", "unmute"):
            missing = want - set(ids)
            if not want or missing:
                raise ValueError(f"give clip ids from action=list (unknown: {sorted(missing) or 'none given'})")
        if action == "place":
            if pattern is not None:
                pid = _pattern_id(d, ev, pattern); item = PATTERN_BASE + pid
                tmpl = next((r for r in recs if struct.unpack("<H", r[6:8])[0] >= PATTERN_BASE), None)
                if tmpl is None:                                  # FL's own clip record, as _place_pattern
                    import fl_blocks
                    tmpl = _clip_template(fl_blocks.AUTOMATION_CLIP, size)
                notes = pats[pid]["notes"]
                natural = max((n[0] + n[3] for n in notes), default=4 * bar_t)
                ln = int(round(float(length_bars) * bar_t)) if length_bars else int(-(-natural // bar_t) * bar_t)
                offs = (0, ln)
            elif channel is not None:
                item = int(channel)
                tmpl = next((r for r in recs if struct.unpack("<H", r[6:8])[0] == item), None)
                if tmpl is None:
                    raise ValueError(f"channel {channel} has no clip in the playlist yet to copy (add it first)")
                ln = int(round(float(length_bars) * bar_t)) if length_bars else struct.unpack("<I", tmpl[8:12])[0]
                offs = None
            else:
                raise ValueError("place needs pattern (id or name) or channel (an audio/automation clip channel)")
            if bar is None:
                raise ValueError("place needs bar")
            used = {499 - struct.unpack("<H", r[12:14])[0] + 1 for r in recs}
            tr = _check_track(track) if track else _free_track(d)
            step = int(round(float(every_bars) * bar_t)) if every_bars else ln
            placed = []
            for i in range(max(1, int(repeat))):
                r = bytearray(tmpl); pos, ln = _clip_range(_bar_to_tick(bar, meters, P) + i * step, ln)
                struct.pack_into("<I", r, 0, pos); struct.pack_into("<H", r, 6, item); struct.pack_into("<I", r, 8, ln)
                struct.pack_into("<H", r, 12, 499 - (tr - 1)); struct.pack_into("<H", r, 18, struct.unpack("<H", r[18:20])[0] & ~CLIP_MUTE)
                if offs:
                    struct.pack_into("<II", r, 24, *offs)
                new_id = _next_clip_id(ids); ids.append(new_id); rid[id(r)] = new_id
                if size >= 88:
                    struct.pack_into("<I", r, 32, new_id)
                recs.append(r); placed.append(r)
            if size < 88:                                         # no stored ids (FL 20/21): ids = places in the list
                order = sorted(recs, key=lambda r: struct.unpack("<I", r[0:4])[0])
                done = [next(j + 1 for j, x in enumerate(order) if x is r) for r in placed]
            else:
                done = [cid(r) for r in placed]
        elif action == "remove":
            recs = [r for r in recs if cid(r) not in want]; done = sorted(want)
        elif action == "move":
            sel = [r for r in recs if cid(r) in want]
            first = min(struct.unpack("<I", r[0:4])[0] for r in sel)
            top_track = min(499 - struct.unpack("<H", r[12:14])[0] + 1 for r in sel)
            for r in sel:
                if bar is not None:
                    pos = struct.unpack("<I", r[0:4])[0] - first + _bar_to_tick(bar, meters, P)
                    struct.pack_into("<I", r, 0, max(0, pos))
                if track:
                    t = 499 - struct.unpack("<H", r[12:14])[0] + 1 - top_track + int(track)
                    struct.pack_into("<H", r, 12, 499 - (_check_track(t) - 1))
                done.append(cid(r))
        elif action == "resize":
            for r in recs:
                if cid(r) not in want:
                    continue
                ln = struct.unpack("<I", r[8:12])[0]; is_pat = struct.unpack("<H", r[6:8])[0] >= PATTERN_BASE
                if trim_start_bars:
                    cut = int(round(float(trim_start_bars) * bar_t))
                    if not is_pat:
                        raise ValueError("trim_start_bars works on pattern clips (for audio use flp_audio_clip_settings start)")
                    if cut >= ln:
                        raise ValueError("trim would remove the whole clip")
                    s, e = _clip_offsets(r)
                    struct.pack_into("<I", r, 0, struct.unpack("<I", r[0:4])[0] + cut)
                    struct.pack_into("<II", r, 24, s + cut, e); ln -= cut
                if length_bars:
                    new = int(round(float(length_bars) * bar_t))
                    if is_pat:
                        s, _ = _clip_offsets(r); struct.pack_into("<II", r, 24, s, s + new)
                    ln = new
                struct.pack_into("<I", r, 8, ln); done.append(cid(r))
        elif action in ("mute", "unmute"):
            on = action == "mute" and bool(mute)
            for r in recs:
                if cid(r) in want:
                    f, = struct.unpack("<H", r[18:20])
                    struct.pack_into("<H", r, 18, (f | CLIP_MUTE) if on else (f & ~CLIP_MUTE))
                    done.append(cid(r))
        else:
            raise ValueError("action: list, place, move, remove, resize, mute, unmute")
        recs.sort(key=lambda r: struct.unpack("<I", r[0:4])[0])
        d = _splice(d, ev, [(k, k + 1 if have else k, _data_event(EV_PLAYLIST, b"".join(bytes(r) for r in recs)))])
        _save(d, output)
        return {"output": output, "action": action, "clips": done, "song_length_bars": flp_info(output).get("song_length_bars")}
    return _with_open_project(project, output, run)


# ----------------------------------------------------------------------------- audio clip (sampler) settings
# Mapped on FL 2026.1.7 by changing each control in FL and diffing the saved project:
#   event 215 (channel parameters): +9 remove DC, +80 normalize, +81 reverse polarity, +96 TIME (float, 768 per bar
#   = 192 per beat, 0 = off), +100 PITCH (cents), +104 MUL (int, 10000 per octave of length), +108 stretch mode,
#   +128 sample start (double 0..1), +136 sample length (double 0..1)
#   event 70 flags: 1 fade stereo, 2 reverse, 256 swap stereo;  event 76 fade in, 75 fade out (0..1024; FL's fade is a
#   depth r = value/256: gain = clamp(1 - r*(1 - t/T)) for the fade-in, so r=1 is a linear fade over the whole sample,
#   r=0.5 starts at half volume, r=2 is silent for the first half then ramps; measured with renders)
STRETCH_MODES = {"resample": 0, "stretch": -1, "stretch_pro": -2, "e3_generic": 1, "e3_mono": 2, "slice_stretch": 3,
                 "slice_map": 4, "auto": 5, "e2_generic": 6, "e2_transient": 7, "e2_mono": 8, "e2_speech": 9}
_MODE_NAMES = {v: k for k, v in STRETCH_MODES.items()}
EV_CHAN_PARAMS, EV_FX_FLAGS, EV_FADE_IN, EV_FADE_OUT = 215, 70, 76, 75


def _channel_events(d, ev, ch):
    """{event id: index} for the events of channel `ch` (ChannelNew .. next ChannelNew)."""
    found, cur = {}, None
    for k, e in enumerate(ev):
        if e["id"] == EV_CHANNEL:
            cur = struct.unpack("<H", _payload(d, e)[:2])[0]
            if found and cur != ch:
                break
        elif cur == ch:
            found.setdefault(e["id"], k)
    return found


EV_CHANNEL_INSERT = 104                                           # FL 20+: word (signed) = mixer insert (-1 = none)
EV_CHANNEL_INSERT_OLD = 22                                        # older projects: byte (signed)
EV_POLYPHONY = 221                                                # channel polyphony: max u32, slide u32, flags u8
POLY_MONO, POLY_PORTA = 0x01, 0x02


def _channel_ranges(d, ev):
    """{channel: (first event after ChannelNew, its ChannelEnd (51) or the next ChannelNew)}."""
    out, cur, k0 = {}, None, None
    for k, e in enumerate(ev):
        if e["id"] == EV_CHANNEL:
            if cur is not None and cur not in out:
                out[cur] = (k0, k)
            cur, k0 = struct.unpack("<H", _payload(d, e)[:2])[0], k + 1
        elif cur is not None and e["id"] == EV_CHANNEL_END:
            out.setdefault(cur, (k0, k)); cur = None
        elif cur is not None and e["id"] in (EV_PATTERN_NEW, 99, EV_MIXER_TRACK):
            out.setdefault(cur, (k0, k)); cur = None
    if cur is not None and cur not in out:
        out[cur] = (k0, len(ev))
    return out


def _channel_inserts(d, ev=None):
    """{channel: mixer insert} read from the file. FL 20-2026 store it as event 104 (signed word, -1 = not routed;
    seen in FL 2026 files, 0 = master), older FL as event 22 (signed byte); 104 wins when both exist. Channels with
    neither are left out. PC-VERIFY: matches channels.getTargetFxTrack in FL for a few channels."""
    ev = ev if ev is not None else _events(d)
    out = {}
    for ch, (a, b) in _channel_ranges(d, ev).items():
        new = old = None
        for k in range(a, b):
            e = ev[k]
            if e["id"] == EV_CHANNEL_INSERT and e["len"] == 2 and new is None:
                new = struct.unpack("<h", _payload(d, e))[0]
            elif e["id"] == EV_CHANNEL_INSERT_OLD and e["len"] == 1 and old is None:
                old = struct.unpack("<b", _payload(d, e))[0]
        v = new if new is not None else old
        if v is not None and -1 <= v <= 1024:
            out[ch] = v
    return out


def _channel_insert(d, ch, ev=None):
    """The mixer insert channel `ch` plays into, from the file (None if the file doesn't say)."""
    if isinstance(d, str):
        d = _load(d)
    return _channel_inserts(d, ev).get(int(ch))


def flp_channel_glide(project, output, channel, mono=True, porta=True, slide=None, max_voices=None):
    """Channel polyphony settings in the file (Channel settings > Misc > Polyphony): mono / porta for glides made of
    overlapping notes (808s), the slide time and the voice limit. PC-VERIFY: event 221 layout (max u32, slide u32,
    flags u8: 1 = mono, 2 = porta) - FL shows Mono + Porta ticked and glides between overlapping notes."""
    writable(output)
    d = _load(project); ev = _events(d); ch = int(channel)
    rng = _channel_ranges(d, ev).get(ch)
    if rng is None:
        raise ValueError(f"no channel {ch}")
    k = next((k for k in range(*rng) if ev[k]["id"] == EV_POLYPHONY and ev[k]["len"] >= 9), None)
    if k is None:
        raise ValueError(f"channel {ch} has no polyphony settings in this file (older FL project?): set Mono/Porta in "
                         "FL's channel settings (Misc functions > Polyphony)")
    p = bytearray(_payload(d, ev[k]))
    mx, sl = struct.unpack_from("<II", p, 0); fl = p[8]
    before = {"mono": bool(fl & POLY_MONO), "porta": bool(fl & POLY_PORTA), "slide": sl, "max_voices": mx}
    if mono is not None:
        fl = (fl | POLY_MONO) if mono else (fl & ~POLY_MONO)
    if porta is not None:
        fl = (fl | POLY_PORTA) if porta else (fl & ~POLY_PORTA)
    if slide is not None:
        sl = max(0, int(slide))
    if max_voices is not None:
        mx = max(0, int(max_voices))
    struct.pack_into("<II", p, 0, mx, sl); p[8] = fl & 0xFF
    _save(_splice(d, ev, [(k, k + 1, _data_event(EV_POLYPHONY, bytes(p)))]), output)
    return {"output": output, "channel": ch, "before": before,
            "after": {"mono": bool(fl & POLY_MONO), "porta": bool(fl & POLY_PORTA), "slide": sl, "max_voices": mx},
            "note": "glides: overlapping notes on this channel now slide (listen to check the slide time)"}


def _clip_settings_read(d, ev, f):
    p = bytes(_payload(d, ev[f[EV_CHAN_PARAMS]]))
    flags = struct.unpack("<H", _payload(d, ev[f[EV_FX_FLAGS]])[:2])[0] if EV_FX_FLAGS in f else 0
    word = lambda eid: struct.unpack("<H", _payload(d, ev[f[eid]])[:2])[0] if eid in f else 0
    t = struct.unpack("<f", p[96:100])[0]; mode = struct.unpack("<i", p[108:112])[0]
    return {"stretch_mode": _MODE_NAMES.get(mode, mode), "time_beats": round(t / 192.0, 4) if t else None,
            "pitch_cents": struct.unpack("<i", p[100:104])[0],
            "multiplier": round(2 ** (struct.unpack("<i", p[104:108])[0] / 10000.0), 4),
            "reverse": bool(flags & 2), "normalize": bool(p[80]), "remove_dc": bool(p[9]), "reverse_polarity": bool(p[81]),
            "fade_stereo": bool(flags & 1), "swap_stereo": bool(flags & 256),
            "fade_in": round(word(EV_FADE_IN) / 256.0, 4), "fade_out": round(word(EV_FADE_OUT) / 256.0, 4),
            "start": round(struct.unpack("<d", p[128:136])[0], 4), "length": round(struct.unpack("<d", p[136:144])[0], 4)}


def flp_audio_clip_settings(project, channel, output=None, stretch_mode=None, time=None, pitch_cents=None,
                            multiplier=None, reverse=None, normalize=None, remove_dc=None, reverse_polarity=None,
                            fade_stereo=None, swap_stereo=None, fade_in=None, fade_out=None, start=None, length=None):
    """Read or set an audio clip channel's sample settings (what FL shows in its channel settings):
    time stretching (stretch_mode, time, pitch_cents, multiplier) and precomputed effects (reverse, normalize,
    remove_dc, reverse_polarity, fade_stereo, swap_stereo, start / length as 0..1 of the sample, fade_in / fade_out
    as a depth 0..4 where 1 = a linear fade across the whole sample, 0.5 = from/to half volume, 2 = steeper with
    silence for half the sample).
    time: beats as a number, '2bar' / '8b', 'none'; or 'fit' = the sample's own length at the project tempo
    (so it then follows tempo changes). Without any setting it just reads them."""
    changes = {k: v for k, v in dict(stretch_mode=stretch_mode, time=time, pitch_cents=pitch_cents, multiplier=multiplier,
               reverse=reverse, normalize=normalize, remove_dc=remove_dc, reverse_polarity=reverse_polarity,
               fade_stereo=fade_stereo, swap_stereo=swap_stereo, fade_in=fade_in, fade_out=fade_out, start=start,
               length=length).items() if v is not None}
    d = _load(project); ev = _events(d); f = _channel_events(d, ev, int(channel))
    if EV_CHAN_PARAMS not in f or len(_payload(d, ev[f[EV_CHAN_PARAMS]])) < 144:
        raise ValueError(f"channel {channel} has no sample settings (not an audio clip / sampler channel?)")
    if not changes:
        return {"project": project, "channel": int(channel), **_clip_settings_read(d, ev, f)}
    output = output or project

    def run():
        writable(output)
        d = _load(project); ev = _events(d); f = _channel_events(d, ev, int(channel))
        p = bytearray(_payload(d, ev[f[EV_CHAN_PARAMS]])); edits = []
        flags = struct.unpack("<H", _payload(d, ev[f[EV_FX_FLAGS]])[:2])[0] if EV_FX_FLAGS in f else 0
        if "stretch_mode" in changes:
            m = str(changes["stretch_mode"]).lower().replace(" ", "_").replace("-", "_")
            if m not in STRETCH_MODES:
                raise ValueError("stretch_mode: " + ", ".join(STRETCH_MODES))
            struct.pack_into("<i", p, 108, STRETCH_MODES[m])
        if "time" in changes:
            t = changes["time"]
            if str(t).lower() in ("none", "off", "0"):
                beats = 0.0
            elif str(t).lower() in ("fit", "project", "project_tempo"):
                path = _sample_path_of(d, ev, f)
                import fl_audio_edit as AE
                x, rate, _ = AE.load(path); tempo = _project_tempo(d)
                beats = len(x) / rate * tempo / 60.0
            else:
                import fl_audio_edit as AE
                beats = float(t) if isinstance(t, (int, float)) else AE.to_seconds(t, 60.0)
            struct.pack_into("<f", p, 96, float(beats * 192.0))
            if beats and STRETCH_MODES.get(str(changes.get("stretch_mode", "")).lower(), None) is None \
                    and struct.unpack("<i", p[108:112])[0] == 0:
                struct.pack_into("<i", p, 108, STRETCH_MODES["stretch_pro"])   # resample can't hold a time: stretch
        if "pitch_cents" in changes:
            struct.pack_into("<i", p, 100, int(round(float(changes["pitch_cents"]))))
        if "multiplier" in changes:
            mul = float(changes["multiplier"])
            if mul <= 0:
                raise ValueError("multiplier must be > 0")
            struct.pack_into("<i", p, 104, int(round(10000 * math.log2(mul))))
        for key, off in (("normalize", 80), ("remove_dc", 9), ("reverse_polarity", 81)):
            if key in changes:
                p[off] = 1 if changes[key] else 0
        for key, off in (("start", 128), ("length", 136)):
            if key in changes:
                v = float(changes[key])
                if not 0 <= v <= 1:
                    raise ValueError(f"{key} is a fraction of the sample, 0..1")
                struct.pack_into("<d", p, off, v)
        for key, bit in (("reverse", 2), ("fade_stereo", 1), ("swap_stereo", 256)):
            if key in changes:
                flags = (flags | bit) if changes[key] else (flags & ~bit)
        edits.append((f[EV_CHAN_PARAMS], f[EV_CHAN_PARAMS] + 1, _data_event(EV_CHAN_PARAMS, bytes(p))))
        if EV_FX_FLAGS in f:
            edits.append((f[EV_FX_FLAGS], f[EV_FX_FLAGS] + 1, bytes([EV_FX_FLAGS]) + struct.pack("<H", flags)))
        elif flags:
            raise ValueError("this channel has no effect-flags event; set reverse etc. once in FL first")
        for key, eid in (("fade_in", EV_FADE_IN), ("fade_out", EV_FADE_OUT)):
            if key in changes:
                v = float(changes[key])
                if not 0 <= v <= 4:
                    raise ValueError(f"{key} is a depth 0..4: 1 = fade across the whole sample from silence, "
                                     "0.5 = from half volume, 2 = silent for half the sample then a faster fade")
                if eid not in f:
                    raise ValueError(f"this channel has no {key} event")
                edits.append((f[eid], f[eid] + 1, bytes([eid]) + struct.pack("<H", int(round(v * 256)))))
        edits.sort()
        d = _splice(d, ev, edits); _save(d, output)
        ev = _events(d)
        return {"output": output, "channel": int(channel), "changed": sorted(changes),
                **_clip_settings_read(d, ev, _channel_events(d, ev, int(channel)))}
    return _with_open_project(project, output, run)


def _sample_path_of(d, ev, f):
    if EV_SAMPLE_PATH not in f:
        raise ValueError("channel has no sample file")
    path = _text16(_payload(d, ev[f[EV_SAMPLE_PATH]]))
    if "%FLStudioFactoryData%" in path:
        raise ValueError("'fit' needs a sample file on disk (factory samples aren't resolved)")
    return path


def _project_tempo(d):
    ev = _events(d)
    return next((struct.unpack("<I", _payload(d, e))[0] / 1000 for e in ev if e["id"] == EV_TEMPO), 120.0)


# ----------------------------------------------------------------------------- bridge without loopMIDI
def _loopback_test(port=None):
    """Send a probe out of `port` and see it come back in on the same name (a loopback port), or on its A/B
    partner (Windows MIDI Services' loopback pair: then FL uses the partner, `fl_port`)."""
    t = _Bridge(); p = t.ports()
    port = port or next(iter(_loopback_ports(p)), LOOPBACK_PORT)
    if port not in p["midi_out"] or port not in p["midi_in"]:
        return {"port": port, "loopback": False, "why": "port not present"}
    if BRIDGE.ok and port in getattr(BRIDGE, "ports_used", ()):
        BRIDGE.close()
    try:
        t._open_pair(p, port, port)
    except RuntimeError as e:
        return {"port": port, "loopback": False, "why": str(e)}
    probe = FRAME + bytes([0x7F, 0x11, 0x22, 0x33, 0x44]) + b"\xF7"   # direction 0x7F: ignored by both ends
    try:
        t._drain(); t._send(probe); t0 = time.time()
        while time.time() - t0 < 1.5:
            if any(m[:len(probe)] == probe for m in t._drain()):
                return {"port": port, "fl_port": port, "loopback": True, "ms": round((time.time() - t0) * 1000, 1)}
            time.sleep(0.005)
    finally:
        t.close()
    partner = _loop_partner(port, p)
    if partner:                                                  # Windows MIDI Services' A/B loopback pair: what
        t2 = _Bridge(); t2.ports()                               # goes out of A comes in on B (and back)
        try:
            t2._open_pair(p, port, partner)
        except RuntimeError as e:
            return {"port": port, "loopback": False, "why": f"pair {port} / {partner}: {e}"}
        try:
            t2._drain(); t2._send(probe); t0 = time.time()
            while time.time() - t0 < 1.5:
                if any(m[:len(probe)] == probe for m in t2._drain()):
                    # the server talks on `port` both ways, FL listens / answers on the partner
                    return {"port": port, "fl_port": partner, "loopback": True, "pair": True,
                            "ms": round((time.time() - t0) * 1000, 1)}
                time.sleep(0.005)
        finally:
            t2.close()
    return {"port": port, "loopback": False, "why": "nothing came back (not a loopback port)"}


def _loop_partner(name, p):
    """The other half of an A/B loopback pair ('Default App Loopback (A)' <-> '(B)'), if it's present."""
    for a, b in (("(A)", "(B)"), ("(B)", "(A)"), (" A", " B"), (" B", " A")):
        if name.endswith(a):
            other = name[:-len(a)] + b
            if other in p["midi_in"] and other in p["midi_out"]:
                return other
    return None


def _fl_midi_key(direction, port):
    keys = [k for k in _reg_dump_keys() if k.endswith(f"\\Devices\\MIDI {direction}\\{port}")]
    def ver(k):
        m = re.match(r"FL Studio (\d+)", k)
        return int(m.group(1)) if m else 0
    return max(keys, key=ver) if keys else None


def fl_bridge_setup(action="status", port_number=None, port=None, restart_fl=False, replace=False):
    """Live-bridge connection. status: which ports are used and whether FL answers. test: does a loopback port (Windows
    11's 'Default Basic App Loopback', or `port`) work. use_loopback: run the bridge over it (no loopMIDI needed):
    installs the script, sets FL's MIDI settings (FL is closed and reopened), checks FL answers. use_loopmidi: go
    back to the loopMIDI pair. use_input: no virtual port at all - FL runs the script on a MIDI input it already has
    (your keyboard: its notes still play), requests and replies go through the file mailbox; undo_input puts that
    input back as it was."""
    if action in ("use_input", "undo_input"):
        return _bridge_on_input(action, port, port_number, restart_fl, replace)
    if action == "diag":
        try:
            d = BRIDGE.call("diag", timeout=6.0)
        except Exception as e:
            d = {"error": str(e)}
        return {"script": d, "mailbox_dir": _mailbox_dir(), "mailbox_alive": _mailbox_alive(),
                "files": sorted(os.listdir(_mailbox_dir()))}
    if action == "update_script":
        done = []
        for path, first in _installed_scripts():
            _install_script(path, first if first.startswith("# name=") else None); done.append(path)
        if not done:
            dest = os.path.join(_hardware_dir(), "fl-headless", "device_flheadless.py"); _install_script(dest); done.append(dest)
        return {"updated": done, "mailbox": _mailbox_dir(), "script_version": _script_version_shipped(),
                "note": "FL loads the new script on its next start (or Options > MIDI settings > reload)."}
    if action == "status":
        p = BRIDGE.ports(); pick = BRIDGE.choose(p); ok = None
        if _mailbox_alive():
            try:
                BRIDGE.call("ping", timeout=4.0); ok = True
            except Exception as e:
                ok = f"no answer: {e}"
            return {"transport": "mailbox (no MIDI traffic)", "fl_answers": ok, "mailbox": _mailbox_dir(),
                    "script_port_note": "FL still needs one MIDI input to load the script on (any loopback port)"}
        if not fl_running():
            return {"ports": pick, "single_loopback_port": bool(pick and pick[0] == pick[1]),
                    "fl_answers": "FL isn't open", "loopmidi_present": "Flapi Request" in p["midi_out"],
                    "loopback_ports": _loopback_ports(p)}
        pong = None
        for t in (4.0, 8.0):                                      # the first message after a restart is slower
            try:
                pong = BRIDGE.call("ping", timeout=t); ok = True; break
            except Exception as e:
                ok = f"no answer: {e}"
        r = {"ports": pick, "single_loopback_port": bool(pick and pick[0] == pick[1]), "fl_answers": ok,
             "loopmidi_present": "Flapi Request" in p["midi_out"], "loopback_ports": _loopback_ports(p)}
        if isinstance(pong, dict):
            r["script_version"] = pong.get("version")
            if _script_note(dict(pong)).get("script_outdated"):
                r["script_outdated"] = _script_note(dict(pong))["script_outdated"]
        return r
    if action == "test":
        return _loopback_test(port)
    if action == "use_loopmidi":
        _state({"bridge_ports": ["Flapi Request", "Flapi Response"]}); BRIDGE.close()
        return fl_bridge_setup("status")
    if action not in ("use_loopback", "use_fl_port"):
        raise ValueError("action: status, test, use_loopback, use_loopmidi, use_input, undo_input, update_script, diag")
    t = _loopback_test(port)
    if not t["loopback"]:
        return {"done": False, "test": t, "note": "no working loopback port: on Windows 11 open MIDI Settings and add the "
                "default basic loopback, or keep loopMIDI - or with a MIDI keyboard connected, "
                "fl_bridge_setup(action='use_input') runs the bridge on its input (no virtual port at all)"}
    lp = t["port"]; flp = t.get("fl_port") or lp                # FL's side (the partner of an A/B pair)
    was_open = _restart_ok(restart_fl, None, "FL's MIDI settings can only change while it is closed")   # raises if not allowed
    dest_dir = os.path.join(_hardware_dir(), "fl-headless")
    dest = os.path.join(dest_dir, "device_flheadless.py")
    _install_script(dest)
    kin, kout = _fl_midi_key("input", flp), _fl_midi_key("output", flp)
    if not kin or not kout:
        raise RuntimeError(f"FL hasn't listed '{flp}' in its MIDI settings yet: open FL once (with the port present), retry")
    dump = _reg_dump(kin.rsplit("\\Devices", 1)[0] + "\\Devices")
    used = set()
    for k, vals in dump.items():
        if "Port" in vals and not k.endswith("\\" + flp):
            try:
                used.add(int(vals["Port"][1]))
            except (TypeError, ValueError):
                pass
    num = int(port_number) if port_number is not None else next(n for n in range(12, 126) if n not in used)
    changes = [{"key": kin, "name": "Enabled", "value": "1"}, {"key": kin, "name": "Type", "value": "-3"},
               {"key": kin, "name": "ScriptFolder", "value": "fl-headless"}, {"key": kin, "name": "Port", "value": str(num)},
               {"key": kout, "name": "Port", "value": str(num)}]
    prev = _state().get("bridge_ports")
    _state({"bridge_ports": [lp, lp]}); BRIDGE.close()
    res = fl_settings_set(changes, restart_fl=True, reopen=True)
    if not was_open:                      # FL was closed: nothing can answer now - FL reads the settings when it starts
        # PC-VERIFY: with FL closed, use_loopback writes the settings and the next FL start answers fl_ping
        return {"done": True, "test": t, "port_number": num, "script": dest, "settings": res["changed"],
                "pending": "FL was closed: it loads the script on this port the next time it starts (fl_ping then)",
                "note": "loopMIDI is no longer needed for the live tools"}
    t0 = time.time(); answer = None
    while time.time() - t0 < 45:
        try:
            BRIDGE.call("ping", timeout=3.0); answer = True; break
        except Exception as e:
            answer = str(e); BRIDGE.close(); time.sleep(2)
    if answer is not True:
        _state({"bridge_ports": prev}); BRIDGE.close()
        return {"done": False, "test": t, "port_number": num, "settings": res["changed"],
                "why": f"FL didn't answer on '{lp}' ({answer}); switched back to the previous ports"}
    return {"done": True, "test": t, "port_number": num, "script": dest, "settings": res["changed"],
            "note": "loopMIDI is no longer needed for the live tools"}


def _bridge_on_input(action, port, port_number, restart_fl, replace):
    """The bridge script on an existing MIDI input (a keyboard): FL needs one input to load a script on, and the file
    mailbox carries everything, so no loopMIDI / loopback port is needed. The script handles only its own SysEx, so
    the keyboard's notes and knobs keep reaching FL as before (FL's generic handling).
    PC-VERIFY: a keyboard input with the fl-headless script still plays notes; the mailbox answers; undo restores."""
    if not IS_WINDOWS:
        raise RuntimeError("FL's MIDI settings live in the Windows registry: " + WINDOWS_ONLY_NOTE)
    st = _state().get("bridge_input") or {}
    if action == "undo_input":
        if not st.get("key"):
            return {"done": False, "note": "the bridge isn't on a MIDI input (nothing to undo)"}
        was = st.get("was") or {}
        changes = [{"key": st["key"], "name": n, "value": v, "type": "text" if n == "ScriptFolder" else "number"}
                   for n, v in was.items() if v is not None]
        _restart_ok(restart_fl, None, "FL's MIDI settings can only change while it is closed")
        res = fl_settings_set(changes, restart_fl=True, reopen=True) if changes else {"changed": []}
        _state({"bridge_input": None})
        return {"done": True, "input": st.get("port"), "restored": res.get("changed"),
                "note": "the live tools need a bridge port again: fl_bridge_setup('use_loopback') or loopMIDI"}
    ins = []
    try:
        ins = [n for n in BRIDGE.ports()["midi_in"] if n not in _loopback_ports(BRIDGE.ports())]
    except Exception:                                             # noqa: BLE001
        pass
    if not port:
        return {"done": False, "inputs": ins,
                "note": "pick the input FL should run the script on (your keyboard): "
                        "fl_bridge_setup(action='use_input', port='<name>', restart_fl=true)"}
    kin = _fl_midi_key("input", port)
    if not kin:
        raise RuntimeError(f"FL hasn't listed the MIDI input '{port}' yet (known: {', '.join(ins) or 'none'}): connect "
                           "it, open FL once, then retry")
    vals = _reg_dump(kin).get(kin, {})
    was = {n: (vals.get(n) or [None, None])[1] for n in ("Enabled", "Type", "ScriptFolder", "Port")}
    other = str(was.get("ScriptFolder") or "")
    if other and other.lower() != "fl-headless" and not replace:
        return {"done": False, "input": port, "its_script": other,
                "why": f"'{port}' runs FL's script '{other}' (its knobs/pads mapping); the bridge would replace it. "
                       "Pass replace=true if that's fine (undo_input puts it back), or pick another input"}
    _restart_ok(restart_fl, None, "FL's MIDI settings can only change while it is closed")   # raises if not allowed
    dest = os.path.join(_hardware_dir(), "fl-headless", "device_flheadless.py")
    _install_script(dest)
    used = set()
    for k, v in _reg_dump(kin.rsplit("\\Devices", 1)[0] + "\\Devices").items():
        if "Port" in v and k != kin:
            try:
                used.add(int(v["Port"][1]))
            except (TypeError, ValueError):
                pass
    try:
        cur_port = int(was.get("Port")) if was.get("Port") not in (None, "") else None
    except (TypeError, ValueError):
        cur_port = None
    num = int(port_number) if port_number is not None else (cur_port if cur_port not in (None, -1) and cur_port
                                                            not in used else next(n for n in range(12, 126)
                                                                                  if n not in used))
    changes = [{"key": kin, "name": "Enabled", "value": "1", "type": "number"},
               {"key": kin, "name": "Type", "value": "-3", "type": "number"},
               {"key": kin, "name": "ScriptFolder", "value": "fl-headless", "type": "text"},
               {"key": kin, "name": "Port", "value": str(num), "type": "number"}]
    _state({"bridge_input": {"port": port, "key": kin, "was": was}})
    res = fl_settings_set(changes, restart_fl=True, reopen=True)
    t0 = time.time(); answer = None
    while time.time() - t0 < 60:
        if _mailbox_alive():
            try:
                BRIDGE.call("ping", timeout=4.0); answer = True; break
            except Exception as e:                                # noqa: BLE001
                answer = str(e)
        time.sleep(1.5)
    if answer is not True:
        return {"done": False, "input": port, "settings": res.get("changed"),
                "why": f"FL didn't answer through the mailbox within 60 s ({answer or 'no heartbeat'}): check that "
                       f"'{port}' is enabled in Options > MIDI settings with Controller type fl-headless; "
                       "fl_bridge_setup(action='undo_input', restart_fl=true) puts it back"}
    return {"done": True, "input": port, "port_number": num, "script": dest, "settings": res.get("changed"),
            "note": f"the live tools now run through FL's script on '{port}' and the file mailbox - no loopMIDI or "
                    "loopback port. Your keyboard still plays; undo_input puts its old setting back"}


# ----------------------------------------------------------------------------- audio editing
def audio_edit(input, output, ops, bpm=None, bits=None):
    """Edit a WAV: trim, cut, silence, fade_in/out, gain, normalize, reverse, repeat, pitch, stretch, mono, stereo,
    width, denoise. Times: seconds, '250ms', '3b' (beats), '2bar' (needs bpm)."""
    import fl_audio_edit as AE
    writable(output)
    return AE.edit(input, output, ops, bpm=bpm, bits=bits)


def audio_join(inputs, output, crossfade="10ms", gap=0, bpm=None, bits=None):
    """Join WAVs end to end with an equal-power crossfade (or a gap of silence)."""
    import fl_audio_edit as AE
    writable(output)
    return AE.join(inputs, output, crossfade=crossfade, gap=gap, bpm=bpm, bits=bits)


def _bar_starts_s(project, start_bar=1, every="1bar", until_s=None):
    """Start times (seconds from start_bar) of every bar/beat step, following the project's tempo map."""
    import fl_audio_edit as AE
    d = _load(project); ev = _events(d); P = _ppq(d)
    _, tm = _song(d, ev)
    tm = sorted(tm) or [(0, 120.0)]
    beats = AE.to_seconds(every, 60.0)                           # at 60 bpm, seconds == beats
    step = int(round(beats * P))
    if step <= 0:
        raise ValueError("'every' must be > 0")
    def sec(tick):                                               # seconds from song start
        t = 0.0; prev_t, prev_b = 0, tm[0][1]
        for tk, b in tm:
            if tk >= tick:
                break
            t += (tk - prev_t) / P * 60.0 / prev_b; prev_t, prev_b = tk, b
        return t + (tick - prev_t) / P * 60.0 / prev_b
    meters = _meter_map(d, ev)                                    # bars follow the time signature (and its markers)
    m_ = AE._TIME_RE.match(every) if isinstance(every, str) else None
    nbars = float(m_.group(1)) if m_ and AE._UNITS.get(m_.group(2).lower()) == "bar" else None
    t0_tick = _bar_to_tick(float(start_bar), meters, P); base = sec(t0_tick); out = []; k = 0
    at = (lambda k_: _bar_to_tick(float(start_bar) + k_ * nbars, meters, P)) if nbars else (lambda k_: t0_tick + k_ * step)
    while True:
        s = sec(at(k)) - base
        if until_s is not None and s >= until_s:
            break
        out.append(round(s, 6)); k += 1
        if until_s is None and k > 10000:
            break
    return out


def audio_slice(input, output_dir=None, mode="transients", bpm=None, every="1b", count=None, threshold=None,
                min_length="60ms", prefix=None, project=None, start_bar=1):
    """Slice a WAV into one-shots: at transients (hits), every N beats/bars, or into equal parts. For beats/bars
    on a song with tempo changes pass `project` (and the bar the WAV starts at): cuts follow its tempo map."""
    import fl_audio_edit as AE
    output_dir = output_dir or os.path.join(os.path.dirname(input), os.path.splitext(os.path.basename(input))[0] + " slices")
    writable(output_dir)
    if mode == "beats" and project:
        x, rate, _ = AE.load(input)
        times = _bar_starts_s(project, start_bar, every, until_s=len(x) / rate)
        r = AE.slice(input, output_dir, mode="times", times=times, min_length=min_length, prefix=prefix)
        r["followed_tempo_map"] = True
        return r
    return AE.slice(input, output_dir, mode=mode, bpm=bpm, every=every, count=count, threshold=threshold,
                    min_length=min_length, prefix=prefix)


def _schema(**fields):
    return {"type": "object", "properties": {k: v[0] for k, v in fields.items()},
            "required": [k for k, v in fields.items() if not v[1]]}


