# File tools that write a project: if that project is the one open in FL, FL saves first, the file is edited, and FL
# loads it straight back (_with_open_project). Without this, FL keeps its old copy in memory and the next save - by
# FL, the user, or another tool's reload - silently writes the old notes back over the edit.
_OPEN_PROJECT_GUARD = {"flp_set_song_length": ("path", None), "flp_set_tempo": ("path", None),
                       "flp_write_notes": ("template", "output"), "flp_write_arrangement": ("template", "output"),
                       "flp_replace_part": ("project", "output"), "flp_style_channels": ("project", "output"),
                       "flp_mixer": ("project", "output"), "flp_add_automation": ("project", "output"),
                       "flp_add_audio_clip": ("project", "output"), "flp_copy_state": ("target", "output"),
                       "flp_load_plugin": ("project", "output"), "flp_remove_effect": ("project", "output"),
                       "flp_add_channel": ("project", "output"), "flp_project_info": ("path", "output"),
                       "flp_restore": ("path", None)}


def _plan_ops(out, ops):
    """flp_edit ops -> [(tool, raw function, args bound to `out`)]; validates names and arguments."""
    import inspect
    plan = []
    for i, op in enumerate(ops):
        op = dict(op); name = op.pop("tool", None); args = dict(op.pop("args", None) or op)
        keep_in = bool(args.pop("_keep_input", False))           # a queued template -> project writer: its own input
        if name == "fl_load_preset":                              # its file-level twin, so it batches with the rest
            name = "flp_load_plugin"; args.pop("project", None)
            args["preset"] = _resolve_preset(args.get("preset", ""))
        if name not in TOOLS or not name.startswith("flp_") or name == "flp_edit":
            raise ValueError(f"op {i + 1}: '{name}' isn't an flp_* tool")
        fn = getattr(TOOLS[name][0], "__wrapped__", TOOLS[name][0]); sig = inspect.signature(fn).parameters
        in_key = _OPEN_PROJECT_GUARD.get(name, (None,))[0] or next((k for k in ("project", "path") if k in sig), None)
        keep_in = keep_in and bool(in_key and args.get(in_key))
        if in_key and not keep_in:
            args[in_key] = out
        if "output" in sig:
            args["output"] = out
        if keep_in:
            fn = (lambda f_, k_: lambda **a: _with_src_title(f_, a, k_))(fn, in_key)
        for k in list(set(args) - set(sig)):                     # common other names for its arguments
            a = _alias_of(k, set(sig), args)
            if a:
                args[a] = args.pop(k)
        bad = set(args) - set(sig)
        if bad and any(p_.kind == p_.VAR_KEYWORD for p_ in sig.values()):   # flp_project_info(**changes)
            if name == "flp_project_info":
                bad -= set(PROJECT_TEXT) | set(PROJECT_BYTE) | {"pitch"}
            else:
                bad = set()
        if bad:
            raise ValueError(f"op {i + 1} ({name}): unknown argument(s) {sorted(bad)}")
        plan.append((name, fn, args))
    return plan


def _with_src_title(fn, args, in_key):
    """Run a template -> project writer the way its guard does: a copy under another name keeps its own title."""
    src = args.get(in_key)
    if isinstance(src, str) and _stem(src).lower() != _stem(args.get("output") or src).lower():
        with _write_source(src):
            return fn(**args)
    return fn(**args)


def _run_plan(out, plan):
    """Run planned ops on the file `out` in order (no FL round trips); all or nothing: a failing op puts the file back."""
    global _EDIT_DEPTH
    orig = open(out, "rb").read(); results = []
    _edit_enter()
    try:
        for i, (name, fn, args) in enumerate(plan):
            try:
                r = fn(**args)
            except Exception as e:
                _write_bytes(out, orig)
                raise RuntimeError(f"op {i + 1} ({name}) failed, so nothing was changed: {type(e).__name__}: {e}")
            results.append({"tool": name, **({k: v for k, v in r.items() if k not in ("output", "clips")}
                                             if isinstance(r, dict) else {"result": r})})
    finally:
        _edit_exit()
    return results


def flp_edit(project, ops, output=None):
    """Several file edits on one project as one step: FL saves once, every op runs on the file, FL reloads once and
    the result is verified. All or nothing: if an op fails the file is put back. ops: [{"tool": "flp_replace_part",
    "channel": 5, "notes": [...]}, {"tool": "flp_add_automation", "replace": true, ...}, ...] - any flp_* writer;
    project/output are filled in."""
    out = output or project
    writable(out)
    if not ops:
        raise ValueError("give ops: [{tool, ...args}]")
    plan = _plan_ops(out, ops)

    def run():
        if os.path.normcase(os.path.abspath(out)) == os.path.normcase(os.path.abspath(project)):
            return {"output": out, "ops": len(plan), "results": _run_plan(out, plan)}
        prev = open(out, "rb").read() if os.path.isfile(out) else None
        bk = None
        if prev is not None:                                      # an existing other file: backed up first
            bk = _backup(out); _CALL_BACKUPS.add(os.path.normcase(os.path.abspath(out)))
        shutil.copyfile(project, out)
        _own_title_file(project, out)                             # a copy under another name: its own title
        try:
            results = _run_plan(out, plan)
        except Exception:
            if prev is not None:
                _write_bytes(out, prev)                           # all or nothing: the ORIGINAL output comes back
            else:
                _remove_own(out)                                  # the copy this call just made
            raise
        r = {"output": out, "ops": len(plan), "results": results}
        if bk:
            r["replaced_existing"] = {"file": out, "backup": bk, "note": "the file that was there is in flp_versions"}
        return r
    return _with_open_project(out, out, run)


def _guard_open_project(fn, in_key, out_key):
    def run(**kw):
        out = kw.get(out_key) if out_key else kw.get(in_key)
        if not out or (out_key == "output" and fn is flp_project_info and not kw.get("output")):
            return fn(**kw)
        src = kw.get(in_key) if out_key and in_key else None
        if src and isinstance(src, str) and isinstance(out, str) and _stem(src).lower() != _stem(out).lower() \
                and not (fn is flp_project_info and kw.get("title") is not None):
            with _write_source(src):                              # a copy under another name: its own title
                return _with_open_project(out, out, lambda: fn(**kw))
        return _with_open_project(out, out, lambda: fn(**kw))
    run.__wrapped__ = fn
    return run


for _n, (_i, _o) in _OPEN_PROJECT_GUARD.items():
    if _n in TOOLS:
        TOOLS[_n] = (_guard_open_project(TOOLS[_n][0], _i, _o),) + tuple(TOOLS[_n][1:])
