# ============================================================================= live-first (big projects)
# A real production takes FL 30 s - 2 min to load, and every file-level edit of the open project used to cost one
# full reload. So: (1) each project's load time is measured, (2) edits can be queued and applied in ONE save+reload
# when FL needs them (lazy mode), (3) renders run in the open FL (no close, no extra loads), (4) notes can be written
# live through a piano-roll script (experimental).

def _mkdirs(d):
    os.makedirs(d, exist_ok=True)
    return True


class _nullctx:
    def __enter__(self):
        return self

    def __exit__(self, *a):
        return False


def _json_read(path, default):
    try:
        with open(path, encoding="utf-8") as f:
            return json.load(f)
    except (OSError, ValueError):
        return default


def _json_write(path, obj):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = f"{path}.{os.getpid()}.{threading.get_ident()}.tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(obj, f)
    _retry_os(lambda: os.replace(tmp, path))


# ---- (1) load cost --------------------------------------------------------------------------------------------
LOAD_COSTS = os.path.join(os.path.dirname(STATE), "load_costs.json")
_LC_LOCK = threading.Lock()


def _note_load_cost(project, seconds, source):
    """Record how long FL took to (re)load `project`: rolling average of its last 5 loads, in its own file (not
    state.json, so a busy session doesn't rewrite the shared state on every reload)."""
    try:
        seconds = float(seconds)
    except (TypeError, ValueError):
        return
    if not project or not 0 < seconds < 900:
        return
    k = _ud_key(project)
    with _LC_LOCK, _file_lock(LOAD_COSTS + ".lock") if _mkdirs(os.path.dirname(LOAD_COSTS)) else _nullctx():
        d = _json_read(LOAD_COSTS, {})
        e = d.get(k) or {"samples": []}
        e["samples"] = list(e.get("samples") or [])[-4:] + [round(seconds, 1)]
        e.update(avg_s=round(sum(e["samples"]) / len(e["samples"]), 1), last_s=round(seconds, 1), source=source,
                 t=int(time.time()), project=os.path.abspath(project))
        d[k] = e
        if len(d) > 300:                                          # forget the projects not loaded for longest
            for old in sorted(d, key=lambda x: d[x].get("t", 0))[:len(d) - 300]:
                d.pop(old, None)
        try:
            _json_write(LOAD_COSTS, d)
        except OSError:
            pass


def project_load_cost(project):
    """How long FL takes to load this project here: {seconds (rolling average, None = never measured), last_s,
    samples, source}. Other tools use it for estimates (ns['project_load_cost'])."""
    e = _json_read(LOAD_COSTS, {}).get(_ud_key(project)) if project else None
    if not e:
        return {"seconds": None, "samples": 0, "note": "not measured yet (every load/reload in FL measures it)"}
    smp = [float(x) for x in (e.get("samples") or []) if isinstance(x, (int, float))]
    return {"seconds": e.get("avg_s"), "last_s": e.get("last_s"), "samples": len(smp), "source": e.get("source"),
            "max_s": max(smp) if smp else e.get("avg_s")}


def _load_cost_ref(project):
    """The load time a reload of `project` is judged against: its slowest recent measured load (a 'reload' that only
    looked fast - FL never really loaded - must not drag the reference down; PC 2026-10-23), else None."""
    try:
        c = project_load_cost(project)
        v = max(float(c.get("max_s") or 0), float(c.get("seconds") or 0))
        return v or None
    except Exception:                                             # noqa: BLE001
        return None


def _measure_load_later(project, t0, wait_s=240, shown_before=None):
    """After FL was told to open `project`: in the background, time until FL holds it (its window names the project
    and the bridge answers with the project's channel count) and record that as the project's load cost.
    PC-VERIFY: on a 30 s+ project the recorded seconds match a stopwatch (FL's title may name the project before
    plugins finished loading; the bridge is busy until then)."""
    def run():
        try:
            want = _fingerprint(project)["channels"]
        except Exception:
            want = None
        # FL's title shows the file's name OR its Project-info title (a project titled unlike its file was never
        # measured: PC 2026-10-23). When FL already showed that name before the load (a same-title copy, the same
        # song), the title must change first (to 'Opening: ...' or another name) - else the old one would count.
        names = _project_names(project)                           # shown_before: FL's title before the open
        need_change = shown_before is not None and str(shown_before).lower() in names   # (None: not known)
        limit = _scaled(max(float(wait_s), 600.0))                # heavy projects load for minutes
        while time.time() - t0 < limit:
            time.sleep(0.4)
            try:
                main = _fl_main_window()
                shown = (_title_stem(main[1]) or "").lower() if main else ""
                if need_change:
                    if not main or shown not in names or _fl_loading_title():
                        need_change = False
                    continue
                if not main or shown not in names:
                    continue
                if not _FL_LOCK.acquire(blocking=False):          # another FL step runs: look again later
                    continue
                try:
                    st = _bridge_state_light(timeout=1.5)
                finally:
                    _FL_LOCK.release()
                n = st.get("channel_count")
                if n is None:
                    n = len(st.get("channels") or [])
                if want is None or n == want:
                    _note_load_cost(project, time.time() - t0, "open"); return
            except Exception:
                pass                                              # FL busy loading
    threading.Thread(target=run, daemon=True).start()


# ---- (2) lazy reloads -----------------------------------------------------------------------------------------
RELOAD_MODES = ("auto", "lazy", "immediate")
LAZY_THRESHOLD_S = 8.0                                            # auto: lazy when a reload costs more than this
PENDING_DIR = os.path.join(os.path.dirname(STATE), "pending")
PENDING_FILE = os.path.join(PENDING_DIR, "queue.json")
_TEMP_ROOTS.append(os.path.normcase(os.path.abspath(PENDING_DIR)))   # shadow copies live in our own state folder
_PENDING_LOCK = threading.RLock()
_SYNC_LOCAL = threading.local()

# writers that may be queued: they only change the project file itself (no samples copied, no journal, no backups
# to restore from). Others always run at once (the queue is applied first, in the same save/reload).
LAZY_TOOLS = {"flp_replace_part", "flp_edit_notes", "flp_add_notes", "flp_new_pattern", "flp_drum_pattern", "flp_duck",
              "flp_arrange", "flp_pattern_tools", "flp_playlist", "flp_audio_clip_settings", "flp_style_channels",
              "flp_mixer", "flp_add_automation", "flp_add_audio_clip", "flp_load_plugin", "flp_remove_effect",
              "flp_add_channel", "flp_project_info", "flp_set_song_length", "flp_set_tempo", "flp_tempo_write",
              "flp_plugin_settings", "flp_instrument_sound", "flp_copy_state", "flp_edit", "flp_compose_write",
              "flp_channel_glide", "flp_remove_channels", "flp_write_arrangement"}
# ... of those, writers that build the project from ANOTHER file (template -> output): queued for the output when it's
# the open project (the template stays as given). PC 2026-10-26: write_arrangement + remove_channels reloaded at once.
LAZY_INTO_TOOLS = {"flp_write_arrangement"}
# readers that can read the shadow copy (project + queued edits) cleanly: they only look at the file's content
SHADOW_READERS = {"flp_info", "flp_list", "flp_notes", "flp_patterns", "flp_tempo_map", "flp_analyze_music",
                  "flp_export_midi", "flp_diff"}
# extension tools that need FL to hold the edits (core ones sync inside: render, listen, mix check, play, open, close)
SYNC_FIRST_TOOLS = {"fl_ab", "flp_perform", "flp_perform_setup", "flp_perform_undo"}   # (fl_finalize: FL closes / exports, both sync)
READ_ANNOTATE = {"fl_doctor", "flp_health"}                     # other readers that say when edits are queued
NOT_READERS = {"flp_finish_piece", "flp_restore", "flp_remove_channels", "flp_write_notes", "flp_write_arrangement", "flp_collect_samples",
               "flp_compose", "flp_arrange_song", "flp_adjust", "flp_perform", "flp_perform_setup", "flp_perform_undo"}
LAZY_TOOLS |= {"flp_meter", "flp_patterns_set"}                 # note / playlist writers added in 2.2
NOT_READERS.add("flp_new_from")


def _reload_mode_setting():
    """(mode, where it comes from): this PC's choice (flh_sync mode=...) > the collection profile's reload_mode > auto."""
    try:
        st = _state_get("reload_mode")
    except Exception:
        st = None
    if st in RELOAD_MODES:
        return st, "this PC (flh_sync mode=...)"
    try:
        store = sys.modules.get("flh_store")
        prof = (store.profile_get() or {}) if store and getattr(store, "H", None) else {}
        if prof.get("reload_mode") in RELOAD_MODES:
            return prof["reload_mode"], "collection profile"
    except Exception:
        pass
    return "auto", "default"


def _reload_mode(project):
    """'lazy' or 'immediate' for an edit of this project. auto: edits of the open project are merged and FL gets
    them in ONE save+reload shortly after the last one (_coalesce_s); without that, lazy when a load costs > 8 s."""
    mode, _src = _reload_mode_setting()
    if mode != "auto":
        return mode
    if _coalesce_s(project) > 0:
        return "lazy"
    c = project_load_cost(project).get("seconds")
    return "lazy" if c and c > LAZY_THRESHOLD_S else "immediate"


# ---- speed: merged edits (one reload for a burst of edits) and live routes (no reload at all) ----------------------
COALESCE_S = 2.5                 # quiet time after the last edit before FL gets the merged edits (one save+reload)
COALESCE_BIG_S = 8.0             # ... at least this for a project that takes long to load
COALESCE_MAX_S = 60.0            # ... and up to its own load time (capped here): while Claude builds a song, the next
                                 # edit usually comes within that, so a burst shares ONE reload instead of one each
                                 # (PC 2026-10-26: a song with Splice INSTRUMENT sounds took 14-52 s per reload).
                                 # Anything that needs FL to hold the edits (a render, a live setting, play, open)
                                 # applies them at once.
FAST_FORCE = None                # tests: True/False forces the fast paths on/off (default: on on Windows)


def _fast_on():
    v = os.environ.get("FLH_FAST")
    if v is not None:
        return v.strip().lower() not in ("0", "false", "off", "no")
    if FAST_FORCE is not None:
        return bool(FAST_FORCE)
    return sys.platform == "win32"


def _coalesce_s(project):
    """Seconds to wait for more edits before FL reloads (0 = merging off: every edit reloads at once)."""
    if not _fast_on():
        return 0.0
    try:
        v = float(os.environ.get("FLH_COALESCE_S", COALESCE_S))
    except ValueError:
        v = COALESCE_S
    if v <= 0:
        return 0.0
    c = project_load_cost(project).get("seconds") if project else None
    if c and c > LAZY_THRESHOLD_S:
        return max(v, COALESCE_BIG_S, min(float(c), COALESCE_MAX_S))
    return v


def _autosync_wanted(project):
    return _reload_mode_setting()[0] == "auto" and _coalesce_s(project) > 0


_AUTOSYNC = {}                   # project key -> {"due", "project", "thread"}
_AUTOSYNC_LOCK = threading.Lock()
_AUTOSYNC_NEWS = []              # what the background flushes did (shown with the next tool result)
_AUTOSYNC_NEWS_PATH = {}         # note -> the project it's about (_news_add)


def _schedule_autosync(project, delay=None):
    """FL gets this project's queued edits (and live changes saved) once nothing new came for `delay` seconds."""
    k = _ud_key(project); d = _coalesce_s(project) if delay is None else float(delay)
    with _AUTOSYNC_LOCK:
        ent = _AUTOSYNC.setdefault(k, {})
        ent["due"] = time.time() + d; ent["project"] = os.path.abspath(project)
        th = ent.get("thread")
        if th is not None and th.is_alive():
            return
        th = threading.Thread(target=_autosync_run, args=(k,), daemon=True, name="flh-autosync")
        ent["thread"] = th
        th.start()


def _autosync_run(k):
    while True:
        with _AUTOSYNC_LOCK:
            ent = _AUTOSYNC.get(k) or {}
            wait = ent.get("due", 0) - time.time(); project = ent.get("project")
            live_dirty = ent.get("live_dirty")
        if wait > 0:
            time.sleep(min(wait, 0.25))
            continue
        q = _pending_get(project) if project else []
        if q and not _autosync_wanted(project):                   # lazy / immediate mode: queued edits wait for
            q = []                                                # flh_sync; only live changes get saved here
        if not q and not live_dirty:
            with _AUTOSYNC_LOCK:
                if (_AUTOSYNC.get(k) or {}).get("due", 0) <= time.time():
                    _AUTOSYNC.pop(k, None)
                    return
            continue
        T = time.time(); held = False
        try:
            if q:                                                 # a check of the previous reload steps aside: this
                # PC-VERIFY: two bursts of edits ~3 s apart: the 2nd merged reload ~1 s, not ~12 s
                _verify_step_aside()                              # flush's own save checks that edit (PC 2026-10-22: a
            waited, t_last = 0.0, time.time()                     # merged reload waited ~10 s for the last one's check)
            while not _FL_LOCK.acquire(timeout=1.0):              # a foreground FL step first; we go right after
                now = time.time(); what = str(_FL_HOLDER.get("what") or "")
                if not what.startswith("job"):                    # a background job holding FL (fl_pc_check, a
                    waited += now - t_last                        # render) has its own deadline: wait for it, the
                t_last = now                                      # time doesn't count (PC 2026-10-23: 'stayed busy
                if waited > _scaled(600):                         # for 10 minutes' behind fl_pc_check)
                    raise RuntimeError(f"FL stayed busy for 10 minutes ({_fl_busy_with()})")
                with _AUTOSYNC_LOCK:
                    gone = k not in _AUTOSYNC
                if gone:                                          # forgotten while waiting (a check's sandbox song:
                    return                                        # fl_pc_check / fl_bench _forget_sandbox)
                if q and what.startswith("checking"):
                    _verify_step_aside()
            held = True
            prev = _FL_HOLDER.get("what")
            _FL_HOLDER["what"] = "putting the last edits into FL (a few seconds)"
            try:
                with _AUTOSYNC_LOCK:
                    (_AUTOSYNC.get(k) or {}).pop("live_dirty", None)
                if q:
                    r = _sync_pending(project) or {}
                    s_ = next(iter(r.values()), {}) if r else {}
                    if isinstance(s_, dict) and s_.get("error"):  # e.g. the file is gone: nothing went in, and
                        raise RuntimeError(s_["error"])           # retrying at once would spin forever
                    if r:
                        _news_add(project, _merged_news(project, s_, len(q), time.time() - T))
                elif live_dirty and _open_in_fl(project):
                    _save_in_fl_and_wait(project, 8.0)            # live changes into the file (no reload)
            finally:
                _FL_HOLDER["what"] = prev
        except Exception as e:                                    # noqa: BLE001 - kept queued, said at the next call
            _state({"verify_alert": f"{os.path.basename(project or '?')}: queued edits couldn't be put into FL "
                                    f"automatically ({type(e).__name__}: {str(e)[:160]}); they're still queued - "
                                    "flh_sync() tries again, flh_sync(discard=true) drops them"})
            with _AUTOSYNC_LOCK:
                _AUTOSYNC.pop(k, None)
            return
        finally:
            if held:
                _FL_LOCK.release()


def _merged_news(project, s_, n, took):
    """What a background flush of merged edits really did - 'in FL now' only when FL reloaded them (and a reload that
    was implausibly fast for the project was checked by FL's save)."""
    name = os.path.basename(project); n = s_.get("ops", n) if isinstance(s_, dict) else n
    s_ = s_ if isinstance(s_, dict) else {}
    chk = s_.get("reload_check") or {}
    if s_.get("reloaded_in_fl") is True:
        how = f"one reload, {took:.1f} s"
        if chk.get("verified") is True:
            how += f"; checked by FL's save (the reload took {chk.get('reload_s')} s, the project loads in ~"\
                   f"{chk.get('load_cost_s')} s)"
        elif chk:
            how += f"; NOT confirmed: {chk.get('note')}"
        return f"{name}: {n} merged edit(s) are in FL now ({how})"
    why = s_.get("WARNING") or s_.get("note") or s_.get("fl_has_open") or "FL wasn't reloaded"
    return f"{name}: {n} merged edit(s) are in the FILE, but not confirmed in FL ({str(why)[:220]})"


def _verify_step_aside():
    """A background check of the last edit stops at its next step, within ~1 s (the next edit's own save checks that
    edit instead): the generation moves on. (_VERIFY_STOP isn't touched: it belongs to whoever waits for FL.)"""
    _PENDING_VERIFY["__gen"] = _PENDING_VERIFY.get("__gen", 0) + 1


def _pop_autosync_news():
    """The background flushes' notes, minus those about a file that's gone since (a sandbox copy fl_bench /
    fl_pc_check recycled: PC 2026-10-24 a bench's 'Bench Trap.flp: levels balanced' came after FL was back on the
    user's song)."""
    out = list(_AUTOSYNC_NEWS); del _AUTOSYNC_NEWS[:]
    paths = dict(_AUTOSYNC_NEWS_PATH); _AUTOSYNC_NEWS_PATH.clear()
    return [t for t in out if not paths.get(t) or os.path.exists(paths[t])]


def _news_add(project, text):
    """A background note about `project` for the next tool result (dropped if the file is gone by then)."""
    _AUTOSYNC_NEWS.append(text)
    if project:
        _AUTOSYNC_NEWS_PATH[text] = os.path.abspath(project)


def _live_route_ok(project):
    """A writer may go into FL live (no file edit, no reload): fast paths on, FL has exactly this project open, the
    bridge answers, and no file edits are queued for it (their order stays simple)."""
    if not _fast_on() or _reload_mode_setting()[0] == "immediate" or _pending_get(project):
        return False
    try:
        return fl_running() and _open_in_fl(project)
    except Exception:
        return False


def _live_batch(project, ops, label, res):
    """Run live ops in FL as one undo step; None (caller edits the file instead) unless every op worked."""
    try:
        r = fl_batch(ops, label=label)
    except Exception:
        return None
    if int(r.get("done") or 0) != len(ops):
        return None                                               # the file route sets the same values again
    _note_live_change("fl_batch", {"ops": ops})                   # in FL, not yet in the file
    with _AUTOSYNC_LOCK:
        _AUTOSYNC.setdefault(_ud_key(project), {})["live_dirty"] = True
    _schedule_autosync(project)                                   # FL saves them into the file in a moment
    res.update(live=True, reloaded_in_fl=False, note="done live in FL: no reload (FL saves it into the file in a moment)")
    return res


def _live_flp_mixer(project, kw):
    ops = _mixer_live_ops(kw)
    if not ops:
        return None
    res = _live_batch(project, ops, "flp_mixer", {"output": project, "tracks": [o["track"] for o in ops]})
    if res is None:
        return None
    for o in ops:                                                 # a fader set is read back in a later call (FL
        if o.get("volume_db") is None:                            # 2026 applies it after the bridge's callback):
            continue                                              # one that didn't hold -> the file route
        want = _fader(min(float(o["volume_db"]), FADER_TOP_DB))
        try:
            ok = _vol_verify(lambda t=o["track"]: BRIDGE.call("mixer_set", track=int(t), timeout=5.0), want,
                             {}, resend=None)[0]
        except Exception:                                         # noqa: BLE001
            ok = False
        if not ok:
            return None                                           # the file route sets the same values again
    return res


def _mixer_live_ops(kw):
    ops = []
    for t in kw.get("tracks") or []:
        if set(t) - {"track", "name", "color", "volume_db", "pan", "route_to", "unroute"}:
            return None
        op = {"op": "mixer", "track": int(t["track"])}
        for f in ("name", "color", "volume_db", "pan"):
            if t.get(f) is not None:
                op[f] = t[f]
        for f in ("route_to", "unroute"):
            if t.get(f):
                op[f] = ",".join(str(int(x)) for x in t[f])
        ops.append(op)
    return ops


def _live_flp_style_channels(project, kw):
    ops = _style_live_ops(kw)
    if not ops:
        return None
    return _live_batch(project, ops, "flp_style_channels", {"output": project, "styled_channels": [o["index"] for o in ops]})


def _style_live_ops(kw):
    ops = []
    for c in kw.get("channels") or []:
        if c.get("icon") is not None or set(c) - {"channel", "name", "color", "icon"}:
            return None                                           # icons only exist in the file
        op = {"op": "channel", "index": int(c["channel"])}
        for f in ("name", "color"):
            if c.get(f) is not None:
                op[f] = c[f]
        ops.append(op)
    return ops


def _live_flp_edit(project, kw):
    """flp_edit whose every op is a mixer / channel name-color edit (and at most one plain tempo): one live batch,
    no reload. Anything else in it: None (the file route runs the whole edit as one merged step)."""
    if kw.get("output") and os.path.normcase(os.path.abspath(kw["output"])) != os.path.normcase(os.path.abspath(project)):
        return None
    ops, tempo = [], None
    for o in kw.get("ops") or []:
        if not isinstance(o, dict):
            return None
        tool = o.get("tool"); args = {k: v for k, v in o.items() if k not in ("tool", "project", "output", "path")}
        if tool == "flp_mixer":
            got = _mixer_live_ops(args)
        elif tool == "flp_style_channels":
            got = _style_live_ops(args)
        elif tool == "flp_set_tempo" and tempo is None and set(args) <= {"bpm"}:
            tempo = args.get("bpm"); got = [] if tempo is not None else None
        else:
            return None
        if got is None or (not got and tool != "flp_set_tempo"):
            return None
        ops += got
    if not ops and tempo is None:
        return None
    if tempo is not None:
        r = _live_flp_set_tempo(project, {"bpm": tempo})
        if r is None:
            return None
    if ops:
        r = _live_batch(project, ops, "flp_edit", {"output": project, "ops": len(kw.get("ops") or [])})
        if r is None:
            return None
    else:
        r = dict(r, output=project, ops=1)
    return r


def _live_flp_set_tempo(project, kw):
    """The song tempo, live (one bridge call). A song whose tempo moves (a tempo lane) is edited in the file."""
    try:
        if len({round(b, 3) for _, b in _song_x(_load(project), _events(_load(project)))[1]}) > 1:
            return None
        bpm = float(kw["bpm"])
        r = BRIDGE.call("set_tempo", bpm=bpm, timeout=4.0)
    except Exception:
        return None
    if abs(float(r.get("tempo") or 0) - bpm) > 0.01:
        return None
    _note_live_change("fl_set_tempo")
    with _AUTOSYNC_LOCK:
        _AUTOSYNC.setdefault(_ud_key(project), {})["live_dirty"] = True
    _schedule_autosync(project)
    return {"path": project, "tempo_bpm": round(bpm, 3), "live": True, "reloaded_in_fl": False,
            "note": "done live in FL: no reload (FL saves it into the file in a moment)"}


LIVE_ROUTES = {"flp_mixer": _live_flp_mixer, "flp_style_channels": _live_flp_style_channels,
               "flp_set_tempo": _live_flp_set_tempo, "flp_edit": _live_flp_edit}


OPEN_WAIT_CAP_S = 1200.0          # the longest an open is waited for while FL visibly keeps loading (fast-PC seconds)
OPEN_LOADING_GRACE_S = 60.0       # after FL's title last said 'Opening: ...': this long for the project's name to show
# FL's title while it loads a project: 'Opening: <plugin>' (FL 2026, English UI).
# PC-VERIFY: the loading title in FL's other UI languages (add the word here when it differs)
LOADING_TITLE_RE = re.compile(r"^\s*(opening|loading|öffne|wird geöffnet|ouverture|abriendo|apertura|abrindo)\b", re.I)
_OPEN_WAIT = {"why": None}        # why the last _wait_open_in_fl gave up (for the caller's message)


def _fl_loading_title():
    """FL's window title while it is still loading a project ('Opening: Fruity Wrapper'), else None."""
    try:
        wins = _fl_windows()
    except Exception:
        return None
    for _h, t in wins:
        if LOADING_TITLE_RE.match(str(t or "")):
            return str(t)
    return None


def _load_cost_guess(project):
    """(seconds, where from) FL is expected to take to load `project`: its own measured load cost, else the project
    it is a version / copy of (journal 'version_of', a file with the same Project-info title or name), else the
    slowest load measured on this PC; (None, None) when nothing was ever measured."""
    try:
        c = project_load_cost(project).get("seconds")
        if c:
            return float(c), "measured"
    except Exception:
        pass
    srcs = []
    try:
        st = sys.modules.get("flh_store")
        if st and getattr(st, "H", None):
            v = (st.journal_get(project) or {}).get("version_of")
            if isinstance(v, str) and v:
                srcs.append(v)
    except Exception:
        pass
    try:
        srcs += _title_twins(project)
    except Exception:
        pass
    for s in srcs:
        try:
            c = project_load_cost(s).get("seconds")
        except Exception:
            c = None
        if c:
            return float(c), f"as {os.path.basename(s)} (its copy / version)"
    try:
        allc = [float(e.get("avg_s") or 0) for e in _json_read(LOAD_COSTS, {}).values() if isinstance(e, dict)]
        if allc and max(allc) > 0:
            return max(allc), "the slowest load measured on this PC"
    except Exception:
        pass
    return None, None


def _title_twins(project):
    """Other .flp files in FLH_ROOTS (FL's backups left out) whose Project-info title is this project's title: FL's
    window shows the title, so FL can't be told apart from them by its window."""
    try:
        t = _flp_title_fast(project)
    except (OSError, ValueError, struct.error):
        return []
    hits = _find_by_title(t) if t else []
    return [h for h in hits if _ud_key(h) != _ud_key(project) and not _is_backup_copy(h) and os.path.isfile(h)]


def _title_warning(project):
    """{shared_title, with, fix} when another project in FLH_ROOTS has this project's Project-info title (e.g. a copy
    made in Explorer), else None. The fix gives the copy a unique title (its file name)."""
    try:
        twins = _title_twins(project)
    except Exception:
        return None
    if not twins:
        return None
    title = _flp_title_fast(project)
    want = next((t for t in (_derived_title(title, _stem(w), _stem(project)) for w in twins) if t), None) \
        or os.path.splitext(os.path.basename(project))[0]
    if want.strip().lower() == str(title).strip().lower():
        want = want + " (2)"
    return {"shared_title": title, "with": [_rel(t) for t in twins[:4]],
            "why": "FL's window shows the Project-info title, so with two files titled alike fl-headless needs a save "
                   "through FL to tell which one is open (slower, and impossible while FL is busy)",
            "fix": f"flp_project_info(path={project!r}, output={project!r}, title={want!r})"}


def _open_fail(project):
    """The message for 'FL didn't open project': what was seen while waiting, and a same-title warning."""
    msg = f"FL didn't open {os.path.basename(project)}"
    if _OPEN_WAIT.get("why"):
        msg += f" ({_OPEN_WAIT['why']})"
    w = _title_warning(project)
    if w:
        msg += (f". Its Project-info title '{w['shared_title']}' is shared with {', '.join(w['with'])}: give it a "
                f"unique title - {w['fix']}")
    return msg


OPEN_IDLE_S = 20.0                # FL quiet this long (no loading title, no title change, not busy): it isn't loading
OPEN_PROOF_GAP_S = (3.0, 4.0, 30.0)   # first identity save after, then every (growing to at most) seconds


def _wait_open_in_fl(project, timeout_s=240):
    """Wait until FL has `project` open. FL's title shows the project's NAME or its Project-info title, so when another
    file shows the same (a copy in another folder, or a byte copy that kept the title) the title alone never tells:
    a save through the bridge proves which file FL holds - tried again every few seconds (FL may still have the old
    one, or be too busy to save) instead of waiting out the deadline (PC 2026-10-21: an export waited 4 minutes on a
    same-name twin; PC 2026-10-23: 372 s on a same-TITLE copy, then failed while FL was still loading). 'Title
    matches but ambiguous' is always 'prove it' - also while an older proof names the twin.
    The wait follows the project's measured load cost (its copy's source, or the slowest load measured here, when it
    has none) and this PC's speed. FL's title 'Opening: <plugin>' means FL is still loading, and any change of FL's
    title is progress: the wait goes on (up to OPEN_WAIT_CAP_S). It fails only once the deadline has passed AND FL
    has been idle (no loading title, no title change, not busy) for OPEN_IDLE_S without the target open."""
    cost, src = _load_cost_guess(project)
    base = max(float(timeout_s), 2.5 * cost + 30.0) if cost else float(timeout_s)
    t0 = time.time(); deadline = t0 + _scaled(base)
    cap = t0 + _scaled(max(base, OPEN_WAIT_CAP_S, 4.0 * (cost or 0.0)))
    idle_s = _scaled(OPEN_IDLE_S)
    names = _project_names(project)
    first, gap, gap_max = OPEN_PROOF_GAP_S
    next_proof, proofs, loading, other = t0 + first, 0, None, None
    seen, last_change, still = None, t0, None
    _OPEN_WAIT["why"] = None
    while True:
        st = _open_state(project)
        if st == "open":
            _note_fl_holds(project)
            return True
        now = time.time()
        lt = _fl_loading_title()
        mt = _main_title()
        if (lt, mt) != seen:                                      # FL's title moved on: progress
            seen, last_change = (lt, mt), now
        if lt:                                                    # FL still loading: progress, not a failure
            loading = lt; last_change = now
            if now >= cap:                                        # ... up to the cap (a load that never ends)
                still = lt
                break
            time.sleep(0.5)
            continue
        if now >= deadline:
            busy = now - last_change < idle_s
            if not busy:                                          # FL's UI thread busy (its script's heartbeat
                try:                                              # stopped: loading) - not its CPU (plugins run)
                    hb = os.path.join(_mailbox_dir(), "alive.json")
                    busy = os.path.exists(hb) and not _mailbox_alive(max_age=3.0) and fl_running()
                except Exception:
                    busy = False
                if busy:
                    last_change = now
            if not busy or now >= cap:
                break
        if now >= next_proof and (_title_stem(mt) or "").lower() in names:   # ambiguous: prove it
            proofs += 1
            try:
                got = _prove_open(project)
            except Exception:
                got = None
            if isinstance(got, str) and got != "never_saved":
                if _ud_key(got) == _ud_key(project):
                    return True
                other = got                                       # FL still holds the twin: wait, ask again
            next_proof = time.time() + gap; gap = min(gap * 1.6, gap_max)
            continue
        time.sleep(0.5)
    waited = time.time() - t0
    bits = [f"waited {waited:.0f} s" + (f"; this project loads in ~{cost:.0f} s ({src})" if cost else "")]
    if still:
        bits.append(f"FL still showed '{still[:60]}' after the longest wait")
    elif loading:
        bits.append(f"FL last showed '{loading[:60]}' and then stayed idle")
    if other:
        bits.append(f"FL's save landed in {_rel(other)}, a file with the same name/title")
    elif proofs:
        bits.append(f"{proofs} save(s) through FL didn't land in it")
    _OPEN_WAIT["why"] = "; ".join(bits)
    return False


def _fl_load_file(project, why="render"):
    """Make FL hold `project` exactly as it is on disk before FL itself uses it (its export renders what FL has
    LOADED, not the file). -> {how: 'already' | 'reloaded' | 'opened' | 'fl_closed', steps_s}.
    - FL shows it (or a same-title twin, then a save through the bridge proves which): 'already' - unless
      fl-headless wrote the file after FL loaded it (FL holds an older copy): then reloaded WITHOUT saving FL's copy
      over the file ('reloaded');
    - FL shows another project: opened through FL's Open dialog (FL's own project is saved first) and waited for
      through the whole load ('opened'). Raises InFlUnavailable when FL didn't end up holding it."""
    steps = {}; T = time.time()
    if not fl_running():
        return {"how": "fl_closed", "steps_s": steps}
    project = os.path.abspath(project)
    act = _live_mutes_active()

    def no_load(what):                                            # a load now would drop the live mutes (the
        if act:                                                   # 'solo' export = the whole mix): refused
            raise InFlUnavailable(f"channel(s) {list(act.get('channels') or [])[:16]} of "
                                  f"{os.path.basename(act['project'])} are muted live for a solo render, and FL would "
                                  f"have to {what} {os.path.basename(project)} first - that drops the mutes, so the "
                                  "export would be the whole mix: nothing was rendered (FL is loaded first, then "
                                  "muted, when it runs again)")
    cur = None
    try:
        cur, _ = _open_project_guess()
    except Exception:
        cur = None
    if not cur or _ud_key(cur) != _ud_key(project):
        stem = _title_stem(_main_title())
        if stem and stem.lower() in _project_names(project) and not _stale_get(project) and not act:
            try:                                                  # the title names it (maybe a twin): prove it
                got = _prove_open(project)
            except Exception:
                got = None
            steps["identity_save"] = round(time.time() - T, 1)
            if isinstance(got, str) and got != "never_saved" and _ud_key(got) == _ud_key(project):
                cur = project
    if cur and _ud_key(cur) == _ud_key(project):
        stale = _stale_get(project)
        older = None if stale else _fl_copy_older(project)        # the file changed behind FL (a copy put over it,
        if not stale and not older:                               # another program, a save by hand in FL)
            return {"how": "already", "steps_s": steps}
        # PC-VERIFY: checklists/core.md 'fl_open safety' 13 (a copy put over the open song, then a render in FL)
        if older and _fl_changed_flag() != 0:                     # FL's export would render FL's copy, not the file
            raise InFlUnavailable(older + ", and FL has unsaved changes (or can't say), so FL's export would render "
                                  "FL's copy instead of the file: nothing was rendered. fl_open(project, "
                                  "save_current=false) loads the file (FL's changes dropped); fl_save() keeps FL's")
        no_load("reload")
        T = time.time()
        try:                                                      # FL holds an older copy: load the file (FL has
            with _reload_verified():                              # nothing unsaved when `older`), proven - never a
                steps.update(_reload_in_fl(project, discard=bool(older)) or {})   # render of FL's old copy
            if steps.get("unproven"):                             # FL was told to load it, not proven: no render
                raise RuntimeError(steps.pop("unproven"))         # taken as the file's
        except Exception as e:
            raise InFlUnavailable(f"FL holds an older copy of {os.path.basename(project)} than the file and couldn't "
                                  f"be made to load it ({type(e).__name__}: {e}); nothing was rendered") from e
        _wait_for(lambda: _ping_ok(), _scaled(max(60.0, 2.0 * (_load_cost_guess(project)[0] or 0.0))), 0.5)
        steps["reload"] = round(time.time() - T, 1)
        return {"how": "reloaded", "steps_s": steps}
    no_load("open")
    T = time.time()
    fl_open(project)
    if not _wait_open_in_fl(project, 240):
        raise InFlUnavailable(_open_fail(project))
    _wait_for(lambda: _ping_ok(), _scaled(max(240.0, 2.0 * (_load_cost_guess(project)[0] or 0.0))), 0.5)
    steps["open"] = round(time.time() - T, 1)
    return {"how": "opened", "steps_s": steps}


def _fl_load_fresh(project):
    """Load `project` from disk into FL WITHOUT saving FL's project first - for a render that came out as another
    state of the song (shorter than the file's). Only when FL reports no unsaved changes: answering No to 'save
    changes?' then loses nothing, whichever file FL holds (the file itself, a same-title twin or an older copy).
    FL showing exactly this project: reloaded in place (proven re-read); else a blank project first (so a file FL
    already holds is really read again), then the file, waited for through the whole load. -> {how, steps_s}.
    PC-VERIFY: with FL holding an older copy (no unsaved changes), this loads the file and FL then shows the edit"""
    if not fl_running():
        return {"how": "fl_closed", "steps_s": {}}
    flag = _fl_changed_flag()
    if flag != 0:
        raise RuntimeError("FL has unsaved changes (or its bridge can't say), so the file wasn't loaded over them")
    project = os.path.abspath(project); steps = {}; T = time.time()
    if _open_state(project) == "open" or _proven_open(project):
        with _reload_verified():                                  # FL showed another state of the song: proven
            steps.update(_reload_in_fl(project) or {})            # reload (marker), never FL's own copy again
        if steps.get("unproven"):
            raise RuntimeError(steps.pop("unproven"))
    else:
        blank = _blank_project()
        cur = None
        try:
            cur = _open_project_guess()[0]
        except Exception:
            cur = None
        ok = [project] + ([cur] if cur else [])
        if blank and _ud_key(blank) != _ud_key(project):
            _open_running_or_fail(blank, on_save="no", discard_ok=ok)
            _fl_load_seen(20.0)
        _open_running_or_fail(project, on_save="no", discard_ok=ok + ([blank] if blank else []))
        _OPEN_PROOF["path"] = None
        if cur:
            _fl_forget(cur)
        if not _wait_open_in_fl(project, 240):
            raise InFlUnavailable(_open_fail(project))
        _stale_clear(project); _note_fl_holds(project)
        _state({"last_opened": project})
    _wait_for(lambda: _ping_ok(), _scaled(max(60.0, 2.0 * (_load_cost_guess(project)[0] or 0.0))), 0.5)
    steps["load_fresh"] = round(time.time() - T, 1)
    return {"how": "loaded_fresh", "steps_s": steps}


def _open_in_fl(project):
    """True when FL runs and has this project open."""
    try:
        return _open_state(project) == "open"
    except Exception:
        return False


def _pending_all():
    return _json_read(PENDING_FILE, {})


def _pending_get(project):
    if not project:
        return []
    return list((_pending_all().get(_ud_key(project)) or {}).get("ops") or [])


def _shadow_path(project):
    import hashlib
    h = hashlib.sha1(_ud_key(project).encode("utf-8")).hexdigest()[:12]
    return os.path.join(PENDING_DIR, h, os.path.basename(project))


def _file_sig(path):
    st = os.stat(path)
    return [st.st_mtime_ns, st.st_size]


def _pending_set(project, ops, base=None):
    """Store the queue of one project (empty: forget it and its shadow copy)."""
    with _PENDING_LOCK, _file_lock(PENDING_FILE + ".lock") if _mkdirs(PENDING_DIR) else _nullctx():
        d = _pending_all(); k = _ud_key(project)
        if ops:
            old = d.get(k) or {}
            d[k] = {"project": os.path.abspath(project), "ops": ops, "since": old.get("since") or int(time.time()),
                    "base": base or old.get("base")}
        else:
            d.pop(k, None)
            shutil.rmtree(os.path.dirname(_shadow_path(project)), ignore_errors=True)   # our own temp copy
        _json_write(PENDING_FILE, d)


def _shadow(project):
    """(path, base signature) of the shadow copy: the project file with the queued edits applied. Built on first use
    and rebuilt when the real file changed (FL or the user saved it): the queued edits are replayed on the new file."""
    with _PENDING_LOCK:
        sh = _shadow_path(project); ent = _pending_all().get(_ud_key(project)) or {}
        if _INFLIGHT.get(_ud_key(project)) and os.path.isfile(sh):
            return sh, ent.get("base")                            # mid-flush the file is half-way: the shadow is right
        sig = _file_sig(project)
        if os.path.isfile(sh) and ent.get("base") == sig:
            return sh, sig
        os.makedirs(os.path.dirname(sh), exist_ok=True)
        shutil.copyfile(project, sh)
        ops = ent.get("ops") or []
        if ops:
            try:
                _run_plan(sh, _plan_ops(sh, ops))
            except Exception as e:
                raise RuntimeError(f"the project changed on disk and the {len(ops)} queued edit(s) no longer apply to it "
                                   f"({e}). flh_sync(discard=true) drops them") from e
            ent["base"] = sig; d = _pending_all(); d[_ud_key(project)] = ent; _json_write(PENDING_FILE, d)
        return sh, sig


def _unshadow(r, sh, src, n, read=False):
    """A result computed on the shadow copy, with the shadow's path put back to the project's."""
    a, b = sh, os.path.abspath(src)

    def fix(v):
        if isinstance(v, str):
            return v.replace(a, b) if a in v else v
        if isinstance(v, dict):
            return {k: fix(x) for k, x in v.items()}
        if isinstance(v, list):
            return [fix(x) for x in v]
        return v
    r = fix(r)
    if isinstance(r, dict) and n:
        r["pending_ops"] = n
        r["pending_note"] = (f"{n} queued edit(s) are included here but not in FL yet" if read else
                             f"{n} edit(s) queued for this project: FL gets them in one save+reload at flh_sync() - or "
                             "automatically before listening, rendering, playing or switching projects")
    return r


def _read_only_call(name, kw):
    return ((name == "flp_project_info" and not kw.get("output"))
            or (name == "flp_remove_channels" and kw.get("dry_run"))
            or (name == "flp_playlist" and kw.get("action", "list") == "list")
            or (name == "flp_audio_clip_settings" and not any(v is not None for k, v in kw.items()
                                                                 if k not in ("project", "channel", "output"))))


def _lazy_wanted(project):
    """Lazy mode and FL has this project open. When FL's title can't tell (e.g. a same-name file elsewhere), one save
    through the bridge proves it, so the very first edit queues too (PC 2026-10-20: it went in immediately)."""
    if _reload_mode(project) != "lazy":
        return False
    if _open_in_fl(project):
        return True
    try:
        if fl_running() and _open_state(project) == "unknown":
            got = _prove_open(project)
            return isinstance(got, str) and got != "never_saved" and _ud_key(got) == _ud_key(project)
    except Exception:
        pass
    return False


def _fl_behind(project):
    """Why FL is known to hold an OLDER copy of `project` than the file fl-headless wrote (a reload that failed or
    wasn't proven), or None. (A file changed behind FL by someone else - a save by hand - isn't counted: FL may hold
    exactly that.)"""
    try:
        e = _stale_get(project)
        return (e.get("why") or "its last reload wasn't proven") if e else None
    except Exception:                                             # noqa: BLE001
        return None


def _run_lazy(name, raw, kw, in_key, out_key, src, writer=True, keep_in=False):
    """Run a writer on the shadow copy (so it's validated and returns its real result now) and queue it when it
    changed something. Nothing touches FL or the real file. A writer that changes nothing because the FILE already
    holds it while FL holds an older copy is queued too: the sync then loads the file into FL (PC 2026-10-27: a
    flp_tempo_write after a sync FL hadn't taken said nothing, flh_sync 'nothing was queued', FL kept its old tempo).
    keep_in: the writer builds `src` from another file (flp_write_arrangement's template): that input stays as given."""
    global _EDIT_DEPTH
    with _PENDING_LOCK:
        sh, sig = _shadow(src)
        before = open(sh, "rb").read()
        kw2 = dict(kw)
        if not keep_in:
            kw2[in_key] = sh
        if out_key:
            kw2[out_key] = sh
        _edit_enter()
        try:
            if keep_in:
                with _write_source(kw[in_key]):                   # a copy under another name: its own title
                    r = raw(**kw2)
            else:
                r = raw(**kw2)
        finally:
            _edit_exit()
        changed = open(sh, "rb").read() != before
        q = _pending_get(src)
        behind = None if changed or not writer else _fl_behind(src)
        queue = changed or bool(behind)
        merge = queue and _autosync_wanted(src)
        if queue:
            if name == "flp_edit":
                add = [dict(o) for o in (kw.get("ops") or [])]
            elif keep_in:
                add = [{"tool": name, "_keep_input": True, in_key: os.path.abspath(kw[in_key]),
                        **{k: v for k, v in kw.items() if k not in (in_key, out_key)}}]
            else:
                add = [{"tool": name, **{k: v for k, v in kw.items() if k not in (in_key, out_key)}}]
            q = q + add
            _pending_set(src, q, base=sig)
        elif not q:
            _pending_set(src, [])                                 # a read: no shadow to keep
        r = _unshadow(r, sh, src, len(q), read=not queue)
        if behind and isinstance(r, dict):
            r["fl_behind"] = (f"the file already holds this, but FL holds an older copy ({str(behind)[:160]}): it's "
                              "queued so the sync loads the file into FL")
        elif writer and not changed and isinstance(r, dict) and not q:
            r.setdefault("note", "nothing changed: the project already holds this, so nothing was queued")
        changed = queue
        if changed and isinstance(r, dict):
            c = project_load_cost(src).get("seconds")
            r["queued"] = True
            r["reload"] = "lazy" + (f" (this project takes ~{c:g} s to load in FL)" if c else "")
        inline = merge and _job_holds_fl()
        if merge and not inline:
            _schedule_autosync(src)
            if isinstance(r, dict):
                r["reload"] = "merged"
                r["pending_note"] = (f"{len(q)} edit(s) merged: FL gets them in ONE reload {_coalesce_s(src):g} s after "
                                     "the last edit (send the rest of a change right away - it joins the same reload)")
    if inline:                                                    # a job holding FL (fl_pc_check, fl_bench, a recipe):
        try:                                                      # a background merge would wait for this very job
            s = _sync_pending(src) or {}                          # (PC 2026-10-23: 10 min, then 'still queued'), so
        except Exception as e:                                    # the edit goes into FL here, in the job's thread
            _schedule_autosync(src)                               # (FL lock first, then _SYNC_RUN_LOCK)
            if isinstance(r, dict):
                r["reload"] = "merged"
                r["pending_note"] = f"still queued: putting it into FL failed ({type(e).__name__}: {str(e)[:120]})"
            return r
        if isinstance(r, dict):
            ent = next(iter(s.values()), {}) if s else {}
            r.update(queued=False, reload="now (a job holds FL, so it went in at once)")
            r.pop("pending_note", None); r.pop("pending_ops", None)
            for x in ("reloaded_in_fl", "verify_job", "WARNING"):
                if x in ent:
                    r[x] = ent[x]
    return r


def _job_holds_fl():
    """This thread is a background job (or a call handed over as one) that holds the FL lock: nothing else can drive
    FL until it ends, so work it leaves to another thread would wait for it."""
    try:
        if not _FL_LOCK._is_owned():
            return False
    except Exception:
        return False
    return bool(getattr(_JOB_LOCAL, "job", None)) or str(_FL_HOLDER.get("what") or "").startswith("job")


def _lazy_tool(name, fn):
    """TOOLS wrapper for a project writer: queue the edit (lazy mode, project open in FL) or run it as before."""
    import inspect
    raw = getattr(fn, "__wrapped__", fn)
    try:
        sig = inspect.signature(raw).parameters
    except (TypeError, ValueError):
        return fn
    in_key = _OPEN_PROJECT_GUARD.get(name, (None,))[0] or next((k for k in ("project", "path") if k in sig), None)
    out_key = "output" if "output" in sig else None
    if not in_key:
        return fn

    def run(**kw):
        src = kw.get(in_key)
        if _editing_here() or not isinstance(src, str) or not os.path.isfile(src):
            return fn(**kw)
        out = (kw.get(out_key) or src) if out_key else src
        same = _ud_key(out) == _ud_key(src)
        q = _pending_get(src)
        if q and not _open_in_fl(src) and _open_state(src) != "unknown":   # FL closed / switched: the queue goes
            _sync_before(name, src); q = []                       # into the file (still loading: keep it queued)
        if same and name == "flp_playlist" and kw.get("clips"):  # clip ids change when FL saves: never queue those
            return fn(**kw)
        if same and _read_only_call(name, kw):
            if not q:
                return fn(**kw)
            return _run_lazy(name, raw, kw, in_key, out_key, src, writer=False)
        if not same and not q and name in LAZY_INTO_TOOLS and isinstance(out, str) and os.path.isfile(out) \
                and (_pending_get(out) or _lazy_wanted(out)):     # built from another file INTO the open project
            return _run_lazy(name, raw, kw, in_key, out_key, out, keep_in=True)
        if same and name in LIVE_ROUTES and not q and _fast_on():  # FL's title can't tell (a 'Project N' name, a
            try:                                                    # same-name twin): one save proves which file FL
                if fl_running() and _open_state(src) == "unknown":  # has, so the edit goes live instead of being
                    _prove_open(src)                                # queued behind FL's older copy (PC check
            except Exception:                                       # 2026-10-22: core.identity_save, 'Project N')
                pass
        if same and name in LIVE_ROUTES and _live_route_ok(src):
            live = LIVE_ROUTES[name](src, kw)
            if live is not None:
                return live
        if same and (q or _lazy_wanted(src)):
            if name in LIVE_NOTE_TOOLS and not q:                 # note edits: live in FL when it can (no reload)
                live = _live_replace_part(src, kw, name=name)
                if live is not None:
                    return live
            return _run_lazy(name, raw, kw, in_key, out_key, src)
        if same and name in LIVE_NOTE_TOOLS and _open_in_fl(src):
            live = _live_replace_part(src, kw, name=name)
            if live is not None:
                return live
        if q:                                                     # output elsewhere: read the queued state
            sh, _sig = _shadow(src); kw2 = dict(kw); kw2[in_key] = sh
            return _unshadow(fn(**kw2), sh, src, len(q), read=True)
        return fn(**kw)
    run.__wrapped__ = raw
    run.__lazy__ = True
    return run


def _pending_read_tool(name, fn):
    """TOOLS wrapper for a reader: with edits queued for its project it reads the shadow copy (SHADOW_READERS) or
    says the result doesn't include them."""
    import inspect
    raw = getattr(fn, "__wrapped__", fn)
    try:
        sig = inspect.signature(raw).parameters
    except (TypeError, ValueError):
        return fn
    key = next((k for k in ("path", "project") if k in sig), None)
    if not key:
        return fn

    def run(**kw):
        src = kw.get(key)
        q = _pending_get(src) if isinstance(src, str) and os.path.isfile(src) else []
        if not q:
            return fn(**kw)
        if name in SHADOW_READERS:
            sh, _sig = _shadow(src); kw2 = dict(kw); kw2[key] = sh
            return _unshadow(fn(**kw2), sh, src, len(q), read=True)
        r = fn(**kw)
        q = _pending_get(src)                                     # a writer may have applied them on the way
        if q and isinstance(r, dict):
            r["pending_ops"] = len(q)
            r["pending_note"] = (f"{len(q)} queued edit(s) for this project aren't in this result (it read the file); "
                                 "flh_sync() applies them")
        return r
    run.__wrapped__ = getattr(fn, "__wrapped__", fn)
    run.__lazy__ = True
    return run


def _sync_first_tool(name, fn):
    def run(**kw):
        _sync_before(name)
        return fn(**kw)
    run.__wrapped__ = getattr(fn, "__wrapped__", fn)
    run.__lazy__ = True
    return run


def _sync_pending(project=None, file_only=False):
    """Apply queued edits: per project ONE save of FL, every queued op on top of what FL saved (so edits made in FL
    meanwhile are kept), ONE reload, verified - flp_edit's path. {project: summary}, or None if nothing was queued.
    A failing op changes nothing and its queue is kept.
    PC-VERIFY: on a big project, three queued edits + a hand edit in FL -> one reload, all four in FL, verified.
    The queue lock is NOT held while FL saves and reloads (PC 2026-10-22: an edit sent meanwhile waited 8.7 s for
    it): the ops being applied are taken off the front of the queue only when they're in; edits queued meanwhile stay
    queued (they were checked on the shadow, which isn't rebuilt mid-flush) for the next reload. Syncs run one at a
    time, the FL lock first (the same order as every FL step: no deadlock)."""
    hold = False
    if not file_only:
        try:
            hold = fl_running()
        except Exception:
            hold = False
        if hold and not _fl_acquire():
            raise RuntimeError(f"FL is busy ({_fl_busy_with()}), so the queued edits weren't applied yet")
    try:
        with _SYNC_RUN_LOCK:
            keys = [_ud_key(project)] if project else list(_pending_all())
            out = {}
            for k in keys:
                ent = _pending_all().get(k)
                if not ent or not ent.get("ops"):
                    continue
                p = ent["project"]
                if not os.path.isfile(p):
                    out[p] = {"error": "the project file is gone; its queued edits are kept (flh_sync discard=true "
                                       "drops them)"}
                    continue
                ops = _pending_take(p)
                if not ops:
                    continue
                ok = False
                try:
                    plan = _plan_ops(p, ops)
                    if file_only:                                 # FL just saved and left this project: the file only
                        res = {"output": p, "results": _run_plan(p, plan)}
                    else:
                        res = _with_open_project(p, p, lambda p=p, plan=plan: {"output": p,
                                                                               "results": _run_plan(p, plan)},
                                                 _pending_ok=False)
                    ok = True
                finally:
                    _pending_done(p, ops, ok)
                out[p] = {"ops": len(ops), **{x: res[x] for x in ("reloaded_in_fl", "steps_s", "verify_job",
                                                                  "previous_edit_held", "WARNING", "reload_check",
                                                                  "fl_has_open", "fl_shows_old_version", "live_kept")
                                              if isinstance(res, dict) and x in res}}
            return out or None
    finally:
        if hold:
            _FL_LOCK.release()


_SYNC_RUN_LOCK = threading.RLock()                                # one queue flush at a time (taken after the FL lock)
_INFLIGHT = {}                                                    # ud key -> the queued ops being put into FL now


def _pending_take(project):
    """The queue of `project`, marked as being applied: the shadow (file + queue) is made sure first and isn't rebuilt
    from the half-synced file meanwhile, so an edit queued during the flush sees exactly the queued state."""
    with _PENDING_LOCK:
        ops = _pending_get(project)
        if ops:
            try:
                _shadow(project)
            except Exception:
                pass
            _INFLIGHT[_ud_key(project)] = list(ops)
        return ops


def _pending_done(project, ops, ok):
    """End of a flush: on success the applied ops leave the front of the queue (edits queued meanwhile stay); on
    failure the queue stays as it was (all or nothing)."""
    with _PENDING_LOCK:
        _INFLIGHT.pop(_ud_key(project), None)
        if not ok:
            return
        cur = _pending_get(project)
        n = len(ops)
        rest = cur[n:] if cur[:n] == list(ops) else [o for o in cur if o not in ops]
        _pending_set(project, rest)


def _sync_before(reason, project=None, file_only=False):
    """Before anything that needs FL (or the file) to hold the queued edits - listening, rendering, playing,
    switching or closing projects: apply them. Cheap no-op when nothing is queued."""
    if getattr(_SYNC_LOCAL, "busy", False):
        return None
    try:
        if not _pending_all():
            return None
    except Exception:
        return None
    _SYNC_LOCAL.busy = True
    try:
        return _sync_pending(project, file_only)
    except Exception as e:
        raise RuntimeError(f"queued edits couldn't be applied before {reason}: {type(e).__name__}: {e}. They're still "
                           "queued: fix the cause and run flh_sync(), or drop them with flh_sync(discard=true)") from e
    finally:
        _SYNC_LOCAL.busy = False


def flh_sync(project=None, discard=False, mode=None):
    """Apply edits queued in lazy mode now (one save + one reload per project), or drop them (discard=true), and/or
    set this PC's reload mode (auto | lazy | immediate)."""
    r = {}
    if mode is not None:
        if mode not in RELOAD_MODES:
            raise ValueError(f"mode: {' | '.join(RELOAD_MODES)}")
        _state({"reload_mode": mode}); r["mode_set"] = mode
    d = _pending_all()
    if project:
        d = {k: v for k, v in d.items() if k == _ud_key(project)}
    if discard:
        r["discarded"] = {v["project"]: [o.get("tool") for o in v.get("ops", [])] for v in d.values()}
        for v in d.values():
            _pending_set(v["project"], [])
        return r
    if d:
        T = time.time()
        r["synced"] = _sync_pending(project) or {}
        r["steps_s"] = {"sync": round(time.time() - T, 1)}
    else:
        r["synced"] = {}; r["note"] = "nothing was queued"
    mode_now, src = _reload_mode_setting()
    r["reload_mode"] = {"mode": mode_now, "from": src, "lazy_when_load_over_s": LAZY_THRESHOLD_S}
    return r


def flp_edit_auto(project, ops, output=None):
    """flp_edit for extensions that want lazy reloads: on a big project open in FL the ops are queued (checked on the
    shadow copy, result has queued=true) instead of one save+reload per call; otherwise exactly flp_edit."""
    return TOOLS["flp_edit"][0](project=project, ops=ops, output=output)


def _pending_summary():
    return {os.path.basename(v["project"]): len(v.get("ops") or []) for v in _pending_all().values() if v.get("ops")}


def _install_live_first(ns):
    """Wrap the tools (core and extensions) once they're all registered: lazy writers, shadow readers, sync-first."""
    T = ns["TOOLS"]
    for name in list(T):
        fn = T[name][0]
        if getattr(fn, "__lazy__", False):
            continue
        if name in LAZY_TOOLS:
            w = _lazy_tool(name, fn)
        elif name in SYNC_FIRST_TOOLS:
            w = _sync_first_tool(name, fn)
        elif (name.startswith("flp_") or name in READ_ANNOTATE) and name not in NOT_READERS:
            w = _pending_read_tool(name, fn)
        else:
            continue
        if w is not fn:
            T[name] = (w,) + tuple(T[name][1:])


# ---- (3) render from the open FL ------------------------------------------------------------------------------
class InFlUnavailable(RuntimeError):
    """FL's own export couldn't start (nothing was rendered, FL was left as it was): the caller may fall back to the
    command-line render."""


# FL's export shortcuts. PC-VERIFY: Ctrl+R = File > Export > Wave file, Shift+Ctrl+R = MP3 file (FL 2024-2026)
RENDER_KEYS = {"wav": (0x52, (0x11,)), "mp3": (0x52, (0x11, 0x10))}
IN_FL_FORMATS = set(RENDER_KEYS) | {"flac"}                        # FLAC: FL's WAV, encoded here
VK_RETURN, VK_ESCAPE = 0x0D, 0x1B
IN_FL_WAITS = {"save_dialog": 10.0, "save_dialog_late": 20.0, "export_dialog": 15.0}       # seconds FL gets to show each export window


def _send_keys(vk, mods=()):
    """Press vk with modifier keys held (real key events: FL's shortcuts only answer those)."""
    import ctypes
    u = ctypes.windll.user32
    for m_ in mods:
        u.keybd_event(m_, 0, 0, 0)
    u.keybd_event(vk, 0, 0, 0); u.keybd_event(vk, 0, 2, 0)
    for m_ in reversed(mods):
        u.keybd_event(m_, 0, 2, 0)


# Windows' own overlays that can hold the foreground and refuse to give it up (emoji / touch keyboard panel, clipboard
# history, Start, Search, notification flyouts): Esc closes them without side effects.
FG_OVERLAYS = ("textinputhost.exe", "shellexperiencehost.exe", "startmenuexperiencehost.exe", "searchhost.exe",
               "searchapp.exe")


def _window_exe(hwnd):
    """Executable file name (lower case) of the process owning a window, or ''."""
    import ctypes
    from ctypes import wintypes
    try:
        pid = wintypes.DWORD()
        ctypes.windll.user32.GetWindowThreadProcessId(wintypes.HWND(hwnd), ctypes.byref(pid))
        k32 = ctypes.windll.kernel32
        h = k32.OpenProcess(0x1000, False, pid.value)              # PROCESS_QUERY_LIMITED_INFORMATION
        if not h:
            return ""
        try:
            buf = ctypes.create_unicode_buffer(520); n = wintypes.DWORD(520)
            if k32.QueryFullProcessImageNameW(h, 0, buf, ctypes.byref(n)):
                return os.path.basename(buf.value).lower()
        finally:
            k32.CloseHandle(h)
    except Exception:
        pass
    return ""


def _focus_main_keys(hwnd):
    """Give FL's main window the keyboard focus (SetFocus through FL's input queue), so a shortcut reaches FL itself
    and not a plugin window that had the focus (Edison answers Ctrl+O / Ctrl+S with its own sample dialogs).
    PC-VERIFY: with Edison's window focused, this makes Ctrl+O open FL's project Open dialog."""
    if os.name != "nt":
        return False
    try:
        import ctypes
        u = ctypes.windll.user32; k32 = ctypes.windll.kernel32
        t_fl = u.GetWindowThreadProcessId(hwnd, None); t_me = k32.GetCurrentThreadId()
        if not t_fl or t_fl == t_me:
            return False
        if not u.AttachThreadInput(t_me, t_fl, True):
            return False
        try:
            u.SetFocus(hwnd)
        finally:
            u.AttachThreadInput(t_me, t_fl, False)
        return True
    except Exception:
        return False


def _audio_open_dialog(d):
    """True for a file dialog that loads AUDIO (a plugin's 'Load sample', e.g. Edison's Ctrl+O), not FL's project
    Open: its file types name audio and no .flp/project."""
    if not d or not (d.get("file_dialog") or d.get("kind") == "open_dialog"):
        return False
    try:
        info = _file_dialog_info(d["hwnd"]) or {}
    except Exception:
        info = {}
    txt = " ".join([str(x) for x in info.get("combos") or []] + [str(d.get("title") or "")] +
                   [str(x) for x in d.get("text") or []]).lower()
    if "flp" in txt or "project" in txt:
        return False
    return bool(re.search(r"\*\.(wav|flac|mp3|ogg|aiff?)|\bwave?\b|\bsample|\bedison\b|\baudio\b", txt))


def _fg_api():
    """(user32 with HWND return types, kernel32) for the foreground code - one place, so tests can stand in a fake."""
    import ctypes
    return _user32(), ctypes.windll.kernel32


FG_STEP_WAIT_S = 0.35             # after each way of taking the foreground: this long for Windows to hand it over
FG_OVERLAY_MINIMIZE = True        # an overlay (TextInputHost...) still in front after Esc: minimised (ignored) once
FG_CLICK_TITLE = True             # last resort: one click on FL's own title bar (a point Windows calls its caption)


def _fl_foreground():
    """Bring FL's main window to the front, so its shortcuts (Ctrl+O, Ctrl+R, ...) reach FL. True if it is.
    Windows only lets the app that had the last input take the foreground: a background server has to earn it. In
    order, each checked at once (FG_STEP_WAIT_S): a Windows overlay in front (TextInputHost - the emoji / touch-keyboard
    panel - Start, Search) gets Esc, then is minimised; AllowSetForegroundWindow + unlock; an ALT key-tap, then
    SetForegroundWindow; the input queues of the foreground window's thread AND FL's thread attached to ours
    (AttachThreadInput), then BringWindowToTop / SetForegroundWindow / SetActiveWindow / SetFocus; SwitchToThisWindow;
    minimise + restore; finally one real click on FL's own title bar (only at a point FL itself calls its caption -
    never a button, menu or another window - and the mouse goes back where it was). PC 2026-10-20 / 2026-10-23:
    'Windows kept textinputhost.exe in front and refused to hand FL the focus' twice; one mouse click on FL fixed it.
    _FG_WHY: who kept the foreground (owner) and which way worked (how).
    PC-VERIFY: with the emoji panel (Win+.) open and the PC idle for 10 min, fl_open of another project drives FL's
    Open dialog; checklists/core.md 'focus'"""
    try:
        u, k32 = _fg_api()
    except Exception:                                             # noqa: BLE001 - not Windows
        return False
    main = _fl_main_window()
    if not main:
        return False
    hwnd = main[0]
    _FG_WHY.update(owner=None, how=None)
    front = lambda: _hwnd_eq(u.GetForegroundWindow(), hwnd)
    got = lambda: _wait_for(lambda: front(), FG_STEP_WAIT_S, 0.03)

    def done(how):
        _FG_WHY["how"] = how
        return True
    if front() and not u.IsIconic(hwnd):
        return done("already")                                    # already in front: nothing to wait for
    alt_tap = lambda: (u.keybd_event(0x12, 0, 0, 0), u.keybd_event(0x12, 0, 2, 0))   # ALT down/up: input of ours
    try:                                                          # a Windows overlay in front: Esc, else minimise it
        fg = u.GetForegroundWindow()
        if fg and not _hwnd_eq(fg, hwnd) and _window_exe(fg) in FG_OVERLAYS:
            _press_vk(fg, VK_ESCAPE); time.sleep(0.2)
            fg2 = u.GetForegroundWindow()
            if FG_OVERLAY_MINIMIZE and fg2 and _hwnd_eq(fg2, fg) and u.IsWindowVisible(fg2):
                u.ShowWindow(fg2, 6)                              # SW_MINIMIZE: out of the way (ignored from here)
    except Exception:                                             # noqa: BLE001
        pass
    try:                                                          # let any process (FL too) take the foreground
        u.AllowSetForegroundWindow(-1)                            # ASFW_ANY
        u.LockSetForegroundWindow(2)                              # LSFW_UNLOCK
    except Exception:                                             # noqa: BLE001
        pass
    for attempt in range(2):                                      # PC 2026-10-20: one try lost to a plugin window
        try:
            alt_tap()
            if u.IsIconic(hwnd):
                u.ShowWindow(hwnd, 9)                             # SW_RESTORE
            u.SetForegroundWindow(hwnd)
        except Exception:                                         # noqa: BLE001
            pass
        if got():
            return done("alt_tap")
        try:                                                      # borrow the input queues (the foreground's and
            me = k32.GetCurrentThreadId()                         # FL's): Windows then treats us as the active app
            fg = u.GetForegroundWindow()
            t_fg = u.GetWindowThreadProcessId(fg, None) if fg else 0
            t_fl = u.GetWindowThreadProcessId(hwnd, None)
            attached = [t for t in dict.fromkeys((t_fg, t_fl)) if t and t != me and u.AttachThreadInput(me, t, True)]
            try:
                alt_tap()
                u.BringWindowToTop(hwnd); u.SetForegroundWindow(hwnd)
                u.SetActiveWindow(hwnd); u.SetFocus(hwnd)
            finally:
                for t in attached:
                    u.AttachThreadInput(me, t, False)
            if attached and got():
                return done("attach_input")
        except Exception:                                         # noqa: BLE001
            pass
    try:                                                          # last resorts, PC-VERIFY: with TextInputHost holding
        u.SwitchToThisWindow(hwnd, True)                          # the foreground (2026-10-22, nobody at the PC) the
        if _wait_for(lambda: front(), FG_STEP_WAIT_S + 0.1, 0.05):   # tries above all failed
            return done("switch_to_this_window")
        u.ShowWindow(hwnd, 6); time.sleep(0.2); u.ShowWindow(hwnd, 9)   # minimise + restore: Windows hands a restored
        if _wait_for(lambda: front(), FG_STEP_WAIT_S + 0.3, 0.05):   # window the foreground
            return done("minimize_restore")
    except Exception:                                             # noqa: BLE001
        pass
    if FG_CLICK_TITLE and not _desktop_locked() and _fg_click_title(u, hwnd) and got():
        return done("title_click")
    try:
        _FG_WHY["owner"] = _window_exe(u.GetForegroundWindow())
    except Exception:                                             # noqa: BLE001
        _FG_WHY["owner"] = None
    return False


def _fg_click_title(u, hwnd):
    """One left click on FL's own title bar - what a person does to give FL the focus. Only at a point that is FL's
    main window (WindowFromPoint, root ancestor) AND that FL itself answers as its caption (WM_NCHITTEST = HTCAPTION):
    never a menu, button or knob, never another window lying over FL. The mouse goes back where it was. -> True if
    clicked. PC-VERIFY: FL 2026's title bar answers HTCAPTION at its top edge (else nothing is clicked)."""
    import ctypes
    from ctypes import wintypes
    try:
        r = wintypes.RECT()
        if not u.GetWindowRect(hwnd, ctypes.byref(r)):
            return False
        w = r.right - r.left
        if w < 200 or r.bottom - r.top < 60:
            return False
        spot = None
        for dy in (4, 10, 16):                                    # the top edge, a few points across the middle
            for fx in (0.5, 0.62, 0.38, 0.75, 0.25):
                x, y = int(r.left + w * fx), int(r.top + dy)
                lp = ((y & 0xFFFF) << 16) | (x & 0xFFFF)
                at = u.WindowFromPoint(wintypes.POINT(x, y))
                if not at or not _hwnd_eq(u.GetAncestor(at, 2), hwnd):   # GA_ROOT: another window lies there
                    continue
                if u.SendMessageW(hwnd, 0x0084, 0, lp) == 2:      # WM_NCHITTEST -> HTCAPTION
                    spot = (x, y); break
            if spot:
                break
        if not spot:
            return False
        old = wintypes.POINT()
        u.GetCursorPos(ctypes.byref(old))
        u.SetCursorPos(*spot)
        u.mouse_event(0x0002, 0, 0, 0, 0); u.mouse_event(0x0004, 0, 0, 0, 0)   # LEFTDOWN, LEFTUP
        time.sleep(0.05)
        u.SetCursorPos(old.x, old.y)
        return True
    except Exception:                                             # noqa: BLE001
        return False


_FG_WHY = {"owner": None, "how": None}


def _fg_note():
    """Why FL couldn't be brought to the front, for error messages."""
    o = _FG_WHY.get("owner")
    if _desktop_locked():
        return LOCKED_NOTE
    if o:
        return (f"Windows kept '{o}' in front and refused to hand FL the focus (this happens when nobody has used the "
                "PC for a while); one click on FL's window fixes it")
    return "FL may be busy or minimised behind another app"


def _wait_for(pred, timeout, step=0.2):
    """pred()'s first truthy value within timeout seconds, else None."""
    t0 = time.time()
    while True:
        v = pred()
        if v:
            return v
        if time.time() - t0 >= timeout:
            return None
        time.sleep(step)


def _new_dialogs(before):
    return [d for d in fl_dialogs() if d["hwnd"] not in before]


def _window_alive(hwnd):
    import ctypes
    u = ctypes.windll.user32
    return bool(u.IsWindow(hwnd)) and bool(u.IsWindowVisible(hwnd))


def _file_dialog_info(hwnd):
    """The file name box and file type text of a Windows file dialog."""
    import ctypes
    from ctypes import wintypes
    u = ctypes.windll.user32; out = {"edits": [], "combos": []}
    proc = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)

    def cb(ch, _):
        c = ctypes.create_unicode_buffer(64); u.GetClassNameW(ch, c, 64)
        n = u.GetWindowTextLengthW(ch); b = ctypes.create_unicode_buffer(n + 1); u.GetWindowTextW(ch, b, n + 1)
        if c.value == "Edit" and u.IsWindowVisible(ch):
            t = ctypes.create_unicode_buffer(1024); u.SendMessageW(ch, 0x000D, 1024, t)   # WM_GETTEXT
            out["edits"].append((ch, t.value or b.value))
        elif c.value == "ComboBox" and u.IsWindowVisible(ch):
            out["combos"].append(b.value)
        return True
    u.EnumChildWindows(wintypes.HWND(hwnd), proc(cb), 0)
    return out


def _file_name_edit(hwnd):
    """The 'File name' box of a Windows file dialog: the visible Edit that sits inside control 0x47C (cmb13, the
    name combo, nested under other windows in Vista+ dialogs) or is control 0x480 (edt1, older dialogs); else the
    first visible Edit, as before (PC 2026-10-20: FL's export Save As has other Edit controls, and the name went into
    the wrong one - FL rendered to its default name)."""
    import ctypes
    from ctypes import wintypes
    u = ctypes.windll.user32
    u.GetParent.restype = wintypes.HWND; u.GetParent.argtypes = [wintypes.HWND]
    edits = []
    proc = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)

    def cb(ch, _):
        c = ctypes.create_unicode_buffer(32); u.GetClassNameW(ch, c, 32)
        if c.value == "Edit" and u.IsWindowVisible(ch):
            edits.append(ch)
        return True
    u.EnumChildWindows(wintypes.HWND(hwnd), proc(cb), 0)
    top = int(hwnd or 0) & 0xFFFFFFFF
    for e in edits:
        w = e
        for _ in range(8):                                        # the Edit, then its parents up to the dialog
            if not w or (int(w) & 0xFFFFFFFF) == top:
                break
            if u.GetDlgCtrlID(w) in (0x47C, 0x480):
                return e
            w = u.GetParent(w)
    return edits[0] if edits else None


_FILE_DIALOG_LAST = {}                                            # what the last submit saw (for error reports)


def _file_dialog_submit(hwnd, path):
    """Type `path` into the file dialog's name box and press its OK (Save). True once the dialog closed."""
    import ctypes
    u = ctypes.windll.user32
    box = _file_name_edit(hwnd)
    if not box:
        return False
    # typed like a person (WM_CHAR per character, then Enter in the box): a Vista-style Save dialog keeps its own
    # copy of the name and ignored a WM_SETTEXT + IDOK (PC 2026-10-20: FL exported to its default name)
    def text():                                                   # WM_GETTEXT: GetWindowText can't read an
        b = ctypes.create_unicode_buffer(1024)                        # Edit's text in another process
        u.SendMessageW(box, 0x000D, 1024, b)
        return b.value.strip()
    u.SendMessageW(box, 0x000C, 0, ctypes.c_wchar_p(""))              # WM_SETTEXT: empty the box
    for ch in path:
        u.SendMessageW(box, 0x0102, ord(ch), 0)                       # WM_CHAR
    if os.path.normcase(text()) != os.path.normcase(path):            # autocomplete may append a suggestion:
        u.SendMessageW(box, 0x000C, 0, ctypes.c_wchar_p(path))        # set the exact text
    _FILE_DIALOG_LAST.update(box_text=text(), wanted=path)
    if os.path.normcase(text()) != os.path.normcase(path):            # the name didn't land: never press Save
        return False
    u.PostMessageW(box, 0x0100, 0x0D, 0); u.PostMessageW(box, 0x0101, 0x0D, 0)   # Enter in the name box
    if _wait_for(lambda: not _window_alive(hwnd), 3.0):
        return True
    u.SendMessageW(hwnd, 0x0111, 1, 0)                                # WM_COMMAND IDOK as before
    return bool(_wait_for(lambda: not _window_alive(hwnd), 5.0))


def _file_dialog_cancel(hwnd):
    import ctypes
    ctypes.windll.user32.SendMessageW(hwnd, 0x0111, 2, 0)            # WM_COMMAND IDCANCEL
    return bool(_wait_for(lambda: not _window_alive(hwnd), 3.0))


def _dismiss(d):
    """Close a popup we opened (never a save question)."""
    if d.get("kind") in ("save_changes", "save_as") and not d.get("file_dialog"):
        return False
    if d.get("file_dialog"):
        return _file_dialog_cancel(d["hwnd"])
    return bool(_press_vk(d["hwnd"], VK_ESCAPE))


def _export_start(hwnd, target):
    """Start FL's export: Enter in its export window (Start is its default button) - posted first, then as a real
    key press with the window in front. True once the file appears or the window closes.
    PC-VERIFY: Enter starts the export (else: which key / button does)."""
    import ctypes
    u = ctypes.windll.user32
    began = lambda: os.path.exists(target) or not _window_alive(hwnd)
    u.PostMessageW(hwnd, 0x0100, VK_RETURN, 0); u.PostMessageW(hwnd, 0x0101, VK_RETURN, 0)
    if _wait_for(began, 3.0):
        return True
    u.keybd_event(0x12, 0, 0, 0); u.keybd_event(0x12, 0, 2, 0); u.SetForegroundWindow(hwnd)
    time.sleep(0.15); _send_keys(VK_RETURN)
    return bool(_wait_for(began, 5.0))


def _render_method(project, formats="wav", method="auto", start_bar=None):
    """'in_fl' or 'cli' for a render. auto: FL's own export when FL is running AND an in-FL export has worked on this
    PC before (a first one is asked for explicitly: method='in_fl'), else the command line."""
    if method not in ("auto", "in_fl", "cli"):
        raise ValueError("method: auto | in_fl | cli")
    if method != "auto":
        return method
    fmts = [f.strip().lower() for f in str(formats).split(",") if f.strip()]
    if start_bar or not IS_WINDOWS or len(fmts) != 1 or fmts[0] not in IN_FL_FORMATS or not fl_running():
        return "cli"
    try:
        ok = (_state().get("in_fl_render") or {}).get("ok")
    except Exception:
        ok = False
    return "in_fl" if ok else "cli"


IN_FL_FAIL_STREAK = 3                                              # in-FL export failures in a row before auto
                                                                   # renders go back to the command line


def _note_in_fl(ok, detail=""):
    """Remember whether FL's own export worked here (auto uses it only after it has). A failure switches auto back to
    the command line until an explicit method='in_fl' render works again - only after IN_FL_FAIL_STREAK failures in a
    row once it has worked."""
    try:
        st = _state().get("in_fl_render") or {}
        if ok:
            st.update(ok=True, streak=0)
        else:                                                     # one slow / unfocused dialog isn't 'FL's export
            st["failures"] = int(st.get("failures", 0)) + 1       # doesn't work here': auto would close FL for the
            st["streak"] = int(st.get("streak", 0)) + 1           # command line on every later render (PC
            if st["streak"] >= IN_FL_FAIL_STREAK or not st.get("ok"):  # 2026-10-22, slow bench: FL closed)
                st["ok"] = False
        st.update(t=int(time.time()), last=("ok" if ok else f"failed: {detail}")[:200])
        _state({"in_fl_render": st})
    except Exception:
        pass


def _wait_render_done(path, exp_hwnd, timeout_s, t0):
    """FL wrote the file: it exists, its size held still for 2 s and the export window closed (or the size held for
    10 s with FL answering). (ok, why)."""
    last, since = None, time.time()
    base = float(timeout_s); timeout_s = _scaled(base); extra = _speed_extra(base, timeout_s); ext = False
    while True:
        if time.time() - t0 >= timeout_s:                         # still writing (grew in the last 10 s) or FL busy
            if extra > 0 and last and (time.time() - since < 10.0 or _fl_still_working()):
                timeout_s += extra; extra = 0.0; ext = True       # in the export: once more (slow PC), no failure
                _slow_note(f"FL is still working (slow PC): its export ran past {base:g} s; waited longer")
            else:
                break
        time.sleep(0.5)
        size = _out_bytes(path)
        if size != last:
            last, since = size, time.time()
            _job_progress(step="render", method="in_fl", bytes=size or 0)
            continue
        if not size or size <= 44:
            continue
        still = time.time() - since
        if still >= 2.0 and not _window_alive(exp_hwnd):
            return True, "file complete, export window closed"
        if still >= 10.0:
            try:
                BRIDGE.call("ping", timeout=2.0)
                return True, "file unchanged for 10 s and FL answers (export window still open)"
            except Exception:
                pass
    return False, f"no complete file after {int(time.time() - t0)} s" + _slow_why(base, time.time() - t0, ext)


def _out_bytes(path):
    """Bytes FL has written for an export to `path`: the file itself, or - when FL's export window has 'Split mixer
    tracks' ticked and writes one file per mixer track instead - every audio file in its folder (PC 2026-10: with
    split on, the named file may never appear)."""
    try:
        return os.path.getsize(path)
    except OSError:
        pass
    try:
        folder = os.path.dirname(path)
        got = [os.path.getsize(os.path.join(folder, f)) for f in os.listdir(folder)
               if f.lower().endswith((".wav", ".mp3", ".flac", ".ogg"))]
        return sum(got) if got else None
    except OSError:
        return None


def _also_formats_aside(target):
    """Files FL wrote next to `target` under the same name in another audio format - its export window can tick
    several formats at once and keeps the user's last choice (WAV + MP3 -> 'song.wav' AND 'song.mp3') - moved into a
    folder beside it, so split detection doesn't take them for mixer-track files. -> [paths].
    PC-VERIFY: with WAV and MP3 both ticked in FL's export window, Ctrl+Shift+R writes '<name>.mp3' and '<name>.wav'
    (fl_preview(format='mp3') then measures from the WAV: measured_from 'wav')."""
    folder = os.path.dirname(target); base = os.path.splitext(os.path.basename(target))[0].lower()
    out = []
    try:
        names = sorted(os.listdir(folder))
    except OSError:
        return out
    for f in names:
        b, ext = os.path.splitext(f)
        p = os.path.join(folder, f)
        if b.lower() == base and ext.lower() in (".wav", ".mp3", ".flac", ".ogg") and \
                os.path.normcase(p) != os.path.normcase(target):
            aside = os.path.join(os.path.dirname(folder), "also"); os.makedirs(aside, exist_ok=True)
            shutil.move(p, os.path.join(aside, f)); out.append(os.path.join(aside, f))
    return out


def _render_in_fl(project, out_dir, formats="wav", timeout_s=900, out_stem=None, probe=None, split=None):
    """FL's own export in the running FL. FLAC: FL exports a WAV (its export window has no FLAC shortcut) and
    fl-headless encodes it to FLAC losslessly (16/24-bit as FL wrote it; a 32-bit WAV becomes 24-bit), then the WAV
    goes. PC 2026-10-21: in-FL stems and FLAC renders failed with 'one of mp3, wav at a time'."""
    fmt = str(formats).split(",")[0].strip().lower()
    kw = {"split": split} if split is not None else {}
    if probe or "," in str(formats) or fmt != "flac":
        return _render_in_fl_raw(project, out_dir, formats, timeout_s, out_stem, probe, **kw)
    r = _render_in_fl_raw(project, out_dir, "wav", timeout_s, out_stem, probe, **kw)
    T = time.time(); out = []
    for w in r.get("rendered") or []:
        if not str(w).lower().endswith(".wav"):
            out.append(w); continue
        out.append(_wav_to_flac(w))
    r["rendered"] = out
    r.setdefault("steps_s", {})["flac_encode"] = round(time.time() - T, 2)
    r["seconds"] = round(float(r.get("seconds") or 0) + time.time() - T, 1)
    return r


def _wav_to_flac(wav):
    """A WAV FL just exported -> FLAC next to it (lossless for 16/24-bit; 32-bit is stored as 24-bit); WAV removed."""
    import numpy as np
    import flac_lite
    x, fs, bits = _wav_load(wav)
    bps = 16 if bits == 16 else 24
    full = float(1 << (bps - 1))
    v = np.clip(np.round(np.asarray(x, dtype=np.float64) * full), -full, full - 1).astype(np.int32)
    if v.ndim == 1:
        v = v[:, None]
    dst = os.path.splitext(wav)[0] + ".flac"
    flac_lite.encode(dst, v, int(fs), bps)
    try:
        os.remove(wav)
    except OSError:
        pass
    return dst


# ---- MP3 frames: the length of FL's MP3 export and frame-exact cuts of it, with no decoder and no encoder ---------
_MP3_KBPS = {1: (0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320),       # MPEG-1 Layer III
             2: (0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160)}           # MPEG-2 / 2.5 Layer III
_MP3_RATES = {3: (44100, 48000, 32000), 2: (22050, 24000, 16000), 0: (11025, 12000, 8000)}


def _mp3_header(h):
    """A Layer III frame header (4 bytes) -> (frame bytes, rate, samples per frame, version, mono) or None."""
    if len(h) < 4 or h[0] != 0xFF or (h[1] & 0xE0) != 0xE0:
        return None
    ver, layer, bri, sri = (h[1] >> 3) & 3, (h[1] >> 1) & 3, h[2] >> 4, (h[2] >> 2) & 3
    if ver == 1 or layer != 1 or not 0 < bri < 15 or sri == 3:
        return None
    rate = _MP3_RATES[ver][sri]; kbps = _MP3_KBPS[1 if ver == 3 else 2][bri]
    n = (144 if ver == 3 else 72) * kbps * 1000 // rate + ((h[2] >> 1) & 1)
    return n, rate, (1152 if ver == 3 else 576), ver, (h[3] >> 6) == 3


def _mp3_frames(data):
    """An MP3's frames -> {frames [(offset, bytes)] of audio, rate, spf} or None when it isn't MPEG Layer III. An
    ID3v2 tag in front / ID3v1 at the end and a Xing / Info / VBRI header frame (no audio) are left out; junk between
    frames is skipped (resync on two headers in a row)."""
    i = 0
    if data[:3] == b"ID3" and len(data) >= 10:
        size = 0
        for b in data[6:10]:
            size = (size << 7) | (b & 0x7F)
        i = 10 + size + (10 if data[5] & 0x10 else 0)
    end = len(data) - (128 if len(data) >= 128 and data[-128:-125] == b"TAG" else 0)
    frames, rate, spf, ver0 = [], None, None, None
    while i + 4 <= end:
        h = _mp3_header(data[i:i + 4])
        ok = h is not None and h[0] > 4 and i + h[0] <= end and (ver0 is None or (h[3] == ver0 and h[1] == rate))
        if ok and not frames:                                     # first frame: the next header must follow it
            nxt = _mp3_header(data[i + h[0]:i + h[0] + 4])
            ok = i + h[0] == end or (nxt is not None and nxt[1] == h[1])
        if not ok:
            i += 1
            continue
        n, r, s, v, mono = h
        if not frames:
            rate, spf, ver0 = r, s, v
            side = (17 if mono else 32) if v == 3 else (9 if mono else 17)
            if data[i + 4 + side:i + 8 + side] in (b"Xing", b"Info") or data[i + 36:i + 40] == b"VBRI":
                i += n
                ver0 = v
                frames.append(None)                               # the header frame: no audio
                continue
        frames.append((i, n))
        i += n
    frames = [f for f in frames if f]
    return {"frames": frames, "rate": rate, "spf": spf} if frames else None


def _mp3_seconds(path):
    """Seconds of audio in an MP3 file (frames x samples per frame), or None."""
    try:
        with open(path, "rb") as f:
            info = _mp3_frames(f.read())
    except OSError:
        return None
    return len(info["frames"]) * info["spf"] / info["rate"] if info else None


MP3_CUT_PREROLL_FRAMES = 2        # frames kept before a cut's start: the decoder's bit reservoir refills there, so
                                  # the wanted start plays clean (~50 ms early)


def _mp3_cut(src, dst, start_s, end_s=None):
    """Frames of `src` covering [start_s, end_s) (whole frames, MP3_CUT_PREROLL_FRAMES earlier) -> dst, no re-encode:
    the sound is FL's encode bit for bit. -> {start_s (where dst begins in src), seconds, bytes}.
    PC-VERIFY: the cut file plays on a phone (iOS / Android) from the cut on; at most a click at the cut points."""
    with open(src, "rb") as f:
        data = f.read()
    info = _mp3_frames(data)
    if not info:
        raise ValueError(f"{os.path.basename(src)} isn't an MP3 fl-headless can cut (MPEG Layer III frames)")
    fr, rate, spf = info["frames"], info["rate"], info["spf"]
    k0 = max(0, int(float(start_s) * rate / spf) - MP3_CUT_PREROLL_FRAMES)
    k1 = len(fr) if end_s is None else min(len(fr), int(math.ceil(float(end_s) * rate / spf)))
    if k0 >= len(fr) or k1 <= k0:
        raise ValueError(f"the cut {start_s:.1f}-{end_s if end_s is not None else 'end'} s is outside the MP3 "
                         f"({len(fr) * spf / rate:.1f} s)")
    writable(dst)
    tmp = dst + ".part"
    with open(tmp, "wb") as f:
        for off, n in fr[k0:k1]:
            f.write(data[off:off + n])
    os.replace(tmp, dst)
    return {"start_s": round(k0 * spf / rate, 4), "seconds": round((k1 - k0) * spf / rate, 3),
            "bytes": os.path.getsize(dst)}


def _render_in_fl_raw(project, out_dir, formats="wav", timeout_s=900, out_stem=None, probe=None, split=None):
    """Render with FL's own export in the running FL: no close, no extra loads.
    File > Export (Ctrl+R) -> Windows Save dialog (path) -> FL's export settings (FL keeps the user's last settings)
    -> Enter (Start) -> wait until the file is complete. probe='save_dialog' | 'export_dialog': open the dialogs, read
    them and cancel (nothing is rendered). Raises InFlUnavailable when the export couldn't start.
    PC-VERIFY: every dialog step (titles, which key starts the export, when FL closes its export window)."""
    steps = {}; T0 = time.time()
    fmt = str(formats).split(",")[0].strip().lower()
    if "," in str(formats) or fmt not in RENDER_KEYS:
        raise InFlUnavailable(f"FL's own export here does one of {sorted(IN_FL_FORMATS)} at a time (got '{formats}')")
    if not IS_WINDOWS or not fl_running() or not _fl_main_window():
        raise InFlUnavailable("FL isn't running")
    blocking = [d for d in fl_dialogs() if d.get("blocks_fl")]
    if blocking:
        raise InFlUnavailable(f"FL shows a popup ({[d['title'] for d in blocking]}): answer it first (fl_dialog)")
    fl_state = None
    if probe:
        cur, _ = _open_project_guess()
        project = cur or project
    else:
        project = os.path.abspath(project)
        # FL's export renders what FL has LOADED: FL must hold exactly this file (a same-title twin is told apart by
        # a save; an older copy than the file - fl-headless wrote it behind FL's back - is reloaded first)
        # PC-VERIFY: after a file edit FL didn't load, fl_render(method='in_fl') reloads first and renders the edit
        ld = _fl_load_file(project, "render")
        steps.update(ld.get("steps_s") or {})
        if ld.get("how") in ("reloaded", "opened"):
            fl_state = ld["how"]
        T = time.time()
        if _sync_before("render", project):
            steps["sync"] = round(time.time() - T, 1)
        gone = _live_mutes_intact(project)                        # a solo render's mutes still on in FL
        if gone:
            raise InFlUnavailable(gone)
    try:
        BRIDGE.call("transport", action="stop", timeout=3.0)
    except Exception:
        pass
    work, fl_work = _render_workdir()
    stem = _safe_stem(project) if project else "render"
    os.makedirs(os.path.join(work, "out"))
    target_fl = os.path.join(fl_work, "out", stem + "." + fmt); target = os.path.join(work, "out", stem + "." + fmt)
    try:
        before = {d["hwnd"] for d in fl_dialogs()}
        T = time.time()
        if not _fl_foreground():
            raise InFlUnavailable("couldn't bring FL's window to the front for its export shortcut: " + _fg_note())
        vk, mods = RENDER_KEYS[fmt]; _send_keys(vk, mods)
        dlg = _wait_for(lambda: next((d for d in _new_dialogs(before) if d.get("file_dialog") or d["class"] == "#32770"),
                                     None), _scaled(IN_FL_WAITS["save_dialog"]))
        if not dlg and fl_running():                              # a busy / slow FL opens it late (PC 2026-10-22,
            dlg = _wait_for(lambda: next((d for d in _new_dialogs(before)   # 2 cores: >10 s); a late one would
                                          if d.get("file_dialog") or d["class"] == "#32770"), None),   # be left open
                            _scaled(IN_FL_WAITS["save_dialog_late"]))
        steps["save_dialog"] = round(time.time() - T, 1)
        if not dlg:
            other = _new_dialogs(before)
            for d in other:
                _dismiss(d)
            raise InFlUnavailable("FL's export Save dialog didn't open" + (f" (FL showed {[d['title'] for d in other]})"
                                                                         if other else ""))
        info = _file_dialog_info(dlg["hwnd"])
        seen = {"save_dialog": {"title": dlg["title"], "file_name": info["edits"][0][1] if info["edits"] else None,
                                "file_types": info["combos"][:3]}}
        if probe == "save_dialog":
            seen["cancelled"] = _file_dialog_cancel(dlg["hwnd"])
            return {"probe": "save_dialog", "seen": seen, "steps_s": steps, "rendered": []}
        T = time.time()
        if not _file_dialog_submit(dlg["hwnd"], target_fl):
            _file_dialog_cancel(dlg["hwnd"])
            raise InFlUnavailable(f"couldn't hand FL's Save dialog the file name (its box: "
                                  f"{str(_FILE_DIALOG_LAST.get('box_text'))[:80]!r})")
        exp = _wait_for(lambda: next((d for d in _new_dialogs(before) if d["hwnd"] != dlg["hwnd"]
                                      and not d.get("file_dialog")), None), _scaled(IN_FL_WAITS["export_dialog"]))
        steps["export_dialog"] = round(time.time() - T, 1)
        if not exp:
            raise InFlUnavailable("FL's export settings window didn't appear after the Save dialog")
        seen["export_dialog"] = {k: exp.get(k) for k in ("title", "class", "text", "buttons", "kind")}
        want_name = os.path.basename(target_fl).lower()
        if probe != "export_dialog" and want_name not in str(exp.get("title") or "").lower() and \
                os.path.splitext(want_name)[0] not in str(exp.get("title") or "").lower():
            _press_vk(exp["hwnd"], VK_ESCAPE)                     # FL would render to another file: never start it
            raise InFlUnavailable(f"FL's export window names another file ('{exp.get('title')}'), so the file name "
                                  "didn't reach FL's Save dialog; nothing was rendered")
        if probe == "export_dialog":
            try:
                img = fl_snapshot(hwnd=exp["hwnd"]).get("_image_png")
            except Exception as e:
                img = None; seen["snapshot_error"] = str(e)[:120]
            seen["cancelled"] = bool(_press_vk(exp["hwnd"], VK_ESCAPE)) or not _window_alive(exp["hwnd"])
            seen["file_written"] = os.path.exists(target)
            r = {"probe": "export_dialog", "seen": seen, "steps_s": steps, "rendered": []}
            if img:
                r["_image_png"] = img
            return r
        flip = _split_prepare(exp["hwnd"], split)               # 'Split mixer tracks' as asked (when it can)
        T = time.time()
        started = _export_start(exp["hwnd"], target)
        if not started:
            _press_vk(exp["hwnd"], VK_ESCAPE)
            raise InFlUnavailable("FL's export window didn't start rendering on Enter")
        steps["start"] = round(time.time() - T, 1); T = time.time()
        ok, why = _wait_render_done(target, exp["hwnd"], timeout_s, T)
        steps["render"] = round(time.time() - T, 1)
        if not ok:
            raise RuntimeError(f"FL's export didn't finish: {why}. FL may still be rendering - look at FL (nothing was "
                               f"forced); popups: {[d['title'] for d in fl_dialogs()]}")
        _note_export("in_fl", time.time() - T0)
        also = _also_formats_aside(target)                        # FL wrote other formats too: not split tracks
        sp = _split_collect(project, os.path.dirname(target), target, stem, flip)
        if sp and sp.get("master"):
            target = sp["master"]                                 # split on: FL's master file is the render
        if not os.path.exists(target):                            # the export window closed before the file showed up
            raise RuntimeError("FL's export window closed but no file was written (cancelled in FL?)" +
                               (f" - it wrote {len(sp['files'])} split track file(s) but no master" if sp else ""))
        left = [d for d in _new_dialogs(before) if d["hwnd"] not in (dlg["hwnd"], exp["hwnd"])]
        os.makedirs(out_dir, exist_ok=True)
        dst = _render_dest(out_dir, out_stem or os.path.splitext(os.path.basename(project))[0], "." + fmt)
        shutil.move(target, dst); _note_render(dst)
        res = {"rendered": [dst], "seconds": round(time.time() - T0, 1), "method": "in_fl", "steps_s": steps,
               "note": "rendered by FL's own export with its current export settings (what FL last used)"}
        if also:
            res["also_rendered"] = []
            for f in also:                                        # next to the render, listed (the caller decides)
                d2 = _render_dest(out_dir, os.path.splitext(os.path.basename(dst))[0], os.path.splitext(f)[1].lower())
                shutil.move(f, d2); _note_render(d2); res["also_rendered"].append(d2)
        if fl_state:
            res["fl_loaded"] = fl_state                           # 'reloaded' (FL held an older copy) / 'opened'
        if sp:
            res["split"] = sp                                     # {files {track: path}, dir}: the caller keeps them
        if left:
            res["popups_after"] = [{"title": d["title"], "text": d["text"][:3]} for d in left]
        _note_in_fl(True)
        return res
    except InFlUnavailable as e:
        _note_in_fl(False, str(e))
        raise
    finally:
        shutil.rmtree(work, ignore_errors=True)


def _ping_ok():
    try:
        BRIDGE.call("ping", timeout=1.5)
        return True
    except Exception:
        return False


def fl_render_probe(stage="save_dialog"):
    """Safe test of rendering from the open FL: opens FL's export dialogs on the open project, reads them and cancels.
    stage 'save_dialog' (Ctrl+R -> the Save dialog, cancelled) or 'export_dialog' (also FL's export settings window,
    with a picture, then Escape). Nothing is rendered."""
    if stage not in ("save_dialog", "export_dialog"):
        raise ValueError("stage: save_dialog | export_dialog")
    work = tempfile.mkdtemp(prefix="flh_probe_")
    try:
        r = _render_in_fl(None, work, "wav", 60, probe=stage)
    except InFlUnavailable as e:
        return {"probe": stage, "ok": False, "why": str(e), "popups": fl_dialogs()}
    finally:
        shutil.rmtree(work, ignore_errors=True)
    r["ok"] = True
    r["next"] = ("run fl_render_probe(stage='export_dialog')" if stage == "save_dialog" else
                 "look at the picture: is it FL's export settings? Then fl_render(project, method='in_fl')")
    return r


def _render_any(project, out_dir, formats="wav", timeout_s=900, out_stem=None, method="auto", close_fl=True):
    """One render by the best route (for fl_finalize and friends): {rendered, seconds, method, closed_fl (fl_close's
    result when FL had to close for the command line, else None)}. in_fl falls back to the command line (FL saved
    and closed first) when FL's export couldn't start and close_fl allows it."""
    note = None
    if _render_method(project, formats, method) == "in_fl":
        try:
            r = _render_in_fl(project, out_dir, formats, timeout_s, out_stem=out_stem)
            r["closed_fl"] = None
            if r.get("split"):                                    # FL split the export: every track's stem, kept
                sp = r.pop("split")
                r["split_stems"] = len(sp.get("files") or {}) if _rc_store_split(project, sp, "in_fl") else 0
            return r
        except InFlUnavailable as e:
            if not close_fl:
                raise
            note = f"FL's own export didn't start ({e}); used the command line"
    closed = None
    if fl_running():
        if not close_fl:
            raise RuntimeError("FL Studio is open: the command-line render needs it closed (close_fl=true)")
        closed = fl_close(save=True)
    r = _render(project, out_dir, formats, timeout_s, out_stem=out_stem)
    r.update(method="cli", closed_fl=closed)
    if note:
        r["in_fl_fallback"] = note
    return r


# ---- render cache, stems once, render counts (fl_render_cache.py does the file / numpy work) --------------------
# Every FL export is counted (_note_export); a render whose project fingerprint (sound + levels + options) was
# rendered before is reused; fader / pan / mute changes are mixed offline from a stems set (FL's 'Split mixer tracks'
# export, one pass); checks that need part of the song crop a cached render or render only that range.
_RENDER_STATS = {"exports": 0, "export_s": 0.0, "reused": 0, "offline": 0, "by_route": {}, "since": None}
_RENDER_LOCAL = threading.local()                                 # exports made by the current thread


def _own_temp(prefix):
    """A temp folder of fl-headless's own that its writers may use (renders land there before the cache takes them)."""
    work = tempfile.mkdtemp(prefix=prefix)
    _TEMP_ROOTS.append(os.path.normcase(os.path.abspath(work)))
    return work


def _own_temp_done(work):
    shutil.rmtree(work, ignore_errors=True)
    try:
        _TEMP_ROOTS.remove(os.path.normcase(os.path.abspath(work)))
    except ValueError:
        pass


def _note_export(route, secs):
    _RENDER_STATS["exports"] += 1; _RENDER_STATS["export_s"] = round(_RENDER_STATS["export_s"] + float(secs or 0), 1)
    _RENDER_STATS["by_route"][route] = _RENDER_STATS["by_route"].get(route, 0) + 1
    _RENDER_STATS["since"] = _RENDER_STATS["since"] or time.strftime("%H:%M:%S")
    _RENDER_LOCAL.n = getattr(_RENDER_LOCAL, "n", 0) + 1


def _note_reuse(offline=False):
    _RENDER_STATS["offline" if offline else "reused"] += 1


def _renders_here():
    return getattr(_RENDER_LOCAL, "n", 0)


def _render_stats_view():
    """This session's FL exports (count, seconds, by route) and how many renders the cache / offline mixing saved."""
    v = dict(_RENDER_STATS, by_route=dict(_RENDER_STATS["by_route"]))
    try:
        c = _rc().status(); v["cache_mb"] = c["used_mb"]; v["cache_cap_gb"] = c["cap_gb"]
    except Exception:                                             # noqa: BLE001
        pass
    return v


def _rc():
    import fl_render_cache as RC
    if RC.H is not globals():
        RC.bind(globals())
    return RC


def _rc_project_fp(project, live=False, tm=None):
    """(fingerprint, note) of what a render of `project` plays now, or (None, why). live: FL has it open and its
    export renders FL's state, so FL is saved first when it reports unsaved changes (the key is then the file FL
    saved; live fader / knob moves are in it). PC-VERIFY: FL clears general.getChangedFlag after a bridge save
    (else every render-type call saves once, ~1 s); a knob turned by hand in FL sets it."""
    RC = _rc()
    if not RC.enabled():
        return None, "render cache off"
    note = None; T = time.time(); tm = tm if tm is not None else {}
    lap = lambda k: tm.__setitem__(k, round(time.time() - T - sum(v for v in tm.values()     # noqa: E731
                                                                   if isinstance(v, float)), 2))
    if live and not _proven_open(project):                        # FL's changed flag is about what FL SHOWS: only
        where = _open_state(project)                              # FL showing this very file makes it this one's
        if where == "not_open":                                   # FL loads the file before its export: the file's
            live = False                                          # state is what renders (FL isn't saved: PC bug)
        elif where != "open":
            return None, ("FL's title can't be pinned to this file (" + _open_why(project) + "): rendered without "
                          "the cache, FL not saved")
    if live:
        try:
            if _stale_block(project):
                return None, "FL holds an older copy of the file"
        except Exception:                                         # noqa: BLE001
            pass
        lap("open_check")
        flag = _fl_changed_flag(); lap("changed_flag")
        if flag is None:                                          # can't tell whether FL holds unsaved changes
            return None, "FL's bridge doesn't report unsaved changes (older script / busy): rendered without the cache"
        if flag != 0:
            try:
                ok = _save_in_fl_and_wait(project, 8.0)
            except Exception:                                     # noqa: BLE001
                ok = False
            lap("save_fl"); tm["save_landed"] = bool(ok); tm["changed_flag_was"] = flag
            if not ok:
                return None, "FL has unsaved changes and its save didn't land: rendered without the cache"
            note = "saved FL first (it had unsaved changes) so the render cache sees them"
    try:
        d = _read_flp_bytes(project)
    except Exception as e:                                        # noqa: BLE001
        return None, f"project unreadable ({type(e).__name__})"
    fp = RC.fingerprint(d); lap("key")
    return fp, note


def _when(t):
    return time.strftime("%H:%M", time.localtime(float(t or 0)))


def _project_is_open(project):
    try:
        cur, _ = _open_project_guess()
        return bool(cur) and _ud_key(cur) == _ud_key(project)
    except Exception:                                             # noqa: BLE001
        return False


def _file_sha(path):
    """sha1 of a file's bytes (None when it can't be read): which exact file a render was made from."""
    import hashlib
    try:
        h = hashlib.sha1()
        with open(path, "rb") as f:
            for b in iter(lambda: f.read(1 << 20), b""):
                h.update(b)
        return h.hexdigest()
    except OSError:
        return None


def _render_cached(project, out_dir, formats="wav", timeout_s=900, out_stem=None, method="auto", close_fl=True,
                   store="exact", strict_file=False):
    """_render_any through the render cache: an unchanged song (same notes, sounds, effects, levels, tempo map) is
    not exported again - the last render is copied / handed back ('reused'). store: 'exact' keeps a copy in the cache
    (fl_finalize: its WAV is consumed), 'external' only references the file written into the user's folder.
    strict_file (fl_finalize): reuse only a render made from this exact project file (its sha1 is kept with every
    render): any byte changed since - even one the sound key leaves out - renders again, and the result says so
    (PC 2026-10-23: a FINAL came out sample-identical to the day before's after edits and live changes)."""
    project = os.path.abspath(project); RC = _rc(); T = time.time(); steps = {}
    fmt = ",".join(f.strip().lower() for f in str(formats).split(",") if f.strip())
    route = _render_method(project, fmt, method)
    _sync_before("render", project)
    steps["sync_before"] = round(time.time() - T, 2)              # queued edits / the last edit's check first
    fp, note = (None, None)
    if "," not in fmt:
        tm = {}
        fp, note = _rc_project_fp(project, live=route == "in_fl" or _project_is_open(project), tm=tm)
        steps["fingerprint_steps"] = {k: v for k, v in tm.items() if not isinstance(v, float) or v >= 0.05}
    key = RC.mix_key(fp, formats=fmt) if fp else None
    fsha = _file_sha(project) if key else None                    # the file this render is made from
    steps["cache_check"] = round(time.time() - T, 2)
    steps["fingerprint"] = round(steps["cache_check"] - steps["sync_before"], 2)
    if key:
        hit = RC.get(key, route=route, exact=True)
        if hit and strict_file:
            was = (hit.get("meta") or {}).get("file_sha")
            if not was or was != fsha:
                note = ((note + "; ") if note else "") + (
                    "a render with the same sound key was kept, but " + (
                        "it doesn't record which project file it was made from" if not was else
                        "the project file changed since (its hash differs)") + ": not reused for a FINAL, rendered again")
                hit = None
        short = _render_short(project, hit["files"][0]["path"]) if hit else None
        if short:                                                 # a render of another state was kept under this
            RC.drop(hit.get("key") or key)                        # song's key (FL held an older copy): never reuse it
            note = ((note + "; ") if note else "") + (f"the kept render ({short[0]:g} s) was shorter than the song "
                                                      f"({short[1]:g} s): dropped, rendered again")
            hit = None
        if hit:
            src = hit["files"][0]["path"]
            dst = _render_dest(out_dir, out_stem or os.path.splitext(os.path.basename(project))[0],
                               os.path.splitext(src)[1])
            if os.path.normcase(os.path.abspath(src)) != os.path.normcase(os.path.abspath(dst)):
                os.makedirs(out_dir, exist_ok=True); shutil.copy2(src, dst); _note_render(dst)
            _note_reuse()
            steps["copy"] = round(time.time() - T - steps["cache_check"], 2)
            r = {"rendered": [dst], "seconds": 0.0, "method": hit.get("route") or route, "closed_fl": None,
                 "reused": f"reused render (unchanged since {_when(hit['created'])}"
                           + ("; made from this exact project file" if strict_file else "") + ")",
                 "renders": 0, "steps_s": steps}
            if note:
                r["note"] = note
            return r
    n0 = _renders_here()
    r = _render_any(project, out_dir, fmt, timeout_s, out_stem=out_stem, method=method, close_fl=close_fl)
    if key and r.get("method") == "cli":                          # FL saved the file on closing: key what it rendered
        fp2, _ = _rc_project_fp(project)
        key = RC.mix_key(fp2, formats=fmt) if fp2 else None
        fsha = _file_sha(project)
    files = r.get("rendered") or []
    short = _render_short(project, files[0]) if len(files) == 1 else None
    if short:                                                     # FL rendered another state than the file's song
        r["render_short"] = {"rendered_s": short[0], "song_s": short[1]}
        key = None                                                # (an older copy it held): never cached as this song
    if key and len(files) == 1:
        RC.put(key, "render", [{"src": files[0], "mode": "external" if store == "external" else "copy",
                                "name": "mix" + os.path.splitext(files[0])[1]}],
               meta={"levels": fp["levels"] if fp else None, "file_sha": fsha}, route=r.get("method"),
               project=project)
    r["renders"] = _renders_here() - n0
    r.setdefault("steps_s", {}).update({k: steps[k] for k in ("cache_check", "sync_before", "fingerprint",
                                                              "fingerprint_steps") if k in steps})
    if note:
        r["cache_note"] = note
    return r


RENDER_SHORT_TOL_S = 1.5           # FL's export runs at least to the song's end (its last clip): a render this much
RENDER_SHORT_TOL_FRAC = 0.005      # (or 0.5 %: tempo-automation sampling) shorter than the modelled song is another
                                   # state of the song (FL held an older copy / a twin) or FL stopped early


def _wav_header_seconds(path):
    """Seconds of audio in a WAV from its header (fmt + data chunk sizes, or the file size for an open-ended data
    chunk), or None."""
    try:
        size = os.path.getsize(path)
        with open(path, "rb") as f:
            h = f.read(65536)
        if h[:4] not in (b"RIFF", b"RF64") or h[8:12] != b"WAVE":
            return None
        i = 12; bps = None
        while i + 8 <= len(h):
            cid = h[i:i + 4]; ln = struct.unpack("<I", h[i + 4:i + 8])[0]
            if cid == b"fmt ":
                chn = struct.unpack("<H", h[i + 10:i + 12])[0]; rate = struct.unpack("<I", h[i + 12:i + 16])[0]
                bits = struct.unpack("<H", h[i + 22:i + 24])[0]
                bps = rate * chn * max(1, bits // 8)
            elif cid == b"data":
                n = size - (i + 8) if ln in (0, 0xFFFFFFFF) or i + 8 + ln > size else ln
                return n / bps if bps else None
            i += 8 + ln + (ln & 1)
    except (OSError, struct.error):
        return None
    return None


def _render_short(project, path):
    """(render seconds, song seconds) when a WAV render of `project` is clearly shorter than its song (pattern clips'
    end through the tempo map - FL's export always runs at least that long), else None. Such a render is of another
    state than the file (FL held an older copy, or a same-title file): it must never become this song's FINAL or
    its cached render (PC 2026-10-23: an extended ending missing from the FINAL)."""
    if not path or not str(path).lower().endswith(".wav"):
        return None
    try:
        got = _wav_header_seconds(path)
        song = _song_seconds(project)[0]
    except Exception:                                             # noqa: BLE001 - no check without a model
        return None
    if not got or not song:
        return None
    if got < song - max(RENDER_SHORT_TOL_S, RENDER_SHORT_TOL_FRAC * song):
        return round(got, 2), round(song, 2)
    return None


def _render_length(project, path):
    """{render_s, song_s, short_s?} of a WAV render of `project`: the audio's seconds (header) against the song's
    length through its tempo map (its last clip / note end - FL's export always runs at least that long). short_s
    when the render ends more than RENDER_SHORT_TOL_S (or 0.5 %) before the song. None when either can't be read."""
    try:
        got = _wav_header_seconds(path) if path and str(path).lower().endswith(".wav") else None
        song, bars, _bpb = _song_seconds(project)
    except Exception:                                             # noqa: BLE001 - no model, no check
        return None
    if not got or not song:
        return None
    out = {"render_s": round(got, 2), "song_s": round(song, 2), "song_bars": round(bars, 2)}
    if got < song - max(RENDER_SHORT_TOL_S, RENDER_SHORT_TOL_FRAC * song):
        out["short_s"] = round(song - got, 2)
        try:
            out["render_ends_bar"] = round(bars * got / song + 1, 2) if song else None
        except Exception:                                         # noqa: BLE001
            pass
    return out


def _render_cache_peek(project, formats="wav", method="auto", strict_file=False):
    """True when a render of `project` would be reused (nothing to export). FL isn't saved here: an FL with unsaved
    changes simply counts as 'would render'. strict_file: only a render made from this exact project file (finals)."""
    try:
        RC = _rc()
        if not RC.enabled():
            return False
        route = _render_method(project, formats, method)
        if _project_is_open(project) and fl_running() and _fl_changed_flag() != 0:
            return False
        if _pending_get(project):
            return False
        fp = RC.fingerprint(_read_flp_bytes(project))
        hit = RC.get(RC.mix_key(fp, formats=str(formats).lower()), route=route, exact=True)
        if hit is not None and strict_file and (hit.get("meta") or {}).get("file_sha") != _file_sha(project):
            return False
        return hit is not None and not _render_short(project, hit["files"][0]["path"])
    except Exception:                                             # noqa: BLE001
        return False


# ---- FL's 'Split mixer tracks' export: every mixer track's stem from ONE export ---------------------------------
def _split_prepare(hwnd, want):
    """Make FL's export window's 'Split mixer tracks' what this export wants, when fl-headless knows where the box is
    (state in_fl_split.click = [x, y] as fractions of the export window, taught with fl_render_cache(split_click=...)).
    want None: leave it - but switch it back off if fl-headless switched it on for the last stems pass.
    -> 'on' / 'off' when it clicked, else None. PC-VERIFY: one click at the taught point toggles the box; FL keeps
    the setting for the next export (so the user's own exports split until it's switched back)."""
    st = dict(_state().get("in_fl_split") or {})
    click = st.get("click")
    if not click or not IS_WINDOWS:
        return None
    do = None
    if want is True and st.get("on") is not True:
        do = "on"; st.update(on=True, restore_off=st.get("on") is False or st.get("restore_off", False))
    elif want is None and st.get("restore_off") and st.get("on") is True:
        do = "off"; st.update(on=False, restore_off=False)
    if do and _click_frac(hwnd, float(click[0]), float(click[1])):
        _state({"in_fl_split": st})
        return do
    return None


def _click_frac(hwnd, fx, fy):
    """A left click inside a window at (fx, fy) fractions of its client area (posted: FL needn't be in front)."""
    try:
        import ctypes
        from ctypes import wintypes
        rc = wintypes.RECT(); u = ctypes.windll.user32
        if not u.GetClientRect(hwnd, ctypes.byref(rc)):
            return False
        x, y = int(rc.right * fx), int(rc.bottom * fy); lp = (y << 16) | (x & 0xFFFF)
        u.PostMessageW(hwnd, 0x0201, 1, lp); time.sleep(0.05); u.PostMessageW(hwnd, 0x0202, 0, lp); time.sleep(0.15)
        return True
    except Exception:                                             # noqa: BLE001
        return False


def _split_collect(project, folder, target, stem, flip):
    """After an in-FL export: the per-track files FL wrote next to `target` ('Split mixer tracks' ticked), moved to a
    staging folder -> {files {track: path}, unmatched, dir, master} or None for a plain export. What FL did is
    remembered (in_fl_split.on), so stems passes know whether one export gives every track."""
    try:
        others = [os.path.join(folder, f) for f in sorted(os.listdir(folder))
                  if f.lower().endswith((".wav", ".mp3", ".flac", ".ogg"))
                  and os.path.normcase(os.path.join(folder, f)) != os.path.normcase(target)]
    except OSError:
        others = []
    st = dict(_state().get("in_fl_split") or {})
    if not others:
        if st.get("on") is not False:
            st.update(on=False, seen=time.strftime("%Y-%m-%d %H:%M")); _state({"in_fl_split": st})
        return None
    names = {}
    try:
        d = _read_flp_bytes(project); names = _mixer_names(d, _events(d))
    except Exception:                                             # noqa: BLE001
        pass
    files, left = _rc().split_names(others, stem, names)
    stage = tempfile.mkdtemp(prefix="flh_split_")
    moved = {}
    for t, f in files.items():
        dst = os.path.join(stage, f"t{t}" + os.path.splitext(f)[1].lower()); shutil.move(f, dst); moved[t] = dst
    if os.path.exists(target) and 0 not in moved:
        moved[0] = os.path.join(stage, "t0" + os.path.splitext(target)[1].lower()); shutil.copy2(target, moved[0])
    elif not os.path.exists(target) and 0 in moved:
        shutil.copy2(moved[0], target)                            # the master is the render
    st.update(on=True, seen=time.strftime("%Y-%m-%d %H:%M"), tracks=len(moved), unmatched=len(left)); st.pop("why", None)
    _state({"in_fl_split": st})
    return {"files": moved, "unmatched": [os.path.basename(f) for f in left][:8], "dir": stage,
            "master": target if os.path.exists(target) else None, "flipped": flip}


def _rc_store_split(project, sp, route):
    """A split export's track files -> the stems set of the project's current fingerprint (16-bit in the cache; the
    staging folder goes). -> the entry or None.
    PC-VERIFY: FL's split files are each track's output after its fader and pan (the remix scales them by fader
    ratios), the bus tracks hold their inputs, and with the export window's 'Enable master effects' off the track
    files carry no master effects (sum of the tracks routed to the master == the master file before its chain)."""
    RC = _rc()
    try:
        if _project_is_open(project) and fl_running() and _fl_changed_flag() != 0:
            return None                                           # FL has changes the file doesn't: no safe key
        fp = RC.fingerprint(_read_flp_bytes(project))
        tracks = {}
        fs = None
        for t in sorted(sp.get("files") or {}):
            tracks[str(t)] = {"level": fp["levels"].get(t), "routes": fp["routes"].get(t, [0] if t else []),
                              "fx": bool(fp["fx"].get(t)), "name": fp["names"].get(t)}
        if sp.get("files"):
            try:
                fs = _wav_load(next(iter(sp["files"].values())))[1]
            except Exception:                                     # noqa: BLE001
                fs = None
        meta = {"tracks": tracks, "master_fx": bool(fp["fx"].get(0)), "fs": fs,
                "chan_insert": {str(c): t for c, t in fp["chan_insert"].items()}, "levels": fp["levels"],
                "inserts": fp["inserts"]}
        files = [{"src": p, "name": f"t{t}", "mode": "measure", "owned_src": True} for t, p in sp["files"].items()]
        return RC.put(RC.stems_key(fp), "stems", files, meta=meta, route=route, project=project)
    except Exception:                                             # noqa: BLE001
        return None
    finally:
        _split_drop(sp)


def _split_drop(sp):
    """A split export's staging folder away (ours, in the temp folder)."""
    if isinstance(sp, dict) and sp.get("dir"):
        shutil.rmtree(sp["dir"], ignore_errors=True)


def _split_ready():
    """(ok, why): can one in-FL export give every mixer track's stem on this PC?"""
    if not IS_WINDOWS:
        return False, "FL runs on Windows only"
    try:
        if not fl_running():
            return False, "FL isn't open"
        st = _state()
    except Exception:                                             # noqa: BLE001
        return False, "FL state unknown"
    if not (st.get("in_fl_render") or {}).get("ok"):
        return False, "FL's own export hasn't worked on this PC yet (fl_render method='in_fl' once)"
    sp = st.get("in_fl_split") or {}
    if sp.get("on") is False and not sp.get("click"):
        return False, ("FL's export window has 'Split mixer tracks' off: tick it once in FL's export window (FL keeps "
                       "it), or teach fl-headless where it is: fl_render_cache(split_click=[x, y])")
    return True, ""


def _stems_set(project, timeout_s=900, render=True):
    """The stems set of `project` as it is now: from the cache, or ONE split export (FL open with the project).
    -> (entry or None, fingerprint, info {renders, why?, note?})."""
    RC = _rc(); n0 = _renders_here()
    info = {"renders": 0}
    ok, why = _split_ready()
    if not ok:                                                    # no split export here: don't even key (no save)
        info["why"] = why; return None, None, info
    fp, note = _rc_project_fp(project, live=True)
    if note:
        info["note"] = note
    if not fp:
        info["why"] = note or "no fingerprint"; return None, None, info
    hit = RC.get(RC.stems_key(fp))
    if hit:
        _note_reuse(offline=True)
        info["reused"] = f"stems from one export at {_when(hit['created'])} (unchanged since)"
        return hit, fp, info
    if not render:
        info["why"] = "no stems of this version yet"; return None, fp, info
    work = _own_temp("flh_stems_")
    try:
        r = _render_in_fl(project, work, "wav", timeout_s, out_stem="mix", split=True)
        info["renders"] = _renders_here() - n0
        sp = r.get("split")
        f = (r.get("rendered") or [None])[0]
        if f:                                                     # the mix itself is a full render: kept for checks
            RC.put(RC.mix_key(fp, formats="wav"), "render", [{"src": f, "name": "mix.wav", "mode": "measure",
                                                              "owned_src": True}], route="in_fl", project=project)
        if not sp:
            info["why"] = ("FL wrote one file, not one per mixer track: 'Split mixer tracks' is off in FL's export "
                           "window (the render is kept for checks)")
            return None, fp, info
        ent = _rc_store_split(project, sp, "in_fl")
        if not ent:
            info["why"] = "the split files couldn't be stored in the render cache"
            return None, fp, info
        if sp.get("unmatched"):
            info["unmatched"] = sp["unmatched"]
        return RC.get(RC.stems_key(fp)) or ent, fp, info
    except InFlUnavailable as e:
        info["why"] = f"FL's own export didn't start ({e})"
        return None, fp, info
    finally:
        _own_temp_done(work)


def _stems_measure_units(project, units, timeout_s=900):
    """Level-balance units [(label, role, [channels], insert)] measured from ONE stems pass: {lufs {label: LUFS},
    missing [labels the stems can't separate], renders, how, why?}."""
    ent, fp, info = _stems_set(project, timeout_s)
    out = {"renders": info.get("renders", 0), "how": None}
    if ent is None:
        out["why"] = info.get("why"); return out
    lu, missing = _rc().units_from_stems(ent, units, fp["levels"])
    out.update(lufs=lu, missing=missing, how=info.get("reused") or "one export with FL's 'Split mixer tracks'")
    return out


def _preview_offline(fp, sections=None, mutes=None):
    """fl_preview's numbers from a stems set without exporting: (result or None, why)."""
    RC = _rc()
    ent = RC.get(RC.stems_key(fp))
    if not ent:
        return None, None
    y, fs, info = RC.remix(ent, fp["levels"], mutes=mutes)
    if y is None:
        return None, "; ".join(info.get("why") or [])
    r = RC.measure(y, fs, sections)
    r["offline"] = ("mixed from cached stems: exact" if info["exact"] else
                    "mixed from cached stems: approximate - " + "; ".join(dict.fromkeys(info["why"]))[:200] +
                    " (exact=true renders)")
    r["changed_tracks"] = info["changed"]
    _note_reuse(offline=True)
    return r, None


def render_range(project, start_bar, end_bar=None, preroll_bars=None, timeout_s=900, method="auto"):
    """Audio of bars [start_bar, end_bar) for checks that need only part of the song (an ending, a section), with
    pre-roll so reverbs / delays are in their steady state, the tempo map honored. Cheapest first: a cached full
    render cropped (no export) -> FL closed: a command-line render of only that range (pre-roll included) -> FL open:
    one in-FL full render (cached for every later check) cropped. -> {x, fs, offset_s (song time of x[0]), start_s,
    end_s, source, renders}."""
    RC = _rc(); project = os.path.abspath(project); n0 = _renders_here()
    pre = RC.PREROLL_BARS if preroll_bars is None else max(0.0, float(preroll_bars))
    _sync_before("render", project)
    live = _project_is_open(project) and fl_running()
    fp, note = _rc_project_fp(project, live=live)
    d = _read_flp_bytes(project)
    _tick_s, bar_s, _P, _m = RC.timeline(d)
    end_s_song = _tick_s(RC.song_end_tick(d))
    a_bar = max(1.0, float(start_bar) - pre)
    s0, s1 = bar_s(float(start_bar)), (bar_s(float(end_bar)) if end_bar else None)
    a_s = bar_s(a_bar)

    def crop(x, fs, t0):
        i = max(0, int(round((a_s - t0) * fs))); j = len(x) if s1 is None else min(len(x), int(round((s1 + 3.0 - t0) * fs)))
        return x[i:j], a_s
    full = RC.get(RC.mix_key(fp, formats="wav")) if fp else None
    if full:
        x, fs = RC.load(full["files"][0]); y, off = crop(x, fs, 0.0); _note_reuse()
        return {"x": y, "fs": fs, "offset_s": round(off, 3), "start_s": round(s0, 3), "end_s": s1 or round(end_s_song, 3),
                "source": f"cached full render ({_when(full['created'])}) cropped", "renders": 0}
    rkey = RC.mix_key(fp, formats="wav", start_bar=float(a_bar), end_bar=float(end_bar) if end_bar else None) \
        if fp else None
    got = RC.get(rkey) if rkey else None
    if got:
        x, fs = RC.load(got["files"][0]); _note_reuse()
        return {"x": x, "fs": fs, "offset_s": round(a_s, 3), "start_s": round(s0, 3), "end_s": s1 or round(end_s_song, 3),
                "source": f"cached range render ({_when(got['created'])})", "renders": 0}
    route = _render_method(project, "wav", method)
    work = _own_temp("flh_range_")
    try:
        if route == "cli" and not fl_running():
            data, _bpm, _bars, _sk = _section_bytes(_load(project), a_bar, end_bar)
            r = _render(project, work, "wav", timeout_s, data=data, out_stem="range")
            f = r["rendered"][0]
            x, fs, _ = _wav_load(f)
            if rkey:
                RC.put(rkey, "range", [{"src": f, "name": "range.wav", "mode": "measure", "owned_src": True}],
                       route="cli", project=project)
            return {"x": x, "fs": fs, "offset_s": round(a_s, 3), "start_s": round(s0, 3),
                    "end_s": s1 or round(end_s_song, 3), "source": "range render (command line)",
                    "renders": _renders_here() - n0}
        r = _render_cached(project, work, "wav", timeout_s, out_stem="full", method=method, close_fl=False,
                           store="exact")
        x, fs, _ = _wav_load(r["rendered"][0])
        y, off = crop(x, fs, 0.0)
        return {"x": y, "fs": fs, "offset_s": round(off, 3), "start_s": round(s0, 3), "end_s": s1 or round(end_s_song, 3),
                "source": "full render (FL open: its export renders the whole song; cached for later checks)",
                "renders": _renders_here() - n0}
    finally:
        _own_temp_done(work)


ENDING_RULES = ("ending_length", "tail_ring", "tail_not_cut", "ends_in_silence", "trail_silence")


def fl_ending_check(project, rules=None, render=True):
    """Will the song's ending pass the collection's ending rules? Predicted from the notes first (the last chord's
    hold vs what fl_finalize's diminuendo needs - flh_finalize's ending_hold_for_rules); only a borderline case
    renders, and then only the last ~45 s (or crops a cached render)."""
    import flh_finalize as F
    RC = _rc(); T = time.time(); n0 = _renders_here()
    try:
        import flh_store
        prof = flh_store.profile_get() or {}
    except Exception:                                             # noqa: BLE001
        prof = {}
    rl = rules if rules is not None else prof.get("rules")
    R = F._rules(rl)
    hold_fn = globals().get("ending_hold_for_rules") or F.ending_hold_for_rules
    need, margin = hold_fn(R)
    d0 = _read_flp_bytes(project)
    got = RC.ending_from_notes(d0)
    res = {"project": project, "need_hold_s": round(need, 1), "steps_s": {}}
    sim_fn = globals().get("ending_predict")
    sim = None
    if got is not None and callable(sim_fn):
        try:
            sim = sim_fn(project, rl, d=d0)
        except Exception as e:                                    # noqa: BLE001 - the hold rule below then
            res["simulation_error"] = f"{type(e).__name__}: {e}"[:160]
    if got is None:
        res.update(predicted=None, why="no notes")
    elif sim is not None:
        # the render-side rules simulated from the notes (flh_finalize.simulate_ending: level curve, the final chord's
        # attack + hold as fl_finalize finds them, its fade, rule_check's definitions) - not just the note lengths
        hold, end_s, last_on = got
        res.update(hold_s=hold, last_attack_s=last_on, song_end_s=end_s,
                   simulated={k: sim.get(k) for k in ("ending_s", "tail_s", "last_full_s", "end_s", "flat", "fade",
                                                       "hold_vs_full_db", "jumps")})
        tol_e = max(1.5, 0.08 * R["min_ending_s"]); tol_t = max(1.5, 0.08 * R["min_tail_s"])   # the model's error
        e, tl = float(sim["ending_s"]), float(sim["tail_s"])
        short = max(R["min_ending_s"] - e, R["min_tail_s"] - tl)
        if e >= R["min_ending_s"] + tol_e and tl >= R["min_tail_s"] + tol_t:
            res["predicted"] = "pass"
            res["why"] = (f"simulated from the notes: ending_length {e:g} s (needs {R['min_ending_s']:g}), tail_ring "
                          f"{tl:g} s (needs {R['min_tail_s']:g}) with fl_finalize's "
                          f"{'diminuendo over the held chord' if sim.get('fade') == 'hold_diminuendo' else 'decay fade'}"
                          " - no render")
        elif e < R["min_ending_s"] - tol_e or tl < R["min_tail_s"] - tol_t:
            res["predicted"] = "fail"
            want = int(-(-(hold + max(short, 0.0) / F.HOLD_FADE_EFF + 2.0) // 1))
            res["fix"] = tool_call_hint("flp_extend_ending", {"project": project, "hold_s": max(want, int(-(-need // 1)))})
            res["why"] = (f"simulated from the notes: ending_length {e:g} s, tail_ring {tl:g} s - the rules need "
                          f"{R['min_ending_s']:g} / {R['min_tail_s']:g} s (predicted, no render)")
        else:
            res["predicted"] = "borderline"
            res["why"] = f"simulated ending_length {e:g} s is within {tol_e:g} s of {R['min_ending_s']:g} s"
        if sim.get("jumps"):
            res["level_jumps_predicted"] = sim["jumps"]
            res["level_jumps_note"] = ("fl_finalize rides these rises in on the final (level_jumps); "
                                       + tool_call_hint("flp_smooth_entries", {"project": project})
                                       + " shapes them in the notes instead")
        try:                                                      # an extended ending undone by a later edit
            import flh_store
            eh = (flh_store.journal_get(project) or {}).get("ending_hold") or {}
            if eh.get("main_s") and hold < float(eh["main_s"]) - 1.0:
                res["ending_undone"] = (f"flp_extend_ending held the last chord {eh['main_s']:g} s, the notes now hold "
                                        f"{hold:g} s (a later flp_perform re-renders the notes from its source): run "
                                        "flp_extend_ending again after the last perform pass")
        except Exception:                                         # noqa: BLE001
            pass
    else:
        hold, end_s, last_on = got
        res.update(hold_s=hold, last_attack_s=last_on, song_end_s=end_s)
        if hold >= need:
            res["predicted"] = "pass"
            res["why"] = (f"the last chord sounds {hold:g} s from its attack; the rules need about {need:.0f} s "
                          "(fl_finalize's diminuendo over it) - predicted from the notes, no render")
        elif hold + margin < need:
            res["predicted"] = "fail"
            res["fix"] = tool_call_hint("flp_extend_ending", {"project": project, "hold_s": int(-(-need // 1))})
            res["why"] = f"the last chord sounds {hold:g} s; about {need:.0f} s are needed (predicted, no render)"
        else:
            res["predicted"] = "borderline"
    res["steps_s"]["predict"] = round(time.time() - T, 2)
    if res.get("predicted") in (None, "borderline") and render:
        T = time.time()
        d = _read_flp_bytes(project)
        tick_s, bar_s, P, meters = RC.timeline(d)
        end_tick = RC.song_end_tick(d)
        start_s = max(0.0, tick_s(end_tick) - RC.ENDING_WINDOW_S)
        lo, hi = 1.0, _tick_to_bar(end_tick, meters, P) + 1
        for _ in range(30):                                       # the bar where the last ~45 s begin
            mid = (lo + hi) / 2
            lo, hi = (mid, hi) if bar_s(mid) < start_s else (lo, mid)
        rr = render_range(project, int(lo), None)
        x, fs = rr["x"], rr["fs"]
        x = x[int(max(0.0, rr["start_s"] - rr["offset_s"]) * fs):]
        if not len(x):
            res.update(measured=None, source=rr["source"], why="the render holds no audio for the ending")
            res["renders"] = _renders_here() - n0
            return res
        chk = F.rule_check(x, fs, rl)
        chk["checks"] = [c for c in chk.get("checks") or [] if c.get("rule") in ENDING_RULES]
        chk["pass"] = all(c["pass"] for c in chk["checks"])
        res.update(measured=chk, source=rr["source"])
        res["steps_s"]["render_range"] = round(time.time() - T, 2)
    res["renders"] = _renders_here() - n0
    return res


def tool_call_hint(tool, args):
    return f"{tool}({', '.join(f'{k}={json.dumps(v)}' for k, v in args.items())})"


def fl_render_cache(action="status", gb=None, split_click=None):
    """The render cache: status (size, entries, renders saved this session), clear (its files to the Recycle Bin),
    gb=N its size cap (0 = off), split_click=[x, y] where 'Split mixer tracks' sits in FL's export window (fractions
    of the window, from fl_render_probe(stage='export_dialog')'s picture) so stems passes can tick it."""
    RC = _rc(); out = {}
    if gb is not None:
        _state({"render_cache_gb": max(0.0, float(gb))}); out["cap_set_gb"] = max(0.0, float(gb))
    if split_click is not None:
        st = dict(_state().get("in_fl_split") or {})
        if split_click in ([], None, False):
            st.pop("click", None)
        else:
            x, y = float(split_click[0]), float(split_click[1])
            if not (0 < x < 1 and 0 < y < 1):
                raise ValueError("split_click: [x, y] as fractions (0..1) of FL's export window")
            st["click"] = [round(x, 4), round(y, 4)]
        _state({"in_fl_split": st}); out["split"] = st
    if action == "clear":
        out.update(RC.clear())
    elif action != "status":
        raise ValueError("action: status | clear")
    out.update(RC.status())
    out["session"] = _render_stats_view()
    out["split_export"] = dict(_state().get("in_fl_split") or {}) or "unknown (no in-FL export seen yet)"
    return out


# ---- after fl_open: extensions' follow-ups (e.g. a new song's pending level balance) ---------------------------
_BEFORE_FL_START = []                                             # [fn()]: run right before fl-headless starts FL
_AFTER_OPEN = []                                                  # [fn(project, result)]: flh_newsong adds one


def _after_open(project, res):
    for fn in list(_AFTER_OPEN):
        try:
            fn(project, res)
        except Exception:                                         # noqa: BLE001 - a follow-up never fails the open
            pass


TOOLS["fl_render_cache"] = (fl_render_cache, "The render cache (unchanged songs aren't exported again; stems mixed "
                            "offline): status, clear (to the Recycle Bin), gb= size cap (0 = off), split_click=[x, y] "
                            "where 'Split mixer tracks' sits in FL's export window.",
                            _schema(action=_STR("status (default) | clear", True), gb=_NUM("size cap in GB", True),
                                    split_click=_p("array", "[x, y] fractions of FL's export window", True,
                                                   items={"type": "number"})))
TOOLS["fl_ending_check"] = (fl_ending_check, "Will the ending pass the collection's ending rules? Predicted from the "
                            "notes first (no render); a borderline case renders only the last ~45 s (or cuts a cached "
                            "render).", _schema(project=_FLP, rules=_p("object", "rule thresholds (default: profile)", True),
                                                render=_BOOL("render when the notes can't tell (default true)", True)))


# ---- (4) live notes through a piano-roll script (experimental) -------------------------------------------------
# What is known (FL Studio API stubs, IL-Group/FL-Studio-API-Stubs): piano-roll scripts are .pyscript files in
# <user data>\Settings\Piano roll scripts; module flpianoroll: score (PPQ, noteCount, getNote, addNote, deleteNote,
# clearNotes(all)), Note(number, time, length, velocity 0-1, pan 0-1, release 0-1, color 0-15, fcut, fres, pitchofs
# (10-cent units), slide, porta, muted). The script edits the channel shown in the piano roll, in the current
# pattern. FL's piano roll has 'Run last script again' = Ctrl+Alt+Y (FL manual, piano roll menu). The MIDI script
# side can pick the pattern (patterns.jumpToPattern), the channel (channels.selectOneChannel) and show/focus the
# piano roll (ui.showWindow / ui.setFocused(widPianoRoll)).
# What is NOT known (PC-VERIFY, see checklists/core.md): whether a script without createDialog runs apply()
# straight away; whether FL re-reads the .pyscript file on 'run last script again' (the job is embedded in the file
# AND written as a queue file, whichever FL lets the script read); whether piano-roll scripts may read/write files
# in FL 2026 (MIDI scripts may not); whether Ctrl+Alt+Y reaches the piano roll when FL is brought to the front; that
# the run is one undo step. Ctrl+Alt+Y runs whatever script ran LAST - if the user ran another one since, that one
# would run: so the job names the exact notes the piano roll must show before it changes anything, the result is
# checked by saving FL and reading the file, and anything unexpected is put back (file restored + reload).
LIVE_SCRIPT_NAME = "fl_headless_notes"
LIVE_MAX_PATTERNS = 16


def _pr_scripts_dir():
    ud = _fl_userdata()
    for s in (os.path.join(ud, "Settings"), os.path.join(ud, "FL Studio", "Settings")):
        if os.path.isdir(s):
            return os.path.join(s, "Piano roll scripts")
    raise FileNotFoundError("FL's Settings folder wasn't found (flh_setup shows which user data folder is used)")


_PR_SCRIPT = '''"""fl-headless live notes - written by fl-headless before each use (don't edit; it's rewritten).
Replaces the notes of the channel shown in the piano roll with the job's notes - only while the job is fresh and only
when the piano roll shows exactly the notes the job expects to replace. Otherwise it changes nothing."""
import flpianoroll as flp

JOB = __JOB__
QUEUE = __QUEUE__
RECEIPT = __RECEIPT__


def _now():
    try:
        import time
        return time.time()
    except Exception:
        return None


def _job():
    try:
        import json
        with open(QUEUE) as f:
            j = json.loads(f.read())
        if isinstance(j, dict) and j.get("id"):
            return j
    except Exception:
        pass
    return JOB


def _receipt(j, status, extra=None):
    try:
        import json
        r = {"id": (j or {}).get("id"), "status": status}
        r.update(extra or {})
        with open(RECEIPT, "w") as f:
            f.write(json.dumps(r))
    except Exception:
        pass


def apply(form=None):
    j = _job()
    if not j or j.get("done"):
        return _receipt(j, "no job")
    now = _now()
    if now is not None and now > float(j.get("until", 0)):
        return _receipt(j, "expired")
    sc = flp.score
    k = float(sc.PPQ) / float(j.get("ppq") or sc.PPQ)
    cur = sorted([int(round(sc.getNote(i).time / k)), int(sc.getNote(i).number)] for i in range(sc.noteCount))
    if cur != sorted(j.get("expect") or []):
        return _receipt(j, "target mismatch", {"found": len(cur), "expected": len(j.get("expect") or [])})
    sc.clearNotes(True)
    for n in j.get("notes") or []:
        x = flp.Note()
        x.number = int(n["key"]); x.time = int(round(n["pos"] * k)); x.length = max(1, int(round(n["len"] * k)))
        for name, val in (("velocity", n.get("vel")), ("pan", n.get("pan")), ("release", n.get("rel")),
                          ("color", n.get("color")), ("fcut", n.get("fcut")), ("fres", n.get("fres")),
                          ("pitchofs", n.get("pitchofs")), ("slide", n.get("slide")), ("porta", n.get("porta")),
                          ("muted", n.get("muted"))):
            if val is not None:
                try:
                    setattr(x, name, val)
                except Exception:
                    pass
        sc.addNote(x)
    _receipt(j, "done", {"notes": sc.noteCount})
'''


def _pr_note(r, P):
    """A note record of the file -> the piano-roll script's note fields (file bytes 0..128 -> 0..1)."""
    pos, flags, ch, ln, key, group, fine, _u, rel, color, pan, vel, mx, my = r
    # k/128 and k/256 are exact binary fractions: FL's x*128 gives the byte back (no rounding drift)
    n = {"pos": pos, "len": ln, "key": key, "vel": min(vel, 128) / 128.0, "pan": min(pan, 128) / 128.0,
         "rel": min(rel, 128) / 128.0, "color": color & 15, "fcut": mx / 256.0, "fres": my / 256.0,
         "pitchofs": int(fine) - 120,
         # always said, True or False: the script sets every field it's given, so a slide turned OFF is written as
         # off too (a missing field left FL's own default to decide). PC-VERIFY: slide flag bit in FL 2026's record
         "slide": bool(flags & NOTE_SLIDE)}
    return n


def _slide_marks(path, chans=None):
    """Where the slide flag (NOTE_SLIDE) is set: sorted (pattern, pos, channel, key) - _fingerprint doesn't hash note
    flags, so a live edit that only switches slides on/off is checked with this too."""
    d = _load(path); ev = _events(d)
    return sorted((pid, r[0], r[2], r[4]) for pid, pt in _patterns(d, ev).items() for r in pt["notes"]
                  if r[1] & NOTE_SLIDE and (chans is None or r[2] in chans))


def _all_channel_notes(path):
    """{(pattern id, channel): sorted note records} from a project file (every pattern is listed under channel None
    too, so a pattern without notes still counts as existing)."""
    d = _load(path); ev = _events(d); out = {}
    for pid, pt in _patterns(d, ev).items():
        out[(pid, None)] = []
        for r in pt["notes"]:
            out.setdefault((pid, r[2]), []).append(tuple(r))
    return {k: sorted(v) for k, v in out.items()}


def _channel_notes(path, ch):
    """{pattern id: sorted note records of channel ch} from a project file."""
    d = _load(path); ev = _events(d)
    return {pid: sorted(tuple(r) for r in pt["notes"] if r[2] == ch) for pid, pt in _patterns(d, ev).items()}


def _note_keys(recs):
    """What FL must keep of notes (as _fingerprint): position, channel, length, key, velocity."""
    return sorted((r[0], r[2], r[3], r[4], min(127, r[11])) for r in recs)


def _write_pr_script(job):
    """Write the piano-roll script with the job embedded and the job as a queue file (ASCII paths)."""
    d = _pr_scripts_dir(); os.makedirs(d, exist_ok=True)
    q = os.path.join(d, LIVE_SCRIPT_NAME + ".job.json"); rc = os.path.join(d, LIVE_SCRIPT_NAME + ".receipt.json")
    body = (_PR_SCRIPT.replace("__JOB__", ascii(job))           # a Python literal: the script needs no json to read it
            .replace("__QUEUE__", ascii(q.replace("\\", "/"))).replace("__RECEIPT__", ascii(rc.replace("\\", "/"))))
    path = os.path.join(d, LIVE_SCRIPT_NAME + ".pyscript")
    with open(path + ".tmp", "w", encoding="ascii", newline="\n") as f:
        f.write(body)
    os.replace(path + ".tmp", path)
    with open(q + ".tmp", "w", encoding="utf-8") as f:
        json.dump(job, f)
    os.replace(q + ".tmp", q)
    try:
        os.remove(rc)                                             # our own receipt from a previous run
    except OSError:
        pass
    return path, q, rc


def _live_notes(channel, pattern, notes, expect, ppq, timeout_s=6.0):
    """Replace channel's notes in pattern in the OPEN FL through the piano-roll script: open that piano roll (bridge),
    write the job, press 'run last script again' (Ctrl+Alt+Y), wait for the receipt (if FL lets the script write one).
    notes / expect: note records as in the file. Doesn't verify: the caller saves FL once and compares the file.
    Returns {target, receipt, steps_s}; raises when a step plainly failed (popup, bridge, script folder)."""
    steps = {}; T = time.time()
    job = {"id": f"{os.getpid()}-{int(time.time() * 1000)}", "until": time.time() + timeout_s + 20, "ppq": int(ppq),
           "expect": sorted([int(r[0]), int(r[4])] for r in expect), "notes": [_pr_note(r, ppq) for r in notes]}
    path, q, rc = _write_pr_script(job)
    steps["script"] = round(time.time() - T, 2); T = time.time()
    tgt = BRIDGE.call("piano_roll", channel=int(channel), pattern=int(pattern), timeout=5.0)
    steps["piano_roll"] = round(time.time() - T, 2)
    if int(tgt.get("pattern") or -1) != int(pattern) or int(tgt.get("channel") if tgt.get("channel") is not None else -1) != int(channel):
        raise RuntimeError(f"FL's piano roll didn't switch to channel {channel} / pattern {pattern} (shows {tgt})")
    before = {d["hwnd"] for d in fl_dialogs()}
    T = time.time()
    if not _fl_foreground():
        raise RuntimeError("couldn't bring FL to the front for the piano-roll shortcut")
    _send_keys(0x59, (0x11, 0x12))                                # Ctrl+Alt+Y: run last script again
    got = _wait_for(lambda: _json_read(rc, None), timeout_s, 0.1)
    steps["run"] = round(time.time() - T, 2)
    pops = _new_dialogs(before)
    for d in pops:                                                # another script's options dialog: cancel it
        _dismiss(d)
    _write_pr_script(dict(job, done=True, notes=[]))              # a later manual run must do nothing
    if pops:
        raise RuntimeError(f"a window opened instead ({[d['title'] for d in pops]}): FL's last piano-roll script isn't "
                           f"{LIVE_SCRIPT_NAME} - run it once from the piano roll (Tools > Scripting)")
    if got and got.get("id") == job["id"] and got.get("status") != "done":
        raise RuntimeError(f"the piano-roll script refused: {got.get('status')}")
    return {"target": tgt, "receipt": got.get("status") if got else None, "steps_s": steps}


def _live_state():
    try:
        return _state().get("live_notes") or {}
    except Exception:
        return {}


def _edit_and_reload_without_save(project, data, fn):
    """Put `data` (FL's own save from just before) back into the file, run fn() on it and reload FL - no new FL save,
    so whatever a failed live attempt changed in FL is thrown away."""
    _write_bytes(project, data)
    try:
        pre_fp = _fingerprint(project)
    except Exception:
        pre_fp = None
    res = fn()
    steps = _reload_in_fl(project) or {}
    if not _wait_for(_ping_ok, 60, 0.3):
        steps["note"] = "FL didn't answer after the reload"
    try:
        BRIDGE.call("transport", action="stop", timeout=3.0)
    except Exception:
        pass
    if isinstance(res, dict):
        res["reloaded_in_fl"] = True; res["steps_s"] = steps
        try:
            res["verify_job"] = _verify_in_background(project, open(project, "rb").read(), _fingerprint(project), False,
                                                      pre_fp)
        except Exception:
            pass
    return res


# note writers the piano-roll script can do live (they only change pattern notes): name -> its project argument.
# PC 2026-10-23 files.slide_flag: a slide turned OFF with flp_edit_notes went the merged-reload way while the slide
# turned ON had gone live; FL's next save then still held the slide (the reload hadn't run yet)
LIVE_NOTE_TOOLS = {"flp_replace_part": "project", "flp_edit_notes": "path", "flp_add_notes": "path"}


def _live_replace_part(project, kw, force=False, name="flp_replace_part"):
    """_live_replace_part_locked holding the FL lock (it saves, writes live and may reload)."""
    if not IS_WINDOWS or (not force and not _live_state().get("ok")) or _pending_get(project):
        return None
    if not _fl_acquire():
        raise RuntimeError(f"FL is busy ({_fl_busy_with()}), so nothing was changed; try again when it's done")
    try:
        return _live_replace_part_locked(project, kw, force, name)
    finally:
        _FL_LOCK.release()


def _live_writer(name, project, args):
    """Run note writer `name` (LIVE_NOTE_TOOLS) on `project` in place, file only (as part of this edit: no save /
    reload of its own - flp_edit_notes / flp_add_notes would otherwise hot-reload FL themselves)."""
    kw = dict(args); kw[LIVE_NOTE_TOOLS[name]] = project; kw["output"] = project
    return _as_edit(lambda: globals()[name](**kw))


def _live_replace_part_locked(project, kw, force=False, name="flp_replace_part"):
    """A note writer (flp_replace_part, flp_edit_notes, flp_add_notes) on the OPEN project without a reload: FL saves,
    the new notes are computed on a temp copy, each changed (pattern, channel) is written live through the piano-roll
    script, FL saves again and the file must then match the temp copy exactly (all notes, clips, channels - and
    where slides are set, which the fingerprint doesn't hash). On a mismatch the file is put back to FL's first save,
    the edit goes in by file and FL reloads (no live leftovers). None when live notes aren't enabled/possible here
    (the caller uses the normal path). PC-VERIFY: the whole path (checklists/core.md)."""
    if not IS_WINDOWS or (not force and not _live_state().get("ok")) or _pending_get(project):
        return None
    if name not in LIVE_NOTE_TOOLS or (kw.get("output") and _ud_key(kw["output"]) != _ud_key(project)):
        return None
    global _EDIT_DEPTH
    steps = {}; T = time.time()
    try:
        if not _save_in_fl_and_wait(project, 8.0):
            return None
    except Exception:
        return None
    steps["save"] = round(time.time() - T, 1); T = time.time()
    orig = open(project, "rb").read()
    work = tempfile.mkdtemp(prefix="flh_live_"); _TEMP_ROOTS.append(os.path.normcase(os.path.abspath(work)))
    try:
        tmp = os.path.join(work, os.path.basename(project))
        with open(tmp, "wb") as f:
            f.write(orig)
        args = {k: v for k, v in kw.items() if k not in (LIVE_NOTE_TOOLS[name], "output")}
        _edit_enter()
        try:
            r = _live_writer(name, tmp, args)
        finally:
            _edit_exit()
        P = _ppq(_load(tmp))
        old, new = _all_channel_notes(project), _all_channel_notes(tmp)
        pats = {p for p, _c in old}
        changed = [k for k in sorted(set(old) | set(new), key=lambda k: (k[0], -1 if k[1] is None else k[1]))
                   if k[1] is not None and old.get(k, []) != new.get(k, [])]
        steps["plan"] = round(time.time() - T, 2)
        if not changed:                                           # nothing to write: as the file route would say
            if isinstance(r, dict):
                r.update(output=project, live=True, verified=True, steps_s=steps, reloaded_in_fl=False,
                         note="nothing changed in the notes, so FL wasn't touched")
            return r
        if len(changed) > LIVE_MAX_PATTERNS or any(p not in pats for p, _c in changed):
            return None                                           # many patterns / a new one: a reload is cleaner
        want = _fingerprint(tmp); chans = {c for _p, c in changed}; want_sl = _slide_marks(tmp, chans)
        T = time.time(); err = None
        try:
            for p, ch in changed:
                _live_notes(ch, p, new.get((p, ch), []), old.get((p, ch), []), P)
        except Exception as e:
            err = f"{type(e).__name__}: {e}"
        steps["live"] = round(time.time() - T, 1); T = time.time()
        ok = err is None and _save_in_fl_and_wait(project, 8.0) and not _fp_diff(want, _fingerprint(project))
        if ok and _slide_marks(project, chans) != want_sl:        # FL kept the notes but not the slide on/off
            ok = False; err = "FL's piano roll didn't take the slide flags (slide on/off)"
        steps["verify"] = round(time.time() - T, 1)
        if ok:
            npat = len({p for p, _c in changed})
            if isinstance(r, dict):
                r.update(output=project, live=True, verified=True, steps_s=steps,
                         note=f"written live in FL ({npat} pattern(s)), no reload; FL saved and holds exactly the edit")
            return r
        T = time.time()
        res = _edit_and_reload_without_save(project, orig, lambda: _live_writer(name, project, args))
        steps["fallback"] = round(time.time() - T, 1)
        res = dict(res or {}); res.update(output=project, live=False, steps_s=dict(steps, **(res.get("steps_s") or {})),
                                          live_note=f"live notes didn't check out ({err or 'FL held something else'}); "
                                                    "the edit went in by file with a reload instead")
        if err and "last piano-roll script" in err:
            st = _live_state(); st["ok"] = False; st["why"] = err[:200]; _state({"live_notes": st})
        return res
    finally:
        try:
            _TEMP_ROOTS.remove(os.path.normcase(os.path.abspath(work)))
        except ValueError:
            pass
        shutil.rmtree(work, ignore_errors=True)


def fl_live_notes_probe(channel=None, pattern=None, project=None):
    """Tests live note writing on the OPEN (saved) project: adds one probe note to a channel's notes in a pattern
    through the piano-roll script, checks FL holds it (save + read), then puts the original notes back the same way.
    Reports which steps work on this FL; on success live notes are switched on for the note writers (LIVE_NOTE_TOOLS).
    Anything left over is undone by restoring FL's first save and reloading."""
    rep = {"steps": {}}; S = rep["steps"]
    if not fl_running():
        raise RuntimeError("open FL with a saved project first (a copy of a song is ideal)")
    if project:                                                   # named by the caller: proven by a save first
        got = _prove_open(project)
        if not (isinstance(got, str) and got != "never_saved" and _ud_key(got) == _ud_key(project)):
            raise RuntimeError(f"FL doesn't have {os.path.basename(project)} open (a save didn't land in it)")
    else:
        project, _t = _open_project_guess()
    if not project:
        raise RuntimeError("couldn't tell which saved project FL has open (untitled projects can't be checked)")
    rep["project"] = project
    try:
        cmds = BRIDGE.call("commands", timeout=5.0)
        S["bridge_piano_roll_command"] = "ok" if "piano_roll" in (cmds or []) else "missing"
    except Exception as e:
        S["bridge_piano_roll_command"] = f"missing ({e})"
    if S["bridge_piano_roll_command"] != "ok":
        rep["next"] = "update FL's bridge script: fl_bridge_setup(action='update_script'), restart FL, probe again"
        return rep
    try:
        d = _pr_scripts_dir(); S["scripts_folder"] = d
    except Exception as e:
        S["scripts_folder"] = f"not found: {e}"; return rep
    if not _save_in_fl_and_wait(project, 8.0):
        S["save"] = "FL didn't save (busy, or a popup)"; return rep
    orig = open(project, "rb").read(); P = _ppq(orig); dd = _load(project); pats = _patterns(dd, _events(dd))
    if pattern is None or channel is None:
        pick = next(((pid, r[2]) for pid, pt in sorted(pats.items()) for r in pt["notes"]), None)
        if pick is None:
            raise RuntimeError("no pattern with notes in the open project: give channel and pattern")
        pattern, channel = pick if pattern is None else (pattern, pick[1])
    pattern, channel = int(pattern), int(channel)
    if pattern not in pats:
        raise ValueError(f"pattern {pattern} isn't in the project")
    old = sorted(tuple(r) for r in pats[pattern]["notes"] if r[2] == channel)
    tmpl = old[0] if old else (0, 16384, channel, P, 60, 0, 120, 0, 64, 0, 64, 100, 128, 128)
    probe_note = (max([r[0] + r[3] for r in old] or [0]), tmpl[1], channel, P, 60, 0, 120, 0, 64, tmpl[9], 64, 100, 128, 128)
    want = sorted(old + [probe_note]); rep.update(channel=channel, pattern=pattern)
    ok_all = False
    try:
        for label, notes, expect in (("add_probe_note", want, old), ("restore", old, want)):
            T = time.time()
            try:
                r = _live_notes(channel, pattern, notes, expect, P)
                S[label] = {"receipt": r["receipt"], "target": r["target"], "steps_s": r["steps_s"]}
            except Exception as e:
                S[label] = f"failed: {type(e).__name__}: {e}"; break
            held = _save_in_fl_and_wait(project, 8.0) and \
                _note_keys(_channel_notes(project, channel).get(pattern, [])) == _note_keys(notes)
            S[label]["fl_holds_it"] = bool(held); S[label]["s"] = round(time.time() - T, 1)
            if not held:
                break
        else:
            ok_all = True
    finally:
        if not ok_all:
            try:
                _edit_and_reload_without_save(project, orig, lambda: {"restored": True})
                S["cleanup"] = "FL's first save restored and reloaded"
            except Exception as e:
                S["cleanup"] = f"FAILED: {e} - the project file is still FL's first save; reopen it in FL"
    st = dict(_live_state(), ok=ok_all, t=int(time.time()), why=None if ok_all else "probe failed")
    _state({"live_notes": st})
    rep["live_notes_enabled"] = ok_all
    if not ok_all:
        first = S.get("add_probe_note")
        if isinstance(first, dict) and not first.get("fl_holds_it") and first.get("receipt") is None:
            rep["next"] = (f"in FL's piano roll run Tools > Scripting > {LIVE_SCRIPT_NAME} once by hand (it does nothing "
                           "on its own), so 'run last script again' (Ctrl+Alt+Y) runs it; then probe again")
        else:
            rep["next"] = "see steps: the first failing step says what FL didn't do"
    else:
        rep["next"] = "live notes are on: flp_replace_part on the open project now writes without a reload"
    return rep


# ---- bug report ------------------------------------------------------------------------------------------------
import collections  # noqa: E402
import traceback  # noqa: E402

_ERRORS = collections.deque(maxlen=40)                          # recent tool errors (kept over flh_reload)


def _note_tool_error(name, exc, tb=None):
    """The dispatcher calls this for every failed tool call (also inside flh_run): a ring buffer for flh_bug_report."""
    try:
        _ERRORS.append({"t": time.strftime("%Y-%m-%d %H:%M:%S"), "tool": name, "error": f"{type(exc).__name__}: {exc}"[:600],
                        "traceback": (tb or "".join(traceback.format_exception(type(exc), exc, exc.__traceback__)))[-4000:]})
    except Exception:
        pass


def _profile_prefixes():
    """The user's own folders as they show up in paths: home / USERPROFILE / OneDrive* (OneDrive folders carry an
    organisation name: 'OneDrive - Contoso Ltd'). Longest first."""
    out = set()
    for v in (os.path.expanduser("~"), os.environ.get("USERPROFILE"), os.environ.get("HOME"),
              os.environ.get("OneDrive"), os.environ.get("OneDriveCommercial"), os.environ.get("OneDriveConsumer")):
        v = (v or "").strip().rstrip("\\/")
        if len(v) >= 4 and v not in ("/root", "/home") and re.search(r"[\\/]", v):
            out.add(v)
    return sorted(out, key=len, reverse=True)


def _scrub(v):
    """Privacy for bug reports: e-mail addresses -> <email>; the user's profile / OneDrive folders in any path -> <user>
    (names with spaces or any script, either slash, doubled backslashes as in repr); other '\\Users\\<name>' /
    '/home/<name>' paths -> <user> up to the next separator; the account name anywhere -> <user>."""
    if isinstance(v, dict):
        return {_scrub(k) if isinstance(k, str) else k: _scrub(x) for k, x in v.items()}
    if isinstance(v, (list, tuple)):
        return [_scrub(x) for x in v]
    if not isinstance(v, str):
        return v
    s = re.sub(r"[\w.+%-]+@[\w-]+(?:\.[\w-]+)+", "<email>", v)
    for pre in _profile_prefixes():
        parts = [re.escape(x) for x in re.split(r"[\\/]+", pre) if x]
        rx = (r"(?:[\\/]+)?" if pre[:1] in "\\/" else "") + r"[\\/]+".join(parts)
        s = re.sub(rx + r"(?=$|[\\/'\"\s:;,)\]}>])", "<user>", s, flags=re.I)
    s = re.sub(r"(?i)([\\/](?:users|home|documents and settings)[\\/]+)(?!<user>)(?:[^\\/'\"\r\n\t:;]|'(?=\w))+", r"\1<user>", s)
    names = set()
    for n in (os.environ.get("USERNAME"), os.environ.get("USER"), os.path.basename(os.path.expanduser("~").rstrip("\\/"))):
        if n and n not in ("root", "user", "admin", "home"):
            names.add(n)
    for n in sorted((x for x in names if len(x) >= 3), key=len, reverse=True):
        s = re.sub(re.escape(n), "<user>", s, flags=re.I)
    return s


def flh_bug_report(errors=10):
    """A privacy-safe bundle for a bug report: versions, OS, FL version/edition, setup check, the last tool errors
    with tracebacks, timings, tool usage counts and extension status - user names replaced by <user>; never audio, project contents
    or file names beyond those scrubbed paths. Writes a .zip in fl-headless's state folder."""
    import platform, zipfile
    rep = {"fl_headless": SERVER["version"], "python": sys.version.split()[0], "os": platform.platform(),
           "machine": platform.machine(), "made": time.strftime("%Y-%m-%d %H:%M:%S")}
    try:
        import numpy
        rep["numpy"] = numpy.__version__
    except ImportError:
        rep["numpy"] = None
    try:
        rep["fl_version"] = _fl_file_version()
    except Exception as e:
        rep["fl_version"] = f"unknown ({type(e).__name__})"
    try:
        cat = sys.modules.get("flh_catalog")
        rep["fl_edition"] = list(cat.fl_edition()) if cat else None
    except Exception:
        rep["fl_edition"] = None
    L = _live()
    try:
        setup = L["TOOLS"]["flh_setup"][0]() if "flh_setup" in L["TOOLS"] else None
    except Exception as e:
        setup = {"error": f"{type(e).__name__}: {e}"}
    try:
        timings = L["fl_timings"]()
    except Exception as e:
        timings = {"error": str(e)}
    ext = L.get("_EXT_STATUS") or {}
    try:
        st = _state()
    except Exception:
        st = {}
    safe_state = {k: st.get(k) for k in ("fl_edition", "reload_mode", "in_fl_render", "live_notes", "quickcheck_version")
                  if k in st}
    costs = [{"avg_s": e.get("avg_s"), "samples": len(e.get("samples") or []), "source": e.get("source")}
             for e in _json_read(LOAD_COSTS, {}).values()]
    errs = list(L.get("_ERRORS") or _ERRORS)[-max(1, int(errors)):]
    files = {"report.json": rep, "setup_check.json": setup, "errors.json": errs, "timings.json": timings,
             "extensions.json": {"loaded": [e.get("module") for e in ext.get("loaded", [])], "errors": ext.get("errors", {})},
             "state.json": dict(safe_state, load_costs=costs, pending_ops=sum(_pending_summary().values()))}
    try:                                                         # tool names + counts only (local usage log)
        files["usage.json"] = (L.get("_usage_summary") or _usage_summary)(25)
    except Exception as e:                                       # noqa: BLE001
        files["usage.json"] = {"error": type(e).__name__}
    try:                                                         # what install.py found (written by it)
        with open(os.path.join(os.path.dirname(STATE), "install_log.txt"), encoding="utf-8", errors="replace") as f:
            files["install_log.json"] = f.read()[-4000:].splitlines()
    except OSError:
        pass
    files = {k: _scrub(v) for k, v in files.items()}
    folder = os.path.join(os.path.dirname(STATE), "bug_reports"); os.makedirs(folder, exist_ok=True)
    path = os.path.join(folder, time.strftime("flh-bug-%Y%m%d-%H%M%S.zip"))
    with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as z:
        for name, obj in files.items():
            z.writestr(name, json.dumps(obj, indent=1, default=str))
    for old in sorted(glob.glob(os.path.join(folder, "flh-bug-*.zip")))[:-10]:
        os.remove(old)                                            # our own earlier reports only (newest 10 kept)
    return {"zip": path, "size_bytes": os.path.getsize(path), "contains": sorted(files),
            "errors_included": len(errs), "privacy": "user names -> <user>, e-mails -> <email>; no audio, no project "
            "contents, no file names except inside scrubbed paths. Read it before sharing if you like (it's JSON).",
            "next": "attach the zip to an issue on the fl-headless GitHub page with what you did and what happened"}


# ============================================================================= extensions
# Extra tool modules next to this file (flh_*.py). Each has register(ns): it keeps the server namespace and adds its
# tools to ns["TOOLS"]. flh_reload re-imports them and registers them again with the fresh namespace.
# ============================================================================= tool surface (tiers + discovery)
# 160+ tools with full descriptions cost ~31k tokens in every session. Clients get the ESSENTIAL tier by default
# (short descriptions, short parameter help); flh_tools finds and explains the rest, and flh_call / flh_run call any
# tool whether it's listed or not. TOOLS entries keep their full description (2nd element); LONG_HELP[name] adds
# more. FLH_TOOLSET env or the profile's "toolset": essential (default) | full | comma list of groups / tool names.
TOOLSETS = ("essential", "full")
