_TOOL_MODULE = {}                            # tool -> extension module that registered it (set by _load_extensions)
CORE_ALWAYS = ("flh_tools", "flh_call", "flh_run", "fl_status", "flh_setup")   # listed in every toolset


def tool_group(name):
    if name in TOOL_GROUPS:
        return TOOL_GROUPS[name]
    for g, names in GROUPS.items():
        if name in names:
            return g
    mod = _TOOL_MODULE.get(name)
    if mod in MODULE_GROUPS and mod not in ("flh_store", "flh_setup"):
        return MODULE_GROUPS[mod]
    return next((g for p, g in PREFIX_GROUPS if name.startswith(p)), "other")


def _toolset_setting():
    """(value, where from): FLH_TOOLSET > the collection profile's 'toolset' > essential."""
    v = os.environ.get("FLH_TOOLSET")
    if v:
        return v.strip(), "FLH_TOOLSET"
    try:
        store = sys.modules.get("flh_store")
        prof = (store.profile_get() or {}) if store and getattr(store, "H", None) else {}
        if isinstance(prof.get("toolset"), str) and prof["toolset"].strip():
            return prof["toolset"].strip(), "collection profile"
        if isinstance(prof.get("toolset"), list):
            return ",".join(str(x) for x in prof["toolset"]), "collection profile"
    except Exception:
        pass
    return "essential", "default"


def listed_tools(T=None, toolset=None):
    """Tool names tools/list shows for the toolset (in TOOLS order)."""
    T = T if T is not None else _live()["TOOLS"]
    ts = (toolset or _toolset_setting()[0]).strip().lower()
    if ts == "full":
        return list(T)
    want = set(CORE_ALWAYS)
    parts = [p.strip() for p in ts.split(",") if p.strip()]
    for p in parts or ["essential"]:
        if p == "essential":
            want |= set(ESSENTIAL) | set(ESSENTIAL_TOOLS)
        elif p in T:
            want.add(p)
        else:
            want |= {n for n in T if tool_group(n) == p}
    return [n for n in T if n in want]


_SENT_RE = re.compile(r"(?<=[.!?])\s+(?=[A-Z'(\[])|(?<=:)\s+(?=[a-z]+ ?[(=:])")


def short_desc(name, desc=None, limit=250):
    """The listing text: SHORT_DESC, else the description cut at sentence ends to <= limit chars."""
    if name in SHORT_DESC:
        return SHORT_DESC[name]
    desc = " ".join(str(desc if desc is not None else _live()["TOOLS"][name][1]).split())
    if len(desc) <= limit:
        return desc
    out = ""
    for s in _SENT_RE.split(desc):
        if len(out) + len(s) + 1 > limit - 4:
            break
        out = (out + " " + s).strip()
    if len(out) < 60:                                            # one long first sentence: cut at a word
        out = desc[:limit - 4].rsplit(" ", 1)[0].rstrip(",;:-(") + " ..."
    return out


def _short_text(t, limit):
    t = " ".join(str(t).split())
    if len(t) <= limit:
        return t
    return t[:limit - 4].rsplit(" ", 1)[0].rstrip(",;:-(") + " ..."


def short_schema(schema, limit=110, keep=None):
    """The input schema with parameter help cut to `limit` chars and empty descriptions dropped; keep: only these
    (and the required) parameters."""
    if not isinstance(schema, dict):
        return schema
    out = {k: v for k, v in schema.items() if k != "properties"}
    props = {}
    req = set(schema.get("required") or [])
    for p, spec in (schema.get("properties") or {}).items():
        if keep is not None and p not in keep and p not in req:
            continue
        if isinstance(spec, dict):
            spec = dict(spec)
            dsc = spec.pop("description", "")
            if dsc:
                spec["description"] = _short_text(dsc, limit)
        props[p] = spec
    out["properties"] = props
    if not out.get("required"):
        out.pop("required", None)
    return out


def tools_list_payload(T=None, toolset=None):
    T = T if T is not None else _live()["TOOLS"]
    ts = (toolset or _toolset_setting()[0]).strip().lower()
    out = []
    for n in listed_tools(T, ts):
        keep = ESSENTIAL_PARAMS.get(n) if ts != "full" else None
        sch = short_schema(T[n][2], 80 if ts != "full" else 90, keep)
        for p_, txt in (SHORT_PARAMS.get(n) or {}).items() if ts != "full" else ():
            if isinstance(sch["properties"].get(p_), dict):
                sch["properties"][p_]["description"] = txt
        desc = short_desc(n, T[n][1])
        hidden = len((T[n][2] or {}).get("properties") or {}) - len(sch.get("properties") or {})
        if hidden > 0:
            desc += f" (+{hidden} options: flh_tools)"
        out.append({"name": n, "description": desc, "inputSchema": sch})
    return out


def _one_liner(name, desc, limit=90):
    s = short_desc(name, desc)
    first = _SENT_RE.split(s)[0]
    return _short_text(first, limit)


def flh_tools(query=None, group=None, name=None, full=False, limit=15):
    """Discovery: the groups (names only), one group's tools with one-liners, a keyword search, or one tool's full
    help + input schema (name= a tool or a list of tools)."""
    T = _live()["TOOLS"]
    listed = set(listed_tools(T))
    ts, src = _toolset_setting()
    if name:
        names = [name] if isinstance(name, str) else list(name)
        out = {}
        for n in names[:8]:
            if n not in T:
                close = [k for k in T if n.lower() in k.lower()][:6]
                out[n] = {"error": "no such tool", **({"did_you_mean": close} if close else {})}
                continue
            e = T[n]
            out[n] = {"group": tool_group(n), "listed": n in listed, "description": e[1],
                      **({"long_help": LONG_HELP[n]} if LONG_HELP.get(n) else {}),
                      **({"long_help_more": e[3]} if len(e) > 3 and e[3] else {}),
                      "arguments": e[2],
                      "call": (f"{n}(...)" if n in listed else f"flh_call(tool='{n}', args={{...}})")}
        return out if len(names) > 1 else out[names[0]]
    groups = {}
    for n in T:
        groups.setdefault(tool_group(n), []).append(n)
    if group:
        g = str(group).strip().lower()
        if g not in groups:
            raise ValueError(f"no group '{group}'; groups: {', '.join(sorted(groups))}")
        return {"group": g, "tools": [[n, _one_liner(n, T[n][1])] + ([] if n in listed else ["(flh_call)"])
                                      for n in groups[g]],
                "next": "flh_tools(name='<tool>') for its full help and arguments"}
    if query:
        words = [w for w in re.findall(r"[a-z0-9]+", str(query).lower()) if len(w) > 1]
        if not words:
            raise ValueError("query: a few words, e.g. 'sidechain', 'render stems', 'vocal tuning'")
        scored = []
        for n, e in T.items():
            if n == "flh_tools":
                continue
            hay_n = n.lower().replace("_", " "); hay_d = str(e[1]).lower() + " " + str(LONG_HELP.get(n, "")).lower()
            sc = sum(3 * (w in hay_n) + min(3, hay_d.count(w)) for w in words)
            sc += 2 * all(w in hay_n + " " + hay_d for w in words)
            if sc:
                scored.append((-sc, n))
        scored.sort()
        return {"query": query, "tools": [[n, _one_liner(n, T[n][1])] + ([] if n in listed else ["(flh_call)"])
                                         for _, n in scored[:int(limit)]],
                "next": "flh_tools(name='<tool>') for full help; unlisted tools run with flh_call(tool, args)"}
    order = list(GROUPS) + sorted(g for g in groups if g not in GROUPS)
    return {"toolset": ts, "toolset_from": src, "listed": len(listed), "total": len(T),
            "groups": {g: ", ".join(groups[g]) for g in order if groups.get(g)},
            "next": "flh_tools(group='mix') for one-liners, query='...' to search, name='tool' for full help; "
                    "toolset=full (FLH_TOOLSET or flh_profile set={'toolset': 'full'}) lists everything",
            **({"full_note": "names only; use group= for descriptions"} if full else {})}


EXTENSIONS = ("flh_store", "flh_finalize", "flh_review", "flh_perform", "flh_catalog", "flh_setup", "flh_cleanup",
              "flh_score", "flh_compose", "flh_mixeng", "flh_vocal", "flh_transcribe", "flh_newsong", "flh_handbook",
              "flh_extras", "flh_access", "flh_pccheck", "flh_realism", "flh_sheet", "flh_shape", "flh_tidy",
              "flh_sounddesign", "flh_sampler", "flh_flex", "flh_finish", "flh_bench", "flh_refbeat", "flh_flip",
              "flh_fx", "flh_sweep", "flh_rise")


def _load_extensions(ns):
    import importlib
    here = os.path.dirname(os.path.abspath(ns.get("__file__") or sys.argv[0]))
    if here not in sys.path:
        sys.path.insert(0, here)
    loaded, errors = [], {}
    for name in EXTENSIONS:
        if not os.path.isfile(os.path.join(here, name + ".py")):
            continue
        try:
            mod = importlib.reload(sys.modules[name]) if name in sys.modules else importlib.import_module(name)
            before = set(ns["TOOLS"])
            mod.register(ns)
            added = sorted(set(ns["TOOLS"]) - before)
            loaded.append({"module": name, "tools": added})
            for t in added:
                ns["_TOOL_MODULE"][t] = name
        except Exception as e:                                   # one broken extension never takes the server down
            errors[name] = f"{type(e).__name__}: {e}"
    ns["_EXT_STATUS"] = {"loaded": loaded, "errors": errors}
    return ns["_EXT_STATUS"]


