# ============================================================================= result hygiene (dispatcher hooks)
def _plain(o, bad):
    """JSON-safe copy: numpy scalars/arrays -> Python numbers/lists, NaN/inf -> None (counted in bad[0]), tuples and
    sets -> lists, anything else unknown -> str. Never raises."""
    if o is None or isinstance(o, (bool, str, int)):
        return o
    if isinstance(o, float):
        if o != o or o in (float("inf"), float("-inf")):
            bad[0] += 1
            return None
        return o
    if isinstance(o, dict):
        return {(k if isinstance(k, str) else str(k)): _plain(v, bad) for k, v in o.items()}
    if isinstance(o, (list, tuple)):
        return [_plain(v, bad) for v in o]
    if isinstance(o, (set, frozenset)):
        return [_plain(v, bad) for v in sorted(o, key=str)]
    if hasattr(o, "tolist") and callable(o.tolist):                # numpy arrays (and scalars: .tolist() -> number)
        try:
            return _plain(o.tolist(), bad)
        except Exception:
            pass
    if hasattr(o, "item") and callable(o.item):
        try:
            return _plain(o.item(), bad)
        except Exception:
            pass
    if isinstance(o, bytes):
        return f"<{len(o)} bytes>"
    return str(o)


def _post_result(name, args, res, took=None):
    """What every tool result goes through (handle() and flh_run steps): JSON-safe numbers (NaN/inf -> null, with a
    note), the user's opt-in access notes (ns['access_adjust']) and the recent-calls log (ns['flh_recent_note']).
    Each hook is optional and can never break the call."""
    L = _live()
    try:
        bad = [0]
        clean = _plain(res, bad)
        if bad[0] and isinstance(clean, dict):
            clean["note_not_finite"] = f"{bad[0]} value(s) weren't finite numbers (NaN/inf); shown as null"
        res = clean
    except Exception:
        pass
    try:
        adj = L.get("access_adjust")
        if adj and isinstance(res, dict):
            res = adj(res, tool=name) or res
    except Exception:
        pass
    try:
        note = L.get("flh_recent_note")
        if note:
            note(name, args, result=res, took=took)
    except Exception:
        pass
    try:                                                          # local usage counts (an 'error' result counts too)
        (L.get("_usage_note") or _usage_note)(name, took, error=isinstance(res, dict) and bool(res.get("error")))
    except Exception:
        pass
    return res


def _note_error_hook(name, args, e, took=None):
    try:
        note = _live().get("flh_recent_note")
        if note:
            note(name, args, error=e)
    except Exception:
        pass
    try:
        (_live().get("_usage_note") or _usage_note)(name, took, error=True)
    except Exception:
        pass


# ----------------------------------------------------------------------------- local tool usage log
# Which tools get used, how often they fail and how long they take - so the user (and a bug report they choose to
# send) can see what matters. LOCAL ONLY: one small JSON in the state folder, never sent anywhere. Only tool names
# from the registry, counts, seconds and the last day used: no arguments, paths, project or song names.
# Cheap: a call only updates an in-memory dict (one lock, a few adds); the file is merged and written at most every
# USAGE_WRITE_S seconds (on the next call after that) and at exit. FLH_NO_USAGE=1 turns it off.
USAGE_WRITE_S = 30.0
USAGE_MAX_TOOLS = 1500                                            # bounded file: oldest-used names drop out first
_USAGE = {"pending": {}, "last_write": None, "since": None}       # pending: name -> [calls, errors, secs, last_t]
_USAGE_LOCK = threading.Lock()
_USAGE_NAME = re.compile(r"^[A-Za-z][\w.:\-]{0,63}$")


def _usage_file():
    return os.path.join(os.path.dirname(STATE), "usage.json")


def _usage_off():
    return os.environ.get("FLH_NO_USAGE", "").strip().lower() in ("1", "true", "yes", "on")


def _usage_note(name, took=None, error=False):
    """Count one call of a registered tool (the dispatcher's hook: handle(), flh_run steps, flh_call's inner tool)."""
    if _usage_off() or not isinstance(name, str) or name not in _live()["TOOLS"] or not _USAGE_NAME.match(name):
        return
    now = time.time()
    try:
        secs = max(0.0, float(took)) if took is not None else 0.0
    except (TypeError, ValueError):
        secs = 0.0
    with _USAGE_LOCK:
        p = _USAGE["pending"].get(name)
        if p is None:
            p = _USAGE["pending"][name] = [0, 0, 0.0, now]
        p[0] += 1; p[1] += 1 if error else 0; p[2] += secs; p[3] = now
        if _USAGE["last_write"] is None:
            _USAGE["last_write"] = now                            # first write USAGE_WRITE_S after the first call
        due = now - _USAGE["last_write"] >= USAGE_WRITE_S
    if due:
        _usage_flush()


def _usage_read():
    d = _json_read(_usage_file(), {})
    if not isinstance(d, dict) or not isinstance(d.get("tools"), dict):
        return {"v": 1, "since": None, "tools": {}}
    return d


def _usage_merge(d, pending):
    """d (the file's dict) plus the pending counts -> a new dict (bounded)."""
    tools = {}
    for k, v in (d.get("tools") or {}).items():
        if isinstance(k, str) and _USAGE_NAME.match(k) and isinstance(v, dict):
            try:
                tools[k] = {"calls": int(v.get("calls") or 0), "errors": int(v.get("errors") or 0),
                            "secs": round(float(v.get("secs") or 0), 2), "last": str(v.get("last") or "")[:10]}
            except (TypeError, ValueError):
                continue
    for k, (c, e, s, t) in pending.items():
        r = tools.setdefault(k, {"calls": 0, "errors": 0, "secs": 0.0, "last": ""})
        r["calls"] += c; r["errors"] += e; r["secs"] = round(r["secs"] + s, 2)
        r["last"] = max(r["last"], time.strftime("%Y-%m-%d", time.localtime(t)))
    if len(tools) > USAGE_MAX_TOOLS:
        keep = sorted(tools, key=lambda k: (tools[k]["last"], tools[k]["calls"]), reverse=True)[:USAGE_MAX_TOOLS]
        tools = {k: tools[k] for k in keep}
    since = d.get("since") if isinstance(d.get("since"), str) else None
    if not since and pending:
        since = time.strftime("%Y-%m-%d", time.localtime(min(p[3] for p in pending.values())))
    return {"v": 1, "since": (since or "")[:10] or None, "tools": tools}


def _usage_flush():
    """Merge this server's pending counts into usage.json (other fl-headless servers on this PC add theirs too)."""
    with _USAGE_LOCK:
        pending = _USAGE["pending"]
        if not pending:
            return False
        _USAGE["pending"] = {}; _USAGE["last_write"] = time.time()
    try:
        if _usage_off():
            return False
        _json_write(_usage_file(), _usage_merge(_usage_read(), pending))
        return True
    except Exception:                                             # noqa: BLE001 - never break a call; keep the counts
        with _USAGE_LOCK:
            for k, (c, e, s, t) in pending.items():
                p = _USAGE["pending"].setdefault(k, [0, 0, 0.0, t])
                p[0] += c; p[1] += e; p[2] += s; p[3] = max(p[3], t)
        return False


def _usage_totals():
    """usage.json plus what this server hasn't written yet (nothing is written)."""
    with _USAGE_LOCK:
        pending = {k: list(v) for k, v in _USAGE["pending"].items()}
    return _usage_merge(_usage_read(), pending)


def _usage_summary(top=15):
    """Counts only (tool names, calls, errors, seconds) - for flh_bug_report."""
    if _usage_off():
        return {"enabled": False}
    d = _usage_totals(); t = d["tools"]
    rows = sorted(t.items(), key=lambda kv: -kv[1]["calls"])[:max(1, int(top))]
    return {"since": d["since"], "tools_used": len(t), "calls": sum(v["calls"] for v in t.values()),
            "top": {k: v["calls"] for k, v in rows},
            "errors": {k: v["errors"] for k, v in sorted(t.items(), key=lambda kv: -kv[1]["errors"]) if v["errors"]}}


def flh_usage(top=20, unused=False):
    """Local tool usage on this PC: most-used tools, error-prone ones, never / rarely used ones (of all tools)."""
    try:
        top = max(1, min(200, int(top)))
    except (TypeError, ValueError):
        top = 20
    unused = unused is True or str(unused).strip().lower() in ("1", "true", "yes", "on")
    T = _live()["TOOLS"]
    d = _usage_totals(); t = {k: v for k, v in d["tools"].items() if k in T}
    calls = sum(v["calls"] for v in t.values())
    most = [{"tool": k, "calls": v["calls"], "errors": v["errors"], "avg_s": round(v["secs"] / v["calls"], 2) if v["calls"] else 0,
             "last": v["last"]} for k, v in sorted(t.items(), key=lambda kv: (-kv[1]["calls"], kv[0]))[:top]]
    err = sorted(((k, v) for k, v in t.items() if v["errors"]),
                 key=lambda kv: (-kv[1]["errors"] / max(1, kv[1]["calls"]), -kv[1]["errors"], kv[0]))[:top]
    never = sorted(k for k in T if k not in t)
    rare = sorted(k for k, v in t.items() if 0 < v["calls"] <= 2)
    r = {"enabled": not _usage_off(), "since": d["since"], "calls": calls, "tools_used": len(t), "tools_total": len(T),
         "most_used": most,
         "error_prone": [{"tool": k, "calls": v["calls"], "errors": v["errors"],
                          "error_rate": round(v["errors"] / max(1, v["calls"]), 2)} for k, v in err],
         "never_used": len(never), "rarely_used": len(rare)}
    if unused:
        r["never_used_tools"] = ", ".join(never); r["rarely_used_tools"] = ", ".join(rare)
    else:
        r["next"] = "unused=true lists the never / rarely (1-2 calls) used tools"
    r["privacy"] = ("local only (usage.json in fl-headless's state folder), never sent anywhere; tool names and "
                    "counts only, no arguments, paths or project names. FLH_NO_USAGE=1 turns it off")
    if not r["enabled"]:
        r["note"] = "FLH_NO_USAGE is set: nothing new is counted"
    return r


def _usage_at_exit():
    try:
        (_live().get("_usage_flush") or _usage_flush)()
    except Exception:                                             # noqa: BLE001
        pass


if not getattr(sys, "_flh_usage_atexit", False):                 # once per process (flh_reload execs this again)
    import atexit
    atexit.register(_usage_at_exit)
    sys._flh_usage_atexit = True


def _dumps(res):
    """Compact JSON for tool results (no indentation: 20-40% fewer tokens); unknown types become text."""
    return json.dumps(res, separators=(",", ":"), ensure_ascii=False, default=lambda o: _plain(o, [0]))


# ============================================================================= MCP stdio loop
def _send(msg):
    line = json.dumps(msg) + "\n"
    lock = globals().get("_SEND_LOCK")                            # a long call's thread may notify meanwhile
    if lock is None:
        sys.stdout.write(line); sys.stdout.flush(); return
    with lock:
        sys.stdout.write(line); sys.stdout.flush()


def _live():
    """The code serving calls: this file as started, or the newer copy flh_reload loaded since."""
    return getattr(sys, "_flh_live", None) or globals()


HELPER_MODULES = ("flh_common", "flac_lite", "fl_music", "fl_mix", "fl_sound", "fl_capture", "fl_audio_edit", "fl_help", "fl_blocks", "ogg_vorbis_lite", "mf_audio",
                  "flh_pccheck_mod", "fl_render_cache", "fl_musicality")   # flh_pccheck_mod: loaded by flh_pccheck via sys.modules


def _reload_code(path):
    """(code object of the server file, where it came from). Compiling ~16k lines takes ~0.25 s, so a compiled copy
    that provably matches the source is used instead: Python's own __pycache__ file when its header matches the
    file (mtime + size, or the source hash), else fl-headless's code cache in its state folder (keyed by the source
    hash + Python's bytecode magic - a second server on this PC, or a reload of unchanged code). Else it compiles
    and keeps the result in that cache. Nothing outside the state folder is written."""
    import hashlib
    import importlib.util
    import marshal
    with open(path, "rb") as f:
        raw = f.read()
    magic = importlib.util.MAGIC_NUMBER
    try:                                                          # Python's own compiled copy
        st = os.stat(path)
        with open(importlib.util.cache_from_source(path), "rb") as f:
            pyc = f.read()
        flags = int.from_bytes(pyc[4:8], "little")
        if pyc[:4] == magic and len(pyc) > 16:
            if flags == 0 and int.from_bytes(pyc[8:12], "little") == int(st.st_mtime) & 0xFFFFFFFF and \
                    int.from_bytes(pyc[12:16], "little") == st.st_size & 0xFFFFFFFF:
                return marshal.loads(pyc[16:]), "pycache"
            if flags & 1 and pyc[8:16] == importlib.util.source_hash(raw):
                return marshal.loads(pyc[16:]), "pycache"
    except Exception:                                             # noqa: BLE001 - none / stale / unreadable
        pass
    tag = magic + hashlib.sha1(raw).digest()
    cache = os.path.join(os.path.dirname(STATE), "code_cache",
                         os.path.splitext(os.path.basename(path))[0] + ".code")
    try:
        with open(cache, "rb") as f:
            blob = f.read()
        if blob[:len(tag)] == tag:
            return marshal.loads(blob[len(tag):]), "code_cache"
    except Exception:                                             # noqa: BLE001
        pass
    code = compile(raw, path, "exec", dont_inherit=True)
    try:
        os.makedirs(os.path.dirname(cache), exist_ok=True)
        tmp = f"{cache}.{os.getpid()}.tmp"
        with open(tmp, "wb") as f:
            f.write(tag + marshal.dumps(code))
        _retry_os(lambda: os.replace(tmp, cache))
    except Exception:                                             # noqa: BLE001 - only a speed-up
        pass
    return code, "compiled"


def flh_reload():
    """Load fl-headless's code from disk into the running server: new and fixed tools work at once, no Claude
    restart. The FL bridge connection and running jobs carry over."""
    path = os.path.abspath(globals().get("__file__") or sys.argv[0])
    t0 = time.time()
    code, how = _reload_code(path)                                # a syntax error keeps the old code serving
    t_compile = round(time.time() - t0, 3)
    import importlib
    helpers = []
    for h in HELPER_MODULES:                                      # helper modules too (FLAC encoder, music, mix...)
        if h in sys.modules:
            try:
                importlib.reload(sys.modules[h]); helpers.append(h)
            except Exception as e:
                helpers.append(f"{h} (kept old: {type(e).__name__}: {e})")
    old = _live()
    ns = {"__name__": "flh_live", "__file__": path, "__builtins__": __builtins__}
    exec(code, ns)
    for keep in ("BRIDGE", "JOBS", "_JOB_EVENTS", "_JOB_LOCAL", "_OVERRUN", "_OVERRUN_THREADS", "_JOB_SEQ", "_SEND_LOCK", "_AUTOSYNC", "_AUTOSYNC_LOCK",
                 "_AUTOSYNC_NEWS", "_AUTOSYNC_NEWS_PATH", "_STATE_NEWS", "_STATE_BAK_T",
                 "_TIMINGS", "_VERIFY_LOCK", "_VERIFY_LEAKS", "_VERIFY_STOP", "_PENDING_VERIFY", "_ERRORS", "_PENDING_LOCK", "_RECENT_CALLS", "_FL_LOCK", "_FL_HOLDER",
                 "_USAGE", "_USAGE_LOCK", "_STALE_FL", "_SYNC_RUN_LOCK", "_INFLIGHT",
                 "_STATE_LOCK", "_LC_LOCK", "_AUTOPLAY",
                 "_LIVE_LOG", "_FL_SYNC_T",
                 "_FL_HOLDS", "_FH_WROTE", "_OPEN_PROOF"):          # live connection, jobs, locks, stats, recent calls
                                                                  # + what FL holds (stale guard) and identity proof
        if keep in old:
            ns[keep] = old[keep]
    before = set(old.get("TOOLS", {})); after = set(ns["TOOLS"])
    sys._flh_live = ns
    try:
        _send({"jsonrpc": "2.0", "method": "notifications/tools/list_changed"})
    except Exception:
        pass
    ext = ns.get("_EXT_STATUS") or {}
    return {"version": ns["SERVER"]["version"], "was": old.get("SERVER", {}).get("version"),
            "tools_added": sorted(after - before), "tools_removed": sorted(before - after),
            "extensions": [e["module"] for e in ext.get("loaded", [])], "helpers_reloaded": helpers,
            "steps_s": {"code": t_compile, "code_from": how, "total": round(time.time() - t0, 3)},
            **({"extension_errors": ext["errors"]} if ext.get("errors") else {}),
            "note": "existing tools changed at once; new tools or arguments appear after the client refreshes its tool "
                    "list (call them via flh_call meanwhile)"}


_TYPE_WORDS = {"string": "a string", "integer": "a whole number", "number": "a number", "boolean": "true or false",
               "array": "a list [...]", "object": "an object {...}"}
_PATHLIKE_ARGS = re.compile(r"^(path|paths|project|projects|output|output_dir|output_mid|folder|file|files|input|"
                            r"preset|audio|backup|other|reference|stems|template|src|dst|save|midi|wav|target)$")
_TRUE_WORDS, _FALSE_WORDS = ("true", "yes", "on", "1"), ("false", "no", "off", "0", "none", "")


def _type_ok(v, t):
    if t == "string":
        return isinstance(v, str)
    if t == "integer":
        return isinstance(v, int) and not isinstance(v, bool)
    if t == "number":
        return isinstance(v, (int, float)) and not isinstance(v, bool)
    if t == "boolean":
        return isinstance(v, bool)
    if t == "array":
        return isinstance(v, list)
    if t == "object":
        return isinstance(v, dict)
    return True                                                   # null / unknown schema words: no opinion


def _coerce_arg(tool, k, v, spec):
    """One argument against its schema type. Lenient where models are predictably loose ("5" for 5, "true" for
    true, 3.0 for 3, a single item for a list); strict otherwise, naming the argument and what it wants."""
    t = spec.get("type") if isinstance(spec, dict) else None
    types = [x for x in (t if isinstance(t, list) else [t]) if x] if t else []
    if "boolean" in types and "string" in types and isinstance(v, str) and \
            v.strip().lower() in ("true", "false", "yes", "no"):          # ["boolean","string"]: a yes/no word is
        return v.strip().lower() in ("true", "yes")                       # the boolean, not a string option
    if "array" in types and isinstance(v, str) and v.strip()[:1] == "[":   # ["array","string"]: a JSON list sent
        try:                                                              # as text is the list (PC 2026-10-22:
            j = json.loads(v)                                             # fl_pc_check(areas='["a", "b"]') ran
            if isinstance(j, list):                                       # nothing - "['a'" matched no check)
                return j
        except ValueError:
            pass
    if not types or v is None or any(_type_ok(v, x) for x in types):
        return v
    for x in types:
        if x in ("integer", "number") and isinstance(v, (str, float)) and not isinstance(v, bool):
            try:
                f = float(str(v).strip())
            except ValueError:
                continue
            if f != f or f in (float("inf"), float("-inf")):
                continue
            if x == "integer" and f.is_integer():
                return int(f)
            if x == "number":
                return f
        if x == "boolean":
            if isinstance(v, str) and v.strip().lower() == "auto" and \
                    re.search(r"\bauto(matic(ally)?)?\b", str(spec.get("description", "")).lower()):
                return None                                       # 'default: auto' -> the tool's own auto choice
            if isinstance(v, str) and v.strip().lower() in _TRUE_WORDS + _FALSE_WORDS:
                return v.strip().lower() in _TRUE_WORDS
            if isinstance(v, (int, float)) and v in (0, 1):
                return bool(v)
        if x in ("array", "object") and isinstance(v, str) and v.strip()[:1] in "[{":
            try:
                j = json.loads(v)
                if _type_ok(j, x):
                    return j
            except ValueError:
                pass
        if x == "array" and not isinstance(v, (dict, list)):
            return [v]                                            # one item where a list is wanted
        if x == "string" and isinstance(v, (int, float)) and not isinstance(v, bool) and not _PATHLIKE_ARGS.match(k):
            return str(v)
    want = " or ".join(_TYPE_WORDS.get(x, x) for x in types)
    what = " (a file or folder path)" if "string" in types and _PATHLIKE_ARGS.match(k) else ""
    raise ValueError(f"{tool}: argument '{k}' expects {want}{what}, got {json.dumps(v, default=str)[:80]}")


def _short_usage(name, sch):
    """'flp_info(path, [full])': required arguments first, then up to 4 optional ones."""
    req = list(sch.get("required") or [])
    opt = [k for k in (sch.get("properties") or {}) if k not in req]
    return f"{name}(" + ", ".join(req + [f"[{k}]" for k in opt[:4]] + (["..."] if len(opt) > 4 else [])) + ")"


def _missing_args_text(name, need, sch):
    """'flp_info needs path (Path to the .flp). Usage: flp_info(path, [full])' - instead of a Python TypeError."""
    props = sch.get("properties") or {}

    def what(k):
        d = str((props.get(k) or {}).get("description") or "").strip()
        d = d.split(". ")[0].rstrip(".")
        return f"{k} ({d[:90]})" if d else k
    return (f"{name} needs {', '.join(what(k) for k in need)}. Usage: {_short_usage(name, sch)}; "
            f"flh_tools(name='{name}') shows every argument")


ARG_ALIASES = (                                                   # a common other name -> the tool's own argument
    ("project", "path", "flp", "project_path", "file"),
    ("input", "path", "file", "wav", "audio", "in_path"),
    ("output", "out", "output_path", "dest", "save_as"),
    ("start_bar", "from_bar", "start", "bar_from", "from"),
    ("end_bar", "to_bar", "end", "bar_to", "to", "until_bar"),
    ("wait_s", "wait", "wait_seconds"),
    ("seconds", "duration", "secs", "duration_s"),
    ("channel", "ch", "channel_index"),
    ("index", "channel", "ch"),
    ("track", "mixer_track", "insert", "mixer"),
    ("query", "q", "search", "text"),
    ("preset", "fst", "preset_path"),
    ("sample", "sample_path", "file", "path"),
    ("job", "job_id", "id"),
    ("folder", "dir", "directory"),
    ("format", "formats", "fmt"),                                 # fl_preview(format=) / fl_render(formats=)
)


# Per-tool other names for one argument (checked before ARG_ALIASES). The same mixer track is 'track' in fl_mixer_set
# and 'index' (+ slot) in the plugin tools (PC 2026-10-27: calls failed both ways) - every one takes both.
PLUGIN_TARGET_TOOLS = ("fl_plugin_params", "fl_plugin_set", "fl_plugin_set_value", "fl_plugin_probe",
                       "fl_plugin_preset")
_MIXER_WORDS = ("track", "mixer_track", "insert", "mixer")
TOOL_ARG_ALIASES = {"fl_mixer_set": {"index": "track"},
                    **{t: {"track": "index", "mixer_track": "index", "insert": "index", "mixer": "index",
                           "channel": "index", "ch": "index", "fx_slot": "slot", "effect_slot": "slot"}
                       for t in PLUGIN_TARGET_TOOLS}}


def _tool_aliases(name, args):
    """args with this tool's own names for the other names TOOL_ARG_ALIASES lists. For the plugin tools a mixer
    name (track=) needs slot >= 0 (an effect), channel= means the instrument (slot -1): a contradiction is refused,
    never guessed (index 3 slot -1 is channel 3's instrument, not mixer track 3)."""
    amap = TOOL_ARG_ALIASES.get(name)
    if not amap or not isinstance(args, dict):
        return args
    out = dict(args); used = []
    for k in list(args):
        own = amap.get(k)
        if not own or k == own:
            continue
        if own in out and out.get(own) is not None:
            raise ValueError(f"{name}: give {own} or {k}, not both (they name the same thing)")
        out[own] = out.pop(k); used.append(k)
    if name in PLUGIN_TARGET_TOOLS and used:
        try:
            sl = None if out.get("slot") is None else int(float(out["slot"]))
        except (TypeError, ValueError):
            sl = None
        if any(k in _MIXER_WORDS for k in used) and (sl is None or sl < 0):
            raise ValueError(f"{name}: {next(k for k in used if k in _MIXER_WORDS)}={out.get('index')} names a mixer "
                             "track - give slot (0..9, the effect's slot on it). A channel's instrument is "
                             "index=<channel> (or channel=) with slot -1")
        if any(k in ("channel", "ch") for k in used) and sl is not None and sl >= 0:
            raise ValueError(f"{name}: channel= means a channel's instrument (slot -1); an effect is "
                             "track=<mixer track> (or index=) with slot 0..9")
    return out


def _alias_of(k, known, given):
    """The tool's own name for argument k (an alias from ARG_ALIASES), if exactly one fits."""
    hits = []
    for grp in ARG_ALIASES:
        if k in grp:
            for c in grp:
                if c != k and c in known and c not in given and c not in hits:
                    hits.append(c)
                    break
    return hits[0] if len(hits) == 1 else None


_ARG_NOTES = threading.local()                                    # what _check_args resolved for this call
PROJECT_ARGS = ("project", "template")
OUTPUT_ARGS = ("output", "output_dir", "output_mid", "out_dir")


def _find_flp(v, scan_cap=20000):
    """An .flp the caller clearly meant when `v` isn't a file: 'Song' / 'Song.flp' / 'Song/Song.flp' relative to an
    allowed folder or the last opened project's folder, a missing '.flp', or a bare song name found in the allowed
    folders (3 levels deep). -> (path, None) when exactly one fits, (None, [candidates]) when several, (None, None)."""
    v = str(v).strip().strip('"')
    if not v:
        return None, None
    names = [v] if v.lower().endswith(".flp") else [v + ".flp", v]
    for n in names:
        if os.path.isfile(n) and n.lower().endswith(".flp"):
            return os.path.abspath(n), None
    if os.path.isabs(v):
        return None, None
    bases = list(_root_entries(os.environ.get("FLH_ROOTS", "")))
    try:
        lo = _state().get("last_opened")
        if lo:
            bases.insert(0, os.path.dirname(lo))
    except Exception:
        pass
    hits = []

    def add(p):
        p = os.path.abspath(p)
        if os.path.isfile(p) and p.lower().endswith(".flp") and all(os.path.normcase(p) != os.path.normcase(h) for h in hits):
            hits.append(p)
    stem = os.path.splitext(os.path.basename(v))[0] if v.lower().endswith(".flp") else os.path.basename(v)
    for b in bases:
        for n in names:
            add(os.path.join(b, n))
        add(os.path.join(b, v.rstrip("/\\"), stem + ".flp"))      # 'Late Rain' -> <root>/Late Rain/Late Rain.flp
    if hits:
        return (hits[0], None) if len(hits) == 1 else (None, hits[:6])
    if any(c in v for c in "/\\:"):
        return None, None
    want = stem.lower() + ".flp"                                  # a bare song name: look in the allowed folders
    for b in _root_entries(os.environ.get("FLH_ROOTS", "")):
        seen = 0
        for dirpath, dirnames, filenames in os.walk(b):
            depth = dirpath[len(b):].count(os.sep)
            dirnames[:] = [d for d in dirnames if not d.startswith((".", "_")) and d.lower() not in
                           ("backup", "backups", "stems", "_preview", "samples", "audio")] if depth < 3 else []
            for f in filenames:
                seen += 1
                if f.lower() == want:
                    add(os.path.join(dirpath, f))
            seen += len(dirnames)
            if seen > scan_cap:
                break
    if len(hits) == 1:
        return hits[0], None
    return (None, hits[:6]) if hits else (None, None)


def _resolve_project_arg(name, k, v):
    """The project argument as a real file (see _find_flp) -> value to use; notes what was resolved."""
    if not isinstance(v, str) or not v.strip() or os.path.isfile(v):
        return v
    p, many = _find_flp(v)
    if many:
        raise ValueError(f"{name}: '{v}' isn't a file and several projects match: {'; '.join(many)} - give the full path")
    if p:
        notes = getattr(_ARG_NOTES, "items", None)
        if notes is not None:
            notes.append(f"{k} '{v}' -> {p}")
        return p
    return v


_SIG_CACHE = {}                                                   # tool function -> (parameters, takes **kw)


def _sig_of(fn):
    """(parameters, takes **kwargs) of a tool function, worked out once per function (inspect is slow per call)."""
    import inspect
    try:
        hit = _SIG_CACHE.get(fn)
    except TypeError:                                             # an unhashable callable: no cache
        hit = None
    if hit is not None:
        return hit
    try:
        params = inspect.signature(inspect.unwrap(fn)).parameters
        free = any(p.kind == p.VAR_KEYWORD for p in params.values())
    except (TypeError, ValueError):
        params, free = None, True
    try:
        if len(_SIG_CACHE) > 2000:
            _SIG_CACHE.clear()
        _SIG_CACHE[fn] = (params, free)
    except TypeError:
        pass
    return params, free


def _check_args(name, args, ent):
    """Check a call's arguments against the tool's input schema before running it: wrong types name the argument
    and what it expects; numbers / booleans sent as strings are accepted; an unknown argument name is refused with
    the closest real ones. Returns the (coerced) arguments."""
    import difflib
    import inspect
    if args is None:
        return {}
    if not isinstance(args, dict):
        raise ValueError(f"{name}: arguments must be an object {{name: value}}, got {type(args).__name__}")
    sch = ent[2] if len(ent) > 2 and isinstance(ent[2], dict) else {}
    props = sch.get("properties") or {}
    params, free = _sig_of(ent[0])
    args = _tool_aliases(name, args)                              # this tool's own other names (track / index)
    out = dict(args)
    _ARG_NOTES.items = []
    known_all = set(props) | {p for p in (params or {}) if not p.startswith("_")}
    for k in list(args):                                          # 'path' for 'project', 'from_bar' for 'start_bar'...
        if k not in props and not free and not (params is not None and k in params):
            a = _alias_of(k, known_all, out)
            if a:
                out[a] = out.pop(k)
    args = dict(out)
    for k, v in args.items():
        spec = props.get(k)
        if spec is None:
            if free or (params is not None and k in params):
                continue
            known = sorted(set(props) | {p for p in (params or {}) if not p.startswith("_")})
            close = difflib.get_close_matches(k, known, n=3, cutoff=0.5)
            raise ValueError(f"{name}: unknown argument '{k}'" + (f"; did you mean {', '.join(close)}?" if close else "")
                             + f" (its arguments: {', '.join(known)[:300]})")
        out[k] = _coerce_arg(name, k, v, spec)
        if k in PROJECT_ARGS or (k == "path" and ".flp" in str(spec.get("description", ""))):
            out[k] = _resolve_project_arg(name, k, out[k])       # 'Late Rain', 'Song.flp' (relative), no '.flp'
    for k in OUTPUT_ARGS:                                         # 'Song v2.flp' -> next to the project it came from
        v = out.get(k)
        if isinstance(v, str) and v.strip() and not os.path.isabs(v) and not re.match(r"^[A-Za-z]:", v):
            src = next((out[a] for a in ("project", "template", "path", "input", "audio") if isinstance(out.get(a), str)
                        and os.path.isabs(out[a]) and os.path.exists(out[a])), None)
            base = os.path.dirname(src) if src else next(iter(_root_entries(os.environ.get("FLH_ROOTS", ""))), None)
            if base:
                out[k] = os.path.join(base, v)
                notes = getattr(_ARG_NOTES, "items", None)
                if notes is not None:
                    notes.append(f"{k} '{v}' -> {out[k]}")
    try:                                                          # a guarded writer's output defaults to its input
        opt_out = (_live().get("_OPEN_PROJECT_GUARD") or {}).get(name, (None, None))[1]
    except Exception:
        opt_out = None
    has_default = {k for k, p in (params or {}).items() if p.default is not inspect.Parameter.empty}
    need = [k for k in (sch.get("required") or []) if k != opt_out and k not in has_default and
            (out.get(k) is None or (isinstance(out.get(k), str) and not out[k].strip()))]
    if need:                                                      # (a misspelt name was answered above, first)
        raise ValueError(_missing_args_text(name, need, sch))
    return out


def _unknown_tool(name, T):
    """The answer to a call of a tool that doesn't exist: the closest real names and how to find / call tools."""
    import difflib
    names = list(T); n = str(name or "")
    close = difflib.get_close_matches(n, names, n=4, cutoff=0.6)
    close += [k for k in names if n and n.lower().strip("_") in k.lower() and k not in close][:4 - len(close)]
    return (f"unknown tool '{n}'" + (f"; did you mean {', '.join(close)}?" if close else "") +
            " flh_tools(query='...') finds tools by what they do; any tool (listed or not) runs as flh_call(tool, args)")


def handle(req):
    m = req.get("method"); L = _live(); T = L["TOOLS"]
    if m == "initialize":
        return {"protocolVersion": req.get("params", {}).get("protocolVersion", "2025-06-18"),
                "capabilities": {"tools": {"listChanged": True}}, "serverInfo": L["SERVER"],
                "instructions": L["INSTRUCTIONS"]}
    if m == "ping":
        return {}
    if m == "tools/list":
        try:
            return {"tools": L["tools_list_payload"](T)}
        except Exception:                                        # never let the tiering break the listing
            return {"tools": [{"name": k, "description": v[1], "inputSchema": v[2]} for k, v in T.items()]}
    if m == "tools/call":
        p = req.get("params", {}); name = p.get("name"); args = p.get("arguments") or {}
        if name not in T:
            return {"content": [{"type": "text", "text": (L.get("_unknown_tool") or _unknown_tool)(name, T)}],
                    "isError": True}
        try:
            if L["_windows_only"](name):
                return {"content": [{"type": "text", "text": f"{name}: {L['WINDOWS_ONLY_NOTE']}"}], "isError": True}
        except KeyError:
            pass
        def run_call(args=args):
            L["_CALL_BACKUPS"].clear()
            try:
                L["_pop_slow_notes"]()                                # this call's own 'FL is still working' notes
            except Exception:
                pass
            t_start = time.time()
            try:
                args = (L.get("_check_args") or _check_args)(name, args, T[name])
                res = T[name][0](**args)
                took = round(time.time() - t_start, 2)
                try:
                    L["_timing_note"](name, took, res)
                except TypeError:
                    L["_timing_note"](name, took)
                except Exception:
                    pass
                img0 = res.pop("_image_png", None) if isinstance(res, dict) else None
                try:
                    res = (L.get("_post_result") or _post_result)(name, args, res, took)
                except Exception:
                    pass
                if img0 and isinstance(res, dict):
                    res["_image_png"] = img0
                if name == "flh_profile" and isinstance(args.get("set"), dict) and "toolset" in args["set"]:
                    try:                                              # the listed tier changed: let the client re-list
                        _send({"jsonrpc": "2.0", "method": "notifications/tools/list_changed"})
                    except Exception:
                        pass
                img = res.pop("_image_png", None) if isinstance(res, dict) else None
                if isinstance(res, dict):
                    res.setdefault("took_s", took)
                    try:
                        slow = L["_pop_slow_notes"]()
                        if slow:
                            res.setdefault("slow_pc", slow[-2:])
                    except Exception:
                        pass
                    rn = getattr(L.get("_ARG_NOTES"), "items", None)
                    if rn:
                        res.setdefault("resolved", list(rn))
                    try:
                        alert = L["_pop_verify_alert"]()
                        if alert:
                            res["ALERT"] = alert
                    except Exception:
                        pass
                    try:
                        news = (L.get("_pop_autosync_news") or (lambda: []))()
                        if news:
                            res["in_fl_now"] = news
                    except Exception:
                        pass
                    try:
                        sn = (L.get("_pop_state_news") or (lambda: []))()
                        if sn:
                            res["state_file"] = sn[-1] if len(sn) == 1 else sn
                    except Exception:
                        pass
                try:
                    text = (L.get("_dumps") or _dumps)(res)
                except Exception:                                     # never turn a done write into an error
                    text = json.dumps(res, default=str)
                content = [{"type": "text", "text": text}]
                if img:
                    content.insert(0, {"type": "image", "data": img, "mimeType": "image/png"})
                return {"content": content}
            except Exception as e:                                   # report, never crash the server
                try:
                    (L.get("_note_error_hook") or _note_error_hook)(name, args, e, took=round(time.time() - t_start, 2))
                except Exception:
                    pass
                try:
                    rec = L.get("_note_tool_error")                    # the live copy's ring buffer (flh_bug_report)
                    if rec:
                        import traceback
                        rec(name, e, traceback.format_exc())
                except Exception:
                    pass
                hint = None
                try:
                    h = L.get("on_tool_error"); hint = h(name, e) if h else None
                except Exception:
                    pass
                return {"content": [{"type": "text", "text": f"{type(e).__name__}: {e}" + (f"\nHINT: {hint}" if hint else "")}],
                        "isError": True}

        return (L.get("_soft_deadline_call") or _soft_deadline_call)(name, args, run_call)
    raise LookupError(m)


# ----------------------------------------------------------------------------- soft deadline for long calls
# MCP clients (and remote bridges) give up on a call after ~60 s, and a call they gave up on still runs here with
# nobody to hear its result. So a tool call that isn't done after CALL_SOFT_S keeps running and is handed over as a
# job: the client gets {"job": ...} at once and fl_job returns the result. While it runs, only calls that can safely
# run beside it are served (fl_job, read-only and popup tools); anything else is refused with what's running.
CALL_SOFT_S = 45.0
NO_SOFT_DEADLINE = {"fl_job"}
BESIDE_OVERRUN = {"fl_job", "flh_tools", "fl_timings", "flh_bug_report", "flh_welcome", "flh_usage"}
_OVERRUN = {}                                                     # job id -> {"tool", "t0"} while still running
_OVERRUN_THREADS = {}                                             # thread ident -> (job id, t0) of a handed-over call
_SEND_LOCK = threading.Lock()


def _call_soft_s():
    try:
        v = float(os.environ.get("FLH_CALL_SOFT_S", CALL_SOFT_S))
    except ValueError:
        v = CALL_SOFT_S
    return v


def _overrun_running():
    for jid, o in list(_OVERRUN.items()):
        if JOBS.get(jid, {}).get("status") == "running":
            return jid, o
        _OVERRUN.pop(jid, None)
    return None, None


def _soft_deadline_call(name, args, run_call):
    soft = _call_soft_s()
    if soft <= 0 or name in NO_SOFT_DEADLINE:
        return run_call()
    jid0, o = _overrun_running()
    if jid0 and not (name in BESIDE_OVERRUN or _parallel_ok(name, args) or _lock_free(name, args or {})):
        return {"content": [{"type": "text", "text": (
            f"{o['tool']} is still running in the background (job {jid0}, {time.time() - o['t0']:.0f} s so far), so "
            f"{name} wasn't run: fl_job('{jid0}') waits for it, then call {name} again")}], "isError": True}
    box, hand = {}, threading.Lock()
    pre = _job_id(name)                                         # only used if the call is handed over

    def work():
        try:
            r = run_call()
        except BaseException as e:                                # noqa: BLE001 - run_call reports its own errors
            r = {"content": [{"type": "text", "text": f"{type(e).__name__}: {e}"}], "isError": True}
        _OVERRUN_THREADS.pop(threading.get_ident(), None)
        with hand:
            box["r"] = r
            if box.get("job"):                                   # handed over: finish the job record
                text = " ".join(c.get("text", "") for c in r.get("content") or [] if c.get("type") == "text")
                if r.get("isError"):
                    JOBS[pre].update(status="failed", error=text[:2000])
                else:
                    try:
                        JOBS[pre].update(status="done", result=json.loads(text))
                    except ValueError:
                        JOBS[pre].update(status="done", result=text)
                JOBS[pre]["seconds"] = round(time.time() - box["t0"], 1)
                if _FL_HOLDER.get("what") == f"job {pre} ({name})":
                    _FL_HOLDER["what"] = None
                _OVERRUN.pop(pre, None)
                ev = _JOB_EVENTS.get(pre)
                if ev:
                    ev.set()
    box["t0"] = time.time()
    th = threading.Thread(target=work, daemon=True, name=f"call-{name}")
    th.start(); th.join(soft)
    with hand:
        if "r" in box:
            return box["r"]
        JOBS[pre] = {"job": pre, "status": "running", "started": time.strftime("%H:%M:%S"), "tool": name}
        _JOB_EVENTS[pre] = threading.Event()
        _OVERRUN[pre] = {"tool": name, "t0": box["t0"]}
        _OVERRUN_THREADS[th.ident] = (pre, box["t0"])             # its _job_progress calls now show in fl_job
        box["job"] = True
        if _FL_HOLDER.get("what") is None and _touches_fl(name):
            _FL_HOLDER["what"] = f"job {pre} ({name})"
    out = {"job": pre, "status": "running", "tool": name,
           "note": f"{name} is taking longer than {soft:.0f} s, so it keeps running in the background: fl_job('{pre}') "
                   "returns its result the moment it's done (don't call it again meanwhile)"}
    return {"content": [{"type": "text", "text": _dumps(out)}]}


def main():
    for stream in (sys.stdin, sys.stdout):                       # JSON-RPC is UTF-8; Windows defaults to cp1252
        try:
            stream.reconfigure(encoding="utf-8")
        except (AttributeError, ValueError):
            pass
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            req = json.loads(line)
        except (json.JSONDecodeError, ValueError):
            continue
        if not isinstance(req, dict) or "id" not in req:         # not a request object / a notification
            continue
        try:
            _send({"jsonrpc": "2.0", "id": req["id"], "result": handle(req)})
        except LookupError as e:
            _send({"jsonrpc": "2.0", "id": req["id"], "error": {"code": -32601, "message": f"method not found: {e}"}})
        except Exception as e:
            _send({"jsonrpc": "2.0", "id": req["id"], "error": {"code": -32603, "message": str(e)}})



def _route_running_loop():
    """After flh_reload (this code exec'd as 'flh_live'): the stdio loop that's running is the ORIGINAL module's
    main(), which calls its own handle/_send. Point those at the live code, so a reload also brings a new
    dispatcher (argument checks, long-call handover, the send lock) - not only new tools."""
    if __name__ != "flh_live":
        return
    me = os.path.normcase(os.path.abspath(globals().get("__file__") or ""))
    for mod in list(sys.modules.values()):
        try:
            if os.path.normcase(os.path.abspath(getattr(mod, "__file__", "") or "")) != me or not hasattr(mod, "main"):
                continue
        except Exception:                                         # noqa: BLE001
            continue
        if getattr(mod, "_FLH_ROUTED", False):
            continue
        orig_handle, orig_send = mod.handle, mod._send

        def routed_handle(req, _fallback=orig_handle):
            live = getattr(sys, "_flh_live", None)
            h = live.get("handle") if isinstance(live, dict) else None
            return (h or _fallback)(req)

        def routed_send(msg, _fallback=orig_send):
            live = getattr(sys, "_flh_live", None)
            f = live.get("_send") if isinstance(live, dict) else None
            return (f or _fallback)(msg)
        mod.handle, mod._send, mod._FLH_ROUTED = routed_handle, routed_send, True


_route_running_loop()


if __name__ == "__main__":
    main()
